__d(function(n,o,t,_,c,d,e){c.exports={"5:1":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0623\u062a\u0650\u0645\u0651\u064f\u0648\u0627 \u0639\u0647\u0648\u062f \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0648\u062b\u0642\u0629\u060c \u0645\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0634\u0631\u0627\u0626\u0639 \u0627\u0644\u062f\u064a\u0646\u060c \u0648\u0627\u0644\u0627\u0646\u0642\u064a\u0627\u062f \u0644\u0647\u0627\u060c \u0648\u0623\u064e\u062f\u0651\u064f\u0648\u0627 \u0627\u0644\u0639\u0647\u0648\u062f \u0644\u0628\u0639\u0636\u0643\u0645 \u0639\u0644\u0649 \u0628\u0639\u0636 \u0645\u0646 \u0627\u0644\u0623\u0645\u0627\u0646\u0627\u062a\u060c \u0648\u0627\u0644\u0628\u064a\u0648\u0639 \u0648\u063a\u064a\u0631\u0647\u0627\u060c \u0645\u0645\u0627 \u0644\u0645 \u064a\u062e\u0627\u0644\u0641 \u0643\u062a\u0627\u0628 \u0627\u0644\u0644\u0647\u060c \u0648\u0633\u0646\u0629 \u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645. \u0648\u0642\u062f \u0623\u062d\u064e\u0644\u0651\u064e \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0627\u0644\u0628\u0647\u064a\u0645\u0629 \u0645\u0646 \u0627\u0644\u0623\u0646\u0639\u0627\u0645\u060c \u0648\u0647\u064a \u0627\u0644\u0625\u0628\u0644\u064f \u0648\u0627\u0644\u0628\u0642\u0631 \u0648\u0627\u0644\u063a\u0646\u0645\u060c \u0625\u0644\u0627 \u0645\u0627 \u0628\u064a\u0651\u064e\u0646\u0647 \u0644\u0643\u0645 \u0645\u0646 \u062a\u062d\u0631\u064a\u0645 \u0627\u0644\u0645\u064a\u062a\u0629 \u0648\u0627\u0644\u062f\u0645 \u0648\u063a\u064a\u0631 \u0630\u0644\u0643\u060c \u0648\u0645\u0646 \u062a\u062d\u0631\u064a\u0645 \u0627\u0644\u0635\u064a\u062f \u0648\u0623\u0646\u062a\u0645 \u0645\u062d\u0631\u0645\u0648\u0646. \u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u062d\u0643\u0645 \u0645\u0627 \u064a\u0634\u0627\u0621 \u0648\u064e\u0641\u0652\u0642 \u062d\u0643\u0645\u062a\u0647 \u0648\u0639\u062f\u0644\u0647.","5:2":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647 \u0644\u0627 \u062a\u062a\u0639\u062f\u0651\u064e\u0648\u0627 \u062d\u062f\u0648\u062f \u0627\u0644\u0644\u0647 \u0648\u0645\u0639\u0627\u0644\u0645\u0647\u060c \u0648\u0644\u0627 \u062a\u0633\u062a\u062d\u0650\u0644\u0651\u064f\u0648\u0627 \u0627\u0644\u0642\u062a\u0627\u0644 \u0641\u064a \u0627\u0644\u0623\u0634\u0647\u0631 \u0627\u0644\u062d\u0631\u0645\u060c \u0648\u0647\u064a: \u0630\u0648 \u0627\u0644\u0642\u0639\u062f\u0629 \u0648\u0630\u0648 \u0627\u0644\u062d\u062c\u0629 \u0648\u0627\u0644\u0645\u062d\u0631\u0645 \u0648\u0631\u062c\u0628\u060c \u0648\u0643\u0627\u0646 \u0630\u0644\u0643 \u0641\u064a \u0635\u062f\u0631 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u0644\u0627 \u062a\u0633\u062a\u062d\u0650\u0644\u0651\u064f\u0648\u0627 \u062d\u0631\u0645\u0629 \u0627\u0644\u0647\u064e\u062f\u0652\u064a\u060c \u0648\u0644\u0627 \u0645\u0627 \u0642\u064f\u0644\u0651\u0650\u062f\u064e \u0645\u0646\u0647; \u0625\u0630 \u0643\u0627\u0646\u0648\u0627 \u064a\u0636\u0639\u0648\u0646 \u0627\u0644\u0642\u0644\u0627\u0626\u062f\u060c \u0648\u0647\u064a \u0636\u0641\u0627\u0626\u0631 \u0645\u0646 \u0635\u0648\u0641 \u0623\u0648 \u0648\u064e\u0628\u064e\u0631 \u0641\u064a \u0627\u0644\u0631\u0642\u0627\u0628 \u0639\u0644\u0627\u0645\u0629\u064b \u0639\u0644\u0649 \u0623\u0646 \u0627\u0644\u0628\u0647\u064a\u0645\u0629 \u0647\u064e\u062f\u0652\u064a\u064c \u0648\u0623\u0646 \u0627\u0644\u0631\u062c\u0644 \u064a\u0631\u064a\u062f \u0627\u0644\u062d\u062c\u060c \u0648\u0644\u0627 \u062a\u064e\u0633\u0652\u062a\u064e\u062d\u0650\u0644\u0651\u064f\u0648\u0627 \u0642\u062a\u0627\u0644 \u0642\u0627\u0635\u062f\u064a \u0627\u0644\u0628\u064a\u062a \u0627\u0644\u062d\u0631\u0627\u0645 \u0627\u0644\u0630\u064a\u0646 \u064a\u0628\u062a\u063a\u0648\u0646 \u0645\u0646 \u0641\u0636\u0644 \u0627\u0644\u0644\u0647 \u0645\u0627 \u064a\u0635\u0644\u062d \u0645\u0639\u0627\u064a\u0634\u0647\u0645 \u0648\u064a\u0631\u0636\u064a \u0631\u0628\u0647\u0645. \u0648\u0625\u0630\u0627 \u062d\u0644\u0644\u062a\u0645 \u0645\u0646 \u0625\u062d\u0631\u0627\u0645\u0643\u0645 \u062d\u0644\u0651\u064e \u0644\u0643\u0645 \u0627\u0644\u0635\u064a\u062f\u060c \u0648\u0644\u0627 \u064a\u062d\u0645\u0650\u0644\u064e\u0646\u0651\u064e\u0643\u0645 \u0628\u064f\u063a\u0652\u0636 \u0642\u0648\u0645 \u0645\u0646 \u0623\u062c\u0644 \u0623\u0646 \u0645\u0646\u0639\u0648\u0643\u0645 \u0645\u0646 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u062d\u0631\u0627\u0645 -\u0643\u0645\u0627 \u062d\u062f\u062b \u0639\u0627\u0645 \xab\u0627\u0644\u062d\u062f\u064a\u0628\u064a\u0629\xbb - \u0639\u0644\u0649 \u062a\u0631\u0643 \u0627\u0644\u0639\u062f\u0644 \u0641\u064a\u0647\u0645. \u0648\u062a\u0639\u0627\u0648\u0646\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0641\u064a\u0645\u0627 \u0628\u064a\u0646\u0643\u0645- \u0639\u0644\u0649 \u0641\u0650\u0639\u0652\u0644 \u0627\u0644\u062e\u064a\u0631\u060c \u0648\u062a\u0642\u0648\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u062a\u0639\u0627\u0648\u0646\u0648\u0627 \u0639\u0644\u0649 \u0645\u0627 \u0641\u064a\u0647 \u0625\u062b\u0645 \u0648\u0645\u0639\u0635\u064a\u0629 \u0648\u062a\u062c\u0627\u0648\u0632 \u0644\u062d\u062f\u0648\u062f \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u062d\u0630\u0631\u0648\u0627 \u0645\u062e\u0627\u0644\u0641\u0629 \u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u0641\u0625\u0646\u0647 \u0634\u062f\u064a\u062f \u0627\u0644\u0639\u0642\u0627\u0628.","5:3":"\u062d\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0627\u0644\u0645\u064a\u062a\u0629\u060c \u0648\u0647\u064a \u0627\u0644\u062d\u064a\u0648\u0627\u0646 \u0627\u0644\u0630\u064a \u062a\u0641\u0627\u0631\u0642\u0647 \u0627\u0644\u062d\u064a\u0627\u0629 \u0628\u062f\u0648\u0646 \u0630\u0643\u0627\u0629\u060c \u0648\u062d\u0631\u0651\u064e\u0645 \u0639\u0644\u064a\u0643\u0645 \u0627\u0644\u062f\u0645 \u0627\u0644\u0633\u0627\u0626\u0644 \u0627\u0644\u0645\u064f\u0631\u0627\u0642\u060c \u0648\u0644\u062d\u0645 \u0627\u0644\u062e\u0646\u0632\u064a\u0631\u060c \u0648\u0645\u0627 \u0630\u064f\u0643\u0650\u0631 \u0639\u0644\u064a\u0647 \u063a\u064a\u0631 \u0627\u0633\u0645 \u0627\u0644\u0644\u0647 \u0639\u0646\u062f \u0627\u0644\u0630\u0628\u062d\u060c \u0648\u0627\u0644\u0645\u0646\u062e\u0646\u0642\u0629 \u0627\u0644\u062a\u064a \u062d\u064f\u0628\u0650\u0633 \u0646\u064e\u0641\u064e\u0633\u064f\u0647\u0627 \u062d\u062a\u0649 \u0645\u0627\u062a\u062a\u060c \u0648\u0627\u0644\u0645\u0648\u0642\u0648\u0630\u0629 \u0648\u0647\u064a \u0627\u0644\u062a\u064a \u0636\u064f\u0631\u0628\u062a \u0628\u0639\u0635\u0627 \u0623\u0648 \u062d\u062c\u0631 \u062d\u062a\u0649 \u0645\u0627\u062a\u062a\u060c \u0648\u0627\u0644\u0645\u064f\u062a\u064e\u0631\u064e\u062f\u0651\u0650\u064a\u0629 \u0648\u0647\u064a \u0627\u0644\u062a\u064a \u0633\u0642\u0637\u062a \u0645\u0646 \u0645\u0643\u0627\u0646 \u0639\u0627\u0644 \u0623\u0648 \u0647\u064e\u0648\u064e\u062a \u0641\u064a \u0628\u0626\u0631 \u0641\u0645\u0627\u062a\u062a\u060c \u0648\u0627\u0644\u0646\u0637\u064a\u062d\u0629 \u0648\u0647\u064a \u0627\u0644\u062a\u064a \u0636\u064e\u0631\u064e\u0628\u064e\u062a\u0652\u0647\u0627 \u0623\u062e\u0631\u0649 \u0628\u0642\u0631\u0646\u0647\u0627 \u0641\u0645\u0627\u062a\u062a\u060c \u0648\u062d\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0627\u0644\u0628\u0647\u064a\u0645\u0629 \u0627\u0644\u062a\u064a \u0623\u0643\u0644\u0647\u0627 \u0627\u0644\u0633\u0628\u064f\u0639\u060c \u0643\u0627\u0644\u0623\u0633\u062f \u0648\u0627\u0644\u0646\u0645\u0631 \u0648\u0627\u0644\u0630\u0626\u0628\u060c \u0648\u0646\u062d\u0648 \u0630\u0644\u0643. \u0648\u0627\u0633\u062a\u062b\u0646\u0649 -\u0633\u0628\u062d\u0627\u0646\u0647- \u0645\u0645\u0627 \u062d\u0631\u0651\u064e\u0645\u0647 \u0645\u0646 \u0627\u0644\u0645\u0646\u062e\u0646\u0642\u0629 \u0648\u0645\u0627 \u0628\u0639\u062f\u0647\u0627 \u0645\u0627 \u0623\u062f\u0631\u0643\u062a\u0645 \u0630\u0643\u0627\u062a\u0647 \u0642\u0628\u0644 \u0623\u0646 \u064a\u0645\u0648\u062a \u0641\u0647\u0648 \u062d\u0644\u0627\u0644 \u0644\u0643\u0645\u060c \u0648\u062d\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0645\u0627 \u0630\u064f\u0628\u0650\u062d \u0644\u063a\u064a\u0631 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0645\u0627 \u064a\u064f\u0646\u0635\u0628 \u0644\u0644\u0639\u0628\u0627\u062f\u0629 \u0645\u0646 \u062d\u062c\u0631 \u0623\u0648 \u063a\u064a\u0631\u0647\u060c \u0648\u062d\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0623\u0646 \u062a\u0637\u0644\u0628\u0648\u0627 \u0639\u0650\u0644\u0652\u0645 \u0645\u0627 \u0642\u064f\u0633\u0650\u0645 \u0644\u0643\u0645 \u0623\u0648 \u0644\u0645 \u064a\u0642\u0633\u0645 \u0628\u0627\u0644\u0623\u0632\u0644\u0627\u0645\u060c \u0648\u0647\u064a \u0627\u0644\u0642\u062f\u0627\u062d \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u0648\u0627 \u064a\u0633\u062a\u0642\u0633\u0645\u0648\u0646 \u0628\u0647\u0627 \u0625\u0630\u0627 \u0623\u0631\u0627\u062f\u0648\u0627 \u0623\u0645\u0631\u064b\u0627 \u0642\u0628\u0644 \u0623\u0646 \u064a\u0642\u062f\u0645\u0648\u0627 \u0639\u0644\u064a\u0647. \u0630\u0644\u0643\u0645 \u0627\u0644\u0645\u0630\u0643\u0648\u0631 \u0641\u064a \u0627\u0644\u0622\u064a\u0629 \u0645\u0646 \u0627\u0644\u0645\u062d\u0631\u0645\u0627\u062a -\u0625\u0630\u0627 \u0627\u0631\u062a\u064f\u0643\u0628\u062a- \u062e\u0631\u0648\u062c \u0639\u0646 \u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u0648\u0637\u0627\u0639\u062a\u0647 \u0625\u0644\u0649 \u0645\u0639\u0635\u064a\u062a\u0647. \u0627\u0644\u0622\u0646 \u0627\u0646\u0642\u0637\u0639 \u0637\u0645\u0639 \u0627\u0644\u0643\u0641\u0627\u0631 \u0645\u0646 \u062f\u064a\u0646\u0643\u0645 \u0623\u0646 \u062a\u0631\u062a\u062f\u0648\u0627 \u0639\u0646\u0647 \u0625\u0644\u0649 \u0627\u0644\u0634\u0631\u0643 \u0628\u0639\u062f \u0623\u0646 \u0646\u0635\u064e\u0631\u0652\u062a\u064f\u0643\u0645 \u0639\u0644\u064a\u0647\u0645\u060c \u0641\u0644\u0627 \u062a\u062e\u0627\u0641\u0648\u0647\u0645 \u0648\u062e\u0627\u0641\u0648\u0646\u064a. \u0627\u0644\u064a\u0648\u0645 \u0623\u0643\u0645\u0644\u062a \u0644\u0643\u0645 \u062f\u064a\u0646\u0643\u0645 \u062f\u064a\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0628\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u0646\u0635\u0631 \u0648\u0625\u062a\u0645\u0627\u0645 \u0627\u0644\u0634\u0631\u064a\u0639\u0629\u060c \u0648\u0623\u062a\u0645\u0645\u062a \u0639\u0644\u064a\u0643\u0645 \u0646\u0639\u0645\u062a\u064a \u0628\u0625\u062e\u0631\u0627\u062c\u0643\u0645 \u0645\u0646 \u0638\u0644\u0645\u0627\u062a \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629 \u0625\u0644\u0649 \u0646\u0648\u0631 \u0627\u0644\u0625\u064a\u0645\u0627\u0646\u060c \u0648\u0631\u0636\u064a\u062a \u0644\u0643\u0645 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u062f\u064a\u0646\u064b\u0627 \u0641\u0627\u0644\u0632\u0645\u0648\u0647\u060c \u0648\u0644\u0627 \u062a\u0641\u0627\u0631\u0642\u0648\u0647. \u0641\u0645\u0646 \u0627\u0636\u0637\u0631\u0651\u064e \u0641\u064a \u0645\u062c\u0627\u0639\u0629 \u0625\u0644\u0649 \u0623\u0643\u0644 \u0627\u0644\u0645\u064a\u062a\u0629\u060c \u0648\u0643\u0627\u0646 \u063a\u064a\u0631 \u0645\u0627\u0626\u0644 \u0639\u0645\u062f\u064b\u0627 \u0644\u0625\u062b\u0645\u060c \u0641\u0644\u0647 \u062a\u0646\u0627\u0648\u0644\u0647\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0644\u0647\u060c \u0631\u062d\u064a\u0645 \u0628\u0647.","5:4":"\u064a\u0633\u0623\u0644\u0643 \u0623\u0635\u062d\u0627\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a-: \u0645\u0627\u0630\u0627 \u0623\u064f\u062d\u0650\u0644\u0651\u064e \u0644\u0647\u0645 \u0623\u064e\u0643\u0652\u0644\u064f\u0647\u061f \u0642\u0644 \u0644\u0647\u0645: \u0623\u064f\u062d\u0650\u0644\u0651\u064e \u0644\u0643\u0645 \u0627\u0644\u0637\u064a\u0628\u0627\u062a \u0648\u0635\u064a\u062f\u064f \u0645\u0627 \u062f\u064e\u0631\u0651\u064e\u0628\u062a\u0645\u0648\u0647 \u0645\u0646 \u0630\u0648\u0627\u062a \u0627\u0644\u0645\u062e\u0627\u0644\u0628 \u0648\u0627\u0644\u0623\u0646\u064a\u0627\u0628 \u0645\u0646 \u0627\u0644\u0643\u0644\u0627\u0628 \u0648\u0627\u0644\u0641\u0647\u0648\u062f \u0648\u0627\u0644\u0635\u0642\u0648\u0631 \u0648\u0646\u062d\u0648\u0647\u0627 \u0645\u0645\u0627 \u064a\u064f\u0639\u064e\u0644\u0651\u064e\u0645\u060c \u062a\u0639\u0644\u0645\u0648\u0646\u0647\u0646 \u0637\u0644\u0628 \u0627\u0644\u0635\u064a\u062f \u0644\u0643\u0645\u060c \u0645\u0645\u0627 \u0639\u0644\u0645\u0643\u0645 \u0627\u0644\u0644\u0647\u060c \u0641\u0643\u0644\u0648\u0627 \u0645\u0645\u0627 \u0623\u0645\u0633\u0643\u0646 \u0644\u0643\u0645\u060c \u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0627\u0633\u0645 \u0627\u0644\u0644\u0647 \u0639\u0646\u062f \u0625\u0631\u0633\u0627\u0644\u0647\u0627 \u0644\u0644\u0635\u064a\u062f\u060c \u0648\u062e\u0627\u0641\u0648\u0627 \u0627\u0644\u0644\u0647 \u0641\u064a\u0645\u0627 \u0623\u0645\u0631\u0643\u0645 \u0628\u0647 \u0648\u0641\u064a\u0645\u0627 \u0646\u0647\u0627\u0643\u0645 \u0639\u0646\u0647. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0633\u0631\u064a\u0639 \u0627\u0644\u062d\u0633\u0627\u0628.","5:5":"\u0648\u0645\u0646 \u062a\u0645\u0627\u0645 \u0646\u0639\u0645\u0629 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0627\u0644\u064a\u0648\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0623\u0646 \u0623\u064e\u062d\u064e\u0644\u0651\u064e \u0644\u0643\u0645 \u0627\u0644\u062d\u0644\u0627\u0644 \u0627\u0644\u0637\u064a\u0628\u060c \u0648\u0630\u0628\u0627\u0626\u062d\u064f \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649 -\u0625\u0646 \u0630\u0643\u0651\u064e\u0648\u0647\u0627 \u062d\u064e\u0633\u064e\u0628\u064e \u0634\u0631\u0639\u0647\u0645- \u062d\u0644\u0627\u0644 \u0644\u0643\u0645 \u0648\u0630\u0628\u0627\u0626\u062d\u0643\u0645 \u062d\u0644\u0627\u0644 \u0644\u0647\u0645. \u0648\u0623\u064e\u062d\u064e\u0644\u0651\u064e \u0644\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0646\u0643\u0627\u062d \u0627\u0644\u0645\u062d\u0635\u0646\u0627\u062a\u060c \u0648\u0647\u064f\u0646\u0651\u064e \u0627\u0644\u062d\u0631\u0627\u0626\u0631 \u0645\u0646 \u0627\u0644\u0646\u0633\u0627\u0621 \u0627\u0644\u0645\u0624\u0645\u0646\u0627\u062a\u060c \u0627\u0644\u0639\u0641\u064a\u0641\u0627\u062a \u0639\u0646 \u0627\u0644\u0632\u0646\u0649\u060c \u0648\u0643\u0630\u0644\u0643 \u0646\u0643\u0627\u062d\u064e \u0627\u0644\u062d\u0631\u0627\u0626\u0631 \u0627\u0644\u0639\u0641\u064a\u0641\u0627\u062a \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0625\u0630\u0627 \u0623\u0639\u0637\u064a\u062a\u0645\u0648\u0647\u064f\u0646\u0651\u064e \u0645\u0647\u0648\u0631\u0647\u0646\u060c \u0648\u0643\u0646\u062a\u0645 \u0623\u0639\u0650\u0641\u0651\u064e\u0627\u0621 \u063a\u064a\u0631 \u0645\u0631\u062a\u0643\u0628\u064a\u0646 \u0644\u0644\u0632\u0646\u0649\u060c \u0648\u0644\u0627 \u0645\u062a\u062e\u0630\u064a \u0639\u0634\u064a\u0642\u0627\u062a\u060c \u0648\u0623\u0645\u0650\u0646\u062a\u0645 \u0645\u0646 \u0627\u0644\u062a\u0623\u062b\u0631 \u0628\u062f\u064a\u0646\u0647\u0646. \u0648\u0645\u0646 \u064a\u062c\u062d\u062f \u0634\u0631\u0627\u0626\u0639 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0641\u0642\u062f \u0628\u0637\u0644 \u0639\u0645\u0644\u0647\u060c \u0648\u0647\u0648 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0645\u0646 \u0627\u0644\u062e\u0627\u0633\u0631\u064a\u0646.","5:6":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0625\u0630\u0627 \u0623\u0631\u062f\u062a\u0645 \u0627\u0644\u0642\u064a\u0627\u0645 \u0625\u0644\u0649 \u0627\u0644\u0635\u0644\u0627\u0629\u060c \u0648\u0623\u0646\u062a\u0645 \u0639\u0644\u0649 \u063a\u064a\u0631 \u0637\u0647\u0627\u0631\u0629 \u0641\u0627\u063a\u0633\u0644\u0648\u0627 \u0648\u062c\u0648\u0647\u0643\u0645 \u0648\u0623\u064a\u062f\u064a\u0643\u0645 \u0645\u0639 \u0627\u0644\u0645\u0631\u0627\u0641\u0642 (\u0648\u0627\u0644\u0645\u0650\u0631\u0652\u0641\u064e\u0642: \u0627\u0644\u0645\u0650\u0641\u0652\u0635\u064e\u0644 \u0627\u0644\u0630\u064a \u0628\u064a\u0646 \u0627\u0644\u0630\u0631\u0627\u0639 \u0648\u0627\u0644\u0639\u064e\u0636\u064f\u062f) \u0648\u0627\u0645\u0633\u062d\u0648\u0627 \u0631\u0624\u0648\u0633\u0643\u0645\u060c \u0648\u0627\u063a\u0633\u0644\u0648\u0627 \u0623\u0631\u062c\u0644\u0643\u0645 \u0645\u0639 \u0627\u0644\u0643\u0639\u0628\u064a\u0646 (\u0648\u0647\u0645\u0627: \u0627\u0644\u0639\u0638\u0645\u0627\u0646 \u0627\u0644\u0628\u0627\u0631\u0632\u0627\u0646 \u0639\u0646\u062f \u0645\u0644\u062a\u0642\u0649 \u0627\u0644\u0633\u0627\u0642 \u0628\u0627\u0644\u0642\u062f\u0645) . \u0648\u0625\u0646 \u0623\u0635\u0627\u0628\u0643\u0645 \u0627\u0644\u062d\u062f\u062b \u0627\u0644\u0623\u0643\u0628\u0631 \u0641\u062a\u0637\u0647\u0631\u0648\u0627 \u0628\u0627\u0644\u0627\u063a\u062a\u0633\u0627\u0644 \u0645\u0646\u0647 \u0642\u0628\u0644 \u0627\u0644\u0635\u0644\u0627\u0629. \u0641\u0625\u0646 \u0643\u0646\u062a\u0645 \u0645\u0631\u0636\u0649\u060c \u0623\u0648 \u0639\u0644\u0649 \u0633\u0641\u0631 \u0641\u064a \u062d\u0627\u0644 \u0627\u0644\u0635\u062d\u0629\u060c \u0623\u0648 \u0642\u0636\u0649 \u0623\u062d\u062f\u0643\u0645 \u062d\u0627\u062c\u062a\u0647\u060c \u0623\u0648 \u062c\u0627\u0645\u0639 \u0632\u0648\u062c\u062a\u0647 \u0641\u0644\u0645 \u062a\u062c\u062f\u0648\u0627 \u0645\u0627\u0621 \u0641\u0627\u0636\u0631\u0628\u0648\u0627 \u0628\u0623\u064a\u062f\u064a\u0643\u0645 \u0648\u062c\u0647 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0627\u0645\u0633\u062d\u0648\u0627 \u0648\u062c\u0648\u0647\u0643\u0645 \u0648\u0623\u064a\u062f\u064a\u0643\u0645 \u0645\u0646\u0647. \u0645\u0627 \u064a\u0631\u064a\u062f \u0627\u0644\u0644\u0647 \u0641\u064a \u0623\u0645\u0631 \u0627\u0644\u0637\u0647\u0627\u0631\u0629 \u0623\u0646 \u064a\u064f\u0636\u064e\u064a\u0651\u0650\u0642 \u0639\u0644\u064a\u0643\u0645\u060c \u0628\u0644 \u0623\u0628\u0627\u062d \u0627\u0644\u062a\u064a\u0645\u0645 \u062a\u0648\u0633\u0639\u0629\u064b \u0639\u0644\u064a\u0643\u0645\u060c \u0648\u0631\u062d\u0645\u0629 \u0628\u0643\u0645\u060c \u0625\u0630 \u062c\u0639\u0644\u0647 \u0628\u062f\u064a\u0644\u0627 \u0644\u0644\u0645\u0627\u0621 \u0641\u064a \u0627\u0644\u0637\u0647\u0627\u0631\u0629\u060c \u0641\u0643\u0627\u0646\u062a \u0631\u062e\u0635\u0629 \u0627\u0644\u062a\u064a\u0645\u0651\u064f\u0645 \u0645\u0646 \u062a\u0645\u0627\u0645 \u0627\u0644\u0646\u0639\u0645 \u0627\u0644\u062a\u064a \u062a\u0642\u062a\u0636\u064a \u0634\u0643\u0631 \u0627\u0644\u0645\u0646\u0639\u0645; \u0628\u0637\u0627\u0639\u062a\u0647 \u0641\u064a\u0645\u0627 \u0623\u0645\u0631 \u0648\u0641\u064a\u0645\u0627 \u0646\u0647\u0649.","5:7":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0639\u0645\u0629 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0641\u064a\u0645\u0627 \u0634\u064e\u0631\u064e\u0639\u0647 \u0644\u0643\u0645\u060c \u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0639\u0647\u062f\u0647 \u0627\u0644\u0630\u064a \u0623\u062e\u0630\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u064a\u0643\u0645 \u0645\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0627\u0644\u0633\u0645\u0639 \u0648\u0627\u0644\u0637\u0627\u0639\u0629 \u0644\u0647\u0645\u0627\u060c \u0648\u0627\u062a\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0641\u064a\u0645\u0627 \u0623\u0645\u0631\u0643\u0645 \u0628\u0647 \u0648\u0646\u0647\u0627\u0643\u0645 \u0639\u0646\u0647. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645\u064c \u0628\u0645\u0627 \u062a\u064f\u0633\u0650\u0631\u0651\u064f\u0648\u0646\u0647 \u0641\u064a \u0646\u0641\u0648\u0633\u0643\u0645.","5:8":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u064e\u0646\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0643\u0648\u0646\u0648\u0627 \u0642\u0648\u0651\u064e\u0627\u0645\u064a\u0646 \u0628\u0627\u0644\u062d\u0642\u060c \u0627\u0628\u062a\u063a\u0627\u0621 \u0648\u062c\u0647 \u0627\u0644\u0644\u0647\u060c \u0634\u064f\u0647\u062f\u0627\u0621 \u0628\u0627\u0644\u0639\u062f\u0644\u060c \u0648\u0644\u0627 \u064a\u062d\u0645\u0644\u0646\u0643\u0645 \u0628\u064f\u063a\u0652\u0636\u064f \u0642\u0648\u0645 \u0639\u0644\u0649 \u0623\u0644\u0627 \u062a\u0639\u062f\u0644\u0648\u0627\u060c \u0627\u0639\u062f\u0650\u0644\u0648\u0627 \u0628\u064a\u0646 \u0627\u0644\u0623\u0639\u062f\u0627\u0621 \u0648\u0627\u0644\u0623\u062d\u0628\u0627\u0628 \u0639\u0644\u0649 \u062f\u0631\u062c\u0629 \u0633\u0648\u0627\u0621\u060c \u0641\u0630\u0644\u0643 \u0627\u0644\u0639\u062f\u0644 \u0623\u0642\u0631\u0628 \u0644\u062e\u0634\u064a\u0629 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u062d\u0630\u0631\u0648\u0627 \u0623\u0646 \u062a\u062c\u0648\u0631\u0648\u0627. \u0625\u0646 \u0627\u0644\u0644\u0647 \u062e\u0628\u064a\u0631 \u0628\u0645\u0627 \u062a\u0639\u0645\u0644\u0648\u0646\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0643\u0645 \u0628\u0647.","5:9":"\u0648\u0639\u062f \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0627\u0644\u0635\u0627\u0644\u062d\u0627\u062a \u0623\u0646 \u064a\u063a\u0641\u0631 \u0644\u0647\u0645 \u0630\u0646\u0648\u0628\u0647\u0645\u060c \u0648\u0623\u0646 \u064a\u062b\u064a\u0628\u0647\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643 \u0627\u0644\u062c\u0646\u0629\u060c \u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u062e\u0644\u0641 \u0648\u0639\u062f\u0647.","5:10":"\u0648\u0627\u0644\u0630\u064a\u0646 \u062c\u062d\u062f\u0648\u0627 \u0648\u062d\u062f\u0627\u0646\u064a\u0629 \u0627\u0644\u0644\u0647 \u0627\u0644\u062f\u0627\u0644\u0629 \u0639\u0644\u0649 \u0627\u0644\u062d\u0642 \u0627\u0644\u0645\u0628\u064a\u0646\u060c \u0648\u0643\u0630\u0651\u064e\u0628\u0648\u0627 \u0628\u0623\u062f\u0644\u062a\u0647 \u0627\u0644\u062a\u064a \u062c\u0627\u0621\u062a \u0628\u0647\u0627 \u0627\u0644\u0631\u0633\u0644\u060c \u0647\u0645 \u0623\u0647\u0644 \u0627\u0644\u0646\u0627\u0631 \u0627\u0644\u0645\u0644\u0627\u0632\u0645\u0648\u0646 \u0644\u0647\u0627.","5:11":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647 \u0627\u0630\u0643\u0631\u0648\u0627 \u0645\u0627 \u0623\u0646\u0639\u0645 \u0627\u0644\u0644\u0647 \u0628\u0647 \u0639\u0644\u064a\u0643\u0645 \u0645\u0646 \u0646\u0639\u0645\u0629 \u0627\u0644\u0623\u0645\u0646\u0650\u060c \u0648\u0625\u0644\u0642\u0627\u0621\u0650 \u0627\u0644\u0631\u0639\u0628 \u0641\u064a \u0642\u0644\u0648\u0628 \u0623\u0639\u062f\u0627\u0626\u0643\u0645 \u0627\u0644\u0630\u064a\u0646 \u0623\u0631\u0627\u062f\u0648\u0627 \u0623\u0646 \u064a\u0628\u0637\u0634\u0648\u0627 \u0628\u0643\u0645\u060c \u0641\u0635\u0631\u0641\u0647\u0645 \u0627\u0644\u0644\u0647 \u0639\u0646\u0643\u0645\u060c \u0648\u062d\u0627\u0644 \u0628\u064a\u0646\u0647\u0645 \u0648\u0628\u064a\u0646 \u0645\u0627 \u0623\u0631\u0627\u062f\u0648\u0647 \u0628\u0643\u0645\u060c \u0648\u0627\u062a\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0627\u062d\u0630\u0631\u0648\u0647\u060c \u0648\u062a\u0648\u0643\u0644\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0641\u064a \u0623\u0645\u0648\u0631\u0643\u0645 \u0627\u0644\u062f\u064a\u0646\u064a\u0629 \u0648\u0627\u0644\u062f\u0646\u064a\u0648\u064a\u0629\u060c \u0648\u062b\u0650\u0642\u0648\u0627 \u0628\u0639\u0648\u0646\u0647 \u0648\u0646\u0635\u0631\u0647.","5:12":"\u0648\u0644\u0642\u062f \u0623\u062e\u0630 \u0627\u0644\u0644\u0647 \u0627\u0644\u0639\u0647\u062f \u0627\u0644\u0645\u0624\u0643\u0651\u064e\u062f \u0639\u0644\u0649 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0623\u0646 \u064a\u062e\u0644\u0635\u0648\u0627 \u0644\u0647 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0648\u062d\u062f\u0647\u060c \u0648\u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u0645\u0648\u0633\u0649 \u0623\u0646 \u064a\u062c\u0639\u0644 \u0639\u0644\u064a\u0647\u0645 \u0627\u062b\u0646\u064a \u0639\u0634\u0631 \u0639\u0631\u064a\u0641\u064b\u0627 \u0628\u0639\u062f\u062f \u0641\u0631\u0648\u0639\u0647\u0645\u060c \u064a\u0623\u062e\u0630\u0648\u0646 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0639\u0647\u062f \u0628\u0627\u0644\u0633\u0645\u0639 \u0648\u0627\u0644\u0637\u0627\u0639\u0629 \u0644\u0644\u0647 \u0648\u0644\u0631\u0633\u0648\u0644\u0647 \u0648\u0644\u0643\u062a\u0627\u0628\u0647\u060c \u0648\u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u0644\u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644: \u0625\u0646\u064a \u0645\u0639\u0643\u0645 \u0628\u062d\u0641\u0638\u064a \u0648\u0646\u0635\u0631\u064a\u060c \u0644\u0626\u0646 \u0623\u0642\u0645\u062a\u0645 \u0627\u0644\u0635\u0644\u0627\u0629\u060c \u0648\u0623\u0639\u0637\u064a\u062a\u0645 \u0627\u0644\u0632\u0643\u0627\u0629 \u0627\u0644\u0645\u0641\u0631\u0648\u0636\u0629 \u0645\u0633\u062a\u062d\u0642\u064a\u0647\u0627\u060c \u0648\u0635\u062f\u0651\u064e\u0642\u062a\u0645 \u0628\u0631\u0633\u0644\u064a \u0641\u064a\u0645\u0627 \u0623\u062e\u0628\u0631\u0648\u0643\u0645 \u0628\u0647 \u0648\u0646\u0635\u0631\u062a\u0645\u0648\u0647\u0645\u060c \u0648\u0623\u0646\u0641\u0642\u062a\u0645 \u0641\u064a \u0633\u0628\u064a\u0644\u064a\u060c \u0644\u0623\u0643\u0641\u0651\u0650\u0631\u0646\u0651\u064e \u0639\u0646\u0643\u0645 \u0633\u064a\u0626\u0627\u062a\u0643\u0645\u060c \u0648\u0644\u0623\u062f\u0652\u062e\u0650\u0644\u064e\u0646\u0651\u064e\u0643\u064f\u0645 \u062c\u0646\u0627\u062a\u064d \u062a\u062c\u0631\u064a \u0645\u0646 \u062a\u062d\u062a \u0642\u0635\u0648\u0631\u0647\u0627 \u0648\u0623\u0634\u062c\u0627\u0631\u0647\u0627 \u0627\u0644\u0623\u0646\u0647\u0627\u0631\u060c \u0641\u0645\u0646 \u062c\u062d\u062f \u0647\u0630\u0627 \u0627\u0644\u0645\u064a\u062b\u0627\u0642 \u0645\u0646\u0643\u0645 \u0641\u0642\u062f \u0639\u062f\u0644 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u062d\u0642 \u0625\u0644\u0649 \u0637\u0631\u064a\u0642 \u0627\u0644\u0636\u0644\u0627\u0644.","5:13":"\u0641\u0628\u0633\u0628\u0628 \u0646\u0642\u0636 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u064a\u0647\u0648\u062f \u0644\u0639\u0647\u0648\u062f\u0647\u0645 \u0627\u0644\u0645\u0624\u0643\u0651\u064e\u062f\u0629 \u0637\u0631\u062f\u0646\u0627\u0647\u0645 \u0645\u0646 \u0631\u062d\u0645\u062a\u0646\u0627\u060c \u0648\u062c\u0639\u0644\u0646\u0627 \u0642\u0644\u0648\u0628\u0647\u0645 \u063a\u0644\u064a\u0638\u0629 \u0644\u0627 \u062a\u0644\u064a\u0646 \u0644\u0644\u0625\u064a\u0645\u0627\u0646\u060c \u064a\u0628\u062f\u0644\u0648\u0646 \u0643\u0644\u0627\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644\u0647 \u0639\u0644\u0649 \u0645\u0648\u0633\u0649\u060c \u0648\u0647\u0648 \u0627\u0644\u062a\u0648\u0631\u0627\u0629\u060c \u0648\u062a\u0631\u0643\u0648\u0627 \u0646\u0635\u064a\u0628\u064b\u0627 \u0645\u0645\u0627 \u0630\u064f\u0643\u0651\u0650\u0631\u0648\u0627 \u0628\u0647\u060c \u0641\u0644\u0645 \u064a\u0639\u0645\u0644\u0648\u0627 \u0628\u0647. \u0648\u0644\u0627 \u062a\u0632\u0627\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u062a\u062c\u062f \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u062e\u064a\u0627\u0646\u0629\u064b \u0648\u063a\u064e\u062f\u0631\u064b\u0627\u060c \u0641\u0647\u0645 \u0639\u0644\u0649 \u0645\u0646\u0647\u0627\u062c \u0623\u0633\u0644\u0627\u0641\u0647\u0645 \u0625\u0644\u0627 \u0642\u0644\u064a\u0644\u0627 \u0645\u0646\u0647\u0645\u060c \u0641\u0627\u0639\u0641 \u0639\u0646 \u0633\u0648\u0621 \u0645\u0639\u0627\u0645\u0644\u062a\u0647\u0645 \u0644\u0643\u060c \u0648\u0627\u0635\u0641\u062d \u0639\u0646\u0647\u0645\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u062d\u0628 \u0645\u064e\u0646 \u0623\u062d\u0633\u0646 \u0627\u0644\u0639\u0641\u0648 \u0648\u0627\u0644\u0635\u0641\u062d \u0625\u0644\u0649 \u0645\u0646 \u0623\u0633\u0627\u0621 \u0625\u0644\u064a\u0647. (\u0648\u0647\u0643\u0630\u0627 \u064a\u062c\u062f \u0623\u0647\u0644 \u0627\u0644\u0632\u064a\u063a \u0633\u0628\u064a\u0644\u0627 \u0625\u0644\u0649 \u0645\u0642\u0627\u0635\u062f\u0647\u0645 \u0627\u0644\u0633\u064a\u0626\u0629 \u0628\u062a\u062d\u0631\u064a\u0641 \u0643\u0644\u0627\u0645 \u0627\u0644\u0644\u0647 \u0648\u062a\u0623\u0648\u064a\u0644\u0647 \u0639\u0644\u0649 \u063a\u064a\u0631 \u0648\u062c\u0647\u0647\u060c \u0641\u0625\u0646 \u0639\u062c\u064e\u0632\u0648\u0627 \u0639\u0646 \u0627\u0644\u062a\u062d\u0631\u064a\u0641 \u0648\u0627\u0644\u062a\u0623\u0648\u064a\u0644 \u062a\u0631\u0643\u0648\u0627 \u0645\u0627 \u0644\u0627 \u064a\u062a\u0641\u0642 \u0645\u0639 \u0623\u0647\u0648\u0627\u0626\u0647\u0645 \u0645\u0650\u0646 \u0634\u0631\u0639 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u062b\u0628\u062a \u0639\u0644\u064a\u0647 \u0625\u0644\u0627 \u0627\u0644\u0642\u0644\u064a\u0644 \u0645\u0645\u0646 \u0639\u0635\u0645\u0647 \u0627\u0644\u0644\u0647 \u0645\u0646\u0647\u0645) .","5:14":"\u0648\u0623\u062e\u0630\u0646\u0627 \u0639\u0644\u0649 \u0627\u0644\u0630\u064a\u0646 \u0627\u062f\u0651\u064e\u0639\u0648\u0627 \u0623\u0646\u0647\u0645 \u0623\u062a\u0628\u0627\u0639 \u0627\u0644\u0645\u0633\u064a\u062d \u0639\u064a\u0633\u0649 -\u0648\u0644\u064a\u0633\u0648\u0627 \u0643\u0630\u0644\u0643- \u0627\u0644\u0639\u0647\u062f \u0627\u0644\u0645\u0624\u0643\u062f \u0627\u0644\u0630\u064a \u0623\u062e\u0630\u0646\u0627\u0647 \u0639\u0644\u0649 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644: \u0628\u0623\u0646 \u064a\u064f\u062a\u0627\u0628\u0639\u0648\u0627 \u0631\u0633\u0648\u0644\u0647\u0645 \u0648\u064a\u0646\u0635\u0631\u0648\u0647 \u0648\u064a\u0624\u0627\u0632\u0631\u0648\u0647\u060c \u0641\u0628\u062f\u0651\u064e\u0644\u0648\u0627 \u062f\u064a\u0646\u0647\u0645\u060c \u0648\u062a\u0631\u0643\u0648\u0627 \u0646\u0635\u064a\u0628\u064b\u0627 \u0645\u0645\u0627 \u0630\u0643\u0631\u0648\u0627 \u0628\u0647\u060c \u0641\u0644\u0645 \u064a\u0639\u0645\u0644\u0648\u0627 \u0628\u0647\u060c \u0643\u0645\u0627 \u0635\u0646\u0639 \u0627\u0644\u064a\u0647\u0648\u062f\u060c \u0641\u0623\u0644\u0642\u064a\u0646\u0627 \u0628\u064a\u0646\u0647\u0645 \u0627\u0644\u0639\u062f\u0627\u0648\u0629 \u0648\u0627\u0644\u0628\u063a\u0636\u0627\u0621 \u0625\u0644\u0649 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0648\u0633\u0648\u0641 \u064a\u0646\u0628\u0626\u0647\u0645 \u0627\u0644\u0644\u0647 \u0628\u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u064a\u0635\u0646\u0639\u0648\u0646 \u064a\u0648\u0645 \u0627\u0644\u062d\u0633\u0627\u0628\u060c \u0648\u0633\u064a\u0639\u0627\u0642\u0628\u0647\u0645 \u0639\u0644\u0649 \u0635\u0646\u064a\u0639\u0647\u0645.","5:15":"\u064a\u0627 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649\u060c \u0642\u062f \u062c\u0627\u0621\u0643\u0645 \u0631\u0633\u0648\u0644\u0646\u0627 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u064a\u0628\u064a\u0651\u0650\u0646 \u0644\u0643\u0645 \u0643\u062b\u064a\u0631\u064b\u0627 \u0645\u0645\u0627 \u0643\u0646\u062a\u0645 \u062a\u064f\u062e\u0652\u0641\u0648\u0646\u0647 \u0639\u0646 \u0627\u0644\u0646\u0627\u0633 \u0645\u0645\u0627 \u0641\u064a \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644\u060c \u0648\u064a\u062a\u0631\u0643 \u0628\u064a\u0627\u0646 \u0645\u0627 \u0644\u0627 \u062a\u0642\u062a\u0636\u064a\u0647 \u0627\u0644\u062d\u0643\u0645\u0629. \u0642\u062f \u062c\u0627\u0621\u0643\u0645 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0646\u0648\u0631 \u0648\u0643\u062a\u0627\u0628 \u0645\u0628\u064a\u0646: \u0648\u0647\u0648 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645.","5:16":"\u064a\u0647\u062f\u064a \u0627\u0644\u0644\u0647 \u0628\u0647\u0630\u0627 \u0627\u0644\u0643\u062a\u0627\u0628 \u0627\u0644\u0645\u0628\u064a\u0646 \u0645\u0646 \u0627\u062a\u0628\u0639 \u0631\u0636\u0627 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0637\u0631\u0642 \u0627\u0644\u0623\u0645\u0646 \u0648\u0627\u0644\u0633\u0644\u0627\u0645\u0629\u060c \u0648\u064a\u062e\u0631\u062c\u0647\u0645 \u0628\u0625\u0630\u0646\u0647 \u0645\u0646 \u0638\u0644\u0645\u0627\u062a \u0627\u0644\u0643\u0641\u0631 \u0625\u0644\u0649 \u0646\u0648\u0631 \u0627\u0644\u0625\u064a\u0645\u0627\u0646\u060c \u0648\u064a\u0648\u0641\u0642\u0647\u0645 \u0625\u0644\u0649 \u062f\u064a\u0646\u0647 \u0627\u0644\u0642\u0648\u064a\u0645.","5:17":"\u0644\u0642\u062f \u0643\u0641\u0631 \u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0627\u0644\u0642\u0627\u0626\u0644\u0648\u0646 \u0628\u0623\u0646 \u0627\u0644\u0644\u0647 \u0647\u0648 \u0627\u0644\u0645\u0633\u064a\u062d \u0628\u0646 \u0645\u0631\u064a\u0645\u060c \u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u062c\u0647\u0644\u0629 \u0645\u0646 \u0627\u0644\u0646\u0635\u0627\u0631\u0649: \u0644\u0648 \u0643\u0627\u0646 \u0627\u0644\u0645\u0633\u064a\u062d \u0625\u0644\u0647\u064b\u0627 \u0643\u0645\u0627 \u064a\u062f\u0651\u064e\u0639\u0648\u0646 \u0644\u0642\u064e\u062f\u0631\u064e \u0623\u0646 \u064a\u062f\u0641\u0639 \u0642\u0636\u0627\u0621 \u0627\u0644\u0644\u0647 \u0625\u0630\u0627 \u062c\u0627\u0621\u0647 \u0628\u0625\u0647\u0644\u0627\u0643\u0647 \u0648\u0625\u0647\u0644\u0627\u0643 \u0623\u064f\u0645\u0651\u0650\u0647 \u0648\u0645\u064e\u0646 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u062c\u0645\u064a\u0639\u064b\u0627\u060c \u0648\u0642\u062f \u0645\u0627\u062a\u062a \u0623\u0645 \u0639\u064a\u0633\u0649 \u0641\u0644\u0645 \u064a\u062f\u0641\u0639 \u0639\u0646\u0647\u0627 \u0627\u0644\u0645\u0648\u062a\u060c \u0643\u0630\u0644\u0643 \u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639 \u0623\u0646 \u064a\u062f\u0641\u0639 \u0639\u0646 \u0646\u0641\u0633\u0647; \u0644\u0623\u0646\u0647\u0645\u0627 \u0639\u0628\u062f\u0627\u0646 \u0645\u0646 \u0639\u0628\u0627\u062f \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0642\u062f\u0631\u0627\u0646 \u0639\u0644\u0649 \u062f\u0641\u0639 \u0627\u0644\u0647\u0644\u0627\u0643 \u0639\u0646\u0647\u0645\u0627\u060c \u0641\u0647\u0630\u0627 \u062f\u0644\u064a\u0644\u064c \u0639\u0644\u0649 \u0623\u0646\u0647 \u0628\u0634\u0631 \u0643\u0633\u0627\u0626\u0631 \u0628\u0646\u064a \u0622\u062f\u0645. \u0648\u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u0648\u062c\u0648\u062f\u0627\u062a \u0641\u064a \u0627\u0644\u0633\u0645\u0627\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0645\u0644\u0643 \u0644\u0644\u0647\u060c \u064a\u062e\u0644\u0642 \u0645\u0627 \u064a\u0634\u0627\u0621 \u0648\u064a\u0648\u062c\u062f\u0647\u060c \u0648\u0647\u0648 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621 \u0642\u062f\u064a\u0631. \u0641\u062d\u0642\u064a\u0642\u0629 \u0627\u0644\u062a\u0648\u062d\u064a\u062f \u062a\u0648\u062c\u0628 \u062a\u0641\u0631\u0651\u064f\u062f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0635\u0641\u0627\u062a \u0627\u0644\u0631\u0628\u0648\u0628\u064a\u0629 \u0648\u0627\u0644\u0623\u0644\u0648\u0647\u064a\u0629\u060c \u0641\u0644\u0627 \u064a\u0634\u0627\u0631\u0643\u0647 \u0623\u062d\u062f \u0645\u0646 \u062e\u0644\u0642\u0647 \u0641\u064a \u0630\u0644\u0643\u060c \u0648\u0643\u062b\u064a\u0631\u064b\u0627 \u0645\u0627 \u064a\u0642\u0639 \u0627\u0644\u0646\u0627\u0633 \u0641\u064a \u0627\u0644\u0634\u0631\u0643 \u0648\u0627\u0644\u0636\u0644\u0627\u0644 \u0628\u063a\u0644\u0648\u0647\u0645 \u0641\u064a \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0648\u0627\u0644\u0635\u0627\u0644\u062d\u064a\u0646\u060c \u0643\u0645\u0627 \u063a\u0644\u0627 \u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0641\u064a \u0627\u0644\u0645\u0633\u064a\u062d\u060c \u0641\u0627\u0644\u0643\u0648\u0646 \u0643\u0644\u0647 \u0644\u0644\u0647\u060c \u0648\u0627\u0644\u062e\u0644\u0642 \u0628\u064a\u062f\u0647 \u0648\u062d\u062f\u0647\u060c \u0648\u0645\u0627 \u064a\u0638\u0647\u0631 \u0645\u0646 \u062e\u0648\u0627\u0631\u0642 \u0648\u0622\u064a\u0627\u062a \u0645\u064e\u0631\u064e\u062f\u0651\u064f\u0647 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647. \u064a\u062e\u0644\u0642 \u0633\u0628\u062d\u0627\u0646\u0647 \u0645\u0627 \u064a\u0634\u0627\u0621\u060c \u0648\u064a\u0641\u0639\u0644 \u0645\u0627 \u064a\u0631\u064a\u062f.","5:18":"\u0648\u0632\u0639\u0645 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0623\u0646\u0647\u0645 \u0623\u0628\u0646\u0627\u0621 \u0627\u0644\u0644\u0647 \u0648\u0623\u062d\u0628\u0627\u0624\u0647\u060c \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0641\u064e\u0644\u0623\u064a\u0651\u0650 \u0634\u064a\u0621 \u064a\u0639\u0630\u0651\u0650\u0628\u0643\u0645 \u0628\u0630\u0646\u0648\u0628\u0643\u0645\u061f \u0641\u0644\u0648 \u0643\u0646\u062a\u0645 \u0623\u062d\u0628\u0627\u0628\u0647 \u0645\u0627 \u0639\u0630\u0628\u0643\u0645\u060c \u0641\u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u062d\u0628 \u0625\u0644\u0627 \u0645\u0646 \u0623\u0637\u0627\u0639\u0647\u060c \u0648\u0642\u0644 \u0644\u0647\u0645: \u0628\u0644 \u0623\u0646\u062a\u0645 \u062e\u0644\u0642\u064c \u0645\u062b\u0644\u064f \u0633\u0627\u0626\u0631 \u0628\u0646\u064a \u0622\u062f\u0645\u060c \u0625\u0646 \u0623\u062d\u0633\u0646\u062a\u064f\u0645 \u062c\u0648\u0632\u064a\u062a\u0645 \u0628\u0625\u062d\u0633\u0627\u0646\u0643\u0645 \u062e\u064a\u0631\u0627\u060c \u0648\u0625\u0646 \u0623\u0633\u064e\u0623\u0652\u062a\u064f\u0645 \u062c\u0648\u0632\u064a\u062a\u0645 \u0628\u0625\u0633\u0627\u0621\u062a\u0643\u0645 \u0634\u0631\u0651\u064b\u0627\u060c \u0641\u0627\u0644\u0644\u0647 \u064a\u063a\u0641\u0631 \u0644\u0645\u0646 \u064a\u0634\u0627\u0621\u060c \u0648\u064a\u0639\u0630\u0628 \u0645\u0646 \u064a\u0634\u0627\u0621\u060c \u0648\u0647\u0648 \u0645\u0627\u0644\u0643 \u0627\u0644\u0645\u0644\u0643\u060c \u064a\u064f\u0635\u064e\u0631\u0651\u0650\u0641\u0647 \u0643\u0645\u0627 \u064a\u0634\u0627\u0621\u060c \u0648\u0625\u0644\u064a\u0647 \u0627\u0644\u0645\u0631\u062c\u0639\u060c \u0641\u064a\u062d\u0643\u0645 \u0628\u064a\u0646 \u0639\u0628\u0627\u062f\u0647\u060c \u0648\u064a\u062c\u0627\u0632\u064a \u0643\u0644\u0627 \u0628\u0645\u0627 \u064a\u0633\u062a\u062d\u0642.","5:19":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0642\u062f \u062c\u0627\u0621\u0643\u0645 \u0631\u0633\u0648\u0644\u0646\u0627 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u064a\u064f\u0628\u064a\u0651\u0650\u0646 \u0644\u0643\u0645 \u0627\u0644\u062d\u0642 \u0648\u0627\u0644\u0647\u062f\u0649 \u0628\u0639\u062f \u0645\u064f\u062f\u0651\u064e\u0629 \u0645\u0646 \u0627\u0644\u0632\u0645\u0646 \u0628\u064a\u0646 \u0625\u0631\u0633\u0627\u0644\u0647 \u0628\u0625\u0631\u0633\u0627\u0644 \u0639\u064a\u0633\u0649 \u0627\u0628\u0646 \u0645\u0631\u064a\u0645; \u0644\u0626\u0644\u0627 \u062a\u0642\u0648\u0644\u0648\u0627: \u0645\u0627 \u062c\u0627\u0621\u0646\u0627 \u0645\u0646 \u0628\u0634\u064a\u0631 \u0648\u0644\u0627 \u0646\u0630\u064a\u0631\u060c \u0641\u0644\u0627 \u0639\u064f\u0630\u0631\u064e \u0644\u0643\u0645 \u0628\u0639\u062f \u0625\u0631\u0633\u0627\u0644\u0647 \u0625\u0644\u064a\u0643\u0645\u060c \u0641\u0642\u062f \u062c\u0627\u0621\u0643\u0645 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0631\u0633\u0648\u0644\u064c \u064a\u0628\u0634\u0651\u0650\u0631 \u0645\u064e\u0646 \u0622\u0645\u0646 \u0628\u0647\u060c \u0648\u064a\u064f\u0646\u0630\u0650\u0631 \u0645\u064e\u0646 \u0639\u0635\u0627\u0647. \u0648\u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621 \u0642\u062f\u064a\u0631 \u0645\u0646 \u0639\u0642\u0627\u0628 \u0627\u0644\u0639\u0627\u0635\u064a \u0648\u062b\u0648\u0627\u0628 \u0627\u0644\u0645\u0637\u064a\u0639.","5:20":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0625\u0630 \u0642\u0627\u0644 \u0645\u0648\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0644\u0642\u0648\u0645\u0647: \u064a\u0627 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0639\u0645\u0629 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645\u060c \u0625\u0630 \u062c\u0639\u0644 \u0641\u064a\u0643\u0645 \u0623\u0646\u0628\u064a\u0627\u0621\u060c \u0648\u062c\u0639\u0644\u0643\u0645 \u0645\u0644\u0648\u0643\u064b\u0627 \u062a\u0645\u0644\u0643\u0648\u0646 \u0623\u0645\u0631\u0643\u0645 \u0628\u0639\u062f \u0623\u0646 \u0643\u0646\u062a\u0645 \u0645\u0645\u0644\u0648\u0643\u064a\u0646 \u0644\u0641\u0631\u0639\u0648\u0646 \u0648\u0642\u0648\u0645\u0647\u060c \u0648\u0642\u062f \u0645\u0646\u062d\u0643\u0645 \u0645\u0646 \u0646\u0639\u0645\u0647 \u0635\u0646\u0648\u0641\u064b\u0627 \u0644\u0645 \u064a\u0645\u0646\u062d\u0647\u0627 \u0623\u062d\u062f\u064b\u0627 \u0645\u0646 \u0639\u0627\u0644\u064e\u0645\u064a \u0632\u0645\u0627\u0646\u0643\u0645.","5:21":"\u064a\u0627 \u0642\u0648\u0645 \u0627\u062f\u062e\u0644\u0648\u0627 \u0627\u0644\u0623\u0631\u0636 \u0627\u0644\u0645\u0642\u062f\u0633\u0629 -\u0623\u064a \u0627\u0644\u0645\u0637\u0647\u0631\u0629\u060c \u0648\u0647\u064a \xab\u0628\u064a\u062a \u0627\u0644\u0645\u0642\u062f\u0633\xbb \u0648\u0645\u0627 \u062d\u0648\u0644\u0647\u0627- \u0627\u0644\u062a\u064a \u0648\u0639\u062f \u0627\u0644\u0644\u0647 \u0623\u0646 \u062a\u062f\u062e\u0644\u0648\u0647\u0627 \u0648\u062a\u0642\u0627\u062a\u0644\u0648\u0627 \u0645\u064e\u0646 \u0641\u064a\u0647\u0627 \u0645\u0646 \u0627\u0644\u0643\u0641\u0627\u0631\u060c \u0648\u0644\u0627 \u062a\u0631\u062c\u0639\u0648\u0627 \u0639\u0646 \u0642\u062a\u0627\u0644 \u0627\u0644\u062c\u0628\u0627\u0631\u064a\u0646\u060c \u0641\u062a\u062e\u0633\u0631\u0648\u0627 \u062e\u064a\u0631 \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u062e\u064a\u0631 \u0627\u0644\u0622\u062e\u0631\u0629.","5:22":"\u0642\u0627\u0644\u0648\u0627: \u064a\u0627 \u0645\u0648\u0633\u0649\u060c \u0625\u0646 \u0641\u064a\u0647\u0627 \u0642\u0648\u0645\u064b\u0627 \u0623\u0634\u062f\u0627\u0621 \u0623\u0642\u0648\u064a\u0627\u0621\u060c \u0644\u0627 \u0637\u0627\u0642\u0629 \u0644\u0646\u0627 \u0628\u062d\u0631\u0628\u0647\u0645\u060c \u0648\u0625\u0646\u0651\u064e\u0627 \u0644\u0646 \u0646\u0633\u062a\u0637\u064a\u0639 \u062f\u062e\u0648\u0644\u0647\u0627 \u0648\u0647\u0645 \u0641\u064a\u0647\u0627\u060c \u0641\u0625\u0646 \u064a\u062e\u0631\u062c\u0648\u0627 \u0645\u0646\u0647\u0627 \u0641\u0625\u0646\u0651\u064e\u0627 \u062f\u0627\u062e\u0644\u0648\u0646.","5:23":"\u0642\u0627\u0644 \u0631\u062c\u0644\u0627\u0646 \u0645\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u062e\u0634\u0648\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0623\u0646\u0639\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645\u0627 \u0628\u0637\u0627\u0639\u062a\u0647 \u0648\u0637\u0627\u0639\u0629 \u0646\u0628\u064a\u0651\u0650\u0647\u060c \u0644\u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644: \u0627\u062f\u062e\u0644\u0648\u0627 \u0639\u0644\u0649 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u062c\u0628\u0627\u0631\u064a\u0646 \u0628\u0627\u0628 \u0645\u062f\u064a\u0646\u062a\u0647\u0645\u060c \u0623\u062e\u0652\u0630\u064b\u0627 \u0628\u0627\u0644\u0623\u0633\u0628\u0627\u0628\u060c \u0641\u0625\u0630\u0627 \u062f\u062e\u0644\u062a\u0645 \u0627\u0644\u0628\u0627\u0628 \u063a\u0644\u0628\u062a\u0645\u0648\u0647\u0645\u060c \u0648\u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0641\u062a\u0648\u0643\u0651\u064e\u0644\u0648\u0627\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u0645\u064f\u0635\u062f\u0651\u0650\u0642\u064a\u0646 \u0631\u0633\u0648\u0644\u0647 \u0641\u064a\u0645\u0627 \u062c\u0627\u0621\u0643\u0645 \u0628\u0647\u060c \u0639\u0627\u0645\u0644\u064a\u0646 \u0628\u0634\u0631\u0639\u0647.","5:24":"\u0642\u0627\u0644 \u0642\u0648\u0645 \u0645\u0648\u0633\u0649 \u0644\u0647: \u0625\u0646\u0627 \u0644\u0646 \u0646\u062f\u062e\u0644 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0623\u0628\u062f\u064b\u0627 \u0645\u0627 \u062f\u0627\u0645 \u0627\u0644\u062c\u0628\u0627\u0631\u0648\u0646 \u0641\u064a\u0647\u0627\u060c \u0641\u0627\u0630\u0647\u0628 \u0623\u0646\u062a \u0648\u0631\u0628\u0643 \u0641\u0642\u0627\u062a\u0644\u0627\u0647\u0645\u060c \u0623\u0645\u0627 \u0646\u062d\u0646 \u0641\u0642\u0627\u0639\u062f\u0648\u0646 \u0647\u0627\u0647\u0646\u0627 \u0648\u0644\u0646 \u0646\u0642\u0627\u062a\u0644\u0647\u0645. \u0648\u0647\u0630\u0627 \u0625\u0635\u0631\u0627\u0631\u064c \u0645\u0646\u0647\u0645 \u0639\u0644\u0649 \u0645\u062e\u0627\u0644\u0641\u0629 \u0645\u0648\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645.","5:25":"\u062a\u0648\u062c\u0651\u064e\u0647 \u0645\u0648\u0633\u0649 \u0625\u0644\u0649 \u0631\u0628\u0647 \u062f\u0627\u0639\u064a\u064b\u0627: \u0625\u0646\u064a \u0644\u0627 \u0623\u0642\u062f\u0631 \u0625\u0644\u0627 \u0639\u0644\u0649 \u0646\u0641\u0633\u064a \u0648\u0623\u062e\u064a\u060c \u0641\u0627\u062d\u0643\u0645 \u0628\u064a\u0646\u0646\u0627 \u0648\u0628\u064a\u0646 \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u0641\u0627\u0633\u0642\u064a\u0646.","5:26":"\u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u0644\u0646\u0628\u064a\u0647 \u0645\u0648\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645: \u0625\u0646 \u0627\u0644\u0623\u0631\u0636 \u0627\u0644\u0645\u0642\u062f\u0651\u064e\u0633\u0629 \u0645\u062d\u0631\u0651\u064e\u0645 \u0639\u0644\u0649 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u064a\u0647\u0648\u062f \u062f\u062e\u0648\u0644\u0647\u0627 \u0623\u0631\u0628\u0639\u064a\u0646 \u0633\u0646\u0629\u060c \u064a\u062a\u064a\u0647\u0648\u0646 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u062d\u0627\u0626\u0631\u064a\u0646\u060c \u0641\u0644\u0627 \u062a\u0623\u0633\u0641 -\u064a\u0627 \u0645\u0648\u0633\u0649- \u0639\u0644\u0649 \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u062e\u0627\u0631\u062c\u064a\u0646 \u0639\u0646 \u0637\u0627\u0639\u062a\u064a.","5:27":"\u0648\u0627\u0642\u0635\u0635 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0639\u0644\u0649 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u062e\u064e\u0628\u064e\u0631 \u0627\u0628\u0646\u064e\u064a\u0652 \u0622\u062f\u0645 \u0642\u0627\u0628\u064a\u0644 \u0648\u0647\u0627\u0628\u064a\u0644\u060c \u0648\u0647\u0648 \u062e\u0628\u0631\u064c \u062d\u0642\u064c: \u062d\u064a\u0646 \u0642\u064e\u062f\u0651\u064e\u0645 \u0643\u0644\u0651\u064c \u0645\u0646\u0647\u0645\u0627 \u0642\u0631\u0628\u0627\u0646\u064b\u0627 -\u0648\u0647\u0648 \u0645\u0627 \u064a\u064f\u062a\u064e\u0642\u0631\u0651\u064e\u0628 \u0628\u0647 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649- \u0641\u062a\u0642\u0628\u0651\u064e\u0644 \u0627\u0644\u0644\u0647 \u0642\u064f\u0631\u0628\u0627\u0646 \u0647\u0627\u0628\u064a\u0644; \u0644\u0623\u0646\u0647 \u0643\u0627\u0646 \u062a\u0642\u064a\u0651\u064b\u0627\u060c \u0648\u0644\u0645 \u064a\u062a\u0642\u0628\u0651\u064e\u0644 \u0642\u064f\u0631\u0628\u0627\u0646 \u0642\u0627\u0628\u064a\u0644; \u0644\u0623\u0646\u0647 \u0644\u0645 \u064a\u0643\u0646 \u062a\u0642\u064a\u0651\u064b\u0627\u060c \u0641\u062d\u0633\u062f \u0642\u0627\u0628\u064a\u0644\u064f \u0623\u062e\u0627\u0647\u060c \u0648\u0642\u0627\u0644: \u0644\u0623\u0642\u062a\u0644\u0646\u0651\u064e\u0643\u060c \u0641\u064e\u0631\u062f\u0651\u064e \u0647\u0627\u0628\u064a\u0644: \u0625\u0646\u0645\u0627 \u064a\u062a\u0642\u0628\u0644 \u0627\u0644\u0644\u0647 \u0645\u0645\u0646 \u064a\u062e\u0634\u0648\u0646\u0647.","5:28":"\u0648\u0642\u0627\u0644 \u0647\u0627\u0628\u064a\u0644\u064f \u0648\u0627\u0639\u0638\u064b\u0627 \u0623\u062e\u0627\u0647: \u0644\u064e\u0626\u0646\u0652 \u0645\u064e\u062f\u064e\u062f\u0652\u062a\u064e \u0625\u0644\u064a\u0651\u064e \u064a\u062f\u0643\u064e \u0644\u062a\u0642\u062a\u064f\u0644\u0646\u064a \u0644\u0627 \u062a\u064e\u062c\u0650\u062f\u064f \u0645\u0646\u064a \u0645\u062b\u0644 \u0641\u0639\u0652\u0644\u0643\u060c \u0648\u0625\u0646\u064a \u0623\u062e\u0634\u0649 \u0627\u0644\u0644\u0647 \u0631\u0628\u0651\u064e \u0627\u0644\u062e\u0644\u0627\u0626\u0642 \u0623\u062c\u0645\u0639\u064a\u0646.","5:29":"\u0625\u0646\u064a \u0623\u0631\u064a\u062f \u0623\u0646 \u062a\u0631\u062c\u0639 \u062d\u0627\u0645\u0644\u0627 \u0625\u062b\u0645 \u0642\u064e\u062a\u0652\u0644\u064a\u060c \u0648\u0625\u062b\u0645\u0643 \u0627\u0644\u0630\u064a \u0639\u0644\u064a\u0643 \u0642\u0628\u0644 \u0630\u0644\u0643\u060c \u0641\u062a\u0643\u0648\u0646 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0646\u0627\u0631 \u0648\u0645\u0644\u0627\u0632\u0645\u064a\u0647\u0627\u060c \u0648\u0630\u0644\u0643 \u062c\u0632\u0627\u0621 \u0627\u0644\u0645\u0639\u062a\u062f\u064a\u0646.","5:30":"\u0641\u064e\u0632\u064e\u064a\u0651\u064e\u0646\u062a \u0644\u0642\u0627\u0628\u064a\u0644\u064e \u0646\u0641\u0633\u064f\u0647 \u0623\u0646 \u064a\u0642\u062a\u0644 \u0623\u062e\u0627\u0647\u060c \u0641\u0642\u062a\u0644\u0647\u060c \u0641\u0623\u0635\u0628\u062d \u0645\u0646 \u0627\u0644\u062e\u0627\u0633\u0631\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0628\u0627\u0639\u0648\u0627 \u0622\u062e\u0631\u062a\u0647\u0645 \u0628\u062f\u0646\u064a\u0627\u0647\u0645.","5:31":"\u0644\u0645\u0627 \u0642\u062a\u0644 \u0642\u0627\u0628\u064a\u0644\u064f \u0623\u062e\u0627\u0647 \u0644\u0645 \u064a\u0639\u0631\u0641 \u0645\u0627 \u064a\u0635\u0646\u0639 \u0628\u062c\u0633\u062f\u0647\u060c \u0641\u0623\u0631\u0633\u0644 \u0627\u0644\u0644\u0647 \u063a\u0631\u0627\u0628\u064b\u0627 \u064a\u062d\u0641\u0631 \u062d\u0641\u0631\u0629\u064b \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0644\u064a\u062f\u0641\u0646 \u0641\u064a\u0647\u0627 \u063a\u0631\u0627\u0628\u064b\u0627 \u0645\u064e\u064a\u0651\u0650\u062a\u064b\u0627; \u0644\u064a\u062f\u0644 \u0642\u0627\u0628\u064a\u0644 \u0643\u064a\u0641 \u064a\u062f\u0641\u0646 \u062c\u064f\u062b\u0645\u0627\u0646 \u0623\u062e\u064a\u0647\u061f \u0641\u062a\u0639\u062c\u0651\u064e\u0628 \u0642\u0627\u0628\u064a\u0644\u060c \u0648\u0642\u0627\u0644: \u0623\u0639\u062c\u0632\u062a\u064f \u0623\u0646 \u0623\u0635\u0646\u0639 \u0645\u062b\u0644 \u0635\u0646\u064a\u0639 \u0647\u0630\u0627 \u0627\u0644\u063a\u0631\u0627\u0628 \u0641\u0623\u0633\u062a\u064f\u0631\u064e \u0639\u0648\u0631\u0629 \u0623\u062e\u064a\u061f \u0641\u062f\u064e\u0641\u064e\u0646\u064e \u0642\u0627\u0628\u064a\u0644 \u0623\u062e\u0627\u0647\u060c \u0641\u0639\u0627\u0642\u0628\u0647 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u0646\u062f\u0627\u0645\u0629 \u0628\u0639\u062f \u0623\u0646 \u0631\u062c\u0639 \u0628\u0627\u0644\u062e\u0633\u0631\u0627\u0646.","5:32":"\u0628\u0633\u0628\u0628 \u062c\u0646\u0627\u064a\u0629 \u0627\u0644\u0642\u062a\u0644 \u0647\u0630\u0647 \u0634\u064e\u0631\u064e\u0639\u0652\u0646\u0627 \u0644\u0628\u0646\u064a \u0627\u0633\u0631\u0627\u0626\u064a\u0644 \u0623\u0646\u0647 \u0645\u0646 \u0642\u062a\u0644 \u0646\u0641\u0633\u0627 \u0628\u063a\u064a\u0631 \u0633\u0628\u0628 \u0645\u0646 \u0642\u0635\u0627\u0635\u060c \u0623\u0648 \u0641\u0633\u0627\u062f \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0628\u0623\u064a \u0646\u0648\u0639 \u0645\u0646 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0641\u0633\u0627\u062f\u060c \u0627\u0644\u0645\u0648\u062c\u0628 \u0644\u0644\u0642\u062a\u0644 \u0643\u0627\u0644\u0634\u0631\u0643 \u0648\u0627\u0644\u0645\u062d\u0627\u0631\u0628\u0629 \u0641\u0643\u0623\u0646\u0645\u0627 \u0642\u062a\u0644 \u0627\u0644\u0646\u0627\u0633 \u062c\u0645\u064a\u0639\u064b\u0627 \u0641\u064a\u0645\u0627 \u0627\u0633\u062a\u0648\u062c\u0628 \u0645\u0646 \u0639\u0638\u064a\u0645 \u0627\u0644\u0639\u0642\u0648\u0628\u0629 \u0645\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0623\u0646\u0647 \u0645\u0646 \u0627\u0645\u062a\u0646\u0639 \u0639\u0646 \u0642\u064e\u062a\u0652\u0644 \u0646\u0641\u0633 \u062d\u0631\u0651\u064e\u0645\u0647\u0627 \u0627\u0644\u0644\u0647 \u0641\u0643\u0623\u0646\u0645\u0627 \u0623\u062d\u064a\u0627 \u0627\u0644\u0646\u0627\u0633 \u062c\u0645\u064a\u0639\u064b\u0627; \u0641\u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u062d\u0631\u0645\u0629 \u0625\u0646\u0633\u0627\u0646 \u0648\u0627\u062d\u062f \u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u062d\u0631\u0645\u0627\u062a \u0627\u0644\u0646\u0627\u0633 \u0643\u0644\u0647\u0645. \u0648\u0644\u0642\u062f \u0623\u062a\u062a \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0631\u0633\u0644\u064f\u0646\u0627 \u0628\u0627\u0644\u062d\u062c\u062c \u0648\u0627\u0644\u062f\u0644\u0627\u0626\u0644 \u0639\u0644\u0649 \u0635\u062d\u0629 \u0645\u0627 \u062f\u0639\u064e\u0648\u0647\u0645 \u0625\u0644\u064a\u0647 \u0645\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0631\u0628\u0647\u0645\u060c \u0648\u0623\u062f\u0627\u0621 \u0645\u0627 \u0641\u064f\u0631\u0650\u0636\u064e \u0639\u0644\u064a\u0647\u0645\u060c \u062b\u0645 \u0625\u0646 \u0643\u062b\u064a\u0631\u064b\u0627 \u0645\u0646\u0647\u0645 \u0628\u0639\u062f \u0645\u062c\u064a\u0621 \u0627\u0644\u0631\u0633\u0644 \u0625\u0644\u064a\u0647\u0645 \u0644\u0645\u062a\u062c\u0627\u0648\u0632\u0648\u0646 \u062d\u062f\u0648\u062f \u0627\u0644\u0644\u0647 \u0628\u0627\u0631\u062a\u0643\u0627\u0628 \u0645\u062d\u0627\u0631\u0645 \u0627\u0644\u0644\u0647 \u0648\u062a\u0631\u0643 \u0623\u0648\u0627\u0645\u0631\u0647.","5:33":"\u0625\u0646\u0645\u0627 \u062c\u0632\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u064a\u062d\u0627\u0631\u0628\u0648\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u064a\u0628\u0627\u0631\u0632\u0648\u0646\u0647 \u0628\u0627\u0644\u0639\u062f\u0627\u0648\u0629\u060c \u0648\u064a\u0639\u062a\u062f\u0648\u0646 \u0639\u0644\u0649 \u0623\u062d\u0643\u0627\u0645\u0647\u060c \u0648\u0639\u0644\u0649 \u0623\u062d\u0643\u0627\u0645 \u0631\u0633\u0648\u0644\u0647\u060c \u0648\u064a\u0641\u0633\u062f\u0648\u0646 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0628\u0642\u062a\u0644 \u0627\u0644\u0623\u0646\u0641\u0633\u060c \u0648\u0633\u0644\u0628 \u0627\u0644\u0623\u0645\u0648\u0627\u0644\u060c \u0623\u0646 \u064a\u064f\u0642\u064e\u062a\u0651\u064e\u0644\u0648\u0627\u060c \u0623\u0648 \u064a\u064f\u0635\u064e\u0644\u0651\u064e\u0628\u0648\u0627 \u0645\u0639 \u0627\u0644\u0642\u062a\u0644 (\u0648\u0627\u0644\u0635\u0644\u0628: \u0623\u0646 \u064a\u064f\u0634\u064e\u062f\u0651\u064e \u0627\u0644\u062c\u0627\u0646\u064a \u0639\u0644\u0649 \u062e\u0634\u0628\u0629) \u0623\u0648 \u062a\u064f\u0642\u0652\u0637\u064e\u0639 \u064a\u062f\u064f \u0627\u0644\u0645\u062d\u0627\u0631\u0628 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0631\u062c\u0644\u0647 \u0627\u0644\u064a\u0633\u0631\u0649\u060c \u0641\u0625\u0646 \u0644\u0645 \u064a\u064e\u062a\u064f\u0628\u0652 \u062a\u064f\u0642\u0637\u0639\u0652 \u064a\u062f\u064f\u0647 \u0627\u0644\u064a\u0633\u0631\u0649 \u0648\u0631\u062c\u0644\u064f\u0647 \u0627\u0644\u064a\u0645\u0646\u0649\u060c \u0623\u0648 \u064a\u064f\u0646\u0641\u064e\u0648\u0627 \u0625\u0644\u0649 \u0628\u0644\u062f \u063a\u064a\u0631 \u0628\u0644\u062f\u0647\u0645\u060c \u0648\u064a\u064f\u062d\u0628\u0633\u0648\u0627 \u0641\u064a \u0633\u062c\u0646 \u0630\u0644\u0643 \u0627\u0644\u0628\u0644\u062f \u062d\u062a\u0649 \u062a\u064e\u0638\u0647\u0631 \u062a\u0648\u0628\u062a\u064f\u0647\u0645. \u0648\u0647\u0630\u0627 \u0627\u0644\u062c\u0632\u0627\u0621 \u0627\u0644\u0630\u064a \u0623\u0639\u062f\u0651\u064e\u0647 \u0627\u0644\u0644\u0647 \u0644\u0644\u0645\u062d\u0627\u0631\u0628\u064a\u0646 \u0647\u0648 \u0630\u0644\u0651 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0639\u0630\u0627\u0628 \u0634\u062f\u064a\u062f \u0625\u0646 \u0644\u0645 \u064a\u062a\u0648\u0628\u0648\u0627.","5:34":"\u0644\u0643\u0646 \u0645\u064e\u0646 \u0623\u062a\u0649 \u0645\u0646 \u0627\u0644\u0645\u062d\u0627\u0631\u0628\u064a\u0646 \u0645\u0646 \u0642\u0628\u0644 \u0623\u0646 \u062a\u0642\u062f\u0631\u0648\u0627 \u0639\u0644\u064a\u0647\u0645 \u0648\u062c\u0627\u0621 \u0637\u0627\u0626\u0639\u064b\u0627 \u0646\u0627\u062f\u0645\u064b\u0627 \u0641\u0625\u0646\u0647 \u064a\u0633\u0642\u0637 \u0639\u0646\u0647 \u0645\u0627 \u0643\u0627\u0646 \u0644\u0644\u0647\u060c \u0641\u0627\u0639\u0644\u0645\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0623\u0646 \u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0644\u0639\u0628\u0627\u062f\u0647\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","5:35":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u062e\u0627\u0641\u0648\u0627 \u0627\u0644\u0644\u0647\u060c \u0648\u062a\u064e\u0642\u064e\u0631\u0651\u064e\u0628\u0648\u0627 \u0625\u0644\u064a\u0647 \u0628\u0637\u0627\u0639\u062a\u0647 \u0648\u0627\u0644\u0639\u0645\u0644 \u0628\u0645\u0627 \u064a\u0631\u0636\u064a\u0647\u060c \u0648\u062c\u0627\u0647\u062f\u0648\u0627 \u0641\u064a \u0633\u0628\u064a\u0644\u0647; \u0643\u064a \u062a\u0641\u0648\u0632\u0648\u0627 \u0628\u062c\u0646\u0627\u062a\u0647.","5:36":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u062c\u062d\u062f\u0648\u0627 \u0648\u062d\u062f\u0627\u0646\u064a\u0629 \u0627\u0644\u0644\u0647\u060c \u0648\u0634\u0631\u064a\u0639\u062a\u0647\u060c \u0644\u0648 \u0623\u0646\u0647\u0645 \u0633\u0644\u0643\u0648\u0627 \u062c\u0645\u064a\u0639 \u0645\u0627 \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0645\u0644\u0643\u0648\u0627 \u0645\u062b\u0644\u0647 \u0645\u0639\u0647\u060c \u0648\u0623\u0631\u0627\u062f\u0648\u0627 \u0623\u0646 \u064a\u0641\u062a\u062f\u0648\u0627 \u0623\u0646\u0641\u0633\u0647\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647 \u0628\u0645\u0627 \u0645\u0644\u0643\u0648\u0627\u060c \u0645\u0627 \u062a\u064e\u0642\u0628\u0651\u064e\u0644 \u0627\u0644\u0644\u0647 \u0630\u0644\u0643 \u0645\u0646\u0647\u0645\u060c \u0648\u0644\u0647\u0645 \u0639\u0630\u0627\u0628 \u0645\u064f\u0648\u062c\u0639.","5:37":"\u064a\u0631\u064a\u062f \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0627\u0641\u0631\u0648\u0646 \u0627\u0644\u062e\u0631\u0648\u062c \u0645\u0646 \u0627\u0644\u0646\u0627\u0631 \u0644\u0645\u0627 \u064a\u0644\u0627\u0642\u0648\u0646\u0647 \u0645\u0646 \u0623\u0647\u0648\u0627\u0644\u0647\u0627\u060c \u0648\u0644\u0627 \u0633\u0628\u064a\u0644 \u0644\u0647\u0645 \u0625\u0644\u0649 \u0630\u0644\u0643\u060c \u0648\u0644\u0647\u0645 \u0639\u0630\u0627\u0628 \u062f\u0627\u0626\u0645.","5:38":"\u0648\u0627\u0644\u0633\u0627\u0631\u0642 \u0648\u0627\u0644\u0633\u0627\u0631\u0642\u0629 \u0641\u0627\u0642\u0637\u0639\u0648\u0627 -\u064a\u0627 \u0648\u0644\u0627\u0629 \u0627\u0644\u0623\u0645\u0631- \u0623\u064a\u062f\u064a\u0647\u0645\u0627 \u0628\u0645\u0642\u062a\u0636\u0649 \u0627\u0644\u0634\u0631\u0639\u060c \u0645\u062c\u0627\u0632\u0627\u0629 \u0644\u0647\u0645\u0627 \u0639\u0644\u0649 \u0623\u064e\u062e\u0652\u0630\u0647\u0645\u0627 \u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u0646\u0627\u0633 \u0628\u063a\u064a\u0631 \u062d\u0642\u060c \u0648\u0639\u0642\u0648\u0628\u0629\u064b \u064a\u0645\u0646\u0639 \u0627\u0644\u0644\u0647 \u0628\u0647\u0627 \u063a\u064a\u0631\u0647\u0645\u0627 \u0623\u0646 \u064a\u0635\u0646\u0639 \u0645\u062b\u0644 \u0635\u0646\u064a\u0639\u0647\u0645\u0627. \u0648\u0627\u0644\u0644\u0647 \u0639\u0632\u064a\u0632 \u0641\u064a \u0645\u0644\u0643\u0647\u060c \u062d\u0643\u064a\u0645 \u0641\u064a \u0623\u0645\u0631\u0647 \u0648\u0646\u0647\u064a\u0647.","5:39":"\u0641\u0645\u0646 \u062a\u0627\u0628 \u0645\u0650\u0646 \u0628\u0639\u062f \u0633\u0631\u0642\u062a\u0647\u060c \u0648\u0623\u0635\u0644\u062d \u0641\u064a \u0643\u0644 \u0623\u0639\u0645\u0627\u0644\u0647\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u0642\u0628\u0644 \u062a\u0648\u0628\u062a\u0647. \u0625\u0646 \u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0644\u0639\u0628\u0627\u062f\u0647\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","5:40":"\u0623\u0644\u0645 \u062a\u0639\u0644\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0623\u0646 \u0627\u0644\u0644\u0647 \u062e\u0627\u0644\u0642 \u0627\u0644\u0643\u0648\u0646 \u0648\u0645\u064f\u062f\u0628\u0651\u0650\u0631\u0647 \u0648\u0645\u0627\u0644\u0643\u0647\u060c \u0648\u0623\u0646\u0647 \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0641\u0639\u0651\u064e\u0627\u0644 \u0644\u0645\u0627 \u064a\u0631\u064a\u062f\u060c \u064a\u0639\u0630\u0628 \u0645\u0646 \u064a\u0634\u0627\u0621\u060c \u0648\u064a\u063a\u0641\u0631 \u0644\u0645\u0646 \u064a\u0634\u0627\u0621\u060c \u0648\u0647\u0648 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621 \u0642\u062f\u064a\u0631.","5:41":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644 \u0644\u0627 \u064a\u062d\u0632\u0646\u0643 \u0627\u0644\u0630\u064a\u0646 \u064a\u0633\u0627\u0631\u0639\u0648\u0646 \u0641\u064a \u062c\u062d\u0648\u062f \u0646\u0628\u0648\u062a\u0643 \u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0623\u0638\u0647\u0631\u0648\u0627 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0642\u0644\u0648\u0628\u0647\u0645 \u062e\u0627\u0644\u064a\u0629 \u0645\u0646\u0647\u060c \u0641\u0625\u0646\u064a \u0646\u0627\u0635\u0631\u0643 \u0639\u0644\u064a\u0647\u0645. \u0648\u0644\u0627 \u064a\u062d\u0632\u0646\u0643 \u062a\u0633\u0631\u0651\u064f\u0639 \u0627\u0644\u064a\u0647\u0648\u062f \u0625\u0644\u0649 \u0625\u0646\u0643\u0627\u0631 \u0646\u0628\u0648\u062a\u0643\u060c \u0641\u0625\u0646\u0647\u0645 \u0642\u0648\u0645 \u064a\u0633\u062a\u0645\u0639\u0648\u0646 \u0644\u0644\u0643\u0630\u0628\u060c \u0648\u064a\u0642\u0628\u0644\u0648\u0646 \u0645\u0627 \u064a\u064e\u0641\u0652\u062a\u064e\u0631\u064a\u0647 \u0623\u062d\u0628\u0627\u0631\u064f\u0647\u0645\u060c \u0648\u064a\u0633\u062a\u062c\u064a\u0628\u0648\u0646 \u0644\u0642\u0648\u0645 \u0622\u062e\u0631\u064a\u0646 \u0644\u0627 \u064a\u062d\u0636\u0631\u0648\u0646 \u0645\u062c\u0644\u0633\u0643\u060c \u0648\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0622\u062e\u0631\u0648\u0646 \u064a\u064f\u0628\u064e\u062f\u0651\u0650\u0644\u0648\u0646 \u0643\u0644\u0627\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0628\u0639\u062f \u0645\u0627 \u0639\u064e\u0642\u064e\u0644\u0648\u0647\u060c \u0648\u064a\u0642\u0648\u0644\u0648\u0646: \u0625\u0646 \u062c\u0627\u0621\u0643\u0645 \u0645\u0646 \u0645\u062d\u0645\u062f \u0645\u0627 \u064a\u0648\u0627\u0641\u0642 \u0627\u0644\u0630\u064a \u0628\u062f\u0651\u064e\u0644\u0646\u0627\u0647 \u0648\u062d\u0631\u0651\u064e\u0641\u0646\u0627\u0647 \u0645\u0646 \u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0641\u0627\u0639\u0645\u0644\u0648\u0627 \u0628\u0647\u060c \u0648\u0625\u0646 \u062c\u0627\u0621\u0643\u0645 \u0645\u0646\u0647 \u0645\u0627 \u064a\u062e\u0627\u0644\u0641\u0647 \u0641\u0627\u062d\u0630\u0631\u0648\u0627 \u0642\u0628\u0648\u0644\u0647\u060c \u0648\u0627\u0644\u0639\u0645\u0644 \u0628\u0647. \u0648\u0645\u0646 \u064a\u0634\u0623 \u0627\u0644\u0644\u0647 \u0636\u0644\u0627\u0644\u062a\u0647 \u0641\u0644\u0646 \u062a\u0633\u062a\u0637\u064a\u0639 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u062f\u064e\u0641\u0652\u0639\u064e \u0630\u0644\u0643 \u0639\u0646\u0647\u060c \u0648\u0644\u0627 \u062a\u0642\u062f\u0631 \u0639\u0644\u0649 \u0647\u062f\u0627\u064a\u062a\u0647. \u0648\u0625\u0646\u0651\u064e \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0648\u0627\u0644\u064a\u0647\u0648\u062f \u0644\u0645 \u064a\u064f\u0631\u0650\u062f\u0650 \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u0637\u0647\u0651\u0650\u0631 \u0642\u0644\u0648\u0628\u0647\u0645 \u0645\u0646 \u062f\u0646\u0633 \u0627\u0644\u0643\u0641\u0631\u060c \u0644\u0647\u0645 \u0627\u0644\u0630\u0644\u0651\u064f \u0648\u0627\u0644\u0641\u0636\u064a\u062d\u0629 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0639\u0630\u0627\u0628 \u0639\u0638\u064a\u0645.","5:42":"\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u064a\u0647\u0648\u062f \u064a\u062c\u0645\u0639\u0648\u0646 \u0628\u064a\u0646 \u0627\u0633\u062a\u0645\u0627\u0639 \u0627\u0644\u0643\u0630\u0628 \u0648\u0623\u0643\u0644 \u0627\u0644\u062d\u0631\u0627\u0645\u060c \u0641\u0625\u0646 \u062c\u0627\u0624\u0648\u0643 \u064a\u062a\u062d\u0627\u0643\u0645\u0648\u0646 \u0625\u0644\u064a\u0643 \u0641\u0627\u0642\u0636 \u0628\u064a\u0646\u0647\u0645\u060c \u0623\u0648 \u0627\u062a\u0631\u0643\u0647\u0645\u060c \u0641\u0625\u0646 \u0644\u0645 \u062a\u062d\u0643\u0645 \u0628\u064a\u0646\u0647\u0645 \u0641\u0644\u0646 \u064a\u0642\u062f\u0631\u0648\u0627 \u0639\u0644\u0649 \u0623\u0646 \u064a\u0636\u0631\u0648\u0643 \u0628\u0634\u064a\u0621\u060c \u0648\u0625\u0646 \u062d\u0643\u0645\u062a \u0641\u0627\u062d\u0643\u0645 \u0628\u064a\u0646\u0647\u0645 \u0628\u0627\u0644\u0639\u062f\u0644. \u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u062d\u0628 \u0627\u0644\u0639\u0627\u062f\u0644\u064a\u0646.","5:43":"\u0625\u0646\u0651\u064e \u0635\u0646\u064a\u0639 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u064a\u0647\u0648\u062f \u0639\u062c\u064a\u0628\u060c \u0641\u0647\u0645 \u064a\u062d\u062a\u0643\u0645\u0648\u0646 \u0625\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0648\u0647\u0645 \u0644\u0627 \u064a\u0624\u0645\u0646\u0648\u0646 \u0628\u0643\u060c \u0648\u0644\u0627 \u0628\u0643\u062a\u0627\u0628\u0643\u060c \u0645\u0639 \u0623\u0646 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0627\u0644\u062a\u064a \u064a\u0624\u0645\u0646\u0648\u0646 \u0628\u0647\u0627 \u0639\u0646\u062f\u0647\u0645\u060c \u0641\u064a\u0647\u0627 \u062d\u0643\u0645 \u0627\u0644\u0644\u0647\u060c \u062b\u0645 \u064a\u062a\u0648\u0644\u0651\u064e\u0648\u0646 \u0645\u0650\u0646 \u0628\u0639\u062f \u062d\u0643\u0645\u0643 \u0625\u0630\u0627 \u0644\u0645 \u064a\u064f\u0631\u0636\u0647\u0645\u060c \u0641\u062c\u0645\u0639\u0648\u0627 \u0628\u064a\u0646 \u0627\u0644\u0643\u0641\u0631 \u0628\u0634\u0631\u0639\u0647\u0645\u060c \u0648\u0627\u0644\u0625\u0639\u0631\u0627\u0636 \u0639\u0646 \u062d\u0643\u0645\u0643\u060c \u0648\u0644\u064a\u0633 \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0645\u062a\u0635\u0641\u0648\u0646 \u0628\u062a\u0644\u0643 \u0627\u0644\u0635\u0641\u0627\u062a\u060c \u0628\u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0628\u0643 \u0648\u0628\u0645\u0627 \u062a\u062d\u0643\u0645 \u0628\u0647.","5:44":"\u0625\u0646\u0627 \u0623\u0646\u0632\u0644\u0646\u0627 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0641\u064a\u0647\u0627 \u0625\u0631\u0634\u0627\u062f \u0645\u0646 \u0627\u0644\u0636\u0644\u0627\u0644\u0629\u060c \u0648\u0628\u064a\u0627\u0646 \u0644\u0644\u0623\u062d\u0643\u0627\u0645\u060c \u0648\u0642\u062f \u062d\u0643\u0645 \u0628\u0647\u0627 \u0627\u0644\u0646\u0628\u064a\u0651\u064f\u0648\u0646 -\u0627\u0644\u0630\u064a\u0646 \u0627\u0646\u0642\u0627\u062f\u0648\u0627 \u0644\u062d\u0643\u0645 \u0627\u0644\u0644\u0647\u060c \u0648\u0623\u0642\u0631\u0648\u0627 \u0628\u0647- \u0628\u064a\u0646 \u0627\u0644\u064a\u0647\u0648\u062f\u060c \u0648\u0644\u0645 \u064a\u062e\u0631\u062c\u0648\u0627 \u0639\u0646 \u062d\u0643\u0645\u0647\u0627 \u0648\u0644\u0645 \u064a\u064f\u062d\u064e\u0631\u0651\u0650\u0641\u0648\u0647\u0627\u060c \u0648\u062d\u0643\u0645 \u0628\u0647\u0627 \u0639\u064f\u0628\u0651\u064e\u0627\u062f \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0641\u0642\u0647\u0627\u0624\u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u064a\u0631\u0628\u0651\u064f\u0648\u0646 \u0627\u0644\u0646\u0627\u0633 \u0628\u0634\u0631\u0639 \u0627\u0644\u0644\u0647; \u0630\u0644\u0643 \u0623\u0646 \u0623\u0646\u0628\u064a\u0627\u0621\u0647\u0645 \u0642\u062f \u0627\u0633\u062a\u0623\u0645\u0646\u0648\u0647\u0645 \u0639\u0644\u0649 \u062a\u0628\u0644\u064a\u063a \u0627\u0644\u062a\u0648\u0631\u0627\u0629\u060c \u0648\u0641\u0650\u0642\u0652\u0647 \u0643\u062a\u0627\u0628 \u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u0639\u0645\u0644 \u0628\u0647\u060c \u0648\u0643\u0627\u0646 \u0627\u0644\u0631\u0628\u0627\u0646\u064a\u0648\u0646 \u0648\u0627\u0644\u0623\u062d\u0628\u0627\u0631 \u0634\u0647\u062f\u0627\u0621 \u0639\u0644\u0649 \u0623\u0646 \u0623\u0646\u0628\u064a\u0627\u0621\u0647\u0645 \u0642\u062f \u0642\u0636\u0648\u0627 \u0641\u064a \u0627\u0644\u064a\u0647\u0648\u062f \u0628\u0643\u062a\u0627\u0628 \u0627\u0644\u0644\u0647. \u0648\u064a\u0642\u0648\u0644 \u062a\u0639\u0627\u0644\u0649 \u0644\u0639\u0644\u0645\u0627\u0621 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0623\u062d\u0628\u0627\u0631\u0647\u0645: \u0641\u0644\u0627 \u062a\u062e\u0634\u0648\u0627 \u0627\u0644\u0646\u0627\u0633 \u0641\u064a \u062a\u0646\u0641\u064a\u0630 \u062d\u0643\u0645\u064a; \u0641\u0625\u0646\u0647\u0645 \u0644\u0627 \u064a\u0642\u062f\u0631\u0648\u0646 \u0639\u0644\u0649 \u0646\u0641\u0639\u0643\u0645 \u0648\u0644\u0627 \u0636\u064e\u0631\u0651\u0650\u0643\u0645\u060c \u0648\u0644\u0643\u0646 \u0627\u062e\u0634\u0648\u0646\u064a \u0641\u0625\u0646\u064a \u0623\u0646\u0627 \u0627\u0644\u0646\u0627\u0641\u0639 \u0627\u0644\u0636\u0627\u0631\u060c \u0648\u0644\u0627 \u062a\u0623\u062e\u0630\u0648\u0627 \u0628\u062a\u0631\u0643 \u0627\u0644\u062d\u0643\u0645 \u0628\u0645\u0627 \u0623\u0646\u0632\u0644\u062a\u064f \u0639\u0648\u0636\u064b\u0627 \u062d\u0642\u064a\u0631\u064b\u0627. \u0641\u0627\u0644\u062d\u0643\u0645 \u0628\u063a\u064a\u0631 \u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0623\u0639\u0645\u0627\u0644 \u0623\u0647\u0644 \u0627\u0644\u0643\u0641\u0631\u060c \u0641\u0627\u0644\u0630\u064a\u0646 \u064a\u0628\u062f\u0644\u0648\u0646 \u062d\u0643\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644\u0647 \u0641\u064a \u0643\u062a\u0627\u0628\u0647\u060c \u0641\u064a\u0643\u062a\u0645\u0648\u0646\u0647 \u0648\u064a\u062c\u062d\u062f\u0648\u0646\u0647 \u0648\u064a\u062d\u0643\u0645\u0648\u0646 \u0628\u063a\u064a\u0631\u0647 \u0645\u0639\u062a\u0642\u062f\u064a\u0646 \u062d\u0644\u0647 \u0648\u062c\u0648\u0627\u0632\u0647 \u0641\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u0643\u0627\u0641\u0631\u0648\u0646.","5:45":"\u0648\u0641\u064e\u0631\u064e\u0636\u0646\u0627 \u0639\u0644\u064a\u0647\u0645 \u0641\u064a \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0623\u0646 \u0627\u0644\u0646\u0641\u0633 \u062a\u064f\u0642\u0652\u062a\u064e\u0644 \u0628\u0627\u0644\u0646\u0641\u0633\u060c \u0648\u0627\u0644\u0639\u064a\u0646 \u062a\u064f\u0641\u0652\u0642\u064e\u0623 \u0628\u0627\u0644\u0639\u064a\u0646\u060c \u0648\u0627\u0644\u0623\u0646\u0641 \u064a\u064f\u062c\u0652\u062f\u064e\u0639 \u0628\u0627\u0644\u0623\u0646\u0641\u060c \u0648\u0627\u0644\u0623\u0630\u064f\u0646 \u062a\u064f\u0642\u0652\u0637\u0639 \u0628\u0627\u0644\u0623\u0630\u064f\u0646\u060c \u0648\u0627\u0644\u0633\u0646\u0651\u064e \u062a\u064f\u0642\u0652\u0644\u064e\u0639\u064f \u0628\u0627\u0644\u0633\u0646\u0651\u0650\u060c \u0648\u0623\u0646\u0651\u064e\u0647 \u064a\u064f\u0642\u0652\u062a\u064e\u0635\u0651\u064f \u0641\u064a \u0627\u0644\u062c\u0631\u0648\u062d\u060c \u0641\u0645\u0646 \u062a\u062c\u0627\u0648\u0632 \u0639\u0646 \u062d\u0642\u0647 \u0641\u064a \u0627\u0644\u0627\u0642\u062a\u0635\u0627\u0635 \u0645\u0646 \u0627\u0644\u0645\u064f\u0639\u062a\u062f\u064a \u0641\u0630\u0644\u0643 \u062a\u0643\u0641\u064a\u0631 \u0644\u0628\u0639\u0636 \u0630\u0646\u0648\u0628 \u0627\u0644\u0645\u0639\u062a\u062f\u0649 \u0639\u0644\u064a\u0647 \u0648\u0625\u0632\u0627\u0644\u0629\u064c \u0644\u0647\u0627. \u0648\u0645\u0646 \u0644\u0645 \u064a\u062d\u0643\u0645 \u0628\u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u0642\u0635\u0627\u0635 \u0648\u063a\u064a\u0631\u0647\u060c \u0641\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u0645\u062a\u062c\u0627\u0648\u0632\u0648\u0646 \u062d\u062f\u0648\u062f \u0627\u0644\u0644\u0647.","5:46":"\u0648\u0623\u062a\u0628\u0639\u0646\u0627 \u0623\u0646\u0628\u064a\u0627\u0621 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0639\u064a\u0633\u0649 \u0628\u0646 \u0645\u0631\u064a\u0645 \u0645\u0624\u0645\u0646\u064b\u0627 \u0628\u0645\u0627 \u0641\u064a \u0627\u0644\u062a\u0648\u0631\u0627\u0629\u060c \u0639\u0627\u0645\u0644\u0627 \u0628\u0645\u0627 \u0641\u064a\u0647\u0627 \u0645\u0645\u0627 \u0644\u0645 \u064a\u0646\u0633\u062e\u0647 \u0643\u062a\u0627\u0628\u0647\u060c \u0648\u0623\u0646\u0632\u0644\u0646\u0627 \u0625\u0644\u064a\u0647 \u0627\u0644\u0625\u0646\u062c\u064a\u0644 \u0647\u0627\u062f\u064a\u0627 \u0625\u0644\u0649 \u0627\u0644\u062d\u0642\u060c \u0648\u0645\u0628\u064a\u0651\u0650\u0646\u064b\u0627 \u0644\u0645\u0627 \u062c\u0647\u0644\u0647 \u0627\u0644\u0646\u0627\u0633 \u0645\u0650\u0646 \u062d\u0643\u0645 \u0627\u0644\u0644\u0647\u060c \u0648\u0634\u0627\u0647\u062f\u064b\u0627 \u0639\u0644\u0649 \u0635\u062f\u0642 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0628\u0645\u0627 \u0627\u0634\u062a\u0645\u0644 \u0639\u0644\u064a\u0647 \u0645\u0646 \u0623\u062d\u0643\u0627\u0645\u0647\u0627\u060c \u0648\u0642\u062f \u062c\u0639\u0644\u0646\u0627\u0647 \u0628\u064a\u0627\u0646\u064b\u0627 \u0644\u0644\u0630\u064a\u0646 \u064a\u062e\u0627\u0641\u0648\u0646 \u0627\u0644\u0644\u0647 \u0648\u0632\u0627\u062c\u0631\u064b\u0627 \u0644\u0647\u0645 \u0639\u0646 \u0627\u0631\u062a\u0643\u0627\u0628 \u0627\u0644\u0645\u062d\u0631\u0651\u064e\u0645\u0627\u062a.","5:47":"\u0648\u0644\u064a\u062d\u0643\u0645 \u0623\u0647\u0644 \u0627\u0644\u0625\u0646\u062c\u064a\u0644 \u0627\u0644\u0630\u064a\u0646 \u0623\u064f\u0631\u0633\u0650\u0644 \u0625\u0644\u064a\u0647\u0645 \u0639\u064a\u0633\u0649 \u0628\u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0641\u064a\u0647. \u0648\u0645\u0646 \u0644\u0645 \u064a\u062d\u0643\u0645 \u0628\u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0641\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u062e\u0627\u0631\u062c\u0648\u0646 \u0639\u0646 \u0623\u0645\u0631\u0647\u060c \u0627\u0644\u0639\u0627\u0635\u0648\u0646 \u0644\u0647.","5:48":"\u0648\u0623\u0646\u0632\u0644\u0646\u0627 \u0625\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0648\u0643\u0644 \u0645\u0627 \u0641\u064a\u0647 \u062d\u0642\u0651 \u064a\u0634\u0647\u062f \u0639\u0644\u0649 \u0635\u062f\u0642 \u0627\u0644\u0643\u062a\u0628 \u0642\u0628\u0644\u0647\u060c \u0648\u0623\u0646\u0647\u0627 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0645\u0635\u062f\u0642\u064b\u0627 \u0644\u0645\u0627 \u0641\u064a\u0647\u0627 \u0645\u0646 \u0635\u062d\u0629\u060c \u0648\u0645\u0628\u064a\u0651\u0650\u0646\u064b\u0627 \u0644\u0645\u0627 \u0641\u064a\u0647\u0627 \u0645\u0646 \u062a\u062d\u0631\u064a\u0641\u060c \u0646\u0627\u0633\u062e\u064b\u0627 \u0644\u0628\u0639\u0636 \u0634\u0631\u0627\u0626\u0639\u0647\u0627\u060c \u0641\u0627\u062d\u0643\u0645 \u0628\u064a\u0646 \u0627\u0644\u0645\u062d\u062a\u0643\u0645\u064a\u0646 \u0625\u0644\u064a\u0643 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0628\u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0625\u0644\u064a\u0643 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0648\u0644\u0627 \u062a\u0646\u0635\u0631\u0641 \u0639\u0646 \u0627\u0644\u062d\u0642 \u0627\u0644\u0630\u064a \u0623\u0645\u0631\u0643 \u0627\u0644\u0644\u0647 \u0628\u0647 \u0625\u0644\u0649 \u0623\u0647\u0648\u0627\u0626\u0647\u0645 \u0648\u0645\u0627 \u0627\u0639\u062a\u0627\u062f\u0648\u0647\u060c \u0641\u0642\u062f \u062c\u0639\u0644\u0646\u0627 \u0644\u0643\u0644 \u0623\u0645\u0629 \u0634\u0631\u064a\u0639\u0629\u060c \u0648\u0637\u0631\u064a\u0642\u0629 \u0648\u0627\u0636\u062d\u0629 \u064a\u0639\u0645\u0644\u0648\u0646 \u0628\u0647\u0627. \u0648\u0644\u0648 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u0644\u062c\u0639\u0644 \u0634\u0631\u0627\u0626\u0639\u0643\u0645 \u0648\u0627\u062d\u062f\u0629\u060c \u0648\u0644\u0643\u0646\u0647 \u062a\u0639\u0627\u0644\u0649 \u062e\u0627\u0644\u0641 \u0628\u064a\u0646\u0647\u0627 \u0644\u064a\u062e\u062a\u0628\u0631\u0643\u0645\u060c \u0641\u064a\u0638\u0647\u0631 \u0627\u0644\u0645\u0637\u064a\u0639 \u0645\u0646 \u0627\u0644\u0639\u0627\u0635\u064a\u060c \u0641\u0633\u0627\u0631\u0639\u0648\u0627 \u0625\u0644\u0649 \u0645\u0627 \u0647\u0648 \u062e\u064a\u0631 \u0644\u0643\u0645 \u0641\u064a \u0627\u0644\u062f\u0627\u0631\u064a\u0646 \u0628\u0627\u0644\u0639\u0645\u0644 \u0628\u0645\u0627 \u0641\u064a \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0641\u0625\u0646 \u0645\u0635\u064a\u0631\u0643\u0645 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0641\u064a\u062e\u0628\u0631\u0643\u0645 \u0628\u0645\u0627 \u0643\u0646\u062a\u0645 \u0641\u064a\u0647 \u062a\u062e\u062a\u0644\u0641\u0648\u0646\u060c \u0648\u064a\u062c\u0632\u064a \u0643\u0644\u0627 \u0628\u0639\u0645\u0644\u0647.","5:49":"\u0648\u0627\u062d\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0628\u064a\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0628\u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0625\u0644\u064a\u0643 \u0641\u064a \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0648\u0644\u0627 \u062a\u062a\u0628\u0639 \u0623\u0647\u0648\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u064a\u062d\u062a\u0643\u0645\u0648\u0646 \u0625\u0644\u064a\u0643\u060c \u0648\u0627\u062d\u0630\u0631\u0647\u0645 \u0623\u0646 \u064a\u0635\u062f\u0651\u064f\u0648\u0643 \u0639\u0646 \u0628\u0639\u0636 \u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0625\u0644\u064a\u0643 \u0641\u062a\u062a\u0631\u0643 \u0627\u0644\u0639\u0645\u0644 \u0628\u0647\u060c \u0641\u0625\u0646 \u0623\u0639\u0631\u0636 \u0647\u0624\u0644\u0627\u0621 \u0639\u0645\u0651\u064e\u0627 \u062a\u062d\u0643\u0645 \u0628\u0647 \u0641\u0627\u0639\u0644\u0645 \u0623\u0646 \u0627\u0644\u0644\u0647 \u064a\u0631\u064a\u062f \u0623\u0646 \u064a\u0635\u0631\u0641\u0647\u0645 \u0639\u0646 \u0627\u0644\u0647\u062f\u0649 \u0628\u0633\u0628\u0628 \u0630\u0646\u0648\u0628\u064d \u0627\u0643\u062a\u0633\u0628\u0648\u0647\u0627 \u0645\u0646 \u0642\u0628\u0644. \u0648\u0625\u0646 \u0643\u062b\u064a\u0631\u064b\u0627 \u0645\u0646 \u0627\u0644\u0646\u0627\u0633 \u0644\u064e\u062e\u0627\u0631\u062c\u0648\u0646 \u0639\u0646 \u0637\u0627\u0639\u0629 \u0631\u0628\u0647\u0645.","5:50":"\u0623\u064a\u0631\u064a\u062f \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u064a\u0647\u0648\u062f \u0623\u0646 \u062a\u062d\u0643\u0645 \u0628\u064a\u0646\u0647\u0645 \u0628\u0645\u0627 \u062a\u0639\u0627\u0631\u0641 \u0639\u0644\u064a\u0647 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0639\u0628\u062f\u0629\u064f \u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u0645\u0646 \u0627\u0644\u0636\u0644\u0627\u0644\u0627\u062a \u0648\u0627\u0644\u062c\u0647\u0627\u0644\u0627\u062a\u061f! \u0644\u0627 \u064a\u0643\u0648\u0646 \u0630\u0644\u0643 \u0648\u0644\u0627 \u064a\u0644\u064a\u0642 \u0623\u0628\u062f\u064b\u0627 \u0648\u0645\u064e\u0646 \u0623\u0639\u062f\u0644 \u0645\u0650\u0646 \u0627\u0644\u0644\u0647 \u0641\u064a \u062d\u0643\u0645\u0647 \u0644\u0645\u0646 \u0639\u0642\u0644 \u0639\u0646 \u0627\u0644\u0644\u0647 \u0634\u064e\u0631\u0652\u0639\u0647\u060c \u0648\u0622\u0645\u0646 \u0628\u0647\u060c \u0648\u0623\u064a\u0642\u0646 \u0623\u0646 \u062d\u0643\u0645 \u0627\u0644\u0644\u0647 \u0647\u0648 \u0627\u0644\u062d\u0642\u061f","5:51":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0644\u0627 \u062a\u062a\u062e\u0630\u0648\u0627 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u062d\u0644\u0641\u0627\u0621\u064e \u0648\u0623\u0646\u0635\u0627\u0631\u064b\u0627 \u0639\u0644\u0649 \u0623\u0647\u0644 \u0627\u0644\u0625\u064a\u0645\u0627\u0646; \u0630\u0644\u0643 \u0623\u0646\u0647\u0645 \u0644\u0627 \u064a\u064f\u0648\u0627\u062f\u0651\u064f\u0648\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0641\u0627\u0644\u064a\u0647\u0648\u062f \u064a\u0648\u0627\u0644\u064a \u0628\u0639\u0636\u0647\u0645 \u0628\u0639\u0636\u064b\u0627\u060c \u0648\u0643\u0630\u0644\u0643 \u0627\u0644\u0646\u0635\u0627\u0631\u0649\u060c \u0648\u0643\u0644\u0627 \u0627\u0644\u0641\u0631\u064a\u0642\u064a\u0646 \u064a\u062c\u062a\u0645\u0639 \u0639\u0644\u0649 \u0639\u062f\u0627\u0648\u062a\u0643\u0645. \u0648\u0623\u0646\u062a\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0623\u062c\u062f\u0631\u064f \u0628\u0623\u0646 \u064a\u0646\u0635\u0631 \u0628\u0639\u0636\u064f\u0643\u0645 \u0628\u0639\u0636\u064b\u0627. \u0648\u0645\u0646 \u064a\u062a\u0648\u0644\u0647\u0645 \u0645\u0646\u0643\u0645 \u0641\u0625\u0646\u0647 \u064a\u0635\u064a\u0631 \u0645\u0646 \u062c\u0645\u0644\u062a\u0647\u0645\u060c \u0648\u062d\u0643\u0645\u0647 \u062d\u0643\u0645\u0647\u0645. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0648\u0641\u0642 \u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u062a\u0648\u0644\u0648\u0646 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646.","5:52":"\u064a\u062e\u0628\u0631 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0646 \u062c\u0645\u0627\u0639\u0629 \u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0623\u0646\u0647\u0645 \u0643\u0627\u0646\u0648\u0627 \u064a\u0628\u0627\u062f\u0631\u0648\u0646 \u0641\u064a \u0645\u0648\u0627\u062f\u0629 \u0627\u0644\u064a\u0647\u0648\u062f \u0644\u0645\u0627 \u0641\u064a \u0642\u0644\u0648\u0628\u0647\u0645 \u0645\u0646 \u0627\u0644\u0634\u0643\u0651\u0650 \u0648\u0627\u0644\u0646\u0641\u0627\u0642\u060c \u0648\u064a\u0642\u0648\u0644\u0648\u0646: \u0625\u0646\u0645\u0627 \u0646\u0648\u0627\u062f\u0651\u064f\u0647\u0645 \u062e\u0634\u064a\u0629 \u0623\u0646 \u064a\u0638\u0641\u0631\u0648\u0627 \u0628\u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0641\u064a\u0635\u064a\u0628\u0648\u0646\u0627 \u0645\u0639\u0647\u0645\u060c \u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0630\u0643\u0631\u0647: \u0641\u0639\u0633\u0649 \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u0623\u062a\u064a \u0628\u0627\u0644\u0641\u062a\u062d -\u0623\u064a \u0641\u062a\u062d \xab\u0645\u0643\u0629\xbb - \u0648\u064a\u0646\u0635\u0631 \u0646\u064e\u0628\u0650\u064a\u0651\u064e\u0647\u060c \u0648\u064a\u064f\u0638\u0652\u0647\u0650\u0631 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0643\u0641\u0627\u0631\u060c \u0623\u0648 \u064a\u064f\u0647\u064a\u0651\u0650\u0626 \u0645\u0646 \u0627\u0644\u0623\u0645\u0648\u0631 \u0645\u0627 \u062a\u0630\u0647\u0628 \u0628\u0647 \u0642\u0648\u0629\u064f \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0651\u064e\u0635\u0627\u0631\u0649\u060c \u0641\u064a\u062e\u0636\u0639\u0648\u0627 \u0644\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0641\u062d\u064a\u0646\u0626\u0630\u064d \u064a\u0646\u062f\u0645 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0639\u0644\u0649 \u0645\u0627 \u0623\u0636\u0645\u0631\u0648\u0627 \u0641\u064a \u0623\u0646\u0641\u0633\u0647\u0645 \u0645\u0646 \u0645\u0648\u0627\u0644\u0627\u062a\u0647\u0645.","5:53":"\u0648\u062d\u064a\u0646\u0626\u0630 \u064a\u0642\u0648\u0644 \u0628\u0639\u0636 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0644\u0628\u0639\u0636\u064d \u0645\u064f\u062a\u0639\u062c\u0651\u0650\u0628\u064a\u0646 \u0645\u0646 \u062d\u0627\u0644 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 -\u0625\u0630\u0627 \u0643\u064f\u0634\u0650\u0641 \u0623\u0645\u0631\u0647\u0645-: \u0623\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u0623\u0642\u0633\u0645\u0648\u0627 \u0628\u0623\u063a\u0644\u0638 \u0627\u0644\u0623\u064a\u0645\u0627\u0646 \u0625\u0646\u0647\u0645 \u0644\u064e\u0645\u064e\u0639\u064e\u0646\u0627\u061f! \u0628\u0637\u0644\u062a \u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0627\u0644\u062a\u064a \u0639\u0645\u0644\u0648\u0647\u0627 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0641\u0644\u0627 \u062b\u0648\u0627\u0628 \u0644\u0647\u0645 \u0639\u0644\u064a\u0647\u0627; \u0644\u0623\u0646\u0647\u0645 \u0639\u0645\u0644\u0648\u0647\u0627 \u0639\u0644\u0649 \u063a\u064a\u0631 \u0625\u064a\u0645\u0627\u0646\u060c \u0641\u062e\u0633\u0631\u0648\u0627 \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629.","5:54":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647 \u0645\u0646 \u064a\u0631\u062c\u0639 \u0645\u0646\u0643\u0645 \u0639\u0646 \u062f\u064a\u0646\u0647\u060c \u0648\u064a\u0633\u062a\u0628\u062f\u0644 \u0628\u0647 \u0627\u0644\u064a\u0647\u0648\u062f\u064a\u0629 \u0623\u0648 \u0627\u0644\u0646\u0635\u0631\u0627\u0646\u064a\u0629 \u0623\u0648 \u063a\u064a\u0631 \u0630\u0644\u0643\u060c \u0641\u0644\u0646 \u064a\u0636\u0631\u0651\u064f\u0648\u0627 \u0627\u0644\u0644\u0647 \u0634\u064a\u0626\u064b\u0627\u060c \u0648\u0633\u0648\u0641 \u064a\u0623\u062a\u064a \u0627\u0644\u0644\u0647 \u0628\u0642\u0648\u0645 \u062e\u064a\u0631 \u0645\u0646\u0647\u0645 \u064a\u064f\u062d\u0650\u0628\u0651\u064f\u0647\u0645 \u0648\u064a\u062d\u0628\u0648\u0646\u0647\u060c \u0631\u062d\u0645\u0627\u0621 \u0628\u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0623\u0634\u062f\u0651\u064e\u0627\u0621 \u0639\u0644\u0649 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646\u060c \u064a\u062c\u0627\u0647\u062f\u0648\u0646 \u0623\u0639\u062f\u0627\u0621 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u064a\u062e\u0627\u0641\u0648\u0646 \u0641\u064a \u0630\u0627\u062a \u0627\u0644\u0644\u0647 \u0623\u062d\u062f\u064b\u0627. \u0630\u0644\u0643 \u0627\u0644\u0625\u0646\u0639\u0627\u0645 \u0645\u0650\u0646 \u0641\u0636\u0644 \u0627\u0644\u0644\u0647 \u064a\u0624\u062a\u064a\u0647 \u0645\u0646 \u0623\u0631\u0627\u062f\u060c \u0648\u0627\u0644\u0644\u0647 \u0648\u0627\u0633\u0639 \u0627\u0644\u0641\u0636\u0644\u060c \u0639\u0644\u064a\u0645 \u0628\u0645\u0646 \u064a\u0633\u062a\u062d\u0642\u0647 \u0645\u0646 \u0639\u0628\u0627\u062f\u0647.","5:55":"\u0625\u0646\u0645\u0627 \u0646\u0627\u0635\u0631\u0643\u0645 -\u0623\u064a\u0651\u064f\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u062d\u0627\u0641\u0638\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0635\u0644\u0627\u0629 \u0627\u0644\u0645\u0641\u0631\u0648\u0636\u0629\u060c \u0648\u064a\u0624\u062f\u0648\u0646 \u0627\u0644\u0632\u0643\u0627\u0629 \u0639\u0646 \u0631\u0636\u0627 \u0646\u0641\u0633\u060c \u0648\u0647\u0645 \u062e\u0627\u0636\u0639\u0648\u0646 \u0644\u0644\u0647.","5:56":"\u0648\u0645\u0646 \u0648\u062b\u0642 \u0628\u0627\u0644\u0644\u0647 \u0648\u062a\u0648\u0644\u0651\u064e\u0649 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0641\u0647\u0648 \u0645\u0646 \u062d\u0632\u0628 \u0627\u0644\u0644\u0647\u060c \u0648\u062d\u0632\u0628 \u0627\u0644\u0644\u0647 \u0647\u0645 \u0627\u0644\u063a\u0627\u0644\u0628\u0648\u0646 \u0627\u0644\u0645\u0646\u062a\u0635\u0631\u0648\u0646.","5:57":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0644\u0627 \u062a\u062a\u062e\u0630\u0648\u0627 \u0627\u0644\u0630\u064a\u0646 \u064a\u0633\u062a\u0647\u0632\u0626\u0648\u0646 \u0648\u064a\u062a\u0644\u0627\u0639\u0628\u0648\u0646 \u0628\u062f\u064a\u0646\u0643\u0645 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0648\u0627\u0644\u0643\u0641\u0627\u0631\u064e \u0623\u0648\u0644\u064a\u0627\u0621\u064e\u060c \u0648\u062e\u0627\u0641\u0648\u0627 \u0627\u0644\u0644\u0647 \u0625\u0646 \u0643\u0646\u062a\u0645 \u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u0647 \u0648\u0628\u0634\u0631\u0639\u0647.","5:58":"\u0648\u0625\u0630\u0627 \u0623\u0630\u0651\u064e\u0646 \u0645\u0624\u0630\u0646\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0628\u0627\u0644\u0635\u0644\u0627\u0629 \u0633\u062e\u0631 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0648\u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0648\u0627\u0633\u062a\u0647\u0632\u0624\u0648\u0627 \u0645\u0646 \u062f\u0639\u0648\u062a\u0643\u0645 \u0625\u0644\u064a\u0647\u0627\u061b \u0648\u0630\u0644\u0643 \u0628\u0633\u0628\u0628 \u062c\u0647\u0644\u0647\u0645 \u0628\u0631\u0628\u0647\u0645\u060c \u0648\u0623\u0646\u0647\u0645 \u0644\u0627 \u064a\u0639\u0642\u0644\u0648\u0646 \u062d\u0642\u064a\u0642\u0629 \u0627\u0644\u0639\u0628\u0627\u062f\u0629.","5:59":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0633\u062a\u0647\u0632\u0626\u064a\u0646 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628: \u0645\u0627 \u062a\u064e\u062c\u0650\u062f\u064f\u0648\u0646\u0647 \u0645\u0637\u0639\u0646\u064b\u0627 \u0623\u0648 \u0639\u064a\u0628\u064b\u0627 \u0647\u0648 \u0645\u062d\u0645\u062f\u0629 \u0644\u0646\u0627: \u0645\u0646 \u0625\u064a\u0645\u0627\u0646\u0646\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0643\u062a\u0628\u0647 \u0627\u0644\u0645\u0646\u0632\u0644\u0629 \u0639\u0644\u064a\u0646\u0627\u060c \u0648\u0639\u0644\u0649 \u0645\u0646 \u0643\u0627\u0646 \u0642\u0628\u0644\u0646\u0627\u060c \u0648\u0625\u064a\u0645\u0627\u0646\u0646\u0627 \u0628\u0623\u0646 \u0623\u0643\u062b\u0631\u0643\u0645 \u062e\u0627\u0631\u062c\u0648\u0646 \u0639\u0646 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645!","5:60":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0644\u0644\u0645\u0624\u0645\u0646\u064a\u0646: \u0647\u0644 \u0623\u062e\u0628\u0631\u0643\u0645 \u0628\u0645\u0646 \u064a\u064f\u062c\u0627\u0632\u064e\u0649 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u062c\u0632\u0627\u0621\u064b \u0623\u0634\u062f\u0651\u064e \u0645\u0650\u0646 \u062c\u0632\u0627\u0621 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0641\u0627\u0633\u0642\u064a\u0646\u061f \u0625\u0646\u0647\u0645 \u0623\u0633\u0644\u0627\u0641\u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0637\u0631\u062f\u0647\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0631\u062d\u0645\u062a\u0647 \u0648\u063a\u064e\u0636\u0650\u0628 \u0639\u0644\u064a\u0647\u0645\u060c \u0648\u0645\u064e\u0633\u064e\u062e\u064e \u062e\u064e\u0644\u0652\u0642\u0647\u0645\u060c \u0641\u062c\u0639\u0644 \u0645\u0646\u0647\u0645 \u0627\u0644\u0642\u0631\u062f\u0629 \u0648\u0627\u0644\u062e\u0646\u0627\u0632\u064a\u0631\u060c \u0628\u0639\u0635\u064a\u0627\u0646\u0647\u0645 \u0648\u0627\u0641\u062a\u0631\u0627\u0626\u0647\u0645 \u0648\u062a\u0643\u0628\u0631\u0647\u0645\u060c \u0643\u0645\u0627 \u0643\u0627\u0646 \u0645\u0646\u0647\u0645 \u0639\u064f\u0628\u0651\u064e\u0627\u062f \u0627\u0644\u0637\u0627\u063a\u0648\u062a (\u0648\u0647\u0648 \u0643\u0644 \u0645\u0627 \u0639\u064f\u0628\u0650\u062f \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u0648\u0647\u0648 \u0631\u0627\u0636\u064d) \u060c \u0644\u0642\u062f \u0633\u0627\u0621 \u0645\u0643\u0627\u0646\u0647\u0645 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0636\u0644\u0651\u064e \u0633\u064e\u0639\u0652\u064a\u064f\u0647\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0639\u0646 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0635\u062d\u064a\u062d.","5:61":"\u0648\u0625\u0630\u0627 \u062c\u0627\u0621\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0645\u0646\u0627\u0641\u0642\u0648 \u0627\u0644\u064a\u0647\u0648\u062f\u060c \u0642\u0627\u0644\u0648\u0627: \u0622\u0645\u0646\u0651\u064e\u0627\u060c \u0648\u0647\u0645 \u0645\u0642\u064a\u0645\u0648\u0646 \u0639\u0644\u0649 \u0643\u0641\u0631\u0647\u0645\u060c \u0642\u062f \u062f\u062e\u0644\u0648\u0627 \u0639\u0644\u064a\u0643\u0645 \u0628\u0643\u0641\u0631\u0647\u0645 \u0627\u0644\u0630\u064a \u064a\u0639\u062a\u0642\u062f\u0648\u0646\u0647 \u0628\u0642\u0644\u0648\u0628\u0647\u0645\u060c \u062b\u0645 \u062e\u0631\u062c\u0648\u0627 \u0648\u0647\u0645 \u0645\u0635\u0631\u0651\u064f\u0648\u0646 \u0639\u0644\u064a\u0647\u060c \u0648\u0627\u0644\u0644\u0647 \u0623\u0639\u0644\u0645 \u0628\u0633\u0631\u0627\u0626\u0631\u0647\u0645\u060c \u0648\u0625\u0646 \u0623\u0638\u0647\u0631\u0648\u0627 \u062e\u0644\u0627\u0641 \u0630\u0644\u0643.","5:62":"\u0648\u062a\u0631\u0649 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0643\u062b\u064a\u0631\u064b\u0627 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u064a\u0628\u0627\u062f\u0631\u0648\u0646 \u0625\u0644\u0649 \u0627\u0644\u0645\u0639\u0627\u0635\u064a \u0645\u0646 \u0642\u0648\u0644 \u0627\u0644\u0643\u0630\u0628 \u0648\u0627\u0644\u0632\u0648\u0631\u060c \u0648\u0627\u0644\u0627\u0639\u062a\u062f\u0627\u0621 \u0639\u0644\u0649 \u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u0644\u0647\u060c \u0648\u0623\u0643\u0652\u0644 \u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u0646\u0627\u0633 \u0628\u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0644\u0642\u062f \u0633\u0627\u0621 \u0639\u0645\u0644\u0647\u0645 \u0648\u0627\u0639\u062a\u062f\u0627\u0624\u0647\u0645.","5:63":"\u0647\u0644\u0627 \u064a\u0646\u0647\u0649 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u064a\u0633\u0627\u0631\u0639\u0648\u0646 \u0641\u064a \u0627\u0644\u0625\u062b\u0645 \u0648\u0627\u0644\u0639\u062f\u0648\u0627\u0646 \u0623\u0626\u0645\u062a\u064f\u0647\u0645 \u0648\u0639\u0644\u0645\u0627\u0624\u0647\u0645\u060c \u0639\u0646 \u0642\u0648\u0644 \u0627\u0644\u0643\u0630\u0628 \u0648\u0627\u0644\u0632\u0648\u0631\u060c \u0648\u0623\u0643\u0644 \u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u0646\u0627\u0633 \u0628\u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0644\u0642\u062f \u0633\u0627\u0621 \u0635\u0646\u064a\u0639\u0647\u0645 \u062d\u064a\u0646 \u062a\u0631\u0643\u0648\u0627 \u0627\u0644\u0646\u0647\u064a \u0639\u0646 \u0627\u0644\u0645\u0646\u0643\u0631.","5:64":"\u064a\u064f\u0637\u0644\u0639 \u0627\u0644\u0644\u0647 \u0646\u064e\u0628\u0650\u064a\u0651\u064e\u0647 \u0639\u0644\u0649 \u0634\u064a\u0621 \u0645\u0646 \u0645\u0622\u062b\u0645 \u0627\u0644\u064a\u0647\u0648\u062f -\u0648\u0643\u0627\u0646 \u0645\u0645\u0627 \u064a\u064f\u0633\u0631\u0651\u064f\u0648\u0646\u0647 \u0641\u064a\u0645\u0627 \u0628\u064a\u0646\u0647\u0645- \u0623\u0646\u0647\u0645 \u0642\u0627\u0644\u0648\u0627: \u064a\u062f \u0627\u0644\u0644\u0647 \u0645\u062d\u0628\u0648\u0633\u0629 \u0639\u0646 \u0641\u0639\u0644 \u0627\u0644\u062e\u064a\u0631\u0627\u062a\u060c \u0628\u064e\u062e\u0650\u0644\u064e \u0639\u0644\u064a\u0646\u0627 \u0628\u0627\u0644\u0631\u0632\u0642 \u0648\u0627\u0644\u062a\u0648\u0633\u0639\u0629\u060c \u0648\u0630\u0644\u0643 \u062d\u064a\u0646 \u0644\u062d\u0642\u0647\u0645 \u062c\u064e\u062f\u0652\u0628 \u0648\u0642\u062d\u0637. \u063a\u064f\u0644\u0651\u064e\u062a\u0652 \u0623\u064a\u062f\u064a\u0647\u0645\u060c \u0623\u064a: \u062d\u0628\u0633\u062a \u0623\u064a\u062f\u064a\u0647\u0645 \u0647\u0645 \u0639\u0646 \u0641\u0650\u0639\u0652\u0644\u0650 \u0627\u0644\u062e\u064a\u0631\u0627\u062a\u060c \u0648\u0637\u0631\u062f\u0647\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0631\u062d\u0645\u062a\u0647 \u0628\u0633\u0628\u0628 \u0642\u0648\u0644\u0647\u0645. \u0648\u0644\u064a\u0633 \u0627\u0644\u0623\u0645\u0631 \u0643\u0645\u0627 \u064a\u0641\u062a\u0631\u0648\u0646\u0647 \u0639\u0644\u0649 \u0631\u0628\u0647\u0645\u060c \u0628\u0644 \u064a\u062f\u0627\u0647 \u0645\u0628\u0633\u0648\u0637\u062a\u0627\u0646 \u0644\u0627 \u062d\u064e\u062c\u0652\u0631\u064e \u0639\u0644\u064a\u0647\u060c \u0648\u0644\u0627 \u0645\u0627\u0646\u0639 \u064a\u0645\u0646\u0639\u0647 \u0645\u0646 \u0627\u0644\u0625\u0646\u0641\u0627\u0642\u060c \u0641\u0625\u0646\u0647 \u0627\u0644\u062c\u0648\u0627\u062f \u0627\u0644\u0643\u0631\u064a\u0645\u060c \u064a\u0646\u0641\u0642 \u0639\u0644\u0649 \u0645\u0642\u062a\u0636\u0649 \u0627\u0644\u062d\u0643\u0645\u0629 \u0648\u0645\u0627 \u0641\u064a\u0647 \u0645\u0635\u0644\u062d\u0629 \u0627\u0644\u0639\u0628\u0627\u062f. \u0648\u0641\u064a \u0627\u0644\u0622\u064a\u0629 \u0625\u062b\u0628\u0627\u062a \u0644\u0635\u0641\u0629 \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0643\u0645\u0627 \u064a\u0644\u064a\u0642 \u0628\u0647 \u0645\u0646 \u063a\u064a\u0631 \u062a\u0634\u0628\u064a\u0647 \u0648\u0644\u0627 \u062a\u0643\u064a\u064a\u0641. \u0644\u0643\u0646\u0647\u0645 \u0633\u0648\u0641 \u064a\u0632\u062f\u0627\u062f\u0648\u0646 \u0637\u063a\u064a\u0627\u0646\u064b\u0627 \u0648\u0643\u0641\u0631\u064b\u0627 \u0628\u0633\u0628\u0628 \u062d\u0642\u062f\u0647\u0645 \u0648\u062d\u0633\u062f\u0647\u0645; \u0644\u0623\u0646 \u0627\u0644\u0644\u0647 \u0642\u062f \u0627\u0635\u0637\u0641\u0627\u0643 \u0628\u0627\u0644\u0631\u0633\u0627\u0644\u0629. \u0648\u064a\u062e\u0628\u0631 \u062a\u0639\u0627\u0644\u0649 \u0623\u0646 \u0637\u0648\u0627\u0626\u0641 \u0627\u0644\u064a\u0647\u0648\u062f \u0633\u064a\u0638\u0644\u0648\u0646 \u0625\u0644\u0649 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u064a\u0639\u0627\u062f\u064a \u0628\u0639\u0636\u0647\u0645 \u0628\u0639\u0636\u064b\u0627\u060c \u0648\u064a\u0646\u0641\u0631 \u0628\u0639\u0636\u0647\u0645 \u0645\u0646 \u0628\u0639\u0636\u060c \u0643\u0644\u0645\u0627 \u062a\u0622\u0645\u0631\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0643\u064a\u062f \u0644\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0628\u0625\u062b\u0627\u0631\u0629 \u0627\u0644\u0641\u062a\u0646 \u0648\u0625\u0634\u0639\u0627\u0644 \u0646\u0627\u0631 \u0627\u0644\u062d\u0631\u0628 \u0631\u062f\u0651\u064e \u0627\u0644\u0644\u0647 \u0643\u064a\u062f\u0647\u0645\u060c \u0648\u0641\u0631\u0651\u064e\u0642 \u0634\u0645\u0644\u0647\u0645\u060c \u0648\u0644\u0627 \u064a\u0632\u0627\u0644 \u0627\u0644\u064a\u0647\u0648\u062f \u064a\u0639\u0645\u0644\u0648\u0646 \u0628\u0645\u0639\u0627\u0635\u064a \u0627\u0644\u0644\u0647 \u0645\u0645\u0627 \u064a\u0646\u0634\u0623 \u0639\u0646\u0647\u0627 \u0627\u0644\u0641\u0633\u0627\u062f \u0648\u0627\u0644\u0627\u0636\u0637\u0631\u0627\u0628 \u0641\u064a \u0627\u0644\u0623\u0631\u0636. \u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0627 \u064a\u062d\u0628 \u0627\u0644\u0645\u0641\u0633\u062f\u064a\u0646.","5:65":"\u0648\u0644\u0648 \u0623\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0627\u0645\u062a\u062b\u0644\u0648\u0627 \u0623\u0648\u0627\u0645\u0631 \u0627\u0644\u0644\u0647 \u0648\u0627\u062c\u062a\u0646\u0628\u0648\u0627 \u0646\u0648\u0627\u0647\u064a\u0647\u060c \u0644\u0643\u0641\u0651\u064e\u0631\u0646\u0627 \u0639\u0646\u0647\u0645 \u0630\u0646\u0648\u0628\u0647\u0645\u060c \u0648\u0644\u0623\u062f\u062e\u0644\u0646\u0627\u0647\u0645 \u062c\u0646\u0627\u062a \u0627\u0644\u0646\u0639\u064a\u0645 \u0641\u064a \u0627\u0644\u062f\u0627\u0631 \u0627\u0644\u0622\u062e\u0631\u0629.","5:66":"\u0648\u0644\u0648 \u0623\u0646\u0651\u064e\u0647\u0645 \u0639\u0645\u0644\u0648\u0627 \u0628\u0645\u0627 \u0641\u064a \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644\u060c \u0648\u0628\u0645\u0627 \u0623\u064f\u0646\u0652\u0632\u0650\u0644 \u0639\u0644\u064a\u0643 \u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644 -\u0648\u0647\u0648 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645- \u0644\u0631\u064f\u0632\u0650\u0642\u0648\u0627 \u0645\u0646 \u0643\u0644\u0651\u0650 \u0633\u0628\u064a\u0644\u064d\u060c \u0641\u0623\u0646\u0632\u0644\u0646\u0627 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0645\u0637\u0631\u060c \u0648\u0623\u0646\u0628\u062a\u0646\u0627 \u0644\u0647\u0645 \u0627\u0644\u062b\u0645\u0631\u060c \u0648\u0647\u0630\u0627 \u062c\u0632\u0627\u0621 \u0627\u0644\u062f\u0646\u064a\u0627. \u0648\u0625\u0646\u0651\u064e \u0645\u0650\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0641\u0631\u064a\u0642\u064b\u0627 \u0645\u0639\u062a\u062f\u0644\u0627 \u062b\u0627\u0628\u062a\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u062d\u0642\u060c \u0648\u0643\u062b\u064a\u0631 \u0645\u0646\u0647\u0645 \u0633\u0627\u0621 \u0639\u0645\u0644\u064f\u0647\u060c \u0648\u0636\u0644 \u0639\u0646 \u0633\u0648\u0627\u0621 \u0627\u0644\u0633\u0628\u064a\u0644.","5:67":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644 \u0628\u0644\u0651\u0650\u063a \u0648\u062d\u064a \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0650\u0644 \u0625\u0644\u064a\u0643 \u0645\u0646 \u0631\u0628\u0643\u060c \u0648\u0625\u0646 \u0642\u0635\u0651\u064e\u0631\u062a \u0641\u064a \u0627\u0644\u0628\u0644\u0627\u063a \u0641\u064e\u0643\u064e\u062a\u064e\u0645\u0652\u062a\u064e \u0645\u0646\u0647 \u0634\u064a\u0626\u064b\u0627\u060c \u0641\u0625\u0646\u0643 \u0644\u0645 \u062a\u064f\u0628\u064e\u0644\u0651\u0650\u063a \u0631\u0633\u0627\u0644\u0629 \u0631\u0628\u0651\u0650\u0643\u060c \u0648\u0642\u062f \u0628\u0644\u0651\u064e\u063a \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0631\u0633\u0627\u0644\u0629 \u0631\u0628\u0647 \u0643\u0627\u0645\u0644\u0629\u060c \u0641\u0645\u0646 \u0632\u0639\u0645 \u0623\u0646\u0647 \u0643\u062a\u0645 \u0634\u064a\u0626\u064b\u0627 \u0645\u0645\u0627 \u0623\u0646\u0632\u0650\u0644 \u0639\u0644\u064a\u0647\u060c \u0641\u0642\u062f \u0623\u0639\u0638\u0645 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0627\u0644\u0641\u0631\u064a\u0629. \u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u062d\u0627\u0641\u0638\u0643 \u0648\u0646\u0627\u0635\u0631\u0643 \u0639\u0644\u0649 \u0623\u0639\u062f\u0627\u0626\u0643\u060c \u0641\u0644\u064a\u0633 \u0639\u0644\u064a\u0643 \u0625\u0644\u0627 \u0627\u0644\u0628\u0644\u0627\u063a. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0648\u0641\u0642 \u0644\u0644\u0631\u0634\u062f \u0645\u064e\u0646 \u062d\u0627\u062f \u0639\u0646 \u0633\u0628\u064a\u0644 \u0627\u0644\u062d\u0642\u060c \u0648\u062c\u062d\u062f \u0645\u0627 \u062c\u0626\u062a \u0628\u0647 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647.","5:68":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649: \u0625\u0646\u0643\u0645 \u0644\u0633\u062a\u0645 \u0639\u0644\u0649 \u062d\u0638\u0651\u064d \u0645\u0646 \u0627\u0644\u062f\u064a\u0646 \u0645\u0627 \u062f\u0645\u062a\u0645 \u0644\u0645 \u062a\u0639\u0645\u0644\u0648\u0627 \u0628\u0645\u0627 \u0641\u064a \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644\u060c \u0648\u0645\u0627 \u062c\u0627\u0621\u0643\u0645 \u0628\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0645\u0646 \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0648\u0625\u0646 \u0643\u062b\u064a\u0631\u064b\u0627 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0644\u0627 \u064a\u0632\u064a\u062f\u0647\u0645 \u0625\u0646\u0632\u0627\u0644\u064f \u0627\u0644\u0642\u0631\u0622\u0646 \u0625\u0644\u064a\u0643 \u0625\u0644\u0627 \u062a\u062c\u0628\u0651\u064f\u0631\u064b\u0627 \u0648\u062c\u062d\u0648\u062f\u064b\u0627\u060c \u0641\u0647\u0645 \u064a\u062d\u0633\u062f\u0648\u0646\u0643; \u0644\u0623\u0646 \u0627\u0644\u0644\u0647 \u0628\u0639\u062b\u0643 \u0628\u0647\u0630\u0647 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0627\u0644\u062e\u0627\u062a\u0645\u0629\u060c \u0627\u0644\u062a\u064a \u0628\u064e\u064a\u0651\u064e\u0646 \u0641\u064a\u0647\u0627 \u0645\u0639\u0627\u064a\u0628\u0647\u0645\u060c \u0641\u0644\u0627 \u062a\u062d\u0632\u0646 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0639\u0644\u0649 \u062a\u0643\u0630\u064a\u0628\u0647\u0645 \u0644\u0643.","5:69":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 (\u0648\u0647\u0645 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646) \u0648\u0627\u0644\u064a\u0647\u0648\u062f\u060c -\u0648\u0627\u0644\u0635\u0627\u0628\u0626\u0648\u0646 \u0643\u0630\u0644\u0643 (\u0648\u0647\u0645 \u0642\u0648\u0645 \u0628\u0627\u0642\u0648\u0646 \u0639\u0644\u0649 \u0641\u0637\u0631\u062a\u0647\u0645\u060c \u0648\u0644\u0627 \u062f\u064a\u0646 \u0645\u0642\u0631\u0631 \u0644\u0647\u0645 \u064a\u062a\u0628\u0639\u0648\u0646\u0647) - \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649 (\u0648\u0647\u0645 \u0623\u062a\u0628\u0627\u0639 \u0627\u0644\u0645\u0633\u064a\u062d) \u0645\u0646 \u0622\u0645\u0646 \u0645\u0646\u0647\u0645 \u0628\u0627\u0644\u0644\u0647 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0627\u0644\u0643\u0627\u0645\u0644\u060c \u0648\u0647\u0648 \u062a\u0648\u062d\u064a\u062f \u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u062a\u0635\u062f\u064a\u0642 \u0628\u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0628\u0645\u0627 \u062c\u0627\u0621 \u0628\u0647\u060c \u0648\u0622\u0645\u0646 \u0628\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631\u060c \u0648\u0639\u0645\u0644 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u060c \u0641\u0644\u0627 \u062e\u0648\u0641 \u0639\u0644\u064a\u0647\u0645 \u0645\u0646 \u0623\u0647\u0648\u0627\u0644 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0648\u0644\u0627 \u0647\u0645 \u064a\u062d\u0632\u0646\u0648\u0646 \u0639\u0644\u0649 \u0645\u0627 \u062a\u0631\u0643\u0648\u0647 \u0648\u0631\u0627\u0621\u0647\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627.","5:70":"\u0644\u0642\u062f \u0623\u062e\u0630\u0646\u0627 \u0627\u0644\u0639\u0647\u062f \u0627\u0644\u0645\u0624\u0643\u0651\u064e\u062f \u0639\u0644\u0649 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0641\u064a \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0628\u0627\u0644\u0633\u0645\u0639 \u0648\u0627\u0644\u0637\u0627\u0639\u0629\u060c \u0648\u0623\u0631\u0633\u0644\u0646\u0627 \u0625\u0644\u064a\u0647\u0645 \u0628\u0630\u0644\u0643 \u0631\u0633\u0644\u0646\u0627\u060c \u0641\u064e\u0646\u064e\u0642\u064e\u0636\u0648\u0627 \u0645\u0627 \u0623\u064f\u062e\u0630 \u0639\u0644\u064a\u0647\u0645 \u0645\u0646 \u0627\u0644\u0639\u0647\u062f\u060c \u0648\u0627\u062a\u0628\u0639\u0648\u0627 \u0623\u0647\u0648\u0627\u0621\u0647\u0645\u060c \u0648\u0643\u0627\u0646\u0648\u0627 \u0643\u0644\u0645\u0627 \u062c\u0627\u0621\u0647\u0645 \u0631\u0633\u0648\u0644 \u0645\u0646 \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0631\u0633\u0644 \u0628\u0645\u0627 \u0644\u0627 \u062a\u0634\u062a\u0647\u064a\u0647 \u0623\u0646\u0641\u0633\u0647\u0645 \u0639\u0627\u062f\u064e\u0648\u0652\u0647: \u0641\u0643\u0630\u0628\u0648\u0627 \u0641\u0631\u064a\u0642\u064b\u0627 \u0645\u0646 \u0627\u0644\u0631\u0633\u0644\u060c \u0648\u0642\u062a\u0644\u0648\u0627 \u0641\u0631\u064a\u0642\u064b\u0627 \u0622\u062e\u0631.","5:71":"\u0648\u0638\u0646\u0651\u064e \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0639\u064f\u0635\u0627\u0629 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0644\u0646 \u064a\u0623\u062e\u0630\u0647\u0645 \u0628\u0627\u0644\u0639\u0630\u0627\u0628 \u062c\u0632\u0627\u0621 \u0639\u0635\u064a\u0627\u0646\u0647\u0645 \u0648\u0639\u064f\u062a\u064f\u0648\u0651\u0650\u0647\u0645\u060c \u0641\u0645\u0636\u0648\u0627 \u0641\u064a \u0634\u0647\u0648\u0627\u062a\u0647\u0645\u060c \u0648\u0639\u0645\u064f\u0648\u0627 \u0639\u0646 \u0627\u0644\u0647\u062f\u0649 \u0641\u0644\u0645 \u064a\u0628\u0635\u0631\u0648\u0647\u060c \u0648\u0635\u064e\u0645\u0651\u064f\u0648\u0627 \u0639\u0646 \u0633\u0645\u0627\u0639 \u0627\u0644\u062d\u0642\u0651\u0650 \u0641\u0644\u0645 \u064a\u0646\u062a\u0641\u0639\u0648\u0627 \u0628\u0647\u060c \u0641\u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0628\u0647\u0645 \u0628\u0623\u0633\u0647\u060c \u0641\u062a\u0627\u0628\u0648\u0627 \u0641\u062a\u0627\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645\u060c \u062b\u0645 \u0639\u064e\u0645\u0650\u064a \u0643\u062b\u064a\u0631\u064c \u0645\u0646\u0647\u0645\u060c \u0648\u0635\u0645\u0651\u064f\u0648\u0627\u060c \u0628\u0639\u062f\u0645\u0627 \u062a\u0628\u064a\u0646 \u0644\u0647\u0645 \u0627\u0644\u062d\u0642\u0651\u064f\u060c \u0648\u0627\u0644\u0644\u0647 \u0628\u0635\u064a\u0631 \u0628\u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u062e\u064a\u0631\u0647\u0627 \u0648\u0634\u0631\u0647\u0627 \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0647\u0645 \u0639\u0644\u064a\u0647\u0627.","5:72":"\u064a\u0642\u0633\u0645 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0623\u0646 \u0627\u0644\u0630\u064a\u0646 \u0642\u0627\u0644\u0648\u0627: \u0625\u0646 \u0627\u0644\u0644\u0647 \u0647\u0648 \u0627\u0644\u0645\u0633\u064a\u062d \u0628\u0646 \u0645\u0631\u064a\u0645\u060c \u0642\u062f \u0643\u0641\u0631\u0648\u0627 \u0628\u0645\u0642\u0627\u0644\u062a\u0647\u0645 \u0647\u0630\u0647\u060c \u0648\u0623\u062e\u0628\u0631 \u062a\u0639\u0627\u0644\u0649 \u0623\u0646 \u0627\u0644\u0645\u0633\u064a\u062d \u0642\u0627\u0644 \u0644\u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644: \u0627\u0639\u0628\u062f\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647\u060c \u0641\u0623\u0646\u0627 \u0648\u0623\u0646\u062a\u0645 \u0641\u064a \u0627\u0644\u0639\u0628\u0648\u062f\u064a\u0629 \u0633\u0648\u0627\u0621. \u0625\u0646\u0647 \u0645\u0646 \u064a\u0639\u0628\u062f \u0645\u0639 \u0627\u0644\u0644\u0647 \u063a\u064a\u0631\u0647 \u0641\u0642\u062f \u062d\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0627\u0644\u062c\u0646\u0629\u060c \u0648\u062c\u0639\u0644 \u0627\u0644\u0646\u0627\u0631 \u0645\u064f\u0633\u062a\u064e\u0642\u064e\u0631\u0651\u064e\u0647\u060c \u0648\u0644\u064a\u0633 \u0644\u0647 \u0646\u0627\u0635\u0631\u064c \u064a\u064f\u0646\u0642\u0630\u064f\u0647 \u0645\u0646\u0647\u0627.","5:73":"\u0644\u0642\u062f \u0643\u0641\u0631 \u0645\u0646 \u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0645\u0646 \u0642\u0627\u0644: \u0625\u0646\u0651\u064e \u0627\u0644\u0644\u0647 \u0645\u062c\u0645\u0648\u0639 \u062b\u0644\u0627\u062b\u0629 \u0623\u0634\u064a\u0627\u0621: \u0647\u064a \u0627\u0644\u0623\u0628\u060c \u0648\u0627\u0644\u0627\u0628\u0646\u060c \u0648\u0631\u0648\u062d \u0627\u0644\u0642\u062f\u0633. \u0623\u0645\u0627 \u0639\u064e\u0644\u0650\u0645\u064e \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0623\u0646\u0647 \u0644\u064a\u0633 \u0644\u0644\u0646\u0627\u0633 \u0633\u0648\u0649 \u0645\u0639\u0628\u0648\u062f \u0648\u0627\u062d\u062f\u060c \u0644\u0645 \u064a\u0644\u062f \u0648\u0644\u0645 \u064a\u0648\u0644\u062f\u060c \u0648\u0625\u0646 \u0644\u0645 \u064a\u0646\u062a\u0647 \u0623\u0635\u062d\u0627\u0628 \u0647\u0630\u0647 \u0627\u0644\u0645\u0642\u0627\u0644\u0629 \u0639\u0646 \u0627\u0641\u062a\u0631\u0627\u0626\u0647\u0645 \u0648\u0643\u0630\u0628\u0647\u0645 \u0644\u064a\u064f\u0635\u0650\u064a\u0628\u064e\u0646\u0651\u064e\u0647\u0645 \u0639\u0630\u0627\u0628 \u0645\u0624\u0644\u0645 \u0645\u0648\u062c\u0639 \u0628\u0633\u0628\u0628 \u0643\u0641\u0631\u0647\u0645 \u0628\u0627\u0644\u0644\u0647.","5:74":"\u0623\u0641\u0644\u0627 \u064a\u0631\u062c\u0639 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u064a\u062a\u0648\u0628\u0648\u0646 \u0639\u0645\u0651\u064e\u0627 \u0642\u0627\u0644\u0648\u0627\u060c \u0648\u064a\u0633\u0623\u0644\u0648\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0645\u063a\u0641\u0631\u0629\u061f \u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0645\u062a\u062c\u0627\u0648\u0632 \u0639\u0646 \u0630\u0646\u0648\u0628 \u0627\u0644\u062a\u0627\u0626\u0628\u064a\u0646\u060c \u0631\u062d\u064a\u0645\u064c \u0628\u0647\u0645","5:75":"\u0645\u0627 \u0627\u0644\u0645\u0633\u064a\u062d \u0627\u0628\u0646 \u0645\u0631\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0625\u0644\u0627 \u0631\u0633\u0648\u0644\u064c \u0643\u0645\u0646 \u062a\u0642\u062f\u0645\u0647 \u0645\u0646 \u0627\u0644\u0631\u0633\u0644\u060c \u0648\u0623\u064f\u0645\u0651\u064f\u0647 \u0642\u062f \u0635\u064e\u062f\u0651\u064e\u0642\u062a \u062a\u0635\u062f\u064a\u0642\u064b\u0627 \u062c\u0627\u0632\u0645\u064b\u0627 \u0639\u0644\u0645\u064b\u0627 \u0648\u0639\u0645\u0644\u0627 \u0648\u0647\u0645\u0627 \u0643\u063a\u064a\u0631\u0647\u0645\u0627 \u0645\u0646 \u0627\u0644\u0628\u0634\u0631 \u064a\u062d\u062a\u0627\u062c\u0627\u0646 \u0625\u0644\u0649 \u0627\u0644\u0637\u0639\u0627\u0645\u060c \u0648\u0644\u0627 \u064a\u0643\u0648\u0646 \u0625\u0644\u0647\u064b\u0627 \u0645\u064e\u0646 \u064a\u062d\u062a\u0627\u062c \u0627\u0644\u0649 \u0627\u0644\u0637\u0639\u0627\u0645 \u0644\u064a\u0639\u064a\u0634. \u0641\u062a\u0623\u0645\u0651\u064e\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u062d\u0627\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0641\u0627\u0631. \u0644\u0642\u062f \u0648\u0636\u062d\u0646\u0627 \u0627\u0644\u0639\u0644\u0627\u0645\u0627\u062a\u0650 \u0627\u0644\u062f\u0627\u0644\u0629\u064e \u0639\u0644\u0649 \u0648\u062d\u062f\u0627\u0646\u064a\u062a\u0646\u0627\u060c \u0648\u0628\u064f\u0637\u0644\u0627\u0646 \u0645\u0627 \u064a\u064e\u062f\u0651\u064e\u0639\u0648\u0646\u0647 \u0641\u064a \u0623\u0646\u0628\u064a\u0627\u0621 \u0627\u0644\u0644\u0647. \u062b\u0645 \u0647\u0645 \u0645\u0639 \u0630\u0644\u0643 \u064a\u064e\u0636\u0650\u0644\u0651\u064f\u0648\u0646 \u0639\u0646 \u0627\u0644\u062d\u0642 \u0627\u0644\u0630\u064a \u0646\u064e\u0647\u062f\u064a\u0647\u0645 \u0625\u0644\u064a\u0647\u060c \u062b\u0645 \u0627\u0646\u0638\u0631 \u0643\u064a\u0641 \u064a\u064f\u0635\u0631\u0641\u0648\u0646 \u0639\u0646 \u0627\u0644\u062d\u0642 \u0628\u0639\u062f \u0647\u0630\u0627 \u0627\u0644\u0628\u064a\u0627\u0646\u061f","5:76":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0641\u0631\u0629: \u0643\u064a\u0641 \u062a\u0634\u0631\u0643\u0648\u0646 \u0645\u0639 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0644\u0627 \u064a\u064e\u0642\u0652\u062f\u0650\u0631\u064f \u0639\u0644\u0649 \u0636\u064e\u0631\u0651\u0650\u0643\u0645\u060c \u0648\u0644\u0627 \u0639\u0644\u0649 \u062c\u064e\u0644\u0652\u0628\u0650 \u0646\u0641\u0639 \u0644\u0643\u0645\u061f \u0648\u0627\u0644\u0644\u0647 \u0647\u0648 \u0627\u0644\u0633\u0645\u064a\u0639 \u0644\u0623\u0642\u0648\u0627\u0644 \u0639\u0628\u0627\u062f\u0647\u060c \u0627\u0644\u0639\u0644\u064a\u0645 \u0628\u0623\u062d\u0648\u0627\u0644\u0647\u0645.","5:77":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0644\u0646\u0635\u0627\u0631\u0649: \u0644\u0627 \u062a\u062a\u062c\u0627\u0648\u0632\u0648\u0627 \u0627\u0644\u062d\u0642\u0651\u064e \u0641\u064a\u0645\u0627 \u062a\u0639\u062a\u0642\u062f\u0648\u0646\u0647 \u0645\u0646 \u0623\u0645\u0631 \u0627\u0644\u0645\u0633\u064a\u062d\u060c \u0648\u0644\u0627 \u062a\u062a\u0628\u0639\u0648\u0627 \u0623\u0647\u0648\u0627\u0621\u0643\u0645\u060c \u0643\u0645\u0627 \u0627\u062a\u0651\u064e\u0628\u0639 \u0627\u0644\u064a\u0647\u0648\u062f \u0623\u0647\u0648\u0627\u0621\u0647\u0645 \u0641\u064a \u0623\u0645\u0631 \u0627\u0644\u062f\u064a\u0646\u060c \u0641\u0648\u0642\u0639\u0648\u0627 \u0641\u064a \u0627\u0644\u0636\u0644\u0627\u0644\u060c \u0648\u062d\u0645\u0644\u0648\u0627 \u0643\u062b\u064a\u0631\u064b\u0627 \u0645\u0646 \u0627\u0644\u0646\u0627\u0633 \u0639\u0644\u0649 \u0627\u0644\u0643\u0641\u0631 \u0628\u0627\u0644\u0644\u0647\u060c \u0648\u062e\u0631\u062c\u0648\u0627 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0625\u0644\u0649 \u0637\u0631\u064a\u0642 \u0627\u0644\u063a\u064e\u0648\u0627\u064a\u0629 \u0648\u0627\u0644\u0636\u0644\u0627\u0644.","5:78":"\u064a\u062e\u0628\u0631 \u062a\u0639\u0627\u0644\u0649 \u0623\u0646\u0647 \u0637\u0631\u062f \u0645\u0646 \u0631\u062d\u0645\u062a\u0647 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0645\u0646 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0641\u064a \u0627\u0644\u0643\u062a\u0627\u0628 \u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644\u0647 \u0639\u0644\u0649 \u062f\u0627\u0648\u062f -\u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645- \u0648\u0647\u0648 \u0627\u0644\u0632\u0651\u064e\u0628\u0648\u0631\u060c \u0648\u0641\u064a \u0627\u0644\u0643\u062a\u0627\u0628 \u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644\u0647 \u0639\u0644\u0649 \u0639\u064a\u0633\u0649 - \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 - \u0648\u0647\u0648 \u0627\u0644\u0625\u0646\u062c\u064a\u0644; \u0628\u0633\u0628\u0628 \u0639\u0635\u064a\u0627\u0646\u0647\u0645 \u0648\u0627\u0639\u062a\u062f\u0627\u0626\u0647\u0645 \u0639\u0644\u0649 \u062d\u0631\u0645\u0627\u062a \u0627\u0644\u0644\u0647.","5:79":"\u0643\u0627\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u064a\u0647\u0648\u062f \u064a\u064f\u062c\u0627\u0647\u0631\u0648\u0646 \u0628\u0627\u0644\u0645\u0639\u0627\u0635\u064a \u0648\u064a\u0631\u0636\u0648\u0646\u0647\u0627\u060c \u0648\u0644\u0627 \u064a\u064e\u0646\u0652\u0647\u0649 \u0628\u0639\u0636\u064f\u0647\u0645 \u0628\u0639\u0636\u064b\u0627 \u0639\u0646 \u0623\u064a\u0651\u0650 \u0645\u0646\u0643\u0631 \u0641\u0639\u0644\u0648\u0647\u060c \u0648\u0647\u0630\u0627 \u0645\u0646 \u0623\u0641\u0639\u0627\u0644\u0647\u0645 \u0627\u0644\u0633\u064a\u0626\u0629\u060c \u0648\u0628\u0647 \u0627\u0633\u062a\u062d\u0642\u0648\u0627 \u0623\u0646 \u064a\u064f\u0637\u0652\u0631\u064e\u062f\u064f\u0648\u0627 \u0645\u0646 \u0631\u062d\u0645\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649.","5:80":"\u062a\u064e\u0631\u064e\u0649 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0643\u062b\u064a\u0631\u064b\u0627 \u0645\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u064a\u0647\u0648\u062f \u064a\u062a\u062e\u0630\u0648\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0623\u0648\u0644\u064a\u0627\u0621 \u0644\u0647\u0645\u060c \u0633\u0627\u0621 \u0645\u0627 \u0639\u0645\u0644\u0648\u0647 \u0645\u0646 \u0627\u0644\u0645\u0648\u0627\u0644\u0627\u0629 \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u062a \u0633\u0628\u0628\u064b\u0627 \u0641\u064a \u063a\u0636\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645\u060c \u0648\u062e\u0644\u0648\u062f\u0647\u0645 \u0641\u064a \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629.","5:81":"\u0648\u0644\u0648 \u0623\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u064a\u0647\u0648\u062f \u0627\u0644\u0630\u064a\u0646 \u064a\u0646\u0627\u0635\u0631\u0648\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0643\u0627\u0646\u0648\u0627 \u0642\u062f \u0622\u0645\u0646\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0627\u0644\u0646\u0628\u064a \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0623\u0642\u0631\u0651\u064f\u0648\u0627 \u0628\u0645\u0627 \u0623\u0646\u0632\u0644 \u0625\u0644\u064a\u0647 -\u0648\u0647\u0648 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645- \u0645\u0627 \u0627\u062a\u062e\u0630\u0648\u0627 \u0627\u0644\u0643\u0641\u0627\u0631 \u0623\u0635\u062d\u0627\u0628\u064b\u0627 \u0648\u0623\u0646\u0635\u0627\u0631\u064b\u0627\u060c \u0648\u0644\u0643\u0646 \u0643\u062b\u064a\u0631\u064b\u0627 \u0645\u0646\u0647\u0645 \u062e\u0627\u0631\u062c\u0648\u0646 \u0639\u0646 \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647.","5:82":"\u0644\u062a\u062c\u062f\u0646\u0651\u064e -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0623\u0634\u062f\u0651\u064e \u0627\u0644\u0646\u0627\u0633 \u0639\u062f\u0627\u0648\u0629 \u0644\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0643 \u0648\u0622\u0645\u0646\u0648\u0627 \u0628\u0643 \u0648\u0627\u062a\u0628\u0639\u0648\u0643\u060c \u0627\u0644\u064a\u0647\u0648\u062f\u064e; \u0644\u0639\u0646\u0627\u062f\u0647\u0645\u060c \u0648\u062c\u062d\u0648\u062f\u0647\u0645\u060c \u0648\u063a\u0645\u0637\u0647\u0645 \u0627\u0644\u062d\u0642\u060c \u0648\u0627\u0644\u0630\u064a\u0646 \u0623\u0634\u0631\u0643\u0648\u0627 \u0645\u0639 \u0627\u0644\u0644\u0647 \u063a\u064a\u0631\u0647\u060c \u0643\u0639\u0628\u062f\u0629 \u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u0648\u063a\u064a\u0631\u0647\u0645\u060c \u0648\u0644\u062a\u062c\u062f\u0646\u0651\u064e \u0623\u0642\u0631\u0628\u0647\u0645 \u0645\u0648\u062f\u0629 \u0644\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0642\u0627\u0644\u0648\u0627: \u0625\u0646\u0627 \u0646\u0635\u0627\u0631\u0649\u060c \u0630\u0644\u0643 \u0628\u0623\u0646 \u0645\u0646\u0647\u0645 \u0639\u0644\u0645\u0627\u0621 \u0628\u062f\u064a\u0646\u0647\u0645 \u0645\u062a\u0632\u0647\u062f\u064a\u0646 \u0648\u0639\u0628\u0651\u064e\u0627\u062f\u064b\u0627 \u0641\u064a \u0627\u0644\u0635\u0648\u0627\u0645\u0639 \u0645\u062a\u0646\u0633\u0643\u064a\u0646\u060c \u0648\u0623\u0646\u0647\u0645 \u0645\u062a\u0648\u0627\u0636\u0639\u0648\u0646 \u0644\u0627 \u064a\u0633\u062a\u0643\u0628\u0631\u0648\u0646 \u0639\u0646 \u0642\u064e\u0628\u0648\u0644 \u0627\u0644\u062d\u0642\u060c \u0648\u0647\u0624\u0644\u0627\u0621 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0642\u0628\u0644\u0648\u0627 \u0631\u0633\u0627\u0644\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0622\u0645\u0646\u0648\u0627 \u0628\u0647\u0627.","5:83":"\u0648\u0645\u0645\u0627 \u064a\u062f\u0644 \u0639\u0644\u0649 \u0642\u0631\u0628 \u0645\u0648\u062f\u062a\u0647\u0645 \u0644\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0623\u0646 \u0641\u0631\u064a\u0642\u064b\u0627 \u0645\u0646\u0647\u0645 (\u0648\u0647\u0645 \u0648\u0641\u062f \u0627\u0644\u062d\u0628\u0634\u0629 \u0644\u0645\u0627 \u0633\u0645\u0639\u0648\u0627 \u0627\u0644\u0642\u0631\u0622\u0646) \u0641\u0627\u0636\u062a \u0623\u0639\u064a\u0646\u0647\u0645 \u0645\u0646 \u0627\u0644\u062f\u0645\u0639 \u0641\u0623\u064a\u0642\u0646\u0648\u0627 \u0623\u0646\u0647 \u062d\u0642\u0651\u064c \u0645\u0646\u0632\u0644 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u062a\u0628\u0639\u0648\u0627 \u0631\u0633\u0648\u0644\u0647\u060c \u0648\u062a\u0636\u0631\u0639\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u0643\u0631\u0645\u0647\u0645 \u0628\u0634\u0631\u0641 \u0627\u0644\u0634\u0647\u0627\u062f\u0629 \u0645\u0639 \u0623\u0645\u0651\u064e\u0629 \u0645\u062d\u0645\u062f \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0639\u0644\u0649 \u0627\u0644\u0623\u0645\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629.","5:84":"\u0648\u0642\u0627\u0644\u0648\u0627: \u0648\u0623\u064a\u0651\u064f \u0644\u0648\u0645 \u0639\u0644\u064a\u0646\u0627 \u0641\u064a \u0625\u064a\u0645\u0627\u0646\u0646\u0627 \u0628\u0627\u0644\u0644\u0647\u060c \u0648\u062a\u0635\u062f\u064a\u0642\u0646\u0627 \u0628\u0627\u0644\u062d\u0642 \u0627\u0644\u0630\u064a \u062c\u0627\u0621\u0646\u0627 \u0628\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u062a\u0628\u0627\u0639\u0646\u0627 \u0644\u0647\u060c \u0648\u0646\u0631\u062c\u0648 \u0623\u0646 \u064a\u062f\u062e\u0644\u0646\u0627 \u0631\u0628\u0646\u0627 \u0645\u0639 \u0623\u0647\u0644 \u0637\u0627\u0639\u062a\u0647 \u0641\u064a \u062c\u0646\u062a\u0647 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u061f","5:85":"\u0641\u062c\u0632\u0627\u0647\u0645 \u0627\u0644\u0644\u0647 \u0628\u0645\u0627 \u0642\u0627\u0644\u0648\u0627 \u0645\u0646 \u0627\u0644\u0627\u0639\u062a\u0632\u0627\u0632 \u0628\u0625\u064a\u0645\u0627\u0646\u0647\u0645 \u0628\u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u0637\u0644\u0628\u0647\u0645 \u0623\u0646 \u064a\u0643\u0648\u0646\u0648\u0627 \u0645\u0639 \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u0635\u0627\u0644\u062d\u064a\u0646\u060c \u062c\u0646\u0627\u062a \u062a\u062c\u0631\u064a \u0645\u0646 \u062a\u062d\u062a \u0642\u0635\u0648\u0631\u0647\u0627 \u0648\u0623\u0634\u062c\u0627\u0631\u0647\u0627 \u0627\u0644\u0623\u0646\u0647\u0627\u0631\u060c \u0645\u0627\u0643\u062b\u064a\u0646 \u0641\u064a\u0647\u0627 \u0644\u0627 \u064a\u062e\u0631\u062c\u0648\u0646 \u0645\u0646\u0647\u0627\u060c \u0648\u0644\u0627 \u064a\u064f\u062d\u0648\u0651\u064e\u0644\u0648\u0646 \u0639\u0646\u0647\u0627\u060c \u0648\u0630\u0644\u0643 \u062c\u0632\u0627\u0621 \u0625\u062d\u0633\u0627\u0646\u0647\u0645 \u0641\u064a \u0627\u0644\u0642\u0648\u0644 \u0648\u0627\u0644\u0639\u0645\u0644.","5:86":"\u0648\u0627\u0644\u0630\u064a\u0646 \u062c\u062d\u062f\u0648\u0627 \u0648\u062d\u062f\u0627\u0646\u064a\u0629 \u0627\u0644\u0644\u0647 \u0648\u0623\u0646\u0643\u0631\u0648\u0627 \u0646\u0628\u0648\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0643\u0630\u0651\u064e\u0628\u0648\u0627 \u0628\u0622\u064a\u0627\u062a\u0647 \u0627\u0644\u0645\u0646\u0632\u0644\u0629 \u0639\u0644\u0649 \u0631\u0633\u0644\u0647\u060c \u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0646\u0627\u0631 \u0627\u0644\u0645\u0644\u0627\u0632\u0645\u0648\u0646 \u0644\u0647\u0627.","5:87":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0644\u0627 \u062a\u062d\u0631\u0651\u0650\u0645\u0648\u0627 \u0637\u064a\u0628\u0627\u062a \u0623\u062d\u0644\u0651\u064e\u0647\u0627 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0645\u0646 \u0627\u0644\u0645\u0637\u0627\u0639\u0645 \u0648\u0627\u0644\u0645\u0634\u0627\u0631\u0628 \u0648\u0646\u0643\u0627\u062d \u0627\u0644\u0646\u0633\u0627\u0621\u060c \u0641\u062a\u0636\u064a\u0642\u0648\u0627 \u0645\u0627 \u0648\u0633\u0651\u064e\u0639 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645\u060c \u0648\u0644\u0627 \u062a\u062a\u062c\u0627\u0648\u0632\u0648\u0627 \u062d\u062f\u0648\u062f \u0645\u0627 \u062d\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u062d\u0628 \u0627\u0644\u0645\u0639\u062a\u062f\u064a\u0646.","5:88":"\u0648\u062a\u0645\u062a\u0639\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0628\u0627\u0644\u062d\u0644\u0627\u0644 \u0627\u0644\u0637\u064a\u0628 \u0645\u0645\u0627 \u0623\u0639\u0637\u0627\u0643\u0645 \u0627\u0644\u0644\u0647 \u0648\u0645\u0646\u062d\u0643\u0645 \u0625\u064a\u0627\u0647\u060c \u0648\u0627\u062a\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0628\u0627\u0645\u062a\u062b\u0627\u0644 \u0623\u0648\u0627\u0645\u0631\u0647\u060c \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0646\u0648\u0627\u0647\u064a\u0647; \u0641\u0625\u0646 \u0625\u064a\u0645\u0627\u0646\u0643\u0645 \u0628\u0627\u0644\u0644\u0647 \u064a\u0648\u062c\u0628 \u0639\u0644\u064a\u0643\u0645 \u062a\u0642\u0648\u0627\u0647 \u0648\u0645\u0631\u0627\u0642\u0628\u062a\u0647.","5:89":"\u0644\u0627 \u064a\u0639\u0627\u0642\u0628\u0643\u0645 \u0627\u0644\u0644\u0647 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646- \u0641\u064a\u0645\u0627 \u0644\u0627 \u062a\u0642\u0635\u062f\u0648\u0646 \u0639\u064e\u0642\u0652\u062f\u064e\u0647 \u0645\u0646 \u0627\u0644\u0623\u064a\u0645\u0627\u0646\u060c \u0645\u062b\u0644 \u0642\u0648\u0644 \u0628\u0639\u0636\u0643\u0645: \u0644\u0627 \u0648\u0627\u0644\u0644\u0647\u060c \u0648\u0628\u0644\u0649 \u0648\u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0643\u0646 \u064a\u0639\u0627\u0642\u0628\u0643\u0645 \u0641\u064a\u0645\u0627 \u0642\u0635\u062f\u062a\u0645 \u0639\u0642\u062f\u0647 \u0628\u0642\u0644\u0648\u0628\u0643\u0645\u060c \u0641\u0625\u0630\u0627 \u0644\u0645 \u062a\u064e\u0641\u064f\u0648\u0627 \u0628\u0627\u0644\u064a\u0645\u064a\u0646 \u0641\u0625\u062b\u0645 \u0630\u0644\u0643 \u064a\u0645\u062d\u0648\u0647 \u0627\u0644\u0644\u0647 \u0628\u0645\u0627 \u062a\u0642\u062f\u0651\u0650\u0645\u0648\u0646\u0647 \u0645\u0645\u0627 \u0634\u0631\u0639\u0647 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0643\u0641\u0627\u0631\u0629 \u0645\u0646 \u0625\u0637\u0639\u0627\u0645 \u0639\u0634\u0631\u0629 \u0645\u062d\u062a\u0627\u062c\u064a\u0646 \u0644\u0627 \u064a\u0645\u0644\u0643\u0648\u0646 \u0645\u0627 \u064a\u0643\u0641\u064a\u0647\u0645 \u0648\u064a\u0633\u062f \u062d\u0627\u062c\u062a\u0647\u0645\u060c \u0644\u0643\u0644 \u0645\u0633\u0643\u064a\u0646 \u0646\u0635\u0641 \u0635\u0627\u0639 \u0645\u0646 \u0623\u0648\u0633\u0637 \u0637\u0639\u0627\u0645 \u0623\u0647\u0644 \u0627\u0644\u0628\u0644\u062f\u060c \u0623\u0648 \u0643\u0633\u0648\u062a\u0647\u0645\u060c \u0644\u0643\u0644 \u0645\u0633\u0643\u064a\u0646 \u0645\u0627 \u064a\u0643\u0641\u064a \u0641\u064a \u0627\u0644\u0643\u0633\u0648\u0629 \u0639\u064f\u0631\u0641\u064b\u0627\u060c \u0623\u0648 \u0625\u0639\u062a\u0627\u0642 \u0645\u0645\u0644\u0648\u0643 \u0645\u0646 \u0627\u0644\u0631\u0642\u060c \u0641\u0627\u0644\u062d\u0627\u0644\u0641 \u0627\u0644\u0630\u064a \u0644\u0645 \u064a\u0641 \u0628\u064a\u0645\u064a\u0646\u0647 \u0645\u062e\u064a\u0631 \u0628\u064a\u0646 \u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0648\u0631 \u0627\u0644\u062b\u0644\u0627\u062b\u0629\u060c \u0641\u0645\u0646 \u0644\u0645 \u064a\u062c\u062f \u0634\u064a\u0626\u064b\u0627 \u0645\u0646 \u0630\u0644\u0643 \u0641\u0639\u0644\u064a\u0647 \u0635\u064a\u0627\u0645 \u062b\u0644\u0627\u062b\u0629 \u0623\u064a\u0627\u0645. \u062a\u0644\u0643 \u0645\u0643\u0641\u0631\u0627\u062a \u0639\u062f\u0645 \u0627\u0644\u0648\u0641\u0627\u0621 \u0628\u0623\u064a\u0645\u0627\u0646\u0643\u0645\u060c \u0648\u0627\u062d\u0641\u0638\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646- \u0623\u064a\u0645\u0627\u0646\u0643\u0645: \u0628\u0627\u062c\u062a\u0646\u0627\u0628 \u0627\u0644\u062d\u0644\u0641\u060c \u0623\u0648 \u0627\u0644\u0648\u0641\u0627\u0621 \u0625\u0646 \u062d\u0644\u0641\u062a\u0645\u060c \u0623\u0648 \u0627\u0644\u0643\u0641\u0627\u0631\u0629 \u0625\u0630\u0627 \u0644\u0645 \u062a\u0641\u0648\u0627 \u0628\u0647\u0627. \u0648\u0643\u0645\u0627 \u0628\u064a\u0651\u064e\u0646 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u062d\u0643\u0645 \u0627\u0644\u0623\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u062a\u062d\u0644\u0644 \u0645\u0646\u0647\u0627 \u064a\u064f\u0628\u064a\u0651\u0650\u0646 \u0644\u0643\u0645 \u0623\u062d\u0643\u0627\u0645 \u062f\u064a\u0646\u0647; \u0644\u062a\u0634\u0643\u0631\u0648\u0627 \u0644\u0647 \u0639\u0644\u0649 \u0647\u062f\u0627\u064a\u062a\u0647 \u0625\u064a\u0627\u0643\u0645 \u0625\u0644\u0649 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645.","5:90":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0625\u0646\u0645\u0627 \u0627\u0644\u062e\u0645\u0631: \u0648\u0647\u064a \u0643\u0644 \u0645\u0633\u0643\u0631 \u064a\u063a\u0637\u064a \u0627\u0644\u0639\u0642\u0644\u060c \u0648\u0627\u0644\u0645\u064a\u0633\u0631: \u0648\u0647\u0648 \u0627\u0644\u0642\u0645\u0627\u0631\u060c \u0648\u0630\u0644\u0643 \u064a\u0634\u0645\u0644 \u0627\u0644\u0645\u0631\u0627\u0647\u0646\u0627\u062a \u0648\u0646\u062d\u0648\u0647\u0627\u060c \u0645\u0645\u0627 \u0641\u064a\u0647 \u0639\u0648\u0636 \u0645\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646\u060c \u0648\u0635\u062f\u0651\u064c \u0639\u0646 \u0630\u0643\u0631 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0644\u0623\u0646\u0635\u0627\u0628: \u0648\u0647\u064a \u0627\u0644\u062d\u062c\u0627\u0631\u0629 \u0627\u0644\u062a\u064a \u0643\u0627\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u064a\u0630\u0628\u062d\u0648\u0646 \u0639\u0646\u062f\u0647\u0627 \u062a\u0639\u0638\u064a\u0645\u064b\u0627 \u0644\u0647\u0627\u060c \u0648\u0645\u0627 \u064a\u0646\u0635\u0628 \u0644\u0644\u0639\u0628\u0627\u062f\u0629 \u062a\u0642\u0631\u0628\u064b\u0627 \u0625\u0644\u064a\u0647\u060c \u0648\u0627\u0644\u0623\u0632\u0644\u0627\u0645: \u0648\u0647\u064a \u0627\u0644\u0642\u0650\u062f\u0627\u062d \u0627\u0644\u062a\u064a \u064a\u0633\u062a\u0642\u0633\u0645 \u0628\u0647\u0627 \u0627\u0644\u0643\u0641\u0627\u0631 \u0642\u0628\u0644 \u0627\u0644\u0625\u0642\u062f\u0627\u0645 \u0639\u0644\u0649 \u0627\u0644\u0634\u064a\u0621\u060c \u0623\u0648 \u0627\u0644\u0625\u062d\u062c\u0627\u0645 \u0639\u0646\u0647\u060c \u0625\u0646 \u0630\u0644\u0643 \u0643\u0644\u0647 \u0625\u062b\u0645\u064c \u0645\u0650\u0646 \u062a\u0632\u064a\u064a\u0646 \u0627\u0644\u0634\u064a\u0637\u0627\u0646\u060c \u0641\u0627\u0628\u062a\u0639\u062f\u0648\u0627 \u0639\u0646 \u0647\u0630\u0647 \u0627\u0644\u0622\u062b\u0627\u0645\u060c \u0644\u0639\u0644\u0643\u0645 \u062a\u0641\u0648\u0632\u0648\u0646 \u0628\u0627\u0644\u062c\u0646\u0629.","5:91":"\u0625\u0646\u0645\u0627 \u064a\u0631\u064a\u062f \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0628\u062a\u0632\u064a\u064a\u0646 \u0627\u0644\u0622\u062b\u0627\u0645 \u0644\u0643\u0645 \u0623\u0646 \u064a\u064f\u0644\u0642\u0650\u064a \u0628\u064a\u0646\u0643\u0645 \u0645\u0627 \u064a\u0648\u062c\u062f \u0627\u0644\u0639\u062f\u0627\u0648\u0629 \u0648\u0627\u0644\u0628\u063a\u0636\u0627\u0621\u060c \u0628\u0633\u0628\u0628 \u0634\u0631\u0628 \u0627\u0644\u062e\u0645\u0631 \u0648\u0644\u0639\u0628 \u0627\u0644\u0645\u064a\u0633\u0631\u060c \u0648\u064a\u0635\u0631\u0641\u0643\u0645 \u0639\u0646 \u0630\u0643\u0631 \u0627\u0644\u0644\u0647 \u0648\u0639\u0646 \u0627\u0644\u0635\u0644\u0627\u0629 \u0628\u063a\u064a\u0627\u0628 \u0627\u0644\u0639\u0642\u0644 \u0641\u064a \u0634\u0631\u0628 \u0627\u0644\u062e\u0645\u0631\u060c \u0648\u0627\u0644\u0627\u0634\u062a\u063a\u0627\u0644 \u0628\u0627\u0644\u0644\u0647\u0648 \u0641\u064a \u0644\u0639\u0628 \u0627\u0644\u0645\u064a\u0633\u0631\u060c \u0641\u0627\u0646\u062a\u0647\u0648\u0627 \u0639\u0646 \u0630\u0644\u0643.","5:92":"\u0648\u0627\u0645\u062a\u062b\u0644\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646- \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u0648\u0637\u0627\u0639\u0629 \u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0641\u064a \u0643\u0644 \u0645\u0627 \u062a\u0641\u0639\u0644\u0648\u0646 \u0648\u062a\u062a\u0631\u0643\u0648\u0646\u060c \u0648\u0627\u062a\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0627\u0642\u0628\u0648\u0647 \u0641\u064a \u0630\u0644\u0643\u060c \u0641\u0625\u0646 \u0623\u0639\u0631\u0636\u062a\u0645 \u0639\u0646 \u0627\u0644\u0627\u0645\u062a\u062b\u0627\u0644 \u0641\u0639\u0645\u0644\u062a\u0645 \u0645\u0627 \u0646\u0647\u064a\u062a\u0645 \u0639\u0646\u0647\u060c \u0641\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646\u0645\u0627 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644\u0646\u0627 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0627\u0644\u0628\u0644\u0627\u063a \u0627\u0644\u0645\u0628\u064a\u0646.","5:93":"\u0644\u064a\u0633 \u0639\u0644\u0649 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0634\u0631\u0628\u0648\u0627 \u0627\u0644\u062e\u0645\u0631 \u0642\u0628\u0644 \u062a\u062d\u0631\u064a\u0645\u0647\u0627 \u0625\u062b\u0645 \u0641\u064a \u0630\u0644\u0643\u060c \u0625\u0630\u0627 \u062a\u0631\u0643\u0648\u0647\u0627 \u0648\u0627\u062a\u0642\u0648\u0627 \u0633\u062e\u0637 \u0627\u0644\u0644\u0647 \u0648\u0622\u0645\u0646\u0648\u0627 \u0628\u0647\u060c \u0648\u0642\u062f\u0651\u064e\u0645\u0648\u0627 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u0629 \u0627\u0644\u062a\u064a \u062a\u062f\u0644 \u0639\u0644\u0649 \u0625\u064a\u0645\u0627\u0646\u0647\u0645 \u0648\u0631\u063a\u0628\u062a\u0647\u0645 \u0641\u064a \u0631\u0636\u0648\u0627\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0646\u0647\u0645\u060c \u062b\u0645 \u0627\u0632\u062f\u0627\u062f\u0648\u0627 \u0628\u0630\u0644\u0643 \u0645\u0631\u0627\u0642\u0628\u0629 \u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644 \u0648\u0625\u064a\u0645\u0627\u0646\u0627 \u0628\u0647\u060c \u062d\u062a\u0649 \u0623\u0635\u0628\u062d\u0648\u0627 \u0645\u0650\u0646 \u064a\u0642\u064a\u0646\u0647\u0645 \u064a\u0639\u0628\u062f\u0648\u0646\u0647\u060c \u0648\u0643\u0623\u0646\u0647\u0645 \u064a\u0631\u0648\u0646\u0647. \u0648\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u064a\u062d\u0628 \u0627\u0644\u0630\u064a\u0646 \u0628\u0644\u063a\u0648\u0627 \u062f\u0631\u062c\u0629 \u0627\u0644\u0625\u062d\u0633\u0627\u0646 \u062d\u062a\u0649 \u0623\u0635\u0628\u062d \u0625\u064a\u0645\u0627\u0646\u0647\u0645 \u0628\u0627\u0644\u063a\u064a\u0628 \u0643\u0627\u0644\u0645\u0634\u0627\u0647\u062f\u0629.","5:94":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0644\u064a\u0628\u0644\u0648\u0646\u0643\u0645 \u0627\u0644\u0644\u0647 \u0628\u0634\u064a\u0621 \u0645\u0646 \u0627\u0644\u0635\u064a\u062f \u064a\u0642\u062a\u0631\u0628 \u0645\u0646\u0643\u0645 \u0639\u0644\u0649 \u063a\u064a\u0631 \u0627\u0644\u0645\u0639\u062a\u0627\u062f \u062d\u064a\u062b \u062a\u0633\u062a\u0637\u064a\u0639\u0648\u0646 \u0623\u064e\u062e\u0652\u0630\u064e \u0635\u063a\u0627\u0631\u0647 \u0628\u063a\u064a\u0631 \u0633\u0644\u0627\u062d \u0648\u0623\u062e\u0630 \u0643\u0628\u0627\u0631\u0647 \u0628\u0627\u0644\u0633\u0644\u0627\u062d; \u0644\u064a\u0639\u0644\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u0645\u064b\u0627 \u0638\u0627\u0647\u0631\u064b\u0627 \u0644\u0644\u062e\u0644\u0642 \u0627\u0644\u0630\u064a\u0646 \u064a\u062e\u0627\u0641\u0648\u0646 \u0631\u0628\u0647\u0645 \u0628\u0627\u0644\u063a\u064a\u0628\u060c \u0644\u064a\u0642\u064a\u0646\u0647\u0645 \u0628\u0643\u0645\u0627\u0644 \u0639\u0644\u0645\u0647 \u0628\u0647\u0645\u060c \u0648\u0630\u0644\u0643 \u0628\u0625\u0645\u0633\u0627\u0643\u0647\u0645 \u0639\u0646 \u0627\u0644\u0635\u064a\u062f\u060c \u0648\u0647\u0645 \u0645\u062d\u0631\u0645\u0648\u0646. \u0641\u0645\u0646 \u062a\u062c\u0627\u0648\u0632 \u062d\u064e\u062f\u0651\u064e\u0647 \u0628\u0639\u062f \u0647\u0630\u0627 \u0627\u0644\u0628\u064a\u0627\u0646 \u0641\u0623\u0642\u062f\u0645 \u0639\u0644\u0649 \u0627\u0644\u0635\u064a\u062f -\u0648\u0647\u0648 \u0645\u064f\u062d\u0652\u0631\u0650\u0645- \u0641\u0625\u0646\u0647 \u064a\u0633\u062a\u062d\u0642 \u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0634\u062f\u064a\u062f.","5:95":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647 \u0644\u0627 \u062a\u0642\u062a\u0644\u0648\u0627 \u0635\u064a\u062f \u0627\u0644\u0628\u0631\u060c \u0648\u0623\u0646\u062a\u0645 \u0645\u062d\u0631\u0645\u0648\u0646 \u0628\u062d\u062c \u0623\u0648 \u0639\u0645\u0631\u0629\u060c \u0623\u0648 \u0643\u0646\u062a\u0645 \u062f\u0627\u062e\u0644 \u0627\u0644\u062d\u0631\u0645 \u0648\u0645\u064e\u0646 \u0642\u062a\u0644 \u0623\u064a\u0651\u064e \u0646\u0648\u0639\u064d \u0645\u0646 \u0635\u064a\u062f \u0627\u0644\u0628\u0631\u0651\u0650 \u0645\u062a\u0639\u0645\u062f\u064b\u0627 \u0641\u062c\u0632\u0627\u0621 \u0630\u0644\u0643 \u0623\u0646 \u064a\u0630\u0628\u062d \u0645\u062b\u0644 \u0630\u0644\u0643 \u0627\u0644\u0635\u064a\u062f \u0645\u0646 \u0628\u0647\u064a\u0645\u0629 \u0627\u0644\u0623\u0646\u0639\u0627\u0645: \u0627\u0644\u0625\u0628\u0644 \u0623\u0648 \u0627\u0644\u0628\u0642\u0631 \u0623\u0648 \u0627\u0644\u063a\u0646\u0645\u060c \u0628\u0639\u062f \u0623\u0646 \u064a\u064f\u0642\u064e\u062f\u0651\u0650\u0631\u0647 \u0627\u062b\u0646\u0627\u0646 \u0639\u062f\u0644\u0627\u0646\u060c \u0648\u0623\u0646 \u064a\u0647\u062f\u064a\u0647 \u0644\u0641\u0642\u0631\u0627\u0621 \u0627\u0644\u062d\u0631\u0645\u060c \u0623\u0648 \u0623\u0646 \u064a\u0634\u062a\u0631\u064a \u0628\u0642\u064a\u0645\u0629 \u0645\u062b\u0644\u0647 \u0637\u0639\u0627\u0645\u064b\u0627 \u064a\u0647\u062f\u064a\u0647 \u0644\u0641\u0642\u0631\u0627\u0621 \u0627\u0644\u062d\u0631\u0645 \u0644\u0643\u0644 \u0645\u0633\u0643\u064a\u0646 \u0646\u0635\u0641 \u0635\u0627\u0639\u060c \u0623\u0648 \u064a\u0635\u0648\u0645 \u0628\u062f\u0644\u0627 \u0645\u0646 \u0630\u0644\u0643 \u064a\u0648\u0645\u0627 \u0639\u0646 \u0643\u0644 \u0646\u0635\u0641 \u0635\u0627\u0639 \u0645\u0646 \u0630\u0644\u0643 \u0627\u0644\u0637\u0639\u0627\u0645\u060c \u0641\u064e\u0631\u064e\u0636\u064e \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0647\u0630\u0627 \u0627\u0644\u062c\u0632\u0627\u0621; \u0644\u064a\u0644\u0642\u0649 \u0628\u0625\u064a\u062c\u0627\u0628 \u0627\u0644\u062c\u0632\u0627\u0621 \u0627\u0644\u0645\u0630\u0643\u0648\u0631 \u0639\u0627\u0642\u0628\u0629 \u0641\u0650\u0639\u0652\u0644\u0647. \u0648\u0627\u0644\u0630\u064a\u0646 \u0648\u0642\u0639\u0648\u0627 \u0641\u064a \u0634\u064a\u0621 \u0645\u0646 \u0630\u0644\u0643 \u0642\u0628\u0644 \u0627\u0644\u062a\u062d\u0631\u064a\u0645 \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0642\u062f \u0639\u0641\u0627 \u0639\u0646\u0647\u0645\u060c \u0648\u0645\u064e\u0646 \u0639\u0627\u062f \u0625\u0644\u0649 \u0627\u0644\u0645\u062e\u0627\u0644\u0641\u0629 \u0645\u062a\u0639\u0645\u062f\u064b\u0627 \u0628\u0639\u062f \u0627\u0644\u062a\u062d\u0631\u064a\u0645\u060c \u0641\u0625\u0646\u0647 \u0645\u064f\u0639\u064e\u0631\u0651\u064e\u0636 \u0644\u0627\u0646\u062a\u0642\u0627\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646\u0647. \u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0632\u064a\u0632 \u0642\u0648\u064a\u0651\u064c \u0645\u0646\u064a\u0639 \u0641\u064a \u0633\u0644\u0637\u0627\u0646\u0647\u060c \u0648\u0645\u0650\u0646 \u0639\u0632\u062a\u0647 \u0623\u0646\u0647 \u064a\u0646\u062a\u0642\u0645 \u0645\u0645\u0646 \u0639\u0635\u0627\u0647 \u0625\u0630\u0627 \u0623\u0631\u0627\u062f\u060c \u0644\u0627 \u064a\u0645\u0646\u0639\u0647 \u0645\u0646 \u0630\u0644\u0643 \u0645\u0627\u0646\u0639.","5:96":"\u0623\u062d\u0644 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646- \u0641\u064a \u062d\u0627\u0644 \u0625\u062d\u0631\u0627\u0645\u0643\u0645 \u0635\u064a\u062f \u0627\u0644\u0628\u062d\u0631\u060c \u0648\u0647\u0648 \u0645\u0627 \u064a\u0635\u0627\u062f \u0645\u0646\u0647 \u062d\u064a\u0651\u064b\u0627\u060c \u0648\u0637\u0639\u0627\u0645\u0647: \u0648\u0647\u0648 \u0627\u0644\u0645\u064a\u062a \u0645\u0646\u0647; \u0645\u0646 \u0623\u062c\u0644 \u0627\u0646\u062a\u0641\u0627\u0639\u0643\u0645 \u0628\u0647 \u0645\u0642\u064a\u0645\u064a\u0646 \u0623\u0648 \u0645\u0633\u0627\u0641\u0631\u064a\u0646\u060c \u0648\u062d\u0631\u0645 \u0639\u0644\u064a\u0643\u0645 \u0635\u064a\u062f \u0627\u0644\u0628\u064e\u0631\u0651\u0650 \u0645\u0627 \u062f\u0645\u062a\u0645 \u0645\u062d\u0631\u0645\u064a\u0646 \u0628\u062d\u062c \u0623\u0648 \u0639\u0645\u0631\u0629. \u0648\u0627\u062e\u0634\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0646\u0641\u0630\u0648\u0627 \u062c\u0645\u064a\u0639 \u0623\u0648\u0627\u0645\u0650\u0631\u0647\u060c \u0648\u0627\u062c\u062a\u0646\u0628\u0648\u0627 \u062c\u0645\u064a\u0639 \u0646\u0648\u0627\u0647\u064a\u0647; \u062d\u062a\u0649 \u062a\u0638\u0641\u064e\u0631\u0648\u0627 \u0628\u0639\u0638\u064a\u0645 \u062b\u0648\u0627\u0628\u0647\u060c \u0648\u062a\u064e\u0633\u0652\u0644\u0645\u0648\u0627 \u0645\u0646 \u0623\u0644\u064a\u0645 \u0639\u0642\u0627\u0628\u0647 \u0639\u0646\u062f\u0645\u0627 \u062a\u062d\u0634\u0631\u0648\u0646 \u0644\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u062c\u0632\u0627\u0621.","5:97":"\u0627\u0645\u062a\u0646\u0651\u064e \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0639\u0628\u0627\u062f\u0647 \u0628\u0623\u0646 \u062c\u0639\u0644 \u0627\u0644\u0643\u0639\u0628\u0629 \u0627\u0644\u0628\u064a\u062a \u0627\u0644\u062d\u0631\u0627\u0645 \u0635\u0644\u0627\u062d\u064b\u0627 \u0644\u062f\u064a\u0646\u0647\u0645\u060c \u0648\u0623\u0645\u0646\u064b\u0627 \u0644\u062d\u064a\u0627\u062a\u0647\u0645; \u0648\u0630\u0644\u0643 \u062d\u064a\u062b \u0622\u0645\u0646\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0623\u0642\u0627\u0645\u0648\u0627 \u0641\u0631\u0627\u0626\u0636\u0647\u060c \u0648\u062d\u0631\u0651\u064e\u0645 \u0627\u0644\u0639\u062f\u0648\u0627\u0646 \u0648\u0627\u0644\u0642\u062a\u0627\u0644 \u0641\u064a \u0627\u0644\u0623\u0634\u0647\u0631 \u0627\u0644\u062d\u0631\u0645 (\u0648\u0647\u064a \u0630\u0648 \u0627\u0644\u0642\u0639\u062f\u0629 \u0648\u0630\u0648 \u0627\u0644\u062d\u062c\u0629 \u0648\u0627\u0644\u0645\u062d\u0631\u0645 \u0648\u0631\u062c\u0628) \u0641\u0644\u0627 \u064a\u0639\u062a\u062f\u064a \u0641\u064a\u0647\u0627 \u0623\u062d\u062f \u0639\u0644\u0649 \u0623\u062d\u062f\u060c \u0648\u062d\u0631\u0651\u064e\u0645 \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0627\u0639\u062a\u062f\u0627\u0621 \u0639\u0644\u0649 \u0645\u0627 \u064a\u064f\u0647\u062f\u064e\u0649 \u0625\u0644\u0649 \u0627\u0644\u062d\u0631\u0645 \u0645\u0646 \u0628\u0647\u064a\u0645\u0629 \u0627\u0644\u0623\u0646\u0639\u0627\u0645\u060c \u0648\u062d\u0631\u0651\u064e\u0645 \u0643\u0630\u0644\u0643 \u0627\u0644\u0627\u0639\u062a\u062f\u0627\u0621 \u0639\u0644\u0649 \u0627\u0644\u0642\u0644\u0627\u0626\u062f\u060c \u0648\u0647\u064a \u0645\u0627 \u0642\u064f\u0644\u0651\u0650\u062f \u0625\u0634\u0639\u0627\u0631\u064b\u0627 \u0628\u0623\u0646\u0647 \u0628\u0642\u0635\u062f \u0628\u0647 \u0627\u0644\u0646\u0633\u0643; \u0630\u0644\u0643 \u0644\u062a\u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u064a\u0639\u0644\u0645 \u062c\u0645\u064a\u0639 \u0645\u0627 \u0641\u064a \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0645\u0627 \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0645\u0646 \u0630\u0644\u0643 \u0645\u0627 \u0634\u0631\u0639\u0647 \u0644\u062d\u0645\u0627\u064a\u0629 \u062e\u0644\u0642\u0647 \u0628\u0639\u0636\u0647\u0645 \u0645\u0646 \u0628\u0639\u0636\u060c \u0648\u0623\u0646 \u0627\u0644\u0644\u0647 \u0628\u0643\u0644 \u0634\u064a\u0621 \u0639\u0644\u064a\u0645\u060c \u0641\u0644\u0627 \u062a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u062e\u0627\u0641\u064a\u0629.","5:98":"\u0627\u0639\u0644\u0645\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633- \u0623\u0646 \u0627\u0644\u0644\u0647 \u062c\u0644 \u0648\u0639\u0644\u0627 \u0634\u062f\u064a\u062f \u0627\u0644\u0639\u0642\u0627\u0628 \u0644\u0645\u0646 \u0639\u0635\u0627\u0647\u060c \u0648\u0623\u0646 \u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0631\u062d\u064a\u0645 \u0644\u0645\u0646 \u062a\u0627\u0628 \u0648\u0623\u0646\u0627\u0628.","5:99":"\u064a\u0628\u064a\u0651\u0650\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0623\u0646 \u0645\u0647\u0645\u0629 \u0631\u0633\u0648\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0647\u062f\u0627\u064a\u0629 \u0627\u0644\u062f\u0644\u0627\u0644\u0629 \u0648\u0627\u0644\u062a\u0628\u0644\u064a\u063a\u060c \u0648\u0628\u064a\u062f \u0627\u0644\u0644\u0647 -\u0648\u062d\u062f\u0647- \u0647\u062f\u0627\u064a\u0629 \u0627\u0644\u062a\u0648\u0641\u064a\u0642\u060c \u0648\u0623\u0646 \u0645\u0627 \u062a\u0646\u0637\u0648\u064a \u0639\u0644\u064a\u0647 \u0646\u0641\u0648\u0633 \u0627\u0644\u0646\u0627\u0633 \u0645\u0645\u0627 \u064a\u064f\u0633\u0631\u0648\u0646 \u0623\u0648 \u064a\u0639\u0644\u0646\u0648\u0646 \u0645\u0646 \u0627\u0644\u0647\u062f\u0627\u064a\u0629 \u0623\u0648 \u0627\u0644\u0636\u0644\u0627\u0644 \u064a\u0639\u0644\u0645\u0647 \u0627\u0644\u0644\u0647.","5:100":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0644\u0627 \u064a\u0633\u062a\u0648\u064a \u0627\u0644\u062e\u0628\u064a\u062b \u0648\u0627\u0644\u0637\u064a\u0628 \u0645\u0646 \u0643\u0644 \u0634\u064a\u0621\u060c \u0641\u0627\u0644\u0643\u0627\u0641\u0631 \u0644\u0627 \u064a\u0633\u0627\u0648\u064a \u0627\u0644\u0645\u0624\u0645\u0646\u060c \u0648\u0627\u0644\u0639\u0627\u0635\u064a \u0644\u0627 \u064a\u0633\u0627\u0648\u064a \u0627\u0644\u0645\u0637\u064a\u0639\u060c \u0648\u0627\u0644\u062c\u0627\u0647\u0644 \u0644\u0627 \u064a\u0633\u0627\u0648\u064a \u0627\u0644\u0639\u0627\u0644\u0645\u060c \u0648\u0627\u0644\u0645\u0628\u062a\u062f\u0639 \u0644\u0627 \u064a\u0633\u0627\u0648\u064a \u0627\u0644\u0645\u062a\u0628\u0639\u060c \u0648\u0627\u0644\u0645\u0627\u0644 \u0627\u0644\u062d\u0631\u0627\u0645 \u0644\u0627 \u064a\u0633\u0627\u0648\u064a \u0627\u0644\u062d\u0644\u0627\u0644\u060c \u0648\u0644\u0648 \u0623\u0639\u062c\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0625\u0646\u0633\u0627\u0646- \u0643\u062b\u0631\u0629 \u0627\u0644\u062e\u0628\u064a\u062b \u0648\u0639\u062f\u062f \u0623\u0647\u0644\u0647. \u0641\u0627\u062a\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u064a\u0627 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0639\u0642\u0648\u0644 \u0627\u0644\u0631\u0627\u062c\u062d\u0629 \u0628\u0627\u062c\u062a\u0646\u0627\u0628 \u0627\u0644\u062e\u0628\u0627\u0626\u062b\u060c \u0648\u0641\u0639\u0644 \u0627\u0644\u0637\u064a\u0628\u0627\u062a; \u0644\u062a\u0641\u0644\u062d\u0648\u0627 \u0628\u0646\u064a\u0644 \u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0627\u0644\u0623\u0639\u0638\u0645\u060c \u0648\u0647\u0648 \u0631\u0636\u0627 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0627\u0644\u0641\u0648\u0632 \u0628\u0627\u0644\u062c\u0646\u0629.","5:101":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647 \u0644\u0627 \u062a\u0633\u0623\u0644\u0648\u0627 \u0639\u0646 \u0623\u0634\u064a\u0627\u0621 \u0645\u0646 \u0623\u0645\u0648\u0631 \u0627\u0644\u062f\u064a\u0646 \u0644\u0645 \u062a\u0624\u0645\u0631\u0648\u0627 \u0641\u064a\u0647\u0627 \u0628\u0634\u064a\u0621\u060c \u0643\u0627\u0644\u0633\u0624\u0627\u0644 \u0639\u0646 \u0627\u0644\u0623\u0645\u0648\u0631 \u063a\u064a\u0631 \u0627\u0644\u0648\u0627\u0642\u0639\u0629\u060c \u0623\u0648 \u0627\u0644\u062a\u064a \u064a\u062a\u0631\u062a\u0628 \u0639\u0644\u064a\u0647\u0627 \u062a\u0634\u062f\u064a\u062f\u0627\u062a \u0641\u064a \u0627\u0644\u0634\u0631\u0639\u060c \u0648\u0644\u0648 \u0643\u064f\u0644\u0651\u0650\u0641\u062a\u0645\u0648\u0647\u0627 \u0644\u0634\u0642\u0651\u064e\u062a\u0652 \u0639\u0644\u064a\u0643\u0645\u060c \u0648\u0625\u0646 \u062a\u0633\u0623\u0644\u0648\u0627 \u0639\u0646\u0647\u0627 \u0641\u064a \u062d\u064a\u0627\u0629 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u062d\u064a\u0646 \u0646\u0632\u0648\u0644 \u0627\u0644\u0642\u0631\u0622\u0646 \u0639\u0644\u064a\u0647 \u062a\u064f\u0628\u064a\u0651\u064e\u0646 \u0644\u0643\u0645\u060c \u0648\u0642\u062f \u062a\u064f\u0643\u0644\u0651\u064e\u0641\u0648\u0646\u0647\u0627 \u0641\u062a\u0639\u062c\u0632\u0648\u0646 \u0639\u0646\u0647\u0627\u060c \u062a\u0631\u0643\u0647\u0627 \u0627\u0644\u0644\u0647 \u0645\u0639\u0627\u0641\u064a\u064b\u0627 \u0644\u0639\u0628\u0627\u062f\u0647 \u0645\u0646\u0647\u0627. \u0648\u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0644\u0639\u0628\u0627\u062f\u0647 \u0625\u0630\u0627 \u062a\u0627\u0628\u0648\u0627\u060c \u062d\u0644\u064a\u0645 \u0639\u0644\u064a\u0647\u0645 \u0641\u0644\u0627 \u064a\u0639\u0627\u0642\u0628\u0647\u0645 \u0648\u0642\u062f \u0623\u0646\u0627\u0628\u0648\u0627 \u0625\u0644\u064a\u0647.","5:102":"\u0625\u0646 \u0645\u062b\u0644 \u062a\u0644\u0643 \u0627\u0644\u0623\u0633\u0626\u0644\u0629 \u0642\u062f \u0633\u0623\u0644\u0647\u0627 \u0642\u0648\u0645\u064c \u0645\u0650\u0646 \u0642\u0628\u0644\u0643\u0645 \u0631\u0633\u0644\u064e\u0647\u0645\u060c \u0641\u0644\u0645\u0627 \u0623\u064f\u0645\u0650\u0631\u0648\u0627 \u0628\u0647\u0627 \u062c\u062d\u062f\u0648\u0647\u0627\u060c \u0648\u0644\u0645 \u064a\u0646\u0641\u0630\u0648\u0647\u0627\u060c \u0641\u0627\u062d\u0630\u0631\u0648\u0627 \u0623\u0646 \u062a\u0643\u0648\u0646\u0648\u0627 \u0645\u062b\u0644\u0647\u0645.","5:103":"\u0645\u0627 \u0634\u0631\u0639 \u0627\u0644\u0644\u0647 \u0644\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0645\u0627 \u0627\u0628\u062a\u062f\u0639\u0648\u0647 \u0641\u064a \u0628\u0647\u064a\u0645\u0629 \u0627\u0644\u0623\u0646\u0639\u0627\u0645 \u0645\u0650\u0646 \u062a\u064e\u0631\u0652\u0643 \u0627\u0644\u0627\u0646\u062a\u0641\u0627\u0639 \u0628\u0628\u0639\u0636\u0647\u0627 \u0648\u062c\u0639\u0644\u0647\u0627 \u0644\u0644\u0623\u0635\u0646\u0627\u0645\u060c \u0648\u0647\u064a: \u0627\u0644\u0628\u064e\u062d\u064a\u0631\u0629 \u0627\u0644\u062a\u064a \u062a\u064f\u0642\u0637\u0639 \u0623\u0630\u0646\u0647\u0627 \u0625\u0630\u0627 \u0648\u0644\u062f\u062a \u0639\u062f\u062f\u064b\u0627 \u0645\u0646 \u0627\u0644\u0628\u0637\u0648\u0646\u060c \u0648\u0627\u0644\u0633\u0627\u0626\u0628\u0629 \u0648\u0647\u064a \u0627\u0644\u062a\u064a \u062a\u064f\u062a\u0631\u0643 \u0644\u0644\u0623\u0635\u0646\u0627\u0645\u060c \u0648\u0627\u0644\u0648\u0635\u064a\u0644\u0629 \u0648\u0647\u064a \u0627\u0644\u062a\u064a \u062a\u062a\u0635\u0644 \u0648\u0644\u0627\u062f\u062a\u0647\u0627 \u0628\u0623\u0646\u062b\u0649 \u0628\u0639\u062f \u0623\u0646\u062b\u0649\u060c \u0648\u0627\u0644\u062d\u0627\u0645\u064a \u0648\u0647\u0648 \u0627\u0644\u0630\u0643\u0631 \u0645\u0646 \u0627\u0644\u0625\u0628\u0644 \u0625\u0630\u0627 \u0648\u064f\u0644\u062f \u0645\u0646 \u0635\u0644\u0628\u0647 \u0639\u062f\u062f \u0645\u0646 \u0627\u0644\u0625\u0628\u0644\u060c \u0648\u0644\u0643\u0646 \u0627\u0644\u0643\u0641\u0627\u0631 \u0646\u0633\u0628\u0648\u0627 \u0630\u0644\u0643 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0627\u0641\u062a\u0631\u0627\u0621 \u0639\u0644\u064a\u0647\u060c \u0648\u0623\u0643\u062b\u0631 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0644\u0627 \u064a\u0645\u064a\u0632\u0648\u0646 \u0627\u0644\u062d\u0642 \u0645\u0646 \u0627\u0644\u0628\u0627\u0637\u0644.","5:104":"\u0648\u0625\u0630\u0627 \u0642\u064a\u0644 \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0641\u0627\u0631 \u0627\u0644\u0645\u062d\u0631\u0651\u0650\u0645\u064a\u0646 \u0645\u0627 \u0623\u062d\u0644 \u0627\u0644\u0644\u0647: \u062a\u0639\u0627\u0644\u0648\u0627 \u0625\u0644\u0649 \u062a\u0646\u0632\u064a\u0644 \u0627\u0644\u0644\u0647 \u0648\u0625\u0644\u0649 \u0631\u0633\u0648\u0644\u0647 \u0644\u064a\u062a\u0628\u064a\u0646 \u0644\u0643\u0645 \u0627\u0644\u062d\u0644\u0627\u0644 \u0648\u0627\u0644\u062d\u0631\u0627\u0645\u060c \u0642\u0627\u0644\u0648\u0627: \u064a\u0643\u0641\u064a\u0646\u0627 \u0645\u0627 \u0648\u0631\u062b\u0646\u0627\u0647 \u0639\u0646 \u0622\u0628\u0627\u0626\u0646\u0627 \u0645\u0646 \u0642\u0648\u0644 \u0648\u0639\u0645\u0644\u060c \u0623\u064a\u0642\u0648\u0644\u0648\u0646 \u0630\u0644\u0643 \u0648\u0644\u0648 \u0643\u0627\u0646 \u0622\u0628\u0627\u0624\u0647\u0645 \u0644\u0627 \u064a\u0639\u0644\u0645\u0648\u0646 \u0634\u064a\u0626\u064b\u0627 \u0623\u064a: \u0644\u0627 \u064a\u0641\u0647\u0645\u0648\u0646 \u062d\u0642\u0651\u064b\u0627 \u0648\u0644\u0627 \u064a\u0639\u0631\u0641\u0648\u0646\u0647\u060c \u0648\u0644\u0627 \u064a\u0647\u062a\u062f\u0648\u0646 \u0625\u0644\u064a\u0647\u061f \u0641\u0643\u064a\u0641 \u064a\u062a\u0628\u0639\u0648\u0646\u0647\u0645\u060c \u0648\u0627\u0644\u062d\u0627\u0644\u0629 \u0647\u0630\u0647\u061f \u0641\u0625\u0646\u0647 \u0644\u0627 \u064a\u062a\u0628\u0639\u0647\u0645 \u0625\u0644\u0627 \u0645\u0646 \u0647\u0648 \u0623\u062c\u0647\u0644 \u0645\u0646\u0647\u0645 \u0648\u0623\u0636\u0644 \u0633\u0628\u064a\u0644\u0627.","5:105":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647 \u0623\u0644\u0632\u0645\u0648\u0627 \u0623\u0646\u0641\u0633\u0643\u0645 \u0628\u0627\u0644\u0639\u0645\u0644 \u0628\u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0645\u0639\u0635\u064a\u062a\u0647\u060c \u0648\u062f\u0627\u0648\u0645\u0648\u0627 \u0639\u0644\u0649 \u0630\u0644\u0643 \u0648\u0625\u0646 \u0644\u0645 \u064a\u0633\u062a\u062c\u0628 \u0627\u0644\u0646\u0627\u0633 \u0644\u0643\u0645\u060c \u0641\u0625\u0630\u0627 \u0641\u0639\u0644\u062a\u0645 \u0630\u0644\u0643 \u0641\u0644\u0627 \u064a\u0636\u0631\u0643\u0645 \u0636\u0644\u0627\u0644 \u0645\u064e\u0646 \u0636\u0644\u0651\u064e \u0625\u0630\u0627 \u0644\u0632\u0645\u062a\u0645 \u0637\u0631\u064a\u0642 \u0627\u0644\u0627\u0633\u062a\u0642\u0627\u0645\u0629\u060c \u0648\u0623\u0645\u0631\u062a\u0645 \u0628\u0627\u0644\u0645\u0639\u0631\u0648\u0641 \u0648\u0646\u0647\u064a\u062a\u0645 \u0639\u0646 \u0627\u0644\u0645\u0646\u0643\u0631\u060c \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0645\u0631\u062c\u0639\u0643\u0645 \u062c\u0645\u064a\u0639\u064b\u0627 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0641\u064a\u062e\u0628\u0631\u0643\u0645 \u0628\u0623\u0639\u0645\u0627\u0644\u0643\u0645\u060c \u0648\u064a\u062c\u0627\u0632\u064a\u0643\u0645 \u0639\u0644\u064a\u0647\u0627.","5:106":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647 \u0625\u0630\u0627 \u0642\u0631\u0628 \u0627\u0644\u0645\u0648\u062a \u0645\u0646 \u0623\u062d\u062f\u0643\u0645\u060c \u0641\u0644\u0652\u064a\u064f\u0634\u0652\u0647\u0650\u062f \u0639\u0644\u0649 \u0648\u0635\u064a\u062a\u0647 \u0627\u062b\u0646\u064a\u0646 \u0623\u0645\u064a\u0646\u064a\u0646 \u0645\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0623\u0648 \u0622\u062e\u0631\u064a\u0646 \u0645\u0646 \u063a\u064a\u0631 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0639\u0646\u062f \u0627\u0644\u062d\u0627\u062c\u0629\u060c \u0648\u0639\u062f\u0645 \u0648\u062c\u0648\u062f \u063a\u064a\u0631\u0647\u0645\u0627 \u0645\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u062a\u064f\u0634\u0647\u062f\u0648\u0646\u0647\u0645\u0627 \u0625\u0646 \u0623\u0646\u062a\u0645 \u0633\u0627\u0641\u0631\u062a\u0645 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0641\u062d\u0644\u0651\u064e \u0628\u0643\u0645 \u0627\u0644\u0645\u0648\u062a\u060c \u0648\u0625\u0646 \u0627\u0631\u062a\u0628\u062a\u0645 \u0641\u064a \u0634\u0647\u0627\u062f\u062a\u0647\u0645\u0627 \u0641\u0642\u0641\u0648\u0647\u0645\u0627 \u0645\u0646 \u0628\u0639\u062f \u0627\u0644\u0635\u0644\u0627\u0629 -\u0623\u064a \u0635\u0644\u0627\u0629 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0648\u0628\u062e\u0627\u0635\u0629 \u0635\u0644\u0627\u0629 \u0627\u0644\u0639\u0635\u0631-\u060c \u0641\u064a\u0642\u0633\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u0642\u0633\u0645\u064b\u0627 \u062e\u0627\u0644\u0635\u064b\u0627 \u0644\u0627 \u064a\u0623\u062e\u0630\u0627\u0646 \u0628\u0647 \u0639\u0648\u0636\u064b\u0627 \u0645\u0646 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0644\u0627 \u064a\u062d\u0627\u0628\u064a\u0627\u0646 \u0628\u0647 \u0630\u0627 \u0642\u0631\u0627\u0628\u0629 \u0645\u0646\u0647\u0645\u0627\u060c \u0648\u0644\u0627 \u064a\u0643\u062a\u0645\u0627\u0646 \u0628\u0647 \u0634\u0647\u0627\u062f\u0629 \u0644\u0644\u0647 \u0639\u0646\u062f\u0647\u0645\u0627\u060c \u0648\u0623\u0646\u0647\u0645\u0627 \u0625\u0646 \u0641\u064e\u0639\u064e\u0644\u0627 \u0630\u0644\u0643 \u0641\u0647\u0645\u0627 \u0645\u0646 \u0627\u0644\u0645\u0630\u0646\u0628\u064a\u0646.","5:107":"\u0641\u0625\u0646 \u0627\u0637\u0644\u0639 \u0623\u0648\u0644\u064a\u0627\u0621 \u0627\u0644\u0645\u064a\u062a \u0639\u0644\u0649 \u0623\u0646 \u0627\u0644\u0634\u0627\u0647\u062f\u064a\u0646 \u0627\u0644\u0645\u0630\u0643\u0648\u0631\u064a\u0646 \u0642\u062f \u0623\u062b\u0645\u0627 \u0628\u0627\u0644\u062e\u064a\u0627\u0646\u0629 \u0641\u064a \u0627\u0644\u0634\u0647\u0627\u062f\u0629 \u0623\u0648 \u0627\u0644\u0648\u0635\u064a\u0629 \u0641\u0644\u064a\u0642\u0645 \u0645\u0642\u0627\u0645\u0647\u0645\u0627 \u0641\u064a \u0627\u0644\u0634\u0647\u0627\u062f\u0629 \u0627\u062b\u0646\u0627\u0646 \u0645\u0646 \u0623\u0648\u0644\u064a\u0627\u0621 \u0627\u0644\u0645\u064a\u062a \u0641\u064a\u0642\u0633\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647: \u0644\u064e\u0634\u0647\u0627\u062f\u062a\u0646\u0627 \u0627\u0644\u0635\u0627\u062f\u0642\u0629 \u0623\u0648\u0644\u0649 \u0628\u0627\u0644\u0642\u0628\u0648\u0644 \u0645\u0646 \u0634\u0647\u0627\u062f\u062a\u0647\u0645\u0627 \u0627\u0644\u0643\u0627\u0630\u0628\u0629\u060c \u0648\u0645\u0627 \u062a\u062c\u0627\u0648\u0632\u0646\u0627 \u0627\u0644\u062d\u0642 \u0641\u064a \u0634\u0647\u0627\u062f\u062a\u0646\u0627\u060c \u0625\u0646\u0627 \u0625\u0646 \u0627\u0639\u062a\u062f\u064a\u0646\u0627 \u0648\u0634\u0647\u062f\u0646\u0627 \u0628\u063a\u064a\u0631 \u0627\u0644\u062d\u0642 \u0644\u0645\u0646 \u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0627\u0644\u0645\u062a\u062c\u0627\u0648\u0632\u064a\u0646 \u062d\u062f\u0648\u062f \u0627\u0644\u0644\u0647.","5:108":"\u0630\u0644\u0643 \u0627\u0644\u062d\u0643\u0645 \u0639\u0646\u062f \u0627\u0644\u0627\u0631\u062a\u064a\u0627\u0628 \u0641\u064a \u0627\u0644\u0634\u0627\u0647\u062f\u064a\u0646 \u0645\u0646 \u0627\u0644\u062d\u0644\u0641 \u0628\u0639\u062f \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0639\u062f\u0645 \u0642\u0628\u0648\u0644 \u0634\u0647\u0627\u062f\u062a\u0647\u0645\u0627\u060c \u0623\u0642\u0631\u0628 \u0625\u0644\u0649 \u0623\u0646 \u064a\u0623\u062a\u0648\u0627 \u0628\u0627\u0644\u0634\u0647\u0627\u062f\u0629 \u0639\u0644\u0649 \u062d\u0642\u064a\u0642\u062a\u0647\u0627 \u062e\u0648\u0641\u064b\u0627 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0623\u0648 \u062e\u0634\u064a\u0629 \u0645\u0646 \u0623\u0646 \u062a\u0631\u062f \u0627\u0644\u064a\u0645\u064a\u0646 \u0627\u0644\u0643\u0627\u0630\u0628\u0629 \u0645\u0646 \u0642\u0650\u0628\u064e\u0644 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u062d\u0642 \u0628\u0639\u062f \u062d\u0644\u0641\u0647\u0645\u060c \u0641\u064a\u0641\u062a\u0636\u062d \u0627\u0644\u0643\u0627\u0630\u0628 \u0627\u0644\u0630\u064a \u0631\u062f\u062a \u064a\u0645\u064a\u0646\u0647 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0642\u062a \u0638\u0647\u0648\u0631 \u062e\u064a\u0627\u0646\u062a\u0647. \u0648\u062e\u0627\u0641\u0648\u0627 \u0627\u0644\u0644\u0647 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633- \u0648\u0631\u0627\u0642\u0628\u0648\u0647 \u0623\u0646 \u062a\u062d\u0644\u0641\u0648\u0627 \u0643\u0630\u0628\u064b\u0627\u060c \u0648\u0623\u0646 \u062a\u0642\u062a\u0637\u0639\u0648\u0627 \u0628\u0623\u064a\u0645\u0627\u0646\u0643\u0645 \u0645\u0627\u0644\u0627 \u062d\u0631\u0627\u0645\u064b\u0627\u060c \u0648\u0627\u0633\u0645\u0639\u0648\u0627 \u0645\u0627 \u062a\u0648\u0639\u0638\u0648\u0646 \u0628\u0647. \u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0647\u062f\u064a \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u0641\u0627\u0633\u0642\u064a\u0646 \u0627\u0644\u062e\u0627\u0631\u062c\u064a\u0646 \u0639\u0646 \u0637\u0627\u0639\u062a\u0647.","5:109":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633- \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u064a\u0648\u0645 \u064a\u062c\u0645\u0639 \u0627\u0644\u0644\u0647 \u0627\u0644\u0631\u0633\u0644 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0641\u064a\u0633\u0623\u0644\u0647\u0645 \u0639\u0646 \u062c\u0648\u0627\u0628 \u0623\u0645\u0645\u0647\u0645 \u0644\u0647\u0645 \u062d\u064a\u0646\u0645\u0627 \u062f\u0639\u0648\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u062a\u0648\u062d\u064a\u062f \u0641\u064a\u062c\u064a\u0628\u0648\u0646: \u0644\u0627 \u0639\u0644\u0645 \u0644\u0646\u0627\u060c \u0641\u0646\u062d\u0646 \u0644\u0627 \u0646\u0639\u0644\u0645 \u0645\u0627 \u0641\u064a \u0635\u062f\u0648\u0631 \u0627\u0644\u0646\u0627\u0633\u060c \u0648\u0644\u0627 \u0645\u0627 \u0623\u062d\u062f\u062b\u0648\u0627 \u0628\u0639\u062f\u0646\u0627. \u0625\u0646\u0643 \u0623\u0646\u062a \u0639\u0644\u064a\u0645 \u0628\u0643\u0644 \u0634\u064a\u0621 \u0645\u0645\u0627 \u062e\u0641\u064a \u0623\u0648 \u0638\u0647\u0631.","5:110":"\u0625\u0630 \u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629: \u064a\u0627 \u0639\u064a\u0633\u0649 \u0628\u0646 \u0645\u0631\u064a\u0645 \u0627\u0630\u0643\u0631 \u0646\u0639\u0645\u062a\u064a \u0639\u0644\u064a\u0643 \u0625\u0630 \u062e\u0644\u0642\u062a\u0643 \u0645\u0646 \u063a\u064a\u0631 \u0623\u0628\u060c \u0648\u0639\u0644\u0649 \u0648\u0627\u0644\u062f\u062a\u0643 \u062d\u064a\u062b \u0627\u0635\u0637\u0641\u064a\u062a\u0647\u0627 \u0639\u0644\u0649 \u0646\u0633\u0627\u0621 \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0646\u060c \u0648\u0628\u0631\u0623\u062a\u0647\u0627 \u0645\u0645\u0627 \u0646\u064f\u0633\u0650\u0628 \u0625\u0644\u064a\u0647\u0627\u060c \u0648\u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0646\u0639\u0645 \u0639\u0644\u0649 \u0639\u064a\u0633\u0649 \u0623\u0646\u0647 \u0642\u0648\u0651\u064e\u0627\u0647 \u0648\u0623\u0639\u0627\u0646\u0647 \u0628\u062c\u0628\u0631\u064a\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u064a\u0643\u0644\u0645 \u0627\u0644\u0646\u0627\u0633 \u0648\u0647\u0648 \u0631\u0636\u064a\u0639\u060c \u0648\u064a\u062f\u0639\u0648\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u0647\u0648 \u0643\u0628\u064a\u0631 \u0628\u0645\u0627 \u0623\u0648\u062d\u0627\u0647 \u0627\u0644\u0644\u0647 \u0625\u0644\u064a\u0647 \u0645\u0646 \u0627\u0644\u062a\u0648\u062d\u064a\u062f\u060c \u0648\u0645\u0646\u0647\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u0651\u064e\u0645\u0647 \u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0648\u0627\u0644\u062e\u0637 \u0628\u062f\u0648\u0646 \u0645\u0639\u0644\u0645\u060c \u0648\u0648\u0647\u0628\u0647 \u0642\u0648\u0629 \u0627\u0644\u0641\u0647\u0645 \u0648\u0627\u0644\u0625\u062f\u0631\u0627\u0643\u060c \u0648\u0639\u064e\u0644\u0651\u064e\u0645\u0647 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0627\u0644\u062a\u064a \u0623\u0646\u0632\u0644\u0647\u0627 \u0639\u0644\u0649 \u0645\u0648\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644 \u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644 \u0639\u0644\u064a\u0647 \u0647\u062f\u0627\u064a\u0629 \u0644\u0644\u0646\u0627\u0633\u060c \u0648\u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0646\u0639\u0645 \u0623\u0646\u0647 \u064a\u0635\u0648\u0651\u0650\u0631 \u0645\u0646 \u0627\u0644\u0637\u064a\u0646 \u0643\u0647\u064a\u0626\u0629 \u0627\u0644\u0637\u064a\u0631 \u0641\u064a\u0646\u0641\u062e \u0641\u064a \u062a\u0644\u0643 \u0627\u0644\u0647\u064a\u0626\u0629\u060c \u0641\u062a\u0643\u0648\u0646 \u0637\u064a\u0631\u064b\u0627 \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0645\u0646\u0647\u0627 \u0623\u0646\u0647 \u064a\u0634\u0641\u064a \u0627\u0644\u0630\u064a \u0648\u064f\u0644\u0650\u062f \u0623\u0639\u0645\u0649 \u0641\u064a\u0628\u0635\u0631\u060c \u0648\u064a\u0634\u0641\u064a \u0627\u0644\u0623\u0628\u0631\u0635\u060c \u0641\u064a\u0639\u0648\u062f \u062c\u0644\u062f\u0647 \u0633\u0644\u064a\u0645\u064b\u0627 \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0645\u0646\u0647\u0627 \u0623\u0646\u0647 \u064a\u062f\u0639\u0648 \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u062d\u064a\u064a\u064e \u0627\u0644\u0645\u0648\u062a\u0649 \u0641\u064a\u0642\u0648\u0645\u0648\u0646 \u0645\u0646 \u0642\u0628\u0648\u0631\u0647\u0645 \u0623\u062d\u064a\u0627\u0621\u060c \u0648\u0630\u0644\u0643 \u0643\u0644\u0647 \u0628\u0625\u0631\u0627\u062f\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0625\u0630\u0646\u0647\u060c \u0648\u0647\u064a \u0645\u0639\u062c\u0632\u0627\u062a \u0628\u0627\u0647\u0631\u0629 \u062a\u0624\u064a\u062f \u0646\u0628\u0648\u0629 \u0639\u064a\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u062b\u0645 \u064a\u0630\u0643\u0651\u0650\u0631\u0647 \u0627\u0644\u0644\u0647 \u062c\u0644 \u0648\u0639\u0644\u0627 \u0646\u0639\u0645\u062a\u0647 \u0639\u0644\u064a\u0647 \u0625\u0630 \u0645\u0646\u0639 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u062d\u064a\u0646 \u0647\u0645\u0651\u064f\u0648\u0627 \u0628\u0642\u062a\u0644\u0647\u060c \u0648\u0642\u062f \u062c\u0627\u0621\u0647\u0645 \u0628\u0627\u0644\u0645\u0639\u062c\u0632\u0627\u062a \u0627\u0644\u0648\u0627\u0636\u062d\u0629 \u0627\u0644\u062f\u0627\u0644\u0629 \u0639\u0644\u0649 \u0646\u0628\u0648\u062a\u0647\u060c \u0641\u0642\u0627\u0644 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0645\u0646\u0647\u0645: \u0625\u0646\u0651\u064e \u0645\u0627 \u062c\u0627\u0621 \u0628\u0647 \u0639\u064a\u0633\u0649 \u0645\u0646 \u0627\u0644\u0628\u064a\u0646\u0627\u062a \u0633\u062d\u0631 \u0638\u0627\u0647\u0631.","5:111":"\u0648\u0627\u0630\u0643\u0631 -\u064a\u0627 \u0639\u064a\u0633\u0649- \u0646\u0639\u0645\u062a\u064a \u0639\u0644\u064a\u0643\u060c \u0625\u0630 \u0623\u0644\u0647\u0645\u062a\u064f\u060c \u0648\u0623\u0644\u0642\u064a\u062a\u064f \u0641\u064a \u0642\u0644\u0648\u0628 \u062c\u0645\u0627\u0639\u0629 \u0645\u0646 \u062e\u0644\u0635\u0627\u0626\u0643 \u0623\u0646 \u064a\u0635\u062f\u0642\u0648\u0627 \u0628\u0648\u062d\u062f\u0627\u0646\u064a\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0646\u0628\u0648\u062a\u0643\u060c \u0641\u0642\u0627\u0644\u0648\u0627: \u0635\u062f\u0651\u064e\u0642\u0646\u0627 \u064a\u0627 \u0631\u0628\u0646\u0627\u060c \u0648\u0627\u0634\u0647\u062f \u0628\u0623\u0646\u0646\u0627 \u062e\u0627\u0636\u0639\u0648\u0646 \u0644\u0643 \u0645\u0646\u0642\u0627\u062f\u0648\u0646 \u0644\u0623\u0645\u0631\u0643.","5:112":"\u0648\u0627\u0630\u0643\u0631 \u0625\u0630 \u0642\u0627\u0644 \u0627\u0644\u062d\u0648\u0627\u0631\u064a\u0648\u0646: \u064a\u0627 \u0639\u064a\u0633\u0649 \u0628\u0646 \u0645\u0631\u064a\u0645 \u0647\u0644 \u064a\u0633\u062a\u0637\u064a\u0639 \u0631\u0628\u0643 \u0625\u0646 \u0633\u0623\u0644\u062a\u0647 \u0623\u0646 \u064a\u0646\u0632\u0644 \u0639\u0644\u064a\u0646\u0627 \u0645\u0627\u0626\u062f\u0629 \u0637\u0639\u0627\u0645 \u0645\u0646 \u0627\u0644\u0633\u0645\u0627\u0621\u061f \u0641\u0643\u0627\u0646 \u062c\u0648\u0627\u0628\u0647 \u0623\u0646 \u0623\u0645\u0631\u0647\u0645 \u0628\u0623\u0646 \u064a\u062a\u0642\u0648\u0627 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0625\u0646 \u0643\u0627\u0646\u0648\u0627 \u0645\u0624\u0645\u0646\u064a\u0646 \u062d\u0642\u0651\u064e \u0627\u0644\u0625\u064a\u0645\u0627\u0646.","5:113":"\u0642\u0627\u0644 \u0627\u0644\u062d\u0648\u0627\u0631\u064a\u0648\u0646: \u0646\u0631\u064a\u062f \u0623\u0646 \u0646\u0623\u0643\u0644 \u0645\u0646 \u0627\u0644\u0645\u0627\u0626\u062f\u0629 \u0648\u062a\u0633\u0643\u0646 \u0642\u0644\u0648\u0628\u0646\u0627 \u0644\u0631\u0624\u064a\u062a\u0647\u0627\u060c \u0648\u0646\u0639\u0644\u0645 \u064a\u0642\u064a\u0646\u0627 \u0635\u062f\u0642\u0643 \u0641\u064a \u0646\u0628\u0648\u062a\u0643\u060c \u0648\u0623\u0646 \u0646\u0643\u0648\u0646 \u0645\u0646 \u0627\u0644\u0634\u0627\u0647\u062f\u064a\u0646 \u0639\u0644\u0649 \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0623\u0646\u0632\u0644\u0647\u0627 \u062d\u062c\u0629 \u0644\u0647 \u0639\u0644\u064a\u0646\u0627 \u0641\u064a \u062a\u0648\u062d\u064a\u062f\u0647 \u0648\u0642\u062f\u0631\u062a\u0647 \u0639\u0644\u0649 \u0645\u0627 \u064a\u0634\u0627\u0621\u060c \u0648\u062d\u062c\u0629 \u0644\u0643 \u0639\u0644\u0649 \u0635\u062f\u0642\u0643 \u0641\u064a \u0646\u0628\u0648\u062a\u0643.","5:114":"\u0623\u062c\u0627\u0628 \u0639\u064a\u0633\u0649 \u0628\u0646 \u0645\u0631\u064a\u0645 \u0637\u0644\u0628 \u0627\u0644\u062d\u0648\u0627\u0631\u064a\u064a\u0646 \u0641\u062f\u0639\u0627 \u0631\u0628\u0647 \u062c\u0644 \u0648\u0639\u0644\u0627 \u0642\u0627\u0626\u0644\u0627: \u0631\u0628\u0646\u0627 \u0623\u0646\u0632\u0644 \u0639\u0644\u064a\u0646\u0627 \u0645\u0627\u0626\u062f\u0629 \u0637\u0639\u0627\u0645 \u0645\u0646 \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u0646\u062a\u062e\u0630 \u064a\u0648\u0645 \u0646\u0632\u0648\u0644\u0647\u0627 \u0639\u064a\u062f\u064b\u0627 \u0644\u0646\u0627\u060c \u0646\u0639\u0638\u0645\u0647 \u0646\u062d\u0646 \u0648\u0645\u064e\u0646 \u0628\u0639\u062f\u0646\u0627\u060c \u0648\u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0627\u0626\u062f\u0629 \u0639\u0644\u0627\u0645\u0629 \u0648\u062d\u062c\u0629 \u0645\u0646\u0643 -\u064a\u0627 \u0623\u0644\u0644\u0647- \u0639\u0644\u0649 \u0648\u062d\u062f\u0627\u0646\u064a\u062a\u0643 \u0648\u0639\u0644\u0649 \u0635\u062f\u0642 \u0646\u0628\u0648\u062a\u064a\u060c \u0648\u0627\u0645\u0646\u062d\u0646\u0627 \u0645\u0646 \u0639\u0637\u0627\u0626\u0643 \u0627\u0644\u062c\u0632\u064a\u0644\u060c \u0648\u0623\u0646\u062a \u062e\u064a\u0631 \u0627\u0644\u0631\u0627\u0632\u0642\u064a\u0646.","5:115":"\u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \u0625\u0646\u064a \u0645\u0646\u0632\u0644 \u0645\u0627\u0626\u062f\u0629 \u0627\u0644\u0637\u0639\u0627\u0645 \u0639\u0644\u064a\u0643\u0645\u060c \u0641\u0645\u0646 \u064a\u062c\u062d\u062f \u0645\u0646\u0643\u0645 \u0648\u062d\u062f\u0627\u0646\u064a\u062a\u064a \u0648\u0646\u0628\u0648\u0629 \u0639\u064a\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0628\u0639\u062f \u0646\u0632\u0648\u0644 \u0627\u0644\u0645\u0627\u0626\u062f\u0629 \u0641\u0625\u0646\u064a \u0623\u0639\u0630\u0628\u0647 \u0639\u0630\u0627\u0628\u064b\u0627 \u0634\u062f\u064a\u062f\u064b\u0627\u060c \u0644\u0627 \u0623\u0639\u0630\u0628\u0647 \u0623\u062d\u062f\u064b\u0627 \u0645\u0646 \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0646. \u0648\u0642\u062f \u0646\u0632\u0644\u062a \u0627\u0644\u0645\u0627\u0626\u062f\u0629 \u0643\u0645\u0627 \u0648\u0639\u062f \u0627\u0644\u0644\u0647.","5:116":"\u0648\u0627\u0630\u0643\u0631 \u0625\u0630 \u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629: \u064a\u0627 \u0639\u064a\u0633\u0649 \u0627\u0628\u0646 \u0645\u0631\u064a\u0645 \u0623\u0623\u0646\u062a \u0642\u0644\u062a \u0644\u0644\u0646\u0627\u0633 \u0627\u062c\u0639\u0644\u0648\u0646\u064a \u0648\u0623\u0645\u064a \u0645\u0639\u0628\u0648\u062f\u064a\u0646 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647\u061f \u0641\u0623\u062c\u0627\u0628 \u0639\u064a\u0633\u0649 -\u0645\u0646\u0632\u0651\u0650\u0647\u064b\u0627 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649-: \u0645\u0627 \u064a\u0646\u0628\u063a\u064a \u0644\u064a \u0623\u0646 \u0623\u0642\u0648\u0644 \u0644\u0644\u0646\u0627\u0633 \u063a\u064a\u0631 \u0627\u0644\u062d\u0642. \u0625\u0646 \u0643\u0646\u062a\u064f \u0642\u0644\u062a\u064f \u0647\u0630\u0627 \u0641\u0642\u062f \u0639\u0644\u0645\u062a\u064e\u0647; \u0644\u0623\u0646\u0647 \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0643 \u0634\u064a\u0621\u060c \u062a\u0639\u0644\u0645 \u0645\u0627 \u062a\u0636\u0645\u0631\u0647 \u0646\u0641\u0633\u064a\u060c \u0648\u0644\u0627 \u0623\u0639\u0644\u0645 \u0623\u0646\u0627 \u0645\u0627 \u0641\u064a \u0646\u0641\u0633\u0643. \u0625\u0646\u0643 \u0623\u0646\u062a \u0639\u0627\u0644\u0645\u064c \u0628\u0643\u0644 \u0634\u064a\u0621 \u0645\u0645\u0627 \u062e\u0641\u064a \u0623\u0648 \u0638\u0647\u0631.","5:117":"\u0642\u0627\u0644 \u0639\u064a\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645: \u064a\u0627 \u0631\u0628\u0651\u0650 \u0645\u0627 \u0642\u0644\u062a\u064f \u0644\u0647\u0645 \u0625\u0644\u0627 \u0645\u0627 \u0623\u0648\u062d\u064a\u062a\u0647 \u0625\u0644\u064a\u0651\u064e\u060c \u0648\u0623\u0645\u0631\u062a\u0646\u064a \u0628\u062a\u0628\u0644\u064a\u063a\u0647 \u0645\u0646 \u0625\u0641\u0631\u0627\u062f\u0643 \u0628\u0627\u0644\u062a\u0648\u062d\u064a\u062f \u0648\u0627\u0644\u0639\u0628\u0627\u062f\u0629\u060c \u0648\u0643\u0646\u062a\u064f \u0639\u0644\u0649 \u0645\u0627 \u064a\u0641\u0639\u0644\u0648\u0646\u0647 -\u0648\u0623\u0646\u0627 \u0628\u064a\u0646 \u0623\u0638\u0647\u0631\u0647\u0645- \u0634\u0627\u0647\u062f\u064b\u0627 \u0639\u0644\u064a\u0647\u0645 \u0648\u0639\u0644\u0649 \u0623\u0641\u0639\u0627\u0644\u0647\u0645 \u0648\u0623\u0642\u0648\u0627\u0644\u0647\u0645\u060c \u0641\u0644\u0645\u0627 \u0648\u0641\u064a\u062a\u0646\u064a \u0623\u062c\u0644\u064a \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0631\u0641\u0639\u062a\u0646\u064a \u0625\u0644\u0649 \u0627\u0644\u0633\u0645\u0627\u0621 \u062d\u064a\u0651\u064b\u0627\u060c \u0643\u0646\u062a \u0623\u0646\u062a \u0627\u0644\u0645\u0637\u0651\u064e\u0644\u0650\u0639 \u0639\u0644\u0649 \u0633\u0631\u0627\u0626\u0631\u0647\u0645\u060c \u0648\u0623\u0646\u062a \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621 \u0634\u0647\u064a\u062f\u060c \u0644\u0627 \u062a\u062e\u0641\u0649 \u0639\u0644\u064a\u0643 \u062e\u0627\u0641\u064a\u0629 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0648\u0644\u0627 \u0641\u064a \u0627\u0644\u0633\u0645\u0627\u0621.","5:118":"\u0625\u0646\u0643 \u064a\u0627 \u0623\u0644\u0644\u0647 \u0625\u0646 \u062a\u0639\u0630\u0628\u0647\u0645 \u0641\u0625\u0646\u0647\u0645 \u0639\u0628\u0627\u062f\u0643 -\u0648\u0623\u0646\u062a \u0623\u0639\u0644\u0645 \u0628\u0623\u062d\u0648\u0627\u0644\u0647\u0645-\u060c \u062a\u0641\u0639\u0644 \u0628\u0647\u0645 \u0645\u0627 \u062a\u0634\u0627\u0621 \u0628\u0639\u062f\u0644\u0643\u060c \u0648\u0625\u0646 \u062a\u063a\u0641\u0631 \u0628\u0631\u062d\u0645\u062a\u0643 \u0644\u0645\u0646 \u0623\u062a\u0649 \u0645\u0646\u0647\u0645 \u0628\u0623\u0633\u0628\u0627\u0628 \u0627\u0644\u0645\u063a\u0641\u0631\u0629\u060c \u0641\u0625\u0646\u0643 \u0623\u0646\u062a \u0627\u0644\u0639\u0632\u064a\u0632 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u063a\u0627\u0644\u064e\u0628\u064f\u060c \u0627\u0644\u062d\u0643\u064a\u0645 \u0641\u064a \u062a\u062f\u0628\u064a\u0631\u0647 \u0648\u0623\u0645\u0631\u0647. \u0648\u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629 \u062b\u0646\u0627\u0621 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 -\u062a\u0639\u0627\u0644\u0649- \u0628\u062d\u0643\u0645\u062a\u0647 \u0648\u0639\u062f\u0644\u0647\u060c \u0648\u0643\u0645\u0627\u0644 \u0639\u0644\u0645\u0647.","5:119":"\u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0639\u064a\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629: \u0647\u0630\u0627 \u064a\u0648\u0645 \u0627\u0644\u062c\u0632\u0627\u0621 \u0627\u0644\u0630\u064a \u064a\u0646\u0641\u0639 \u0627\u0644\u0645\u0648\u062d\u062f\u064a\u0646 \u062a\u0648\u062d\u064a\u062f\u0647\u0645 \u0631\u0628\u0647\u0645\u060c \u0648\u0627\u0646\u0642\u064a\u0627\u062f\u0647\u0645 \u0644\u0634\u0631\u0639\u0647\u060c \u0648\u0635\u062f\u0642\u0647\u0645 \u0641\u064a \u0646\u064a\u0627\u062a\u0647\u0645 \u0648\u0623\u0642\u0648\u0627\u0644\u0647\u0645 \u0648\u0623\u0639\u0645\u0627\u0644\u0647\u0645\u060c \u0644\u0647\u0645 \u062c\u0646\u0627\u062a \u062a\u062c\u0631\u064a \u0645\u0646 \u062a\u062d\u062a \u0642\u0635\u0648\u0631\u0647\u0627 \u0648\u0623\u0634\u062c\u0627\u0631\u0647\u0627 \u0627\u0644\u0623\u0646\u0647\u0627\u0631\u060c \u0645\u0627\u0643\u062b\u064a\u0646 \u0641\u064a\u0647\u0627 \u0623\u0628\u062f\u064b\u0627\u060c \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645 \u0641\u0642\u0628\u0644 \u062d\u0633\u0646\u0627\u062a\u0647\u0645\u060c \u0648\u0631\u0636\u0648\u0627 \u0639\u0646\u0647 \u0628\u0645\u0627 \u0623\u0639\u0637\u0627\u0647\u0645 \u0645\u0646 \u062c\u0632\u064a\u0644 \u062b\u0648\u0627\u0628\u0647. \u0630\u0644\u0643 \u0627\u0644\u062c\u0632\u0627\u0621 \u0648\u0627\u0644\u0631\u0636\u0627 \u0645\u0646\u0647 \u0639\u0644\u064a\u0647\u0645 \u0647\u0648 \u0627\u0644\u0641\u0648\u0632 \u0627\u0644\u0639\u0638\u064a\u0645.","5:120":"\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647 \u0645\u0644\u0643 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0648\u0645\u0627 \u0641\u064a\u0647\u0646\u060c \u0648\u0647\u0648 -\u0633\u0628\u062d\u0627\u0646\u0647- \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621 \u0642\u062f\u064a\u0631 \u0644\u0627 \u064a\u0639\u062c\u0632\u0647 \u0634\u064a\u0621.","6:1":"\u0627\u0644\u062b\u0646\u0627\u0621 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0628\u0635\u0641\u0627\u062a\u0647 \u0627\u0644\u062a\u064a \u0643\u0644\u0651\u0647\u0627 \u0623\u0648\u0635\u0627\u0641 \u0643\u0645\u0627\u0644\u060c \u0648\u0628\u0646\u0639\u0645\u0647 \u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0648\u0627\u0644\u0628\u0627\u0637\u0646\u0629\u060c \u0627\u0644\u062f\u064a\u0646\u064a\u0629 \u0648\u0627\u0644\u062f\u0646\u064a\u0648\u064a\u0629\u060c \u0627\u0644\u0630\u064a \u0623\u0646\u0634\u0623 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0648\u0645\u0627 \u0641\u064a\u0647\u0646\u060c \u0648\u062e\u0644\u0642 \u0627\u0644\u0638\u0644\u0645\u0627\u062a \u0648\u0627\u0644\u0646\u0648\u0631\u060c \u0648\u0630\u0644\u0643 \u0628\u062a\u0639\u0627\u0642\u0628 \u0627\u0644\u0644\u064a\u0644 \u0648\u0627\u0644\u0646\u0647\u0627\u0631. \u0648\u0641\u064a \u0647\u0630\u0627 \u062f\u0644\u0627\u0644\u0629 \u0639\u0644\u0649 \u0639\u0638\u0645\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0627\u0633\u062a\u062d\u0642\u0627\u0642\u0647 \u0648\u062d\u062f\u0647 \u0627\u0644\u0639\u0628\u0627\u062f\u0629\u060c \u0641\u0644\u0627 \u064a\u062c\u0648\u0632 \u0644\u0623\u062d\u062f \u0623\u0646 \u064a\u0634\u0631\u0643 \u0628\u0647 \u063a\u064a\u0631\u0647. \u0648\u0645\u0639 \u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0648\u062d \u0641\u0625\u0646 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u064a\u0633\u0648\u0648\u0646 \u0628\u0627\u0644\u0644\u0647 \u063a\u064a\u0631\u0647\u060c \u0648\u064a\u0634\u0631\u0643\u0648\u0646 \u0628\u0647.","6:2":"\u0647\u0648 \u0627\u0644\u0630\u064a \u062e\u0644\u0642 \u0623\u0628\u0627\u0643\u0645 \u0622\u062f\u0645 \u0645\u0646 \u0637\u064a\u0646 \u0648\u0623\u0646\u062a\u0645 \u0633\u0644\u0627\u0644\u0629 \u0645\u0646\u0647\u060c \u062b\u0645 \u0643\u062a\u0628 \u0645\u062f\u0629 \u0628\u0642\u0627\u0626\u0643\u0645 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0643\u062a\u0628 \u0623\u062c\u0644\u0627 \u0622\u062e\u0631 \u0645\u062d\u062f\u0651\u064e\u062f\u064b\u0627 \u0644\u0627 \u064a\u0639\u0644\u0645\u0647 \u0625\u0644\u0627 \u0647\u0648 \u062c\u0644 \u0648\u0639\u0644\u0627 \u0648\u0647\u0648 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u062b\u0645 \u0623\u0646\u062a\u0645 \u0628\u0639\u062f \u0647\u0630\u0627 \u062a\u0634\u0643\u0651\u064f\u0648\u0646 \u0641\u064a \u0642\u062f\u0631\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u0649 \u0627\u0644\u0628\u0639\u062b \u0628\u0639\u062f \u0627\u0644\u0645\u0648\u062a.","6:3":"\u0648\u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0647\u0648 \u0627\u0644\u0625\u0644\u0647 \u0627\u0644\u0645\u0639\u0628\u0648\u062f \u0641\u064a \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636. \u0648\u0645\u0646 \u062f\u0644\u0627\u0626\u0644 \u0623\u0644\u0648\u0647\u064a\u062a\u0647 \u0623\u0646\u0647 \u064a\u0639\u0644\u0645 \u062c\u0645\u064a\u0639 \u0645\u0627 \u062a\u062e\u0641\u0648\u0646\u0647 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633- \u0648\u0645\u0627 \u062a\u0639\u0644\u0646\u0648\u0646\u0647\u060c \u0648\u064a\u0639\u0644\u0645 \u062c\u0645\u064a\u0639 \u0623\u0639\u0645\u0627\u0644\u0643\u0645 \u0645\u0646 \u062e\u064a\u0631 \u0623\u0648 \u0634\u0631; \u0648\u0644\u0647\u0630\u0627 \u0641\u0625\u0646\u0647 -\u062c\u0644\u0651\u064e \u0648\u0639\u0644\u0627- \u0648\u062d\u062f\u0647 \u0647\u0648 \u0627\u0644\u0625\u0644\u0647 \u0627\u0644\u0645\u0633\u062a\u062d\u0642 \u0644\u0644\u0639\u0628\u0627\u062f\u0629.","6:4":"\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0641\u0627\u0631 \u0627\u0644\u0630\u064a\u0646 \u064a\u0634\u0631\u0643\u0648\u0646 \u0645\u0639 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u063a\u064a\u0631\u0647 \u0642\u062f \u062c\u0627\u0621\u062a\u0647\u0645 \u0627\u0644\u062d\u062c\u062c \u0627\u0644\u0648\u0627\u0636\u062d\u0629 \u0648\u0627\u0644\u062f\u0644\u0627\u0644\u0627\u062a \u0627\u0644\u0628\u064a\u0646\u0629 \u0639\u0644\u0649 \u0648\u062d\u062f\u0627\u0646\u064a\u0629 \u0627\u0644\u0644\u0647 -\u062c\u0644 \u0648\u0639\u0644\u0627- \u0648\u0635\u0650\u062f\u0652\u0642\u0650 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0641\u064a \u0646\u0628\u0648\u062a\u0647\u060c \u0648\u0645\u0627 \u062c\u0627\u0621 \u0628\u0647\u060c \u0648\u0644\u0643\u0646 \u0645\u0627 \u0625\u0646 \u062c\u0627\u0621\u062a\u0647\u0645 \u062d\u062a\u0649 \u0623\u0639\u0631\u0636\u0648\u0627 \u0639\u0646 \u0642\u0628\u0648\u0644\u0647\u0627\u060c \u0648\u0644\u0645 \u064a\u0624\u0645\u0646\u0648\u0627 \u0628\u0647\u0627.","6:5":"\u0644\u0642\u062f \u062c\u062d\u062f \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0641\u0627\u0631 \u0627\u0644\u062d\u0642\u0651\u064e \u0627\u0644\u0630\u064a \u062c\u0627\u0621\u0647\u0645 \u0628\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0633\u062e\u0631\u0648\u0627 \u0645\u0646 \u062f\u0639\u0627\u062a\u0647; \u062c\u0647\u0644\u0627 \u0645\u0646\u0647\u0645 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u063a\u062a\u0631\u0627\u0631\u064b\u0627 \u0628\u0625\u0645\u0647\u0627\u0644\u0647 \u0625\u064a\u0627\u0647\u0645\u060c \u0641\u0633\u0648\u0641 \u064a\u0631\u0648\u0646 \u0645\u0627 \u0627\u0633\u062a\u0647\u0632\u0621\u0648\u0627 \u0628\u0647 \u0623\u0646\u0647 \u0627\u0644\u062d\u0642 \u0648\u0627\u0644\u0635\u062f\u0642\u060c \u0648\u064a\u0628\u064a\u0646 \u0627\u0644\u0644\u0647 \u0644\u0644\u0645\u0643\u0630\u0628\u064a\u0646 \u0643\u0630\u0628\u0647\u0645 \u0648\u0627\u0641\u062a\u0631\u0627\u0621\u0647\u0645\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0647\u0645 \u0639\u0644\u064a\u0647.","6:6":"\u0623\u0644\u0645 \u064a\u0639\u0644\u0645 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u064a\u062c\u062d\u062f\u0648\u0646 \u0648\u062d\u062f\u0627\u0646\u064a\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0627\u0633\u062a\u062d\u0642\u0627\u0642\u0647 \u0648\u062d\u062f\u0647 \u0627\u0644\u0639\u0628\u0627\u062f\u0629\u060c \u0648\u064a\u0643\u0630\u0628\u0648\u0646 \u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f\u064b\u0627 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0645\u0627 \u062d\u0644\u0651\u064e \u0628\u0627\u0644\u0623\u0645\u0645 \u0627\u0644\u0645\u0643\u0630\u0628\u0629 \u0642\u0628\u0644\u0647\u0645 \u0645\u0646 \u0647\u0644\u0627\u0643 \u0648\u062a\u062f\u0645\u064a\u0631\u060c \u0648\u0642\u062f \u0645\u0643\u0646\u0651\u064e\u0627\u0647\u0645 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0645\u0627 \u0644\u0645 \u0646\u0645\u0643\u0646 \u0644\u0643\u0645 \u0623\u064a\u0647\u0627 \u0627\u0644\u0643\u0627\u0641\u0631\u0648\u0646\u060c \u0648\u0623\u0646\u0639\u0645\u0646\u0627 \u0639\u0644\u064a\u0647\u0645 \u0628\u0625\u0646\u0632\u0627\u0644 \u0627\u0644\u0623\u0645\u0637\u0627\u0631 \u0648\u062c\u0631\u064a\u0627\u0646 \u0627\u0644\u0623\u0646\u0647\u0627\u0631 \u0645\u0646 \u062a\u062d\u062a \u0645\u0633\u0627\u0643\u0646\u0647\u0645\u061b \u0627\u0633\u062a\u062f\u0631\u0627\u062c\u064b\u0627 \u0648\u0625\u0645\u0644\u0627\u0621\u064b \u0644\u0647\u0645\u060c \u0641\u0643\u0641\u0631\u0648\u0627 \u0628\u0646\u0639\u0645 \u0627\u0644\u0644\u0647 \u0648\u0643\u0630\u0628\u0648\u0627 \u0627\u0644\u0631\u0633\u0644\u060c \u0641\u0623\u0647\u0644\u0643\u0646\u0627\u0647\u0645 \u0628\u0633\u0628\u0628 \u0630\u0646\u0648\u0646\u0647\u0645\u060c \u0648\u0623\u0646\u0634\u0623\u0646\u0627 \u0645\u0646 \u0628\u0639\u062f\u0647\u0645 \u0623\u0645\u0645\u064b\u0627 \u0623\u062e\u0631\u0649 \u062e\u0644\u0641\u0648\u0647\u0645 \u0641\u064a \u0639\u0645\u0627\u0631\u0629 \u0627\u0644\u0623\u0631\u0636\u061f","6:7":"\u0648\u0644\u0648 \u0646\u0632\u0651\u064e\u0644\u0646\u0627 \u0639\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0643\u062a\u0627\u0628\u064b\u0627 \u0645\u0646 \u0627\u0644\u0633\u0645\u0627\u0621 \u0641\u064a \u0623\u0648\u0631\u0627\u0642 \u0641\u0644\u0645\u0633\u0647 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0628\u0623\u064a\u062f\u064a\u0647\u0645 \u0644\u0642\u0627\u0644\u0648\u0627: \u0625\u0646\u0651\u064e \u0645\u0627 \u062c\u0626\u062a \u0628\u0647 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0633\u062d\u0631 \u0648\u0627\u0636\u062d \u0628\u064a\u0651\u0650\u0646.","6:8":"\u0648\u0642\u0627\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646: \u0647\u0644\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u0649 \u0645\u062d\u0645\u062f \u0645\u064e\u0644\u064e\u0643\u064b\u0627 \u0645\u0646 \u0627\u0644\u0633\u0645\u0627\u0621; \u0644\u064a\u0635\u062f\u0642\u0647 \u0641\u064a\u0645\u0627 \u062c\u0627\u0621 \u0628\u0647 \u0645\u0646 \u0627\u0644\u0646\u0628\u0648\u0629\u060c \u0648\u0644\u0648 \u0623\u0646\u0632\u0644\u0646\u0627 \u0645\u064e\u0644\u064e\u0643\u0651\u064b\u0627 \u0645\u0646 \u0627\u0644\u0633\u0645\u0627\u0621 \u0625\u062c\u0627\u0628\u0629 \u0644\u0637\u0644\u0628\u0647\u0645 \u0644\u0642\u0636\u064a \u0627\u0644\u0623\u0645\u0631 \u0628\u0625\u0647\u0644\u0627\u0643\u0647\u0645\u060c \u062b\u0645 \u0644\u0627 \u064a\u0645\u0647\u0644\u0648\u0646 \u0644\u062a\u0648\u0628\u0629\u060c \u0641\u0642\u062f \u0633\u0628\u0642 \u0641\u064a \u0639\u0644\u0645 \u0627\u0644\u0644\u0647 \u0623\u0646\u0647\u0645 \u0644\u0627 \u064a\u0624\u0645\u0646\u0648\u0646.","6:9":"\u0648\u0644\u0648 \u062c\u0639\u0644\u0646\u0627 \u0627\u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0645\u0631\u0633\u0644 \u0625\u0644\u064a\u0647\u0645 \u0645\u064e\u0644\u064e\u0643\u064b\u0627 \u0625\u0630 \u0644\u0645 \u064a\u0642\u062a\u0646\u0639\u0648\u0627 \u0628\u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0644\u062c\u0639\u0644\u0646\u0627 \u0630\u0644\u0643 \u0627\u0644\u0645\u0644\u0643 \u0641\u064a \u0635\u0648\u0631\u0629 \u0627\u0644\u0628\u0634\u0631\u060c \u062d\u062a\u0649 \u064a\u0633\u062a\u0637\u064a\u0639\u0648\u0627 \u0627\u0644\u0633\u0645\u0627\u0639 \u0645\u0646\u0647 \u0648\u0645\u062e\u0627\u0637\u0628\u062a\u0647; \u0625\u0630 \u0644\u064a\u0633 \u0628\u0625\u0645\u0643\u0627\u0646\u0647\u0645 \u0631\u0624\u064a\u0629 \u0627\u0644\u0645\u0644\u0643 \u0639\u0644\u0649 \u0635\u0648\u0631\u062a\u0647 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u064a\u0629\u060c \u0648\u0644\u0648 \u062c\u0627\u0621\u0647\u0645 \u0627\u0644\u0645\u0644\u0643 \u0628\u0635\u0648\u0631\u0629 \u0631\u062c\u0644 \u0644\u0627\u0634\u062a\u0628\u0647 \u0627\u0644\u0623\u0645\u0631 \u0639\u0644\u064a\u0647\u0645\u060c \u0643\u0645\u0627 \u0627\u0634\u062a\u0628\u0647 \u0639\u0644\u064a\u0647\u0645 \u0623\u0645\u0631 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645.","6:10":"\u0648\u0644\u0645\u0651\u064e\u0627 \u0643\u0627\u0646 \u0637\u0644\u0628\u0647\u0645 \u0625\u0646\u0632\u0627\u0644 \u0627\u0644\u0645\u0644\u0643 \u0639\u0644\u0649 \u0633\u0628\u064a\u0644 \u0627\u0644\u0627\u0633\u062a\u0647\u0632\u0627\u0621 \u0628\u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0628\u064a\u0651\u064e\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0647 \u0623\u0646 \u0627\u0644\u0627\u0633\u062a\u0647\u0632\u0627\u0621 \u0628\u0627\u0644\u0631\u0633\u0644 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0633\u0644\u0627\u0645 \u0644\u064a\u0633 \u0623\u0645\u0631\u0627 \u062d\u0627\u062f\u062b\u0627\u060c \u0628\u0644 \u0642\u062f \u0648\u0642\u0639 \u0645\u0646 \u0627\u0644\u0643\u0641\u0627\u0631 \u0627\u0644\u0633\u0627\u0628\u0642\u064a\u0646 \u0645\u0639 \u0623\u0646\u0628\u064a\u0627\u0626\u0647\u0645\u060c \u0641\u0623\u062d\u0627\u0637 \u0628\u0647\u0645 \u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0630\u064a \u0643\u0627\u0646\u0648\u0627 \u064a\u0647\u0632\u0624\u0648\u0646 \u0628\u0647 \u0648\u064a\u0646\u0643\u0631\u0648\u0646 \u0648\u0642\u0648\u0639\u0647.","6:11":"\u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0633\u064a\u0631\u0648\u0627 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u062b\u0645 \u0627\u0646\u0638\u0631\u0648\u0627 \u0643\u064a\u0641 \u0623\u0639\u0642\u0628 \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0643\u0630\u0628\u064a\u0646 \u0627\u0644\u0647\u0644\u0627\u0643 \u0648\u0627\u0644\u062e\u0632\u064a\u061f \u0641\u0627\u062d\u0630\u0631\u0648\u0627 \u0645\u062b\u0644 \u0645\u0635\u0627\u0631\u0639\u0647\u0645\u060c \u0648\u062e\u0627\u0641\u0648\u0627 \u0623\u0646 \u064a\u062d\u0644\u0651\u064e \u0628\u0643\u0645 \u0645\u062b\u0644 \u0627\u0644\u0630\u064a \u062d\u0644 \u0628\u0647\u0645.","6:12":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0644\u0645\u0646 \u0645\u064f\u0644\u0643\u064f \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0648\u0645\u0627 \u0641\u064a\u0647\u0646\u061f \u0642\u0644: \u0647\u0648 \u0644\u0644\u0647 \u0643\u0645\u0627 \u062a\u0642\u0631\u0648\u0646 \u0628\u0630\u0644\u0643 \u0648\u062a\u0639\u0644\u0645\u0648\u0646\u0647\u060c \u0641\u0627\u0639\u0628\u062f\u0648\u0647 \u0648\u062d\u062f\u0647. \u0643\u062a\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0646\u0641\u0633\u0647 \u0627\u0644\u0631\u062d\u0645\u0629 \u0641\u0644\u0627 \u064a\u0639\u062c\u0644 \u0639\u0644\u0649 \u0639\u0628\u0627\u062f\u0647 \u0628\u0627\u0644\u0639\u0642\u0648\u0628\u0629. \u0644\u064a\u062c\u0645\u0639\u0646\u0643\u0645 \u0625\u0644\u0649 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0627\u0644\u0630\u064a \u0644\u0627 \u0634\u0643 \u0641\u064a\u0647 \u0644\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u062c\u0632\u0627\u0621. \u0627\u0644\u0630\u064a\u0646 \u0623\u0634\u0631\u0643\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0623\u0647\u0644\u0643\u0648\u0627 \u0623\u0646\u0641\u0633\u0647\u0645\u060c \u0641\u0647\u0645 \u0644\u0627 \u064a\u0648\u062d\u062f\u0648\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u064a\u0635\u062f\u0642\u0648\u0646 \u0628\u0648\u0639\u062f\u0647 \u0648\u0648\u0639\u064a\u062f\u0647\u060c \u0648\u0644\u0627 \u064a\u0642\u0631\u0648\u0646 \u0628\u0646\u0628\u0648\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645.","6:13":"\u0648\u0644\u0644\u0647 \u0645\u0644\u0643 \u0643\u0644 \u0634\u064a\u0621 \u0641\u064a \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636\u060c \u0633\u0643\u0646 \u0623\u0648 \u062a\u062d\u0631\u0643\u060c \u062e\u0641\u064a \u0623\u0648 \u0638\u0647\u0631\u060c \u0627\u0644\u062c\u0645\u064a\u0639 \u0639\u0628\u064a\u062f\u0647 \u0648\u062e\u0644\u0642\u0647\u060c \u0648\u062a\u062d\u062a \u0642\u0647\u0631\u0647 \u0648\u062a\u0635\u0631\u0641\u0647 \u0648\u062a\u062f\u0628\u064a\u0631\u0647\u060c \u0648\u0647\u0648 \u0627\u0644\u0633\u0645\u064a\u0639 \u0644\u0623\u0642\u0648\u0627\u0644 \u0639\u0628\u0627\u062f\u0647\u060c \u0627\u0644\u062d\u0644\u064a\u0645 \u0628\u062d\u0631\u0643\u0627\u062a\u0647\u0645 \u0648\u0633\u0631\u0627\u0626\u0631\u0647\u0645.","6:14":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0645\u0639 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u063a\u064a\u0631\u0647: \u0623\u063a\u064a\u0631 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0623\u062a\u062e\u0630 \u0648\u0644\u064a\u0651\u064b\u0627 \u0648\u0646\u0635\u064a\u0631\u064b\u0627\u060c \u0648\u0647\u0648 \u062e\u0627\u0644\u0642 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0648\u0645\u0627 \u0641\u064a\u0647\u0646\u060c \u0648\u0647\u0648 \u0627\u0644\u0630\u064a \u064a\u0631\u0632\u0642 \u062e\u0644\u0642\u0647 \u0648\u0644\u0627 \u064a\u0631\u0632\u0642\u0647 \u0623\u062d\u062f\u061f \u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0625\u0646\u064a \u0623\u064f\u0645\u0650\u0631\u0652\u062a\u064f \u0623\u0646 \u0623\u0643\u0648\u0646 \u0623\u0648\u0644 \u0645\u064e\u0646 \u062e\u0636\u0639 \u0648\u0627\u0646\u0642\u0627\u062f \u0644\u0647 \u0628\u0627\u0644\u0639\u0628\u0648\u062f\u064a\u0629 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0629\u060c \u0648\u0646\u0647\u064a\u062a \u0623\u0646 \u0623\u0643\u0648\u0646 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0645\u0639\u0647 \u063a\u064a\u0631\u0647.","6:15":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0645\u0639 \u0627\u0644\u0644\u0647 \u063a\u064a\u0631\u0647: \u0625\u0646\u064a \u0623\u062e\u0627\u0641 \u0625\u0646 \u0639\u0635\u064a\u062a \u0631\u0628\u064a\u060c \u0641\u062e\u0627\u0644\u0641\u062a \u0623\u0645\u0631\u0647\u060c \u0648\u0623\u0634\u0631\u0643\u062a \u0645\u0639\u0647 \u063a\u064a\u0631\u0647 \u0641\u064a \u0639\u0628\u0627\u062f\u062a\u0647\u060c \u0623\u0646 \u064a\u0646\u0632\u0644 \u0628\u064a \u0639\u0630\u0627\u0628 \u0639\u0638\u064a\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629.","6:16":"\u0645\u0646 \u064a\u0635\u0631\u0641 \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0630\u0644\u0643 \u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0634\u062f\u064a\u062f \u0641\u0642\u062f \u0631\u062d\u0645\u0647\u060c \u0648\u0630\u0644\u0643 \u0627\u0644\u0635\u0631\u0641 \u0647\u0648 \u0627\u0644\u0638\u0641\u0631 \u0627\u0644\u0628\u064a\u0646 \u0628\u0627\u0644\u0646\u062c\u0627\u0629 \u0645\u0646 \u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0639\u0638\u064a\u0645.","6:17":"\u0648\u0625\u0646 \u064a\u0635\u0628\u0643 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0625\u0646\u0633\u0627\u0646- \u0628\u0634\u064a\u0621 \u064a\u0636\u0631\u0643 \u0643\u0627\u0644\u0641\u0642\u0631 \u0648\u0627\u0644\u0645\u0631\u0636 \u0641\u0644\u0627 \u0643\u0627\u0634\u0641 \u0644\u0647 \u0625\u0644\u0627 \u0647\u0648\u060c \u0648\u0625\u0646 \u064a\u0635\u0628\u0643 \u0628\u062e\u064a\u0631 \u0643\u0627\u0644\u063a\u0646\u0649 \u0648\u0627\u0644\u0635\u062d\u0629 \u0641\u0644\u0627 \u0631\u0627\u062f \u0644\u0641\u0636\u0644\u0647 \u0648\u0644\u0627 \u0645\u0627\u0646\u0639 \u0644\u0642\u0636\u0627\u0626\u0647\u060c \u0641\u0647\u0648 -\u062c\u0644 \u0648\u0639\u0644\u0627- \u0627\u0644\u0642\u0627\u062f\u0631 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621.","6:18":"\u0648\u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0647\u0648 \u0627\u0644\u063a\u0627\u0644\u0628 \u0627\u0644\u0642\u0627\u0647\u0631 \u0641\u0648\u0642 \u0639\u0628\u0627\u062f\u0647; \u062e\u0636\u0639\u062a \u0644\u0647 \u0627\u0644\u0631\u0642\u0627\u0628 \u0648\u0630\u064e\u0644\u0651\u064e\u062a\u0652 \u0644\u0647 \u0627\u0644\u062c\u0628\u0627\u0628\u0631\u0629\u060c \u0648\u0647\u0648 \u0627\u0644\u062d\u0643\u064a\u0645 \u0627\u0644\u0630\u064a \u064a\u0636\u0639 \u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0645\u0648\u0627\u0636\u0639\u0647\u0627 \u0648\u064e\u0641\u0652\u0642 \u062d\u0643\u0645\u062a\u0647\u060c \u0627\u0644\u062e\u0628\u064a\u0631 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0634\u064a\u0621. \u0648\u0645\u0646 \u0627\u062a\u0635\u0641 \u0628\u0647\u0630\u0647 \u0627\u0644\u0635\u0641\u0627\u062a \u064a\u062c\u0628 \u0623\u0644\u0627 \u064a\u0634\u0631\u0643 \u0628\u0647. \u0648\u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629 \u0625\u062b\u0628\u0627\u062a \u0627\u0644\u0641\u0648\u0642\u064a\u0629 \u0644\u0644\u0647 -\u062a\u0639\u0627\u0644\u0649- \u0639\u0644\u0649 \u062c\u0645\u064a\u0639 \u062e\u0644\u0642\u0647\u060c \u0641\u0648\u0642\u064a\u0629 \u0645\u0637\u0644\u0642\u0629 \u062a\u0644\u064a\u0642 \u0628\u062c\u0644\u0627\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647.","6:19":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644 \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646-: \u0623\u064a\u0651\u064f \u0634\u064a\u0621 \u0623\u0639\u0638\u0645 \u0634\u0647\u0627\u062f\u0629 \u0641\u064a \u0625\u062b\u0628\u0627\u062a \u0635\u062f\u0642\u064a \u0641\u064a\u0645\u0627 \u0623\u062e\u0628\u0631\u062a\u0643\u0645 \u0628\u0647 \u0623\u0646\u064a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u061f \u0642\u0644: \u0627\u0644\u0644\u0647 \u0634\u0647\u064a\u062f \u0628\u064a\u0646\u064a \u0648\u0628\u064a\u0646\u0643\u0645 \u0623\u064a: \u0647\u0648 \u0627\u0644\u0639\u0627\u0644\u0645 \u0628\u0645\u0627 \u062c\u0626\u062a\u0643\u0645 \u0628\u0647 \u0648\u0645\u0627 \u0623\u0646\u062a\u0645 \u0642\u0627\u0626\u0644\u0648\u0646\u0647 \u0644\u064a\u060c \u0648\u0623\u0648\u062d\u0649 \u0627\u0644\u0644\u0647 \u0625\u0644\u064a\u0651\u064e \u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0622\u0646 \u0645\u0650\u0646 \u0623\u062c\u0644 \u0623\u0646 \u0623\u0646\u0630\u0631\u0643\u0645 \u0628\u0647 \u0639\u0630\u0627\u0628\u0647 \u0623\u0646 \u064a\u062d\u0644\u0651\u064e \u0628\u0643\u0645\u060c \u0648\u0623\u0646\u0630\u0631 \u0628\u0647 \u0645\u064e\u0646 \u0648\u0635\u0644 \u0625\u0644\u064a\u0647 \u0645\u0646 \u0627\u0644\u0623\u0645\u0645. \u0625\u0646\u0643\u0645 \u0644\u062a\u0642\u0631\u0648\u0646 \u0623\u0646 \u0645\u0639 \u0627\u0644\u0644\u0647 \u0645\u0639\u0628\u0648\u062f\u0627\u062a \u0623\u062e\u0631\u0649 \u062a\u0634\u0631\u0643\u0648\u0646\u0647\u0627 \u0628\u0647. \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0625\u0646\u064a \u0644\u0627 \u0623\u0634\u0647\u062f \u0639\u0644\u0649 \u0645\u0627 \u0623\u0642\u0631\u0631\u062a\u0645 \u0628\u0647\u060c \u0625\u0646\u0645\u0627 \u0627\u0644\u0644\u0647 \u0625\u0644\u0647 \u0648\u0627\u062d\u062f \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647\u060c \u0648\u0625\u0646\u0646\u064a \u0628\u0631\u064a\u0621 \u0645\u0646 \u0643\u0644 \u0634\u0631\u064a\u0643 \u062a\u0639\u0628\u062f\u0648\u0646\u0647 \u0645\u0639\u0647.","6:20":"\u0627\u0644\u0630\u064a\u0646 \u0622\u062a\u064a\u0646\u0627\u0647\u0645 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644\u060c \u064a\u0639\u0631\u0641\u0648\u0646 \u0645\u062d\u0645\u062f\u064b\u0627 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0628\u0635\u0641\u0627\u062a\u0647 \u0627\u0644\u0645\u0643\u062a\u0648\u0628\u0629 \u0639\u0646\u062f\u0647\u0645 \u0643\u0645\u0639\u0631\u0641\u062a\u0647\u0645 \u0623\u0628\u0646\u0627\u0621\u0647\u0645\u060c \u0641\u0643\u0645\u0627 \u0623\u0646 \u0623\u0628\u0646\u0627\u0621\u0647\u0645 \u0644\u0627 \u064a\u0634\u062a\u0628\u0647\u0648\u0646 \u0623\u0645\u0627\u0645\u0647\u0645 \u0628\u063a\u064a\u0631\u0647\u0645\u060c \u0641\u0643\u0630\u0644\u0643 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0644\u0627 \u064a\u0634\u062a\u0628\u0647 \u0628\u063a\u064a\u0631\u0647 \u0644\u062f\u0642\u0629 \u0648\u0635\u0641\u0647 \u0641\u064a \u0643\u062a\u0628\u0647\u0645\u060c \u0648\u0644\u0643\u0646\u0647\u0645 \u0627\u062a\u0628\u0639\u0648\u0627 \u0623\u0647\u0648\u0627\u0621\u0647\u0645\u060c \u0641\u062e\u0633\u0631\u0648\u0627 \u0623\u0646\u0641\u0633\u0647\u0645 \u062d\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0628\u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0628\u0645\u0627 \u062c\u0627\u0621 \u0628\u0647.","6:21":"\u0644\u0627 \u0623\u062d\u062f \u0623\u0634\u062f \u0638\u0644\u0645\u064b\u0627 \u0645\u0645\u0651\u064e\u0646 \u062a\u064e\u0642\u064e\u0648\u0651\u064e\u0644\u064e \u0627\u0644\u0643\u0630\u0628 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0641\u0632\u0639\u0645 \u0623\u0646 \u0644\u0647 \u0634\u0631\u0643\u0627\u0621 \u0641\u064a \u0627\u0644\u0639\u0628\u0627\u062f\u0629\u060c \u0623\u0648 \u0627\u062f\u0651\u064e\u0639\u0649 \u0623\u0646 \u0644\u0647 \u0648\u0644\u062f\u064b\u0627 \u0623\u0648 \u0635\u0627\u062d\u0628\u0629\u060c \u0623\u0648 \u0643\u0630\u0628 \u0628\u0628\u0631\u0627\u0647\u064a\u0646\u0647 \u0648\u0623\u062f\u0644\u062a\u0647 \u0627\u0644\u062a\u064a \u0623\u064a\u0651\u064e\u062f \u0628\u0647\u0627 \u0631\u0633\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0633\u0644\u0627\u0645. \u0625\u0646\u0647 \u0644\u0627 \u064a\u0641\u0644\u062d \u0627\u0644\u0638\u0627\u0644\u0645\u0648\u0646 \u0627\u0644\u0630\u064a\u0646 \u0627\u0641\u062a\u0631\u0648\u0627 \u0627\u0644\u0643\u0630\u0628 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u064a\u0638\u0641\u0631\u0648\u0646 \u0628\u0645\u0637\u0627\u0644\u0628\u0647\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0644\u0627 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629.","6:22":"\u0648\u0644\u064a\u062d\u0630\u0631 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0627\u0644\u0645\u0643\u0630\u0628\u0648\u0646 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u064a\u0648\u0645 \u0646\u062d\u0634\u0631\u0647\u0645 \u062b\u0645 \u0646\u0642\u0648\u0644 \u0644\u0647\u0645: \u0623\u064a\u0646 \u0622\u0644\u0647\u062a\u0643\u0645 \u0627\u0644\u062a\u064a \u0643\u0646\u062a\u0645 \u062a\u062f\u0651\u064e\u0639\u0648\u0646 \u0623\u0646\u0647\u0645 \u0634\u0631\u0643\u0627\u0621 \u0645\u0639 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u064a\u0634\u0641\u0639\u0648\u0627 \u0644\u0643\u0645\u061f","6:23":"\u062b\u0645 \u0644\u0645 \u062a\u0643\u0646 \u0625\u062c\u0627\u0628\u062a\u0647\u0645 \u062d\u064a\u0646 \u0641\u062a\u0646\u0648\u0627 \u0648\u0627\u062e\u062a\u0628\u0631\u0648\u0627 \u0628\u0627\u0644\u0633\u0624\u0627\u0644 \u0639\u0646 \u0634\u0631\u0643\u0627\u0626\u0647\u0645 \u0625\u0644\u0627 \u0623\u0646 \u062a\u0628\u0631\u0624\u0648\u0627 \u0645\u0646\u0647\u0645\u060c \u0648\u0623\u0642\u0633\u0645\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0631\u0628\u0647\u0645 \u0623\u0646\u0647\u0645 \u0644\u0645 \u064a\u0643\u0648\u0646\u0648\u0627 \u0645\u0634\u0631\u0643\u064a\u0646 \u0645\u0639 \u0627\u0644\u0644\u0647 \u063a\u064a\u0631\u0647.","6:24":"\u062a\u0623\u0645\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0643\u064a\u0641 \u0643\u0630\u0628 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0639\u0644\u0649 \u0623\u0646\u0641\u0633\u0647\u0645 \u0648\u0647\u0645 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0642\u062f \u062a\u0628\u0631\u0624\u0648\u0627 \u0645\u0646 \u0627\u0644\u0634\u0631\u0643\u061f \u0648\u0630\u0647\u0628 \u0648\u063a\u0627\u0628 \u0639\u0646\u0647\u0645 \u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u064a\u0638\u0646\u0648\u0646\u0647 \u0645\u0646 \u0634\u0641\u0627\u0639\u0629 \u0622\u0644\u0647\u062a\u0647\u0645.","6:25":"\u0648\u0645\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0645\u0646 \u064a\u0633\u062a\u0645\u0639 \u0625\u0644\u064a\u0643 \u0627\u0644\u0642\u0631\u0622\u0646 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-\u060c \u0641\u0644\u0627 \u064a\u0635\u0644 \u0625\u0644\u0649 \u0642\u0644\u0648\u0628\u0647\u0645; \u0644\u0623\u0646\u0647\u0645 \u0628\u0633\u0628\u0628 \u0627\u062a\u0628\u0627\u0639\u0647\u0645 \u0623\u0647\u0648\u0627\u0621\u0647\u0645 \u062c\u0639\u0644\u0646\u0627 \u0639\u0644\u0649 \u0642\u0644\u0648\u0628\u0647\u0645 \u0623\u063a\u0637\u064a\u0629; \u0644\u0626\u0644\u0627 \u064a\u0641\u0642\u0647\u0648\u0627 \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0648\u062c\u0639\u0644\u0646\u0627 \u0641\u064a \u0622\u0630\u0627\u0646\u0647\u0645 \u062b\u0642\u0644\u0627 \u0648\u0635\u0645\u0645\u064b\u0627 \u0641\u0644\u0627 \u062a\u0633\u0645\u0639 \u0648\u0644\u0627 \u062a\u0639\u064a \u0634\u064a\u0626\u064b\u0627\u060c \u0648\u0625\u0646 \u064a\u0631\u0648\u0627 \u0627\u0644\u0622\u064a\u0627\u062a \u0627\u0644\u0643\u062b\u064a\u0631\u0629 \u0627\u0644\u062f\u0627\u0644\u0629 \u0639\u0644\u0649 \u0635\u062f\u0642 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0644\u0627 \u064a\u0635\u062f\u0642\u0648\u0627 \u0628\u0647\u0627\u060c \u062d\u062a\u0649 \u0625\u0630\u0627 \u062c\u0627\u0624\u0648\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0628\u0639\u062f \u0645\u0639\u0627\u064a\u0646\u0629 \u0627\u0644\u0622\u064a\u0627\u062a \u0627\u0644\u062f\u0627\u0644\u0629 \u0639\u0644\u0649 \u0635\u062f\u0642\u0643 \u064a\u062e\u0627\u0635\u0645\u0648\u0646\u0643: \u064a\u0642\u0648\u0644 \u0627\u0644\u0630\u064a\u0646 \u062c\u062d\u062f\u0648\u0627 \u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647: \u0645\u0627 \u0647\u0630\u0627 \u0627\u0644\u0630\u064a \u0646\u0633\u0645\u0639 \u0625\u0644\u0627 \u0645\u0627 \u062a\u0646\u0627\u0642\u0644\u0647 \u0627\u0644\u0623\u0648\u0644\u0648\u0646 \u0645\u0646 \u062d\u0643\u0627\u064a\u0627\u062a \u0644\u0627 \u062d\u0642\u064a\u0642\u0629 \u0644\u0647\u0627.","6:26":"\u0648\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u064a\u0646\u0647\u0648\u0646 \u0627\u0644\u0646\u0627\u0633 \u0639\u0646 \u0627\u062a\u0628\u0627\u0639 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0625\u0644\u064a\u0647\u060c \u0648\u064a\u0628\u062a\u0639\u062f\u0648\u0646 \u0628\u0623\u0646\u0641\u0633\u0647\u0645 \u0639\u0646\u0647\u060c \u0648\u0645\u0627 \u064a\u0647\u0644\u0643\u0648\u0646 -\u0628\u0635\u062f\u0647\u0645 \u0639\u0646 \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647- \u0625\u0644\u0627 \u0623\u0646\u0641\u0633\u0647\u0645\u060c \u0648\u0645\u0627 \u064a\u062d\u0633\u0648\u0646 \u0623\u0646\u0647\u0645 \u064a\u0639\u0645\u0644\u0648\u0646 \u0644\u0647\u0644\u0627\u0643\u0647\u0627.","6:27":"\u0648\u0644\u0648 \u062a\u0631\u0649 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0644\u0631\u0623\u064a\u062a \u0623\u0645\u0631\u064b\u0627 \u0639\u0638\u064a\u0645\u064b\u0627\u060c \u0648\u0630\u0644\u0643 \u062d\u064a\u0646 \u064a\u064f\u062d\u0652\u0628\u064e\u0633\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0646\u0627\u0631\u060c \u0648\u064a\u0634\u0627\u0647\u062f\u0648\u0646 \u0645\u0627 \u0641\u064a\u0647\u0627 \u0645\u0646 \u0627\u0644\u0633\u0644\u0627\u0633\u0644 \u0648\u0627\u0644\u0623\u063a\u0644\u0627\u0644\u060c \u0648\u0631\u0623\u0648\u0627 \u0628\u0623\u0639\u064a\u0646\u0647\u0645 \u062a\u0644\u0643 \u0627\u0644\u0623\u0645\u0648\u0631 \u0627\u0644\u0639\u0638\u0627\u0645 \u0648\u0627\u0644\u0623\u0647\u0648\u0627\u0644\u060c \u0641\u0639\u0646\u062f \u0630\u0644\u0643 \u0642\u0627\u0644\u0648\u0627: \u064a\u0627\u0644\u064a\u062a\u0646\u0627 \u0646\u064f\u0639\u0627\u062f \u0625\u0644\u0649 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0641\u0646\u0635\u062f\u0642 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0648\u0646\u0639\u0645\u0644 \u0628\u0647\u0627\u060c \u0648\u0646\u0643\u0648\u0646 \u0645\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646.","6:28":"\u0644\u064a\u0633 \u0627\u0644\u0623\u0645\u0631 \u0643\u0630\u0644\u0643\u060c \u0628\u0644 \u0638\u0647\u0631 \u0644\u0647\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u064a\u0639\u0644\u0645\u0648\u0646\u0647 \u0645\u0646 \u0623\u0646\u0641\u0633\u0647\u0645 \u0645\u0646 \u0635\u062f\u0642 \u0645\u0627 \u062c\u0627\u0621\u062a \u0628\u0647 \u0627\u0644\u0631\u0633\u0644 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0625\u0646 \u0643\u0627\u0646\u0648\u0627 \u064a\u0638\u0647\u0631\u0648\u0646 \u0644\u0623\u062a\u0628\u0627\u0639\u0647 \u062e\u0644\u0627\u0641\u0647. \u0648\u0644\u0648 \u0641\u0631\u0636 \u0623\u0646 \u0623\u0639\u064a\u062f\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u062f\u0646\u064a\u0627 \u0641\u0623\u0645\u0647\u0644\u0648\u0627 \u0644\u0631\u062c\u0639\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0639\u0646\u0627\u062f \u0628\u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u062a\u0643\u0630\u064a\u0628. \u0648\u0625\u0646\u0647\u0645 \u0644\u0643\u0627\u0630\u0628\u0648\u0646 \u0641\u064a \u0642\u0648\u0644\u0647\u0645: \u0644\u0648 \u0631\u062f\u062f\u0646\u0627 \u0625\u0644\u0649 \u0627\u0644\u062f\u0646\u064a\u0627 \u0644\u0645 \u0646\u0643\u0630\u0628 \u0628\u0622\u064a\u0627\u062a \u0631\u0628\u0646\u0627\u060c \u0648\u0643\u0646\u0627 \u0645\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646.","6:29":"\u0648\u0642\u0627\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0627\u0644\u0645\u0646\u0643\u0631\u0648\u0646 \u0644\u0644\u0628\u0639\u062b: \u0645\u0627 \u0627\u0644\u062d\u064a\u0627\u0629 \u0625\u0644\u0627 \u0647\u0630\u0647 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062a\u064a \u0646\u062d\u0646 \u0641\u064a\u0647\u0627\u060c \u0648\u0645\u0627 \u0646\u062d\u0646 \u0628\u0645\u0628\u0639\u0648\u062b\u064a\u0646 \u0628\u0639\u062f \u0645\u0648\u062a\u0646\u0627.","6:30":"\u0648\u0644\u0648 \u062a\u0631\u0649 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u0646\u0643\u0631\u064a \u0627\u0644\u0628\u0639\u062b \u0625\u0630 \u062d\u064f\u0628\u0633\u0648\u0627 \u0628\u064a\u0646 \u064a\u062f\u064a \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0642\u0636\u0627\u0626\u0647 \u0641\u064a\u0647\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0644\u0631\u0623\u064a\u062a \u0623\u0633\u0648\u0623 \u062d\u0627\u0644\u060c \u0625\u0630 \u064a\u0642\u0648\u0644 \u0627\u0644\u0644\u0647 \u062c\u0644 \u0648\u0639\u0644\u0627 \u0623\u0644\u064a\u0633 \u0647\u0630\u0627 \u0628\u0627\u0644\u062d\u0642\u060c \u0623\u064a: \u0623\u0644\u064a\u0633 \u0647\u0630\u0627 \u0627\u0644\u0628\u0639\u062b \u0627\u0644\u0630\u064a \u0643\u0646\u062a\u0645 \u062a\u0646\u0643\u0631\u0648\u0646\u0647 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u062d\u0642\u0651\u064b\u0627\u061f \u0642\u0627\u0644\u0648\u0627: \u0628\u0644\u0649 \u0648\u0631\u0628\u0646\u0627 \u0625\u0646\u0647 \u0644\u062d\u0642\u060c \u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \u0641\u0630\u0648\u0642\u0648\u0627 \u0627\u0644\u0639\u0630\u0627\u0628 \u0628\u0645\u0627 \u0643\u0646\u062a\u0645 \u062a\u0643\u0641\u0631\u0648\u0646 \u0623\u064a: \u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0630\u064a \u0643\u0646\u062a\u0645 \u062a\u0643\u0630\u0628\u0648\u0646 \u0628\u0647 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0628\u0633\u0628\u0628 \u062c\u062d\u0648\u062f\u0643\u0645 \u0628\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645.","6:31":"\u0642\u062f \u062e\u0633\u0631 \u0627\u0644\u0643\u0641\u0627\u0631 \u0627\u0644\u0630\u064a\u0646 \u0623\u0646\u0643\u0631\u0648\u0627 \u0627\u0644\u0628\u0639\u062b \u0628\u0639\u062f \u0627\u0644\u0645\u0648\u062a\u060c \u062d\u062a\u0649 \u0625\u0630\u0627 \u0642\u0627\u0645\u062a \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0648\u0641\u0648\u062c\u0626\u0648\u0627 \u0628\u0633\u0648\u0621 \u0627\u0644\u0645\u0635\u064a\u0631\u060c \u0646\u0627\u062f\u064e\u0648\u0627 \u0639\u0644\u0649 \u0623\u0646\u0641\u0633\u0647\u0645 \u0628\u0627\u0644\u062d\u0633\u0631\u0629 \u0639\u0644\u0649 \u0645\u0627 \u0636\u064a\u0651\u064e\u0639\u0648\u0647 \u0641\u064a \u062d\u064a\u0627\u062a\u0647\u0645 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0647\u0645 \u064a\u062d\u0645\u0644\u0648\u0646 \u0622\u062b\u0627\u0645\u0647\u0645 \u0639\u0644\u0649 \u0638\u0647\u0648\u0631\u0647\u0645\u060c \u0641\u0645\u0627 \u0623\u0633\u0648\u0623 \u0627\u0644\u0623\u062d\u0645\u0627\u0644 \u0627\u0644\u062b\u0642\u064a\u0644\u0629 \u0627\u0644\u0633\u064a\u0626\u0629 \u0627\u0644\u062a\u064a \u064a\u062d\u0645\u0644\u0648\u0646\u0647\u0627!!","6:32":"\u0648\u0645\u0627 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627 \u0641\u064a \u063a\u0627\u0644\u0628 \u0623\u062d\u0648\u0627\u0644\u0647\u0627 \u0625\u0644\u0627 \u063a\u0631\u0648\u0631 \u0648\u0628\u0627\u0637\u0644\u060c \u0648\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d \u0644\u0644\u062f\u0627\u0631 \u0627\u0644\u0622\u062e\u0631\u0629 \u062e\u064a\u0631 \u0644\u0644\u0630\u064a\u0646 \u064a\u062e\u0634\u0648\u0646 \u0627\u0644\u0644\u0647\u060c \u0641\u064a\u062a\u0642\u0648\u0646 \u0639\u0630\u0627\u0628\u0647 \u0628\u0637\u0627\u0639\u062a\u0647 \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0645\u0639\u0627\u0635\u064a\u0647. \u0623\u0641\u0644\u0627 \u062a\u0639\u0642\u0644\u0648\u0646 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0627\u0644\u0645\u063a\u062a\u0631\u0648\u0646 \u0628\u0632\u064a\u0646\u0629 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627- \u0641\u062a\u0642\u062f\u0651\u0650\u0645\u0648\u0627 \u0645\u0627 \u064a\u0628\u0642\u0649 \u0639\u0644\u0649 \u0645\u0627 \u064a\u0641\u0646\u0649\u061f","6:33":"\u0625\u0646\u0627 \u0646\u0639\u0644\u0645 \u0625\u0646\u0647 \u0644\u064a\u064f\u062f\u0652\u062e\u0644 \u0627\u0644\u062d\u0632\u0646\u064e \u0625\u0644\u0649 \u0642\u0644\u0628\u0643 \u062a\u0643\u0630\u064a\u0628\u064f \u0642\u0648\u0645\u0643 \u0644\u0643 \u0641\u064a \u0627\u0644\u0638\u0627\u0647\u0631\u060c \u0641\u0627\u0635\u0628\u0631 \u0648\u0627\u0637\u0645\u0626\u0646; \u0641\u0625\u0646\u0647\u0645 \u0644\u0627 \u064a\u0643\u0630\u0628\u0648\u0646\u0643 \u0641\u064a \u0642\u0631\u0627\u0631\u0629 \u0623\u0646\u0641\u0633\u0647\u0645\u060c \u0628\u0644 \u064a\u0639\u062a\u0642\u062f\u0648\u0646 \u0635\u062f\u0642\u0643\u060c \u0648\u0644\u0643\u0646\u0647\u0645 \u0644\u0638\u0644\u0645\u0647\u0645 \u0648\u0639\u062f\u0648\u0627\u0646\u0647\u0645 \u064a\u062c\u062d\u062f\u0648\u0646 \u0627\u0644\u0628\u0631\u0627\u0647\u064a\u0646 \u0627\u0644\u0648\u0627\u0636\u062d\u0629 \u0639\u0644\u0649 \u0635\u062f\u0642\u0643\u060c \u0641\u064a\u0643\u0630\u0628\u0648\u0646\u0643 \u0641\u064a\u0645\u0627 \u062c\u0626\u062a \u0628\u0647.","6:34":"\u0648\u0644\u0642\u062f \u0643\u0630\u0651\u064e\u0628 \u0627\u0644\u0643\u0641\u0627\u0631\u064f \u0631\u0633\u0644\u0627 \u0645\u0646 \u0642\u0628\u0644\u0643 \u0623\u0631\u0633\u0644\u0647\u0645 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0625\u0644\u0649 \u0623\u0645\u0645\u0647\u0645 \u0648\u0623\u0648\u0630\u0648\u0627 \u0641\u064a \u0633\u0628\u064a\u0644\u0647\u060c \u0641\u0635\u0628\u0631\u0648\u0627 \u0639\u0644\u0649 \u0630\u0644\u0643 \u0648\u0645\u0636\u0648\u0627 \u0641\u064a \u062f\u0639\u0648\u062a\u0647\u0645 \u0648\u062c\u0647\u0627\u062f\u0647\u0645 \u062d\u062a\u0649 \u0623\u062a\u0627\u0647\u0645 \u0646\u0635\u0631 \u0627\u0644\u0644\u0647. \u0648\u0644\u0627 \u0645\u0628\u062f\u0644 \u0644\u0643\u0644\u0645\u0627\u062a \u0627\u0644\u0644\u0647\u060c \u0648\u0647\u064a \u0645\u0627 \u0623\u0646\u0632\u0644 \u0639\u0644\u0649 \u0646\u0628\u064a\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0645\u0650\u0646 \u0648\u0639\u062f\u0647 \u0625\u064a\u0627\u0647 \u0628\u0627\u0644\u0646\u0635\u0631 \u0639\u0644\u0649 \u0645\u064e\u0646 \u0639\u0627\u062f\u0627\u0647. \u0648\u0644\u0642\u062f \u062c\u0627\u0621\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u0650\u0646 \u062e\u0628\u0631 \u0645\u064e\u0646 \u0643\u0627\u0646 \u0642\u0628\u0644\u0643 \u0645\u0646 \u0627\u0644\u0631\u0633\u0644\u060c \u0648\u0645\u0627 \u062a\u062d\u0642\u0642 \u0644\u0647\u0645 \u0645\u0646 \u0646\u0635\u0631 \u0627\u0644\u0644\u0647\u060c \u0648\u0645\u0627 \u062c\u0631\u0649 \u0639\u0644\u0649 \u0645\u0643\u0630\u0628\u064a\u0647\u0645 \u0645\u0646 \u0646\u0642\u0645\u0629 \u0627\u0644\u0644\u0647 \u0645\u0646\u0647\u0645 \u0648\u063a\u0636\u0628\u0647 \u0639\u0644\u064a\u0647\u0645\u060c \u0641\u0644\u0643 \u0641\u064a\u0645\u0646 \u062a\u0642\u062f\u0645 \u0645\u0646 \u0627\u0644\u0631\u0633\u0644 \u0623\u0633\u0648\u0629 \u0648\u0642\u062f\u0648\u0629. \u0648\u0641\u064a \u0647\u0630\u0627 \u062a\u0633\u0644\u064a\u0629 \u0644\u0644\u0631\u0633\u0648\u0644 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645.","6:35":"\u0648\u0625\u0646 \u0643\u0627\u0646 \u0639\u064e\u0638\u064f\u0645\u064e \u0639\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0635\u062f\u0648\u062f \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0648\u0627\u0646\u0635\u0631\u0627\u0641\u0647\u0645 \u0639\u0646 \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0644\u062f\u0639\u0648\u062a\u0643\u060c \u0641\u0625\u0646 \u0627\u0633\u062a\u0637\u0639\u062a \u0623\u0646 \u062a\u062a\u062e\u0630 \u0646\u0641\u0642\u064b\u0627 \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u0623\u0648 \u0645\u0635\u0639\u062f\u064b\u0627 \u062a\u0635\u0639\u062f \u0641\u064a\u0647 \u0625\u0644\u0649 \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u0641\u062a\u0623\u062a\u064a\u0647\u0645 \u0628\u0639\u0644\u0627\u0645\u0629 \u0648\u0628\u0631\u0647\u0627\u0646 \u0639\u0644\u0649 \u0635\u062d\u0629 \u0642\u0648\u0644\u0643 \u063a\u064a\u0631 \u0627\u0644\u0630\u064a \u062c\u0626\u0646\u0627\u0647\u0645 \u0628\u0647 \u0641\u0627\u0641\u0639\u0644. \u0648\u0644\u0648 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u0644\u064e\u062c\u064e\u0645\u0639\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0647\u062f\u0649 \u0627\u0644\u0630\u064a \u0623\u0646\u062a\u0645 \u0639\u0644\u064a\u0647 \u0648\u0648\u0641\u0651\u064e\u0642\u0647\u0645 \u0644\u0644\u0625\u064a\u0645\u0627\u0646\u060c \u0648\u0644\u0643\u0646 \u0644\u0645 \u064a\u0634\u0623 \u0630\u0644\u0643 \u0644\u062d\u0643\u0645\u0629 \u064a\u0639\u0644\u0645\u0647\u0627 \u0633\u0628\u062d\u0627\u0646\u0647\u060c \u0641\u0644\u0627 \u062a\u0643\u0648\u0646\u0646 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u0646 \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0627\u0634\u062a\u062f \u062d\u0632\u0646\u0647\u0645\u060c \u0648\u062a\u062d\u0633\u0651\u064e\u0631\u0648\u0627 \u062d\u062a\u0649 \u0623\u0648\u0635\u0644\u0647\u0645 \u0630\u0644\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0632\u0639 \u0627\u0644\u0634\u062f\u064a\u062f.","6:36":"\u0625\u0646\u0645\u0627 \u064a\u062c\u064a\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0625\u0644\u0649 \u0645\u0627 \u062f\u0639\u0648\u062a \u0625\u0644\u064a\u0647 \u0645\u0646 \u0627\u0644\u0647\u062f\u0649 \u0627\u0644\u0630\u064a\u0646 \u064a\u0633\u0645\u0639\u0648\u0646 \u0627\u0644\u0643\u0644\u0627\u0645 \u0633\u0645\u0627\u0639 \u0642\u0628\u0648\u0644. \u0623\u0645\u0627 \u0627\u0644\u0643\u0641\u0627\u0631 \u0641\u0647\u0645 \u0641\u064a \u0639\u062f\u0627\u062f \u0627\u0644\u0645\u0648\u062a\u0649; \u0644\u0623\u0646 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062d\u0642\u064a\u0642\u064a\u0629 \u0625\u0646\u0645\u0627 \u062a\u0643\u0648\u0646 \u0628\u0627\u0644\u0625\u0633\u0644\u0627\u0645. \u0648\u0627\u0644\u0645\u0648\u062a\u0649 \u064a\u062e\u0631\u062c\u0647\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0642\u0628\u0648\u0631\u0647\u0645 \u0623\u062d\u064a\u0627\u0621\u060c \u062b\u0645 \u064a\u0639\u0648\u062f\u0648\u0646 \u0625\u0644\u064a\u0647 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0644\u064a\u0648\u0641\u0648\u0627 \u062d\u0633\u0627\u0628\u0647\u0645 \u0648\u062c\u0632\u0627\u0621\u0647\u0645.","6:37":"\u0648\u0642\u0627\u0644 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 -\u062a\u0639\u0646\u062a\u064b\u0627 \u0648\u0627\u0633\u062a\u0643\u0628\u0627\u0631\u064b\u0627-: \u0647\u0644\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0639\u0644\u0627\u0645\u0629 \u062a\u062f\u0644 \u0639\u0644\u0649 \u0635\u062f\u0642 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0645\u0646 \u0646\u0648\u0639 \u0627\u0644\u0639\u0644\u0627\u0645\u0627\u062a \u0627\u0644\u062e\u0627\u0631\u0642\u0629\u060c \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0625\u0646 \u0627\u0644\u0644\u0647 \u0642\u0627\u062f\u0631 \u0639\u0644\u0649 \u0623\u0646 \u064a\u0646\u0632\u0644 \u0639\u0644\u064a\u0647\u0645 \u0622\u064a\u0629\u060c \u0648\u0644\u0643\u0646 \u0623\u0643\u062b\u0631\u0647\u0645 \u0644\u0627 \u064a\u0639\u0644\u0645\u0648\u0646 \u0623\u0646 \u0625\u0646\u0632\u0627\u0644 \u0627\u0644\u0622\u064a\u0627\u062a \u0625\u0646\u0645\u0627 \u064a\u0643\u0648\u0646 \u0648\u064e\u0641\u0652\u0642 \u062d\u0643\u0645\u062a\u0647 \u062a\u0639\u0627\u0644\u0649.","6:38":"\u0644\u064a\u0633 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u062d\u064a\u0648\u0627\u0646 \u064a\u064e\u062f\u0650\u0628\u0651\u064f \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0623\u0648 \u0637\u0627\u0626\u0631 \u064a\u0637\u064a\u0631 \u0641\u064a \u0627\u0644\u0633\u0645\u0627\u0621 \u0628\u062c\u0646\u0627\u062d\u064a\u0647 \u0625\u0644\u0627 \u062c\u0645\u0627\u0639\u0627\u062a \u0645\u062a\u062c\u0627\u0646\u0633\u0629 \u0627\u0644\u062e\u0644\u0642 \u0645\u062b\u0644\u0643\u0645. \u0645\u0627 \u062a\u0631\u0643\u0646\u0627 \u0641\u064a \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u0645\u062d\u0641\u0648\u0638 \u0634\u064a\u0626\u064b\u0627 \u0625\u0644\u0627 \u0623\u062b\u0628\u062a\u0646\u0627\u0647\u060c \u062b\u0645 \u0625\u0646\u0647\u0645 \u0625\u0644\u0649 \u0631\u0628\u0647\u0645 \u064a\u062d\u0634\u0631\u0648\u0646 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0641\u064a\u062d\u0627\u0633\u0628 \u0627\u0644\u0644\u0647 \u0643\u0644\u0627 \u0628\u0645\u0627 \u0639\u0645\u0644.","6:39":"\u0648\u0627\u0644\u0630\u064a\u0646 \u0643\u0630\u0628\u0648\u0627 \u0628\u062d\u062c\u062c \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0635\u0645\u0651\u064c \u0644\u0627 \u064a\u0633\u0645\u0639\u0648\u0646 \u0645\u0627 \u064a\u0646\u0641\u0639\u0647\u0645\u060c \u0628\u064f\u0643\u0652\u0645\u064c \u0644\u0627 \u064a\u062a\u0643\u0644\u0645\u0648\u0646 \u0628\u0627\u0644\u062d\u0642\u060c \u0641\u0647\u0645 \u062d\u0627\u0626\u0631\u0648\u0646 \u0641\u064a \u0627\u0644\u0638\u0644\u0645\u0627\u062a\u060c \u0644\u0645 \u064a\u062e\u062a\u0627\u0631\u0648\u0627 \u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u0627\u0633\u062a\u0642\u0627\u0645\u0629. \u0645\u0646 \u064a\u0634\u0623 \u0627\u0644\u0644\u0647 \u0625\u0636\u0644\u0627\u0644\u0647 \u064a\u0636\u0644\u0644\u0647\u060c \u0648\u0645\u0646 \u064a\u0634\u0623 \u0647\u062f\u0627\u064a\u062a\u0647 \u064a\u062c\u0639\u0644\u0647 \u0639\u0644\u0649 \u0635\u0631\u0627\u0637 \u0645\u0633\u062a\u0642\u064a\u0645.","6:40":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0623\u062e\u0628\u0631\u0648\u0646\u064a \u0625\u0646 \u062c\u0627\u0621\u0643\u0645 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0623\u0648 \u062c\u0627\u0621\u062a\u0643\u0645 \u0627\u0644\u0633\u0627\u0639\u0629 \u0627\u0644\u062a\u064a \u062a\u0628\u0639\u062b\u0648\u0646 \u0641\u064a\u0647\u0627: \u0623\u063a\u064a\u0631 \u0627\u0644\u0644\u0647 \u062a\u062f\u0639\u0648\u0646 \u0647\u0646\u0627\u0643 \u0644\u0643\u0634\u0641 \u0645\u0627 \u0646\u0632\u0644 \u0628\u0643\u0645 \u0645\u0646 \u0627\u0644\u0628\u0644\u0627\u0621\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u0645\u062d\u0642\u064a\u0646 \u0641\u064a \u0632\u0639\u0645\u0643\u0645 \u0623\u0646 \u0622\u0644\u0647\u062a\u0643\u0645 \u0627\u0644\u062a\u064a \u062a\u0639\u0628\u062f\u0648\u0646\u0647\u0627 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u062a\u0646\u0641\u0639 \u0623\u0648 \u062a\u0636\u0631\u061f","6:41":"\u0628\u0644 \u062a\u062f\u0639\u0648\u0646 -\u0647\u0646\u0627\u0643- \u0631\u0628\u0643\u0645 \u0627\u0644\u0630\u064a \u062e\u0644\u0642\u0643\u0645 \u0644\u0627 \u063a\u064a\u0631\u0647\u060c \u0648\u062a\u0633\u062a\u063a\u064a\u062b\u0648\u0646 \u0628\u0647\u060c \u0641\u064a\u0641\u0631\u062c \u0639\u0646\u0643\u0645 \u0627\u0644\u0628\u0644\u0627\u0621 \u0627\u0644\u0639\u0638\u064a\u0645 \u0627\u0644\u0646\u0627\u0632\u0644 \u0628\u0643\u0645 \u0625\u0646 \u0634\u0627\u0621; \u0644\u0623\u0646\u0647 \u0627\u0644\u0642\u0627\u062f\u0631 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621\u060c \u0648\u062a\u062a\u0631\u0643\u0648\u0646 \u062d\u064a\u0646\u0626\u0630 \u0623\u0635\u0646\u0627\u0645\u0643\u0645 \u0648\u0623\u0648\u062b\u0627\u0646\u0643\u0645 \u0648\u0623\u0648\u0644\u064a\u0627\u0621\u0643\u0645.","6:42":"\u0648\u0644\u0642\u062f \u0628\u0639\u062b\u0646\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0625\u0644\u0649 \u062c\u0645\u0627\u0639\u0627\u062a \u0645\u0646 \u0627\u0644\u0646\u0627\u0633 \u0645\u0646 \u0642\u0628\u0644\u0643 \u0631\u0633\u0644\u0627 \u064a\u062f\u0639\u0648\u0646\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0641\u0643\u0630\u0651\u064e\u0628\u0648\u0647\u0645\u060c \u0641\u0627\u0628\u062a\u0644\u064a\u0646\u0627\u0647\u0645 \u0641\u064a \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0628\u0634\u062f\u0629 \u0627\u0644\u0641\u0642\u0631 \u0648\u0636\u064a\u0642 \u0627\u0644\u0645\u0639\u064a\u0634\u0629\u060c \u0648\u0627\u0628\u062a\u0644\u064a\u0646\u0627\u0647\u0645 \u0641\u064a \u0623\u062c\u0633\u0627\u0645\u0647\u0645 \u0628\u0627\u0644\u0623\u0645\u0631\u0627\u0636 \u0648\u0627\u0644\u0622\u0644\u0627\u0645; \u0631\u062c\u0627\u0621 \u0623\u0646 \u064a\u062a\u0630\u0644\u0644\u0648\u0627 \u0644\u0631\u0628\u0647\u0645\u060c \u0648\u064a\u062e\u0636\u0639\u0648\u0627 \u0644\u0647 \u0648\u062d\u062f\u0647 \u0628\u0627\u0644\u0639\u0628\u0627\u062f\u0629.","6:43":"\u0641\u0647\u0644\u0627 \u0625\u0630 \u062c\u0627\u0621 \u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0645 \u0627\u0644\u0645\u0643\u0630\u0628\u0629 \u0628\u0644\u0627\u0624\u0646\u0627 \u062a\u0630\u0644\u0644\u0648\u0627 \u0644\u0646\u0627\u060c \u0648\u0644\u0643\u0646 \u0642\u0633\u062a \u0642\u0644\u0648\u0628\u0647\u0645\u060c \u0648\u0632\u064a\u0651\u064e\u0646 \u0644\u0647\u0645 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u064a\u0639\u0645\u0644\u0648\u0646 \u0645\u0646 \u0627\u0644\u0645\u0639\u0627\u0635\u064a\u060c \u0648\u064a\u0623\u062a\u0648\u0646 \u0645\u0646 \u0627\u0644\u0634\u0631\u0643.","6:44":"\u0641\u0644\u0645\u0627 \u062a\u0631\u0643\u0648\u0627 \u0627\u0644\u0639\u0645\u0644 \u0628\u0623\u0648\u0627\u0645\u0631 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0645\u0639\u0631\u0636\u064a\u0646 \u0639\u0646\u0647\u0627\u060c \u0641\u062a\u062d\u0646\u0627 \u0639\u0644\u064a\u0647\u0645 \u0623\u0628\u0648\u0627\u0628 \u0643\u0644 \u0634\u064a\u0621 \u0645\u0646 \u0627\u0644\u0631\u0632\u0642 \u0641\u0623\u0628\u062f\u0644\u0646\u0627\u0647\u0645 \u0628\u0627\u0644\u0628\u0623\u0633\u0627\u0621 \u0631\u062e\u0627\u0621\u064b \u0641\u064a \u0627\u0644\u0639\u064a\u0634\u060c \u0648\u0628\u0627\u0644\u0636\u0631\u0627\u0621 \u0635\u062d\u0629 \u0641\u064a \u0627\u0644\u0623\u062c\u0633\u0627\u0645; \u0627\u0633\u062a\u062f\u0631\u0627\u062c\u0627 \u0645\u0646\u0627 \u0644\u0647\u0645\u060c \u062d\u062a\u0649 \u0625\u0630\u0627 \u0628\u0637\u0631\u0648\u0627\u060c \u0648\u0623\u0639\u062c\u0628\u0648\u0627 \u0628\u0645\u0627 \u0623\u0639\u0637\u064a\u0646\u0627\u0647\u0645 \u0645\u0646 \u0627\u0644\u062e\u064a\u0631 \u0648\u0627\u0644\u0646\u0639\u0645\u0629 \u0623\u062e\u0630\u0646\u0627\u0647\u0645 \u0628\u0627\u0644\u0639\u0630\u0627\u0628 \u0641\u062c\u0623\u0629\u060c \u0641\u0625\u0630\u0627 \u0647\u0645 \u0622\u064a\u0633\u0648\u0646 \u0645\u0646\u0642\u0637\u0639\u0648\u0646 \u0645\u0646 \u0643\u0644 \u062e\u064a\u0631.","6:45":"\u0641\u0627\u0633\u062a\u0624\u0635\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0642\u0648\u0645 \u0648\u0623\u064f\u0647\u0644\u0643\u0648\u0627 \u0625\u0630 \u0643\u0641\u0631\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0643\u0630\u0651\u064e\u0628\u0648\u0627 \u0631\u0633\u0644\u0647\u060c \u0641\u0644\u0645 \u064a\u0628\u0642 \u0645\u0646\u0647\u0645 \u0623\u062d\u062f. \u0648\u0627\u0644\u0634\u0643\u0631 \u0648\u0627\u0644\u062b\u0646\u0627\u0621 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 -\u062e\u0627\u0644\u0642 \u0643\u0644 \u0634\u064a\u0621 \u0648\u0645\u0627\u0644\u0643\u0647- \u0639\u0644\u0649 \u0646\u0635\u0631\u0629 \u0623\u0648\u0644\u064a\u0627\u0626\u0647 \u0648\u0647\u0644\u0627\u0643 \u0623\u0639\u062f\u0627\u0626\u0647.","6:46":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0623\u062e\u0628\u0631\u0648\u0646\u064a \u0625\u0646 \u0623\u0630\u0647\u0628 \u0627\u0644\u0644\u0647 \u0633\u0645\u0639\u0643\u0645 \u0641\u0623\u0635\u0645\u0651\u064e\u0643\u0645\u060c \u0648\u0630\u0647\u0628 \u0628\u0623\u0628\u0635\u0627\u0631\u0643\u0645 \u0641\u0623\u0639\u0645\u0627\u0643\u0645\u060c \u0648\u0637\u0628\u0639 \u0639\u0644\u0649 \u0642\u0644\u0648\u0628\u0643\u0645 \u0641\u0623\u0635\u0628\u062d\u062a\u0645 \u0644\u0627 \u062a\u0641\u0642\u0647\u0648\u0646 \u0642\u0648\u0644\u0627 \u0623\u064a\u0651\u064f \u0625\u0644\u0647 \u063a\u064a\u0631 \u0627\u0644\u0644\u0647 \u062c\u0644 \u0648\u0639\u0644\u0627 \u064a\u0642\u062f\u0631 \u0639\u0644\u0649 \u0631\u062f\u0651\u0650 \u0630\u0644\u0643 \u0644\u0643\u0645\u061f! \u0627\u0646\u0638\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0643\u064a\u0641 \u0646\u0646\u0648\u0651\u0650\u0639 \u0644\u0647\u0645 \u0627\u0644\u062d\u062c\u062c\u060c \u062b\u0645 \u0647\u0645 \u0628\u0639\u062f \u0630\u0644\u0643 \u064a\u0639\u0631\u0636\u0648\u0646 \u0639\u0646 \u0627\u0644\u062a\u0630\u0643\u0631 \u0648\u0627\u0644\u0627\u0639\u062a\u0628\u0627\u0631\u061f","6:47":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0623\u062e\u0628\u0631\u0648\u0646\u064a \u0625\u0646 \u0646\u0632\u0644 \u0628\u0643\u0645 \u0639\u0642\u0627\u0628 \u0627\u0644\u0644\u0647 \u0641\u062c\u0623\u0629 \u0648\u0623\u0646\u062a\u0645 \u0644\u0627 \u062a\u0634\u0639\u0631\u0648\u0646 \u0628\u0647\u060c \u0623\u0648 \u0638\u0627\u0647\u0631\u064b\u0627 \u0639\u0650\u064a\u0627\u0646\u064b\u0627 \u0648\u0623\u0646\u062a\u0645 \u062a\u0646\u0638\u0631\u0648\u0646 \u0625\u0644\u064a\u0647: \u0647\u0644 \u064a\u064f\u0647\u0644\u0643 \u0625\u0644\u0627 \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u0638\u0627\u0644\u0645\u0648\u0646 \u0627\u0644\u0630\u064a\u0646 \u062a\u062c\u0627\u0648\u0632\u0648\u0627 \u0627\u0644\u062d\u062f\u060c \u0628\u0635\u0631\u0641\u0647\u0645 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0644\u063a\u064a\u0631 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0628\u062a\u0643\u0630\u064a\u0628\u0647\u0645 \u0631\u0633\u0644\u0647\u061f","6:48":"\u0648\u0645\u0627 \u0646\u0631\u0633\u0644 \u0631\u0633\u0644\u0646\u0627 \u0625\u0644\u0627 \u0645\u0628\u0634\u0631\u064a\u0646 \u0623\u0647\u0644 \u0637\u0627\u0639\u062a\u0646\u0627 \u0628\u0627\u0644\u0646\u0639\u064a\u0645 \u0627\u0644\u0645\u0642\u064a\u0645\u060c \u0648\u0645\u0646\u0630\u0631\u064a\u0646 \u0623\u0647\u0644 \u0627\u0644\u0645\u0639\u0635\u064a\u0629 \u0628\u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0623\u0644\u064a\u0645\u060c \u0641\u0645\u0646 \u0622\u0645\u0646 \u0648\u0635\u062f\u0651\u064e\u0642 \u0627\u0644\u0631\u0633\u0644 \u0648\u0639\u0645\u0644 \u0635\u0627\u0644\u062d\u064b\u0627 \u0641\u0623\u0648\u0644\u0626\u0643 \u0644\u0627 \u064a\u062e\u0627\u0641\u0648\u0646 \u0639\u0646\u062f \u0644\u0642\u0627\u0621 \u0631\u0628\u0647\u0645\u060c \u0648\u0644\u0627 \u064a\u062d\u0632\u0646\u0648\u0646 \u0639\u0644\u0649 \u0634\u064a\u0621 \u0641\u0627\u062a\u0647\u0645 \u0645\u0646 \u062d\u0638\u0648\u0638 \u0627\u0644\u062f\u0646\u064a\u0627.","6:49":"\u0648\u0627\u0644\u0630\u064a\u0646 \u0643\u0630\u0651\u064e\u0628\u0648\u0627 \u0628\u0622\u064a\u0627\u062a\u0646\u0627 \u0645\u0646 \u0627\u0644\u0642\u0631\u0622\u0646 \u0648\u0627\u0644\u0645\u0639\u062c\u0632\u0627\u062a \u0641\u0623\u0648\u0644\u0626\u0643 \u064a\u0635\u064a\u0628\u0647\u0645 \u0627\u0644\u0639\u0630\u0627\u0628 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0628\u0633\u0628\u0628 \u0643\u0641\u0631\u0647\u0645 \u0648\u062e\u0631\u0648\u062c\u0647\u0645 \u0639\u0646 \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649.","6:50":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0625\u0646\u064a \u0644\u0627 \u0623\u062f\u0651\u064e\u0639\u064a \u0623\u0646\u064a \u0623\u0645\u0644\u0643 \u062e\u0632\u0627\u0626\u0646 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636\u060c \u0641\u0623\u062a\u0635\u0631\u0641 \u0641\u064a\u0647\u0627\u060c \u0648\u0644\u0627 \u0623\u062f\u0651\u064e\u0639\u064a \u0623\u0646\u064a \u0623\u0639\u0644\u0645 \u0627\u0644\u063a\u064a\u0628\u060c \u0648\u0644\u0627 \u0623\u062f\u0651\u064e\u0639\u064a \u0623\u0646\u064a \u0645\u0644\u0643\u060c \u0648\u0625\u0646\u0645\u0627 \u0623\u0646\u0627 \u0631\u0633\u0648\u0644 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0623\u062a\u0628\u0639 \u0645\u0627 \u064a\u0648\u062d\u0649 \u0625\u0644\u064a\u0651\u064e\u060c \u0648\u0623\u0628\u0644\u0651\u0650\u063a \u0648\u062d\u064a\u0647 \u0625\u0644\u0649 \u0627\u0644\u0646\u0627\u0633\u060c \u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0647\u0644 \u064a\u0633\u062a\u0648\u064a \u0627\u0644\u0643\u0627\u0641\u0631 \u0627\u0644\u0630\u064a \u0639\u064e\u0645\u0650\u064a \u0639\u0646 \u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0641\u0644\u0645 \u064a\u0624\u0645\u0646 \u0628\u0647\u0627 \u0648\u0627\u0644\u0645\u0624\u0645\u0646 \u0627\u0644\u0630\u064a \u0623\u0628\u0635\u0631 \u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0641\u0622\u0645\u0646 \u0628\u0647\u0627\u061f \u0623\u0641\u0644\u0627 \u062a\u062a\u0641\u0643\u0631\u0648\u0646 \u0641\u064a \u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647; \u0644\u062a\u0628\u0635\u0631\u0648\u0627 \u0627\u0644\u062d\u0642 \u0641\u062a\u0624\u0645\u0646\u0648\u0627 \u0628\u0647\u061f","6:51":"\u0648\u062e\u0648\u0651\u0650\u0641 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0628\u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u0639\u0644\u0645\u0648\u0646 \u0623\u0646\u0647\u0645 \u064a\u064f\u062d\u0634\u0631\u0648\u0646 \u0625\u0644\u0649 \u0631\u0628\u0647\u0645\u060c \u0641\u0647\u0645 \u0645\u0635\u062f\u0651\u0650\u0642\u0648\u0646 \u0628\u0648\u0639\u062f \u0627\u0644\u0644\u0647 \u0648\u0648\u0639\u064a\u062f\u0647\u060c \u0644\u064a\u0633 \u0644\u0647\u0645 \u063a\u064a\u0631 \u0627\u0644\u0644\u0647 \u0648\u0644\u064a\u0651 \u064a\u0646\u0635\u0631\u0647\u0645\u060c \u0648\u0644\u0627 \u0634\u0641\u064a\u0639 \u064a\u0634\u0641\u0639 \u0644\u0647\u0645 \u0639\u0646\u062f\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0641\u064a\u062e\u0644\u0635\u0647\u0645 \u0645\u0646 \u0639\u0630\u0627\u0628\u0647; \u0644\u0639\u0644\u0647\u0645 \u064a\u062a\u0642\u0648\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0641\u0639\u0644 \u0627\u0644\u0623\u0648\u0627\u0645\u0631 \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0627\u0644\u0646\u0648\u0627\u0647\u064a.","6:52":"\u0648\u0644\u0627 \u062a\u064f\u0628\u0652\u0639\u062f -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0639\u0646 \u0645\u062c\u0627\u0644\u0633\u062a\u0643 \u0636\u0639\u0641\u0627\u0621 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u0639\u0628\u062f\u0648\u0646 \u0631\u0628\u0647\u0645 \u0623\u0648\u0644 \u0627\u0644\u0646\u0647\u0627\u0631 \u0648\u0622\u062e\u0631\u0647\u060c \u064a\u0631\u064a\u062f\u0648\u0646 \u0628\u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0627\u0644\u0635\u0627\u0644\u062d\u0629 \u0648\u062c\u0647 \u0627\u0644\u0644\u0647\u060c \u0645\u0627 \u0639\u0644\u064a\u0643 \u0645\u0646 \u062d\u0633\u0627\u0628 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0641\u0642\u0631\u0627\u0621 \u0645\u0646 \u0634\u064a\u0621\u060c \u0625\u0646\u0645\u0627 \u062d\u0633\u0627\u0628\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u064a\u0633 \u0639\u0644\u064a\u0647\u0645 \u0634\u064a\u0621 \u0645\u0646 \u062d\u0633\u0627\u0628\u0643\u060c \u0641\u0625\u0646 \u0623\u0628\u0639\u062f\u062a\u0647\u0645 \u0641\u0625\u0646\u0643 \u062a\u0643\u0648\u0646 \u0645\u0646 \u0627\u0644\u0645\u062a\u062c\u0627\u0648\u0632\u064a\u0646 \u062d\u062f\u0648\u062f \u0627\u0644\u0644\u0647\u060c \u0627\u0644\u0630\u064a\u0646 \u064a\u0636\u0639\u0648\u0646 \u0627\u0644\u0634\u064a\u0621 \u0641\u064a \u063a\u064a\u0631 \u0645\u0648\u0636\u0639\u0647.","6:53":"\u0648\u0643\u0630\u0644\u0643 \u0627\u0628\u062a\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0639\u0636 \u0639\u0628\u0627\u062f\u0647 \u0628\u0628\u0639\u0636 \u0628\u062a\u0628\u0627\u064a\u0646 \u062d\u0638\u0648\u0638\u0647\u0645 \u0645\u0646 \u0627\u0644\u0623\u0631\u0632\u0627\u0642 \u0648\u0627\u0644\u0623\u062e\u0644\u0627\u0642\u060c \u0641\u062c\u0639\u0644 \u0628\u0639\u0636\u0647\u0645 \u063a\u0646\u064a\u0651\u064b\u0627 \u0648\u0628\u0639\u0636\u0647\u0645 \u0641\u0642\u064a\u0631\u064b\u0627\u060c \u0648\u0628\u0639\u0636\u0647\u0645 \u0642\u0648\u064a\u0651\u064b\u0627 \u0648\u0628\u0639\u0636\u0647\u0645 \u0636\u0639\u064a\u0641\u064b\u0627\u060c \u0641\u0623\u062d\u0648\u062c \u0628\u0639\u0636\u0647\u0645 \u0625\u0644\u0649 \u0628\u0639\u0636 \u0627\u062e\u062a\u0628\u0627\u0631\u064b\u0627 \u0645\u0646\u0647 \u0644\u0647\u0645 \u0628\u0630\u0644\u0643; \u0644\u064a\u0642\u0648\u0644 \u0627\u0644\u0643\u0627\u0641\u0631\u0648\u0646 \u0627\u0644\u0623\u063a\u0646\u064a\u0627\u0621: \u0623\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0636\u0639\u0641\u0627\u0621 \u0645\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0628\u0627\u0644\u0647\u062f\u0627\u064a\u0629 \u0625\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0645\u0650\u0646 \u0628\u064a\u0646\u0646\u0627\u061f \u0623\u0644\u064a\u0633 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0623\u0639\u0644\u0645 \u0628\u0645\u0646 \u064a\u0634\u0643\u0631\u0648\u0646 \u0646\u0639\u0645\u062a\u0647\u060c \u0641\u064a\u0648\u0641\u0642\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u0647\u062f\u0627\u064a\u0629 \u0644\u062f\u064a\u0646\u0647\u061f","6:54":"\u0648\u0625\u0630\u0627 \u062c\u0627\u0621\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0627\u0644\u0630\u064a\u0646 \u0635\u064e\u062f\u0651\u064e\u0642\u0648\u0627 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0627\u0644\u0634\u0627\u0647\u062f\u0629 \u0639\u0644\u0649 \u0635\u062f\u0642\u0643 \u0645\u0646 \u0627\u0644\u0642\u0631\u0622\u0646 \u0648\u063a\u064a\u0631\u0647 \u0645\u0633\u062a\u0641\u062a\u064a\u0646 \u0639\u0646 \u0627\u0644\u062a\u0648\u0628\u0629 \u0645\u0646 \u0630\u0646\u0648\u0628\u0647\u0645 \u0627\u0644\u0633\u0627\u0628\u0642\u0629\u060c \u0641\u0623\u0643\u0631\u0650\u0645\u0652\u0647\u0645 \u0628\u0631\u062f\u0651\u0650 \u0627\u0644\u0633\u0644\u0627\u0645 \u0639\u0644\u064a\u0647\u0645\u060c \u0648\u0628\u064e\u0634\u0651\u0650\u0631\u0647\u0645 \u0628\u0631\u062d\u0645\u0629 \u0627\u0644\u0644\u0647 \u0627\u0644\u0648\u0627\u0633\u0639\u0629; \u0641\u0625\u0646\u0647 \u062c\u0644\u0651\u064e \u0648\u0639\u0644\u0627 \u0642\u062f \u0643\u062a\u0628 \u0639\u0644\u0649 \u0646\u0641\u0633\u0647 \u0627\u0644\u0631\u062d\u0645\u0629 \u0628\u0639\u0628\u0627\u062f\u0647 \u062a\u0641\u0636\u0644\u0627 \u0623\u0646\u0647 \u0645\u0646 \u0627\u0642\u062a\u0631\u0641 \u0630\u0646\u0628\u064b\u0627 \u0628\u062c\u0647\u0627\u0644\u0629 \u0645\u0646\u0647 \u0644\u0639\u0627\u0642\u0628\u062a\u0647\u0627 \u0648\u0625\u064a\u062c\u0627\u0628\u0647\u0627 \u0644\u0633\u062e\u0637 \u0627\u0644\u0644\u0647 -\u0641\u0643\u0644 \u0639\u0627\u0635 \u0644\u0644\u0647 \u0645\u062e\u0637\u0626\u064b\u0627 \u0623\u0648 \u0645\u062a\u0639\u0645\u062f\u064b\u0627 \u0641\u0647\u0648 \u062c\u0627\u0647\u0644 \u0628\u0647\u0630\u0627 \u0627\u0644\u0627\u0639\u062a\u0628\u0627\u0631 \u0648\u0625\u0646 \u0643\u0627\u0646 \u0639\u0627\u0644\u0645\u064b\u0627 \u0628\u0627\u0644\u062a\u062d\u0631\u064a\u0645- \u062b\u0645 \u062a\u0627\u0628 \u0645\u0646 \u0628\u0639\u062f\u0647 \u0648\u062f\u0627\u0648\u0645 \u0639\u0644\u0649 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u060c \u0641\u0625\u0646\u0647 \u062a\u0639\u0627\u0644\u0649 \u064a\u063a\u0641\u0631 \u0630\u0646\u0628\u0647\u060c \u0641\u0647\u0648 \u063a\u0641\u0648\u0631 \u0644\u0639\u0628\u0627\u062f\u0647 \u0627\u0644\u062a\u0627\u0626\u0628\u064a\u0646\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","6:55":"\u0648\u0645\u062b\u0644 \u0647\u0630\u0627 \u0627\u0644\u0628\u064a\u0627\u0646 \u0627\u0644\u0630\u064a \u0628\u064a\u0651\u064e\u0646\u0651\u064e\u0627\u0647 \u0644\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0646\u0628\u064a\u0651\u0650\u0646 \u0627\u0644\u062d\u062c\u062c \u0627\u0644\u0648\u0627\u0636\u062d\u0629 \u0639\u0644\u0649 \u0643\u0644 \u062d\u0642 \u064a\u0646\u0643\u0631\u0647 \u0623\u0647\u0644 \u0627\u0644\u0628\u0627\u0637\u0644; \u0644\u064a\u062a\u0628\u064a\u0646 \u0627\u0644\u062d\u0642\u060c \u0648\u0644\u064a\u0638\u0647\u0631 \u0637\u0631\u064a\u0642 \u0623\u0647\u0644 \u0627\u0644\u0628\u0627\u0637\u0644 \u0627\u0644\u0645\u062e\u0627\u0644\u0641\u064a\u0646 \u0644\u0644\u0631\u0633\u0644.","6:56":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0625\u0646 \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644 \u0646\u0647\u0627\u0646\u064a \u0623\u0646 \u0623\u0639\u0628\u062f \u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u0627\u0644\u062a\u064a \u062a\u0639\u0628\u062f\u0648\u0646\u0647\u0627 \u0645\u0646 \u062f\u0648\u0646\u0647\u060c \u0648\u0642\u0644 \u0644\u0647\u0645: \u0644\u0627 \u0623\u062a\u0628\u0639 \u0623\u0647\u0648\u0627\u0621\u0643\u0645 \u0642\u062f \u0636\u0644\u0644\u062a \u0639\u0646 \u0627\u0644\u0635\u0631\u0627\u0637 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645 \u0625\u0646 \u0627\u062a\u0628\u0639\u062a \u0623\u0647\u0648\u0627\u0621\u064e\u0643\u0645\u060c \u0648\u0645\u0627 \u0623\u0646\u0627 \u0645\u0646 \u0627\u0644\u0645\u0647\u062a\u062f\u064a\u0646.","6:57":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644 \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646-: \u0625\u0646\u064a \u0639\u0644\u0649 \u0628\u0635\u064a\u0631\u0629 \u0648\u0627\u0636\u062d\u0629 \u0645\u0646 \u0634\u0631\u064a\u0639\u0629 \u0627\u0644\u0644\u0647 \u0627\u0644\u062a\u064a \u0623\u0648\u062d\u0627\u0647\u0627 \u0625\u0644\u064a\u0651\u064e\u060c \u0648\u0630\u0644\u0643 \u0628\u0625\u0641\u0631\u0627\u062f\u0647 \u0648\u062d\u062f\u0647 \u0628\u0627\u0644\u0639\u0628\u0627\u062f\u0629\u060c \u0648\u0642\u062f \u0643\u0630\u0651\u064e\u0628\u062a\u0645 \u0628\u0647\u0630\u0627\u060c \u0648\u0644\u064a\u0633 \u0641\u064a \u0642\u062f\u0631\u062a\u064a \u0625\u0646\u0632\u0627\u0644 \u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0630\u064a \u062a\u0633\u062a\u0639\u062c\u0644\u0648\u0646 \u0628\u0647\u060c \u0648\u0645\u0627 \u0627\u0644\u062d\u0643\u0645 \u0641\u064a \u062a\u0623\u062e\u0631 \u0630\u0644\u0643 \u0625\u0644\u0627 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u064a\u0642\u0635\u0651\u064f \u0627\u0644\u062d\u0642\u0651\u064e\u060c \u0648\u0647\u0648 \u062e\u064a\u0631 \u0645\u064e\u0646 \u064a\u0641\u0635\u0644 \u0628\u064a\u0646 \u0627\u0644\u062d\u0642 \u0648\u0627\u0644\u0628\u0627\u0637\u0644 \u0628\u0642\u0636\u0627\u0626\u0647 \u0648\u062d\u0643\u0645\u0647.","6:58":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0644\u0648 \u0623\u0646\u0646\u064a \u0623\u0645\u0644\u0643 \u0625\u0646\u0632\u0627\u0644 \u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0630\u064a \u062a\u0633\u062a\u062d\u062c\u0644\u0648\u0646\u0647 \u0644\u0623\u0646\u0632\u0644\u062a\u0647 \u0628\u0643\u0645\u060c \u0648\u0642\u0636\u064a \u0627\u0644\u0623\u0645\u0631 \u0628\u064a\u0646\u064a \u0648\u0628\u064a\u0646\u0643\u0645\u060c \u0648\u0644\u0643\u0646 \u0630\u0644\u0643 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0647\u0648 \u0623\u0639\u0644\u0645 \u0628\u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u062a\u062c\u0627\u0648\u0632\u0648\u0627 \u062d\u062f\u0651\u064e\u0647\u0645 \u0641\u0623\u0634\u0631\u0643\u0648\u0627 \u0645\u0639\u0647 \u063a\u064a\u0631\u0647.","6:59":"\u0648\u0639\u0646\u062f \u0627\u0644\u0644\u0647 -\u062c\u0644 \u0648\u0639\u0644\u0627- \u0645\u0641\u0627\u062a\u062d \u0627\u0644\u063a\u064a\u0628 \u0623\u064a: \u062e\u0632\u0627\u0626\u0646 \u0627\u0644\u063a\u064a\u0628\u060c \u0644\u0627 \u064a\u0639\u0644\u0645\u0647\u0627 \u0625\u0644\u0627 \u0647\u0648\u060c \u0648\u0645\u0646\u0647\u0627: \u0639\u0644\u0645 \u0627\u0644\u0633\u0627\u0639\u0629\u060c \u0648\u0646\u0632\u0648\u0644 \u0627\u0644\u063a\u064a\u062b\u060c \u0648\u0645\u0627 \u0641\u064a \u0627\u0644\u0623\u0631\u062d\u0627\u0645\u060c \u0648\u0627\u0644\u0643\u0633\u0628 \u0641\u064a \u0627\u0644\u0645\u0633\u062a\u0642\u0628\u0644\u060c \u0648\u0645\u0643\u0627\u0646 \u0645\u0648\u062a \u0627\u0644\u0625\u0646\u0633\u0627\u0646\u060c \u0648\u064a\u0639\u0644\u0645 \u0643\u0644 \u0645\u0627 \u0641\u064a \u0627\u0644\u0628\u0631 \u0648\u0627\u0644\u0628\u062d\u0631\u060c \u0648\u0645\u0627 \u062a\u0633\u0642\u0637 \u0645\u0646 \u0648\u0631\u0642\u0629 \u0645\u0646 \u0646\u0628\u062a\u0629 \u0625\u0644\u0627 \u064a\u0639\u0644\u0645\u0647\u0627\u060c \u0641\u0643\u0644 \u062d\u0628\u0629 \u0641\u064a \u062e\u0641\u0627\u064a\u0627 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0643\u0644 \u0631\u0637\u0628 \u0648\u064a\u0627\u0628\u0633\u060c \u0645\u062b\u0628\u062a \u0641\u064a \u0643\u062a\u0627\u0628 \u0648\u0627\u0636\u062d \u0644\u0627 \u0644\u064e\u0628\u0652\u0633 \u0641\u064a\u0647\u060c \u0648\u0647\u0648 \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u0645\u062d\u0641\u0648\u0638.","6:60":"\u0648\u0647\u0648 \u0633\u0628\u062d\u0627\u0646\u0647 \u0627\u0644\u0630\u064a \u064a\u0642\u0628\u0636 \u0623\u0631\u0648\u0627\u062d\u0643\u0645 \u0628\u0627\u0644\u0644\u064a\u0644 \u0628\u0645\u0627 \u064a\u0634\u0628\u0647 \u0642\u0628\u0636\u0647\u0627 \u0639\u0646\u062f \u0627\u0644\u0645\u0648\u062a\u060c \u0648\u064a\u0639\u0644\u0645 \u0645\u0627 \u0627\u0643\u062a\u0633\u0628\u062a\u0645 \u0641\u064a \u0627\u0644\u0646\u0647\u0627\u0631 \u0645\u0646 \u0627\u0644\u0623\u0639\u0645\u0627\u0644\u060c \u062b\u0645 \u064a\u0639\u064a\u062f \u0623\u0631\u0648\u0627\u062d\u0643\u0645 \u0625\u0644\u0649 \u0623\u062c\u0633\u0627\u0645\u0643\u0645 \u0628\u0627\u0644\u064a\u0642\u0638\u0629 \u0645\u0646 \u0627\u0644\u0646\u0648\u0645 \u0646\u0647\u0627\u0631\u064b\u0627 \u0628\u0645\u0627 \u064a\u0634\u0628\u0647 \u0627\u0644\u0623\u062d\u064a\u0627\u0621 \u0628\u0639\u062f \u0627\u0644\u0645\u0648\u062a; \u0644\u062a\u064f\u0642\u0636\u0649 \u0622\u062c\u0627\u0644\u0643\u0645 \u0627\u0644\u0645\u062d\u062f\u062f\u0629 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u062b\u0645 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0645\u0639\u0627\u062f\u0643\u0645 \u0628\u0639\u062f \u0628\u0639\u062b\u0643\u0645 \u0645\u0646 \u0642\u0628\u0648\u0631\u0643\u0645 \u0623\u062d\u064a\u0627\u0621\u064b\u060c \u062b\u0645 \u064a\u062e\u0628\u0631\u0643\u0645 \u0628\u0645\u0627 \u0643\u0646\u062a\u0645 \u062a\u0639\u0645\u0644\u0648\u0646 \u0641\u064a \u062d\u064a\u0627\u062a\u0643\u0645 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u062b\u0645 \u064a\u062c\u0627\u0632\u064a\u0643\u0645 \u0628\u0630\u0644\u0643.","6:61":"\u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0647\u0648 \u0627\u0644\u0642\u0627\u0647\u0631 \u0641\u0648\u0642 \u0639\u0628\u0627\u062f\u0647\u060c \u0641\u0648\u0642\u064a\u0629 \u0645\u0637\u0644\u0642\u0629 \u0645\u0646 \u0643\u0644 \u0648\u062c\u0647\u060c \u062a\u0644\u064a\u0642 \u0628\u062c\u0644\u0627\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649. \u0643\u0644 \u0634\u064a\u0621 \u062e\u0627\u0636\u0639 \u0644\u062c\u0644\u0627\u0644\u0647 \u0648\u0639\u0638\u0645\u062a\u0647\u060c \u0648\u064a\u0631\u0633\u0644 \u0639\u0644\u0649 \u0639\u0628\u0627\u062f\u0647 \u0645\u0644\u0627\u0626\u0643\u0629\u060c \u064a\u062d\u0641\u0638\u0648\u0646 \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0648\u064a\u064f\u062d\u0652\u0635\u0648\u0646\u0647\u0627\u060c \u062d\u062a\u0649 \u0625\u0630\u0627 \u0646\u0632\u0644 \u0627\u0644\u0645\u0648\u062a \u0628\u0623\u062d\u062f\u0647\u0645 \u0642\u0628\u0636 \u0631\u0648\u062d\u064e\u0647 \u0645\u064e\u0644\u0643\u064f \u0627\u0644\u0645\u0648\u062a \u0648\u0623\u0639\u0648\u0627\u0646\u0647\u060c \u0648\u0647\u0645 \u0644\u0627 \u064a\u0636\u064a\u0639\u0648\u0646 \u0645\u0627 \u0623\u064f\u0645\u0631\u0648\u0627 \u0628\u0647.","6:62":"\u062b\u0645 \u0623\u0639\u064a\u062f \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u062a\u0648\u0641\u0648\u0646 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0645\u0648\u0644\u0627\u0647\u0645 \u0627\u0644\u062d\u0642. \u0623\u0644\u0627 \u0644\u0647 \u0627\u0644\u0642\u0636\u0627\u0621 \u0648\u0627\u0644\u0641\u0635\u0644 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0628\u064a\u0646 \u0639\u0628\u0627\u062f\u0647 \u0648\u0647\u0648 \u0623\u0633\u0631\u0639 \u0627\u0644\u062d\u0627\u0633\u0628\u064a\u0646.","6:63":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0645\u0646 \u064a\u0646\u0642\u0630\u0643\u0645 \u0645\u0646 \u0645\u062e\u0627\u0648\u0641 \u0638\u0644\u0645\u0627\u062a \u0627\u0644\u0628\u0631 \u0648\u0627\u0644\u0628\u062d\u0631\u061f \u0623\u0644\u064a\u0633 \u0647\u0648 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0630\u064a \u062a\u062f\u0639\u0648\u0646\u0647 \u0641\u064a \u0627\u0644\u0634\u062f\u0627\u0626\u062f \u0645\u062a\u0630\u0644\u0644\u064a\u0646 \u062c\u0647\u0631\u064b\u0627 \u0648\u0633\u0631\u0651\u064b\u0627\u061f \u062a\u0642\u0648\u0644\u0648\u0646: \u0644\u0626\u0646 \u0623\u0646\u062c\u0627\u0646\u0627 \u0631\u0628\u0646\u0627 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0645\u062e\u0627\u0648\u0641 \u0644\u0646\u0643\u0648\u0646\u0646 \u0645\u0646 \u0627\u0644\u0634\u0627\u0643\u0631\u064a\u0646 \u0628\u0639\u0628\u0627\u062f\u062a\u0647 \u0639\u0632 \u0648\u062c\u0644 \u0648\u062d\u062f\u0647 \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647.","6:64":"\u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0647\u0648 \u0627\u0644\u0630\u064a \u064a\u0646\u0642\u0630\u0643\u0645 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0645\u062e\u0627\u0648\u0641 \u0648\u0645\u0646 \u0643\u0644 \u0634\u062f\u0629\u060c \u062b\u0645 \u0623\u0646\u062a\u0645 \u0628\u0639\u062f \u0630\u0644\u0643 \u062a\u0634\u0631\u0643\u0648\u0646 \u0645\u0639\u0647 \u0641\u064a \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u063a\u064a\u0631\u0647.","6:65":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644 \u0647\u0648 \u0627\u0644\u0642\u0627\u062f\u0631 \u0648\u062d\u062f\u0647 \u0639\u0644\u0649 \u0623\u0646 \u064a\u0631\u0633\u0644 \u0639\u0644\u064a\u0643\u0645 \u0639\u0630\u0627\u0628\u064b\u0627 \u0645\u0650\u0646 \u0641\u0648\u0642\u0643\u0645 \u0643\u0627\u0644\u0631\u0651\u064e\u062c\u0652\u0645 \u0623\u0648 \u0627\u0644\u0637\u0648\u0641\u0627\u0646\u060c \u0648\u0645\u0627 \u0623\u0634\u0628\u0647 \u0630\u0644\u0643\u060c \u0623\u0648 \u0645\u0646 \u062a\u062d\u062a \u0623\u0631\u062c\u0644\u0643\u0645 \u0643\u0627\u0644\u0632\u0644\u0627\u0632\u0644 \u0648\u0627\u0644\u062e\u0633\u0641\u060c \u0623\u0648 \u064a\u062e\u0644\u0637 \u0623\u0645\u0631\u0643\u0645 \u0639\u0644\u064a\u0643\u0645 \u0641\u062a\u0643\u0648\u0646\u0648\u0627 \u0641\u0631\u0642\u064b\u0627 \u0645\u062a\u0646\u0627\u062d\u0631\u0629 \u064a\u0642\u062a\u0644 \u0628\u0639\u0636\u0643\u0645 \u0628\u0639\u0636\u064b\u0627. \u0627\u0646\u0638\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0643\u064a\u0641 \u0646\u064f\u0646\u0648\u0651\u0650\u0639 \u062d\u062c\u062c\u0646\u0627 \u0627\u0644\u0648\u0627\u0636\u062d\u0627\u062a \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0644\u0639\u0644\u0647\u0645 \u064a\u0641\u0647\u0645\u0648\u0646 \u0641\u064a\u0639\u062a\u0628\u0631\u0648\u0627\u061f","6:66":"\u0648\u0643\u0630\u0651\u064e\u0628 \u0628\u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0641\u0627\u0631\u064f \u0645\u0650\u0646 \u0642\u0648\u0645\u0643 \u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644\u060c \u0648\u0647\u0648 \u0627\u0644\u0643\u062a\u0627\u0628 \u0627\u0644\u0635\u0627\u062f\u0642 \u0641\u064a \u0643\u0644 \u0645\u0627 \u062c\u0627\u0621 \u0628\u0647. \u0642\u0644 \u0644\u0647\u0645: \u0644\u0633\u062a \u0639\u0644\u064a\u0643\u0645 \u0628\u062d\u0641\u064a\u0638 \u0648\u0644\u0627 \u0631\u0642\u064a\u0628\u060c \u0648\u0625\u0646\u0645\u0627 \u0623\u0646\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0623\u0628\u0644\u063a\u0643\u0645 \u0645\u0627 \u0623\u0631\u0633\u0644\u062a \u0625\u0644\u064a\u0643\u0645.","6:67":"\u0644\u0643\u0644 \u062e\u0628\u0631 \u0642\u0631\u0627\u0631 \u064a\u0633\u062a\u0642\u0631 \u0639\u0646\u062f\u0647\u060c \u0648\u0646\u0647\u0627\u064a\u0629 \u064a\u0646\u062a\u0647\u064a \u0625\u0644\u064a\u0647\u0627\u060c \u0641\u064a\u062a\u0628\u064a\u0651\u064e\u0646 \u0627\u0644\u062d\u0642 \u0645\u0646 \u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0648\u0633\u0648\u0641 \u062a\u0639\u0644\u0645\u0648\u0646 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0643\u0641\u0627\u0631- \u0639\u0627\u0642\u0628\u0629 \u0623\u0645\u0631\u0643\u0645 \u0639\u0646\u062f \u062d\u0644\u0648\u0644 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647 \u0628\u0643\u0645.","6:68":"\u0648\u0625\u0630\u0627 \u0631\u0623\u064a\u062a -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u062a\u0643\u0644\u0645\u0648\u0646 \u0641\u064a \u0622\u064a\u0627\u062a \u0627\u0644\u0642\u0631\u0622\u0646 \u0628\u0627\u0644\u0628\u0627\u0637\u0644 \u0648\u0627\u0644\u0627\u0633\u062a\u0647\u0632\u0627\u0621\u060c \u0641\u0627\u0628\u062a\u0639\u062f \u0639\u0646\u0647\u0645 \u062d\u062a\u0649 \u064a\u0623\u062e\u0630\u0648\u0627 \u0641\u064a \u062d\u062f\u064a\u062b \u0622\u062e\u0631\u060c \u0648\u0625\u0646 \u0623\u0646\u0633\u0627\u0643 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631 \u0641\u0644\u0627 \u062a\u0642\u0639\u062f \u0628\u0639\u062f \u062a\u0630\u0643\u0631\u0643 \u0645\u0639 \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u0645\u0639\u062a\u062f\u064a\u0646\u060c \u0627\u0644\u0630\u064a\u0646 \u062a\u0643\u0644\u0645\u0648\u0627 \u0641\u064a \u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u0628\u0627\u0637\u0644.","6:69":"\u0648\u0645\u0627 \u0639\u0644\u0649 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u062e\u0627\u0641\u0648\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0641\u064a\u0637\u064a\u0639\u0648\u0646 \u0623\u0648\u0627\u0645\u0631\u0647\u060c \u0648\u064a\u062c\u062a\u0646\u0628\u0648\u0646 \u0646\u0648\u0627\u0647\u064a\u0647 \u0645\u0646 \u062d\u0633\u0627\u0628 \u0627\u0644\u0644\u0647 \u0644\u0644\u062e\u0627\u0626\u0636\u064a\u0646 \u0627\u0644\u0645\u0633\u062a\u0647\u0632\u0626\u064a\u0646 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0645\u0646 \u0634\u064a\u0621\u060c \u0648\u0644\u0643\u0646 \u0639\u0644\u064a\u0647\u0645 \u0623\u0646 \u064a\u0639\u0638\u0648\u0647\u0645 \u0644\u064a\u0645\u0633\u0643\u0648\u0627 \u0639\u0646 \u0630\u0644\u0643 \u0627\u0644\u0643\u0644\u0627\u0645 \u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0644\u0639\u0644\u0647\u0645 \u064a\u062a\u0642\u0648\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649.","6:70":"\u0648\u0627\u062a\u0631\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u062c\u0639\u0644\u0648\u0627 \u062f\u064a\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0644\u0639\u0628\u064b\u0627 \u0648\u0644\u0647\u0648\u064b\u0627; \u0645\u0633\u062a\u0647\u0632\u0626\u064a\u0646 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u063a\u0631\u0651\u064e\u062a\u0647\u0645 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627 \u0628\u0632\u064a\u0646\u062a\u0647\u0627\u060c \u0648\u0630\u0643\u0651\u0631 \u0628\u0627\u0644\u0642\u0631\u0622\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0648\u063a\u064a\u0631\u0647\u0645; \u0643\u064a \u0644\u0627 \u062a\u0631\u062a\u0647\u0646 \u0646\u0641\u0633 \u0628\u0630\u0646\u0648\u0628\u0647\u0627 \u0648\u0643\u0641\u0631\u0647\u0627 \u0628\u0631\u0628\u0647\u0627\u060c \u0644\u064a\u0633 \u0644\u0647\u0627 \u063a\u064a\u0631 \u0627\u0644\u0644\u0647 \u0646\u0627\u0635\u0631 \u064a\u0646\u0635\u0631\u0647\u0627\u060c \u0641\u064a\u0646\u0642\u0630\u0647\u0627 \u0645\u0646 \u0639\u0630\u0627\u0628\u060c \u0648\u0644\u0627 \u0634\u0627\u0641\u0639 \u064a\u0634\u0641\u0639 \u0644\u0647\u0627 \u0639\u0646\u062f\u0647\u060c \u0648\u0625\u0646 \u062a\u064e\u0641\u0652\u062a\u064e\u062f\u0650 \u0628\u0623\u064a \u0641\u062f\u0627\u0621 \u0644\u0627 \u064a\u064f\u0642\u0652\u0628\u064e\u0644 \u0645\u0646\u0647\u0627. \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0630\u064a\u0646 \u0627\u0631\u062a\u064f\u0647\u0650\u0646\u0648\u0627 \u0628\u0630\u0646\u0648\u0628\u0647\u0645\u060c \u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u0646\u0627\u0631 \u0634\u0631\u0627\u0628 \u0634\u062f\u064a\u062f \u0627\u0644\u062d\u0631\u0627\u0631\u0629 \u0648\u0639\u0630\u0627\u0628 \u0645\u0648\u062c\u0639; \u0628\u0633\u0628\u0628 \u0643\u0641\u0631\u0647\u0645 \u0628\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u0651\u064e\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0628\u062f\u064a\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645.","6:71":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0623\u0646\u0639\u0628\u062f \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0623\u0648\u062b\u0627\u0646\u064b\u0627 \u0644\u0627 \u062a\u0646\u0641\u0639 \u0648\u0644\u0627 \u062a\u0636\u0631\u061f \u0648\u0646\u0631\u062c\u0639 \u0625\u0644\u0649 \u0627\u0644\u0643\u0641\u0631 \u0628\u0639\u062f \u0647\u062f\u0627\u064a\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0646\u0627 \u0625\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0641\u0646\u0634\u0628\u0647 -\u0641\u064a \u0631\u062c\u0648\u0639\u0646\u0627 \u0625\u0644\u0649 \u0627\u0644\u0643\u0641\u0631- \u0645\u064e\u0646 \u0641\u0633\u062f \u0639\u0642\u0644\u0647 \u0628\u0627\u0633\u062a\u0647\u0648\u0627\u0621 \u0627\u0644\u0634\u064a\u0627\u0637\u064a\u0646 \u0644\u0647\u060c \u0641\u064e\u0636\u064e\u0644\u0651\u064e \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0644\u0647 \u0631\u0641\u0642\u0629 \u0639\u0642\u0644\u0627\u0621 \u0645\u0624\u0645\u0646\u0648\u0646 \u064a\u062f\u0639\u0648\u0646\u0647 \u0625\u0644\u0649 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0635\u062d\u064a\u062d \u0627\u0644\u0630\u064a \u0647\u0645 \u0639\u0644\u064a\u0647 \u0641\u064a\u0623\u0628\u0649. \u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0625\u0646\u0651\u064e \u0647\u062f\u0649 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u0628\u0639\u062b\u0646\u064a \u0628\u0647 \u0647\u0648 \u0627\u0644\u0647\u062f\u0649 \u0627\u0644\u062d\u0642\u060c \u0648\u0623\u064f\u0645\u0650\u0631\u0646\u0627 \u062c\u0645\u064a\u0639\u064b\u0627 \u0644\u0646\u0633\u0644\u0645 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0646 \u0628\u0639\u0628\u0627\u062f\u062a\u0647 \u0648\u062d\u062f\u0647 \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647\u060c \u0641\u0647\u0648 \u0631\u0628 \u0643\u0644 \u0634\u064a\u0621 \u0648\u0645\u0627\u0644\u0643\u0647.","6:72":"\u0648\u0643\u0630\u0644\u0643 \u0623\u064f\u0645\u0631\u0646\u0627 \u0628\u0623\u0646 \u0646\u0642\u064a\u0645 \u0627\u0644\u0635\u0644\u0627\u0629 \u0643\u0627\u0645\u0644\u0629\u060c \u0648\u0623\u0646 \u0646\u062e\u0634\u0627\u0647 \u0628\u0641\u0639\u0644 \u0623\u0648\u0627\u0645\u0631\u0647 \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0646\u0648\u0627\u0647\u064a\u0647. \u0648\u0647\u0648 -\u062c\u0644 \u0648\u0639\u0644\u0627- \u0627\u0644\u0630\u064a \u0625\u0644\u064a\u0647 \u062a\u064f\u062d\u0652\u0634\u064e\u0631\u064f \u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u0644\u0627\u0626\u0642 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629.","6:73":"\u0648\u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0647\u0648 \u0627\u0644\u0630\u064a \u062e\u0644\u0642 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0628\u0627\u0644\u062d\u0642\u060c \u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0625\u0630 \u064a\u0642\u0648\u0644 \u0627\u0644\u0644\u0647: \xab\u0643\u0646\xbb \u060c \u0641\u064a\u0643\u0648\u0646 \u0639\u0646 \u0623\u0645\u0631\u0647 \u0643\u0644\u0645\u062d \u0627\u0644\u0628\u0635\u0631 \u0623\u0648 \u0647\u0648 \u0623\u0642\u0631\u0628\u060c \u0642\u0648\u0644\u0647 \u0647\u0648 \u0627\u0644\u062d\u0642 \u0627\u0644\u0643\u0627\u0645\u0644\u060c \u0648\u0644\u0647 \u0627\u0644\u0645\u0644\u0643 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062d\u062f\u0647\u060c \u064a\u0648\u0645 \u064a\u0646\u0641\u062e \u0627\u0644\u0645\u064e\u0644\u064e\u0643 \u0641\u064a \xab\u0627\u0644\u0642\u0631\u0646\xbb \u0627\u0644\u0646\u0641\u062e\u0629 \u0627\u0644\u062b\u0627\u0646\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u0643\u0648\u0646 \u0628\u0647\u0627 \u0639\u0648\u062f\u0629 \u0627\u0644\u0623\u0631\u0648\u0627\u062d \u0625\u0644\u0649 \u0627\u0644\u0623\u062c\u0633\u0627\u0645. \u0648\u0647\u0648 \u0633\u0628\u062d\u0627\u0646\u0647 \u0627\u0644\u0630\u064a \u064a\u0639\u0644\u0645 \u0645\u0627 \u063a\u0627\u0628 \u0639\u0646 \u062d\u0648\u0627\u0633\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633 - \u0648\u0645\u0627 \u062a\u0634\u0627\u0647\u062f\u0648\u0646\u0647\u060c \u0648\u0647\u0648 \u0627\u0644\u062d\u0643\u064a\u0645 \u0627\u0644\u0630\u064a \u064a\u0636\u0639 \u0627\u0644\u0623\u0645\u0648\u0631 \u0641\u064a \u0645\u0648\u0627\u0636\u0639\u0647\u0627\u060c \u0627\u0644\u062e\u0628\u064a\u0631 \u0628\u0623\u0645\u0648\u0631 \u062e\u0644\u0642\u0647. \u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0647\u0648 \u0627\u0644\u0630\u064a \u064a\u062e\u062a\u0635 \u0628\u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0648\u0631 \u0648\u063a\u064a\u0631\u0647\u0627 \u0628\u062f\u0621\u064b\u0627 \u0648\u0646\u0647\u0627\u064a\u0629\u060c \u0646\u0634\u0623\u0629 \u0648\u0645\u0635\u064a\u0631\u064b\u0627\u060c \u0648\u0647\u0648 \u0648\u062d\u062f\u0647 \u0627\u0644\u0630\u064a \u064a\u062c\u0628 \u0639\u0644\u0649 \u0627\u0644\u0639\u0628\u0627\u062f \u0627\u0644\u0627\u0646\u0642\u064a\u0627\u062f \u0644\u0634\u0631\u0639\u0647\u060c \u0648\u0627\u0644\u062a\u0633\u0644\u064a\u0645 \u0644\u062d\u0643\u0645\u0647\u060c \u0648\u0627\u0644\u062a\u0637\u0644\u0639 \u0644\u0631\u0636\u0648\u0627\u0646\u0647 \u0648\u0645\u063a\u0641\u0631\u062a\u0647.","6:74":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u064f\u062d\u0627\u062c\u0651\u064e\u0629 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0644\u0623\u0628\u064a\u0647 \u0622\u0632\u0631\u060c \u0625\u0630 \u0642\u0627\u0644 \u0644\u0647: \u0623\u062a\u062c\u0639\u0644 \u0645\u0646 \u0627\u0644\u0623\u0635\u0646\u0627\u0645 \u0622\u0644\u0647\u0629 \u062a\u0639\u0628\u062f\u0647\u0627 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u061f \u0625\u0646\u064a \u0623\u0631\u0627\u0643 \u0648\u0642\u0648\u0645\u0643 \u0641\u064a \u0636\u0644\u0627\u0644 \u0628\u064a\u0651\u0650\u0646 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u062d\u0642.","6:75":"\u0648\u0643\u0645\u0627 \u0647\u062f\u064a\u0646\u0627 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0625\u0644\u0649 \u0627\u0644\u062d\u0642 \u0641\u064a \u0623\u0645\u0631 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0646\u064f\u0631\u064a\u0647 \u0645\u0627 \u062a\u062d\u062a\u0648\u064a \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0645\u0646 \u0645\u0644\u0643 \u0639\u0638\u064a\u0645\u060c \u0648\u0642\u062f\u0631\u0629 \u0628\u0627\u0647\u0631\u0629\u060c \u0644\u064a\u0643\u0648\u0646 \u0645\u0646 \u0627\u0644\u0631\u0627\u0633\u062e\u064a\u0646 \u0641\u064a \u0627\u0644\u0625\u064a\u0645\u0627\u0646.","6:76":"\u0641\u0644\u0645\u0627 \u0623\u0638\u0644\u0645 \u0639\u0644\u0649 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0627\u0644\u0644\u064a\u0644 \u0648\u063a\u0637\u0651\u064e\u0627\u0647 \u0646\u0627\u0638\u0631 \u0642\u0648\u0645\u0647; \u0644\u064a\u062b\u0628\u062a \u0644\u0647\u0645 \u0623\u0646 \u062f\u064a\u0646\u0647\u0645 \u0628\u0627\u0637\u0644\u060c \u0648\u0643\u0627\u0646\u0648\u0627 \u064a\u0639\u0628\u062f\u0648\u0646 \u0627\u0644\u0646\u062c\u0648\u0645. \u0631\u0623\u0649 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0643\u0648\u0643\u0628\u064b\u0627\u060c \u0641\u0642\u0627\u0644 -\u0645\u0633\u062a\u062f\u0631\u062c\u0627 \u0642\u0648\u0645\u0647 \u0644\u0625\u0644\u0632\u0627\u0645\u0647\u0645 \u0628\u0627\u0644\u062a\u0648\u062d\u064a\u062f-: \u0647\u0630\u0627 \u0631\u0628\u064a\u060c \u0641\u0644\u0645\u0627 \u063a\u0627\u0628 \u0627\u0644\u0643\u0648\u0643\u0628\u060c \u0642\u0627\u0644: \u0644\u0627 \u0623\u062d\u0628 \u0627\u0644\u0622\u0644\u0647\u0629 \u0627\u0644\u062a\u064a \u062a\u063a\u064a\u0628.","6:77":"\u0641\u0644\u0645\u0627 \u0631\u0623\u0649 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0627\u0644\u0642\u0645\u0631 \u0637\u0627\u0644\u0639\u064b\u0627 \u0642\u0627\u0644 \u0644\u0642\u0648\u0645\u0647 -\u0639\u0644\u0649 \u0633\u0628\u064a\u0644 \u0627\u0633\u062a\u062f\u0631\u0627\u062c \u0627\u0644\u062e\u0635\u0645-: \u0647\u0630\u0627 \u0631\u0628\u064a\u060c \u0641\u0644\u0645\u0627 \u063a\u0627\u0628\u060c \u0642\u0627\u0644 -\u0645\u0641\u062a\u0642\u0631\u0627 \u0625\u0644\u0649 \u0647\u062f\u0627\u064a\u0629 \u0631\u0628\u0647-: \u0644\u0626\u0646 \u0644\u0645 \u064a\u0648\u0641\u0642\u0646\u064a \u0631\u0628\u064a \u0625\u0644\u0649 \u0627\u0644\u0635\u0648\u0627\u0628 \u0641\u064a \u062a\u0648\u062d\u064a\u062f\u0647\u060c \u0644\u0623\u0643\u0648\u0646\u0646 \u0645\u0646 \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u0636\u0627\u0644\u064a\u0646 \u0639\u0646 \u0633\u0648\u0627\u0621 \u0627\u0644\u0633\u0628\u064a\u0644 \u0628\u0639\u0628\u0627\u062f\u0629 \u063a\u064a\u0631 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649.","6:78":"\u0641\u0644\u0645\u0627 \u0631\u0623\u0649 \u0627\u0644\u0634\u0645\u0633 \u0637\u0627\u0644\u0639\u0629 \u0642\u0627\u0644 \u0644\u0642\u0648\u0645\u0647: \u0647\u0630\u0627 \u0631\u0628\u064a\u060c \u0647\u0630\u0627 \u0623\u0643\u0628\u0631 \u0645\u0646 \u0627\u0644\u0643\u0648\u0643\u0628 \u0648\u0627\u0644\u0642\u0645\u0631\u060c \u0641\u0644\u0645\u0627 \u063a\u0627\u0628\u062a\u060c \u0642\u0627\u0644 \u0644\u0642\u0648\u0645\u0647: \u0625\u0646\u064a \u0628\u0631\u064a\u0621 \u0645\u0645\u0627 \u062a\u0634\u0631\u0643\u0648\u0646 \u0645\u0646 \u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u0648\u0627\u0644\u0646\u062c\u0648\u0645 \u0648\u0627\u0644\u0623\u0635\u0646\u0627\u0645 \u0627\u0644\u062a\u064a \u062a\u0639\u0628\u062f\u0648\u0646\u0647\u0627 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649.","6:79":"\u0625\u0646\u064a \u062a\u0648\u062c\u0651\u064e\u0647\u062a \u0628\u0648\u062c\u0647\u064a \u0641\u064a \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644 \u0648\u062d\u062f\u0647\u060c \u0641\u0647\u0648 \u0627\u0644\u0630\u064a \u062e\u0644\u0642 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0627\u0626\u0644\u0627 \u0639\u0646 \u0627\u0644\u0634\u0631\u0643 \u0625\u0644\u0649 \u0627\u0644\u062a\u0648\u062d\u064a\u062f\u060c \u0648\u0645\u0627 \u0623\u0646\u0627 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0645\u0639 \u0627\u0644\u0644\u0647 \u063a\u064a\u0631\u0647.","6:80":"\u0648\u062c\u0627\u062f\u0644\u0647 \u0642\u0648\u0645\u0647 \u0641\u064a \u062a\u0648\u062d\u064a\u062f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0642\u0627\u0644: \u0623\u062a\u062c\u0627\u062f\u0644\u0648\u0646\u0646\u064a \u0641\u064a \u062a\u0648\u062d\u064a\u062f\u064a \u0644\u0644\u0647 \u0628\u0627\u0644\u0639\u0628\u0627\u062f\u0629\u060c \u0648\u0642\u062f \u0648\u0641\u0642\u0646\u064a \u0625\u0644\u0649 \u0645\u0639\u0631\u0641\u0629 \u0648\u062d\u062f\u0627\u0646\u064a\u062a\u0647\u060c \u0641\u0625\u0646 \u0643\u0646\u062a\u0645 \u062a\u062e\u0648\u0641\u0648\u0646\u0646\u064a \u0628\u0622\u0644\u0647\u062a\u0643\u0645 \u0623\u0646 \u062a\u0648\u0642\u0639 \u0628\u064a \u0636\u0631\u0631\u064b\u0627 \u0641\u0625\u0646\u0646\u064a \u0644\u0627 \u0623\u0631\u0647\u0628\u0647\u0627 \u0641\u0644\u0646 \u062a\u0636\u0631\u0646\u064a\u060c \u0625\u0644\u0627 \u0623\u0646 \u064a\u0634\u0627\u0621 \u0631\u0628\u064a \u0634\u064a\u0626\u064b\u0627. \u0648\u0633\u0639 \u0631\u0628\u064a \u0643\u0644 \u0634\u064a\u0621 \u0639\u0644\u0645\u064b\u0627. \u0623\u0641\u0644\u0627 \u062a\u062a\u0630\u0643\u0631\u0648\u0646 \u0641\u062a\u0639\u0644\u0645\u0648\u0627 \u0623\u0646\u0647 \u0648\u062d\u062f\u0647 \u0627\u0644\u0645\u0639\u0628\u0648\u062f \u0627\u0644\u0645\u0633\u062a\u062d\u0642 \u0644\u0644\u0639\u0628\u0648\u062f\u064a\u0629\u061f","6:81":"\u0648\u0643\u064a\u0641 \u0623\u062e\u0627\u0641 \u0623\u0648\u062b\u0627\u0646\u0643\u0645 \u0648\u0623\u0646\u062a\u0645 \u0644\u0627 \u062a\u062e\u0627\u0641\u0648\u0646 \u0631\u0628\u064a \u0627\u0644\u0630\u064a \u062e\u0644\u0642\u0643\u0645\u060c \u0648\u062e\u0644\u0642 \u0623\u0648\u062b\u0627\u0646\u0643\u0645 \u0627\u0644\u062a\u064a \u0623\u0634\u0631\u0643\u062a\u0645\u0648\u0647\u0627 \u0645\u0639\u0647 \u0641\u064a \u0627\u0644\u0639\u0628\u0627\u062f\u0629\u060c \u0645\u0646 \u063a\u064a\u0631 \u062d\u062c\u0629 \u0644\u0643\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643\u061f \u0641\u0623\u064a \u0627\u0644\u0641\u0631\u064a\u0642\u064a\u0646: \u0641\u0631\u064a\u0642 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0648\u0641\u0631\u064a\u0642 \u0627\u0644\u0645\u0648\u062d\u062f\u064a\u0646 \u0623\u062d\u0642 \u0628\u0627\u0644\u0637\u0645\u0623\u0646\u064a\u0646\u0629 \u0648\u0627\u0644\u0633\u0644\u0627\u0645\u0629 \u0648\u0627\u0644\u0623\u0645\u0646 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647\u061f \u0625\u0646 \u0643\u0646\u062a\u0645 \u062a\u0639\u0644\u0645\u0648\u0646 \u0635\u062f\u0642 \u0645\u0627 \u0623\u0642\u0648\u0644 \u0641\u0623\u062e\u0628\u0631\u0648\u0646\u064a.","6:82":"\u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647 \u0648\u0644\u0645 \u064a\u062e\u0644\u0637\u0648\u0627 \u0625\u064a\u0645\u0627\u0646\u0647\u0645 \u0628\u0634\u0631\u0643\u060c \u0623\u0648\u0644\u0626\u0643 \u0644\u0647\u0645 \u0627\u0644\u0637\u0645\u0623\u0646\u064a\u0646\u0629 \u0648\u0627\u0644\u0633\u0644\u0627\u0645\u0629\u060c \u0648\u0647\u0645 \u0627\u0644\u0645\u0648\u0641\u0642\u0648\u0646 \u0625\u0644\u0649 \u0637\u0631\u064a\u0642 \u0627\u0644\u062d\u0642.","6:83":"\u0648\u062a\u0644\u0643 \u0627\u0644\u062d\u062c\u0629 \u0627\u0644\u062a\u064a \u062d\u0627\u062c\u0651\u064e \u0628\u0647\u0627 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0642\u0648\u0645\u0647 \u0647\u064a \u062d\u062c\u062a\u0646\u0627 \u0627\u0644\u062a\u064a \u0648\u0641\u0642\u0646\u0627\u0647 \u0625\u0644\u064a\u0647\u0627 \u062d\u062a\u0649 \u0627\u0646\u0642\u0637\u0639\u062a \u062d\u062c\u062a\u0647\u0645. \u0646\u0631\u0641\u0639 \u0645\u064e\u0646 \u0646\u0634\u0627\u0621 \u0645\u0646 \u0639\u0628\u0627\u062f\u0646\u0627 \u0645\u0631\u0627\u062a\u0628 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629. \u0625\u0646 \u0631\u0628\u0643 \u062d\u0643\u064a\u0645 \u0641\u064a \u062a\u062f\u0628\u064a\u0631 \u062e\u0644\u0642\u0647\u060c \u0639\u0644\u064a\u0645 \u0628\u0647\u0645.","6:84":"\u0648\u0645\u0646\u0646\u0651\u064e\u0627 \u0639\u0644\u0649 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0628\u0623\u0646 \u0631\u0632\u0642\u0646\u0627\u0647 \u0625\u0633\u062d\u0627\u0642 \u0627\u0628\u0646\u064b\u0627 \u0648\u064a\u0639\u0642\u0648\u0628 \u062d\u0641\u064a\u062f\u064b\u0627\u060c \u0648\u0648\u0641\u0651\u064e\u0642\u0646\u0627 \u0643\u0644\u0627 \u0645\u0646\u0647\u0645\u0627 \u0644\u0633\u0628\u064a\u0644 \u0627\u0644\u0631\u0634\u0627\u062f\u060c \u0648\u0643\u0630\u0644\u0643 \u0648\u0641\u0651\u064e\u0642\u0646\u0627 \u0644\u0644\u062d\u0642 \u0646\u0648\u062d\u064b\u0627 -\u0645\u0646 \u0642\u0628\u0644 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0648\u0625\u0633\u062d\u0627\u0642 \u0648\u064a\u0639\u0642\u0648\u0628- \u0648\u0643\u0630\u0644\u0643 \u0648\u0641\u0651\u064e\u0642\u0646\u0627 \u0644\u0644\u062d\u0642 \u0645\u0646 \u0630\u0631\u064a\u0629 \u0646\u0648\u062d \u062f\u0627\u0648\u062f \u0648\u0633\u0644\u064a\u0645\u0627\u0646 \u0648\u0623\u064a\u0648\u0628 \u0648\u064a\u0648\u0633\u0641 \u0648\u0645\u0648\u0633\u0649 \u0648\u0647\u0627\u0631\u0648\u0646 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u0643\u0645\u0627 \u062c\u0632\u064a\u0646\u0627 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0628\u0625\u062d\u0633\u0627\u0646\u0647\u0645 \u0646\u062c\u0632\u064a \u0643\u0644 \u0645\u062d\u0633\u0646.","6:85":"\u0648\u0643\u0630\u0644\u0643 \u0647\u062f\u064a\u0646\u0627 \u0632\u0643\u0631\u064a\u0627 \u0648\u064a\u062d\u064a\u0649 \u0648\u0639\u064a\u0633\u0649 \u0648\u0625\u0644\u064a\u0627\u0633\u060c \u0648\u0643\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0633\u0644\u0627\u0645 \u0645\u0646 \u0627\u0644\u0635\u0627\u0644\u062d\u064a\u0646.","6:86":"\u0648\u0647\u062f\u064a\u0646\u0627 \u0643\u0630\u0644\u0643 \u0625\u0633\u0645\u0627\u0639\u064a\u0644 \u0648\u0627\u0644\u064a\u0633\u0639 \u0648\u064a\u0648\u0646\u0633 \u0648\u0644\u0648\u0637\u0627\u060c \u0648\u0643\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0631\u0633\u0644 \u0641\u0636\u0651\u064e\u0644\u0646\u0627\u0647\u0645 \u0639\u0644\u0649 \u0623\u0647\u0644 \u0632\u0645\u0627\u0646\u0647\u0645.","6:87":"\u0648\u0643\u0630\u0644\u0643 \u0648\u0641\u0651\u064e\u0642\u0646\u0627 \u0644\u0644\u062d\u0642 \u0645\u0646 \u0634\u0626\u0646\u0627 \u0647\u062f\u0627\u064a\u062a\u0647 \u0645\u0646 \u0622\u0628\u0627\u0621 \u0647\u0624\u0644\u0627\u0621 \u0648\u0630\u0631\u064a\u0627\u062a\u0647\u0645 \u0648\u0625\u062e\u0648\u0627\u0646\u0647\u0645\u060c \u0648\u0627\u062e\u062a\u0631\u0646\u0627\u0647\u0645 \u0644\u062f\u064a\u0646\u0646\u0627 \u0648\u0625\u0628\u0644\u0627\u063a \u0631\u0633\u0627\u0644\u062a\u0646\u0627 \u0625\u0644\u0649 \u0645\u064e\u0646 \u0623\u0631\u0633\u0644\u0646\u0627\u0647\u0645 \u0625\u0644\u064a\u0647\u0645\u060c \u0648\u0623\u0631\u0634\u062f\u0646\u0627\u0647\u0645 \u0625\u0644\u0649 \u0637\u0631\u064a\u0642 \u0635\u062d\u064a\u062d\u060c \u0644\u0627 \u0639\u0648\u062c \u0641\u064a\u0647\u060c \u0648\u0647\u0648 \u062a\u0648\u062d\u064a\u062f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u062a\u0646\u0632\u064a\u0647\u0647 \u0639\u0646 \u0627\u0644\u0634\u0631\u0643.","6:88":"\u0630\u0644\u0643 \u0627\u0644\u0647\u062f\u0649 \u0647\u0648 \u062a\u0648\u0641\u064a\u0642 \u0627\u0644\u0644\u0647\u060c \u0627\u0644\u0630\u064a \u064a\u0648\u0641\u0642 \u0628\u0647 \u0645\u0646 \u064a\u0634\u0627\u0621 \u0645\u0646 \u0639\u0628\u0627\u062f\u0647. \u0648\u0644\u0648 \u0623\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0623\u0634\u0631\u0643\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 -\u0639\u0644\u0649 \u0633\u0628\u064a\u0644 \u0627\u0644\u0641\u0631\u0636 \u0648\u0627\u0644\u062a\u0642\u062f\u064a\u0631- \u0644\u0628\u0637\u0644 \u0639\u0645\u0644\u0647\u0645; \u0644\u0623\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0627 \u064a\u0642\u0628\u0644 \u0645\u0639 \u0627\u0644\u0634\u0631\u0643 \u0639\u0645\u0644\u0627.","6:89":"\u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u0623\u0646\u0639\u0645\u0646\u0627 \u0639\u0644\u064a\u0647\u0645 \u0628\u0627\u0644\u0647\u062f\u0627\u064a\u0629 \u0648\u0627\u0644\u0646\u0628\u0648\u0629 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0622\u062a\u064a\u0646\u0627\u0647\u0645 \u0627\u0644\u0643\u062a\u0627\u0628 \u0643\u0635\u062d\u0641 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0648\u062a\u0648\u0631\u0627\u0629 \u0645\u0648\u0633\u0649 \u0648\u0632\u0628\u0648\u0631 \u062f\u0627\u0648\u062f \u0648\u0625\u0646\u062c\u064a\u0644 \u0639\u064a\u0633\u0649\u060c \u0648\u0622\u062a\u064a\u0646\u0627\u0647\u0645 \u0641\u064e\u0647\u0652\u0645\u064e \u0647\u0630\u0647 \u0627\u0644\u0643\u062a\u0628\u060c \u0648\u0627\u062e\u062a\u0631\u0646\u0627\u0647\u0645 \u0644\u0625\u0628\u0644\u0627\u063a \u0648\u062d\u064a\u0646\u0627\u060c \u0641\u0625\u0646 \u064a\u062c\u062d\u062f -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0628\u0622\u064a\u0627\u062a \u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0641\u0627\u0631\u064f \u0645\u0646 \u0642\u0648\u0645\u0643\u060c \u0641\u0642\u062f \u0648\u0643\u0644\u0646\u0627 \u0628\u0647\u0627 \u0642\u0648\u0645\u064b\u0627 \u0622\u062e\u0631\u064a\u0646 - \u0623\u064a: \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0648\u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0648\u0623\u062a\u0628\u0627\u0639\u0647\u0645 \u0625\u0644\u0649 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629- \u0644\u064a\u0633\u0648\u0627 \u0628\u0647\u0627 \u0628\u0643\u0627\u0641\u0631\u064a\u0646\u060c \u0628\u0644 \u0645\u0624\u0645\u0646\u0648\u0646 \u0628\u0647\u0627\u060c \u0639\u0627\u0645\u0644\u0648\u0646 \u0628\u0645\u0627 \u062a\u062f\u0644 \u0639\u0644\u064a\u0647.","6:90":"\u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0627\u0644\u0645\u0630\u0643\u0648\u0631\u0648\u0646 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0648\u0641\u0642\u0647\u0645 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u062f\u064a\u0646\u0647 \u0627\u0644\u062d\u0642\u060c \u0641\u0627\u062a\u0628\u0639 \u0647\u062f\u0627\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0648\u0627\u0633\u0644\u0643 \u0633\u0628\u064a\u0644\u0647\u0645. \u0642\u0644 \u0644\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0644\u0627 \u0623\u0637\u0644\u0628 \u0645\u0646\u0643\u0645 \u0639\u0644\u0649 \u062a\u0628\u0644\u064a\u063a \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0639\u0648\u0636\u064b\u0627 \u0645\u0646 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0625\u0646\u0652 \u0623\u062c\u0631\u064a \u0625\u0644\u0627 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u0645\u0627 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0625\u0644\u0627 \u062f\u0639\u0648\u0629 \u062c\u0645\u064a\u0639 \u0627\u0644\u0646\u0627\u0633 \u0625\u0644\u0649 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645 \u0648\u062a\u0630\u0643\u064a\u0631 \u0644\u0643\u0645 \u0648\u0644\u0643\u0644 \u0645\u064e\u0646 \u0643\u0627\u0646 \u0645\u062b\u0644\u0643\u0645\u060c \u0645\u0645\u0646 \u0647\u0648 \u0645\u0642\u064a\u0645 \u0639\u0644\u0649 \u0628\u0627\u0637\u0644\u060c \u0644\u0639\u0644\u0643\u0645 \u062a\u062a\u0630\u0643\u0631\u0648\u0646 \u0628\u0647 \u0645\u0627 \u064a\u0646\u0641\u0639\u0643\u0645.","6:91":"\u0648\u0645\u0627 \u0639\u064e\u0638\u0651\u064e\u0645 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0627\u0644\u0644\u0647 \u062d\u0642 \u062a\u0639\u0638\u064a\u0645\u0647; \u0625\u0630 \u0623\u0646\u0643\u0631\u0648\u0627 \u0623\u0646 \u064a\u0643\u0648\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0642\u062f \u0623\u0646\u0632\u0644 \u0639\u0644\u0649 \u0623\u062d\u062f \u0645\u0646 \u0627\u0644\u0628\u0634\u0631 \u0634\u064a\u0626\u064b\u0627 \u0645\u0646 \u0648\u062d\u064a\u0647. \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0625\u0630\u0627 \u0643\u0627\u0646 \u0627\u0644\u0623\u0645\u0631 \u0643\u0645\u0627 \u062a\u0632\u0639\u0645\u0648\u0646\u060c \u0641\u0645\u0646 \u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0627\u0644\u0630\u064a \u062c\u0627\u0621 \u0628\u0647 \u0645\u0648\u0633\u0649 \u0625\u0644\u0649 \u0642\u0648\u0645\u0647 \u0646\u0648\u0631\u064b\u0627 \u0644\u0644\u0646\u0627\u0633 \u0648\u0647\u062f\u0627\u064a\u0629 \u0644\u0647\u0645\u061f \u062b\u0645 \u062a\u0648\u062c\u0647 \u0627\u0644\u062e\u0637\u0627\u0628 \u0625\u0644\u0649 \u0627\u0644\u064a\u0647\u0648\u062f \u0632\u064e\u062c\u0652\u0631\u064b\u0627 \u0644\u0647\u0645 \u0628\u0642\u0648\u0644\u0647: \u062a\u062c\u0639\u0644\u0648\u0646 \u0647\u0630\u0627 \u0627\u0644\u0643\u062a\u0627\u0628 \u0641\u064a \u0642\u0631\u0627\u0637\u064a\u0633 \u0645\u062a\u0641\u0631\u0642\u0629\u060c \u062a\u0638\u0647\u0631\u0648\u0646 \u0628\u0639\u0636\u0647\u0627\u060c \u0648\u062a\u0643\u062a\u0645\u0648\u0646 \u0643\u062b\u064a\u0631\u064b\u0627 \u0645\u0646\u0647\u0627\u060c \u0648\u0645\u0645\u0627 \u0643\u062a\u0645\u0648\u0647 \u0627\u0644\u0625\u062e\u0628\u0627\u0631 \u0639\u0646 \u0635\u0641\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0646\u0628\u0648\u062a\u0647\u060c \u0648\u0639\u0644\u0651\u064e\u0645\u0643\u0645 \u0627\u0644\u0644\u0647 \u0645\u0639\u0634\u0631 \u0627\u0644\u0639\u0631\u0628 \u0628\u0627\u0644\u0642\u0631\u0622\u0646\u0650 -\u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644\u0647 \u0639\u0644\u064a\u0643\u0645\u060c \u0641\u064a\u0647 \u062e\u0628\u0631 \u0645\u064e\u0646 \u0642\u0628\u0644\u0643\u0645 \u0648\u0645\u064e\u0646 \u0628\u0639\u062f\u0643\u0645\u060c \u0648\u0645\u0627 \u064a\u0643\u0648\u0646 \u0628\u0639\u062f \u0645\u0648\u062a\u0643\u0645- \u0645\u0627 \u0644\u0645 \u062a\u0639\u0644\u0645\u0648\u0647 \u0623\u0646\u062a\u0645 \u0648\u0644\u0627 \u0622\u0628\u0627\u0624\u0643\u0645\u060c \u0642\u0644: \u0627\u0644\u0644\u0647 \u0647\u0648 \u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644\u0647\u060c \u062b\u0645 \u062f\u0639 \u0647\u0624\u0644\u0627\u0621 \u0641\u064a \u062d\u062f\u064a\u062b\u0647\u0645 \u0627\u0644\u0628\u0627\u0637\u0644 \u064a\u062e\u0648\u0636\u0648\u0646 \u0648\u064a\u0644\u0639\u0628\u0648\u0646.","6:92":"\u0648\u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0622\u0646 \u0643\u062a\u0627\u0628 \u0623\u0646\u0632\u0644\u0646\u0627\u0647 \u0625\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0639\u0638\u064a\u0645 \u0627\u0644\u0646\u0641\u0639\u060c \u064a\u0634\u0647\u062f \u0639\u0644\u0649 \u0635\u062f\u0642 \u0645\u0627 \u062a\u0642\u062f\u0645\u0647 \u0645\u0646 \u0627\u0644\u0643\u062a\u0628 \u0627\u0644\u0645\u0646\u0632\u0644\u0629 \u0648\u0623\u0646\u0647\u0627 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0623\u0646\u0632\u0644\u0646\u0627\u0647 \u0644\u0646\u062e\u0648\u0651\u0650\u0641 \u0628\u0647 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647 \u0648\u0628\u0623\u0633\u0647 \u0623\u0647\u0644 \xab\u0645\u0643\u0629\xbb \u0648\u0645\u0646 \u062d\u0648\u0644\u0647\u0627 \u0645\u0646 \u0623\u0647\u0644 \u0623\u0642\u0637\u0627\u0631 \u0627\u0644\u0623\u0631\u0636 \u0643\u0644\u0647\u0627. \u0648\u0627\u0644\u0630\u064a\u0646 \u064a\u0635\u062f\u0642\u0648\u0646 \u0628\u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u064a\u0635\u062f\u0642\u0648\u0646 \u0628\u0623\u0646 \u0627\u0644\u0642\u0631\u0622\u0646 \u0643\u0644\u0627\u0645 \u0627\u0644\u0644\u0647\u060c \u0648\u064a\u062d\u0627\u0641\u0638\u0648\u0646 \u0639\u0644\u0649 \u0625\u0642\u0627\u0645 \u0627\u0644\u0635\u0644\u0627\u0629 \u0641\u064a \u0623\u0648\u0642\u0627\u062a\u0647\u0627.","6:93":"\u0648\u0645\u064e\u0646 \u0623\u0634\u062f\u0651\u064f \u0638\u0644\u0645\u0651\u064e\u0627 \u0645\u0645\u0651\u064e\u0646 \u0627\u062e\u062a\u0644\u0642 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0642\u0648\u0644\u0627 \u0643\u0630\u0628\u064b\u0627\u060c \u0641\u0627\u062f\u0639\u0649 \u0623\u0646\u0647 \u0644\u0645 \u064a\u0628\u0639\u062b \u0631\u0633\u0648\u0644\u0627 \u0645\u0646 \u0627\u0644\u0628\u0634\u0631\u060c \u0623\u0648 \u0627\u062f\u0639\u0649 \u0643\u0630\u0628\u064b\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0623\u0648\u062d\u0649 \u0625\u0644\u064a\u0647 \u0648\u0644\u0645 \u064a\u064f\u0648\u062d\u0650 \u0625\u0644\u064a\u0647 \u0634\u064a\u0626\u064b\u0627\u060c \u0623\u0648 \u0627\u062f\u0651\u064e\u0639\u0649 \u0623\u0646\u0647 \u0642\u0627\u062f\u0631 \u0639\u0644\u0649 \u0623\u0646 \u064a\u064f\u0646\u0652\u0632\u0644 \u0645\u062b\u0644 \u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0642\u0631\u0622\u0646\u061f \u0648\u0644\u0648 \u0623\u0646\u0643 \u0623\u0628\u0635\u0631\u062a -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u062a\u062c\u0627\u0648\u0632\u064a\u0646 \u0627\u0644\u062d\u062f\u0651\u064e \u0648\u0647\u0645 \u0641\u064a \u0623\u0647\u0648\u0627\u0644 \u0627\u0644\u0645\u0648\u062a \u0644\u0631\u0623\u064a\u062a \u0623\u0645\u0631\u064b\u0627 \u0647\u0627\u0626\u0644\u0627 \u0648\u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0627\u0644\u0630\u064a\u0646 \u064a\u0642\u0628\u0636\u0648\u0646 \u0623\u0631\u0648\u0627\u062d\u0647\u0645 \u0628\u0627\u0633\u0637\u0648 \u0623\u064a\u062f\u064a\u0647\u0645 \u0628\u0627\u0644\u0639\u0630\u0627\u0628 \u0642\u0627\u0626\u0644\u064a\u0646 \u0644\u0647\u0645: \u0623\u062e\u0631\u062c\u0648\u0627 \u0623\u0646\u0641\u0633\u0643\u0645\u060c \u0627\u0644\u064a\u0648\u0645 \u062a\u0647\u0627\u0646\u0648\u0646 \u063a\u0627\u064a\u0629 \u0627\u0644\u0625\u0647\u0627\u0646\u0629\u060c \u0643\u0645\u0627 \u0643\u0646\u062a\u0645 \u062a\u0643\u0630\u0628\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u062a\u0633\u062a\u0643\u0628\u0631\u0648\u0646 \u0639\u0646 \u0627\u062a\u0628\u0627\u0639 \u0622\u064a\u0627\u062a\u0647 \u0648\u0627\u0644\u0627\u0646\u0642\u064a\u0627\u062f \u0644\u0631\u0633\u0644\u0647.","6:94":"\u0648\u0644\u0642\u062f \u062c\u0626\u062a\u0645\u0648\u0646\u0627 \u0644\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u062c\u0632\u0627\u0621 \u0641\u0631\u0627\u062f\u0649 \u0643\u0645\u0627 \u0623\u0648\u062c\u062f\u0646\u0627\u0643\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0623\u0648\u0644 \u0645\u0631\u0629 \u062d\u0641\u0627\u0629 \u0639\u0631\u0627\u0629\u060c \u0648\u062a\u0631\u0643\u062a\u0645 \u0648\u0631\u0627\u0621 \u0638\u0647\u0648\u0631\u0643\u0645 \u0645\u0627 \u0645\u0643\u0646\u0651\u064e\u0627\u0643\u0645 \u0641\u064a\u0647 \u0645\u0645\u0627 \u062a\u062a\u0628\u0627\u0647\u0648\u0646 \u0628\u0647 \u0645\u0646 \u0623\u0645\u0648\u0627\u0644 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0645\u0627 \u0646\u0631\u0649 \u0645\u0639\u0643\u0645 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0623\u0648\u062b\u0627\u0646\u0643\u0645 \u0627\u0644\u062a\u064a \u0643\u0646\u062a\u0645 \u062a\u0639\u062a\u0642\u062f\u0648\u0646 \u0623\u0646\u0647\u0627 \u062a\u0634\u0641\u0639 \u0644\u0643\u0645\u060c \u0648\u062a\u064e\u062f\u0651\u064e\u0639\u0648\u0646 \u0623\u0646\u0647\u0627 \u0634\u0631\u0643\u0627\u0621 \u0645\u0639 \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u0639\u0628\u0627\u062f\u0629\u060c \u0644\u0642\u062f \u0632\u0627\u0644 \u062a\u064e\u0648\u0627\u0635\u064f\u0644\u064f\u0643\u0645 \u0627\u0644\u0630\u064a \u0643\u0627\u0646 \u0628\u064a\u0646\u0643\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0630\u0647\u0628 \u0639\u0646\u0643\u0645 \u0645\u0627 \u0643\u0646\u062a\u0645 \u062a\u064e\u062f\u0651\u064e\u0639\u0648\u0646 \u0645\u0646 \u0623\u0646 \u0622\u0644\u0647\u062a\u0643\u0645 \u0634\u0631\u0643\u0627\u0621 \u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u0639\u0628\u0627\u062f\u0629\u060c \u0648\u0638\u0647\u0631 \u0623\u0646\u0643\u0645 \u0627\u0644\u062e\u0627\u0633\u0631\u0648\u0646 \u0644\u0623\u0646\u0641\u0633\u0643\u0645 \u0648\u0623\u0647\u0644\u064a\u0643\u0645 \u0648\u0623\u0645\u0648\u0627\u0644\u0643\u0645.","6:95":"\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u064a\u0634\u0642 \u0627\u0644\u062d\u0628\u060c \u0641\u064a\u062e\u0631\u062c \u0645\u0646\u0647 \u0627\u0644\u0632\u0631\u0639\u060c \u0648\u064a\u0634\u0642 \u0627\u0644\u0646\u0648\u0649\u060c \u0641\u064a\u062e\u0631\u062c \u0645\u0646\u0647 \u0627\u0644\u0634\u062c\u0631\u060c \u064a\u062e\u0631\u062c \u0627\u0644\u062d\u064a \u0645\u0646 \u0627\u0644\u0645\u064a\u062a \u0643\u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0648\u0627\u0644\u062d\u064a\u0648\u0627\u0646 \u0645\u062b\u0644\u0627 \u0645\u0646 \u0627\u0644\u0646\u0637\u0641\u0629\u060c \u0648\u064a\u062e\u0631\u062c \u0627\u0644\u0645\u064a\u062a \u0645\u0646 \u0627\u0644\u062d\u064a \u0643\u0627\u0644\u0646\u0637\u0641\u0629 \u0645\u0646 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0648\u0627\u0644\u062d\u064a\u0648\u0627\u0646\u060c \u0630\u0644\u0643\u0645 \u0627\u0644\u0644\u0647 \u0623\u064a: \u0641\u0627\u0639\u0644 \u0647\u0630\u0627 \u0647\u0648 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647 \u0627\u0644\u0645\u0633\u062a\u062d\u0642 \u0644\u0644\u0639\u0628\u0627\u062f\u0629\u060c \u0641\u0643\u064a\u0641 \u062a\u064f\u0635\u0652\u0631\u064e\u0641\u0648\u0646 \u0639\u0646 \u0627\u0644\u062d\u0642 \u0625\u0644\u0649 \u0627\u0644\u0628\u0627\u0637\u0644 \u0641\u062a\u0639\u0628\u062f\u0648\u0646 \u0645\u0639\u0647 \u063a\u064a\u0631\u0647\u061f","6:96":"\u0648\u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0647\u0648 \u0627\u0644\u0630\u064a \u0634\u0642 \u0636\u064a\u0627\u0621 \u0627\u0644\u0635\u0628\u0627\u062d \u0645\u0646 \u0638\u0644\u0627\u0645 \u0627\u0644\u0644\u064a\u0644\u060c \u0648\u062c\u0639\u0644 \u0627\u0644\u0644\u064a\u0644 \u0645\u0633\u062a\u0642\u0631\u064b\u0627\u060c \u064a\u0633\u0643\u0646 \u0641\u064a\u0647 \u0645\u0646 \u064a\u062a\u0639\u0628 \u0628\u0627\u0644\u0646\u0647\u0627\u0631 \u0641\u064a\u0623\u062e\u0630 \u0646\u0635\u064a\u0628\u0647 \u0645\u0646 \u0627\u0644\u0631\u0627\u062d\u0629\u060c \u0648\u062c\u0639\u0644 \u0627\u0644\u0634\u0645\u0633 \u0648\u0627\u0644\u0642\u0645\u0631 \u064a\u062c\u0631\u064a\u0627\u0646 \u0641\u064a \u0641\u0644\u0643\u064a\u0647\u0645\u0627 \u0628\u062d\u0633\u0627\u0628 \u0645\u062a\u0642\u0646 \u0645\u0642\u062f\u0651\u064e\u0631\u060c \u0644\u0627 \u064a\u062a\u063a\u064a\u0631 \u0648\u0644\u0627 \u064a\u0636\u0637\u0631\u0628\u060c \u0630\u0644\u0643 \u062a\u0642\u062f\u064a\u0631 \u0627\u0644\u0639\u0632\u064a\u0632 \u0627\u0644\u0630\u064a \u0639\u0632\u0651\u064e \u0633\u0644\u0637\u0627\u0646\u0647\u060c \u0627\u0644\u0639\u0644\u064a\u0645 \u0628\u0645\u0635\u0627\u0644\u062d \u062e\u0644\u0642\u0647 \u0648\u062a\u062f\u0628\u064a\u0631 \u0634\u0626\u0648\u0646\u0647\u0645. \u0648\u0627\u0644\u0639\u0632\u064a\u0632 \u0648\u0627\u0644\u0639\u0644\u064a\u0645 \u0645\u0646 \u0623\u0633\u0645\u0627\u0621 \u0627\u0644\u0644\u0647 \u0627\u0644\u062d\u0633\u0646\u0649 \u064a\u062f\u0644\u0627\u0646 \u0639\u0644\u0649 \u0643\u0645\u0627\u0644 \u0627\u0644\u0639\u0632\u0629 \u0648\u0627\u0644\u0639\u0644\u0645.","6:97":"\u0648\u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0647\u0648 \u0627\u0644\u0630\u064a \u062c\u0639\u0644 \u0644\u0643\u0645 \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633 \u0627\u0644\u0646\u062c\u0648\u0645 \u0639\u0644\u0627\u0645\u0627\u062a\u060c \u062a\u0639\u0631\u0641\u0648\u0646 \u0628\u0647\u0627 \u0627\u0644\u0637\u0631\u0642 \u0644\u064a\u0644\u0627 \u0625\u0630\u0627 \u0636\u0644\u0644\u062a\u0645 \u0628\u0633\u0628\u0628 \u0627\u0644\u0638\u0644\u0645\u0629 \u0627\u0644\u0634\u062f\u064a\u062f\u0629 \u0641\u064a \u0627\u0644\u0628\u0631 \u0648\u0627\u0644\u0628\u062d\u0631\u060c \u0642\u062f \u0628\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0627\u0644\u0628\u0631\u0627\u0647\u064a\u0646 \u0627\u0644\u0648\u0627\u0636\u062d\u0629; \u0644\u064a\u062a\u062f\u0628\u0631\u0647\u0627 \u0645\u0646\u0643\u0645 \u0623\u0648\u0644\u0648 \u0627\u0644\u0639\u0644\u0645 \u0628\u0627\u0644\u0644\u0647 \u0648\u0634\u0631\u0639\u0647.","6:98":"\u0648\u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0647\u0648 \u0627\u0644\u0630\u064a \u0627\u0628\u062a\u062f\u0623 \u062e\u0644\u0642\u0643\u0645 \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633 \u0645\u0646 \u0622\u062f\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645; \u0625\u0630 \u062e\u0644\u0642\u0647 \u0645\u0646 \u0637\u064a\u0646\u060c \u062b\u0645 \u0643\u0646\u062a\u0645 \u0633\u0644\u0627\u0644\u0629 \u0648\u0646\u0633\u0644\u0627 \u0645\u0646\u0647\u060c \u0641\u062c\u0639\u0644 \u0644\u0643\u0645 \u0645\u0633\u062a\u0642\u064e\u0631\u064b\u0627 \u062a\u0633\u062a\u0642\u0631\u0648\u0646 \u0641\u064a\u0647\u060c \u0648\u0647\u0648 \u0623\u0631\u062d\u0627\u0645 \u0627\u0644\u0646\u0633\u0627\u0621\u060c \u0648\u0645\u064f\u0633\u062a\u0648\u062f\u0639\u064b\u0627 \u062a\u064f\u062d\u0641\u064e\u0638\u064f\u0648\u0646 \u0641\u064a\u0647\u060c \u0648\u0647\u0648 \u0623\u0635\u0644\u0627\u0628 \u0627\u0644\u0631\u062c\u0627\u0644\u060c \u0642\u062f \u0628\u064a\u0646\u0627 \u0627\u0644\u062d\u062c\u062c \u0648\u0645\u064a\u0632\u0646\u0627 \u0627\u0644\u0623\u062f\u0644\u0629\u060c \u0648\u0623\u062d\u0643\u0645\u0646\u0627\u0647\u0627 \u0644\u0642\u0648\u0645 \u064a\u0641\u0647\u0645\u0648\u0646 \u0645\u0648\u0627\u0642\u0639 \u0627\u0644\u062d\u062c\u062c \u0648\u0645\u0648\u0627\u0636\u0639 \u0627\u0644\u0639\u0628\u0631.","6:99":"\u0648\u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0647\u0648 \u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644 \u0645\u0646 \u0627\u0644\u0633\u062d\u0627\u0628 \u0645\u0637\u0631\u064b\u0627 \u0641\u0623\u062e\u0631\u062c \u0628\u0647 \u0646\u0628\u0627\u062a \u0643\u0644 \u0634\u064a\u0621\u060c \u0641\u0623\u062e\u0631\u062c \u0645\u0646 \u0627\u0644\u0646\u0628\u0627\u062a \u0632\u0631\u0639\u064b\u0627 \u0648\u0634\u062c\u0631\u064b\u0627 \u0623\u062e\u0636\u0631\u060c \u062b\u0645 \u0623\u062e\u0631\u062d \u0645\u0646 \u0627\u0644\u0632\u0631\u0639 \u062d\u064e\u0628\u0651\u064b\u0627 \u064a\u0631\u0643\u0628 \u0628\u0639\u0636\u0647 \u0628\u0639\u0636\u064b\u0627\u060c \u0643\u0633\u0646\u0627\u0628\u0644 \u0627\u0644\u0642\u0645\u062d \u0648\u0627\u0644\u0634\u0639\u064a\u0631 \u0648\u0627\u0644\u0623\u0631\u0632\u060c \u0648\u0623\u062e\u0631\u062c \u0645\u0646 \u0637\u0644\u0639 \u0627\u0644\u0646\u062e\u0644 -\u0648\u0647\u0648 \u0645\u0627 \u062a\u0646\u0634\u0623 \u0641\u064a\u0647 \u0639\u0630\u0648\u0642 \u0627\u0644\u0631\u0637\u0628- \u0639\u0630\u0648\u0642\u064b\u0627 \u0642\u0631\u064a\u0628\u0629 \u0627\u0644\u062a\u0646\u0627\u0648\u0644\u060c \u0648\u0623\u062e\u0631\u062c \u0633\u0628\u062d\u0627\u0646\u0647 \u0628\u0633\u0627\u062a\u064a\u0646 \u0645\u0646 \u0623\u0639\u0646\u0627\u0628\u060c \u0648\u0623\u062e\u0631\u062c \u0634\u062c\u0631 \u0627\u0644\u0632\u064a\u062a\u0648\u0646 \u0648\u0627\u0644\u0631\u0645\u0627\u0646 \u0627\u0644\u0630\u064a \u064a\u062a\u0634\u0627\u0628\u0647 \u0641\u064a \u0648\u0631\u0642\u0647 \u0648\u064a\u062e\u062a\u0644\u0641 \u0641\u064a \u062b\u0645\u0631\u0647 \u0634\u0643\u0644\u0627 \u0648\u0637\u0639\u0645\u064b\u0627 \u0648\u0637\u0628\u0639\u064b\u0627. \u0627\u0646\u0638\u0631\u0648\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633 \u0625\u0644\u0649 \u062b\u0645\u0631 \u0647\u0630\u0627 \u0627\u0644\u0646\u0628\u0627\u062a \u0625\u0630\u0627 \u0623\u062b\u0645\u0631\u060c \u0648\u0625\u0644\u0649 \u0646\u0636\u062c\u0647 \u0648\u0628\u0644\u0648\u063a\u0647 \u062d\u064a\u0646 \u064a\u0628\u0644\u063a. \u0625\u0646 \u0641\u064a \u0630\u0644\u0643\u0645 - \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633 - \u0644\u062f\u0644\u0627\u0644\u0627\u062a \u0639\u0644\u0649 \u0643\u0645\u0627\u0644 \u0642\u062f\u0631\u0629 \u062e\u0627\u0644\u0642 \u0647\u0630\u0647 \u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0648\u062d\u0643\u0645\u062a\u0647 \u0648\u0631\u062d\u0645\u062a\u0647 \u0644\u0642\u0648\u0645 \u064a\u0635\u062f\u0642\u0648\u0646 \u0628\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u064a\u0639\u0645\u0644\u0648\u0646 \u0628\u0634\u0631\u0639\u0647.","6:100":"\u0648\u062c\u0639\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0627\u0644\u062c\u0646 \u0634\u0631\u0643\u0627\u0621 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0641\u064a \u0627\u0644\u0639\u0628\u0627\u062f\u0629; \u0627\u0639\u062a\u0642\u0627\u062f\u064b\u0627 \u0645\u0646\u0647\u0645 \u0623\u0646\u0647\u0645 \u064a\u0646\u0641\u0639\u0648\u0646 \u0623\u0648 \u064a\u0636\u0631\u0648\u0646\u060c \u0648\u0642\u062f \u062e\u0644\u0642\u0647\u0645 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0645\u0627 \u064a\u0639\u0628\u062f\u0648\u0646 \u0645\u0646 \u0627\u0644\u0639\u062f\u0645\u060c \u0641\u0647\u0648 \u0627\u0644\u0645\u0633\u062a\u0642\u0644 \u0628\u0627\u0644\u062e\u0644\u0642 \u0648\u062d\u062f\u0647\u060c \u0641\u064a\u062c\u0628 \u0623\u0646 \u064a\u0633\u062a\u0642\u0644 \u0628\u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0648\u062d\u062f\u0647 \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647. \u0648\u0644\u0642\u062f \u0643\u0630\u0628 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u062d\u064a\u0646 \u0646\u0633\u0628\u0648\u0627 \u0625\u0644\u064a\u0647 \u0627\u0644\u0628\u0646\u064a\u0646 \u0648\u0627\u0644\u0628\u0646\u0627\u062a; \u062c\u0647\u0644\u0627 \u0645\u0646\u0647\u0645 \u0628\u0645\u0627 \u064a\u062c\u0628 \u0644\u0647 \u0645\u0646 \u0635\u0641\u0627\u062a \u0627\u0644\u0643\u0645\u0627\u0644\u060c \u062a\u0646\u0632\u0651\u064e\u0647 \u0648\u0639\u0644\u0627 \u0639\u0645\u0627 \u0646\u0633\u0628\u0647 \u0625\u0644\u064a\u0647 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0645\u0646 \u0630\u0644\u0643 \u0627\u0644\u0643\u0630\u0628 \u0648\u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0621.","6:101":"\u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0647\u0648 \u0627\u0644\u0630\u064a \u0623\u0648\u062c\u062f \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0648\u0645\u0627 \u0641\u064a\u0647\u0646 \u0639\u0644\u0649 \u063a\u064a\u0631 \u0645\u062b\u0627\u0644 \u0633\u0627\u0628\u0642. \u0643\u064a\u0641 \u064a\u0643\u0648\u0646 \u0644\u0647 \u0648\u0644\u062f \u0648\u0644\u0645 \u062a\u0643\u0646 \u0644\u0647 \u0635\u0627\u062d\u0628\u0629\u061f \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0645\u0627 \u064a\u0642\u0648\u0644 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0639\u0644\u0648\u0651\u064b\u0627 \u0643\u0628\u064a\u0631\u064b\u0627\u060c \u0648\u0647\u0648 \u0627\u0644\u0630\u064a \u062e\u0644\u0642 \u0643\u0644 \u0634\u064a\u0621 \u0645\u0646 \u0627\u0644\u0639\u062f\u0645\u060c \u0648\u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0634\u064a\u0621 \u0645\u0646 \u0623\u0645\u0648\u0631 \u0627\u0644\u062e\u0644\u0642.","6:102":"\u0630\u0644\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646- \u0647\u0648 \u0631\u0628\u0643\u0645 \u062c\u0644 \u0648\u0639\u0644\u0627 \u0644\u0627 \u0645\u0639\u0628\u0648\u062f \u0628\u062d\u0642 \u0633\u0648\u0627\u0647\u060c \u062e\u0627\u0644\u0642 \u0643\u0644 \u0634\u064a\u0621 \u0641\u0627\u0646\u0642\u0627\u062f\u0648\u0627 \u0648\u0627\u062e\u0636\u0639\u0648\u0627 \u0644\u0647 \u0628\u0627\u0644\u0637\u0627\u0639\u0629 \u0648\u0627\u0644\u0639\u0628\u0627\u062f\u0629. \u0648\u0647\u0648 \u0633\u0628\u062d\u0627\u0646\u0647 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621 \u0648\u0643\u064a\u0644 \u0648\u062d\u0641\u064a\u0638\u060c \u064a\u062f\u0628\u0631 \u0623\u0645\u0648\u0631 \u062e\u0644\u0642\u0647.","6:103":"\u0644\u0627 \u062a\u0631\u0649 \u0627\u0644\u0644\u0647\u064e \u0627\u0644\u0623\u0628\u0635\u0627\u0631\u064f \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0623\u0645\u0627 \u0641\u064a \u0627\u0644\u062f\u0627\u0631 \u0627\u0644\u0622\u062e\u0631\u0629 \u0641\u0625\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u064a\u0631\u0648\u0646 \u0631\u0628\u0647\u0645 \u0628\u063a\u064a\u0631 \u0625\u062d\u0627\u0637\u0629\u060c \u0648\u0647\u0648 \u0633\u0628\u062d\u0627\u0646\u0647 \u064a\u062f\u0631\u0643 \u0627\u0644\u0623\u0628\u0635\u0627\u0631 \u0648\u064a\u062d\u064a\u0637 \u0628\u0647\u0627\u060c \u0648\u064a\u0639\u0644\u0645\u0647\u0627 \u0639\u0644\u0649 \u0645\u0627 \u0647\u064a \u0639\u0644\u064a\u0647\u060c \u0648\u0647\u0648 \u0627\u0644\u0644\u0637\u064a\u0641 \u0628\u0623\u0648\u0644\u064a\u0627\u0626\u0647 \u0627\u0644\u0630\u064a \u064a\u0639\u0644\u0645 \u062f\u0642\u0627\u0626\u0642 \u0627\u0644\u0623\u0634\u064a\u0627\u0621\u060c \u0627\u0644\u062e\u0628\u064a\u0631 \u0627\u0644\u0630\u064a \u064a\u0639\u0644\u0645 \u0628\u0648\u0627\u0637\u0646\u0647\u0627.","6:104":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0642\u062f \u062c\u0627\u0621\u062a\u0643\u0645 \u0628\u0631\u0627\u0647\u064a\u0646 \u0638\u0627\u0647\u0631\u0629 \u062a\u0628\u0635\u0631\u0648\u0646 \u0628\u0647\u0627 \u0627\u0644\u0647\u062f\u0649 \u0645\u0646 \u0627\u0644\u0636\u0644\u0627\u0644\u060c \u0645\u0645\u0627 \u0627\u0634\u062a\u0645\u0644 \u0639\u0644\u064a\u0647\u0627 \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0648\u062c\u0627\u0621 \u0628\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0641\u0645\u064e\u0646 \u062a\u0628\u064a\u0651\u064e\u0646 \u0647\u0630\u0647 \u0627\u0644\u0628\u0631\u0627\u0647\u064a\u0646 \u0648\u0622\u0645\u0646 \u0628\u0645\u062f\u0644\u0648\u0644\u0647\u0627 \u0641\u0646\u064e\u0641\u0652\u0639\u064f \u0630\u0644\u0643 \u0644\u0646\u0641\u0633\u0647\u060c \u0648\u0645\u064e\u0646 \u0644\u0645 \u064a\u0628\u0635\u0631 \u0627\u0644\u0647\u062f\u0649 \u0628\u0639\u062f \u0638\u0647\u0648\u0631 \u0627\u0644\u062d\u062c\u0629 \u0639\u0644\u064a\u0647 \u0641\u0639\u0644\u0649 \u0646\u0641\u0633\u0647 \u062c\u0646\u0649\u060c \u0648\u0645\u0627 \u0623\u0646\u0627 \u0639\u0644\u064a\u0643\u0645 \u0628\u062d\u0627\u0641\u0638 \u0623\u062d\u0635\u064a \u0623\u0639\u0645\u0627\u0644\u0643\u0645\u060c \u0648\u0625\u0646\u0645\u0627 \u0623\u0646\u0627 \u0645\u0628\u0644\u063a\u060c \u0648\u0627\u0644\u0644\u0647 \u064a\u0647\u062f\u064a \u0645\u064e\u0646 \u064a\u0634\u0627\u0621 \u0648\u064a\u0636\u0644 \u0645\u064e\u0646 \u064a\u0634\u0627\u0621 \u0648\u064e\u0641\u0652\u0642 \u0639\u0644\u0645\u0647 \u0648\u062d\u0643\u0645\u062a\u0647.","6:105":"\u0648\u0643\u0645\u0627 \u0628\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0622\u0646 \u0644\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0627\u0644\u0628\u0631\u0627\u0647\u064a\u0646 \u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0641\u064a \u0623\u0645\u0631 \u0627\u0644\u062a\u0648\u062d\u064a\u062f \u0648\u0627\u0644\u0646\u0628\u0648\u0629 \u0648\u0627\u0644\u0645\u0639\u0627\u062f \u0646\u0628\u064a\u0651\u0650\u0646 \u0644\u0647\u0645 \u0627\u0644\u0628\u0631\u0627\u0647\u064a\u0646 \u0641\u064a \u0643\u0644 \u0645\u0627 \u062c\u0647\u0644\u0648\u0647 \u0641\u064a\u0642\u0648\u0644\u0648\u0646 \u0639\u0646\u062f \u0630\u0644\u0643 \u0643\u0630\u0628\u064b\u0627: \u062a\u0639\u0644\u0645\u062a \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628\u060c \u0648\u0644\u0646\u0628\u064a\u0646 -\u0628\u062a\u0635\u0631\u064a\u0641\u0646\u0627 \u0627\u0644\u0622\u064a\u0627\u062a- \u0627\u0644\u062d\u0642\u0651\u064e \u0644\u0642\u0648\u0645 \u064a\u0639\u0644\u0645\u0648\u0646\u0647\u060c \u0641\u064a\u0642\u0628\u0644\u0648\u0646\u0647 \u0648\u064a\u062a\u0628\u0639\u0648\u0646\u0647\u060c \u0648\u0647\u0645 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0628\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0645\u0627 \u0623\u0646\u0632\u0644 \u0639\u0644\u064a\u0647.","6:106":"\u0627\u062a\u0628\u0639 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u0627 \u0623\u0648\u062d\u064a\u0646\u0627\u0647 \u0625\u0644\u064a\u0643 \u0645\u0646 \u0627\u0644\u0623\u0648\u0627\u0645\u0631 \u0648\u0627\u0644\u0646\u0648\u0627\u0647\u064a \u0627\u0644\u062a\u064a \u0623\u0639\u0638\u0645\u064f\u0647\u0627 \u062a\u0648\u062d\u064a\u062f \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u0627\u0644\u062f\u0639\u0648\u0629 \u0625\u0644\u064a\u0647\u060c \u0648\u0644\u0627 \u062a\u064f\u0628\u0627\u0644 \u0628\u0639\u0646\u0627\u062f \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646\u060c \u0648\u0627\u062f\u0639\u0627\u0626\u0647\u0645 \u0627\u0644\u0628\u0627\u0637\u0644.","6:107":"\u0648\u0644\u0648 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0623\u0646 \u0644\u0627 \u064a\u0634\u0631\u0643 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0644\u0645\u0627 \u0623\u0634\u0631\u0643\u0648\u0627\u060c \u0644\u0643\u0646\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u064a\u0645 \u0628\u0645\u0627 \u0633\u064a\u0643\u0648\u0646 \u0645\u0646 \u0633\u0648\u0621 \u0627\u062e\u062a\u064a\u0627\u0631\u0647\u0645 \u0648\u0627\u062a\u0628\u0627\u0639\u0647\u0645 \u0623\u0647\u0648\u0627\u0621\u0647\u0645 \u0627\u0644\u0645\u0646\u062d\u0631\u0641\u0629. \u0648\u0645\u0627 \u062c\u0639\u0644\u0646\u0627\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0639\u0644\u064a\u0647\u0645 \u0631\u0642\u064a\u0628\u064b\u0627 \u062a\u062d\u0641\u0638 \u0639\u0644\u064a\u0647\u0645 \u0623\u0639\u0645\u0627\u0644\u0647\u0645\u060c \u0648\u0645\u0627 \u0623\u0646\u062a \u0628\u0642\u064e\u064a\u0651\u0650\u0645\u064d \u0639\u0644\u064a\u0647\u0645 \u062a\u062f\u0628\u0631 \u0645\u0635\u0627\u0644\u062d\u0647\u0645.","6:108":"\u0648\u0644\u0627 \u062a\u0633\u0628\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646- \u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u0627\u0644\u062a\u064a \u064a\u0639\u0628\u062f\u0647\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 -\u0633\u062f\u0651\u064b\u0627 \u0644\u0644\u0630\u0631\u064a\u0639\u0629- \u062d\u062a\u0649 \u0644\u0627 \u064a\u062a\u0633\u0628\u0628 \u0630\u0644\u0643 \u0641\u064a \u0633\u0628\u0647\u0645 \u0627\u0644\u0644\u0647 \u062c\u0647\u0644\u0627 \u0648\u0627\u0639\u062a\u062f\u0627\u0621\u064b: \u0628\u063a\u064a\u0631 \u0639\u0644\u0645. \u0648\u0643\u0645\u0627 \u062d\u0633\u0651\u064e\u0646\u0651\u064e\u0627 \u0644\u0647\u0624\u0644\u0627\u0621 \u0639\u0645\u0644\u0647\u0645 \u0627\u0644\u0633\u064a\u0626 \u0639\u0642\u0648\u0628\u0629 \u0644\u0647\u0645 \u0639\u0644\u0649 \u0633\u0648\u0621 \u0627\u062e\u062a\u064a\u0627\u0631\u0647\u0645\u060c \u062d\u0633\u0651\u064e\u0646\u0651\u064e\u0627 \u0644\u0643\u0644 \u0623\u0645\u0629 \u0623\u0639\u0645\u0627\u0644\u0647\u0627\u060c \u062b\u0645 \u0625\u0644\u0649 \u0631\u0628\u0647\u0645 \u0645\u0639\u0627\u062f\u0647\u0645 \u062c\u0645\u064a\u0639\u064b\u0627 \u0641\u064a\u062e\u0628\u0631\u0647\u0645 \u0628\u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u0648\u0627 \u064a\u0639\u0645\u0644\u0648\u0646\u0647\u0627 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u062b\u0645 \u064a\u062c\u0627\u0632\u064a\u0647\u0645 \u0628\u0647\u0627.","6:109":"\u0648\u0623\u0642\u0633\u0645 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0628\u0623\u064a\u0645\u0627\u0646 \u0645\u0624\u0643\u0651\u064e\u062f\u0629: \u0644\u0626\u0646 \u062c\u0627\u0621\u0646\u0627 \u0645\u062d\u0645\u062f \u0628\u0639\u0644\u0627\u0645\u0629 \u062e\u0627\u0631\u0642\u0629 \u0644\u0646\u0635\u062f\u0642\u0646\u0651\u064e \u0628\u0645\u0627 \u062c\u0627\u0621 \u0628\u0647\u060c \u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0625\u0646\u0645\u0627 \u0645\u062c\u064a\u0621 \u0627\u0644\u0645\u0639\u062c\u0632\u0627\u062a \u0627\u0644\u062e\u0627\u0631\u0642\u0629 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0647\u0648 \u0627\u0644\u0642\u0627\u062f\u0631 \u0639\u0644\u0649 \u0627\u0644\u0645\u062c\u064a\u0621 \u0628\u0647\u0627 \u0625\u0630\u0627 \u0634\u0627\u0621\u060c \u0648\u0645\u0627 \u064a\u062f\u0631\u064a\u0643\u0645 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646: \u0644\u0639\u0644 \u0647\u0630\u0647 \u0627\u0644\u0645\u0639\u062c\u0632\u0627\u062a \u0625\u0630\u0627 \u062c\u0627\u0621\u062a \u0644\u0627 \u064a\u0635\u062f\u0651\u0650\u0642 \u0628\u0647\u0627 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646.","6:110":"\u0648\u0646\u0642\u0644\u0628 \u0623\u0641\u0626\u062f\u062a\u0647\u0645 \u0648\u0623\u0628\u0635\u0627\u0631\u0647\u0645\u060c \u0641\u0646\u062d\u0648\u0644 \u0628\u064a\u0646\u0647\u0627 \u0648\u0628\u064a\u0646 \u0627\u0644\u0627\u0646\u062a\u0641\u0627\u0639 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647\u060c \u0641\u0644\u0627 \u064a\u0624\u0645\u0646\u0648\u0646 \u0628\u0647\u0627 \u0643\u0645\u0627 \u0644\u0645 \u064a\u0624\u0645\u0646\u0648\u0627 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0642\u0631\u0622\u0646 \u0639\u0646\u062f \u0646\u0632\u0648\u0644\u0647\u0627 \u0623\u0648\u0644 \u0645\u0631\u0629\u060c \u0648\u0646\u062a\u0631\u0643\u0647\u0645 \u0641\u064a \u062a\u0645\u0631\u0651\u064f\u062f\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0645\u062a\u062d\u064a\u0651\u0650\u0631\u064a\u0646\u060c \u0644\u0627 \u064a\u0647\u062a\u062f\u0648\u0646 \u0625\u0644\u0649 \u0627\u0644\u062d\u0642 \u0648\u0627\u0644\u0635\u0648\u0627\u0628.","6:111":"\u0648\u0644\u0648 \u0623\u0646\u0646\u0627 \u0623\u062c\u0628\u0646\u0627 \u0637\u0644\u0628 \u0647\u0624\u0644\u0627\u0621\u060c \u0641\u0646\u0632\u0651\u064e\u0644\u0646\u0627 \u0625\u0644\u064a\u0647\u0645 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0645\u0646 \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u0648\u0623\u062d\u064a\u064a\u0646\u0627 \u0644\u0647\u0645 \u0627\u0644\u0645\u0648\u062a\u0649\u060c \u0641\u0643\u0644\u0645\u0648\u0647\u0645\u060c \u0648\u062c\u0645\u0639\u0646\u0627 \u0644\u0647\u0645 \u0643\u0644 \u0634\u064a\u0621 \u0637\u0644\u0628\u0648\u0647 \u0641\u0639\u0627\u064a\u0646\u0648\u0647 \u0645\u0648\u0627\u062c\u0647\u0629\u060c \u0644\u0645 \u064a\u0635\u062f\u0651\u0650\u0642\u0648\u0627 \u0628\u0645\u0627 \u062f\u0639\u0648\u062a\u0647\u0645 \u0625\u0644\u064a\u0647 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0648\u0644\u0645 \u064a\u0639\u0645\u0644\u0648\u0627 \u0628\u0647\u060c \u0625\u0644\u0627 \u0645\u0646 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u0644\u0647 \u0627\u0644\u0647\u062f\u0627\u064a\u0629\u060c \u0648\u0644\u0643\u0646 \u0623\u0643\u062b\u0631 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0641\u0627\u0631 \u064a\u062c\u0647\u0644\u0648\u0646 \u0627\u0644\u062d\u0642 \u0627\u0644\u0630\u064a \u062c\u0626\u062a \u0628\u0647 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649.","6:112":"\u0648\u0643\u0645\u0627 \u0627\u0628\u062a\u0644\u064a\u0646\u0627\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0628\u0623\u0639\u062f\u0627\u0626\u0643 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0627\u0628\u062a\u0644\u064a\u0646\u0627 \u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 -\u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0633\u0644\u0627\u0645- \u0628\u0623\u0639\u062f\u0627\u0621 \u0645\u0650\u0646 \u0645\u0631\u062f\u0629 \u0642\u0648\u0645\u0647\u0645 \u0648\u0623\u0639\u062f\u0627\u0621 \u0645\u0646 \u0645\u0631\u062f\u0629 \u0627\u0644\u062c\u0646\u060c \u064a\u064f\u0644\u0642\u064a \u0628\u0639\u0636\u0647\u0645 \u0625\u0644\u0649 \u0628\u0639\u0636 \u0627\u0644\u0642\u0648\u0644 \u0627\u0644\u0630\u064a \u0632\u064a\u0651\u064e\u0646\u0648\u0647 \u0628\u0627\u0644\u0628\u0627\u0637\u0644; \u0644\u064a\u063a\u062a\u0631 \u0628\u0647 \u0633\u0627\u0645\u0639\u0647\u060c \u0641\u064a\u0636\u0644 \u0639\u0646 \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647. \u0648\u0644\u0648 \u0623\u0631\u0627\u062f \u0631\u0628\u0643 -\u062c\u0644\u0651\u064e \u0648\u0639\u0644\u0627- \u0644\u062d\u0627\u0644 \u0628\u064a\u0646\u0647\u0645 \u0648\u0628\u064a\u0646 \u062a\u0644\u0643 \u0627\u0644\u0639\u062f\u0627\u0648\u0629\u060c \u0648\u0644\u0643\u0646\u0647 \u0627\u0644\u0627\u0628\u062a\u0644\u0627\u0621 \u0645\u0646 \u0627\u0644\u0644\u0647\u060c \u0641\u062f\u0639\u0647\u0645 \u0648\u0645\u0627 \u064a\u062e\u062a\u0644\u0642\u0648\u0646 \u0645\u0650\u0646 \u0643\u0630\u0628 \u0648\u0632\u0648\u0631.","6:113":"\u0648\u0644\u0650\u062a\u0645\u064a\u0644 \u0625\u0644\u064a\u0647 \u0642\u0644\u0648\u0628 \u0627\u0644\u0643\u0641\u0627\u0631 \u0627\u0644\u0630\u064a\u0646 \u0644\u0627 \u064a\u0635\u062f\u0642\u0648\u0646 \u0628\u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u0622\u062e\u0631\u0629 \u0648\u0644\u0627 \u064a\u0639\u0645\u0644\u0648\u0646 \u0644\u0647\u0627\u060c \u0648\u0644\u062a\u062d\u0628\u0651\u064e\u0647 \u0623\u0646\u0641\u0633\u0647\u0645\u060c \u0648\u0644\u064a\u0643\u062a\u0633\u0628\u0648\u0627 \u0645\u0646 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0633\u064a\u0626\u0629 \u0645\u0627 \u0647\u0645 \u0645\u0643\u062a\u0633\u0628\u0648\u0646. \u0648\u0641\u064a \u0647\u0630\u0627 \u062a\u0647\u062f\u064a\u062f \u0639\u0638\u064a\u0645 \u0644\u0647\u0645.","6:114":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0623\u063a\u064a\u0631 \u0627\u0644\u0644\u0647 \u0625\u0644\u0647\u064a \u0648\u0625\u0644\u0647\u0643\u0645 \u0623\u0637\u0644\u0628 \u062d\u064e\u0643\u064e\u0645\u064b\u0627 \u0628\u064a\u0646\u064a \u0648\u0628\u064a\u0646\u0643\u0645\u060c \u0648\u0647\u0648 \u0633\u0628\u062d\u0627\u0646\u0647 \u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644 \u0625\u0644\u064a\u0643\u0645 \u0627\u0644\u0642\u0631\u0622\u0646 \u0645\u0628\u064a\u0646\u064b\u0627 \u0641\u064a\u0647 \u0627\u0644\u062d\u0643\u0645 \u0641\u064a\u0645\u0627 \u062a\u062e\u062a\u0635\u0645\u0648\u0646 \u0641\u064a\u0647 \u0645\u0646 \u0623\u0645\u0631\u064a \u0648\u0623\u0645\u0631\u0643\u0645\u061f \u0648\u0628\u0646\u0648 \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0627\u0644\u0630\u064a\u0646 \u0622\u062a\u0627\u0647\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644 \u064a\u0639\u0644\u0645\u0648\u0646 \u0639\u0644\u0645\u064b\u0627 \u064a\u0642\u064a\u0646\u064b\u0627 \u0623\u0646 \u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0622\u0646 \u0645\u0646\u0632\u0644 \u0639\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u0646 \u0631\u0628\u0643 \u0628\u0627\u0644\u062d\u0642\u060c \u0641\u0644\u0627 \u062a\u0643\u0648\u0646\u0646 \u0645\u0646 \u0627\u0644\u0634\u0627\u0643\u0651\u0650\u064a\u0646 \u0641\u064a \u0634\u064a\u0621 \u0645\u0645\u0627 \u0623\u0648\u062d\u064a\u0646\u0627 \u0625\u0644\u064a\u0643.","6:115":"\u0648\u062a\u0645\u062a \u0643\u0644\u0645\u0629 \u0631\u0628\u0643 -\u0648\u0647\u064a \u0627\u0644\u0642\u0631\u0622\u0646- \u0635\u062f\u0642\u064b\u0627 \u0641\u064a \u0627\u0644\u0623\u062e\u0628\u0627\u0631 \u0648\u0627\u0644\u0623\u0642\u0648\u0627\u0644\u060c \u0648\u0639\u062f\u0644\u0627 \u0641\u064a \u0627\u0644\u0623\u062d\u0643\u0627\u0645\u060c \u0641\u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639 \u0623\u062d\u062f \u0623\u0646 \u064a\u0628\u062f\u0651\u0650\u0644 \u0643\u0644\u0645\u0627\u062a\u0647 \u0627\u0644\u0643\u0627\u0645\u0644\u0629. \u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0647\u0648 \u0627\u0644\u0633\u0645\u064a\u0639 \u0644\u0645\u0627 \u064a\u0642\u0648\u0644 \u0639\u0628\u0627\u062f\u0647\u060c \u0627\u0644\u062d\u0644\u064a\u0645 \u0628\u0638\u0648\u0627\u0647\u0631 \u0623\u0645\u0648\u0631\u0647\u0645 \u0648\u0628\u0648\u0627\u0637\u0646\u0647\u0627.","6:116":"\u0648\u0644\u0648 \u0641\u064f\u0631\u0636 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0623\u0646\u0643 \u0623\u0637\u0639\u062a \u0623\u0643\u062b\u0631 \u0623\u0647\u0644 \u0627\u0644\u0623\u0631\u0636 \u0644\u0623\u0636\u0644\u0651\u064f\u0648\u0643 \u0639\u0646 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647\u060c \u0645\u0627 \u064a\u0633\u064a\u0631\u0648\u0646 \u0625\u0644\u0627 \u0639\u0644\u0649 \u0645\u0627 \u0638\u0646\u0648\u0647 \u062d\u0642\u0651\u064b\u0627 \u0628\u062a\u0642\u0644\u064a\u062f\u0647\u0645 \u0623\u0633\u0644\u0627\u0641\u0647\u0645\u060c \u0648\u0645\u0627 \u0647\u0645 \u0625\u0644\u0627 \u064a\u0638\u0646\u0648\u0646 \u0648\u064a\u0643\u0630\u0628\u0648\u0646.","6:117":"\u0625\u0646 \u0631\u0628\u0643 \u0647\u0648 \u0623\u0639\u0644\u0645 \u0628\u0627\u0644\u0636\u0627\u0644\u064a\u0646 \u0639\u0646 \u0633\u0628\u064a\u0644 \u0627\u0644\u0631\u0634\u0627\u062f\u060c \u0648\u0647\u0648 \u0623\u0639\u0644\u0645 \u0645\u0646\u0643\u0645 \u0648\u0645\u0646\u0647\u0645 \u0628\u0645\u0646 \u0643\u0627\u0646 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0648\u0633\u062f\u0627\u062f\u060c \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0645\u0646\u0647\u0645 \u0623\u062d\u062f.","6:118":"\u0641\u0643\u0644\u0648\u0627 \u0645\u0646 \u0627\u0644\u0630\u0628\u0627\u0626\u062d \u0627\u0644\u062a\u064a \u0630\u064f\u0643\u0650\u0631\u064e \u0627\u0633\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0627\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u0628\u0628\u0631\u0627\u0647\u064a\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0648\u0627\u0636\u062d\u0629 \u0645\u0635\u062f\u0642\u064a\u0646.","6:119":"\u0648\u0623\u064a\u0651\u064f \u0634\u064a\u0621 \u064a\u0645\u0646\u0639\u0643\u0645 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0645\u0646 \u0623\u0646 \u062a\u0623\u0643\u0644\u0648\u0627 \u0645\u0645\u0627 \u0630\u0643\u0631 \u0627\u0633\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u060c \u0648\u0642\u062f \u0628\u064a\u0651\u064e\u0646 \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0644\u0643\u0645 \u062c\u0645\u064a\u0639 \u0645\u0627 \u062d\u0631\u0651\u064e\u0645 \u0639\u0644\u064a\u0643\u0645\u061f \u0644\u0643\u0646 \u0645\u0627 \u062f\u0639\u062a \u0625\u0644\u064a\u0647 \u0627\u0644\u0636\u0631\u0648\u0631\u0629 \u0628\u0633\u0628\u0628 \u0627\u0644\u0645\u062c\u0627\u0639\u0629\u060c \u0645\u0645\u0627 \u0647\u0648 \u0645\u062d\u0631\u0645 \u0639\u0644\u064a\u0643\u0645 \u0643\u0627\u0644\u0645\u064a\u062a\u0629\u060c \u0641\u0625\u0646\u0647 \u0645\u0628\u0627\u062d \u0644\u0643\u0645. \u0648\u0625\u0646\u0651\u064e \u0643\u062b\u064a\u0631\u064b\u0627 \u0645\u0646 \u0627\u0644\u0636\u0627\u0644\u064a\u0646 \u0644\u064a\u0636\u0644\u0648\u0646 \u0639\u0646 \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0623\u0634\u064a\u0627\u0639\u0647\u0645 \u0641\u064a \u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u062d\u0631\u0627\u0645 \u0648\u062a\u062d\u0631\u064a\u0645 \u0627\u0644\u062d\u0644\u0627\u0644 \u0628\u0623\u0647\u0648\u0627\u0626\u0647\u0645\u061b \u062c\u0647\u0644\u0627 \u0645\u0646\u0647\u0645. \u0625\u0646 \u0631\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0647\u0648 \u0623\u0639\u0644\u0645 \u0628\u0645\u0646 \u062a\u062c\u0627\u0648\u0632 \u062d\u062f\u0647 \u0641\u064a \u0630\u0644\u0643\u060c \u0648\u0647\u0648 \u0627\u0644\u0630\u064a \u064a\u062a\u0648\u0644\u0649 \u062d\u0633\u0627\u0628\u0647 \u0648\u062c\u0632\u0627\u0621\u0647.","6:120":"\u0648\u0627\u062a\u0631\u0643\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633- \u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u0639\u0627\u0635\u064a\u060c \u0645\u0627 \u0643\u0627\u0646 \u0645\u0646\u0647\u0627 \u0639\u0644\u0627\u0646\u064a\u0629 \u0648\u0645\u0627 \u0643\u0627\u0646 \u0633\u0631\u0651\u064b\u0627. \u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u0641\u0639\u0644\u0648\u0646 \u0627\u0644\u0645\u0639\u0627\u0635\u064a \u0633\u064a\u0639\u0627\u0642\u0628\u0647\u0645 \u0631\u0628\u0647\u0645; \u0628\u0633\u0628\u0628 \u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u064a\u0639\u0645\u0644\u0648\u0646\u0647 \u0645\u0646 \u0627\u0644\u0633\u064a\u0626\u0627\u062a.","6:121":"\u0648\u0644\u0627 \u062a\u0623\u0643\u0644\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646- \u0645\u0646 \u0627\u0644\u0630\u0628\u0627\u0626\u062d \u0627\u0644\u062a\u064a \u0644\u0645 \u064a\u0630\u0643\u0631 \u0627\u0633\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0627 \u0639\u0646\u062f \u0627\u0644\u0630\u0628\u062d\u060c \u0643\u0627\u0644\u0645\u064a\u062a\u0629 \u0648\u0645\u0627 \u0630\u0628\u062d \u0644\u0644\u0623\u0648\u062b\u0627\u0646 \u0648\u0627\u0644\u062c\u0646\u060c \u0648\u063a\u064a\u0631 \u0630\u0644\u0643\u060c \u0648\u0625\u0646 \u0627\u0644\u0623\u0643\u0644 \u0645\u0646 \u062a\u0644\u0643 \u0627\u0644\u0630\u0628\u0627\u0626\u062d \u0644\u062e\u0631\u0648\u062c \u0639\u0646 \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649. \u0648\u0625\u0646 \u0645\u0631\u062f\u0629 \u0627\u0644\u062c\u0646 \u0644\u064e\u064a\u064f\u0644\u0652\u0642\u0648\u0646 \u0625\u0644\u0649 \u0623\u0648\u0644\u064a\u0627\u0626\u0647\u0645 \u0645\u0646 \u0634\u064a\u0627\u0637\u064a\u0646 \u0627\u0644\u0625\u0646\u0633 \u0628\u0627\u0644\u0634\u0628\u0647\u0627\u062a \u062d\u0648\u0644 \u062a\u062d\u0631\u064a\u0645 \u0623\u0643\u0644 \u0627\u0644\u0645\u064a\u062a\u0629\u060c \u0641\u064a\u0623\u0645\u0631\u0648\u0646\u0647\u0645 \u0623\u0646 \u064a\u0642\u0648\u0644\u0648\u0627 \u0644\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0641\u064a \u062c\u062f\u0627\u0644\u0647\u0645 \u0645\u0639\u0647\u0645: \u0625\u0646\u0643\u0645 \u0628\u0639\u062f\u0645 \u0623\u0643\u0644\u0643\u0645 \u0627\u0644\u0645\u064a\u062a\u0629 \u0644\u0627 \u062a\u0623\u0643\u0644\u0648\u0646 \u0645\u0627 \u0642\u062a\u0644\u0647 \u0627\u0644\u0644\u0647\u060c \u0628\u064a\u0646\u0645\u0627 \u062a\u0623\u0643\u0644\u0648\u0646 \u0645\u0645\u0627 \u062a\u0630\u0628\u062d\u0648\u0646\u0647\u060c \u0648\u0625\u0646 \u0623\u0637\u0639\u062a\u0645\u0648\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0641\u064a \u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0645\u064a\u062a\u0629- \u0641\u0623\u0646\u062a\u0645 \u0648\u0647\u0645 \u0641\u064a \u0627\u0644\u0634\u0631\u0643 \u0633\u0648\u0627\u0621.","6:122":"\u0623\u0648\u064e \u0645\u0646 \u0643\u0627\u0646 \u0645\u064a\u062a\u064b\u0627 \u0641\u064a \u0627\u0644\u0636\u0644\u0627\u0644\u0629 \u0647\u0627\u0644\u0643\u0627 \u062d\u0627\u0626\u0631\u0627\u060c \u0641\u0623\u062d\u064a\u064a\u0646\u0627 \u0642\u0644\u0628\u0647 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646\u060c \u0648\u0647\u062f\u064a\u0646\u0627\u0647 \u0644\u0647\u060c \u0648\u0648\u0641\u0642\u0646\u0627\u0647 \u0644\u0627\u062a\u0628\u0627\u0639 \u0631\u0633\u0644\u0647\u060c \u0641\u0623\u0635\u0628\u062d \u064a\u0639\u064a\u0634 \u0641\u064a \u0623\u0646\u0648\u0627\u0631 \u0627\u0644\u0647\u062f\u0627\u064a\u0629\u060c \u0643\u0645\u0646 \u0645\u062b\u0644\u0647 \u0641\u064a \u0627\u0644\u062c\u0647\u0627\u0644\u0627\u062a \u0648\u0627\u0644\u0623\u0647\u0648\u0627\u0621 \u0648\u0627\u0644\u0636\u0644\u0627\u0644\u0627\u062a \u0627\u0644\u0645\u062a\u0641\u0631\u0642\u0629\u060c \u0644\u0627 \u064a\u0647\u062a\u062f\u064a \u0625\u0644\u0649 \u0645\u0646\u0641\u0630 \u0648\u0644\u0627 \u0645\u062e\u0644\u0635 \u0644\u0647 \u0645\u0645\u0627 \u0647\u0648 \u0641\u064a\u0647\u061f \u0644\u0627 \u064a\u0633\u062a\u0648\u064a\u0627\u0646\u060c \u0648\u0643\u0645\u0627 \u062e\u0630\u0644\u062a\u064f \u0647\u0630\u0627 \u0627\u0644\u0643\u0627\u0641\u0631 \u0627\u0644\u0630\u064a \u064a\u062c\u0627\u062f\u0644\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0641\u0632\u064a\u0651\u064e\u0646\u0652\u062a\u064f \u0644\u0647 \u0633\u0648\u0621 \u0639\u0645\u0644\u0647\u060c \u0641\u0631\u0622\u0647 \u062d\u0633\u0646\u064b\u0627\u060c \u0632\u064a\u0651\u064e\u0646\u0652\u062a\u064f \u0644\u0644\u062c\u0627\u062d\u062f\u064a\u0646 \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0627\u0644\u0633\u064a\u0626\u0629; \u0644\u064a\u0633\u062a\u0648\u062c\u0628\u0648\u0627 \u0628\u0630\u0644\u0643 \u0627\u0644\u0639\u0630\u0627\u0628.","6:123":"\u0648\u0645\u062b\u0644 \u0647\u0630\u0627 \u0627\u0644\u0630\u064a \u062d\u0635\u0644 \u0645\u0650\u0646 \u0632\u0639\u0645\u0627\u0621 \u0627\u0644\u0643\u0641\u0627\u0631 \u0641\u064a \xab\u0645\u0643\u0629\xbb \u0645\u0646 \u0627\u0644\u0635\u062f\u0651\u0650 \u0639\u0646 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u062c\u0639\u0644\u0646\u0627 \u0641\u064a \u0643\u0644 \u0642\u0631\u064a\u0629 \u0645\u062c\u0631\u0645\u064a\u0646 \u064a\u062a\u0632\u0639\u0645\u0647\u0645 \u0623\u0643\u0627\u0628\u0631\u0647\u0645; \u0644\u064a\u0645\u0643\u0631\u0648\u0627 \u0641\u064a\u0647\u0627 \u0628\u0627\u0644\u0635\u062f \u0639\u0646 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0645\u0627 \u064a\u0643\u064a\u062f\u0648\u0646 \u0625\u0644\u0627 \u0623\u0646\u0641\u0633\u0647\u0645\u060c \u0648\u0645\u0627 \u064a\u064f\u062d\u0650\u0633\u0651\u064f\u0648\u0646 \u0628\u0630\u0644\u0643.","6:124":"\u0648\u0625\u0630\u0627 \u062c\u0627\u0621\u062a \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0645\u0646 \u0623\u0647\u0644 \xab\u0645\u0643\u0629\xbb \u062d\u062c\u0629 \u0638\u0627\u0647\u0631\u0629 \u0639\u0644\u0649 \u0646\u0628\u0648\u0629 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0642\u0627\u0644 \u0628\u0639\u0636 \u0643\u0628\u0631\u0627\u0626\u0647\u0645: \u0644\u0646 \u0646\u0635\u062f\u0651\u0650\u0642 \u0628\u0646\u0628\u0648\u062a\u0647 \u062d\u062a\u0649 \u064a\u0639\u0637\u064a\u0646\u0627 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0646\u0628\u0648\u0629 \u0648\u0627\u0644\u0645\u0639\u062c\u0632\u0627\u062a \u0645\u062b\u0644 \u0645\u0627 \u0623\u0639\u0637\u0649 \u0631\u0633\u0644\u0647 \u0627\u0644\u0633\u0627\u0628\u0642\u064a\u0646. \u0641\u0631\u062f\u0651\u064e \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u064a\u0647\u0645 \u0628\u0642\u0648\u0644\u0647: \u0627\u0644\u0644\u0647 \u0623\u0639\u0644\u0645 \u062d\u064a\u062b \u064a\u062c\u0639\u0644 \u0631\u0633\u0627\u0644\u062a\u0647 \u0623\u064a: \u0628\u0627\u0644\u0630\u064a\u0646 \u0647\u0645 \u0623\u0647\u0644 \u0644\u062d\u0645\u0644 \u0631\u0633\u0627\u0644\u062a\u0647 \u0648\u062a\u0628\u0644\u064a\u063a\u0647\u0627 \u0625\u0644\u0649 \u0627\u0644\u0646\u0627\u0633. \u0633\u064a\u0646\u0627\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0637\u063a\u0627\u0629 \u0627\u0644\u0630\u0644\u060c \u0648\u0644\u0647\u0645 \u0639\u0630\u0627\u0628 \u0645\u0648\u062c\u0639 \u0641\u064a \u0646\u0627\u0631 \u062c\u0647\u0646\u0645; \u0628\u0633\u0628\u0628 \u0643\u064a\u062f\u0647\u0645 \u0644\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0623\u0647\u0644\u0647.","6:125":"\u0641\u0645\u0646 \u064a\u0634\u0623 \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u0648\u0641\u0642\u0647 \u0644\u0642\u064e\u0628\u0648\u0644 \u0627\u0644\u062d\u0642 \u064a\u0634\u0631\u062d \u0635\u062f\u0631\u0647 \u0644\u0644\u062a\u0648\u062d\u064a\u062f \u0648\u0627\u0644\u0625\u064a\u0645\u0627\u0646\u060c \u0648\u0645\u0646 \u064a\u0634\u0623 \u0623\u0646 \u064a\u0636\u0644\u0647 \u064a\u062c\u0639\u0644 \u0635\u062f\u0631\u0647 \u0641\u064a \u062d\u0627\u0644 \u0634\u062f\u064a\u062f\u0629 \u0645\u0646 \u0627\u0644\u0627\u0646\u0642\u0628\u0627\u0636 \u0639\u0646 \u0642\u064e\u0628\u0648\u0644 \u0627\u0644\u0647\u062f\u0649\u060c \u0643\u062d\u0627\u0644 \u0645\u064e\u0646 \u064a\u0635\u0639\u062f \u0641\u064a \u0637\u0628\u0642\u0627\u062a \u0627\u0644\u062c\u0648 \u0627\u0644\u0639\u0644\u064a\u0627\u060c \u0641\u064a\u0635\u0627\u0628 \u0628\u0636\u064a\u0642 \u0634\u062f\u064a\u062f \u0641\u064a \u0627\u0644\u062a\u0646\u0641\u0633. \u0648\u0643\u0645\u0627 \u064a\u062c\u0639\u0644 \u0627\u0644\u0644\u0647 \u0635\u062f\u0648\u0631 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0634\u062f\u064a\u062f\u0629 \u0627\u0644\u0636\u064a\u0642 \u0648\u0627\u0644\u0627\u0646\u0642\u0628\u0627\u0636\u060c \u0643\u0630\u0644\u0643 \u064a\u062c\u0639\u0644 \u0627\u0644\u0639\u0630\u0627\u0628 \u0639\u0644\u0649 \u0627\u0644\u0630\u064a\u0646 \u0644\u0627 \u064a\u0624\u0645\u0646\u0648\u0646 \u0628\u0647.","6:126":"\u0648\u0647\u0630\u0627 \u0627\u0644\u0630\u064a \u0628\u064a\u0651\u064e\u0646\u0651\u064e\u0627\u0647 \u0644\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0647\u0648 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0645\u0648\u0635\u0644 \u0625\u0644\u0649 \u0631\u0636\u0627 \u0631\u0628\u0643 \u0648\u062c\u0646\u062a\u0647. \u0642\u062f \u0628\u064a\u0646\u0651\u064e\u0627 \u0627\u0644\u0628\u0631\u0627\u0647\u064a\u0646 \u0644\u0645\u0646 \u064a\u062a\u0630\u0643\u0631 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0639\u0642\u0648\u0644 \u0627\u0644\u0631\u0627\u062c\u062d\u0629.","6:127":"\u0644\u0644\u0645\u062a\u0630\u0643\u0631\u064a\u0646 \u0639\u0646\u062f \u0631\u0628\u0647\u0645 \u062c\u0644 \u0648\u0639\u0644\u0627 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u062f\u0627\u0631 \u0627\u0644\u0633\u0644\u0627\u0645\u0629 \u0648\u0627\u0644\u0623\u0645\u0627\u0646 \u0645\u0646 \u0643\u0644 \u0645\u0643\u0631\u0648\u0647 \u0648\u0647\u064a \u0627\u0644\u062c\u0646\u0629\u060c \u0648\u0647\u0648 \u0633\u0628\u062d\u0627\u0646\u0647 \u0646\u0627\u0635\u0631\u0647\u0645 \u0648\u062d\u0627\u0641\u0638\u0647\u0645 \u062c\u0632\u0627\u0621\u064b \u0644\u0647\u0645; \u0628\u0633\u0628\u0628 \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0627\u0644\u0635\u0627\u0644\u062d\u0629.","6:128":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u064a\u0648\u0645 \u064a\u062d\u0634\u0631 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0643\u0641\u0627\u0631 \u0648\u0623\u0648\u0644\u064a\u0627\u0621\u0647\u0645 \u0645\u0646 \u0634\u064a\u0627\u0637\u064a\u0646 \u0627\u0644\u062c\u0646 \u0641\u064a\u0642\u0648\u0644: \u064a\u0627 \u0645\u0639\u0634\u0631 \u0627\u0644\u062c\u0646 \u0642\u062f \u0623\u0636\u0644\u0644\u062a\u0645 \u0643\u062b\u064a\u0631\u064b\u0627 \u0645\u0646 \u0627\u0644\u0625\u0646\u0633\u060c \u0648\u0642\u0627\u0644 \u0623\u0648\u0644\u064a\u0627\u0624\u0647\u0645 \u0645\u0646 \u0643\u0641\u0627\u0631 \u0627\u0644\u0625\u0646\u0633: \u0631\u0628\u0646\u0627 \u0642\u062f \u0627\u0646\u062a\u0641\u0639 \u0628\u0639\u0636\u0646\u0627 \u0645\u0646 \u0628\u0639\u0636\u060c \u0648\u0628\u0644\u063a\u0646\u0627 \u0627\u0644\u0623\u062c\u0644 \u0627\u0644\u0630\u064a \u0623\u062c\u0651\u064e\u0644\u0652\u062a\u064e\u0647 \u0644\u0646\u0627 \u0628\u0627\u0646\u0642\u0636\u0627\u0621 \u062d\u064a\u0627\u062a\u0646\u0627 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0647\u0645: \u0627\u0644\u0646\u0627\u0631 \u0645\u062b\u0648\u0627\u0643\u0645\u060c \u0623\u064a: \u0645\u0643\u0627\u0646 \u0625\u0642\u0627\u0645\u062a\u0643\u0645 \u062e\u0627\u0644\u062f\u064a\u0646 \u0641\u064a\u0647\u0627\u060c \u0625\u0644\u0627 \u0645\u064e\u0646 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u0639\u062f\u0645 \u062e\u0644\u0648\u062f\u0647 \u0641\u064a\u0647\u0627 \u0645\u0646 \u0639\u0635\u0627\u0629 \u0627\u0644\u0645\u0648\u062d\u062f\u064a\u0646. \u0625\u0646 \u0631\u0628\u0643 \u062d\u0643\u064a\u0645 \u0641\u064a \u062a\u062f\u0628\u064a\u0631\u0647 \u0648\u0635\u0646\u0639\u0647\u060c \u0639\u0644\u064a\u0645 \u0628\u062c\u0645\u064a\u0639 \u0623\u0645\u0648\u0631 \u0639\u0628\u0627\u062f\u0647.","6:129":"\u0648\u0643\u0645\u0627 \u0633\u0644\u0651\u064e\u0637\u0652\u0646\u0627 \u0634\u064a\u0627\u0637\u064a\u0646 \u0627\u0644\u062c\u0646 \u0639\u0644\u0649 \u0643\u0641\u0627\u0631 \u0627\u0644\u0625\u0646\u0633\u060c \u0641\u0643\u0627\u0646\u0648\u0627 \u0623\u0648\u0644\u064a\u0627\u0621 \u0644\u0647\u0645\u060c \u0646\u0633\u0644\u0651\u0650\u0637 \u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0645\u0646 \u0627\u0644\u0625\u0646\u0633 \u0628\u0639\u0636\u0647\u0645 \u0639\u0644\u0649 \u0628\u0639\u0636 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627; \u0628\u0633\u0628\u0628 \u0645\u0627 \u064a\u0639\u0645\u0644\u0648\u0646\u0647 \u0645\u0646 \u0627\u0644\u0645\u0639\u0627\u0635\u064a.","6:130":"\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0645\u0646 \u0627\u0644\u062c\u0646 \u0648\u0627\u0644\u0625\u0646\u0633\u060c \u0623\u0644\u0645 \u064a\u0623\u062a\u0643\u0645 \u0631\u0633\u0644 \u0645\u0646 \u062c\u0645\u0644\u062a\u0643\u0645 -\u0648\u0638\u0627\u0647\u0631 \u0627\u0644\u0646\u0635\u0648\u0635 \u064a\u062f\u0644\u0651\u064f \u0639\u0644\u0649 \u0623\u0646\u0651\u064e \u0627\u0644\u0631\u0633\u0644 \u0645\u0646 \u0627\u0644\u0625\u0646\u0633 \u0641\u0642\u0637-\u060c \u064a\u062e\u0628\u0631\u0648\u0646\u0643\u0645 \u0628\u0622\u064a\u0627\u062a\u064a \u0627\u0644\u0648\u0627\u0636\u062d\u0629 \u0627\u0644\u0645\u0634\u062a\u0645\u0644\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0645\u0631 \u0648\u0627\u0644\u0646\u0647\u064a \u0648\u0628\u064a\u0627\u0646 \u0627\u0644\u062e\u064a\u0631 \u0648\u0627\u0644\u0634\u0631\u060c \u0648\u064a\u062d\u0630\u0631\u0648\u0646\u0643\u0645 \u0644\u0642\u0627\u0621 \u0639\u0630\u0627\u0628\u064a \u0641\u064a \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u061f \u0642\u0627\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0645\u0646 \u0627\u0644\u0625\u0646\u0633 \u0648\u0627\u0644\u062c\u0646: \u0634\u064e\u0647\u0650\u062f\u0652\u0646\u0627 \u0639\u0644\u0649 \u0623\u0646\u0641\u0633\u0646\u0627 \u0628\u0623\u0646 \u0631\u0633\u0644\u0643 \u0642\u062f \u0628\u0644\u063a\u0648\u0646\u0627 \u0622\u064a\u0627\u062a\u0643\u060c \u0648\u0623\u0646\u0630\u0631\u0648\u0646\u0627 \u0644\u0642\u0627\u0621 \u064a\u0648\u0645\u0646\u0627 \u0647\u0630\u0627\u060c \u0641\u0643\u0630\u0628\u0646\u0627\u0647\u0645\u060c \u0648\u062e\u062f\u0639\u062a \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0632\u064a\u0646\u0629\u064f \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0634\u0647\u062f\u0648\u0627 \u0639\u0644\u0649 \u0623\u0646\u0641\u0633\u0647\u0645 \u0623\u0646\u0647\u0645 \u0643\u0627\u0646\u0648\u0627 \u062c\u0627\u062d\u062f\u064a\u0646 \u0648\u062d\u062f\u0627\u0646\u064a\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0645\u0643\u0630\u0628\u064a\u0646 \u0644\u0631\u0633\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0633\u0644\u0627\u0645.","6:131":"\u0625\u0646\u0645\u0627 \u0623\u0639\u0630\u0631\u0646\u0627 \u0625\u0644\u0649 \u0627\u0644\u062b\u0642\u0644\u064a\u0646 \u0628\u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0631\u0633\u0644 \u0648\u0625\u0646\u0632\u0627\u0644 \u0627\u0644\u0643\u062a\u0628\u060c \u0644\u0626\u0644\u0627 \u064a\u0624\u0627\u062e\u064e\u0630\u064e \u0623\u062d\u062f \u0628\u0638\u0644\u0645\u0647\u060c \u0648\u0647\u0648 \u0644\u0645 \u062a\u0628\u0644\u063a\u0647 \u062f\u0639\u0648\u0629\u060c \u0648\u0644\u0643\u0646 \u0623\u0639\u0630\u0631\u0646\u0627 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0645\u060c \u0648\u0645\u0627 \u0639\u0630\u0651\u064e\u0628\u0646\u0627 \u0623\u062d\u062f\u064b\u0627 \u0625\u0644\u0627 \u0628\u0639\u062f \u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0631\u0633\u0644 \u0625\u0644\u064a\u0647\u0645.","6:132":"\u0648\u0644\u0643\u0644 \u0639\u0627\u0645\u0644 \u0641\u064a \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0623\u0648 \u0645\u0639\u0635\u064a\u062a\u0647 \u0645\u0631\u0627\u062a\u0628 \u0645\u0646 \u0639\u0645\u0644\u0647\u060c \u064a\u0628\u0644\u0651\u0650\u063a\u0647 \u0627\u0644\u0644\u0647 \u0625\u064a\u0627\u0647\u0627\u060c \u0648\u064a\u062c\u0627\u0632\u064a\u0647 \u0639\u0644\u064a\u0647\u0627. \u0648\u0645\u0627 \u0631\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0628\u063a\u0627\u0641\u0644 \u0639\u0645\u0627 \u064a\u0639\u0645\u0644 \u0639\u0628\u0627\u062f\u0647.","6:133":"\u0648\u0631\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0627\u0644\u0630\u064a \u0623\u0645\u0631 \u0627\u0644\u0646\u0627\u0633 \u0628\u0639\u0628\u0627\u062f\u062a\u0647\u060c \u0647\u0648 \u0627\u0644\u063a\u0646\u064a \u0648\u062d\u062f\u0647\u060c \u0648\u0643\u0644 \u062e\u0644\u0642\u0647 \u0645\u062d\u062a\u0627\u062c\u0648\u0646 \u0625\u0644\u064a\u0647\u060c \u0648\u0647\u0648 \u0633\u0628\u062d\u0627\u0646\u0647 \u0630\u0648 \u0627\u0644\u0631\u062d\u0645\u0629 \u0627\u0644\u0648\u0627\u0633\u0639\u0629\u060c \u0644\u0648 \u0623\u0631\u0627\u062f \u0644\u0623\u0647\u0644\u0643\u0643\u0645\u060c \u0648\u0623\u0648\u062c\u062f \u0642\u0648\u0645\u064b\u0627 \u063a\u064a\u0631\u0643\u0645 \u064a\u062e\u0644\u0641\u0648\u0646\u0643\u0645 \u0645\u0646 \u0628\u0639\u062f \u0641\u0646\u0627\u0626\u0643\u0645\u060c \u0648\u064a\u0639\u0645\u0644\u0648\u0646 \u0628\u0637\u0627\u0639\u062a\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0643\u0645\u0627 \u0623\u0648\u062c\u062f\u0643\u0645 \u0645\u0646 \u0646\u0633\u0644 \u0642\u0648\u0645 \u0622\u062e\u0631\u064a\u0646 \u0643\u0627\u0646\u0648\u0627 \u0642\u0628\u0644\u0643\u0645.","6:134":"\u0625\u0646 \u0627\u0644\u0630\u064a \u064a\u0648\u0639\u062f\u0643\u0645 \u0628\u0647 \u0631\u0628\u0643\u0645 - \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 - \u0645\u0646 \u0627\u0644\u0639\u0642\u0627\u0628 \u0639\u0644\u0649 \u0643\u0641\u0631\u0643\u0645 \u0648\u0627\u0642\u0639 \u0628\u0643\u0645\u060c \u0648\u0644\u0646 \u062a\u064f\u0639\u062c\u0650\u0632\u0648\u0627 \u0631\u0628\u0643\u0645 \u0647\u0631\u0628\u064b\u0627\u060c \u0641\u0647\u0648 \u0642\u0627\u062f\u0631 \u0639\u0644\u0649 \u0625\u0639\u0627\u062f\u062a\u0643\u0645\u060c \u0648\u0625\u0646 \u0635\u0631\u062a\u0645 \u062a\u0631\u0627\u0628\u064b\u0627 \u0648\u0639\u0638\u0627\u0645\u064b\u0627.","6:135":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u064a\u0627 \u0642\u0648\u0645 \u0627\u0639\u0645\u0644\u0648\u0627 \u0639\u0644\u0649 \u0637\u0631\u064a\u0642\u062a\u0643\u0645 \u0641\u0625\u0646\u064a \u0639\u0627\u0645\u0644 \u0639\u0644\u0649 \u0637\u0631\u064a\u0642\u062a\u064a \u0627\u0644\u062a\u064a \u0634\u0631\u0639\u0647\u0627 \u0644\u064a \u0631\u0628\u064a \u062c\u0644 \u0648\u0639\u0644\u0627 \u0641\u0633\u0648\u0641 \u062a\u0639\u0644\u0645\u0648\u0646 -\u0639\u0646\u062f \u062d\u0644\u0648\u0644 \u0627\u0644\u0646\u0642\u0645\u0629 \u0628\u0643\u0645- \u0645\u064e\u0646\u0650 \u0627\u0644\u0630\u064a \u062a\u0643\u0648\u0646 \u0644\u0647 \u0627\u0644\u0639\u0627\u0642\u0628\u0629 \u0627\u0644\u062d\u0633\u0646\u0629\u061f \u0625\u0646\u0647 \u0644\u0627 \u064a\u0641\u0648\u0632 \u0628\u0631\u0636\u0648\u0627\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0627\u0644\u062c\u0646\u0629 \u0645\u064e\u0646 \u062a\u062c\u0627\u0648\u0632 \u062d\u062f\u0647 \u0648\u0638\u0644\u0645\u060c \u0641\u0623\u0634\u0631\u0643 \u0645\u0639 \u0627\u0644\u0644\u0647 \u063a\u064a\u0631\u0647.","6:136":"\u0648\u062c\u0639\u0644 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0644\u0644\u0647 -\u062c\u0644\u0651\u064e \u0648\u0639\u0644\u0627- \u062c\u0632\u0621\u064b\u0627 \u0645\u0645\u0627 \u062e\u0644\u0642 \u0645\u0646 \u0627\u0644\u0632\u0631\u0648\u0639 \u0648\u0627\u0644\u062b\u0645\u0627\u0631 \u0648\u0627\u0644\u0623\u0646\u0639\u0627\u0645 \u064a\u0642\u062f\u0645\u0648\u0646\u0647 \u0644\u0644\u0636\u064a\u0648\u0641 \u0648\u0627\u0644\u0645\u0633\u0627\u0643\u064a\u0646\u060c \u0648\u062c\u0639\u0644\u0648\u0627 \u0642\u0633\u0645\u064b\u0627 \u0622\u062e\u0631 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0644\u0634\u0631\u0643\u0627\u0626\u0647\u0645 \u0645\u0646 \u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u0648\u0627\u0644\u0623\u0646\u0635\u0627\u0628\u060c \u0641\u0645\u0627 \u0643\u0627\u0646 \u0645\u062e\u0635\u0635\u064b\u0627 \u0644\u0634\u0631\u0643\u0627\u0626\u0647\u0645 \u0641\u0625\u0646\u0647 \u064a\u0635\u0644 \u0625\u0644\u064a\u0647\u0627 \u0648\u062d\u062f\u0647\u0627\u060c \u0648\u0644\u0627 \u064a\u0635\u0644 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u0645\u0627 \u0643\u0627\u0646 \u0645\u062e\u0635\u0635\u0627 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0641\u0625\u0646\u0647 \u064a\u0635\u0644 \u0625\u0644\u0649 \u0634\u0631\u0643\u0627\u0626\u0647\u0645. \u0628\u0626\u0633 \u062d\u0643\u0645 \u0627\u0644\u0642\u0648\u0645 \u0648\u0642\u0633\u0645\u062a\u0647\u0645.","6:137":"\u0648\u0643\u0645\u0627 \u0632\u064a\u0651\u064e\u0646 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0644\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0623\u0646 \u064a\u062c\u0639\u0644\u0648\u0627 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0645\u0646 \u0627\u0644\u062d\u0631\u062b \u0648\u0627\u0644\u0623\u0646\u0639\u0627\u0645 \u0646\u0635\u064a\u0628\u064b\u0627\u060c \u0648\u0644\u0634\u0631\u0643\u0627\u0626\u0647\u0645 \u0646\u0635\u064a\u0628\u064b\u0627\u060c \u0632\u064a\u0651\u064e\u0646\u062a \u0627\u0644\u0634\u064a\u0627\u0637\u064a\u0646 \u0644\u0643\u062b\u064a\u0631 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0642\u064e\u062a\u0652\u0644\u064e \u0623\u0648\u0644\u0627\u062f\u0647\u0645 \u062e\u0634\u064a\u0629 \u0627\u0644\u0641\u0642\u0631; \u0644\u064a\u0648\u0642\u0639\u0648\u0627 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0622\u0628\u0627\u0621 \u0641\u064a \u0627\u0644\u0647\u0644\u0627\u0643 \u0628\u0642\u062a\u0644 \u0627\u0644\u0646\u0641\u0633 \u0627\u0644\u062a\u064a \u062d\u0631\u0645 \u0627\u0644\u0644\u0647 \u0642\u062a\u0644\u0647\u0627 \u0625\u0644\u0627 \u0628\u0627\u0644\u062d\u0642\u060c \u0648\u0644\u064a\u062e\u0644\u0637\u0648\u0627 \u0639\u0644\u064a\u0647\u0645 \u062f\u064a\u0646\u0647\u0645 \u0641\u064a\u0644\u062a\u0628\u0633\u060c \u0641\u064a\u0636\u0644\u0648\u0627 \u0648\u064a\u0647\u0644\u0643\u0648\u0627\u060c \u0648\u0644\u0648 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u0623\u0644\u0627 \u064a\u0641\u0639\u0644\u0648\u0627 \u0630\u0644\u0643 \u0645\u0627 \u0641\u0639\u0644\u0648\u0647\u060c \u0648\u0644\u0643\u0646\u0647 \u0642\u062f\u0651\u064e\u0631 \u0630\u0644\u0643 \u0644\u0639\u0644\u0645\u0647 \u0628\u0633\u0648\u0621 \u062d\u0627\u0644\u0647\u0645 \u0648\u0645\u0622\u0644\u0647\u0645\u060c \u0641\u0627\u062a\u0631\u0643\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0648\u0634\u0623\u0646\u0647\u0645 \u0641\u064a\u0645\u0627 \u064a\u0641\u062a\u0631\u0648\u0646 \u0645\u0646 \u0643\u0630\u0628\u060c \u0641\u0633\u064a\u062d\u0643\u0645 \u0627\u0644\u0644\u0647 \u0628\u064a\u0646\u0643 \u0648\u0628\u064a\u0646\u0647\u0645.","6:138":"\u0648\u0642\u0627\u0644 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646: \u0647\u0630\u0647 \u0625\u0628\u0644 \u0648\u0632\u0631\u0639 \u062d\u0631\u0627\u0645\u060c \u0644\u0627 \u064a\u0623\u0643\u0644\u0647\u0627 \u0625\u0644\u0627 \u0645\u064e\u0646 \u064a\u0623\u0630\u0646\u0648\u0646 \u0644\u0647 -\u062d\u0633\u0628 \u0627\u062f\u0639\u0627\u0626\u0647\u0645- \u0645\u0650\u0646 \u0633\u062f\u0646\u0629 \u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u0648\u063a\u064a\u0631\u0647\u0645. \u0648\u0647\u0630\u0647 \u0625\u0628\u0644 \u062d\u064f\u0631\u0651\u0650\u0645\u062a \u0638\u0647\u0648\u0631\u0647\u0627\u060c \u0641\u0644\u0627 \u064a\u062d\u0644 \u0631\u0643\u0648\u0628\u0647\u0627 \u0648\u0627\u0644\u062d\u0645\u0644\u064f \u0639\u0644\u064a\u0647\u0627 \u0628\u062d\u0627\u0644 \u0645\u0646 \u0627\u0644\u0623\u062d\u0648\u0627\u0644. \u0648\u0647\u0630\u0647 \u0625\u0628\u0644 \u0644\u0627 \u064a\u064e\u0630\u0643\u0631\u0648\u0646 \u0627\u0633\u0645 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u064a\u0647\u0627 \u0641\u064a \u0623\u064a \u0634\u0623\u0646 \u0645\u0646 \u0634\u0626\u0648\u0646\u0647\u0627. \u0641\u0639\u0644\u0648\u0627 \u0630\u0644\u0643 \u0643\u0630\u0628\u064b\u0627 \u0645\u0646\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0633\u064a\u062c\u0632\u064a\u0647\u0645 \u0627\u0644\u0644\u0647 \u0628\u0633\u0628\u0628 \u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u064a\u0641\u062a\u0631\u0648\u0646 \u0645\u0646 \u0643\u0630\u0628\u064d \u0639\u0644\u064a\u0647 \u0633\u0628\u062d\u0627\u0646\u0647.","6:139":"\u0648\u0642\u0627\u0644 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646: \u0645\u0627 \u0641\u064a \u0628\u0637\u0648\u0646 \u0627\u0644\u0623\u0646\u0639\u0627\u0645 \u0645\u0646 \u0623\u062c\u0646\u0651\u064e\u0629 \u0645\u0628\u0627\u062d \u0644\u0631\u062c\u0627\u0644\u0646\u0627\u060c \u0648\u0645\u062d\u0631\u0645 \u0639\u0644\u0649 \u0646\u0633\u0627\u0626\u0646\u0627\u060c \u0625\u0630\u0627 \u0648\u0644\u062f \u062d\u064a\u0651\u064b\u0627\u060c \u0648\u064a\u0634\u0631\u0643\u0648\u0646 \u0641\u064a\u0647 \u0625\u0630\u0627 \u0648\u0644\u062f \u0645\u064a\u062a\u064b\u0627. \u0633\u064a\u0639\u0627\u0642\u0628\u0647\u0645 \u0627\u0644\u0644\u0647 \u0625\u0630 \u0634\u0631\u0651\u064e\u0639\u0648\u0627 \u0644\u0623\u0646\u0641\u0633\u0647\u0645 \u0645\u0646 \u0627\u0644\u062a\u062d\u0644\u064a\u0644 \u0648\u0627\u0644\u062a\u062d\u0631\u064a\u0645 \u0645\u0627 \u0644\u0645 \u064a\u0623\u0630\u0646 \u0628\u0647 \u0627\u0644\u0644\u0647. \u0625\u0646\u0647 \u062a\u0639\u0627\u0644\u0649 \u062d\u0643\u064a\u0645 \u0641\u064a \u062a\u062f\u0628\u064a\u0631 \u0623\u0645\u0648\u0631 \u062e\u0644\u0642\u0647\u060c \u0639\u0644\u064a\u0645 \u0628\u0647\u0645.","6:140":"\u0642\u062f \u062e\u0633\u0631 \u0648\u0647\u0644\u0643 \u0627\u0644\u0630\u064a\u0646 \u0642\u062a\u0644\u0648\u0627 \u0623\u0648\u0644\u0627\u062f\u0647\u0645 \u0644\u0636\u0639\u0641 \u0639\u0642\u0648\u0644\u0647\u0645 \u0648\u062c\u0647\u0644\u0647\u0645\u060c \u0648\u062d\u0631\u0645\u0648\u0627 \u0645\u0627 \u0631\u0632\u0642\u0647\u0645 \u0627\u0644\u0644\u0647 \u0643\u0630\u0628\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647. \u0642\u062f \u0628\u064e\u0639\u064f\u062f\u0648\u0627 \u0639\u0646 \u0627\u0644\u062d\u0642\u060c \u0648\u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0647\u062f\u0649 \u0648\u0627\u0644\u0631\u0634\u0627\u062f. \u0641\u0627\u0644\u062a\u062d\u0644\u064a\u0644 \u0648\u0627\u0644\u062a\u062d\u0631\u064a\u0645 \u0645\u0646 \u062e\u0635\u0627\u0626\u0635 \u0627\u0644\u0623\u0644\u0648\u0647\u064a\u0629 \u0641\u064a \u0627\u0644\u062a\u0634\u0631\u064a\u0639\u060c \u0648\u0627\u0644\u062d\u0644\u0627\u0644 \u0645\u0627 \u0623\u062d\u0644\u0647 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0644\u062d\u0631\u0627\u0645 \u0645\u0627 \u062d\u0631\u0651\u064e\u0645\u0647 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u064a\u0633 \u0644\u0623\u062d\u062f \u0645\u0646 \u062e\u064e\u0644\u0652\u0642\u0647 \u0641\u0631\u062f\u064b\u0627 \u0643\u0627\u0646 \u0623\u0648 \u062c\u0645\u0627\u0639\u0629 \u0623\u0646 \u064a\u0634\u0631\u0639 \u0644\u0639\u0628\u0627\u062f\u0647 \u0645\u0627 \u0644\u0645 \u064a\u0623\u0630\u0646 \u0628\u0647 \u0627\u0644\u0644\u0647.","6:141":"\u0648\u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0647\u0648 \u0627\u0644\u0630\u064a \u0623\u0648\u062c\u062f \u0644\u0643\u0645 \u0628\u0633\u0627\u062a\u064a\u0646: \u0645\u0646\u0647\u0627 \u0645\u0627 \u0647\u0648 \u0645\u0631\u0641\u0648\u0639 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u0643\u0627\u0644\u0623\u0639\u0646\u0627\u0628\u060c \u0648\u0645\u0646\u0647\u0627 \u0645\u0627 \u0647\u0648 \u063a\u064a\u0631 \u0645\u0631\u0641\u0648\u0639\u060c \u0648\u0644\u0643\u0646\u0647 \u0642\u0627\u0626\u0645 \u0639\u0644\u0649 \u0633\u0648\u0642\u0647 \u0643\u0627\u0644\u0646\u062e\u0644 \u0648\u0627\u0644\u0632\u0631\u0639\u060c \u0645\u062a\u0646\u0648\u0639\u064b\u0627 \u0637\u0639\u0645\u0647\u060c \u0648\u0627\u0644\u0632\u064a\u062a\u0648\u0646 \u0648\u0627\u0644\u0631\u0645\u0627\u0646 \u0645\u062a\u0634\u0627\u0628\u0647\u064b\u0627 \u0645\u0646\u0638\u0631\u0647\u060c \u0648\u0645\u062e\u062a\u0644\u0641\u064b\u0627 \u062b\u0645\u0631\u0647 \u0648\u0637\u0639\u0645\u0647. \u0643\u0644\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633- \u0645\u0650\u0646 \u062b\u0645\u0631\u0647 \u0625\u0630\u0627 \u0623\u062b\u0645\u0631\u060c \u0648\u0623\u0639\u0637\u0648\u0627 \u0632\u0643\u0627\u062a\u0647 \u0627\u0644\u0645\u0641\u0631\u0648\u0636\u0629 \u0639\u0644\u064a\u0643\u0645 \u064a\u0648\u0645 \u062d\u0635\u0627\u062f\u0647 \u0648\u0642\u0637\u0627\u0641\u0647\u060c \u0648\u0644\u0627 \u062a\u062a\u062c\u0627\u0648\u0632\u0648\u0627 \u062d\u062f\u0648\u062f \u0627\u0644\u0627\u0639\u062a\u062f\u0627\u0644 \u0641\u064a \u0625\u062e\u0631\u0627\u062c \u0627\u0644\u0645\u0627\u0644 \u0648\u0623\u0643\u0644 \u0627\u0644\u0637\u0639\u0627\u0645 \u0648\u063a\u064a\u0631 \u0630\u0644\u0643. \u0625\u0646\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0627 \u064a\u062d\u0628 \u0627\u0644\u0645\u062a\u062c\u0627\u0648\u0632\u064a\u0646 \u062d\u062f\u0648\u062f\u0647 \u0628\u0625\u0646\u0641\u0627\u0642 \u0627\u0644\u0645\u0627\u0644 \u0641\u064a \u063a\u064a\u0631 \u0648\u062c\u0647\u0647.","6:142":"\u0648\u0623\u0648\u062c\u062f \u0645\u0646 \u0627\u0644\u0623\u0646\u0639\u0627\u0645 \u0645\u0627 \u0647\u0648 \u0645\u0647\u064a\u0651\u064e\u0623 \u0644\u0644\u062d\u0645\u0644 \u0639\u0644\u064a\u0647 \u0644\u0643\u0628\u0631\u0647 \u0648\u0627\u0631\u062a\u0641\u0627\u0639\u0647 \u0643\u0627\u0644\u0625\u0628\u0644\u060c \u0648\u0645\u0646\u0647\u0627 \u0645\u0627 \u0647\u0648 \u0645\u0647\u064a\u0651\u064e\u0623 \u0644\u063a\u064a\u0631 \u0627\u0644\u062d\u0645\u0644 \u0644\u0635\u063a\u0631\u0647 \u0648\u0642\u0631\u0628\u0647 \u0645\u0646 \u0627\u0644\u0623\u0631\u0636 \u0643\u0627\u0644\u0628\u0642\u0631 \u0648\u0627\u0644\u063a\u0646\u0645\u060c \u0643\u0644\u0648\u0627 \u0645\u0645\u0627 \u0623\u0628\u0627\u062d\u0647 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0648\u0623\u0639\u0637\u0627\u0643\u0645\u0648\u0647 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0623\u0646\u0639\u0627\u0645\u060c \u0648\u0644\u0627 \u062a\u062d\u0631\u0645\u0648\u0627 \u0645\u0627 \u0623\u062d\u0644\u0651\u064e \u0627\u0644\u0644\u0647 \u0645\u0646\u0647\u0627 \u0627\u062a\u0628\u0627\u0639\u064b\u0627 \u0644\u0637\u0631\u0642 \u0627\u0644\u0634\u064a\u0637\u0627\u0646\u060c \u0643\u0645\u0627 \u0641\u0639\u0644 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646. \u0625\u0646 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0644\u0643\u0645 \u0639\u062f\u0648 \u0638\u0627\u0647\u0631 \u0627\u0644\u0639\u062f\u0627\u0648\u0629.","6:143":"\u0647\u0630\u0647 \u0627\u0644\u0623\u0646\u0639\u0627\u0645 \u0627\u0644\u062a\u064a \u0631\u0632\u0642\u0647\u0627 \u0627\u0644\u0644\u0647 \u0639\u0628\u0627\u062f\u0647 \u0645\u0646 \u0627\u0644\u0625\u0628\u0644 \u0648\u0627\u0644\u0628\u0642\u0631 \u0648\u0627\u0644\u063a\u0646\u0645 \u062b\u0645\u0627\u0646\u064a\u0629 \u0623\u0635\u0646\u0627\u0641: \u0623\u0631\u0628\u0639\u0629 \u0645\u0646\u0647\u0627 \u0645\u0646 \u0627\u0644\u063a\u0646\u0645\u060c \u0648\u0647\u064a \u0627\u0644\u0636\u0623\u0646 \u0630\u0643\u0648\u0631\u064b\u0627 \u0648\u0625\u0646\u0627\u062b\u064b\u0627\u060c \u0648\u0627\u0644\u0645\u0639\u0632 \u0630\u0643\u0648\u0631\u064b\u0627 \u0648\u0625\u0646\u0627\u062b\u064b\u0627. \u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0647\u0644 \u062d\u064e\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u0643\u0631\u064a\u0646 \u0645\u0646 \u0627\u0644\u063a\u0646\u0645\u061f \u0641\u0625\u0646 \u0642\u0627\u0644\u0648\u0627: \u0646\u0639\u0645\u060c \u0641\u0642\u062f \u0643\u0630\u0628\u0648\u0627 \u0641\u064a \u0630\u0644\u0643; \u0644\u0623\u0646\u0647\u0645 \u0644\u0627 \u064a\u062d\u0631\u0645\u0648\u0646 \u0643\u0644 \u0630\u0643\u0631 \u0645\u0646 \u0627\u0644\u0636\u0623\u0646 \u0648\u0627\u0644\u0645\u0639\u0632\u060c \u0648\u0642\u0644 \u0644\u0647\u0645: \u0647\u0644 \u062d\u064e\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u0623\u0646\u062b\u064a\u064a\u0646 \u0645\u0646 \u0627\u0644\u063a\u0646\u0645\u061f \u0641\u0625\u0646 \u0642\u0627\u0644\u0648\u0627: \u0646\u0639\u0645\u060c \u0641\u0642\u062f \u0643\u0630\u0628\u0648\u0627 \u0623\u064a\u0636\u064b\u0627; \u0644\u0623\u0646\u0647\u0645 \u0644\u0627 \u064a\u062d\u0631\u0645\u0648\u0646 \u0643\u0644 \u0623\u0646\u062b\u0649 \u0645\u0646 \u0648\u0644\u062f \u0627\u0644\u0636\u0623\u0646 \u0648\u0627\u0644\u0645\u0639\u0632\u060c \u0648\u0642\u0644 \u0644\u0647\u0645: \u0647\u0644 \u062d\u064e\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647 \u0645\u0627 \u0627\u0634\u062a\u0645\u0644\u062a \u0639\u0644\u064a\u0647 \u0623\u0631\u062d\u0627\u0645 \u0627\u0644\u0623\u0646\u062b\u064a\u064a\u0646 \u0645\u0646 \u0627\u0644\u0636\u0623\u0646 \u0648\u0627\u0644\u0645\u0639\u0632 \u0645\u0646 \u0627\u0644\u062d\u0645\u0644\u061f \u0641\u0625\u0646 \u0642\u0627\u0644\u0648\u0627: \u0646\u0639\u0645\u060c \u0641\u0642\u062f \u0643\u0630\u0628\u0648\u0627 \u0623\u064a\u0636\u064b\u0627; \u0644\u0623\u0646\u0647\u0645 \u0644\u0627 \u064a\u062d\u0631\u0645\u0648\u0646 \u0643\u0644 \u062d\u064e\u0645\u0652\u0644 \u0645\u0650\u0646 \u0630\u0644\u0643\u060c \u062e\u0628\u0651\u0650\u0631\u0648\u0646\u064a \u0628\u0639\u0644\u0645 \u064a\u062f\u0644 \u0639\u0644\u0649 \u0635\u062d\u0629 \u0645\u0627 \u0630\u0647\u0628\u062a\u0645 \u0625\u0644\u064a\u0647\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u0635\u0627\u062f\u0642\u064a\u0646 \u0641\u064a\u0645\u0627 \u062a\u0646\u0633\u0628\u0648\u0646\u0647 \u0625\u0644\u0649 \u0631\u0628\u0643\u0645.","6:144":"\u0648\u0627\u0644\u0623\u0635\u0646\u0627\u0641 \u0627\u0644\u0623\u0631\u0628\u0639\u0629 \u0627\u0644\u0623\u062e\u0631\u0649: \u0647\u064a \u0627\u062b\u0646\u0627\u0646 \u0645\u0646 \u0627\u0644\u0625\u0628\u0644 \u0630\u0643\u0648\u0631\u064b\u0627 \u0648\u0625\u0646\u0627\u062b\u064b\u0627\u060c \u0648\u0627\u062b\u0646\u0627\u0646 \u0645\u0646 \u0627\u0644\u0628\u0642\u0631 \u0630\u0643\u0648\u0631\u064b\u0627 \u0648\u0625\u0646\u0627\u062b\u064b\u0627. \u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0623\u062d\u064e\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u0643\u0631\u064a\u0646 \u0623\u0645 \u0627\u0644\u0623\u0646\u062b\u064a\u064a\u0646\u061f \u0623\u0645 \u062d\u0631\u0651\u064e\u0645 \u0645\u0627 \u0627\u0634\u062a\u0645\u0644\u062a \u0639\u0644\u064a\u0647 \u0623\u0631\u062d\u0627\u0645 \u0627\u0644\u0623\u0646\u062b\u064a\u064a\u0646 \u0630\u0643\u0648\u0631\u064b\u0627 \u0648\u0625\u0646\u0627\u062b\u064b\u0627\u061f \u0623\u0645 \u0643\u0646\u062a\u0645 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u062d\u0627\u0636\u0631\u064a\u0646\u060c \u0625\u0630 \u0648\u0635\u0627\u0643\u0645 \u0627\u0644\u0644\u0647 \u0628\u0647\u0630\u0627 \u0627\u0644\u062a\u062d\u0631\u064a\u0645 \u0644\u0644\u0623\u0646\u0639\u0627\u0645\u060c \u0641\u0644\u0627 \u0623\u062d\u062f \u0623\u0634\u062f \u0638\u0644\u0645\u064b\u0627 \u0645\u0645\u0646 \u0627\u062e\u062a\u0644\u0642 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0627\u0644\u0643\u0630\u0628; \u0644\u064a\u0635\u0631\u0641 \u0627\u0644\u0646\u0627\u0633 \u0628\u062c\u0647\u0644\u0647 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0647\u062f\u0649. \u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0627 \u064a\u0648\u0641\u0642 \u0644\u0644\u0631\u0634\u062f \u0645\u064e\u0646 \u062a\u062c\u0627\u0648\u0632 \u062d\u062f\u0651\u064e\u0647\u060c \u0641\u0643\u0630\u0628 \u0639\u0644\u0649 \u0631\u0628\u0647\u060c \u0648\u0623\u0636\u0644\u0651\u064e \u0627\u0644\u0646\u0627\u0633.","6:145":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0625\u0646\u064a \u0644\u0627 \u0623\u062c\u062f \u0641\u064a\u0645\u0627 \u0623\u0648\u062d\u0649 \u0627\u0644\u0644\u0647 \u0625\u0644\u064a\u0651\u064e \u0634\u064a\u0626\u064b\u0627 \u0645\u062d\u0631\u0645\u064b\u0627 \u0639\u0644\u0649 \u0645\u0646 \u064a\u0623\u0643\u0644\u0647 \u0645\u0645\u0627 \u062a\u0630\u0643\u0631\u0648\u0646 \u0623\u0646\u0647 \u062d\u064f\u0631\u0651\u0650\u0645 \u0645\u0646 \u0627\u0644\u0623\u0646\u0639\u0627\u0645\u060c \u0625\u0644\u0627 \u0623\u0646 \u064a\u0643\u0648\u0646 \u0642\u062f \u0645\u0627\u062a \u0628\u063a\u064a\u0631 \u062a\u0630\u0643\u064a\u0629\u060c \u0623\u0648 \u064a\u0643\u0648\u0646 \u062f\u0645\u064b\u0627 \u0645\u0631\u0627\u0642\u064b\u0627\u060c \u0623\u0648 \u064a\u0643\u0648\u0646 \u0644\u062d\u0645 \u062e\u0646\u0632\u064a\u0631 \u0641\u0625\u0646\u0647 \u0646\u062c\u0633\u060c \u0623\u0648 \u0627\u0644\u0630\u064a \u0643\u0627\u0646\u062a \u0630\u0643\u0627\u062a\u0647 \u062e\u0631\u0648\u062c\u064b\u0627 \u0639\u0646 \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649; \u0643\u0645\u0627 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0627\u0644\u0645\u0630\u0628\u0648\u062d \u0642\u062f \u0630\u0643\u0631 \u0639\u0644\u064a\u0647 \u0627\u0633\u0645 \u063a\u064a\u0631 \u0627\u0644\u0644\u0647 \u0639\u0646\u062f \u0627\u0644\u0630\u0628\u062d. \u0641\u0645\u0646 \u0627\u0636\u0637\u0631 \u0625\u0644\u0649 \u0627\u0644\u0623\u0643\u0644 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0645\u062d\u0631\u0645\u0627\u062a \u0628\u0633\u0628\u0628 \u0627\u0644\u062c\u0648\u0639 \u0627\u0644\u0634\u062f\u064a\u062f \u063a\u064a\u0631 \u0637\u0627\u0644\u0628 \u0628\u0623\u0643\u0644\u0647 \u0645\u0646\u0647\u0627 \u062a\u0644\u0630\u0630\u064b\u0627\u060c \u0648\u0644\u0627 \u0645\u062a\u062c\u0627\u0648\u0632 \u062d\u062f \u0627\u0644\u0636\u0631\u0648\u0631\u0629\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u063a\u0641\u0648\u0631 \u0644\u0647\u060c \u0631\u062d\u064a\u0645 \u0628\u0647. \u0648\u0642\u062f \u062b\u0628\u062a - \u0641\u064a\u0645\u0627 \u0628\u0639\u062f - \u0628\u0627\u0644\u0633\u0646\u0629 \u062a\u062d\u0631\u064a\u0645 \u0643\u0644 \u0630\u064a \u0646\u0627\u0628 \u0645\u0646 \u0627\u0644\u0633\u0628\u0627\u0639\u060c \u0648\u0645\u062e\u0644\u0628 \u0645\u0646 \u0627\u0644\u0637\u064a\u0631\u060c \u0648\u0627\u0644\u062d\u0645\u0631 \u0627\u0644\u0623\u0647\u0644\u064a\u0629\u060c \u0648\u0627\u0644\u0643\u0644\u0627\u0628.","6:146":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0645\u0627 \u062d\u0631\u0645\u0651\u064e\u0646\u0627 \u0639\u0644\u0649 \u0627\u0644\u064a\u0647\u0648\u062f \u0645\u0646 \u0627\u0644\u0628\u0647\u0627\u0626\u0645 \u0648\u0627\u0644\u0637\u064a\u0631: \u0648\u0647\u0648 \u0643\u0644 \u0645\u0627 \u0644\u0645 \u064a\u0643\u0646 \u0645\u0634\u0642\u0648\u0642 \u0627\u0644\u0623\u0635\u0627\u0628\u0639 \u0643\u0627\u0644\u0625\u0628\u0644 \u0648\u0627\u0644\u0646\u0651\u064e\u0639\u0627\u0645\u060c \u0648\u0634\u062d\u0648\u0645 \u0627\u0644\u0628\u0642\u0631 \u0648\u0627\u0644\u063a\u0646\u0645\u060c \u0625\u0644\u0627 \u0645\u0627 \u0639\u064e\u0644\u0650\u0642 \u0645\u0646 \u0627\u0644\u0634\u062d\u0645 \u0628\u0638\u0647\u0648\u0631\u0647\u0627 \u0623\u0648 \u0623\u0645\u0639\u0627\u0626\u0647\u0627\u060c \u0623\u0648 \u0627\u062e\u062a\u0644\u0637 \u0628\u0639\u0638\u0645 \u0627\u0644\u0623\u0644\u0652\u064a\u0629 \u0648\u0627\u0644\u062c\u0646\u0628 \u0648\u0646\u062d\u0648 \u0630\u0644\u0643. \u0630\u0644\u0643 \u0627\u0644\u062a\u062d\u0631\u0645 \u0627\u0644\u0645\u0630\u0643\u0648\u0631 \u0639\u0644\u0649 \u0627\u0644\u064a\u0647\u0648\u062f \u0639\u0642\u0648\u0628\u0629 \u0645\u0650\u0646\u0651\u064e\u0627 \u0644\u0647\u0645 \u0628\u0633\u0628\u0628 \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0627\u0644\u0633\u064a\u0626\u0629\u060c \u0648\u0625\u0646\u0651\u064e\u0627 \u0644\u0635\u0627\u062f\u0642\u0648\u0646 \u0641\u064a\u0645\u0627 \u0623\u062e\u0628\u0631\u0646\u0627 \u0628\u0647 \u0639\u0646\u0647\u0645.","6:147":"\u0641\u0625\u0646 \u0643\u0630\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u062e\u0627\u0644\u0641\u0648\u0643 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u064a\u0647\u0648\u062f\u060c \u0648\u063a\u064a\u0631\u0647\u0645\u060c \u0641\u0642\u0644 \u0644\u0647\u0645: \u0631\u0628\u0643\u0645 \u062c\u0644 \u0648\u0639\u0644\u0627 \u0630\u0648 \u0631\u062d\u0645\u0629 \u0648\u0627\u0633\u0639\u0629\u060c \u0648\u0644\u0627 \u064a\u064f\u062f\u0652\u0641\u0639 \u0639\u0642\u0627\u0628\u0647 \u0639\u0646 \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u0630\u064a\u0646 \u0623\u062c\u0631\u0645\u0648\u0627\u060c \u0641\u0627\u0643\u062a\u0633\u0628\u0648\u0627 \u0627\u0644\u0630\u0646\u0648\u0628\u060c \u0648\u0627\u062c\u062a\u0631\u062d\u0648\u0627 \u0627\u0644\u0633\u064a\u0626\u0627\u062a. \u0648\u0641\u064a \u0647\u0630\u0627 \u062a\u0647\u062f\u064a\u062f \u0644\u0647\u0645 \u0644\u0645\u062e\u0627\u0644\u0641\u062a\u0647\u0645 \u0627\u0644\u0631\u0633\u0648\u0644 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645.","6:148":"\u0633\u064a\u0642\u0648\u0644 \u0627\u0644\u0630\u064a\u0646 \u0623\u0634\u0631\u0643\u0648\u0627: \u0644\u0648 \u0623\u0631\u0627\u062f \u0627\u0644\u0644\u0647 \u0623\u0646 \u0644\u0627 \u0646\u0634\u0631\u0643 -\u0646\u062d\u0646 \u0648\u0622\u0628\u0627\u0624\u0646\u0627- \u0648\u0623\u0646 \u0644\u0627 \u0646\u062d\u0631\u0645 \u0634\u064a\u0626\u064b\u0627 \u0645\u0650\u0646 \u062f\u0648\u0646\u0647 \u0645\u0627 \u0641\u0639\u0644\u0646\u0627 \u0630\u0644\u0643\u060c \u0648\u0631\u062f\u0651\u064e \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0628\u0628\u064a\u0627\u0646 \u0623\u0646 \u0647\u0630\u0647 \u0627\u0644\u0634\u0628\u0647\u0629 \u0642\u062f \u0623\u062b\u0627\u0631\u0647\u0627 \u0627\u0644\u0643\u0641\u0627\u0631 \u0645\u0650\u0646 \u0642\u0628\u0644\u0647\u0645\u060c \u0648\u0643\u0630\u0651\u064e\u0628\u0648\u0627 \u0628\u0647\u0627 \u062f\u0639\u0648\u0629 \u0631\u0633\u0644\u0647\u0645\u060c \u0648\u0627\u0633\u062a\u0645\u064e\u0631\u0651\u064f\u0648\u0627 \u0639\u0644\u0649 \u0630\u0644\u0643\u060c \u062d\u062a\u0649 \u0646\u0632\u0644 \u0628\u0647\u0645 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647. \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0647\u0644 \u0639\u0646\u062f\u0643\u0645 -\u0641\u064a\u0645\u0627 \u062d\u0631\u0651\u064e\u0645\u062a\u0645 \u0645\u0646 \u0627\u0644\u0623\u0646\u0639\u0627\u0645 \u0648\u0627\u0644\u062d\u0631\u062b\u060c \u0648\u0641\u064a\u0645\u0627 \u0632\u0639\u0645\u062a\u0645 \u0645\u0646 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0642\u062f \u0634\u0627\u0621 \u0644\u0643\u0645 \u0627\u0644\u0643\u0641\u0631\u060c \u0648\u0631\u0636\u064a\u0647 \u0645\u0646\u0643\u0645 \u0648\u0623\u062d\u0628\u0647 \u0644\u0643\u0645- \u0645\u0646 \u0639\u0644\u0645 \u0635\u062d\u064a\u062d \u0641\u062a\u0638\u0647\u0631\u0648\u0647 \u0644\u0646\u0627\u061f \u0625\u0646 \u062a\u062a\u0628\u0639\u0648\u0646 \u0641\u064a \u0623\u0645\u0648\u0631 \u0647\u0630\u0627 \u0627\u0644\u062f\u064a\u0646 \u0625\u0644\u0627 \u0645\u062c\u0631\u062f \u0627\u0644\u0638\u0646\u060c \u0648\u0625\u0646 \u0623\u0646\u062a\u0645 \u0625\u0644\u0627 \u062a\u0643\u0630\u0628\u0648\u0646.","6:149":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0645: \u0641\u0644\u0644\u0647 \u062c\u0644 \u0648\u0639\u0644\u0627 \u0627\u0644\u062d\u062c\u0629 \u0627\u0644\u0642\u0627\u0637\u0639\u0629 \u0627\u0644\u062a\u064a \u064a\u0642\u0637\u0639 \u0628\u0647\u0627 \u0638\u0646\u0648\u0646\u0643\u0645\u060c \u0641\u0644\u0648 \u0634\u0627\u0621 \u0644\u0648\u0641\u0651\u064e\u0642\u0643\u0645 \u062c\u0645\u064a\u0639\u064b\u0627 \u0625\u0644\u0649 \u0637\u0631\u064a\u0642 \u0627\u0644\u0627\u0633\u062a\u0642\u0627\u0645\u0629.","6:150":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0647\u0627\u062a\u0648\u0627 \u0634\u0647\u062f\u0627\u0621\u0643\u0645 \u0627\u0644\u0630\u064a\u0646 \u064a\u0634\u0647\u062f\u0648\u0646 \u0623\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0647\u0648 \u0627\u0644\u0630\u064a \u062d\u0631\u0651\u064e\u0645 \u0645\u0627 \u062d\u0631\u0651\u064e\u0645\u062a\u0645 \u0645\u0646 \u0627\u0644\u062d\u0631\u062b \u0648\u0627\u0644\u0623\u0646\u0639\u0627\u0645\u060c \u0641\u0625\u0646 \u0634\u0647\u062f\u0648\u0627 -\u0643\u0630\u0628\u064b\u0627 \u0648\u0632\u0648\u0631\u064b\u0627- \u0641\u0644\u0627 \u062a\u0635\u062f\u0642\u0647\u0645\u060c \u0648\u0644\u0627 \u062a\u0648\u0627\u0641\u0642 \u0627\u0644\u0630\u064a\u0646 \u062d\u0643\u0651\u064e\u0645\u0648\u0627 \u0623\u0647\u0648\u0627\u0621\u0647\u0645\u060c \u0641\u0643\u0630\u0628\u0648\u0627 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0641\u064a\u0645\u0627 \u0630\u0647\u0628\u0648\u0627 \u0625\u0644\u064a\u0647 \u0645\u0646 \u062a\u062d\u0631\u064a\u0645 \u0645\u0627 \u0623\u062d\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u062a\u062d\u0644\u064a\u0644 \u0645\u0627 \u062d\u0631\u0645 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u062a\u062a\u0628\u0639 \u0627\u0644\u0630\u064a\u0646 \u0644\u0627 \u064a\u0635\u062f\u0642\u0648\u0646 \u0628\u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u0622\u062e\u0631\u0629 \u0648\u0644\u0627 \u064a\u0639\u0645\u0644\u0648\u0646 \u0644\u0647\u0627\u060c \u0648\u0627\u0644\u0630\u064a\u0646 \u0647\u0645 \u0628\u0631\u0628\u0647\u0645 \u064a\u0634\u0631\u0643\u0648\u0646 \u0641\u064a\u0639\u0628\u062f\u0648\u0646 \u0645\u0639\u0647 \u063a\u064a\u0631\u0647.","6:151":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0645: \u062a\u0639\u0627\u0644\u0648\u0627 \u0623\u062a\u0644 \u0645\u0627 \u062d\u0631\u0645 \u0631\u0628\u0643\u0645 \u0639\u0644\u064a\u0643\u0645: \u0623\u0646 \u0644\u0627 \u062a\u0634\u0631\u0643\u0648\u0627 \u0645\u0639\u0647 \u0634\u064a\u0626\u064b\u0627 \u0645\u0646 \u0645\u062e\u0644\u0648\u0642\u0627\u062a\u0647 \u0641\u064a \u0639\u0628\u0627\u062f\u062a\u0647\u060c \u0628\u0644 \u0627\u0635\u0631\u0641\u0648\u0627 \u062c\u0645\u064a\u0639 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0644\u0647 \u0648\u062d\u062f\u0647\u060c \u0643\u0627\u0644\u062e\u0648\u0641 \u0648\u0627\u0644\u0631\u062c\u0627\u0621 \u0648\u0627\u0644\u062f\u0639\u0627\u0621\u060c \u0648\u063a\u064a\u0631 \u0630\u0644\u0643\u060c \u0648\u0623\u0646 \u062a\u062d\u0633\u0646\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0648\u0627\u0644\u062f\u064a\u0646 \u0628\u0627\u0644\u0628\u0631 \u0648\u0627\u0644\u062f\u0639\u0627\u0621 \u0648\u0646\u062d\u0648 \u0630\u0644\u0643 \u0645\u0646 \u0627\u0644\u0625\u062d\u0633\u0627\u0646\u060c \u0648\u0644\u0627 \u062a\u0642\u062a\u0644\u0648\u0627 \u0623\u0648\u0644\u0627\u062f\u0643\u0645 \u0645\u0650\u0646 \u0623\u062c\u0644 \u0641\u0642\u0631 \u0646\u0632\u0644 \u0628\u0643\u0645; \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u0631\u0632\u0642\u0643\u0645 \u0648\u0625\u064a\u0627\u0647\u0645\u060c \u0648\u0644\u0627 \u062a\u0642\u0631\u0628\u0648\u0627 \u0645\u0627 \u0643\u0627\u0646 \u0638\u0627\u0647\u0631\u064b\u0627 \u0645\u0646 \u0643\u0628\u064a\u0631 \u0627\u0644\u0622\u062b\u0627\u0645\u060c \u0648\u0645\u0627 \u0643\u0627\u0646 \u062e\u0641\u064a\u0651\u064b\u0627\u060c \u0648\u0644\u0627 \u062a\u0642\u062a\u0644\u0648\u0627 \u0627\u0644\u0646\u0641\u0633 \u0627\u0644\u062a\u064a \u062d\u0631\u0645 \u0627\u0644\u0644\u0647 \u0642\u062a\u0644\u0647\u0627 \u0625\u0644\u0627 \u0628\u0627\u0644\u062d\u0642\u060c \u0648\u0630\u0644\u0643 \u0641\u064a \u062d\u0627\u0644 \u0627\u0644\u0642\u0635\u0627\u0635 \u0645\u0646 \u0627\u0644\u0642\u0627\u062a\u0644 \u0623\u0648 \u0627\u0644\u0632\u0646\u0649 \u0628\u0639\u062f \u0627\u0644\u0625\u062d\u0635\u0627\u0646 \u0623\u0648 \u0627\u0644\u0631\u062f\u0629 \u0639\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0630\u0644\u0643\u0645 \u0627\u0644\u0645\u0630\u0643\u0648\u0631 \u0645\u0645\u0627 \u0646\u0647\u0627\u0643\u0645 \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u060c \u0648\u0639\u0647\u062f \u0625\u0644\u064a\u0643\u0645 \u0628\u0627\u062c\u062a\u0646\u0627\u0628\u0647\u060c \u0648\u0645\u0645\u0627 \u0623\u0645\u0631\u0643\u0645 \u0628\u0647\u060c \u0648\u0635\u0651\u064e\u0627\u0643\u0645 \u0628\u0647 \u0631\u0628\u0643\u0645; \u0644\u0639\u0644\u0643\u0645 \u062a\u0639\u0642\u0644\u0648\u0646 \u0623\u0648\u0627\u0645\u0631\u0647 \u0648\u0646\u0648\u0627\u0647\u064a\u0647.","6:152":"\u0648\u0644\u0627 \u062a\u0642\u0631\u0628\u0648\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0623\u0648\u0635\u064a\u0627\u0621 \u0645\u0627\u0644 \u0645\u0646 \u0645\u0627\u062a \u0623\u0628\u0648\u0647 \u0648\u0647\u0648 \u0635\u063a\u064a\u0631 \u0625\u0644\u0627 \u0628\u0627\u0644\u062d\u0627\u0644 \u0627\u0644\u062a\u064a \u062a\u0635\u0644\u062d \u0628\u0647\u0627 \u0623\u0645\u0648\u0627\u0644\u0647 \u0648\u064a\u064e\u0646\u0652\u062a\u064e\u0641\u0650\u0639 \u0628\u0647\u0627\u060c \u062d\u062a\u0649 \u064a\u0635\u0644 \u0625\u0644\u0649 \u0633\u0646 \u0627\u0644\u0628\u0644\u0648\u063a \u0648\u064a\u0643\u0648\u0646 \u0631\u0627\u0634\u062f\u064b\u0627\u060c \u0641\u0625\u0630\u0627 \u0628\u0644\u063a \u0630\u0644\u0643 \u0641\u0633\u0644\u0645\u0648\u0627 \u0625\u0644\u064a\u0647 \u0645\u0627\u0644\u0647\u060c \u0648\u0623\u0648\u0641\u0648\u0627 \u0627\u0644\u0643\u064a\u0644 \u0648\u0627\u0644\u0648\u0632\u0646 \u0628\u0627\u0644\u0639\u062f\u0644 \u0627\u0644\u0630\u064a \u064a\u0643\u0648\u0646 \u0628\u0647 \u062a\u0645\u0627\u0645 \u0627\u0644\u0648\u0641\u0627\u0621. \u0648\u0625\u0630\u0627 \u0628\u0630\u0644\u062a\u0645 \u062c\u0647\u062f\u0643\u0645 \u0641\u0644\u0627 \u062d\u0631\u062c \u0639\u0644\u064a\u0643\u0645 \u0641\u064a\u0645\u0627 \u0642\u062f \u064a\u0643\u0648\u0646 \u0645\u0646 \u0646\u0642\u0635\u060c \u0644\u0627 \u0646\u0643\u0644\u0641 \u0646\u0641\u0633\u064b\u0627 \u0625\u0644\u0627 \u0648\u0633\u0639\u0647\u0627. \u0648\u0625\u0630\u0627 \u0642\u0644\u062a\u0645 \u0641\u062a\u062d\u0631\u0651\u064e\u0648\u0627 \u0641\u064a \u0642\u0648\u0644\u0643\u0645 \u0627\u0644\u0639\u062f\u0644 \u062f\u0648\u0646 \u0645\u064a\u0644 \u0639\u0646 \u0627\u0644\u062d\u0642 \u0641\u064a \u062e\u0628\u0631 \u0623\u0648 \u0634\u0647\u0627\u062f\u0629 \u0623\u0648 \u062d\u0643\u0645 \u0623\u0648 \u0634\u0641\u0627\u0639\u0629\u060c \u0648\u0644\u0648 \u0643\u0627\u0646 \u0627\u0644\u0630\u064a \u062a\u0639\u0644\u0642 \u0628\u0647 \u0627\u0644\u0642\u0648\u0644 \u0630\u0627 \u0642\u0631\u0627\u0628\u0629 \u0645\u0646\u0643\u0645\u060c \u0641\u0644\u0627 \u062a\u0645\u064a\u0644\u0648\u0627 \u0645\u0639\u0647 \u0628\u063a\u064a\u0631 \u062d\u0642\u060c \u0648\u0623\u0648\u0641\u0648\u0627 \u0628\u0645\u0627 \u0639\u0647\u062f \u0627\u0644\u0644\u0647 \u0628\u0647 \u0625\u0644\u064a\u0643\u0645 \u0645\u0646 \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0634\u0631\u064a\u0639\u062a\u0647. \u0630\u0644\u0643\u0645 \u0627\u0644\u0645\u062a\u0644\u0648\u0651\u064f \u0639\u0644\u064a\u0643\u0645 \u0645\u0646 \u0627\u0644\u0623\u062d\u0643\u0627\u0645\u060c \u0648\u0635\u0651\u064e\u0627\u0643\u0645 \u0628\u0647 \u0631\u0628\u0643\u0645; \u0631\u062c\u0627\u0621 \u0623\u0646 \u062a\u062a\u0630\u0643\u0631\u0648\u0627 \u0639\u0627\u0642\u0628\u0629 \u0623\u0645\u0631\u0643\u0645.","6:153":"\u0648\u0645\u0645\u0627 \u0648\u0635\u0627\u0643\u0645 \u0627\u0644\u0644\u0647 \u0628\u0647 \u0623\u0646 \u0647\u0630\u0627 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0647\u0648 \u0637\u0631\u064a\u0642 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645 \u0641\u0627\u0633\u0644\u0643\u0648\u0647\u060c \u0648\u0644\u0627 \u062a\u0633\u0644\u0643\u0648\u0627 \u0633\u0628\u0644 \u0627\u0644\u0636\u0644\u0627\u0644\u060c \u0641\u062a\u0641\u0631\u0642\u0643\u0645\u060c \u0648\u062a\u0628\u0639\u062f\u0643\u0645 \u0639\u0646 \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645. \u0630\u0644\u0643\u0645 \u0627\u0644\u062a\u0648\u062c\u0647 \u0646\u062d\u0648 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645 \u0647\u0648 \u0627\u0644\u0630\u064a \u0648\u0635\u0651\u064e\u0627\u0643\u0645 \u0627\u0644\u0644\u0647 \u0628\u0647; \u0644\u062a\u062a\u0642\u0648\u0627 \u0639\u0630\u0627\u0628\u0647 \u0628\u0641\u0639\u0644 \u0623\u0648\u0627\u0645\u0631\u0647\u060c \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0646\u0648\u0627\u0647\u064a\u0647.","6:154":"\u062b\u0645 \u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0647\u0648 \u0627\u0644\u0630\u064a \u0623\u062a\u0649 \u0645\u0648\u0633\u0649 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u062a\u0645\u0627\u0645\u064b\u0627 \u0644\u0646\u0639\u0645\u062a\u0647 \u0639\u0644\u0649 \u0627\u0644\u0645\u062d\u0633\u0646\u064a\u0646 \u0645\u0646 \u0623\u0647\u0644 \u0645\u0644\u062a\u0647\u060c \u0648\u062a\u0641\u0635\u064a\u0644\u0627 \u0644\u0643\u0644 \u0634\u064a\u0621 \u0645\u0646 \u0623\u0645\u0648\u0631 \u062f\u064a\u0646\u0647\u0645\u060c \u0648\u0647\u062f\u0649 \u0648\u062f\u0644\u0627\u0644\u0629 \u0639\u0644\u0649 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645 \u0648\u0631\u062d\u0645\u0629 \u0644\u0647\u0645; \u0631\u062c\u0627\u0621 \u0623\u0646 \u064a\u0635\u062f\u0651\u0650\u0642\u0648\u0627 \u0628\u0627\u0644\u0628\u0639\u062b \u0628\u0639\u062f \u0627\u0644\u0645\u0648\u062a \u0648\u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u062c\u0632\u0627\u0621\u060c \u0648\u064a\u0639\u0645\u0644\u0648\u0627 \u0644\u0630\u0644\u0643.","6:155":"\u0648\u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0622\u0646 \u0643\u062a\u0627\u0628 \u0623\u0646\u0632\u0644\u0646\u0627\u0647 \u0639\u0644\u0649 \u0646\u0628\u064a\u0646\u0627 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u062e\u064a\u0631\u0647 \u0643\u062b\u064a\u0631 \u0641\u0627\u062a\u0628\u0639\u0648\u0647 \u0641\u064a\u0645\u0627 \u064a\u0623\u0645\u0631 \u0628\u0647 \u0648\u064a\u0646\u0647\u0649 \u0639\u0646\u0647\u060c \u0648\u0627\u062a\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0623\u0646 \u062a\u062e\u0627\u0644\u0641\u0648\u0627 \u0644\u0647 \u0623\u0645\u0631\u064b\u0627; \u0631\u062c\u0627\u0621 \u0623\u0646 \u062a\u0631\u062d\u0645\u0648\u0627 \u0641\u062a\u0646\u062c\u0648\u0627 \u0645\u0646 \u0639\u0630\u0627\u0628\u0647\u060c \u0648\u062a\u0638\u0641\u0631\u0648\u0627 \u0628\u062b\u0648\u0627\u0628\u0647.","6:156":"\u0648\u0623\u0646\u0632\u0644\u0646\u0627 \u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0622\u0646; \u0644\u0626\u0644\u0627 \u062a\u0642\u0648\u0644\u0648\u0627 -\u064a\u0627 \u0643\u0641\u0627\u0631 \u0627\u0644\u0639\u0631\u0628-: \u0625\u0646\u0645\u0627 \u0623\u064f\u0646\u0632\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0645\u0646 \u0627\u0644\u0633\u0645\u0627\u0621 \u0639\u0644\u0649 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649\u060c \u0648\u0642\u062f \u0643\u0646\u0627 \u0639\u0646 \u0642\u0631\u0627\u0621\u0629 \u0643\u062a\u0628\u0647\u0645 \u0641\u064a \u0634\u063a\u0644\u060c \u0648\u0646\u062d\u0646 \u0644\u064a\u0633 \u0644\u0646\u0627 \u0628\u0647\u0627 \u0639\u0644\u0645 \u0648\u0644\u0627 \u0645\u0639\u0631\u0641\u0629.","6:157":"\u0648\u0644\u0626\u0644\u0627 \u062a\u0642\u0648\u0644\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646-: \u0644\u0648 \u0623\u0646\u0651\u064e\u0627 \u0623\u064f\u0646\u0632\u0644 \u0639\u0644\u064a\u0646\u0627 \u0643\u062a\u0627\u0628 \u0645\u0646 \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u0643\u0645\u0627 \u0623\u064f\u0646\u0632\u0644 \u0639\u0644\u0649 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649\u060c \u0644\u0643\u0646\u0651\u064e\u0627 \u0623\u0634\u062f\u0651\u064e \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0639\u0644\u0649 \u0637\u0631\u064a\u0642 \u0627\u0644\u062d\u0642 \u0645\u0646\u0647\u0645\u060c \u0641\u0642\u062f \u062c\u0627\u0621\u0643\u0645 \u0643\u062a\u0627\u0628 \u0628\u0644\u0633\u0627\u0646\u0643\u0645 \u0639\u0631\u0628\u064a \u0645\u0628\u064a\u0646\u060c \u0648\u0630\u0644\u0643 \u062d\u062c\u0629 \u0648\u0627\u0636\u062d\u0629 \u0645\u0650\u0646 \u0631\u0628\u0643\u0645 \u0648\u0625\u0631\u0634\u0627\u062f \u0625\u0644\u0649 \u0637\u0631\u064a\u0642 \u0627\u0644\u062d\u0642\u060c \u0648\u0631\u062d\u0645\u0629\u064c \u0644\u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0629. \u0641\u0644\u0627 \u0623\u062d\u062f \u0623\u0634\u062f \u0638\u0644\u0645\u064b\u0627 \u0648\u0639\u062f\u0648\u0627\u0646\u064b\u0627 \u0645\u0645\u0646 \u0643\u0630\u0651\u064e\u0628 \u0628\u062d\u062c\u062c \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0623\u0639\u0631\u0636 \u0639\u0646\u0647\u0627!! \u0641\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0639\u0631\u0636\u0648\u0646 \u0633\u0646\u0639\u0627\u0642\u0628\u0647\u0645 \u0639\u0642\u0627\u0628\u064b\u0627 \u0634\u062f\u064a\u062f\u064b\u0627 \u0641\u064a \u0646\u0627\u0631 \u062c\u0647\u0646\u0645; \u0628\u0633\u0628\u0628 \u0625\u0639\u0631\u0627\u0636\u0647\u0645 \u0639\u0646 \u0622\u064a\u0627\u062a\u0646\u0627\u060c \u0648\u0635\u062f\u0651\u0650\u0647\u0645 \u0639\u0646 \u0633\u0628\u064a\u0644\u0646\u0627.","6:158":"\u0647\u0644 \u064a\u0646\u062a\u0638\u0631 \u0627\u0644\u0630\u064a\u0646 \u0623\u0639\u0631\u0636\u0648\u0627 \u0648\u0635\u062f\u0648\u0627 \u0639\u0646 \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0625\u0644\u0627 \u0623\u0646 \u064a\u0623\u062a\u064a\u0647\u0645 \u0645\u0644\u0643 \u0627\u0644\u0645\u0648\u062a \u0648\u0623\u0639\u0648\u0627\u0646\u0647 \u0644\u0642\u0628\u0636 \u0623\u0631\u0648\u0627\u062d\u0647\u0645\u060c \u0623\u0648 \u064a\u0623\u062a\u064a \u0631\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0644\u0641\u0635\u0644 \u0628\u064a\u0646 \u0639\u0628\u0627\u062f\u0647 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0623\u0648 \u064a\u0623\u062a\u064a \u0628\u0639\u0636 \u0623\u0634\u0631\u0627\u0637 \u0627\u0644\u0633\u0627\u0639\u0629 \u0648\u0639\u0644\u0627\u0645\u0627\u062a\u0647\u0627 \u0627\u0644\u062f\u0627\u0644\u0629 \u0639\u0644\u0649 \u0645\u062c\u064a\u0626\u0647\u0627\u060c \u0648\u0647\u064a \u0637\u0644\u0648\u0639 \u0627\u0644\u0634\u0645\u0633 \u0645\u0646 \u0645\u063a\u0631\u0628\u0647\u0627\u061f \u0641\u062d\u064a\u0646 \u064a\u0643\u0648\u0646 \u0630\u0644\u0643 \u0644\u0627 \u064a\u0646\u0641\u0639 \u0646\u0641\u0633\u0627 \u0625\u064a\u0645\u0627\u0646\u0647\u0627\u060c \u0625\u0646 \u0644\u0645 \u062a\u0643\u0646 \u0622\u0645\u0646\u062a \u0645\u0646 \u0642\u0628\u0644\u060c \u0648\u0644\u0627 \u064a\u064f\u0642\u0628\u0644 \u0645\u0646\u0647\u0627 \u0625\u0646 \u0643\u0627\u0646\u062a \u0645\u0624\u0645\u0646\u0629 \u0643\u0633\u0628 \u0639\u0645\u0644 \u0635\u0627\u0644\u062d \u0625\u0646 \u0644\u0645 \u062a\u0643\u0646 \u0639\u0627\u0645\u0644\u0629 \u0628\u0647 \u0642\u0628\u0644 \u0630\u0644\u0643. \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0627\u0646\u062a\u0638\u0631\u0648\u0627 \u0645\u062c\u064a\u0621 \u0630\u0644\u0643; \u0644\u062a\u0639\u0644\u0645\u0648\u0627 \u0627\u0644\u0645\u062d\u0642 \u0645\u0646 \u0627\u0644\u0645\u0628\u0637\u0644\u060c \u0648\u0627\u0644\u0645\u0633\u064a\u0621 \u0645\u0646 \u0627\u0644\u0645\u062d\u0633\u0646\u060c \u0625\u0646\u0627 \u0645\u0646\u062a\u0638\u0631\u0648\u0646 \u0630\u0644\u0643.","6:159":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u0641\u0631\u0642\u0648\u0627 \u062f\u064a\u0646\u0647\u0645 \u0628\u0639\u062f \u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u0645\u062c\u062a\u0645\u0639\u064a\u0646 \u0639\u0644\u0649 \u062a\u0648\u062d\u064a\u062f \u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u0639\u0645\u0644 \u0628\u0634\u0631\u0639\u0647\u060c \u0641\u0623\u0635\u0628\u062d\u0648\u0627 \u0641\u0631\u0642\u0627 \u0648\u0623\u062d\u0632\u0627\u0628\u0627\u060c \u0625\u0646\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0628\u0631\u064a\u0621 \u0645\u0646\u0647\u0645\u060c \u0625\u0646\u0645\u0627 \u062d\u0643\u0645\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u062b\u0645 \u064a\u062e\u0628\u0631\u0647\u0645 \u0628\u0623\u0639\u0645\u0627\u0644\u0647\u0645\u060c \u0641\u064a\u062c\u0627\u0632\u064a \u0645\u0646 \u062a\u0627\u0628 \u0645\u0646\u0647\u0645 \u0648\u0623\u062d\u0633\u0646 \u0628\u0625\u062d\u0633\u0627\u0646\u0647\u060c \u0648\u064a\u0639\u0627\u0642\u0628 \u0627\u0644\u0645\u0633\u064a\u0621 \u0628\u0625\u0633\u0627\u0621\u062a\u0647.","6:160":"\u0645\u0646 \u0644\u0642\u064a \u0631\u0628\u0647 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0628\u062d\u0633\u0646\u0629 \u0645\u0646 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u0629 \u0641\u0644\u0647 \u0639\u0634\u0631 \u062d\u0633\u0646\u0627\u062a \u0623\u0645\u062b\u0627\u0644\u0647\u0627\u060c \u0648\u0645\u0646 \u0644\u0642\u064a \u0631\u0628\u0647 \u0628\u0633\u064a\u0626\u0629 \u0641\u0644\u0627 \u064a\u0639\u0627\u0642\u0628 \u0625\u0644\u0627 \u0628\u0645\u062b\u0644\u0647\u0627\u060c \u0648\u0647\u0645 \u0644\u0627 \u064a\u0638\u0644\u0645\u0648\u0646 \u0645\u062b\u0642\u0627\u0644 \u0630\u0631\u0629.","6:161":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0625\u0646\u0646\u064a \u0623\u0631\u0634\u062f\u0646\u064a \u0631\u0628\u064a \u0625\u0644\u0649 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0642\u0648\u064a\u0645 \u0627\u0644\u0645\u0648\u0635\u0644 \u0625\u0644\u0649 \u062c\u0646\u062a\u0647\u060c \u0648\u0647\u0648 \u062f\u064a\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0627\u0644\u0642\u0627\u0626\u0645 \u0628\u0623\u0645\u0631 \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0647\u0648 \u062f\u064a\u0646 \u0627\u0644\u062a\u0648\u062d\u064a\u062f \u062f\u064a\u0646 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u0645\u0627 \u0643\u0627\u0646 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0645\u0639 \u0627\u0644\u0644\u0647 \u063a\u064a\u0631\u0647.","6:162":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0625\u0646 \u0635\u0644\u0627\u062a\u064a\u060c \u0648\u0646\u0633\u0643\u064a\u060c \u0623\u064a: \u0630\u0628\u062d\u064a \u0644\u0644\u0647 \u0648\u062d\u062f\u0647\u060c \u0644\u0627 \u0644\u0644\u0623\u0635\u0646\u0627\u0645\u060c \u0648\u0644\u0627 \u0644\u0644\u0623\u0645\u0648\u0627\u062a\u060c \u0648\u0644\u0627 \u0644\u0644\u062c\u0646\u060c \u0648\u0644\u0627 \u0644\u063a\u064a\u0631 \u0630\u0644\u0643 \u0645\u0645\u0627 \u062a\u0630\u0628\u062d\u0648\u0646\u0647 \u0644\u063a\u064a\u0631 \u0627\u0644\u0644\u0647\u060c \u0648\u0639\u0644\u0649 \u063a\u064a\u0631 \u0627\u0633\u0645\u0647 \u0643\u0645\u0627 \u062a\u0641\u0639\u0644\u0648\u0646\u060c \u0648\u062d\u064a\u0627\u062a\u064a \u0648\u0645\u0648\u062a\u064a \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0646.","6:163":"\u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647 \u0641\u064a \u0623\u0644\u0648\u0647\u064a\u062a\u0647 \u0648\u0644\u0627 \u0641\u064a \u0631\u0628\u0648\u0628\u064a\u062a\u0647 \u0648\u0644\u0627 \u0641\u064a \u0635\u0641\u0627\u062a\u0647 \u0648\u0623\u0633\u0645\u0627\u0626\u0647\u060c \u0648\u0628\u0630\u0644\u0643 \u0627\u0644\u062a\u0648\u062d\u064a\u062f \u0627\u0644\u062e\u0627\u0644\u0635 \u0623\u0645\u0631\u0646\u064a \u0631\u0628\u064a \u062c\u0644 \u0648\u0639\u0644\u0627 \u0648\u0623\u0646\u0627 \u0623\u0648\u0644 \u0645\u0646 \u0623\u0642\u0631 \u0648\u0627\u0646\u0642\u0627\u062f \u0644\u0644\u0647 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0629.","6:164":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0623\u063a\u064a\u0631 \u0627\u0644\u0644\u0647 \u0623\u0637\u0644\u0628 \u0625\u0644\u0647\u0627\u060c \u0648\u0647\u0648 \u062e\u0627\u0644\u0642 \u0643\u0644 \u0634\u064a\u0621 \u0648\u0645\u0627\u0644\u0643\u0647 \u0648\u0645\u062f\u0628\u0631\u0647\u061f \u0648\u0644\u0627 \u064a\u0639\u0645\u0644 \u0623\u064a \u0625\u0646\u0633\u0627\u0646 \u0639\u0645\u0644\u0627 \u0633\u064a\u0626\u0627 \u0625\u0644\u0627 \u0643\u0627\u0646 \u0625\u062b\u0645\u0647 \u0639\u0644\u064a\u0647\u060c \u0648\u0644\u0627 \u062a\u062d\u0645\u0644 \u0646\u0641\u0633 \u0622\u062b\u0645\u0629 \u0625\u062b\u0645 \u0646\u0641\u0633 \u0623\u062e\u0631\u0649\u060c \u062b\u0645 \u0625\u0644\u0649 \u0631\u0628\u0643\u0645 \u0645\u0639\u0627\u062f\u0643\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0641\u064a\u062e\u0628\u0631\u0643\u0645 \u0628\u0645\u0627 \u0643\u0646\u062a\u0645 \u062a\u062e\u062a\u0644\u0641\u0648\u0646 \u0641\u064a\u0647 \u0645\u0646 \u0623\u0645\u0631 \u0627\u0644\u062f\u064a\u0646.","6:165":"\u0648\u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0647\u0648 \u0627\u0644\u0630\u064a \u062c\u0639\u0644\u0643\u0645 \u062a\u062e\u0644\u0641\u0648\u0646 \u0645\u0646 \u0633\u0628\u0642\u0643\u0645 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0628\u0639\u062f \u0623\u0646 \u0623\u0647\u0644\u0643\u0647\u0645 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0633\u062a\u062e\u0644\u0641\u0643\u0645 \u0641\u064a\u0647\u0627; \u0644\u062a\u0639\u0645\u0631\u0648\u0647\u0627 \u0628\u0639\u062f\u0647\u0645 \u0628\u0637\u0627\u0639\u0629 \u0631\u0628\u0643\u0645\u060c \u0648\u0631\u0641\u0639 \u0628\u0639\u0636\u0643\u0645 \u0641\u064a \u0627\u0644\u0631\u0632\u0642 \u0648\u0627\u0644\u0642\u0648\u0629 \u0641\u0648\u0642 \u0628\u0639\u0636 \u062f\u0631\u062c\u0627\u062a\u060c \u0644\u064a\u0628\u0644\u0648\u0643\u0645 \u0641\u064a\u0645\u0627 \u0623\u0639\u0637\u0627\u0643\u0645 \u0645\u0646 \u0646\u0639\u0645\u0647\u060c \u0641\u064a\u0638\u0647\u0631 \u0644\u0644\u0646\u0627\u0633 \u0627\u0644\u0634\u0627\u0643\u0631 \u0645\u0646 \u063a\u064a\u0631\u0647. \u0625\u0646 \u0631\u0628\u0643 \u0633\u0631\u064a\u0639 \u0627\u0644\u0639\u0642\u0627\u0628 \u0644\u0645\u0646 \u0643\u0641\u0631 \u0628\u0647 \u0648\u0639\u0635\u0627\u0647\u060c \u0648\u0625\u0646\u0647 \u0644\u063a\u0641\u0648\u0631 \u0644\u0645\u0646 \u0622\u0645\u0646 \u0628\u0647 \u0648\u0639\u0645\u0644 \u0635\u0627\u0644\u062d\u0627 \u0648\u062a\u0627\u0628 \u0645\u0646 \u0627\u0644\u0645\u0648\u0628\u0642\u0627\u062a\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u060c \u0648\u0627\u0644\u063a\u0641\u0648\u0631 \u0648\u0627\u0644\u0631\u062d\u064a\u0645 \u0627\u0633\u0645\u0627\u0646 \u0643\u0631\u064a\u0645\u0627\u0646 \u0645\u0646 \u0623\u0633\u0645\u0627\u0621 \u0627\u0644\u0644\u0647 \u0627\u0644\u062d\u0633\u0646\u0649.","7:1":"\u0633\u0628\u0642 \u0627\u0644\u0643\u0644\u0627\u0645 \u0639\u0644\u0649 \u0627\u0644\u062d\u0631\u0648\u0641 \u0627\u0644\u0645\u0642\u0637\u0651\u064e\u0639\u0629 \u0641\u064a \u0623\u0648\u0644 \u0633\u0648\u0631\u0629 \u0627\u0644\u0628\u0642\u0631\u0629.","7:2":"\u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0622\u0646 \u0643\u062a\u0627\u0628 \u0639\u0638\u064a\u0645 \u0623\u0646\u0632\u0644\u0647 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0641\u0644\u0627 \u064a\u0643\u0646 \u0641\u064a \u0635\u062f\u0631\u0643 \u0634\u0643 \u0645\u0646\u0647 \u0641\u064a \u0623\u0646\u0647 \u0623\u0646\u0632\u0644 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u062a\u062a\u062d\u0631\u062c \u0641\u064a \u0625\u0628\u0644\u0627\u063a\u0647 \u0648\u0627\u0644\u0625\u0646\u0630\u0627\u0631 \u0628\u0647\u060c \u0623\u0646\u0632\u0644\u0646\u0627\u0647 \u0625\u0644\u064a\u0643; \u0644\u062a\u062e\u0648\u0641 \u0628\u0647 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0648\u062a\u0630\u0643\u0631 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646.","7:3":"\u0627\u062a\u0628\u0639\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633- \u0645\u0627 \u0623\u064f\u0646\u0632\u0644 \u0625\u0644\u064a\u0643\u0645 \u0645\u0646 \u0631\u0628\u0643\u0645 \u0645\u0646 \u0627\u0644\u0643\u062a\u0627\u0628 \u0648\u0627\u0644\u0633\u0646\u0629 \u0628\u0627\u0645\u062a\u062b\u0627\u0644 \u0627\u0644\u0623\u0648\u0627\u0645\u0631 \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0627\u0644\u0646\u0648\u0627\u0647\u064a\u060c \u0648\u0644\u0627 \u062a\u062a\u0628\u0639\u0648\u0627 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u0623\u0648\u0644\u064a\u0627\u0621 \u0643\u0627\u0644\u0634\u064a\u0627\u0637\u064a\u0646 \u0648\u0627\u0644\u0623\u062d\u0628\u0627\u0631 \u0648\u0627\u0644\u0631\u0647\u0628\u0627\u0646. \u0625\u0646\u0643\u0645 \u0642\u0644\u064a\u0644\u0627 \u0645\u0627 \u062a\u062a\u0639\u0638\u0648\u0646\u060c \u0648\u062a\u0639\u062a\u0628\u0631\u0648\u0646\u060c \u0641\u062a\u0631\u062c\u0639\u0648\u0646 \u0625\u0644\u0649 \u0627\u0644\u062d\u0642.","7:4":"\u0648\u0643\u062b\u064a\u0631 \u0645\u0646 \u0627\u0644\u0642\u0631\u0649 \u0623\u0647\u0644\u0643\u0646\u0627 \u0623\u0647\u0644\u0647\u0627 \u0628\u0633\u0628\u0628 \u0645\u062e\u0627\u0644\u0641\u0629 \u0631\u0633\u0644\u0646\u0627 \u0648\u062a\u0643\u0630\u064a\u0628\u0647\u0645\u060c \u0641\u0623\u0639\u0642\u0628\u0647\u0645 \u0630\u0644\u0643 \u062e\u0632\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0645\u0648\u0635\u0648\u0644\u0627 \u0628\u0630\u0644\u0651\u0650 \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0641\u062c\u0627\u0621\u0647\u0645 \u0639\u0630\u0627\u0628\u0646\u0627 \u0645\u0631\u0629 \u0648\u0647\u0645 \u0646\u0627\u0626\u0645\u0648\u0646 \u0644\u064a\u0644\u0627 \u0648\u0645\u0631\u0629 \u0648\u0647\u0645 \u0646\u0627\u0626\u0645\u0648\u0646 \u0646\u0647\u0627\u0631\u064b\u0627. \u0648\u062e\u064e\u0635\u0651\u064e \u0627\u0644\u0644\u0647 \u0647\u0630\u064a\u0646 \u0627\u0644\u0648\u0642\u062a\u064a\u0646; \u0644\u0623\u0646\u0647\u0645\u0627 \u0648\u0642\u062a\u0627\u0646 \u0644\u0644\u0633\u0643\u0648\u0646 \u0648\u0627\u0644\u0627\u0633\u062a\u0631\u0627\u062d\u0629\u060c \u0641\u0645\u062c\u064a\u0621 \u0627\u0644\u0639\u0630\u0627\u0628 \u0641\u064a\u0647\u0645\u0627 \u0623\u0641\u0638\u0639 \u0648\u0623\u0634\u062f.","7:5":"\u0641\u0645\u0627 \u0643\u0627\u0646 \u0642\u0648\u0644\u0647\u0645 \u0639\u0646\u062f \u0645\u062c\u064a\u0621 \u0627\u0644\u0639\u0630\u0627\u0628 \u0625\u0644\u0627 \u0627\u0644\u0625\u0642\u0631\u0627\u0631 \u0628\u0627\u0644\u0630\u0646\u0648\u0628 \u0648\u0627\u0644\u0625\u0633\u0627\u0621\u0629\u060c \u0648\u0623\u0646\u0647\u0645 \u062d\u0642\u064a\u0642\u0648\u0646 \u0628\u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0630\u064a \u0646\u0632\u0644 \u0628\u0647\u0645.","7:6":"\u0641\u0644\u0646\u0633\u0623\u0644\u0646 \u0627\u0644\u0623\u0645\u0645 \u0627\u0644\u0630\u064a\u0646 \u0623\u0631\u0633\u0644 \u0625\u0644\u064a\u0647\u0645 \u0627\u0644\u0645\u0631\u0633\u0644\u0648\u0646: \u0645\u0627\u0630\u0627 \u0623\u062c\u0628\u062a\u0645 \u0631\u0633\u0644\u0646\u0627 \u0625\u0644\u064a\u0643\u0645\u061f \u0648\u0644\u0646\u0633\u0652\u0623\u0644\u064e\u0646\u0651\u064e \u0627\u0644\u0645\u0631\u0633\u0644\u064a\u0646 \u0639\u0646 \u062a\u0628\u0644\u064a\u063a\u0647\u0645 \u0644\u0631\u0633\u0627\u0644\u0627\u062a \u0631\u0628\u0647\u0645\u060c \u0648\u0639\u0645\u0651\u064e\u0627 \u0623\u062c\u0627\u0628\u062a\u0647\u0645 \u0628\u0647 \u0623\u0645\u0645\u0647\u0645.","7:7":"\u0641\u0644\u064e\u0646\u0642\u064f\u0635\u0651\u064e\u0646\u0651\u064e \u0639\u0644\u0649 \u0627\u0644\u062e\u0644\u0642 \u0643\u0644\u0647\u0645 \u0645\u0627 \u0639\u0645\u0644\u0648\u0627 \u0628\u0639\u0644\u0645 \u0645\u0646\u0627 \u0644\u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0641\u064a\u0645\u0627 \u0623\u0645\u0631\u0646\u0627\u0647\u0645 \u0628\u0647\u060c \u0648\u0645\u0627 \u0646\u0647\u064a\u0646\u0627\u0647\u0645 \u0639\u0646\u0647\u060c \u0648\u0645\u0627 \u0643\u0646\u0627 \u063a\u0627\u0626\u0628\u064a\u0646 \u0639\u0646\u0647\u0645 \u0641\u064a \u062d\u0627\u0644 \u0645\u0646 \u0627\u0644\u0623\u062d\u0648\u0627\u0644.","7:8":"\u0648\u0648\u0632\u0646 \u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0646\u0627\u0633 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u064a\u0643\u0648\u0646 \u0628\u0645\u064a\u0632\u0627\u0646 \u062d\u0642\u064a\u0642\u064a \u0628\u0627\u0644\u0639\u062f\u0644 \u0648\u0627\u0644\u0642\u0633\u0637 \u0627\u0644\u0630\u064a \u0644\u0627 \u0638\u0644\u0645 \u0641\u064a\u0647\u060c \u0641\u0645\u0646 \u062b\u0642\u0644\u062a \u0645\u0648\u0627\u0632\u064a\u0646 \u0623\u0639\u0645\u0627\u0644\u0647 -\u0644\u0643\u062b\u0631\u0629 \u062d\u0633\u0646\u0627\u062a\u0647- \u0641\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u0641\u0627\u0626\u0632\u0648\u0646.","7:9":"\u0648\u0645\u0646 \u062e\u064e\u0641\u0651\u064e\u062a\u0652 \u0645\u0648\u0627\u0632\u064a\u0646 \u0623\u0639\u0645\u0627\u0644\u0647 -\u0644\u0643\u062b\u0631\u0629 \u0633\u064a\u0626\u0627\u062a\u0647- \u0641\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0623\u0636\u0627\u0639\u0648\u0627 \u062d\u0638\u0651\u064e\u0647\u0645 \u0645\u0646 \u0631\u0636\u0648\u0627\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0628\u0633\u0628\u0628 \u062a\u062c\u0627\u0648\u0632\u0647\u0645 \u0627\u0644\u062d\u062f \u0628\u062c\u062d\u062f \u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0639\u062f\u0645 \u0627\u0644\u0627\u0646\u0642\u064a\u0627\u062f \u0644\u0647\u0627.","7:10":"\u0648\u0644\u0642\u062f \u0645\u0643\u0651\u064e\u0646\u0651\u064e\u0627 \u0644\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633- \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u062c\u0639\u0644\u0646\u0627\u0647\u0627 \u0642\u0631\u0627\u0631\u064b\u0627 \u0644\u0643\u0645\u060c \u0648\u062c\u0639\u0644\u0646\u0627 \u0644\u0643\u0645 \u0641\u064a\u0647\u0627 \u0645\u0627 \u062a\u0639\u064a\u0634\u0648\u0646 \u0628\u0647 \u0645\u0646 \u0645\u0637\u0627\u0639\u0645 \u0648\u0645\u0634\u0627\u0631\u0628\u060c \u0648\u0645\u0639 \u0630\u0644\u0643 \u0641\u0634\u0643\u0631\u0643\u0645 \u0644\u0646\u0639\u0645 \u0627\u0644\u0644\u0647 \u0642\u0644\u064a\u0644.","7:11":"\u0648\u0644\u0642\u062f \u0623\u0646\u0639\u0645\u0646\u0627 \u0639\u0644\u064a\u0643\u0645 \u0628\u062e\u0644\u0642 \u0623\u0635\u0644\u0643\u0645 -\u0648\u0647\u0648 \u0623\u0628\u0648\u0643\u0645 \u0622\u062f\u0645 \u0645\u0646 \u0627\u0644\u0639\u062f\u0645- \u062b\u0645 \u0635\u0648\u0651\u064e\u0631\u0646\u0627\u0647 \u0639\u0644\u0649 \u0647\u064a\u0626\u062a\u0647 \u0627\u0644\u0645\u0641\u0636\u0644\u0629 \u0639\u0644\u0649 \u0643\u062b\u064a\u0631 \u0645\u0646 \u0627\u0644\u062e\u0644\u0642\u060c \u062b\u0645 \u0623\u0645\u0631\u0646\u0627 \u0645\u0644\u0627\u0626\u0643\u062a\u0646\u0627 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0633\u0644\u0627\u0645 \u0628\u0627\u0644\u0633\u062c\u0648\u062f \u0644\u0647 -\u0625\u0643\u0631\u0627\u0645\u064b\u0627 \u0648\u0627\u062d\u062a\u0631\u0627\u0645\u064b\u0627 \u0648\u0625\u0638\u0647\u0627\u0631\u064b\u0627 \u0644\u0641\u0636\u0644 \u0622\u062f\u0645- \u0641\u0633\u062c\u062f\u0648\u0627 \u062c\u0645\u064a\u0639\u064b\u0627\u060c \u0644\u0643\u0646\u0651\u064e \u0625\u0628\u0644\u064a\u0633 \u0627\u0644\u0630\u064a \u0643\u0627\u0646 \u0645\u0639\u0647\u0645 \u0644\u0645 \u064a\u0643\u0646 \u0645\u0646 \u0627\u0644\u0633\u0627\u062c\u062f\u064a\u0646 \u0644\u0622\u062f\u0645; \u062d\u0633\u062f\u064b\u0627 \u0644\u0647 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062a\u0643\u0631\u064a\u0645 \u0627\u0644\u0639\u0638\u064a\u0645.","7:12":"\u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649 \u0645\u0646\u0643\u0631\u064b\u0627 \u0639\u0644\u0649 \u0625\u0628\u0644\u064a\u0633 \u062a\u064e\u0631\u0652\u0643\u064e \u0627\u0644\u0633\u062c\u0648\u062f: \u0645\u0627 \u0645\u0646\u0639\u0643 \u0623\u0644\u0627 \u062a\u0633\u062c\u062f \u0625\u0630 \u0623\u0645\u0631\u062a\u0643\u061f \u0641\u0642\u0627\u0644 \u0625\u0628\u0644\u064a\u0633: \u0623\u0646\u0627 \u0623\u0641\u0636\u0644 \u0645\u0646\u0647 \u062e\u0644\u0642\u064b\u0627; \u0644\u0623\u0646\u064a \u0645\u062e\u0644\u0648\u0642 \u0645\u0646 \u0646\u0627\u0631\u060c \u0648\u0647\u0648 \u0645\u062e\u0644\u0648\u0642 \u0645\u0646 \u0637\u064a\u0646. \u0641\u0631\u0623\u0649 \u0623\u0646 \u0627\u0644\u0646\u0627\u0631 \u0623\u0634\u0631\u0641 \u0645\u0646 \u0627\u0644\u0637\u064a\u0646.","7:13":"\u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u0644\u0625\u0628\u0644\u064a\u0633: \u0641\u0627\u0647\u0628\u0637 \u0645\u0646 \u0627\u0644\u062c\u0646\u0629\u060c \u0641\u0645\u0627 \u064a\u0635\u062d \u0644\u0643 \u0623\u0646 \u062a\u062a\u0643\u0628\u0631 \u0641\u064a\u0647\u0627\u060c \u0641\u0627\u062e\u0631\u062c \u0645\u0646 \u0627\u0644\u062c\u0646\u0629\u060c \u0625\u0646\u0643 \u0645\u0646 \u0627\u0644\u0630\u0644\u064a\u0644\u064a\u0646 \u0627\u0644\u062d\u0642\u064a\u0631\u064a\u0646.","7:14":"\u0642\u0627\u0644 \u0625\u0628\u0644\u064a\u0633 \u0644\u0644\u0647 -\u062c\u0644 \u0648\u0639\u0644\u0627- \u062d\u064a\u0646\u0645\u0627 \u064a\u0626\u0633 \u0645\u0646 \u0631\u062d\u0645\u062a\u0647: \u0623\u0645\u0647\u0644\u0646\u064a \u0625\u0644\u0649 \u064a\u0648\u0645 \u0627\u0644\u0628\u0639\u062b; \u0648\u0630\u0644\u0643 \u0644\u0623\u062a\u0645\u0643\u0646 \u0645\u0646 \u0625\u063a\u0648\u0627\u0621 \u0645\u064e\u0646 \u0623\u0642\u062f\u0631 \u0639\u0644\u064a\u0647 \u0645\u0646 \u0628\u0646\u064a \u0622\u062f\u0645.","7:15":"\u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \u0625\u0646\u0643 \u0645\u0645\u0646 \u0643\u062a\u0628\u062a\u064f \u0639\u0644\u064a\u0647\u0645 \u062a\u0623\u062e\u064a\u0631 \u0627\u0644\u0623\u062c\u0644 \u0625\u0644\u0649 \u0627\u0644\u0646\u0641\u062e\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0641\u064a \u0627\u0644\u0642\u0631\u0646\u060c \u0625\u0630 \u064a\u0645\u0648\u062a \u0627\u0644\u062e\u0644\u0642 \u0643\u0644\u0647\u0645.","7:16":"\u0642\u0627\u0644 \u0625\u0628\u0644\u064a\u0633 \u0644\u0639\u0646\u0647 \u0627\u0644\u0644\u0647: \u0641\u0628\u0633\u0628\u0628 \u0645\u0627 \u0623\u0636\u0644\u0644\u062a\u0646\u064a \u0644\u0623\u062c\u062a\u0647\u062f\u0646\u0651\u064e \u0641\u064a \u0625\u063a\u0648\u0627\u0621 \u0628\u0646\u064a \u0622\u062f\u0645 \u0639\u0646 \u0637\u0631\u064a\u0642\u0643 \u0627\u0644\u0642\u0648\u064a\u0645\u060c \u0648\u0644\u0623\u0635\u062f\u0651\u064e\u0646\u0651\u064e\u0647\u0645 \u0639\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0627\u0644\u0630\u064a \u0641\u0637\u0631\u062a\u0647\u0645 \u0639\u0644\u064a\u0647.","7:17":"\u062b\u0645 \u0644\u0622\u062a\u064a\u0646\u0651\u064e\u0647\u0645 \u0645\u0646 \u062c\u0645\u064a\u0639 \u0627\u0644\u062c\u0647\u0627\u062a \u0648\u0627\u0644\u062c\u0648\u0627\u0646\u0628\u060c \u0641\u0623\u0635\u062f\u0647\u0645 \u0639\u0646 \u0627\u0644\u062d\u0642\u060c \u0648\u0623\u064f\u062d\u0633\u0651\u0650\u0646 \u0644\u0647\u0645 \u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0648\u0623\u0631\u063a\u0628\u0647\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0623\u0634\u0643\u0643\u0647\u0645 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0644\u0627 \u062a\u062c\u062f \u0623\u0643\u062b\u0631 \u0628\u0646\u064a \u0622\u062f\u0645 \u0634\u0627\u0643\u0631\u064a\u0646 \u0644\u0643 \u0646\u0639\u0645\u062a\u0643.","7:18":"\u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0625\u0628\u0644\u064a\u0633: \u0627\u062e\u0631\u062c \u0645\u0646 \u0627\u0644\u062c\u0646\u0629 \u0645\u0645\u0642\u0648\u062a\u064b\u0627 \u0645\u0637\u0631\u0648\u062f\u064b\u0627\u060c \u0644\u0623\u0645\u0644\u0623\u0646\u0651\u064e \u062c\u0647\u0646\u0645 \u0645\u0646\u0643 \u0648\u0645\u0645\u0646 \u062a\u0628\u0639\u0643 \u0645\u0646 \u0628\u0646\u064a \u0622\u062f\u0645 \u0623\u062c\u0645\u0639\u064a\u0646.","7:19":"\u0648\u064a\u0627 \u0622\u062f\u0645 \u0627\u0633\u0643\u0646 \u0623\u0646\u062a \u0648\u0632\u0648\u062c\u0643 \u062d\u0648\u0627\u0621 \u0627\u0644\u062c\u0646\u0629\u060c \u0641\u0643\u064f\u0644\u0627 \u0645\u0646 \u062b\u0645\u0627\u0631\u0647\u0627 \u062d\u064a\u062b \u0634\u0626\u062a\u0645\u0627\u060c \u0648\u0644\u0627 \u062a\u0623\u0643\u0644\u0627 \u0645\u0646 \u062b\u0645\u0631\u0629 \u0634\u062c\u0631\u0629 (\u0639\u064e\u064a\u0651\u064e\u0646\u0647\u0627 \u0644\u0647\u0645\u0627) \u060c \u0641\u0625\u0646 \u0641\u0639\u0644\u062a\u0645\u0627 \u0630\u0644\u0643 \u0643\u0646\u062a\u0645\u0627 \u0645\u0646 \u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0627\u0644\u0645\u062a\u062c\u0627\u0648\u0632\u064a\u0646 \u062d\u062f\u0648\u062f \u0627\u0644\u0644\u0647.","7:20":"\u0641\u0623\u0644\u0642\u0649 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0644\u0622\u062f\u0645 \u0648\u062d\u0648\u0627\u0621 \u0648\u0633\u0648\u0633\u0629 \u0644\u0625\u064a\u0642\u0627\u0639\u0647\u0645\u0627 \u0641\u064a \u0645\u0639\u0635\u064a\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0627\u0644\u0623\u0643\u0644 \u0645\u0646 \u062a\u0644\u0643 \u0627\u0644\u0634\u062c\u0631\u0629 \u0627\u0644\u062a\u064a \u0646\u0647\u0627\u0647\u0645\u0627 \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627; \u0644\u062a\u0643\u0648\u0646 \u0639\u0627\u0642\u0628\u062a\u0647\u0645\u0627 \u0627\u0646\u0643\u0634\u0627\u0641 \u0645\u0627 \u0633\u064f\u062a\u0631 \u0645\u0646 \u0639\u0648\u0631\u0627\u062a\u0647\u0645\u0627\u060c \u0648\u0642\u0627\u0644 \u0644\u0647\u0645\u0627 \u0641\u064a \u0645\u062d\u0627\u0648\u0644\u0629 \u0627\u0644\u0645\u0643\u0631 \u0628\u0647\u0645\u0627: \u0625\u0646\u0645\u0627 \u0646\u0647\u0627\u0643\u0645\u0627 \u0631\u0628\u0643\u0645\u0627 \u0639\u0646 \u0627\u0644\u0623\u0643\u0644 \u0645\u0650\u0646 \u062b\u0645\u0631 \u0647\u0630\u0647 \u0627\u0644\u0634\u062c\u0631\u0629 \u0645\u0650\u0646 \u0623\u062c\u0644 \u0623\u0646 \u0644\u0627 \u062a\u0643\u0648\u0646\u0627 \u0645\u0644\u064e\u0643\u064a\u0646\u060c \u0648\u0645\u0650\u0646 \u0623\u062c\u0644 \u0623\u0646 \u0644\u0627 \u062a\u0643\u0648\u0646\u0627 \u0645\u0646 \u0627\u0644\u062e\u0627\u0644\u062f\u064a\u0646 \u0641\u064a \u0627\u0644\u062d\u064a\u0627\u0629.","7:21":"\u0648\u0623\u0642\u0633\u0645 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0644\u0622\u062f\u0645 \u0648\u062d\u0648\u0627\u0621 \u0628\u0627\u0644\u0644\u0647 \u0625\u0646\u0647 \u0645\u0645\u0646 \u064a\u0646\u0635\u062d \u0644\u0647\u0645\u0627 \u0641\u064a \u0645\u0634\u0648\u0631\u062a\u0647 \u0639\u0644\u064a\u0647\u0645\u0627 \u0628\u0627\u0644\u0623\u0643\u0644 \u0645\u0646 \u0627\u0644\u0634\u062c\u0631\u0629\u060c \u0648\u0647\u0648 \u0643\u0627\u0630\u0628 \u0641\u064a \u0630\u0644\u0643.","7:22":"\u0641\u062c\u0631\u0651\u064e\u0623\u0647\u0645\u0627 \u0648\u063a\u0631\u0651\u064e\u0647\u0645\u0627\u060c \u0641\u0623\u0643\u0644\u0627 \u0645\u0646 \u0627\u0644\u0634\u062c\u0631\u0629 \u0627\u0644\u062a\u064a \u0646\u0647\u0627\u0647\u0645\u0627 \u0627\u0644\u0644\u0647 \u0639\u0646 \u0627\u0644\u0627\u0642\u062a\u0631\u0627\u0628 \u0645\u0646\u0647\u0627\u060c \u0641\u0644\u0645\u0627 \u0623\u0643\u0644\u0627 \u0645\u0646\u0647\u0627 \u0627\u0646\u0643\u0634\u0641\u062a \u0644\u0647\u0645\u0627 \u0639\u0648\u0631\u0627\u062a\u0647\u0645\u0627\u060c \u0648\u0632\u0627\u0644 \u0645\u0627 \u0633\u062a\u0631\u0647\u0645\u0627 \u0627\u0644\u0644\u0647 \u0628\u0647 \u0642\u0628\u0644 \u0627\u0644\u0645\u062e\u0627\u0644\u0641\u0629\u060c \u0641\u0623\u062e\u0630\u0627 \u064a\u0644\u0632\u0642\u0627\u0646 \u0628\u0639\u0636 \u0648\u0631\u0642 \u0627\u0644\u062c\u0646\u0629 \u0639\u0644\u0649 \u0639\u0648\u0631\u0627\u062a\u0647\u0645\u0627\u060c \u0648\u0646\u0627\u062f\u0627\u0647\u0645\u0627 \u0631\u0628\u0647\u0645\u0627 \u062c\u0644 \u0648\u0639\u0644\u0627 \u0623\u0644\u0645 \u0623\u0646\u0647\u0643\u0645\u0627 \u0639\u0646 \u0627\u0644\u0623\u0643\u0644 \u0645\u0646 \u062a\u0644\u0643 \u0627\u0644\u0634\u062c\u0631\u0629\u060c \u0648\u0623\u0642\u0644 \u0644\u0643\u0645\u0627: \u0625\u0646 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0644\u0643\u0645\u0627 \u0639\u062f\u0648 \u0638\u0627\u0647\u0631 \u0627\u0644\u0639\u062f\u0627\u0648\u0629\u061f \u0648\u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629 \u062f\u0644\u064a\u0644 \u0639\u0644\u0649 \u0623\u0646 \u0643\u0634\u0641 \u0627\u0644\u0639\u0648\u0631\u0629 \u0645\u0646 \u0639\u0638\u0627\u0626\u0645 \u0627\u0644\u0623\u0645\u0648\u0631\u060c \u0648\u0623\u0646\u0647 \u0643\u0627\u0646 \u0648\u0644\u0645 \u064a\u0632\u0644 \u0645\u0633\u062a\u0647\u062c\u064e\u0646\u064b\u0627 \u0641\u064a \u0627\u0644\u0637\u0628\u0627\u0639\u060c \u0645\u0633\u062a\u0642\u0628\u064e\u062d\u064b\u0627 \u0641\u064a \u0627\u0644\u0639\u0642\u0648\u0644.","7:23":"\u0642\u0627\u0644 \u0622\u062f\u0645 \u0648\u062d\u0648\u0627\u0621: \u0631\u0628\u0646\u0627 \u0638\u0644\u0645\u0646\u0627 \u0623\u0646\u0641\u0633\u0646\u0627 \u0628\u0627\u0644\u0623\u0643\u0644 \u0645\u0646 \u0627\u0644\u0634\u062c\u0631\u0629\u060c \u0648\u0625\u0646 \u0644\u0645 \u062a\u063a\u0641\u0631 \u0644\u0646\u0627 \u0648\u062a\u0631\u062d\u0645\u0646\u0627 \u0644\u0646\u0643\u0648\u0646\u0646 \u0645\u0645\u0646 \u0623\u0636\u0627\u0639\u0648\u0627 \u062d\u0638\u0651\u064e\u0647\u0645 \u0641\u064a \u062f\u0646\u064a\u0627\u0647\u0645 \u0648\u0623\u062e\u0631\u0627\u0647\u0645. (\u0648\u0647\u0630\u0647 \u0627\u0644\u0643\u0644\u0645\u0627\u062a \u0647\u064a \u0627\u0644\u062a\u064a \u062a\u0644\u0642\u0627\u0647\u0627 \u0622\u062f\u0645 \u0645\u0646 \u0631\u0628\u0647\u060c \u0641\u062f\u0639\u0627 \u0628\u0647\u0627 \u0641\u062a\u0627\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647) .","7:24":"\u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649 \u0645\u062e\u0627\u0637\u0628\u064b\u0627 \u0622\u062f\u0645 \u0648\u062d\u0648\u0627\u0621 \u0644\u0625\u0628\u0644\u064a\u0633: \u0627\u0647\u0628\u0637\u0648\u0627 \u0645\u0646 \u0627\u0644\u0633\u0645\u0627\u0621 \u0625\u0644\u0649 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0633\u064a\u0643\u0648\u0646 \u0628\u0639\u0636\u0643\u0645 \u0644\u0628\u0639\u0636 \u0639\u062f\u0648\u064b\u0627\u060c \u0648\u0644\u0643\u0645 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0645\u0643\u0627\u0646 \u062a\u0633\u062a\u0642\u0631\u0648\u0646 \u0641\u064a\u0647\u060c \u0648\u062a\u062a\u0645\u062a\u0639\u0648\u0646 \u0625\u0644\u0649 \u0627\u0646\u0642\u0636\u0627\u0621 \u0622\u062c\u0627\u0644\u0643\u0645.","7:25":"\u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0622\u062f\u0645 \u0648\u062d\u0648\u0651\u064e\u0627\u0621 \u0648\u0630\u0631\u064a\u062a\u0647\u0645\u0627: \u0641\u064a\u0647\u0627 \u062a\u062d\u064a\u0648\u0646\u060c \u0623\u064a: \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u062a\u0642\u0636\u0648\u0646 \u0623\u064a\u0627\u0645 \u062d\u064a\u0627\u062a\u0643\u0645 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0641\u064a\u0647\u0627 \u062a\u0643\u0648\u0646 \u0648\u0641\u0627\u062a\u0643\u0645\u060c \u0648\u0645\u0646\u0647\u0627 \u064a\u062e\u0631\u062c\u0643\u0645 \u0631\u0628\u0643\u0645\u060c \u0648\u064a\u062d\u0634\u0631\u0643\u0645 \u0623\u062d\u064a\u0627\u0621 \u064a\u0648\u0645 \u0627\u0644\u0628\u0639\u062b.","7:26":"\u064a\u0627 \u0628\u0646\u064a \u0622\u062f\u0645 \u0642\u062f \u062c\u0639\u0644\u0646\u0627 \u0644\u0643\u0645 \u0644\u0628\u0627\u0633\u064b\u0627 \u064a\u0633\u062a\u0631 \u0639\u0648\u0631\u0627\u062a\u0643\u0645\u060c \u0648\u0647\u0648 \u0644\u0628\u0627\u0633 \u0627\u0644\u0636\u0631\u0648\u0631\u0629\u060c \u0648\u0644\u0628\u0627\u0633\u064b\u0627 \u0644\u0644\u0632\u064a\u0646\u0629 \u0648\u0627\u0644\u062a\u062c\u0645\u0644\u060c \u0648\u0647\u0648 \u0645\u0646 \u0627\u0644\u0643\u0645\u0627\u0644 \u0648\u0627\u0644\u062a\u0646\u0639\u0645. \u0648\u0644\u0628\u0627\u0633\u064f \u062a\u0642\u0648\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0641\u0639\u0644 \u0627\u0644\u0623\u0648\u0627\u0645\u0631 \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0627\u0644\u0646\u0648\u0627\u0647\u064a \u0647\u0648 \u062e\u064a\u0631 \u0644\u0628\u0627\u0633 \u0644\u0644\u0645\u0624\u0645\u0646. \u0630\u0644\u0643 \u0627\u0644\u0630\u064a \u0645\u064e\u0646\u0651\u064e \u0627\u0644\u0644\u0647 \u0628\u0647 \u0639\u0644\u064a\u0643\u0645 \u0645\u0646 \u0627\u0644\u062f\u0644\u0627\u0626\u0644 \u0639\u0644\u0649 \u0631\u0628\u0648\u0628\u064a\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0648\u062d\u062f\u0627\u0646\u064a\u062a\u0647 \u0648\u0641\u0636\u0644\u0647 \u0648\u0631\u062d\u0645\u062a\u0647 \u0628\u0639\u0628\u0627\u062f\u0647; \u0644\u0643\u064a \u062a\u062a\u0630\u0643\u0631\u0648\u0627 \u0647\u0630\u0647 \u0627\u0644\u0646\u0639\u0645\u060c \u0641\u062a\u0634\u0643\u0631\u0648\u0627 \u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0627. \u0648\u0641\u064a \u0630\u0644\u0643 \u0627\u0645\u062a\u0646\u0627\u0646 \u0645\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u0649 \u062e\u064e\u0644\u0652\u0642\u0647 \u0628\u0647\u0630\u0647 \u0627\u0644\u0646\u0639\u0645.","7:27":"\u064a\u0627 \u0628\u0646\u064a \u0622\u062f\u0645 \u0644\u0627 \u064a\u062e\u062f\u0639\u0646\u0651\u064e\u0643\u0645 \u0627\u0644\u0634\u064a\u0637\u0627\u0646\u060c \u0641\u064a\u0632\u064a\u0646 \u0644\u0643\u0645 \u0627\u0644\u0645\u0639\u0635\u064a\u0629\u060c \u0643\u0645\u0627 \u0632\u064a\u0651\u064e\u0646\u0647\u0627 \u0644\u0623\u0628\u0648\u064a\u0643\u0645 \u0622\u062f\u0645 \u0648\u062d\u0648\u0627\u0621\u060c \u0641\u0623\u062e\u0631\u062c\u0647\u0645\u0627 \u0628\u0633\u0628\u0628\u0647\u0627 \u0645\u0646 \u0627\u0644\u062c\u0646\u0629\u060c \u064a\u0646\u0632\u0639 \u0639\u0646\u0647\u0645\u0627 \u0644\u0628\u0627\u0633\u0647\u0645\u0627 \u0627\u0644\u0630\u064a \u0633\u062a\u0631\u0647\u0645\u0627 \u0627\u0644\u0644\u0647 \u0628\u0647; \u0644\u062a\u0646\u0643\u0634\u0641 \u0644\u0647\u0645\u0627 \u0639\u0648\u0631\u0627\u062a\u0647\u0645\u0627. \u0625\u0646 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u064a\u0631\u0627\u0643\u0645 \u0647\u0648 \u0648\u0630\u0631\u064a\u062a\u0647 \u0648\u062c\u0646\u0633\u0647 \u0648\u0623\u0646\u062a\u0645 \u0644\u0627 \u062a\u0631\u0648\u0646\u0647\u0645 \u0641\u0627\u062d\u0630\u0631\u0648\u0647\u0645. \u0625\u0646\u0651\u064e\u0627 \u062c\u0639\u0644\u0646\u0627 \u0627\u0644\u0634\u064a\u0627\u0637\u064a\u0646 \u0623\u0648\u0644\u064a\u0627\u0621 \u0644\u0644\u0643\u0641\u0627\u0631 \u0627\u0644\u0630\u064a\u0646 \u0644\u0627 \u064a\u0648\u062d\u062f\u0648\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u064a\u0635\u062f\u0642\u0648\u0646 \u0631\u0633\u0644\u0647\u060c \u0648\u0644\u0627 \u064a\u0639\u0645\u0644\u0648\u0646 \u0628\u0647\u062f\u064a\u0647.","7:28":"\u0648\u0625\u0630\u0627 \u0623\u062a\u0649 \u0627\u0644\u0643\u0641\u0627\u0631 \u0642\u0628\u064a\u062d\u064b\u0627 \u0645\u0646 \u0627\u0644\u0641\u0639\u0644 \u0627\u0639\u062a\u0630\u0631\u0648\u0627 \u0639\u0646 \u0641\u0639\u0644\u0647 \u0628\u0623\u0646\u0647 \u0645\u0645\u0627 \u0648\u0631\u062b\u0648\u0647 \u0639\u0646 \u0622\u0628\u0627\u0626\u0647\u0645\u060c \u0648\u0623\u0646\u0647 \u0645\u0645\u0627 \u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u0628\u0647. \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0627 \u064a\u0623\u0645\u0631 \u0639\u0628\u0627\u062f\u0647 \u0628\u0642\u0628\u0627\u0626\u062d \u0627\u0644\u0623\u0641\u0639\u0627\u0644 \u0648\u0645\u0633\u0627\u0648\u0626\u0647\u0627\u060c \u0623\u062a\u0642\u0648\u0644\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646- \u0645\u0627 \u0644\u0627 \u062a\u0639\u0644\u0645\u0648\u0646 \u0643\u0630\u0628\u064b\u0627 \u0648\u0627\u0641\u062a\u0631\u0627\u0621\u064b\u061f","7:29":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0623\u0645\u0631 \u0631\u0628\u064a \u0628\u0627\u0644\u0639\u062f\u0644\u060c \u0648\u0623\u0645\u0631\u0643\u0645 \u0628\u0623\u0646 \u062a\u062e\u0644\u0635\u0648\u0627 \u0644\u0647 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0641\u064a \u0643\u0644 \u0645\u0648\u0636\u0639 \u0645\u0646 \u0645\u0648\u0627\u0636\u0639\u0647\u0627\u060c \u0648\u0628\u062e\u0627\u0635\u0629 \u0641\u064a \u0627\u0644\u0645\u0633\u0627\u062c\u062f\u060c \u0648\u0623\u0646 \u062a\u062f\u0639\u0648\u0647 \u0645\u062e\u0644\u0635\u064a\u0646 \u0644\u0647 \u0627\u0644\u0637\u0627\u0639\u0629 \u0648\u0627\u0644\u0639\u0628\u0627\u062f\u0629\u060c \u0648\u0623\u0646 \u062a\u0624\u0645\u0646\u0648\u0627 \u0628\u0627\u0644\u0628\u0639\u062b \u0628\u0639\u062f \u0627\u0644\u0645\u0648\u062a. \u0648\u0643\u0645\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0623\u0648\u062c\u062f\u0643\u0645 \u0645\u0646 \u0627\u0644\u0639\u062f\u0645 \u0641\u0625\u0646\u0647 \u0642\u0627\u062f\u0631 \u0639\u0644\u0649 \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062d\u064a\u0627\u0629 \u0625\u0644\u064a\u0643\u0645 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649.","7:30":"\u062c\u0639\u0644 \u0627\u0644\u0644\u0647 \u0639\u0628\u0627\u062f\u0647 \u0641\u0631\u064a\u0642\u064a\u0646: \u0641\u0631\u064a\u0642\u064b\u0627 \u0648\u0641\u0651\u064e\u0642\u0647\u0645 \u0644\u0644\u0647\u062f\u0627\u064a\u0629 \u0625\u0644\u0649 \u0627\u0644\u0635\u0631\u0627\u0637 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645\u060c \u0648\u0641\u0631\u064a\u0642\u064b\u0627 \u0648\u062c\u0628\u062a \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0636\u0644\u0627\u0644\u0629 \u0639\u0646 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645\u060c \u0625\u0646\u0647\u0645 \u0627\u062a\u062e\u0630\u0648\u0627 \u0627\u0644\u0634\u064a\u0627\u0637\u064a\u0646 \u0623\u0648\u0644\u064a\u0627\u0621 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647\u060c \u0641\u0623\u0637\u0627\u0639\u0648\u0647\u0645 \u062c\u0647\u0644\u0627 \u0645\u0646\u0647\u0645 \u0648\u0638\u0646\u064b\u0627 \u0628\u0623\u0646\u0647\u0645 \u0642\u062f \u0633\u0644\u0643\u0648\u0627 \u0633\u0628\u064a\u0644 \u0627\u0644\u0647\u062f\u0627\u064a\u0629.","7:31":"\u064a\u0627 \u0628\u0646\u064a \u0622\u062f\u0645 \u0643\u0648\u0646\u0648\u0627 \u0639\u0646\u062f \u0623\u062f\u0627\u0621 \u0643\u0644 \u0635\u0644\u0627\u0629 \u0639\u0644\u0649 \u062d\u0627\u0644\u0629 \u0645\u0646 \u0627\u0644\u0632\u064a\u0646\u0629 \u0627\u0644\u0645\u0634\u0631\u0648\u0639\u0629 \u0645\u0646 \u062b\u064a\u0627\u0628 \u0633\u0627\u062a\u0631\u0629 \u0644\u0639\u0648\u0631\u0627\u062a\u0643\u0645 \u0648\u0646\u0638\u0627\u0641\u0629 \u0648\u0637\u0647\u0627\u0631\u0629 \u0648\u0646\u062d\u0648 \u0630\u0644\u0643\u060c \u0648\u0643\u0644\u0648\u0627 \u0648\u0627\u0634\u0631\u0628\u0648\u0627 \u0645\u0646 \u0637\u064a\u0628\u0627\u062a \u0645\u0627 \u0631\u0632\u0642\u0643\u0645 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u062a\u062a\u062c\u0627\u0648\u0632\u0648\u0627 \u062d\u062f\u0648\u062f \u0627\u0644\u0627\u0639\u062a\u062f\u0627\u0644 \u0641\u064a \u0630\u0644\u0643. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u062d\u0628 \u0627\u0644\u0645\u062a\u062c\u0627\u0648\u0632\u064a\u0646 \u0627\u0644\u0645\u0633\u0631\u0641\u064a\u0646 \u0641\u064a \u0627\u0644\u0637\u0639\u0627\u0645 \u0648\u0627\u0644\u0634\u0631\u0627\u0628 \u0648\u063a\u064a\u0631 \u0630\u0644\u0643.","7:32":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u062c\u0647\u0644\u0629 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0645\u064e\u0646 \u0627\u0644\u0630\u064a \u062d\u0631\u0645 \u0639\u0644\u064a\u0643\u0645 \u0627\u0644\u0644\u0628\u0627\u0633 \u0627\u0644\u062d\u0633\u0646 \u0627\u0644\u0630\u064a \u062c\u0639\u0644\u0647 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0632\u064a\u0646\u0629 \u0644\u0643\u0645\u061f \u0648\u0645\u064e\u0646 \u0627\u0644\u0630\u064a \u062d\u0631\u0651\u064e\u0645 \u0639\u0644\u064a\u0643\u0645 \u0627\u0644\u062a\u0645\u062a\u0639 \u0628\u0627\u0644\u062d\u0644\u0627\u0644 \u0627\u0644\u0637\u064a\u0628 \u0645\u0646 \u0631\u0632\u0642 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u061f \u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0625\u0646\u0651\u064e \u0645\u0627 \u0623\u062d\u0644\u0647 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0645\u0644\u0627\u0628\u0633 \u0648\u0627\u0644\u0637\u064a\u0628\u0627\u062a \u0645\u0646 \u0627\u0644\u0645\u0637\u0627\u0639\u0645 \u0648\u0627\u0644\u0645\u0634\u0627\u0631\u0628 \u062d\u0642 \u0644\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0641\u064a \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627 \u064a\u0634\u0627\u0631\u0643\u0647\u0645 \u0641\u064a\u0647\u0627 \u063a\u064a\u0631\u0647\u0645\u060c \u062e\u0627\u0644\u0635\u0629 \u0644\u0647\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629. \u0645\u062b\u0644 \u0630\u0644\u0643 \u0627\u0644\u062a\u0641\u0635\u064a\u0644 \u064a\u0641\u0635\u0651\u0650\u0644 \u0627\u0644\u0644\u0647 \u0627\u0644\u0622\u064a\u0627\u062a \u0644\u0642\u0648\u0645 \u064a\u0639\u0644\u0645\u0648\u0646 \u0645\u0627 \u064a\u0628\u064a\u0651\u0650\u0646 \u0644\u0647\u0645\u060c \u0648\u064a\u0641\u0642\u0647\u0648\u0646 \u0645\u0627 \u064a\u0645\u064a\u0632 \u0644\u0647\u0645.","7:33":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0625\u0646\u0645\u0627 \u062d\u064e\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u0642\u0628\u0627\u0626\u062d \u0645\u0646 \u0627\u0644\u0623\u0639\u0645\u0627\u0644\u060c \u0645\u0627 \u0643\u0627\u0646 \u0645\u0646\u0647\u0627 \u0638\u0627\u0647\u0631\u064b\u0627\u060c \u0648\u0645\u0627 \u0643\u0627\u0646 \u062e\u0641\u064a\u0651\u064b\u0627\u060c \u0648\u062d\u064e\u0631\u0651\u064e\u0645 \u0627\u0644\u0645\u0639\u0627\u0635\u064a \u0643\u0644\u0647\u0627\u060c \u0648\u0645\u0650\u0646 \u0623\u0639\u0638\u0645\u0647\u0627 \u0627\u0644\u0627\u0639\u062a\u062f\u0627\u0621 \u0639\u0644\u0649 \u0627\u0644\u0646\u0627\u0633\u060c \u0641\u0625\u0646 \u0630\u0644\u0643 \u0645\u062c\u0627\u0646\u0628 \u0644\u0644\u062d\u0642\u060c \u0648\u062d\u0631\u0651\u064e\u0645 \u0623\u0646 \u062a\u0639\u0628\u062f\u0648\u0627 \u0645\u0639 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u063a\u064a\u0631\u0647 \u0645\u0645\u0627 \u0644\u0645 \u064a\u064f\u0646\u064e\u0632\u0651\u0650\u0644 \u0628\u0647 \u062f\u0644\u064a\u0644\u0627 \u0648\u0628\u0631\u0647\u0627\u0646\u064b\u0627\u060c \u0641\u0625\u0646\u0647 \u0644\u0627 \u062d\u062c\u0629 \u0644\u0641\u0627\u0639\u0644 \u0630\u0644\u0643\u060c \u0648\u062d\u0631\u0651\u064e\u0645 \u0623\u0646 \u062a\u0646\u0633\u0628\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0645\u0627 \u0644\u0645 \u064a\u0634\u0631\u0639\u0647 \u0627\u0641\u062a\u0631\u0627\u0621\u064b \u0648\u0643\u0630\u0628\u064b\u0627\u060c \u0643\u062f\u0639\u0648\u0649 \u0623\u0646 \u0644\u0644\u0647 \u0648\u0644\u062f\u064b\u0627\u060c \u0648\u062a\u062d\u0631\u064a\u0645 \u0628\u0639\u0636 \u0627\u0644\u062d\u0644\u0627\u0644 \u0645\u0646 \u0627\u0644\u0645\u0644\u0627\u0628\u0633 \u0648\u0627\u0644\u0645\u0622\u0643\u0644.","7:34":"\u0648\u0644\u0643\u0644 \u062c\u0645\u0627\u0639\u0629 \u0627\u062c\u062a\u0645\u0639\u062a \u0639\u0644\u0649 \u0627\u0644\u0643\u0641\u0631 \u0628\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u062a\u0643\u0630\u064a\u0628 \u0631\u0633\u0644\u0647 -\u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0627\u0644\u0633\u0644\u0627\u0645- \u0648\u0642\u062a \u0644\u062d\u0644\u0648\u0644 \u0627\u0644\u0639\u0642\u0648\u0628\u0629 \u0628\u0647\u0645\u060c \u0641\u0625\u0630\u0627 \u062c\u0627\u0621 \u0627\u0644\u0648\u0642\u062a \u0627\u0644\u0630\u064a \u0648\u0642\u0651\u064e\u062a\u0647 \u0627\u0644\u0644\u0647 \u0644\u0625\u0647\u0644\u0627\u0643\u0647\u0645 \u0644\u0627 \u064a\u062a\u0623\u062e\u0631\u0648\u0646 \u0639\u0646\u0647 \u0644\u062d\u0638\u0629\u060c \u0648\u0644\u0627 \u064a\u062a\u0642\u062f\u0645\u0648\u0646 \u0639\u0644\u064a\u0647.","7:35":"\u064a\u0627 \u0628\u0646\u064a \u0622\u062f\u0645 \u0625\u0630\u0627 \u062c\u0627\u0621\u0643\u0645 \u0631\u0633\u0644\u064a \u0645\u0646 \u0623\u0642\u0648\u0627\u0645\u0643\u0645\u060c \u064a\u062a\u0644\u0648\u0646 \u0639\u0644\u064a\u0643\u0645 \u0622\u064a\u0627\u062a \u0643\u062a\u0627\u0628\u064a\u060c \u0648\u064a\u0628\u064a\u0646\u0648\u0646 \u0644\u0643\u0645 \u0627\u0644\u0628\u0631\u0627\u0647\u064a\u0646 \u0639\u0644\u0649 \u0635\u062f\u0642 \u0645\u0627 \u062c\u0627\u0624\u0648\u0643\u0645 \u0628\u0647 \u0641\u0623\u0637\u064a\u0639\u0648\u0647\u0645\u060c \u0641\u0625\u0646\u0647 \u0645\u0646 \u0627\u062a\u0642\u0649 \u0633\u062e\u0637\u064a \u0648\u0623\u0635\u0644\u062d \u0639\u0645\u0644\u0647 \u0641\u0644\u0627 \u062e\u0648\u0641 \u0639\u0644\u064a\u0647\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0645\u0646 \u0639\u0642\u0627\u0628 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0644\u0627 \u0647\u0645 \u064a\u062d\u0632\u0646\u0648\u0646 \u0639\u0644\u0649 \u0645\u0627 \u0641\u0627\u062a\u0647\u0645 \u0645\u0646 \u062d\u0638\u0648\u0638 \u0627\u0644\u062f\u0646\u064a\u0627.","7:36":"\u0648\u0627\u0644\u0643\u0641\u0627\u0631 \u0627\u0644\u0630\u064a\u0646 \u0643\u0630\u0651\u064e\u0628\u0648\u0627 \u0628\u0627\u0644\u062f\u0644\u0627\u0626\u0644 \u0639\u0644\u0649 \u062a\u0648\u062d\u064a\u062f \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0633\u062a\u0639\u0644\u064e\u0648\u0627 \u0639\u0646 \u0627\u062a\u0628\u0627\u0639\u0647\u0627\u060c \u0623\u0648\u0644\u0626\u0643 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0646\u0627\u0631 \u0645\u0627\u0643\u062b\u064a\u0646 \u0641\u064a\u0647\u0627\u060c \u0644\u0627 \u064a\u062e\u0631\u062c\u0648\u0646 \u0645\u0646\u0647\u0627 \u0623\u0628\u062f\u064b\u0627.","7:37":"\u0644\u0627 \u0623\u062d\u062f \u0623\u0634\u062f \u0638\u0644\u0645\u064b\u0627 \u0645\u0645\u0646 \u0627\u062e\u062a\u0644\u0642 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0643\u0630\u0628\u060c \u0623\u0648 \u0643\u0630\u0651\u064e\u0628 \u0628\u0622\u064a\u0627\u062a\u0647 \u0627\u0644\u0645\u0646\u0632\u0644\u0629\u060c \u0623\u0648\u0644\u0626\u0643 \u064a\u0635\u0644 \u0625\u0644\u064a\u0647\u0645 \u062d\u0638\u0651\u064f\u0647\u0645 \u0645\u0646 \u0627\u0644\u0639\u0630\u0627\u0628 \u0645\u0645\u0627 \u0643\u062a\u0628 \u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u0645\u062d\u0641\u0648\u0638\u060c \u062d\u062a\u0649 \u0625\u0630\u0627 \u062c\u0627\u0621\u0647\u0645 \u0645\u0644\u0643 \u0627\u0644\u0645\u0648\u062a \u0648\u0623\u0639\u0648\u0627\u0646\u0647 \u064a\u0642\u0628\u0636\u0648\u0646 \u0623\u0631\u0648\u0627\u062d\u0647\u0645 \u0642\u0627\u0644\u0648\u0627 \u0644\u0647\u0645: \u0623\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0643\u0646\u062a\u0645 \u062a\u0639\u0628\u062f\u0648\u0646\u0647\u0645 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0634\u0631\u0643\u0627\u0621 \u0648\u0627\u0644\u0623\u0648\u0644\u064a\u0627\u0621 \u0648\u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u0644\u064a\u062e\u0644\u0651\u0650\u0635\u0648\u0643\u0645 \u0645\u0645\u0627 \u0623\u0646\u062a\u0645 \u0641\u064a\u0647\u061f \u0642\u0627\u0644\u0648\u0627: \u0630\u0647\u0628\u0648\u0627 \u0639\u0646\u0627\u060c \u0648\u0627\u0639\u062a\u0631\u0641\u0648\u0627 \u0639\u0644\u0649 \u0623\u0646\u0641\u0633\u0647\u0645 \u062d\u064a\u0646\u0626\u0630 \u0623\u0646\u0647\u0645 \u0643\u0627\u0646\u0648\u0627 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u062c\u0627\u062d\u062f\u064a\u0646 \u0645\u0643\u0630\u0628\u064a\u0646 \u0648\u062d\u062f\u0627\u0646\u064a\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649.","7:38":"\u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 -\u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0627\u0644\u0645\u0641\u062a\u0631\u064a\u0646-: \u0627\u062f\u062e\u0644\u0648\u0627 \u0627\u0644\u0646\u0627\u0631 \u0641\u064a \u062c\u0645\u0644\u0629 \u062c\u0645\u0627\u0639\u0627\u062a \u0645\u0646 \u0623\u0645\u062b\u0627\u0644\u0643\u0645 \u0641\u064a \u0627\u0644\u0643\u0641\u0631\u060c \u0642\u062f \u0633\u0644\u0641\u062a \u0645\u0646 \u0642\u0628\u0644\u0643\u0645 \u0645\u0646 \u0627\u0644\u062c\u0646 \u0648\u0627\u0644\u0625\u0646\u0633\u060c \u0643\u0644\u0645\u0627 \u062f\u062e\u0644\u062a \u0627\u0644\u0646\u0627\u0631\u064e \u062c\u0645\u0627\u0639\u0629\u064c \u0645\u0646 \u0623\u0647\u0644 \u0645\u0644\u0629 \u0644\u0639\u0646\u062a \u0646\u0638\u064a\u0631\u062a\u0647\u0627 \u0627\u0644\u062a\u064a \u0636\u0644\u0651\u064e\u062a\u0652 \u0628\u0627\u0644\u0627\u0642\u062a\u062f\u0627\u0621 \u0628\u0647\u0627\u060c \u062d\u062a\u0649 \u0625\u0630\u0627 \u062a\u0644\u0627\u062d\u0642 \u0641\u064a \u0627\u0644\u0646\u0627\u0631 \u0627\u0644\u0623\u0648\u0644\u0648\u0646 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0645\u0644\u0644 \u0627\u0644\u0643\u0627\u0641\u0631\u0629 \u0648\u0627\u0644\u0622\u062e\u0631\u0648\u0646 \u0645\u0646\u0647\u0645 \u062c\u0645\u064a\u0639\u064b\u0627\u060c \u0642\u0627\u0644 \u0627\u0644\u0622\u062e\u0631\u0648\u0646 \u0627\u0644\u0645\u062a\u0628\u0639\u0648\u0646 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0644\u0642\u0627\u062f\u062a\u0647\u0645: \u0631\u0628\u0646\u0627 \u0647\u0624\u0644\u0627\u0621 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0623\u0636\u0644\u0648\u0646\u0627 \u0639\u0646 \u0627\u0644\u062d\u0642\u060c \u0641\u0622\u062a\u0647\u0645 \u0639\u0630\u0627\u0628\u064b\u0627 \u0645\u0636\u0627\u0639\u0641\u0627 \u0645\u0646 \u0627\u0644\u0646\u0627\u0631\u060c \u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \u0644\u0643\u0644 \u0636\u0639\u0641\u060c \u0623\u064a: \u0644\u0643\u0644 \u0645\u0646\u0643\u0645 \u0648\u0645\u0646\u0647\u0645 \u0639\u0630\u0627\u0628 \u0645\u0636\u0627\u0639\u0641 \u0645\u0646 \u0627\u0644\u0646\u0627\u0631\u060c \u0648\u0644\u0643\u0646 \u0644\u0627 \u062a\u062f\u0631\u0643\u0648\u0646 \u0623\u064a\u0647\u0627 \u0627\u0644\u0623\u062a\u0628\u0627\u0639 \u0645\u0627 \u0644\u0643\u0644 \u0641\u0631\u064a\u0642 \u0645\u0646\u0643\u0645 \u0645\u0646 \u0627\u0644\u0639\u0630\u0627\u0628 \u0648\u0627\u0644\u0622\u0644\u0627\u0645.","7:39":"\u0648\u0642\u0627\u0644 \u0627\u0644\u0645\u062a\u0628\u0648\u0639\u0648\u0646 \u0645\u0646 \u0627\u0644\u0631\u0624\u0633\u0627\u0621 \u0648\u063a\u064a\u0631\u0647\u0645 \u0644\u0623\u062a\u0628\u0627\u0639\u0647\u0645: \u0646\u062d\u0646 \u0648\u0623\u0646\u062a\u0645 \u0645\u062a\u0633\u0627\u0648\u0648\u0646 \u0641\u064a \u0627\u0644\u063a\u064a\u0651\u0650 \u0648\u0627\u0644\u0636\u0644\u0627\u0644\u060c \u0648\u0641\u064a \u0641\u0650\u0639\u0652\u0644\u0650 \u0623\u0633\u0628\u0627\u0628 \u0627\u0644\u0639\u0630\u0627\u0628 \u0641\u0644\u0627 \u0641\u064e\u0636\u0652\u0644\u064e \u0644\u0643\u0645 \u0639\u0644\u064a\u0646\u0627\u060c \u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0647\u0645 \u062c\u0645\u064a\u0639\u064b\u0627: \u0641\u0630\u0648\u0642\u0648\u0627 \u0627\u0644\u0639\u0630\u0627\u0628 \u0623\u064a \u0639\u0630\u0627\u0628 \u062c\u0647\u0646\u0645; \u0628\u0633\u0628\u0628 \u0645\u0627 \u0643\u0633\u0628\u062a\u0645 \u0645\u0646 \u0627\u0644\u0645\u0639\u0627\u0635\u064a.","7:40":"\u0625\u0646 \u0627\u0644\u0643\u0641\u0627\u0631 \u0627\u0644\u0630\u064a\u0646 \u0644\u0645 \u064a\u0635\u062f\u0651\u0650\u0642\u0648\u0627 \u0628\u062d\u062c\u062c\u0646\u0627 \u0648\u0622\u064a\u0627\u062a\u0646\u0627 \u0627\u0644\u062f\u0627\u0644\u0629 \u0639\u0644\u0649 \u0648\u062d\u062f\u0627\u0646\u064a\u062a\u0646\u0627\u060c \u0648\u0644\u0645 \u064a\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0646\u0627 \u062a\u0643\u0628\u0631\u064b\u0627 \u0648\u0627\u0633\u062a\u0639\u0644\u0627\u0621\u064b\u060c \u0644\u0627 \u062a\u064f\u0641\u062a\u0651\u064e\u062d \u0644\u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u062d\u064a\u0627\u0629 \u0648\u0644\u0627 \u0644\u0623\u0631\u0648\u0627\u062d\u0647\u0645 \u0639\u0646\u062f \u0627\u0644\u0645\u0645\u0627\u062a \u0623\u0628\u0648\u0627\u0628 \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u0648\u0644\u0627 \u064a\u0645\u0643\u0646 \u0623\u0646 \u064a\u062f\u062e\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0641\u0627\u0631 \u0627\u0644\u062c\u0646\u0629 \u0625\u0644\u0627 \u0625\u0630\u0627 \u062f\u062e\u0644 \u0627\u0644\u062c\u0645\u0644 \u0641\u064a \u062b\u0642\u0628 \u0627\u0644\u0625\u0628\u0631\u0629\u060c \u0648\u0647\u0630\u0627 \u0645\u0633\u062a\u062d\u064a\u0644. \u0648\u0645\u062b\u0644 \u0630\u0644\u0643 \u0627\u0644\u062c\u0632\u0627\u0621 \u0646\u062c\u0632\u064a \u0627\u0644\u0630\u064a\u0646 \u0643\u062b\u0631 \u0625\u062c\u0631\u0627\u0645\u0647\u0645\u060c \u0648\u0627\u0634\u062a\u062f\u0651\u064e \u0637\u063a\u064a\u0627\u0646\u0647\u0645.","7:41":"\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0641\u0627\u0631 \u0645\u062e\u0644\u062f\u0648\u0646 \u0641\u064a \u0627\u0644\u0646\u0627\u0631\u060c \u0644\u0647\u0645 \u0645\u0650\u0646 \u062c\u0647\u0646\u0645 \u0641\u0631\u0627\u0634 \u0645\u0650\u0646 \u062a\u062d\u062a\u0647\u0645\u060c \u0648\u0645\u0646 \u0641\u0648\u0642\u0647\u0645 \u0623\u063a\u0637\u064a\u0629 \u062a\u063a\u0634\u0627\u0647\u0645. \u0648\u0628\u0645\u062b\u0644 \u0647\u0630\u0627 \u0627\u0644\u0639\u0642\u0627\u0628 \u0627\u0644\u0634\u062f\u064a\u062f \u064a\u0639\u0627\u0642\u0628 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u062a\u062c\u0627\u0648\u0632\u0648\u0627 \u062d\u062f\u0648\u062f\u0647 \u0641\u0643\u0641\u0631\u0648\u0627 \u0628\u0647 \u0648\u0639\u0635\u064e\u0648\u0652\u0647.","7:42":"\u0648\u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u0629 \u0641\u064a \u062d\u062f\u0648\u062f \u0637\u0627\u0642\u0627\u062a\u0647\u0645 -\u0644\u0627 \u064a\u0643\u0644\u0641 \u0627\u0644\u0644\u0647 \u0646\u0641\u0633\u064b\u0627 \u0645\u0646 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0625\u0644\u0627 \u0645\u0627 \u062a\u0637\u064a\u0642- \u0623\u0648\u0644\u0626\u0643 \u0623\u0647\u0644 \u0627\u0644\u062c\u0646\u0629\u060c \u0647\u0645 \u0641\u064a\u0647\u0627 \u0645\u0627\u0643\u062b\u0648\u0646 \u0623\u0628\u062f\u064b\u0627 \u0644\u0627 \u064a\u062e\u0631\u062c\u0648\u0646 \u0645\u0646\u0647\u0627.","7:43":"\u0648\u0623\u0630\u0647\u0628 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0645\u0627 \u0641\u064a \u0635\u062f\u0648\u0631 \u0623\u0647\u0644 \u0627\u0644\u062c\u0646\u0629 \u0645\u0646 \u062d\u0642\u062f \u0648\u0636\u063a\u0627\u0626\u0646\u060c \u0648\u0645\u0646 \u0643\u0645\u0627\u0644 \u0646\u0639\u064a\u0645\u0647\u0645 \u0623\u0646 \u0627\u0644\u0623\u0646\u0647\u0627\u0631 \u062a\u062c\u0631\u064a \u0641\u064a \u0627\u0644\u062c\u0646\u0629 \u0645\u0646 \u062a\u062d\u062a \u063a\u0631\u0641\u0647\u0645 \u0648\u0645\u0646\u0627\u0632\u0644\u0647\u0645. \u0648\u0642\u0627\u0644 \u0623\u0647\u0644 \u0627\u0644\u062c\u0646\u0629 \u062d\u064a\u0646\u0645\u0627 \u062f\u062e\u0644\u0648\u0647\u0627: \u0627\u0644\u062d\u0645\u062f \u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u0648\u0641\u0651\u064e\u0642\u0646\u0627 \u0644\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d \u0627\u0644\u0630\u064a \u0623\u0643\u0633\u0628\u0646\u0627 \u0645\u0627 \u0646\u062d\u0646 \u0641\u064a\u0647 \u0645\u0646 \u0627\u0644\u0646\u0639\u064a\u0645\u060c \u0648\u0645\u0627 \u0643\u0646\u0627 \u0644\u0646\u0648\u0641\u0651\u064e\u0642 \u0625\u0644\u0649 \u0633\u0644\u0648\u0643 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645 \u0644\u0648\u0644\u0627 \u0623\u064e\u0646\u0652 \u0647\u062f\u0627\u0646\u0627 \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0644\u0633\u0644\u0648\u0643 \u0647\u0630\u0627 \u0627\u0644\u0637\u0631\u064a\u0642\u060c \u0648\u0648\u0641\u0651\u064e\u0642\u0646\u0627 \u0644\u0644\u062b\u0628\u0627\u062a \u0639\u0644\u064a\u0647\u060c \u0644\u0642\u062f \u062c\u0627\u0621\u062a \u0631\u0633\u0644 \u0631\u0628\u0646\u0627 \u0628\u0627\u0644\u062d\u0642 \u0645\u0646 \u0627\u0644\u0625\u062e\u0628\u0627\u0631 \u0628\u0648\u0639\u062f \u0623\u0647\u0644 \u0637\u0627\u0639\u062a\u0647 \u0648\u0648\u0639\u064a\u062f \u0623\u0647\u0644 \u0645\u0639\u0635\u064a\u062a\u0647\u060c \u0648\u0646\u064f\u0648\u062f\u0648\u0627 \u062a\u0647\u0646\u0626\u0629 \u0644\u0647\u0645 \u0648\u0625\u0643\u0631\u0627\u0645\u064b\u0627: \u0623\u0646 \u062a\u0644\u0643\u0645 \u0627\u0644\u062c\u0646\u0629 \u0623\u0648\u0631\u062b\u0643\u0645 \u0627\u0644\u0644\u0647 \u0625\u064a\u0627\u0647\u0627 \u0628\u0631\u062d\u0645\u062a\u0647\u060c \u0648\u0628\u0645\u0627 \u0642\u062f\u0651\u064e\u0645\u062a\u0645\u0648\u0647 \u0645\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d.","7:44":"\u0648\u0646\u0627\u062f\u0649 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u062c\u0646\u0629 -\u0628\u0639\u062f \u062f\u062e\u0648\u0644\u0647\u0645 \u0641\u064a\u0647\u0627- \u0623\u0647\u0644\u064e \u0627\u0644\u0646\u0627\u0631 \u0642\u0627\u0626\u0644\u064a\u0646 \u0644\u0647\u0645: \u0625\u0646\u0627 \u0642\u062f \u0648\u062c\u062f\u0646\u0627 \u0645\u0627 \u0648\u0639\u062f\u0646\u0627 \u0631\u0628\u0646\u0627 \u0639\u0644\u0649 \u0623\u0644\u0633\u0646\u0629 \u0631\u0633\u0644\u0647 \u062d\u0642\u064b\u0627 \u0645\u0646 \u0625\u062b\u0627\u0628\u0629 \u0623\u0647\u0644 \u0637\u0627\u0639\u062a\u0647\u060c \u0641\u0647\u0644 \u0648\u062c\u062f\u062a\u0645 \u0645\u0627 \u0648\u0639\u062f\u0643\u0645 \u0631\u0628\u0643\u0645 \u0639\u0644\u0649 \u0623\u0644\u0633\u0646\u0629 \u0631\u0633\u0644\u0647 \u062d\u0642\u064b\u0627 \u0645\u0646 \u0639\u0642\u0627\u0628 \u0623\u0647\u0644 \u0645\u0639\u0635\u064a\u062a\u0647\u061f \u0641\u0623\u062c\u0627\u0628\u0647\u0645 \u0623\u0647\u0644 \u0627\u0644\u0646\u0627\u0631 \u0642\u0627\u0626\u0644\u064a\u0646: \u0646\u0639\u0645 \u0642\u062f \u0648\u062c\u062f\u0646\u0627 \u0645\u0627 \u0648\u0639\u062f\u0646\u0627 \u0631\u0628\u0646\u0627 \u062d\u0642\u064b\u0627. \u0641\u0623\u0630\u0651\u064e\u0646 \u0645\u0624\u0630\u0646 \u0628\u064a\u0646 \u0623\u0647\u0644 \u0627\u0644\u062c\u0646\u0629 \u0648\u0623\u0647\u0644 \u0627\u0644\u0646\u0627\u0631: \u0623\u0646\u0652 \u0644\u0639\u0646\u0629 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u062a\u062c\u0627\u0648\u0632\u0648\u0627 \u062d\u062f\u0648\u062f \u0627\u0644\u0644\u0647\u060c \u0648\u0643\u0641\u0631\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0644\u0647.","7:45":"\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0627\u0641\u0631\u0648\u0646 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0643\u0627\u0646\u0648\u0627 \u064a\u064f\u0639\u0652\u0631\u0650\u0636\u0648\u0646 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645\u060c \u0648\u064a\u0645\u0646\u0639\u0648\u0646 \u0627\u0644\u0646\u0627\u0633 \u0645\u0646 \u0633\u0644\u0648\u0643\u0647\u060c \u0648\u064a\u0637\u0644\u0628\u0648\u0646 \u0623\u0646 \u062a\u0643\u0648\u0646 \u0627\u0644\u0633\u0628\u064a\u0644 \u0645\u0639\u0648\u062c\u0629 \u062d\u062a\u0649 \u0644\u0627 \u064a\u062a\u0628\u064a\u0646\u0647\u0627 \u0623\u062d\u062f\u060c \u0648\u0647\u0645 \u0628\u0627\u0644\u0622\u062e\u0631\u0629 -\u0648\u0645\u0627 \u0641\u064a\u0647\u0627- \u062c\u0627\u062d\u062f\u0648\u0646.","7:46":"\u0648\u0628\u064a\u0646 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u062c\u0646\u0629 \u0648\u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0646\u0627\u0631 \u062d\u0627\u062c\u0632 \u0639\u0638\u064a\u0645 \u064a\u0642\u0627\u0644 \u0644\u0647 \u0627\u0644\u0623\u0639\u0631\u0627\u0641\u060c \u0648\u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062d\u0627\u062c\u0632 \u0631\u062c\u0627\u0644 \u064a\u0639\u0631\u0641\u0648\u0646 \u0623\u0647\u0644 \u0627\u0644\u062c\u0646\u0629 \u0648\u0623\u0647\u0644 \u0627\u0644\u0646\u0627\u0631 \u0628\u0639\u0644\u0627\u0645\u0627\u062a\u0647\u0645\u060c \u0643\u0628\u064a\u0627\u0636 \u0648\u062c\u0648\u0647 \u0623\u0647\u0644 \u0627\u0644\u062c\u0646\u0629\u060c \u0648\u0633\u0648\u0627\u062f \u0648\u062c\u0648\u0647 \u0623\u0647\u0644 \u0627\u0644\u0646\u0627\u0631\u060c \u0648\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0631\u062c\u0627\u0644 \u0642\u0648\u0645 \u0627\u0633\u062a\u0648\u062a \u062d\u0633\u0646\u0627\u062a\u0647\u0645 \u0648\u0633\u064a\u0626\u0627\u062a\u0647\u0645 \u064a\u0631\u062c\u0648\u0646 \u0631\u062d\u0645\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649. \u0648\u0646\u0627\u062f\u0649 \u0631\u062c\u0627\u0644 \u0627\u0644\u0623\u0639\u0631\u0627\u0641 \u0623\u0647\u0644 \u0627\u0644\u062c\u0646\u0629 \u0628\u0627\u0644\u062a\u062d\u064a\u0629 \u0642\u0627\u0626\u0644\u064a\u0646 \u0644\u0647\u0645: \u0633\u0644\u0627\u0645 \u0639\u0644\u064a\u0643\u0645\u060c \u0648\u0623\u0647\u0644 \u0627\u0644\u0623\u0639\u0631\u0627\u0641 \u0644\u0645 \u064a\u062f\u062e\u0644\u0648\u0627 \u0627\u0644\u062c\u0646\u0629 \u0628\u0639\u062f\u060c \u0648\u0647\u0645 \u064a\u0631\u062c\u0648\u0646 \u062f\u062e\u0648\u0644\u0647\u0627.","7:47":"\u0648\u0625\u0630\u0627 \u062d\u064f\u0648\u0651\u0650\u0644\u064e\u062a\u0652 \u0623\u0628\u0635\u0627\u0631 \u0631\u062c\u0627\u0644 \u0627\u0644\u0623\u0639\u0631\u0627\u0641 \u062c\u0647\u0629 \u0623\u0647\u0644 \u0627\u0644\u0646\u0627\u0631 \u0642\u0627\u0644\u0648\u0627: \u0631\u0628\u0646\u0627 \u0644\u0627 \u062a\u064f\u0635\u064a\u0651\u0650\u0631\u0646\u0627 \u0645\u0639 \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0628\u0634\u0631\u0643\u0647\u0645 \u0648\u0643\u0641\u0631\u0647\u0645.","7:48":"\u0648\u0646\u0627\u062f\u0649 \u0623\u0647\u0644 \u0627\u0644\u0623\u0639\u0631\u0627\u0641 \u0631\u062c\u0627\u0644\u0627 \u0645\u0646 \u0642\u0627\u062f\u0629 \u0627\u0644\u0643\u0641\u0627\u0631 \u0627\u0644\u0630\u064a\u0646 \u0641\u064a \u0627\u0644\u0646\u0627\u0631\u060c \u064a\u0639\u0631\u0641\u0648\u0646\u0647\u0645 \u0628\u0639\u0644\u0627\u0645\u0627\u062a \u062e\u0627\u0635\u0629 \u062a\u0645\u064a\u0632\u0647\u0645\u060c \u0642\u0627\u0644\u0648\u0627 \u0644\u0647\u0645: \u0645\u0627 \u0646\u0641\u0639\u0643\u0645 \u0645\u0627 \u0643\u0646\u062a\u0645 \u062a\u062c\u0645\u0639\u0648\u0646 \u0645\u0646 \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0648\u0627\u0644\u0631\u062c\u0627\u0644 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0645\u0627 \u0646\u0641\u0639\u0643\u0645 \u0627\u0633\u062a\u0639\u0644\u0627\u0624\u0643\u0645 \u0639\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0642\u064e\u0628\u0648\u0644 \u0627\u0644\u062d\u0642.","7:49":"\u0623\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0636\u0639\u0641\u0627\u0621 \u0648\u0627\u0644\u0641\u0642\u0631\u0627\u0621 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u062c\u0646\u0629 \u0627\u0644\u0630\u064a\u0646 \u0623\u0642\u0633\u0645\u062a\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0634\u0645\u0644\u0647\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0628\u0631\u062d\u0645\u0629\u060c \u0648\u0644\u0646 \u064a\u062f\u062e\u0644\u0647\u0645 \u0627\u0644\u062c\u0646\u0629\u061f \u0627\u062f\u062e\u0644\u0648\u0627 \u0627\u0644\u062c\u0646\u0629 \u064a\u0627 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0623\u0639\u0631\u0627\u0641 \u0641\u0642\u062f \u063a\u064f\u0641\u0650\u0631\u064e \u0644\u0643\u0645\u060c \u0644\u0627 \u062e\u0648\u0641 \u0639\u0644\u064a\u0643\u0645 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u0623\u0646\u062a\u0645 \u062a\u062d\u0632\u0646\u0648\u0646 \u0639\u0644\u0649 \u0645\u0627 \u0641\u0627\u062a\u0643\u0645 \u0645\u0646 \u062d\u0638\u0648\u0638 \u0627\u0644\u062f\u0646\u064a\u0627.","7:50":"\u0648\u0627\u0633\u062a\u063a\u0627\u062b \u0623\u0647\u0644 \u0627\u0644\u0646\u0627\u0631 \u0628\u0623\u0647\u0644 \u0627\u0644\u062c\u0646\u0629 \u0637\u0627\u0644\u0628\u064a\u0646 \u0645\u0646\u0647\u0645 \u0623\u0646 \u064a\u064f\u0641\u064a\u0636\u0648\u0627 \u0639\u0644\u064a\u0647\u0645 \u0645\u0646 \u0627\u0644\u0645\u0627\u0621\u060c \u0623\u0648 \u0645\u0645\u0627 \u0631\u0632\u0642\u0647\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0637\u0639\u0627\u0645\u060c \u0641\u0623\u062c\u0627\u0628\u0648\u0647\u0645 \u0628\u0623\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0642\u062f \u062d\u064e\u0631\u0651\u064e\u0645 \u0627\u0644\u0634\u0631\u0627\u0628 \u0648\u0627\u0644\u0637\u0639\u0627\u0645 \u0639\u0644\u0649 \u0627\u0644\u0630\u064a\u0646 \u062c\u062d\u062f\u0648\u0627 \u062a\u0648\u062d\u064a\u062f\u0647\u060c \u0648\u0643\u0630\u0651\u064e\u0628\u0648\u0627 \u0631\u0633\u0644\u0647.","7:51":"\u0627\u0644\u0630\u064a\u0646 \u062d\u064e\u0631\u064e\u0645\u0647\u0645 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0645\u0646 \u0646\u0639\u064a\u0645 \u0627\u0644\u0622\u062e\u0631\u0629 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u062c\u0639\u0644\u0648\u0627 \u0627\u0644\u062f\u064a\u0646 \u0627\u0644\u0630\u064a \u0623\u0645\u0631\u0647\u0645 \u0627\u0644\u0644\u0647 \u0628\u0627\u062a\u0628\u0627\u0639\u0647 \u0628\u0627\u0637\u0644\u0627 \u0648\u0644\u0647\u0648\u064b\u0627\u060c \u0648\u062e\u062f\u0639\u062a\u0647\u0645 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0634\u063a\u0644\u0648\u0627 \u0628\u0632\u062e\u0627\u0631\u0641\u0647\u0627 \u0639\u0646 \u0627\u0644\u0639\u0645\u0644 \u0644\u0644\u0622\u062e\u0631\u0629\u060c \u0641\u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u064a\u0646\u0633\u0627\u0647\u0645 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u064a\u062a\u0631\u0643\u0647\u0645 \u0641\u064a \u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0645\u0648\u062c\u0639\u060c \u0643\u0645\u0627 \u062a\u0631\u0643\u0648\u0627 \u0627\u0644\u0639\u0645\u0644 \u0644\u0644\u0642\u0627\u0621 \u064a\u0648\u0645\u0647\u0645 \u0647\u0630\u0627\u060c \u0648\u0644\u0643\u0648\u0646\u0647\u0645 \u0628\u0623\u062f\u0644\u0629 \u0627\u0644\u0644\u0647 \u0648\u0628\u0631\u0627\u0647\u064a\u0646\u0647 \u064a\u0646\u0643\u0631\u0648\u0646 \u0645\u0639 \u0639\u0644\u0645\u0647\u0645 \u0628\u0623\u0646\u0647\u0627 \u062d\u0642.","7:52":"\u0648\u0644\u0642\u062f \u062c\u0626\u0646\u0627 \u0627\u0644\u0643\u0641\u0627\u0631 \u0628\u0642\u0631\u0622\u0646 \u0623\u0646\u0632\u0644\u0646\u0627\u0647 \u0639\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0628\u064a\u0651\u064e\u0646\u0651\u064e\u0627\u0647 \u0645\u0634\u062a\u0645\u0644\u0627 \u0639\u0644\u0649 \u0639\u0644\u0645 \u0639\u0638\u064a\u0645\u060c \u0647\u0627\u062f\u064a\u064b\u0627 \u0645\u0646 \u0627\u0644\u0636\u0644\u0627\u0644\u0629 \u0625\u0644\u0649 \u0627\u0644\u0631\u0634\u062f \u0648\u0631\u062d\u0645\u0629 \u0644\u0642\u0648\u0645 \u064a\u0624\u0645\u0646\u0648\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u064a\u0639\u0645\u0644\u0648\u0646 \u0628\u0634\u0631\u0639\u0647. \u0648\u062e\u0635\u0651\u064e\u0647\u0645 \u062f\u0648\u0646 \u063a\u064a\u0631\u0647\u0645; \u0644\u0623\u0646\u0647\u0645 \u0647\u0645 \u0627\u0644\u0645\u0646\u062a\u0641\u0639\u0648\u0646 \u0628\u0647.","7:53":"\u0647\u0644 \u064a\u0646\u062a\u0638\u0631 \u0627\u0644\u0643\u0641\u0627\u0631 \u0625\u0644\u0627 \u0645\u0627 \u0648\u064f\u0639\u0650\u062f\u0648\u0627 \u0628\u0647 \u0641\u064a \u0627\u0644\u0642\u0631\u0622\u0646 \u0645\u0646 \u0627\u0644\u0639\u0642\u0627\u0628 \u0627\u0644\u0630\u064a \u064a\u0624\u0648\u0644 \u0625\u0644\u064a\u0647 \u0623\u0645\u0631\u0647\u0645\u061f \u064a\u0648\u0645 \u064a\u0623\u062a\u064a \u0645\u0627 \u064a\u0624\u0648\u0644 \u0625\u0644\u064a\u0647 \u0627\u0644\u0623\u0645\u0631 \u0645\u0646 \u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0627\u0644\u062b\u0648\u0627\u0628 \u0648\u0627\u0644\u0639\u0642\u0627\u0628 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u064a\u0642\u0648\u0644 \u0627\u0644\u0643\u0641\u0627\u0631 \u0627\u0644\u0630\u064a\u0646 \u062a\u0631\u0643\u0648\u0627 \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0648\u0643\u0641\u0631\u0648\u0627 \u0628\u0647 \u0641\u064a \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627: \u0642\u062f \u062a\u0628\u064a\u0651\u064e\u0646 \u0644\u0646\u0627 \u0627\u0644\u0622\u0646 \u0623\u0646\u0651\u064e \u0631\u0633\u0644 \u0631\u0628\u0646\u0627 \u0642\u062f \u062c\u0627\u0624\u0648\u0627 \u0628\u0627\u0644\u062d\u0642\u060c \u0648\u0646\u0635\u062d\u0648\u0627 \u0644\u0646\u0627\u060c \u0641\u0647\u0644 \u0644\u0646\u0627 \u0645\u0646 \u0623\u0635\u062f\u0642\u0627\u0621 \u0648\u0634\u0641\u0639\u0627\u0621\u060c \u0641\u064a\u0634\u0641\u0639\u0648\u0627 \u0644\u0646\u0627 \u0639\u0646\u062f \u0631\u0628\u0646\u0627\u060c \u0623\u0648 \u0646\u0639\u0627\u062f \u0625\u0644\u0649 \u0627\u0644\u062f\u0646\u064a\u0627 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0641\u0646\u0639\u0645\u0644 \u0641\u064a\u0647\u0627 \u0628\u0645\u0627 \u064a\u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0627\u061f \u0642\u062f \u062e\u0633\u0631\u0648\u0627 \u0623\u0646\u0641\u0633\u0647\u0645 \u0628\u062f\u062e\u0648\u0644\u0647\u0645 \u0627\u0644\u0646\u0627\u0631 \u0648\u062e\u0644\u0648\u062f\u0647\u0645 \u0641\u064a\u0647\u0627\u060c \u0648\u0630\u0647\u0628 \u0639\u0646\u0647\u0645 \u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u064a\u0639\u0628\u062f\u0648\u0646\u0647 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u064a\u0641\u062a\u0631\u0648\u0646\u0647 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0645\u0645\u0627 \u064a\u064e\u0639\u0650\u062f\u064f\u0647\u0645 \u0628\u0647 \u0627\u0644\u0634\u064a\u0637\u0627\u0646.","7:54":"\u0625\u0646 \u0631\u0628\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633- \u0647\u0648 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u0623\u0648\u062c\u062f \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0645\u0646 \u0627\u0644\u0639\u062f\u0645 \u0641\u064a \u0633\u062a\u0629 \u0623\u064a\u0627\u0645\u060c \u062b\u0645 \u0627\u0633\u062a\u0648\u0649 -\u0633\u0628\u062d\u0627\u0646\u0647- \u0639\u0644\u0649 \u0627\u0644\u0639\u0631\u0634 -\u0623\u064a \u0639\u0644\u0627 \u0648\u0627\u0631\u062a\u0641\u0639- \u0627\u0633\u062a\u0648\u0627\u0621\u064b \u064a\u0644\u064a\u0642 \u0628\u062c\u0644\u0627\u0644\u0647 \u0648\u0639\u0638\u0645\u062a\u0647\u060c \u064a\u064f\u062f\u062e\u0644 \u0633\u0628\u062d\u0627\u0646\u0647 \u0627\u0644\u0644\u064a\u0644 \u0639\u0644\u0649 \u0627\u0644\u0646\u0647\u0627\u0631\u060c \u0641\u064a\u0644\u0628\u0633\u0647 \u0625\u064a\u0627\u0647 \u062d\u062a\u0649 \u064a\u0630\u0647\u0628 \u0646\u0648\u0631\u0647\u060c \u0648\u064a\u064f\u062f\u062e\u0644 \u0627\u0644\u0646\u0647\u0627\u0631 \u0639\u0644\u0649 \u0627\u0644\u0644\u064a\u0644 \u0641\u064a\u0630\u0647\u0628 \u0638\u0644\u0627\u0645\u0647\u060c \u0648\u0643\u0644 \u0648\u0627\u062d\u062f \u0645\u0646\u0647\u0645\u0627 \u064a\u0637\u0644\u0628 \u0627\u0644\u0622\u062e\u0631 \u0633\u0631\u064a\u0639\u064b\u0627 \u062f\u0627\u0626\u0645\u064b\u0627\u060c \u0648\u0647\u0648 -\u0633\u0628\u062d\u0627\u0646\u0647- \u0627\u0644\u0630\u064a \u062e\u0644\u0642 \u0627\u0644\u0634\u0645\u0633 \u0648\u0627\u0644\u0642\u0645\u0631 \u0648\u0627\u0644\u0646\u062c\u0648\u0645 \u0645\u0630\u0644\u0644\u0627\u062a \u0644\u0647 \u064a\u0633\u062e\u0631\u0647\u0646 -\u0633\u0628\u062d\u0627\u0646\u0647- \u0643\u0645\u0627 \u064a\u0634\u0627\u0621\u060c \u0648\u0647\u0646\u0651\u064e \u0645\u0646 \u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0627\u0644\u0639\u0638\u064a\u0645\u0629. \u0623\u0644\u0627 \u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u062e\u0644\u0642 \u0643\u0644\u0647 \u0648\u0644\u0647 \u0627\u0644\u0623\u0645\u0631 \u0643\u0644\u0647\u060c \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u062a\u0639\u0627\u0638\u0645 \u0648\u062a\u0646\u0632\u0651\u064e\u0647 \u0639\u0646 \u0643\u0644 \u0646\u0642\u0635\u060c \u0631\u0628 \u0627\u0644\u062e\u0644\u0642 \u0623\u062c\u0645\u0639\u064a\u0646.","7:55":"\u0627\u062f\u0639\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0631\u0628\u0643\u0645 \u0645\u062a\u0630\u0644\u0644\u064a\u0646 \u0644\u0647 \u062e\u0641\u064a\u0629 \u0648\u0633\u0631\u0651\u064b\u0627\u060c \u0648\u0644\u064a\u0643\u0646 \u0627\u0644\u062f\u0639\u0627\u0621 \u0628\u062e\u0634\u0648\u0639 \u0648\u0628\u064f\u0639\u0652\u062f\u064d \u0639\u0646 \u0627\u0644\u0631\u064a\u0627\u0621. \u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0627 \u064a\u062d\u0628 \u0627\u0644\u0645\u062a\u062c\u0627\u0648\u0632\u064a\u0646 \u062d\u062f\u0648\u062f \u0634\u0631\u0639\u0647\u060c \u0648\u0623\u0639\u0638\u0645 \u0627\u0644\u062a\u062c\u0627\u0648\u0632 \u0627\u0644\u0634\u0631\u0643 \u0628\u0627\u0644\u0644\u0647\u060c \u0643\u062f\u0639\u0627\u0621 \u063a\u064a\u0631 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0623\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0648\u062b\u0627\u0646\u060c \u0648\u0646\u062d\u0648 \u0630\u0644\u0643.","7:56":"\u0648\u0644\u0627 \u062a\u064f\u0641\u0652\u0633\u062f\u0648\u0627 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0628\u0623\u064a\u0651\u0650 \u0646\u0648\u0639 \u0645\u0646 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0641\u0633\u0627\u062f\u060c \u0628\u0639\u062f \u0625\u0635\u0644\u0627\u062d \u0627\u0644\u0644\u0647 \u0625\u064a\u0627\u0647\u0627 \u0628\u0628\u0639\u062b\u0629 \u0627\u0644\u0631\u0633\u0644 -\u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0633\u0644\u0627\u0645- \u0648\u0639\u064f\u0645\u0652\u0631\u0627\u0646\u0647\u0627 \u0628\u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u062f\u0639\u0648\u0647 -\u0633\u0628\u062d\u0627\u0646\u0647- \u0645\u062e\u0644\u0635\u064a\u0646 \u0644\u0647 \u0627\u0644\u062f\u0639\u0627\u0621; \u062e\u0648\u0641\u064b\u0627 \u0645\u0646 \u0639\u0642\u0627\u0628\u0647 \u0648\u0631\u062c\u0627\u0621 \u0644\u062b\u0648\u0627\u0628\u0647. \u0625\u0646 \u0631\u062d\u0645\u0629 \u0627\u0644\u0644\u0647 \u0642\u0631\u064a\u0628 \u0645\u0646 \u0627\u0644\u0645\u062d\u0633\u0646\u064a\u0646.","7:57":"\u0648\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0647\u0648 \u0627\u0644\u0630\u064a \u064a\u0631\u0633\u0644 \u0627\u0644\u0631\u064a\u0627\u062d \u0627\u0644\u0637\u064a\u0628\u0629 \u0627\u0644\u0644\u064a\u0646\u0629 \u0645\u0628\u0634\u0631\u0627\u062a \u0628\u0627\u0644\u063a\u064a\u062b \u0627\u0644\u0630\u064a \u062a\u062b\u064a\u0631\u0647 \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647\u060c \u0641\u064a\u0633\u062a\u0628\u0634\u0631 \u0627\u0644\u062e\u0644\u0642 \u0628\u0631\u062d\u0645\u0629 \u0627\u0644\u0644\u0647\u060c \u062d\u062a\u0649 \u0625\u0630\u0627 \u062d\u0645\u0644\u062a \u0627\u0644\u0631\u064a\u062d \u0627\u0644\u0633\u062d\u0627\u0628 \u0627\u0644\u0645\u062d\u0645\u0644 \u0628\u0627\u0644\u0645\u0637\u0631 \u0633\u0627\u0642\u0647 \u0627\u0644\u0644\u0647 \u0628\u0647\u0627 \u0644\u0625\u062d\u064a\u0627\u0621 \u0628\u0644\u062f\u060c \u0642\u062f \u0623\u062c\u062f\u0628\u062a \u0623\u0631\u0636\u0647\u060c \u0648\u064a\u064e\u0628\u0650\u0633\u062a \u0623\u0634\u062c\u0627\u0631\u0647 \u0648\u0632\u0631\u0639\u0647\u060c \u0641\u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0628\u0647 \u0627\u0644\u0645\u0637\u0631\u060c \u0641\u0623\u062e\u0631\u062c \u0628\u0647 \u0627\u0644\u0643\u0644\u0623 \u0648\u0627\u0644\u0623\u0634\u062c\u0627\u0631 \u0648\u0627\u0644\u0632\u0631\u0648\u0639\u060c \u0641\u0639\u0627\u062f\u062a \u0623\u0634\u062c\u0627\u0631\u0647 \u0645\u062d\u0645\u0644\u0629 \u0628\u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062b\u0645\u0631\u0627\u062a. \u0643\u0645\u0627 \u0646\u062d\u064a\u064a \u0647\u0630\u0627 \u0627\u0644\u0628\u0644\u062f \u0627\u0644\u0645\u064a\u062a \u0628\u0627\u0644\u0645\u0637\u0631 \u0646\u062e\u0631\u062c \u0627\u0644\u0645\u0648\u062a\u0649 \u0645\u0646 \u0642\u0628\u0648\u0631\u0647\u0645 \u0623\u062d\u064a\u0627\u0621\u064b \u0628\u0639\u062f \u0641\u0646\u0627\u0626\u0647\u0645; \u0644\u062a\u062a\u0639\u0638\u0648\u0627\u060c \u0641\u062a\u0633\u062a\u062f\u0644\u0648\u0627 \u0639\u0644\u0649 \u062a\u0648\u062d\u064a\u062f \u0627\u0644\u0644\u0647 \u0648\u0642\u062f\u0631\u062a\u0647 \u0639\u0644\u0649 \u0627\u0644\u0628\u0639\u062b.","7:58":"\u0648\u0627\u0644\u0623\u0631\u0636 \u0627\u0644\u0646\u0642\u064a\u0629 \u0625\u0630\u0627 \u0646\u0632\u0644 \u0639\u0644\u064a\u0647\u0627 \u0627\u0644\u0645\u0637\u0631 \u062a\u064f\u062e\u0652\u0631\u062c \u0646\u0628\u0627\u062a\u064b\u0627 -\u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647 \u0648\u0645\u0634\u064a\u0626\u062a\u0647- \u0637\u064a\u0628\u064b\u0627 \u0645\u064a\u0633\u0631\u064b\u0627\u060c \u0648\u0643\u0630\u0644\u0643 \u0627\u0644\u0645\u0624\u0645\u0646 \u0625\u0630\u0627 \u0646\u0632\u0644\u062a \u0639\u0644\u064a\u0647 \u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0627\u0646\u062a\u0641\u0639 \u0628\u0647\u0627\u060c \u0648\u0623\u062b\u0645\u0631\u062a \u0641\u064a\u0647 \u062d\u064a\u0627\u0629 \u0635\u0627\u0644\u062d\u0629\u060c \u0623\u0645\u0627 \u0627\u0644\u0623\u0631\u0636 \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u062e\u0629 \u0627\u0644\u0631\u062f\u064a\u0626\u0629 \u0641\u0625\u0646\u0647\u0627 \u0644\u0627 \u062a\u064f\u062e\u0631\u062c \u0627\u0644\u0646\u0628\u0627\u062a \u0625\u0644\u0627 \u0639\u0633\u0631\u064b\u0627 \u0631\u062f\u064a\u0626\u0627 \u0644\u0627 \u0646\u0641\u0639 \u0641\u064a\u0647\u060c \u0648\u0644\u0627 \u062a\u064f\u062e\u0631\u062c \u0646\u0628\u0627\u062a\u064b\u0627 \u0637\u064a\u0628\u064b\u0627\u060c \u0648\u0643\u0630\u0644\u0643 \u0627\u0644\u0643\u0627\u0641\u0631 \u0644\u0627 \u064a\u0646\u062a\u0641\u0639 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647. \u0645\u062b\u0644 \u0630\u0644\u0643 \u0627\u0644\u062a\u0646\u0648\u064a\u0639 \u0627\u0644\u0628\u062f\u064a\u0639 \u0641\u064a \u0627\u0644\u0628\u064a\u0627\u0646 \u0646\u064f\u0646\u0648\u0651\u0650\u0639 \u0627\u0644\u062d\u062c\u062c \u0648\u0627\u0644\u0628\u0631\u0627\u0647\u064a\u0646 \u0644\u0625\u062b\u0628\u0627\u062a \u0627\u0644\u062d\u0642 \u0644\u0623\u0646\u0627\u0633 \u064a\u0634\u0643\u0631\u0648\u0646 \u0646\u0639\u0645 \u0627\u0644\u0644\u0647\u060c \u0648\u064a\u0637\u064a\u0639\u0648\u0646\u0647.","7:59":"\u0644\u0642\u062f \u0628\u0639\u062b\u0646\u0627 \u0646\u0648\u062d\u064b\u0627 \u0625\u0644\u0649 \u0642\u0648\u0645\u0647; \u0644\u064a\u062f\u0639\u0648\u0647\u0645 \u0625\u0644\u0649 \u062a\u0648\u062d\u064a\u062f \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u0625\u062e\u0644\u0627\u0635 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0644\u0647\u060c \u0641\u0642\u0627\u0644: \u064a\u0627 \u0642\u0648\u0645 \u0627\u0639\u0628\u062f\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647\u060c \u0648\u0627\u062e\u0636\u0639\u0648\u0627 \u0644\u0647 \u0628\u0627\u0644\u0637\u0627\u0639\u0629\u060c \u0644\u064a\u0633 \u0644\u0643\u0645 \u0645\u0646 \u0625\u0644\u0647 \u064a\u0633\u062a\u062d\u0642 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u063a\u064a\u0631\u0647 \u062c\u0644 \u0648\u0639\u0644\u0627 \u0641\u0623\u062e\u0644\u0635\u0648\u0627 \u0644\u0647 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0641\u0625\u0646 \u0644\u0645 \u062a\u0641\u0639\u0644\u0648\u0627 \u0648\u0628\u0642\u064a\u062a\u0645 \u0639\u0644\u0649 \u0639\u0628\u0627\u062f\u0629 \u0623\u0648\u062b\u0627\u0646\u0643\u0645\u060c \u0641\u0625\u0646\u0646\u064a \u0623\u062e\u0627\u0641 \u0623\u0646 \u064a\u062d\u0644\u0651\u064e \u0639\u0644\u064a\u0643\u0645 \u0639\u0630\u0627\u0628 \u064a\u0648\u0645 \u064a\u0639\u0638\u0645 \u0641\u064a\u0647 \u0628\u0644\u0627\u0624\u0643\u0645\u060c \u0648\u0647\u0648 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629.","7:60":"\u0642\u0627\u0644 \u0644\u0647 \u0633\u0627\u062f\u062a\u0647\u0645 \u0648\u0643\u0628\u0631\u0627\u0624\u0647\u0645: \u0625\u0646\u0627 \u0644\u0646\u0639\u062a\u0642\u062f -\u064a\u0627 \u0646\u0648\u062d- \u0623\u0646\u0643 \u0641\u064a \u0636\u0644\u0627\u0644 \u0628\u064a\u0651\u0650\u0646 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0635\u0648\u0627\u0628.","7:61":"\u0642\u0627\u0644 \u0646\u0648\u062d: \u064a\u0627 \u0642\u0648\u0645 \u0644\u0633\u062a \u0636\u0627\u0644\u0627 \u0641\u064a \u0645\u0633\u0623\u0644\u0629 \u0645\u0646 \u0627\u0644\u0645\u0633\u0627\u0626\u0644 \u0628\u0648\u062c\u0647 \u0645\u0646 \u0627\u0644\u0648\u062c\u0648\u0647\u060c \u0648\u0644\u0643\u0646\u064a \u0631\u0633\u0648\u0644 \u0645\u0646 \u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0646 \u0631\u0628\u064a \u0648\u0631\u0628\u0643\u0645 \u0648\u0631\u0628 \u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u0644\u0642.","7:62":"\u0623\u064f\u0628\u0644\u0651\u0650\u063a\u0643\u0645 \u0645\u0627 \u0623\u064f\u0631\u0633\u0644\u062a \u0628\u0647 \u0645\u0646 \u0631\u0628\u064a\u060c \u0648\u0623\u0646\u0635\u062d \u0644\u0643\u0645 \u0645\u062d\u0630\u0631\u064b\u0627 \u0644\u0643\u0645 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647 \u0648\u0645\u0628\u0634\u0631\u064b\u0627 \u0628\u062b\u0648\u0627\u0628\u0647\u060c \u0648\u0623\u0639\u0644\u0645 \u0645\u0646 \u0634\u0631\u064a\u0639\u062a\u0647 \u0645\u0627 \u0644\u0627 \u062a\u0639\u0644\u0645\u0648\u0646.","7:63":"\u0648\u0647\u0644 \u0623\u062b\u0627\u0631 \u0639\u062c\u0628\u0643\u0645 \u0623\u0646 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0625\u0644\u064a\u0643\u0645 \u0645\u0627 \u064a\u0630\u0643\u0631\u0643\u0645 \u0628\u0645\u0627 \u0641\u064a\u0647 \u0627\u0644\u062e\u064a\u0631 \u0644\u0643\u0645\u060c \u0639\u0644\u0649 \u0644\u0633\u0627\u0646 \u0631\u062c\u0644 \u0645\u0646\u0643\u0645\u060c \u062a\u0639\u0631\u0641\u0648\u0646 \u0646\u0633\u0628\u0647 \u0648\u0635\u062f\u0642\u0647; \u0644\u064a\u062e\u0648\u0651\u0650\u0641\u0643\u0645 \u0628\u0623\u0633 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0639\u0642\u0627\u0628\u0647\u060c \u0648\u0644\u062a\u062a\u0642\u0648\u0627 \u0633\u062e\u0637\u0647 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0647\u060c \u0648\u0631\u062c\u0627\u0621 \u0623\u0646 \u062a\u0638\u0641\u0631\u0648\u0627 \u0628\u0631\u062d\u0645\u062a\u0647 \u0648\u062c\u0632\u064a\u0644 \u062b\u0648\u0627\u0628\u0647\u061f","7:64":"\u0641\u0643\u0630\u0628\u0648\u0627 \u0646\u0648\u062d\u064b\u0627 \u0641\u0623\u0646\u062c\u064a\u0646\u0627\u0647 \u0648\u0645\u064e\u0646 \u0622\u0645\u0646 \u0645\u0639\u0647 \u0641\u064a \u0627\u0644\u0633\u0641\u064a\u0646\u0629\u060c \u0648\u0623\u063a\u0631\u0642\u0646\u0627 \u0627\u0644\u0643\u0641\u0627\u0631 \u0627\u0644\u0630\u064a\u0646 \u0643\u0630\u0628\u0648\u0627 \u0628\u062d\u062c\u062c\u0646\u0627 \u0627\u0644\u0648\u0627\u0636\u062d\u0629. \u0625\u0646\u0647\u0645 \u0643\u0627\u0646\u0648\u0627 \u0639\u064f\u0645\u0652\u064a\u064e \u0627\u0644\u0642\u0644\u0648\u0628 \u0639\u0646 \u0631\u0624\u064a\u0629 \u0627\u0644\u062d\u0642.","7:65":"\u0648\u0644\u0642\u062f \u0623\u0631\u0633\u0644\u0646\u0627 \u0625\u0644\u0649 \u0642\u0628\u064a\u0644\u0629 \u0639\u0627\u062f \u0623\u062e\u0627\u0647\u0645 \u0647\u0648\u062f\u0627 \u062d\u064a\u0646 \u0639\u0628\u062f\u0648\u0627 \u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647\u060c \u0641\u0642\u0627\u0644 \u0644\u0647\u0645: \u0627\u0639\u0628\u062f\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647\u060c \u0644\u064a\u0633 \u0644\u0643\u0645 \u0645\u0646 \u0625\u0644\u0647 \u064a\u0633\u062a\u062d\u0642 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u063a\u064a\u0631\u0647 \u062c\u0644 \u0648\u0639\u0644\u0627 \u0641\u0623\u062e\u0644\u0635\u0648\u0627 \u0644\u0647 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0623\u0641\u0644\u0627 \u062a\u062a\u0642\u0648\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647 \u0648\u0633\u062e\u0637\u0647 \u0639\u0644\u064a\u0643\u0645\u061f","7:66":"\u0642\u0627\u0644 \u0627\u0644\u0643\u0628\u0631\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0645\u0646 \u0642\u0648\u0645 \u0647\u0648\u062f: \u0625\u0646\u0627 \u0644\u0646\u0639\u0644\u0645 \u0623\u0646\u0643 \u0628\u062f\u0639\u0648\u062a\u0643 \u0625\u064a\u0627\u0646\u0627 \u0625\u0644\u0649 \u062a\u0631\u0643 \u0639\u0628\u0627\u062f\u0629 \u0622\u0644\u0647\u062a\u0646\u0627 \u0648\u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0646\u0627\u0642\u0635 \u0627\u0644\u0639\u0642\u0644\u060c \u0648\u0625\u0646\u0627 \u0644\u0646\u0639\u062a\u0642\u062f \u0623\u0646\u0643 \u0645\u0646 \u0627\u0644\u0643\u0627\u0630\u0628\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0641\u064a\u0645\u0627 \u062a\u0642\u0648\u0644.","7:67":"\u0642\u0627\u0644 \u0647\u0648\u062f: \u064a\u0627 \u0642\u0648\u0645 \u0644\u064a\u0633 \u0628\u064a \u0646\u0642\u0635 \u0641\u064a \u0639\u0642\u0644\u064a\u060c \u0648\u0644\u0643\u0646\u064a \u0631\u0633\u0648\u0644 \u0625\u0644\u064a\u0643\u0645 \u0645\u0646 \u0631\u0628 \u0627\u0644\u062e\u0644\u0642 \u0623\u062c\u0645\u0639\u064a\u0646.","7:68":"\u0623\u064f\u0628\u0644\u0651\u0650\u063a\u0643\u0645 \u0645\u0627 \u0623\u0631\u0633\u0644\u0646\u064a \u0628\u0647 \u0631\u0628\u064a \u0625\u0644\u064a\u0643\u0645\u060c \u0648\u0623\u0646\u0627 \u0644\u0643\u0645 - \u0641\u064a\u0645\u0627 \u062f\u0639\u0648\u062a\u0643\u0645 \u0625\u0644\u064a\u0647 \u0645\u0646 \u062a\u0648\u062d\u064a\u062f \u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u0639\u0645\u0644 \u0628\u0634\u0631\u064a\u0639\u062a\u0647 - \u0646\u0627\u0635\u062d\u060c \u0623\u0645\u064a\u0646 \u0639\u0644\u0649 \u0648\u062d\u064a \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649.","7:69":"\u0648\u0647\u0644 \u0623\u062b\u0627\u0631 \u0639\u062c\u0628\u0643\u0645 \u0623\u0646 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0625\u0644\u064a\u0643\u0645 \u0645\u0627 \u064a\u0630\u0643\u0631\u0643\u0645 \u0628\u0645\u0627 \u0641\u064a\u0647 \u0627\u0644\u062e\u064a\u0631 \u0644\u0643\u0645\u060c \u0639\u0644\u0649 \u0644\u0633\u0627\u0646 \u0631\u062c\u0644 \u0645\u0646\u0643\u0645\u060c \u062a\u0639\u0631\u0641\u0648\u0646 \u0646\u0633\u0628\u0647 \u0648\u0635\u062f\u0642\u0647; \u0644\u064a\u062e\u0648\u0651\u0650\u0641\u0643\u0645 \u0628\u0623\u0633 \u0627\u0644\u0644\u0647 \u0648\u0639\u0642\u0627\u0628\u0647\u061f \u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0639\u0645\u0629 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0625\u0630 \u062c\u0639\u0644\u0643\u0645 \u062a\u062e\u0644\u0641\u0648\u0646 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0645\u064e\u0646 \u0642\u0628\u0644\u0643\u0645 \u0645\u0646 \u0628\u0639\u062f \u0645\u0627 \u0623\u0647\u0644\u0643 \u0642\u0648\u0645 \u0646\u0648\u062d\u060c \u0648\u0632\u0627\u062f \u0641\u064a \u0623\u062c\u0633\u0627\u0645\u0643\u0645 \u0642\u0648\u0629 \u0648\u0636\u062e\u0627\u0645\u0629\u060c \u0641\u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0650\u0639\u064e\u0645\u064e \u0627\u0644\u0644\u0647 \u0627\u0644\u0643\u062b\u064a\u0631\u0629 \u0639\u0644\u064a\u0643\u0645; \u0631\u062c\u0627\u0621 \u0623\u0646 \u062a\u0641\u0648\u0632\u0648\u0627 \u0627\u0644\u0641\u0648\u0632 \u0627\u0644\u0639\u0638\u064a\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629.","7:70":"\u0642\u0627\u0644\u062a \u0639\u0627\u062f \u0644\u0647\u0648\u062f \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645: \u0623\u062f\u0639\u0648\u062a\u0646\u0627 \u0644\u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0648\u0647\u064e\u062c\u0652\u0631 \u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0623\u0635\u0646\u0627\u0645 \u0627\u0644\u062a\u064a \u0648\u0631\u062b\u0646\u0627 \u0639\u0628\u0627\u062f\u062a\u0647\u0627 \u0639\u0646 \u0622\u0628\u0627\u0626\u0646\u0627\u061f \u0641\u0623\u062a\u0646\u0627 \u0628\u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0630\u064a \u062a\u062e\u0648\u0641\u0646\u0627 \u0628\u0647 \u0625\u0646 \u0643\u0646\u062a \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0635\u062f\u0642 \u0641\u064a\u0645\u0627 \u062a\u0642\u0648\u0644.","7:71":"\u0642\u0627\u0644 \u0647\u0648\u062f \u0644\u0642\u0648\u0645\u0647: \u0642\u062f \u062d\u0644\u0651\u064e \u0628\u0643\u0645 \u0639\u0630\u0627\u0628 \u0648\u063a\u0636\u0628 \u0645\u0646 \u0631\u0628\u0643\u0645 \u062c\u0644 \u0648\u0639\u0644\u0627 \u0623\u062a\u062c\u0627\u062f\u0644\u0648\u0646\u0646\u064a \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0623\u0635\u0646\u0627\u0645 \u0627\u0644\u062a\u064a \u0633\u0645\u064a\u062a\u0645\u0648\u0647\u0627 \u0622\u0644\u0647\u0629 \u0623\u0646\u062a\u0645 \u0648\u0622\u0628\u0627\u0624\u0643\u0645\u061f \u0645\u0627 \u0646\u0632\u0651\u064e\u0644 \u0627\u0644\u0644\u0647 \u0628\u0647\u0627 \u0645\u0646 \u062d\u062c\u0629 \u0648\u0644\u0627 \u0628\u0631\u0647\u0627\u0646; \u0644\u0623\u0646\u0647\u0627 \u0645\u062e\u0644\u0648\u0642\u0629 \u0644\u0627 \u062a\u0636\u0631 \u0648\u0644\u0627 \u062a\u0646\u0641\u0639\u060c \u0648\u0625\u0646\u0645\u0627 \u0627\u0644\u0645\u0639\u0628\u0648\u062f \u0648\u062d\u062f\u0647 \u0647\u0648 \u0627\u0644\u062e\u0627\u0644\u0642 \u0633\u0628\u062d\u0627\u0646\u0647\u060c \u0641\u0627\u0646\u062a\u0638\u0631\u0648\u0627 \u0646\u0632\u0648\u0644 \u0627\u0644\u0639\u0630\u0627\u0628 \u0639\u0644\u064a\u0643\u0645 \u0641\u0625\u0646\u064a \u0645\u0646\u062a\u0638\u0631 \u0645\u0639\u0643\u0645 \u0646\u0632\u0648\u0644\u0647\u060c \u0648\u0647\u0630\u0627 \u063a\u0627\u064a\u0629 \u0641\u064a \u0627\u0644\u062a\u0647\u062f\u064a\u062f \u0648\u0627\u0644\u0648\u0639\u064a\u062f.","7:72":"\u0641\u0648\u0642\u0639 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647 \u0628\u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0631\u064a\u062d \u0627\u0644\u0634\u062f\u064a\u062f\u0629 \u0639\u0644\u064a\u0647\u0645\u060c \u0641\u0623\u0646\u062c\u0649 \u0627\u0644\u0644\u0647 \u0647\u0648\u062f\u064b\u0627 \u0648\u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0645\u0639\u0647 \u0628\u0631\u062d\u0645\u0629 \u0639\u0638\u064a\u0645\u0629 \u0645\u0646\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0623\u0647\u0644\u0643 \u0627\u0644\u0643\u0641\u0627\u0631 \u0645\u0646 \u0642\u0648\u0645\u0647 \u062c\u0645\u064a\u0639\u0627 \u0648\u062f\u0645\u0651\u064e\u0631\u0647\u0645 \u0639\u0646 \u0622\u062e\u0631\u0647\u0645\u060c \u0648\u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u0645\u0624\u0645\u0646\u064a\u0646 \u0644\u062c\u0645\u0639\u0647\u0645 \u0628\u064a\u0646 \u0627\u0644\u062a\u0643\u0630\u064a\u0628 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0648\u062a\u0631\u0643 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d.","7:73":"\u0648\u0644\u0642\u062f \u0623\u0631\u0633\u0644\u0646\u0627 \u0625\u0644\u0649 \u0642\u0628\u064a\u0644\u0629 \u062b\u0645\u0648\u062f \u0623\u062e\u0627\u0647\u0645 \u0635\u0627\u0644\u062d\u064b\u0627 \u0644\u0645\u0651\u064e\u0627 \u0639\u0628\u062f\u0648\u0627 \u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649. \u0641\u0642\u0627\u0644 \u0635\u0627\u0644\u062d \u0644\u0647\u0645: \u064a\u0627 \u0642\u0648\u0645 \u0627\u0639\u0628\u062f\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647; \u0644\u064a\u0633 \u0644\u0643\u0645 \u0645\u0646 \u0625\u0644\u0647 \u064a\u0633\u062a\u062d\u0642 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u063a\u064a\u0631\u0647 \u062c\u0644 \u0648\u0639\u0644\u0627\u060c \u0641\u0623\u062e\u0644\u0635\u0648\u0627 \u0644\u0647 \u0627\u0644\u0639\u0628\u0627\u062f\u0629\u060c \u0642\u062f \u062c\u0626\u062a\u0643\u0645 \u0628\u0627\u0644\u0628\u0631\u0647\u0627\u0646 \u0639\u0644\u0649 \u0635\u062f\u0642 \u0645\u0627 \u0623\u062f\u0639\u0648\u0643\u0645 \u0625\u0644\u064a\u0647\u060c \u0625\u0630 \u062f\u0639\u0648\u062a\u064f \u0627\u0644\u0644\u0647 \u0623\u0645\u0627\u0645\u0643\u0645\u060c \u0641\u0623\u062e\u0631\u062c \u0644\u0643\u0645 \u0645\u0646 \u0627\u0644\u0635\u062e\u0631\u0629 \u0646\u0627\u0642\u0629 \u0639\u0638\u064a\u0645\u0629 \u0643\u0645\u0627 \u0633\u0623\u0644\u062a\u0645\u060c \u0641\u0627\u062a\u0631\u0643\u0648\u0647\u0627 \u062a\u0623\u0643\u0644 \u0641\u064a \u0623\u0631\u0636 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0645\u0631\u0627\u0639\u064a\u060c \u0648\u0644\u0627 \u062a\u062a\u0639\u0631\u0636\u0648\u0627 \u0644\u0647\u0627 \u0628\u0623\u064a \u0623\u0630\u0649\u060c \u0641\u064a\u0635\u064a\u0628\u0643\u0645 \u0628\u0633\u0628\u0628 \u0630\u0644\u0643 \u0639\u0630\u0627\u0628 \u0645\u0648\u062c\u0639.","7:74":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0639\u0645\u0629 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645\u060c \u0625\u0630 \u062c\u0639\u0644\u0643\u0645 \u062a\u064e\u062e\u0652\u0644\u064f\u0641\u0648\u0646 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0645\u064e\u0646 \u0642\u0628\u0644\u0643\u0645\u060c \u0645\u0646 \u0628\u0639\u062f \u0642\u0628\u064a\u0644\u0629 \u0639\u0627\u062f\u060c \u0648\u0645\u0643\u0651\u064e\u0646 \u0644\u0643\u0645 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0627\u0644\u0637\u064a\u0628\u0629 \u062a\u0646\u0632\u0644\u0648\u0646\u0647\u0627\u060c \u0641\u062a\u0628\u0646\u0648\u0646 \u0641\u064a \u0633\u0647\u0648\u0644\u0647\u0627 \u0627\u0644\u0628\u064a\u0648\u062a \u0627\u0644\u0639\u0638\u064a\u0645\u0629\u060c \u0648\u062a\u0646\u062d\u062a\u0648\u0646 \u0645\u0646 \u062c\u0628\u0627\u0644\u0647\u0627 \u0628\u064a\u0648\u062a\u064b\u0627 \u0623\u062e\u0631\u0649\u060c \u0641\u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0650\u0639\u064e\u0645\u064e \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645\u060c \u0648\u0644\u0627 \u062a\u064e\u0633\u0652\u0639\u064e\u0648\u0627 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0628\u0627\u0644\u0625\u0641\u0633\u0627\u062f.","7:75":"\u0642\u0627\u0644 \u0627\u0644\u0633\u0627\u062f\u0629 \u0648\u0627\u0644\u0643\u0628\u0631\u0627\u0621 \u0645\u0646 \u0627\u0644\u0630\u064a\u0646 \u0627\u0633\u062a\u0639\u0644\u064e\u0648\u0627 -\u0645\u0646 \u0642\u0648\u0645 \u0635\u0627\u0644\u062d- \u0644\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0627\u0633\u062a\u0636\u0639\u0641\u0648\u0647\u0645\u060c \u0648\u0627\u0633\u062a\u0647\u0627\u0646\u0648\u0627 \u0628\u0647\u0645: \u0623\u062a\u0639\u0644\u0645\u0648\u0646 \u062d\u0642\u064a\u0642\u0629 \u0623\u0646 \u0635\u0627\u0644\u062d\u064b\u0627 \u0642\u062f \u0623\u0631\u0633\u0644\u0647 \u0627\u0644\u0644\u0647 \u0625\u0644\u064a\u0646\u0627\u061f \u0642\u0627\u0644 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627: \u0625\u0646\u0627 \u0645\u0635\u062f\u0642\u0648\u0646 \u0628\u0645\u0627 \u0623\u0631\u0633\u0644\u0647 \u0627\u0644\u0644\u0647 \u0628\u0647\u060c \u0645\u062a\u0651\u064e\u0628\u0639\u0648\u0646 \u0644\u0634\u0631\u0639\u0647.","7:76":"\u0642\u0627\u0644 \u0627\u0644\u0630\u064a\u0646 \u0627\u0633\u062a\u0639\u0644\u064e\u0648\u0652\u0627: \u0625\u0646\u0651\u064e\u0627 \u0628\u0627\u0644\u0630\u064a \u0635\u062f\u0651\u064e\u0642\u062a\u0645 \u0628\u0647 \u0648\u0627\u062a\u0628\u0639\u062a\u0645\u0648\u0647 \u0645\u0646 \u0646\u0628\u0648\u0629 \u0635\u0627\u0644\u062d \u062c\u0627\u062d\u062f\u0648\u0646.","7:77":"\u0641\u0646\u062d\u0631\u0648\u0627 \u0627\u0644\u0646\u0627\u0642\u0629 \u0627\u0633\u062a\u062e\u0641\u0627\u0641\u0627 \u0645\u0646\u0647\u0645 \u0628\u0648\u0639\u064a\u062f \u0635\u0627\u0644\u062d\u060c \u0648\u0627\u0633\u062a\u0643\u0628\u0631\u0648\u0627 \u0639\u0646 \u0627\u0645\u062a\u062b\u0627\u0644 \u0623\u0645\u0631 \u0631\u0628\u0647\u0645\u060c \u0648\u0642\u0627\u0644\u0648\u0627 \u0639\u0644\u0649 \u0633\u0628\u064a\u0644 \u0627\u0644\u0627\u0633\u062a\u0647\u0632\u0627\u0621 \u0648\u0627\u0633\u062a\u0628\u0639\u0627\u062f \u0627\u0644\u0639\u0630\u0627\u0628: \u064a\u0627 \u0635\u0627\u0644\u062d \u0627\u0626\u062a\u0646\u0627 \u0628\u0645\u0627 \u062a\u062a\u0648\u0639\u0651\u064e\u062f\u0646\u0627 \u0628\u0647 \u0645\u0646 \u0627\u0644\u0639\u0630\u0627\u0628\u060c \u0625\u0646 \u0643\u0646\u062a \u0645\u0650\u0646 \u0631\u0633\u0644 \u0627\u0644\u0644\u0647.","7:78":"\u0641\u0623\u062e\u0630\u064e\u062a \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0627\u0644\u0632\u0644\u0632\u0644\u0629\u064f \u0627\u0644\u0634\u062f\u064a\u062f\u0629 \u0627\u0644\u062a\u064a \u062e\u0644\u0639\u062a \u0642\u0644\u0648\u0628\u0647\u0645\u060c \u0641\u0623\u0635\u0628\u062d\u0648\u0627 \u0641\u064a \u0628\u0644\u062f\u0647\u0645 \u0647\u0627\u0644\u0643\u064a\u0646\u060c \u0644\u0627\u0635\u0642\u064a\u0646 \u0628\u0627\u0644\u0623\u0631\u0636 \u0639\u0644\u0649 \u0631\u064f\u0643\u064e\u0628\u0647\u0645 \u0648\u0648\u062c\u0648\u0647\u0647\u0645\u060c \u0644\u0645 \u064a\u064f\u0641\u0652\u0644\u0650\u062a \u0645\u0646\u0647\u0645 \u0623\u062d\u062f.","7:79":"\u0641\u0623\u0639\u0631\u0636 \u0635\u0627\u0644\u062d \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0639\u0646 \u0642\u0648\u0645\u0647 -\u062d\u064a\u0646 \u0639\u0642\u0631\u0648\u0627 \u0627\u0644\u0646\u0627\u0642\u0629 \u0648\u062d\u0644 \u0628\u0647\u0645 \u0627\u0644\u0647\u0644\u0627\u0643- \u0648\u0642\u0627\u0644 \u0644\u0647\u0645: \u064a\u0627 \u0642\u0648\u0645 \u0644\u0642\u062f \u0623\u0628\u0644\u063a\u062a\u0643\u0645 \u0645\u0627 \u0623\u0645\u0631\u0646\u064a \u0631\u0628\u064a \u0628\u0625\u0628\u0644\u0627\u063a\u0647 \u0645\u0646 \u0623\u0645\u0631\u0647 \u0648\u0646\u0647\u064a\u0647\u060c \u0648\u0628\u064e\u0630\u064e\u0644\u0652\u062a \u0644\u0643\u0645 \u0648\u0633\u0639\u064a \u0641\u064a \u0627\u0644\u062a\u0631\u063a\u064a\u0628 \u0648\u0627\u0644\u062a\u0631\u0647\u064a\u0628 \u0648\u0627\u0644\u0646\u0635\u062d\u060c \u0648\u0644\u0643\u0646\u0643\u0645 \u0644\u0627 \u062a\u062d\u0628\u0648\u0646 \u0627\u0644\u0646\u0627\u0635\u062d\u064a\u0646\u060c \u0641\u0631\u062f\u062f\u062a\u0645 \u0642\u0648\u0644\u0647\u0645\u060c \u0648\u0623\u0637\u0639\u062a\u0645 \u0643\u0644 \u0634\u064a\u0637\u0627\u0646 \u0631\u062c\u064a\u0645.","7:80":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0648\u0637\u064b\u0627 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u062d\u064a\u0646 \u0642\u0627\u0644 \u0644\u0642\u0648\u0645\u0647: \u0623\u062a\u0641\u0639\u0644\u0648\u0646 \u0627\u0644\u0641\u0639\u0644\u0629 \u0627\u0644\u0645\u0646\u0643\u0631\u0629 \u0627\u0644\u062a\u064a \u0628\u0644\u063a\u062a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0642\u0628\u062d\u061f \u0645\u0627 \u0641\u0639\u0644\u0647\u0627 \u0645\u0650\u0646 \u0623\u062d\u062f \u0642\u0628\u0644\u0643\u0645 \u0645\u0646 \u0627\u0644\u0645\u062e\u0644\u0648\u0642\u064a\u0646.","7:81":"\u0625\u0646\u0643\u0645 \u0644\u062a\u0623\u062a\u0648\u0646 \u0627\u0644\u0630\u0643\u0648\u0631 \u0641\u064a \u0623\u062f\u0628\u0627\u0631\u0647\u0645\u060c \u0634\u0647\u0648\u0629 \u0645\u0646\u0643\u0645 \u0644\u0630\u0644\u0643\u060c \u063a\u064a\u0631 \u0645\u0628\u0627\u0644\u064a\u0646 \u0628\u0642\u0628\u062d\u0647\u0627\u060c \u062a\u0627\u0631\u0643\u064a\u0646 \u0627\u0644\u0630\u064a \u0623\u062d\u0644\u0651\u064e\u0647 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0645\u0646 \u0646\u0633\u0627\u0626\u0643\u0645\u060c \u0628\u0644 \u0623\u0646\u062a\u0645 \u0642\u0648\u0645 \u0645\u062a\u062c\u0627\u0648\u0632\u0648\u0646 \u0644\u062d\u062f\u0648\u062f \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u0625\u0633\u0631\u0627\u0641. \u0625\u0646 \u0625\u062a\u064a\u0627\u0646 \u0627\u0644\u0630\u0643\u0648\u0631 \u062f\u0648\u0646 \u0627\u0644\u0625\u0646\u0627\u062b \u0645\u0646 \u0627\u0644\u0641\u0648\u0627\u062d\u0634 \u0627\u0644\u062a\u064a \u0627\u0628\u062a\u062f\u0639\u0647\u0627 \u0642\u0648\u0645 \u0644\u0648\u0637\u060c \u0648\u0644\u0645 \u064a\u0633\u0628\u0642\u0647\u0645 \u0628\u0647\u0627 \u0623\u062d\u062f \u0645\u0646 \u0627\u0644\u062e\u0644\u0642.","7:82":"\u0648\u0645\u0627 \u0643\u0627\u0646 \u062c\u0648\u0627\u0628 \u0642\u0648\u0645 \u0644\u0648\u0637 \u062d\u064a\u0646 \u0623\u0646\u0643\u0631 \u0639\u0644\u064a\u0647\u0645 \u0641\u0639\u0644\u0647\u0645 \u0627\u0644\u0634\u0646\u064a\u0639 \u0625\u0644\u0627 \u0623\u0646 \u0642\u0627\u0644 \u0628\u0639\u0636\u0647\u0645 \u0644\u0628\u0639\u0636: \u0623\u062e\u0631\u062c\u0648\u0627 \u0644\u0648\u0637\u064b\u0627 \u0648\u0623\u0647\u0644\u0647 \u0645\u0646 \u0628\u0644\u0627\u062f\u0643\u0645\u060c \u0625\u0646\u0647 \u0648\u0645\u0646 \u062a\u0628\u0639\u0647 \u0623\u0646\u0627\u0633 \u064a\u062a\u0646\u0632\u0647\u0648\u0646 \u0639\u0646 \u0625\u062a\u064a\u0627\u0646 \u0623\u062f\u0628\u0627\u0631 \u0627\u0644\u0631\u062c\u0627\u0644 \u0648\u0627\u0644\u0646\u0633\u0627\u0621.","7:83":"\u0641\u0623\u0646\u062c\u0649 \u0627\u0644\u0644\u0647 \u0644\u0648\u0637\u064b\u0627 \u0648\u0623\u0647\u0644\u0647 \u0645\u0646 \u0627\u0644\u0639\u0630\u0627\u0628 \u062d\u064a\u062b \u0623\u0645\u0631\u0647 \u0628\u0645\u063a\u0627\u062f\u0631\u0629 \u0630\u0644\u0643 \u0627\u0644\u0628\u0644\u062f\u060c \u0625\u0644\u0627 \u0627\u0645\u0631\u0623\u062a\u0647\u060c \u0641\u0625\u0646\u0647\u0627 \u0643\u0627\u0646\u062a \u0645\u0646 \u0627\u0644\u0647\u0627\u0644\u0643\u064a\u0646 \u0627\u0644\u0628\u0627\u0642\u064a\u0646 \u0641\u064a \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647.","7:84":"\u0648\u0639\u0630\u0651\u064e\u0628 \u0627\u0644\u0644\u0647 \u0627\u0644\u0643\u0641\u0627\u0631 \u0645\u0646 \u0642\u0648\u0645 \u0644\u0648\u0637 \u0628\u0623\u0646 \u0623\u0646\u0632\u0644 \u0639\u0644\u064a\u0647\u0645 \u0645\u0637\u0631\u064b\u0627 \u0645\u0646 \u0627\u0644\u062d\u062c\u0627\u0631\u0629\u060c \u0648\u0642\u0644\u0628 \u0628\u0644\u0627\u062f\u0647\u0645\u060c \u0641\u062c\u0639\u0644 \u0639\u0627\u0644\u064a\u0647\u0627 \u0633\u0627\u0641\u0644\u0647\u0627\u060c \u0641\u0627\u0646\u0638\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0643\u064a\u0641 \u0635\u0627\u0631\u062a \u0639\u0627\u0642\u0628\u0629 \u0627\u0644\u0630\u064a\u0646 \u0627\u062c\u062a\u0631\u0624\u0648\u0627 \u0639\u0644\u0649 \u0645\u0639\u0627\u0635\u064a \u0627\u0644\u0644\u0647 \u0648\u0643\u0630\u0628\u0648\u0627 \u0631\u0633\u0644\u0647.","7:85":"\u0648\u0644\u0642\u062f \u0623\u0631\u0633\u0644\u0646\u0627 \u0625\u0644\u0649 \u0642\u0628\u064a\u0644\u0629 \xab\u0645\u062f\u064a\u0646\xbb \u0623\u062e\u0627\u0647\u0645 \u0634\u0639\u064a\u0628\u064b\u0627 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0641\u0642\u0627\u0644 \u0644\u0647\u0645: \u064a\u0627 \u0642\u0648\u0645 \u0627\u0639\u0628\u062f\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647; \u0644\u064a\u0633 \u0644\u0643\u0645 \u0645\u0650\u0646 \u0625\u0644\u0647 \u064a\u0633\u062a\u062d\u0642 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u063a\u064a\u0631\u0647 \u062c\u0644 \u0648\u0639\u0644\u0627 \u0641\u0623\u062e\u0644\u0635\u0648\u0627 \u0644\u0647 \u0627\u0644\u0639\u0628\u0627\u062f\u0629\u060c \u0642\u062f \u062c\u0627\u0621\u0643\u0645 \u0628\u0631\u0647\u0627\u0646 \u0645\u0646 \u0631\u0628\u0643\u0645 \u0639\u0644\u0649 \u0635\u0650\u062f\u0652\u0642 \u0645\u0627 \u0623\u062f\u0639\u0648\u0643\u0645 \u0625\u0644\u064a\u0647\u060c \u0641\u0623\u062f\u0648\u0627 \u0644\u0644\u0646\u0627\u0633 \u062d\u0642\u0648\u0642\u0647\u0645 \u0628\u0625\u064a\u0641\u0627\u0621 \u0627\u0644\u0643\u064a\u0644\u060c \u0627\u0644\u0645\u064a\u0632\u0627\u0646\u060c \u0648\u0644\u0627 \u062a\u0646\u0642\u0635\u0648\u0647\u0645 \u062d\u0642\u0648\u0642\u0647\u0645 \u0641\u062a\u0638\u0644\u0645\u0648\u0647\u0645\u060c \u0648\u0644\u0627 \u062a\u0641\u0633\u062f\u0648\u0627 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 -\u0628\u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u0638\u0644\u0645- \u0628\u0639\u062f \u0625\u0635\u0644\u0627\u062d\u0647\u0627 \u0628\u0634\u0631\u0627\u0626\u0639 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0627\u0644\u0633\u0627\u0628\u0642\u064a\u0646 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0633\u0644\u0627\u0645. \u0630\u0644\u0643 \u0627\u0644\u0630\u064a \u062f\u0639\u0648\u062a\u0643\u0645 \u0625\u0644\u064a\u0647 \u062e\u064a\u0631 \u0644\u0643\u0645 \u0641\u064a \u062f\u0646\u064a\u0627\u0643\u0645 \u0648\u0623\u062e\u0631\u0627\u0643\u0645\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u0645\u0635\u062f\u0642\u064a\u0651\u064e \u0641\u064a\u0645\u0627 \u062f\u0639\u0648\u062a\u0643\u0645 \u0625\u0644\u064a\u0647\u060c \u0639\u0627\u0645\u0644\u064a\u0646 \u0628\u0634\u0631\u0639 \u0627\u0644\u0644\u0647.","7:86":"\u0648\u0644\u0627 \u062a\u0642\u0639\u062f\u0648\u0627 \u0628\u0643\u0644 \u0637\u0631\u064a\u0642 \u062a\u062a\u0648\u0639\u062f\u0648\u0646 \u0627\u0644\u0646\u0627\u0633 \u0628\u0627\u0644\u0642\u062a\u0644\u060c \u0625\u0646 \u0644\u0645 \u064a\u0639\u0637\u0648\u0643\u0645 \u0623\u0645\u0648\u0627\u0644\u0647\u0645\u060c \u0648\u062a\u0635\u062f\u0651\u064f\u0648\u0646 \u0639\u0646 \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0627\u0644\u0642\u0648\u064a\u0645 \u0645\u0646 \u0635\u062f\u0651\u064e\u0642 \u0628\u0647 \u0639\u0632 \u0648\u062c\u0644\u060c \u0648\u0639\u0645\u0644 \u0635\u0627\u0644\u062d\u064b\u0627\u060c \u0648\u062a\u0628\u063a\u0648\u0646 \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0623\u0646 \u062a\u0643\u0648\u0646 \u0645\u0639\u0648\u062c\u0629\u060c \u0648\u062a\u0645\u064a\u0644\u0648\u0646\u0647\u0627 \u0627\u062a\u0628\u0627\u0639\u064b\u0627 \u0644\u0623\u0647\u0648\u0627\u0626\u0643\u0645\u060c \u0648\u062a\u0646\u0641\u0651\u0650\u0631\u0648\u0646 \u0627\u0644\u0646\u0627\u0633 \u0639\u0646 \u0627\u062a\u0628\u0627\u0639\u0647\u0627. \u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0639\u0645\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u064a\u0643\u0645 \u0625\u0630 \u0643\u0627\u0646 \u0639\u062f\u062f\u0643\u0645 \u0642\u0644\u064a\u0644\u0627 \u0641\u0643\u062b\u0651\u064e\u0631\u0643\u0645\u060c \u0641\u0623\u0635\u0628\u062d\u062a\u0645 \u0623\u0642\u0648\u064a\u0627\u0621 \u0639\u0632\u064a\u0632\u064a\u0646\u060c \u0648\u0627\u0646\u0638\u0631\u0648\u0627 \u0643\u064a\u0641 \u0643\u0627\u0646 \u0639\u0627\u0642\u0628\u0629 \u0627\u0644\u0645\u0641\u0633\u062f\u064a\u0646 \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0645\u0627 \u062d\u0644\u0651\u064e \u0628\u0647\u0645 \u0645\u0646 \u0627\u0644\u0647\u0644\u0627\u0643 \u0648\u0627\u0644\u062f\u0645\u0627\u0631\u061f","7:87":"\u0648\u0625\u0646 \u0643\u0627\u0646 \u062c\u0645\u0627\u0639\u0629 \u0645\u0646\u0643\u0645 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0628\u0627\u0644\u0630\u064a \u0623\u0631\u0633\u0644\u0646\u064a \u0627\u0644\u0644\u0647 \u0628\u0647\u060c \u0648\u062c\u0645\u0627\u0639\u0629 \u0644\u0645 \u064a\u0635\u062f\u0651\u0650\u0642\u0648\u0627 \u0628\u0630\u0644\u0643\u060c \u0641\u0627\u0646\u062a\u0638\u0631\u0648\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0643\u0630\u0628\u0648\u0646 \u0642\u0636\u0627\u0621 \u0627\u0644\u0644\u0647 \u0627\u0644\u0641\u0627\u0635\u0644 \u0628\u064a\u0646\u0646\u0627 \u0648\u0628\u064a\u0646\u0643\u0645 \u062d\u064a\u0646 \u064a\u062d\u0644\u0651\u064f \u0639\u0644\u064a\u0643\u0645 \u0639\u0630\u0627\u0628\u0647 \u0627\u0644\u0630\u064a \u0623\u0646\u0630\u0631\u062a\u0643\u0645 \u0628\u0647. \u0648\u0627\u0644\u0644\u0647 -\u062c\u0644\u0651\u064e \u0648\u0639\u0644\u0627- \u0647\u0648 \u062e\u064a\u0631 \u0627\u0644\u062d\u0627\u0643\u0645\u064a\u0646 \u0628\u064a\u0646 \u0639\u0628\u0627\u062f\u0647.","7:88":"\u0642\u0627\u0644 \u0627\u0644\u0633\u0627\u062f\u0629 \u0648\u0627\u0644\u0643\u0628\u0631\u0627\u0621 \u0645\u0646 \u0642\u0648\u0645 \u0634\u0639\u064a\u0628 \u0627\u0644\u0630\u064a\u0646 \u062a\u0643\u0628\u0631\u0648\u0627 \u0639\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u062a\u0628\u0627\u0639 \u0631\u0633\u0648\u0644\u0647 \u0634\u0639\u064a\u0628 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645: \u0644\u0646\u062e\u0631\u062c\u0646\u0643 \u064a\u0627 \u0634\u0639\u064a\u0628 \u0648\u0645\u064e\u0646 \u0645\u0639\u0643 \u0645\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0645\u0646 \u062f\u064a\u0627\u0631\u0646\u0627\u060c \u0625\u0644\u0627 \u0625\u0630\u0627 \u0635\u0631\u062a\u0645 \u0625\u0644\u0649 \u062f\u064a\u0646\u0646\u0627\u060c \u0642\u0627\u0644 \u0634\u064f\u0639\u064a\u0628 \u0645\u0646\u0643\u0631\u064b\u0627 \u0648\u0645\u062a\u0639\u062c\u0628\u064b\u0627 \u0645\u0646 \u0642\u0648\u0644\u0647\u0645: \u0623\u0646\u062a\u0627\u0628\u0639\u0643\u0645 \u0639\u0644\u0649 \u062f\u064a\u0646\u0643\u0645 \u0648\u0645\u0650\u0644\u0651\u064e\u062a\u0643\u0645 \u0627\u0644\u0628\u0627\u0637\u0644\u0629\u060c \u0648\u0644\u0648 \u0643\u0646\u0627 \u0643\u0627\u0631\u0647\u064a\u0646 \u0644\u0647\u0627 \u0644\u0639\u0650\u0644\u0652\u0645\u0650\u0646\u0627 \u0628\u0628\u0637\u0644\u0627\u0646\u0647\u0627\u061f","7:89":"\u0648\u0642\u0627\u0644 \u0634\u0639\u064a\u0628 \u0644\u0642\u0648\u0645\u0647 \u0645\u0633\u062a\u062f\u0631\u0643\u064b\u0627: \u0642\u062f \u0627\u062e\u062a\u0644\u0642\u0646\u0627 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0627\u0644\u0643\u0630\u0628 \u0625\u0646 \u0639\u064f\u062f\u0652\u0646\u0627 \u0625\u0644\u0649 \u062f\u064a\u0646\u0643\u0645 \u0628\u0639\u062f \u0623\u0646 \u0623\u0646\u0642\u0630\u0646\u0627 \u0627\u0644\u0644\u0647 \u0645\u0646\u0647\u060c \u0648\u0644\u064a\u0633 \u0644\u0646\u0627 \u0623\u0646 \u0646\u062a\u062d\u0648\u0644 \u0625\u0644\u0649 \u063a\u064a\u0631 \u062f\u064a\u0646 \u0631\u0628\u0646\u0627 \u0625\u0644\u0627 \u0623\u0646 \u064a\u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u0631\u0628\u0646\u0627\u060c \u0648\u0642\u062f \u0648\u0633\u0639 \u0631\u0628\u0646\u0627 \u0643\u0644 \u0634\u064a\u0621 \u0639\u0644\u0645\u064b\u0627\u060c \u0641\u064a\u0639\u0644\u0645 \u0645\u0627 \u064a\u0635\u0644\u062d \u0644\u0644\u0639\u0628\u0627\u062f\u060c \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0627\u0639\u062a\u0645\u0627\u062f\u0646\u0627 \u0647\u062f\u0627\u064a\u0629 \u0648\u0646\u0635\u0631\u0629\u060c \u0631\u0628\u0646\u0627 \u0627\u062d\u0643\u0645 \u0628\u064a\u0646\u0646\u0627 \u0648\u0628\u064a\u0646 \u0642\u0648\u0645\u0646\u0627 \u0628\u0627\u0644\u062d\u0642\u060c \u0648\u0623\u0646\u062a \u062e\u064a\u0631 \u0627\u0644\u062d\u0627\u0643\u0645\u064a\u0646.","7:90":"\u0648\u0642\u0627\u0644 \u0627\u0644\u0633\u0627\u062f\u0629 \u0648\u0627\u0644\u0643\u0628\u0631\u0627\u0621 \u0627\u0644\u0645\u0643\u0630\u0628\u0648\u0646 \u0627\u0644\u0631\u0627\u0641\u0636\u0648\u0646 \u0644\u062f\u0639\u0648\u0629 \u0627\u0644\u062a\u0648\u062d\u064a\u062f \u0625\u0645\u0639\u0627\u0646\u064b\u0627 \u0641\u064a \u0627\u0644\u0639\u062a\u0648\u0651\u0650 \u0648\u0627\u0644\u062a\u0645\u0631\u062f\u060c \u0645\u062d\u0630\u0631\u064a\u0646 \u0645\u0646 \u0627\u062a\u0628\u0627\u0639 \u0634\u0639\u064a\u0628: \u0644\u0626\u0646 \u0627\u062a\u0628\u0639\u062a\u0645 \u0634\u0639\u064a\u0628\u064b\u0627 \u0625\u0646\u0643\u0645 \u0625\u0630\u064b\u0627 \u0644\u0647\u0627\u0644\u0643\u0648\u0646.","7:91":"\u0641\u0623\u062e\u0630\u064e\u062a\u0652 \u0642\u0648\u0645\u064e \u0634\u0639\u064a\u0628 \u0627\u0644\u0632\u0644\u0632\u0644\u0629\u064f \u0627\u0644\u0634\u062f\u064a\u062f\u0629\u060c \u0641\u0623\u0635\u0628\u062d\u0648\u0627 \u0641\u064a \u062f\u0627\u0631\u0647\u0645 \u0635\u0631\u0639\u0649 \u0645\u064a\u062a\u064a\u0646.","7:92":"\u0627\u0644\u0630\u064a\u0646 \u0643\u0630\u0651\u064e\u0628\u0648\u0627 \u0634\u0639\u064a\u0628\u064b\u0627 \u0643\u0623\u0646\u0647\u0645 \u0644\u0645 \u064a\u0642\u064a\u0645\u0648\u0627 \u0641\u064a \u062f\u064a\u0627\u0631\u0647\u0645\u060c \u0648\u0644\u0645 \u064a\u062a\u0645\u062a\u0639\u0648\u0627 \u0641\u064a\u0647\u0627\u060c \u062d\u064a\u062b \u0627\u0633\u062a\u0624\u0635\u0644\u0648\u0627\u060c \u0641\u0644\u0645 \u064a\u0628\u0642 \u0644\u0647\u0645 \u0623\u062b\u0631\u060c \u0648\u0623\u0635\u0627\u0628\u0647\u0645 \u0627\u0644\u062e\u0633\u0631\u0627\u0646 \u0648\u0627\u0644\u0647\u0644\u0627\u0643 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629.","7:93":"\u0641\u0623\u0639\u0631\u0636 \u0634\u0639\u064a\u0628 \u0639\u0646\u0647\u0645 \u062d\u064a\u0646\u0645\u0627 \u0623\u064a\u0642\u0646 \u0628\u062d\u0644\u0648\u0644 \u0627\u0644\u0639\u0630\u0627\u0628 \u0628\u0647\u0645\u060c \u0648\u0642\u0627\u0644: \u064a\u0627 \u0642\u0648\u0645 \u0644\u0642\u062f \u0623\u0628\u0644\u063a\u062a\u0643\u0645 \u0631\u0633\u0627\u0644\u0627\u062a \u0631\u0628\u064a\u060c \u0648\u0646\u0635\u062d\u062a \u0644\u0643\u0645 \u0628\u0627\u0644\u062f\u062e\u0648\u0644 \u0641\u064a \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u0625\u0642\u0644\u0627\u0639 \u0639\u0645\u0627 \u0623\u0646\u062a\u0645 \u0639\u0644\u064a\u0647\u060c \u0641\u0644\u0645 \u062a\u0633\u0645\u0639\u0648\u0627 \u0648\u0644\u0645 \u062a\u0637\u064a\u0639\u0648\u0627\u060c \u0641\u0643\u064a\u0641 \u0623\u062d\u0632\u0646 \u0639\u0644\u0649 \u0642\u0648\u0645 \u062c\u062d\u062f\u0648\u0627 \u0648\u062d\u062f\u0627\u0646\u064a\u0629 \u0627\u0644\u0644\u0647 \u0648\u0643\u0630\u0628\u0648\u0627 \u0631\u0633\u0644\u0647\u061f","7:94":"\u0648\u0645\u0627 \u0623\u0631\u0633\u0644\u0646\u0627 \u0641\u064a \u0642\u0631\u064a\u0629 \u0645\u0646 \u0646\u0628\u064a \u064a\u062f\u0639\u0648\u0647\u0645 \u0625\u0644\u0649 \u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0644\u0647\u060c \u0648\u064a\u0646\u0647\u0627\u0647\u0645 \u0639\u0645\u0651\u064e\u0627 \u0647\u0645 \u0641\u064a\u0647 \u0645\u0646 \u0627\u0644\u0634\u0631\u0643\u060c \u0641\u0643\u0630\u0651\u064e\u0628\u0647 \u0642\u0648\u0645\u0647\u060c \u0625\u0644\u0627 \u0627\u0628\u062a\u0644\u064a\u0646\u0627\u0647\u0645 \u0628\u0627\u0644\u0628\u0623\u0633\u0627\u0621 \u0648\u0627\u0644\u0636\u0631\u0627\u0621\u060c \u0641\u0623\u0635\u0628\u0646\u0627\u0647\u0645 \u0641\u064a \u0623\u0628\u062f\u0627\u0646\u0647\u0645 \u0628\u0627\u0644\u0623\u0645\u0631\u0627\u0636 \u0648\u0627\u0644\u0623\u0633\u0642\u0627\u0645\u060c \u0648\u0641\u064a \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0628\u0627\u0644\u0641\u0642\u0631 \u0648\u0627\u0644\u062d\u0627\u062c\u0629; \u0631\u062c\u0627\u0621 \u0623\u0646 \u064a\u0633\u062a\u0643\u064a\u0646\u0648\u0627\u060c \u0648\u064a\u0646\u064a\u0628\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u064a\u0631\u062c\u0639\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u062d\u0642.","7:95":"\u062b\u0645 \u0628\u062f\u0651\u064e\u0644\u0646\u0627 \u0627\u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u0637\u064a\u0628\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0645\u0643\u0627\u0646 \u0627\u0644\u062d\u0627\u0644\u0629 \u0627\u0644\u0633\u064a\u0626\u0629\u060c \u0641\u0623\u0635\u0628\u062d\u0648\u0627 \u0641\u064a \u0639\u0627\u0641\u064a\u0629 \u0641\u064a \u0623\u0628\u062f\u0627\u0646\u0647\u0645\u060c \u0648\u0633\u064e\u0639\u064e\u0629 \u0648\u0631\u062e\u0627\u0621 \u0641\u064a \u0623\u0645\u0648\u0627\u0644\u0647\u0645; \u0625\u0645\u0647\u0627\u0644\u0627 \u0644\u0647\u0645\u060c \u0648\u0644\u0639\u0644\u0647\u0645 \u064a\u0634\u0643\u0631\u0648\u0646\u060c \u0641\u0644\u0645 \u064a\u064f\u0641\u0650\u062f \u0645\u0639\u0647\u0645 \u0643\u0644 \u0630\u0644\u0643\u060c \u0648\u0644\u0645 \u064a\u0639\u062a\u0628\u0631\u0648\u0627 \u0648\u0644\u0645 \u064a\u0646\u062a\u0647\u0648\u0627 \u0639\u0645\u0651\u064e\u0627 \u0647\u0645 \u0641\u064a\u0647\u060c \u0648\u0642\u0627\u0644\u0648\u0627: \u0647\u0630\u0647 \u0639\u0627\u062f\u0629 \u0627\u0644\u062f\u0647\u0631 \u0641\u064a \u0623\u0647\u0644\u0647\u060c \u064a\u0648\u0645 \u062e\u064a\u0631 \u0648\u064a\u0648\u0645 \u0634\u0631\u060c \u0648\u0647\u0648 \u0645\u0627 \u062c\u0631\u0649 \u0644\u0622\u0628\u0627\u0626\u0646\u0627 \u0645\u0646 \u0642\u0628\u0644\u060c \u0641\u0623\u062e\u0630\u0646\u0627\u0647\u0645 \u0628\u0627\u0644\u0639\u0630\u0627\u0628 \u0641\u062c\u0623\u0629 \u0648\u0647\u0645 \u0622\u0645\u0646\u0648\u0646\u060c \u0644\u0627 \u064a\u062e\u0637\u0631 \u0644\u0647\u0645 \u0627\u0644\u0647\u0644\u0627\u0643 \u0639\u0644\u0649 \u0628\u0627\u0644.","7:96":"\u0648\u0644\u0648 \u0623\u0646\u0651\u064e \u0623\u0647\u0644 \u0627\u0644\u0642\u0631\u0649 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0631\u0633\u0644\u0647\u0645 \u0648\u0627\u062a\u0628\u0639\u0648\u0647\u0645 \u0648\u0627\u062c\u062a\u0646\u0628\u0648\u0627 \u0645\u0627 \u0646\u0647\u0627\u0647\u0645 \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u060c \u0644\u0641\u062a\u062d \u0627\u0644\u0644\u0647 \u0644\u0647\u0645 \u0623\u0628\u0648\u0627\u0628 \u0627\u0644\u062e\u064a\u0631 \u0645\u0646 \u0643\u0644\u0651\u0650 \u0648\u062c\u0647\u060c \u0648\u0644\u0643\u0646\u0647\u0645 \u0643\u0630\u0651\u064e\u0628\u0648\u0627\u060c \u0641\u0639\u0627\u0642\u0628\u0647\u0645 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0645\u0647\u0644\u0643 \u0628\u0633\u0628\u0628 \u0643\u0641\u0631\u0647\u0645 \u0648\u0645\u0639\u0627\u0635\u064a\u0647\u0645.","7:97":"\u0623\u064a\u0638\u0646 \u0623\u0647\u0644 \u0627\u0644\u0642\u0631\u0649 \u0623\u0646\u0647\u0645 \u0641\u064a \u0645\u0646\u062c\u0627\u0629 \u0648\u0645\u0623\u0645\u0646 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647\u060c \u0623\u0646 \u064a\u0623\u062a\u064a\u0647\u0645 \u0644\u064a\u0644\u0627 \u0648\u0647\u0645 \u0646\u0627\u0626\u0645\u0648\u0646\u061f","7:98":"\u0623\u0648\u064e \u0623\u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0642\u0631\u0649 \u0623\u0646 \u064a\u0623\u062a\u064a\u0647\u0645 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647 \u0648\u0642\u062a \u0627\u0644\u0636\u062d\u0649\u060c \u0648\u0647\u0645 \u063a\u0627\u0641\u0644\u0648\u0646 \u0645\u062a\u0634\u0627\u063a\u0644\u0648\u0646 \u0628\u0623\u0645\u0648\u0631 \u062f\u0646\u064a\u0627\u0647\u0645\u061f \u0648\u062e\u0635\u0651\u064e \u0627\u0644\u0644\u0647 \u0647\u0630\u064a\u0646 \u0627\u0644\u0648\u0642\u062a\u064a\u0646 \u0628\u0627\u0644\u0630\u0643\u0631\u060c \u0644\u0623\u0646 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u064a\u0643\u0648\u0646 \u0623\u063a\u0652\u0641\u064e\u0644 \u0645\u0627 \u064a\u0643\u0648\u0646 \u0641\u064a\u0647\u0645\u0627\u060c \u0641\u0645\u062c\u064a\u0621 \u0627\u0644\u0639\u0630\u0627\u0628 \u0641\u064a\u0647\u0645\u0627 \u0623\u0641\u0638\u0639 \u0648\u0623\u0634\u062f.","7:99":"\u0623\u0641\u0623\u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0642\u0631\u0649 \u0627\u0644\u0645\u0643\u0630\u0628\u0629 \u0645\u064e\u0643\u0652\u0631\u064e \u0627\u0644\u0644\u0647 \u0648\u0625\u0645\u0647\u0627\u0644\u0647 \u0644\u0647\u0645; \u0627\u0633\u062a\u062f\u0631\u0627\u062c\u064b\u0627 \u0644\u0647\u0645 \u0628\u0645\u0627 \u0623\u0646\u0639\u0645 \u0639\u0644\u064a\u0647\u0645 \u0641\u064a \u062f\u0646\u064a\u0627\u0647\u0645 \u0639\u0642\u0648\u0628\u0629 \u0644\u0645\u0643\u0631\u0647\u0645\u061f \u0641\u0644\u0627 \u064a\u0623\u0645\u0646 \u0645\u0643\u0631 \u0627\u0644\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u0647\u0627\u0644\u0643\u0648\u0646.","7:100":"\u0623\u0648\u064e \u0644\u0645 \u064a\u062a\u0628\u064a\u0646 \u0644\u0644\u0630\u064a\u0646 \u0633\u0643\u0646\u0648\u0627 \u0627\u0644\u0623\u0631\u0636 \u0645\u0646 \u0628\u0639\u062f \u0625\u0647\u0644\u0627\u0643 \u0623\u0647\u0644\u0647\u0627 \u0627\u0644\u0633\u0627\u0628\u0642\u064a\u0646 \u0628\u0633\u0628\u0628 \u0645\u0639\u0627\u0635\u064a\u0647\u0645\u060c \u0641\u0633\u0627\u0631\u0648\u0627 \u0633\u064a\u0631\u062a\u0647\u0645\u060c \u0623\u0646 \u0644\u0648 \u0646\u0634\u0627\u0621 \u0623\u0635\u0628\u0646\u0627\u0647\u0645 \u0628\u0633\u0628\u0628 \u0630\u0646\u0648\u0628\u0647\u0645 \u0643\u0645\u0627 \u0641\u0639\u0644\u0646\u0627 \u0628\u0623\u0633\u0644\u0627\u0641\u0647\u0645\u060c \u0648\u0646\u062e\u062a\u0645 \u0639\u0644\u0649 \u0642\u0644\u0648\u0628\u0647\u0645\u060c \u0641\u0644\u0627 \u064a\u062f\u062e\u0644\u0647\u0627 \u0627\u0644\u062d\u0642\u060c \u0648\u0644\u0627 \u064a\u0633\u0645\u0639\u0648\u0646 \u0645\u0648\u0639\u0638\u0629 \u0648\u0644\u0627 \u062a\u0630\u0643\u064a\u0631\u064b\u0627\u061f","7:101":"\u062a\u0644\u0643 \u0627\u0644\u0642\u0631\u0649 \u0627\u0644\u062a\u064a \u062a\u064e\u0642\u064e\u062f\u0651\u064e\u0645 \u0630\u0650\u0643\u0652\u0631\u064f\u0647\u0627\u060c \u0648\u0647\u064a \u0642\u0631\u0649 \u0642\u0648\u0645 \u0646\u0648\u062d \u0648\u0647\u0648\u062f \u0648\u0635\u0627\u0644\u062d \u0648\u0644\u0648\u0637 \u0648\u0634\u0639\u064a\u0628\u060c \u0646\u0642\u0635\u0651\u064f \u0639\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u0646 \u0623\u062e\u0628\u0627\u0631\u0647\u0627\u060c \u0648\u0645\u0627 \u0643\u0627\u0646 \u0645\u0646 \u0623\u064e\u0645\u0652\u0631 \u0631\u0633\u0644 \u0627\u0644\u0644\u0647 \u0627\u0644\u062a\u064a \u0623\u0631\u0633\u0644\u062a \u0625\u0644\u064a\u0647\u0645\u060c \u0645\u0627 \u064a\u062d\u0635\u0644 \u0628\u0647 \u0639\u0628\u0631\u0629 \u0644\u0644\u0645\u0639\u062a\u0628\u0631\u064a\u0646 \u0648\u0627\u0632\u062f\u062c\u0627\u0631 \u0644\u0644\u0638\u0627\u0644\u0645\u064a\u0646. \u0648\u0644\u0642\u062f \u062c\u0627\u0621\u062a \u0623\u0647\u0644\u064e \u0627\u0644\u0642\u0631\u0649 \u0631\u0633\u0644\u0646\u0627 \u0628\u0627\u0644\u062d\u062c\u062c \u0627\u0644\u0628\u064a\u0646\u0627\u062a \u0639\u0644\u0649 \u0635\u062f\u0642\u0647\u0645\u060c \u0641\u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u0644\u064a\u0624\u0645\u0646\u0648\u0627 \u0628\u0645\u0627 \u062c\u0627\u0621\u062a\u0647\u0645 \u0628\u0647 \u0627\u0644\u0631\u0633\u0644; \u0628\u0633\u0628\u0628 \u0637\u063a\u064a\u0627\u0646\u0647\u0645 \u0648\u062a\u0643\u0630\u064a\u0628\u0647\u0645 \u0628\u0627\u0644\u062d\u0642\u060c \u0648\u0645\u062b\u0644 \u062e\u064e\u062a\u0652\u0645\u0650 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0642\u0644\u0648\u0628 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0627\u0644\u0645\u0630\u0643\u0648\u0631\u064a\u0646 \u064a\u062e\u062a\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0642\u0644\u0648\u0628 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0628\u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645.","7:102":"\u0648\u0645\u0627 \u0648\u064e\u062c\u064e\u062f\u0652\u0646\u0627 \u0644\u0623\u0643\u062b\u0631 \u0627\u0644\u0623\u0645\u0645 \u0627\u0644\u0645\u0627\u0636\u064a\u0629 \u0645\u0646 \u0623\u0645\u0627\u0646\u0629 \u0648\u0644\u0627 \u0648\u0641\u0627\u0621 \u0628\u0627\u0644\u0639\u0647\u062f\u060c \u0648\u0645\u0627 \u0648\u062c\u062f\u0646\u0627 \u0623\u0643\u062b\u0631\u0647\u0645 \u0625\u0644\u0627 \u0641\u0633\u0642\u0629 \u0639\u0646 \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u0648\u0627\u0645\u062a\u062b\u0627\u0644 \u0623\u0645\u0631\u0647.","7:103":"\u062b\u0645 \u0628\u0639\u062b\u0646\u0627 \u0645\u0646 \u0628\u0639\u062f \u0627\u0644\u0631\u0633\u0644 \u0627\u0644\u0645\u062a\u0642\u062f\u0645 \u0630\u0650\u0643\u0652\u0631\u0647\u0645 \u0645\u0648\u0633\u0649 \u0628\u0646 \u0639\u0645\u0631\u0627\u0646 \u0628\u0645\u0639\u062c\u0632\u0627\u062a\u0646\u0627 \u0627\u0644\u0628\u064a\u0646\u0629 \u0625\u0644\u0649 \u0641\u0631\u0639\u0648\u0646 \u0648\u0642\u0648\u0645\u0647\u060c \u0641\u062c\u062d\u062f\u0648\u0627 \u0648\u0643\u0641\u0631\u0648\u0627 \u0628\u0647\u0627 \u0638\u0644\u0645\u064b\u0627 \u0645\u0646\u0647\u0645 \u0648\u0639\u0646\u0627\u062f\u064b\u0627\u060c \u0641\u0627\u0646\u0638\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u062a\u0628\u0635\u0631\u064b\u0627 \u0643\u064a\u0641 \u0641\u0639\u0644\u0646\u0627 \u0628\u0647\u0645 \u0648\u0623\u063a\u0631\u0642\u0646\u0627\u0647\u0645 \u0639\u0646 \u0622\u062e\u0631\u0647\u0645 \u0628\u0645\u0631\u0623\u0649 \u0645\u0646 \u0645\u0648\u0633\u0649 \u0648\u0642\u0648\u0645\u0647\u061f \u0648\u062a\u0644\u0643 \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0645\u0641\u0633\u062f\u064a\u0646.","7:104":"\u0648\u0642\u0627\u0644 \u0645\u0648\u0633\u0649 \u0644\u0641\u0631\u0639\u0648\u0646 \u0645\u062d\u0627\u0648\u0631\u064b\u0627 \u0645\u0628\u0644\u0651\u0650\u063a\u064b\u0627: \u0625\u0646\u064a \u0631\u0633\u0648\u0644\u064c \u0645\u0646 \u0627\u0644\u0644\u0647 \u062e\u0627\u0644\u0642 \u0627\u0644\u062e\u0644\u0642 \u0623\u062c\u0645\u0639\u064a\u0646\u060c \u0648\u0645\u062f\u0628\u0651\u0650\u0631 \u0623\u062d\u0648\u0627\u0644\u0647\u0645 \u0648\u0645\u0622\u0644\u0647\u0645.","7:105":"\u062c\u062f\u064a\u0631 \u0628\u0623\u0646 \u0644\u0627 \u0623\u0642\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u062d\u0642\u060c \u0648\u062d\u0631\u064a\u0651\u064c \u0628\u064a \u0623\u0646 \u0623\u0644\u062a\u0632\u0645\u0647\u060c \u0642\u062f \u062c\u0626\u062a\u0643\u0645 \u0628\u0628\u0631\u0647\u0627\u0646 \u0648\u062d\u062c\u0629 \u0628\u0627\u0647\u0631\u0629 \u0645\u0646 \u0631\u0628\u0643\u0645 \u0639\u0644\u0649 \u0635\u0650\u062f\u0652\u0642 \u0645\u0627 \u0623\u0630\u0643\u0631\u0647 \u0644\u0643\u0645\u060c \u0641\u0623\u0637\u0644\u0642 -\u064a\u0627 \u0641\u0631\u0639\u0648\u0646- \u0645\u0639\u064a \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0645\u0650\u0646 \u0623\u064e\u0633\u0652\u0631\u0643 \u0648\u0642\u064e\u0647\u0652\u0631\u0643\u060c \u0648\u062e\u0644\u0651\u0650 \u0633\u0628\u064a\u0644\u0647\u0645 \u0644\u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0644\u0647.","7:106":"\u0642\u0627\u0644 \u0641\u0631\u0639\u0631\u0646 \u0644\u0645\u0648\u0633\u0649: \u0625\u0646 \u0643\u0646\u062a\u064e \u062c\u0626\u062a\u064e \u0628\u0622\u064a\u0629 \u062d\u0633\u0628 \u0632\u0639\u0645\u0643 \u0641\u0623\u062a\u0646\u064a \u0628\u0647\u0627\u060c \u0648\u0623\u062d\u0636\u0631\u0647\u0627 \u0639\u0646\u062f\u064a; \u0644\u062a\u0635\u062d\u0651\u064e \u062f\u0639\u0648\u0627\u0643 \u0648\u064a\u062b\u0628\u062a \u0635\u062f\u0642\u0643\u060c \u0625\u0646 \u0643\u0646\u062a \u0635\u0627\u062f\u0642\u064b\u0627 \u0641\u064a\u0645\u0627 \u0627\u062f\u0651\u064e\u0639\u064a\u062a \u0623\u0646\u0643 \u0631\u0633\u0648\u0644 \u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0646.","7:107":"\u0641\u0623\u0644\u0642\u0649 \u0645\u0648\u0633\u0649 \u0639\u0635\u0627\u0647\u060c \u0641\u062a\u062d\u0648\u0644\u062a \u062d\u064a\u0651\u064e\u0629 \u0639\u0638\u064a\u0645\u0629 \u0638\u0627\u0647\u0631\u0629 \u0644\u0644\u0639\u064a\u0627\u0646.","7:108":"\u0648\u062c\u0630\u0628 \u064a\u062f\u0647 \u0645\u0646 \u062c\u064a\u0628\u0647 \u0623\u0648 \u0645\u0646 \u062c\u0646\u0627\u062d\u0647 \u0641\u0625\u0630\u0627 \u0647\u064a \u0628\u064a\u0636\u0627\u0621 \u0643\u0627\u0644\u0644\u0628\u0646 \u0645\u0646 \u063a\u064a\u0631 \u0628\u0631\u0635 \u0622\u064a\u0629 \u0644\u0641\u0631\u0639\u0648\u0646\u060c \u0641\u0625\u0630\u0627 \u0631\u062f\u0651\u064e\u0647\u0627 \u0639\u0627\u062f\u062a \u0625\u0644\u0649 \u0644\u0648\u0646\u0647\u0627 \u0627\u0644\u0623\u0648\u0644\u060c \u0643\u0633\u0627\u0626\u0631 \u0628\u062f\u0646\u0647.","7:109":"\u0642\u0627\u0644 \u0627\u0644\u0623\u0634\u0631\u0627\u0641 \u0645\u0646 \u0642\u0648\u0645 \u0641\u0631\u0639\u0648\u0646: \u0625\u0646 \u0645\u0648\u0633\u0649 \u0644\u0633\u0627\u062d\u0631 \u064a\u0623\u062e\u0630 \u0628\u0623\u0639\u064a\u0646 \u0627\u0644\u0646\u0627\u0633 \u0628\u062e\u062f\u0627\u0639\u0647 \u0625\u064a\u0627\u0647\u0645\u060c \u062d\u062a\u0649 \u064a\u062e\u064a\u0644 \u0625\u0644\u064a\u0647\u0645 \u0623\u0646 \u0627\u0644\u0639\u0635\u0627 \u062d\u064a\u0629\u060c \u0648\u0627\u0644\u0634\u064a\u0621 \u0628\u062e\u0644\u0627\u0641 \u0645\u0627 \u0647\u0648 \u0639\u0644\u064a\u0647\u060c \u0648\u0647\u0648 \u0648\u0627\u0633\u0639 \u0627\u0644\u0639\u0644\u0645 \u0628\u0627\u0644\u0633\u062d\u0631 \u0645\u0627\u0647\u0631 \u0628\u0647.","7:110":"\u064a\u0631\u064a\u062f \u0623\u0646 \u064a\u062e\u0631\u062c\u0643\u0645 \u062c\u0645\u064a\u0639\u064b\u0627 \u0645\u0646 \u0623\u0631\u0636\u0643\u0645\u060c \u0642\u0627\u0644 \u0641\u0631\u0639\u0648\u0646: \u0641\u0628\u0645\u0627\u0630\u0627 \u062a\u0634\u064a\u0631\u0648\u0646 \u0639\u0644\u064a\u0651\u064e \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0644\u0623 \u0641\u064a \u0623\u0645\u0631 \u0645\u0648\u0633\u0649\u061f","7:111":"\u0642\u0627\u0644 \u0645\u064e\u0646 \u062d\u0636\u0631 \u0645\u0646\u0627\u0638\u0631\u0629 \u0645\u0648\u0633\u0649 \u0645\u0650\u0646 \u0633\u0627\u062f\u0629 \u0642\u0648\u0645 \u0641\u0631\u0639\u0648\u0646 \u0648\u0643\u0628\u0631\u0627\u0626\u0647\u0645: \u0623\u064e\u062e\u0651\u0650\u0631 \u0645\u0648\u0633\u0649 \u0648\u0623\u062e\u0627\u0647 \u0647\u0627\u0631\u0648\u0646\u060c \u0648\u0627\u0628\u0639\u062b \u0641\u064a \u0645\u062f\u0627\u0626\u0646 \xab\u0645\u0635\u0631\xbb \u0648\u0623\u0642\u0627\u0644\u064a\u0645\u0647\u0627 \u0627\u0644\u0634\u0651\u064f\u0631\u064e\u0637.","7:112":"\u0644\u064a\u062c\u0645\u0639\u0648\u0627 \u0644\u0643 \u0643\u0644 \u0633\u0627\u062d\u0631 \u0648\u0627\u0633\u0639 \u0627\u0644\u0639\u0644\u0645 \u0628\u0627\u0644\u0633\u062d\u0631.","7:113":"\u0648\u062c\u0627\u0621 \u0627\u0644\u0633\u062d\u0631\u0629 \u0641\u0631\u0639\u0648\u0646 \u0642\u0627\u0644\u0648\u0627: \u0623\u0626\u0646\u0651\u064e \u0644\u0646\u0627 \u0644\u062c\u0627\u0626\u0632\u0629 \u0648\u0645\u0627\u0644\u0627 \u0625\u0646 \u063a\u064e\u0644\u064e\u0628\u0652\u0646\u0627 \u0645\u0648\u0633\u0649\u061f","7:114":"\u0642\u0627\u0644 \u0641\u0631\u0639\u0648\u0646: \u0646\u0639\u0645 \u0644\u0643\u0645 \u0627\u0644\u0623\u062c\u0631 \u0648\u0627\u0644\u0642\u0631\u0628 \u0645\u0646\u064a \u0625\u0646 \u063a\u064e\u0644\u064e\u0628\u0652\u062a\u064f\u0645\u0648\u0647.","7:115":"\u0642\u0627\u0644 \u0633\u062d\u0631\u0629 \u0641\u0631\u0639\u0648\u0646 \u0644\u0645\u0648\u0633\u0649 \u0639\u0644\u0649 \u0633\u0628\u064a\u0644 \u0627\u0644\u062a\u0643\u0628\u0631 \u0648\u0639\u062f\u0645 \u0627\u0644\u0645\u0628\u0627\u0644\u0627\u0629: \u064a\u0627 \u0645\u0648\u0633\u0649 \u0627\u062e\u062a\u0631 \u0623\u0646 \u062a\u064f\u0644\u0642\u064a \u0639\u0635\u0627\u0643 \u0623\u0648\u0644\u0627 \u0623\u0648 \u0646\u064f\u0644\u0642\u064a \u0646\u062d\u0646 \u0623\u0648\u0644\u0627.","7:116":"\u0642\u0627\u0644 \u0645\u0648\u0633\u0649 \u0644\u0644\u0633\u062d\u0631\u0629: \u0623\u0644\u0642\u0648\u0627 \u0623\u0646\u062a\u0645\u060c \u0641\u0644\u0645\u0627 \u0623\u0644\u0642\u064e\u0648\u0627 \u0627\u0644\u062d\u0628\u0627\u0644 \u0648\u0627\u0644\u0639\u0635\u064a\u0651\u064e \u0633\u062d\u0631\u0648\u0627 \u0623\u0639\u064a\u0646 \u0627\u0644\u0646\u0627\u0633\u060c \u0641\u062e\u064f\u064a\u0651\u0650\u0644 \u0625\u0644\u0649 \u0627\u0644\u0623\u0628\u0635\u0627\u0631 \u0623\u0646 \u0645\u0627 \u0641\u0639\u0644\u0648\u0647 \u062d\u0642\u064a\u0642\u0629\u060c \u0648\u0644\u0645 \u064a\u0643\u0646 \u0625\u0644\u0627 \u0645\u062c\u0631\u062f \u0635\u0646\u0639\u0629 \u0648\u062e\u064a\u0627\u0644\u060c \u0648\u0623\u0631\u0647\u0628\u0648\u0627 \u0627\u0644\u0646\u0627\u0633 \u0625\u0631\u0647\u0627\u0628\u064b\u0627 \u0634\u062f\u064a\u062f\u064b\u0627\u060c \u0648\u062c\u0627\u0624\u0648\u0627 \u0628\u0633\u062d\u0631 \u0642\u0648\u064a \u0643\u062b\u064a\u0631.","7:117":"\u0648\u0623\u0648\u062d\u0649 \u0627\u0644\u0644\u0647 \u0625\u0644\u0649 \u0639\u0628\u062f\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u0648\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0641\u064a \u0630\u0644\u0643 \u0627\u0644\u0645\u0648\u0642\u0641 \u0627\u0644\u0639\u0638\u064a\u0645 \u0627\u0644\u0630\u064a \u0641\u0631\u0651\u064e\u0642 \u0627\u0644\u0644\u0647 \u0641\u064a\u0647 \u0628\u064a\u0646 \u0627\u0644\u062d\u0642 \u0648\u0627\u0644\u0628\u0627\u0637\u0644\u060c \u064a\u0623\u0645\u0631\u0647 \u0628\u0623\u0646 \u064a\u064f\u0644\u0642\u064a \u0645\u0627 \u0641\u064a \u064a\u0645\u064a\u0646\u0647 \u0648\u0647\u064a \u0639\u0635\u0627\u0647\u060c \u0641\u0623\u0644\u0642\u0627\u0647\u0627 \u0641\u0625\u0630\u0627 \u0647\u064a \u062a\u0628\u0644\u0639 \u0645\u0627 \u064a\u0644\u0642\u0648\u0646\u0647\u060c \u0648\u064a\u0648\u0647\u0645\u0648\u0646 \u0627\u0644\u0646\u0627\u0633 \u0623\u0646\u0647 \u062d\u0642 \u0648\u0647\u0648 \u0628\u0627\u0637\u0644.","7:118":"\u0641\u0638\u0647\u0631 \u0627\u0644\u062d\u0642 \u0648\u0627\u0633\u062a\u0628\u0627\u0646 \u0644\u0645\u0646 \u0634\u0647\u062f\u0647 \u0648\u062d\u0636\u0631\u0647 \u0641\u064a \u0623\u0645\u0631 \u0645\u0648\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u0623\u0646\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u064a\u062f\u0639\u0648 \u0625\u0644\u0649 \u0627\u0644\u062d\u0642\u060c \u0648\u0628\u0637\u0644 \u0627\u0644\u0643\u0630\u0628 \u0627\u0644\u0630\u064a \u0643\u0627\u0646\u0648\u0627 \u064a\u0639\u0645\u0644\u0648\u0646\u0647.","7:119":"\u0641\u063a\u064f\u0644\u0650\u0628\u064e \u062c\u0645\u064a\u0639 \u0627\u0644\u0633\u062d\u0631\u0629 \u0641\u064a \u0645\u0643\u0627\u0646 \u0627\u062c\u062a\u0645\u0627\u0639\u0647\u0645\u060c \u0648\u0627\u0646\u0635\u0631\u0641 \u0641\u0631\u0639\u0648\u0646 \u0648\u0642\u0648\u0645\u0647 \u0623\u0630\u0644\u0627\u0621 \u0645\u0642\u0647\u0648\u0631\u064a\u0646 \u0645\u063a\u0644\u0648\u0628\u064a\u0646.","7:120":"\u0648\u062e\u064e\u0631\u0651\u064e \u0627\u0644\u0633\u062d\u0631\u0629 \u0633\u064f\u062c\u0651\u064e\u062f\u064b\u0627 \u0639\u0644\u0649 \u0648\u062c\u0648\u0647\u0647\u0645 \u0644\u0644\u0647 \u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0646 \u0644\u0650\u0645\u064e\u0627 \u0639\u0627\u064a\u0646\u0648\u0627 \u0645\u0646 \u0639\u0638\u064a\u0645 \u0642\u062f\u0631\u0629 \u0627\u0644\u0644\u0647.","7:121":"\u0642\u0627\u0644\u0648\u0627: \u0622\u0645\u0646\u0627 \u0628\u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0646.","7:122":"\u0648\u0647\u0648 \u0631\u0628 \u0645\u0648\u0633\u0649 \u0648\u0647\u0627\u0631\u0648\u0646\u060c \u0648\u0647\u0648 \u0627\u0644\u0630\u064a \u064a\u062c\u0628 \u0623\u0646 \u062a\u0635\u0631\u0641 \u0644\u0647 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0648\u062d\u062f\u0647 \u062f\u0648\u0646 \u0645\u064e\u0646 \u0633\u0648\u0627\u0647.","7:123":"\u0642\u0627\u0644 \u0641\u0631\u0639\u0648\u0646 \u0644\u0644\u0633\u062d\u0631\u0629: \u0622\u0645\u0646\u062a\u0645 \u0628\u0627\u0644\u0644\u0647 \u0642\u0628\u0644 \u0623\u0646 \u0622\u0630\u0646 \u0644\u0643\u0645 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0647\u061f \u0625\u0646 \u0625\u064a\u0645\u0627\u0646\u0643\u0645 \u0628\u0627\u0644\u0644\u0647 \u0648\u062a\u0635\u062f\u064a\u0642\u0643\u0645 \u0644\u0645\u0648\u0633\u0649 \u0648\u0625\u0642\u0631\u0627\u0631\u0643\u0645 \u0628\u0646\u0628\u0648\u062a\u0647 \u0644\u062d\u064a\u0644\u0629 \u0627\u062d\u062a\u0644\u062a\u0645\u0648\u0647\u0627 \u0623\u0646\u062a\u0645 \u0648\u0645\u0648\u0633\u0649; \u0644\u062a\u062e\u0631\u062c\u0648\u0627 \u0623\u0647\u0644 \u0645\u062f\u064a\u0646\u062a\u0643\u0645 \u0645\u0646\u0647\u0627\u060c \u0648\u062a\u0643\u0648\u0646\u0648\u0627 \u0627\u0644\u0645\u0633\u062a\u0623\u062b\u0631\u064a\u0646 \u0628\u062e\u064a\u0631\u0627\u062a\u0647\u0627\u060c \u0641\u0633\u0648\u0641 \u062a\u0639\u0644\u0645\u0648\u0646 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u062d\u0631\u0629- \u0645\u0627 \u064a\u062d\u0644\u0651\u064f \u0628\u0643\u0645 \u0645\u0646 \u0627\u0644\u0639\u0630\u0627\u0628 \u0648\u0627\u0644\u0646\u0643\u0627\u0644.","7:124":"\u0644\u0623\u0642\u0637\u0639\u0646\u0651\u064e \u0623\u064a\u062f\u064a\u0643\u0645 \u0648\u0623\u0631\u062c\u0644\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0633\u062d\u0631\u0629- \u0645\u0646 \u062e\u0644\u0627\u0641: \u0628\u0642\u0637\u0639 \u0627\u0644\u064a\u062f \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0627\u0644\u0631\u062c\u0644 \u0627\u0644\u064a\u0633\u0631\u0649\u060c \u0623\u0648 \u0627\u0644\u064a\u062f \u0627\u0644\u064a\u0633\u0631\u0649 \u0648\u0627\u0644\u0631\u062c\u0644 \u0627\u0644\u064a\u0645\u0646\u0649\u060c \u062b\u0645 \u0644\u0623\u0639\u0644\u0642\u0646\u0651\u064e\u0643\u0645 \u062c\u0645\u064a\u0639\u064b\u0627 \u0639\u0644\u0649 \u062c\u0630\u0648\u0639 \u0627\u0644\u0646\u062e\u0644; \u062a\u0646\u0643\u064a\u0644\u0627 \u0628\u0643\u0645 \u0648\u0625\u0631\u0647\u0627\u0628\u064b\u0627 \u0644\u0644\u0646\u0627\u0633.","7:125":"\u0642\u0627\u0644 \u0627\u0644\u0633\u062d\u0631\u0629 \u0644\u0641\u0631\u0639\u0648\u0646: \u0642\u062f \u062a\u062d\u0642\u0642\u0646\u0627 \u0623\u0646\u0651\u064e\u0627 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0631\u0627\u062c\u0639\u0648\u0646\u060c \u0648\u0623\u0646 \u0639\u0630\u0627\u0628\u0647 \u0623\u0634\u062f \u0645\u0646 \u0639\u0630\u0627\u0628\u0643\u060c \u0641\u0644\u0646\u0635\u0628\u0631\u0646\u0651\u064e \u0627\u0644\u064a\u0648\u0645 \u0639\u0644\u0649 \u0639\u0630\u0627\u0628\u0643; \u0644\u0650\u0646\u0646\u062c\u0648 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629.","7:126":"\u0648\u0644\u0633\u062a\u064e \u062a\u0639\u064a\u0628 \u0645\u0646\u0627 \u0648\u062a\u0646\u0643\u0631 -\u064a\u0627 \u0641\u0631\u0639\u0648\u0646- \u0625\u0644\u0627 \u0625\u064a\u0645\u0627\u0646\u0646\u0627 \u0648\u062a\u0635\u062f\u064a\u0642\u0646\u0627 \u0628\u062d\u062c\u062c \u0631\u0628\u0646\u0627 \u0648\u0623\u062f\u0644\u062a\u0647 \u0627\u0644\u062a\u064a \u062c\u0627\u0621 \u0628\u0647\u0627 \u0645\u0648\u0633\u0649 \u0648\u0644\u0627 \u062a\u0642\u062f\u0631 \u0639\u0644\u0649 \u0645\u062b\u0644\u0647\u0627 \u0623\u0646\u062a \u0648\u0644\u0627 \u0623\u062d\u062f \u0622\u062e\u0631 \u0633\u0648\u0649 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u0644\u0647 \u0645\u0644\u0643 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636\u060c \u0631\u0628\u0646\u0627 \u0623\u064e\u0641\u0650\u0636\u0652 \u0639\u0644\u064a\u0646\u0627 \u0635\u0628\u0631\u064b\u0627 \u0639\u0638\u064a\u0645\u064b\u0627 \u0648\u062b\u0628\u0627\u062a\u0627 \u0639\u0644\u064a\u0647\u060c \u0648\u062a\u0648\u0641\u0651\u064e\u0646\u0627 \u0645\u0646\u0642\u0627\u062f\u064a\u0646 \u0644\u0623\u0645\u0631\u0643 \u0645\u062a\u0628\u0639\u064a\u0646 \u0631\u0633\u0648\u0644\u0643.","7:127":"\u0648\u0642\u0627\u0644 \u0627\u0644\u0633\u0627\u062f\u0629 \u0648\u0627\u0644\u0643\u0628\u0631\u0627\u0621 \u0645\u0646 \u0642\u0648\u0645 \u0641\u0631\u0639\u0648\u0646 \u0644\u0641\u0631\u0639\u0648\u0646: \u0623\u064e\u062a\u064e\u062f\u064e\u0639\u064f \u0645\u0648\u0633\u0649 \u0648\u0642\u0648\u0645\u0647 \u0645\u0646 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0644\u064a\u0641\u0633\u062f\u0648\u0627 \u0627\u0644\u0646\u0627\u0633 \u0641\u064a \u0623\u0631\u0636 \xab\u0645\u0635\u0631\xbb \u0628\u062a\u063a\u064a\u064a\u0631 \u062f\u064a\u0646\u0647\u0645 \u0628\u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647\u060c \u0648\u062a\u0631\u0643 \u0639\u0628\u0627\u062f\u062a\u0643 \u0648\u0639\u0628\u0627\u062f\u0629 \u0622\u0644\u0647\u062a\u0643\u061f \u0642\u0627\u0644 \u0641\u0631\u0639\u0648\u0646: \u0633\u0646\u064f\u0642\u064e\u062a\u0651\u0650\u0644 \u0623\u0628\u0646\u0627\u0621 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0648\u0646\u0633\u062a\u0628\u0642\u064a \u0646\u0633\u0627\u0621\u0647\u0645 \u0623\u062d\u064a\u0627\u0621 \u0644\u0644\u062e\u062f\u0645\u0629\u060c \u0648\u0625\u0646\u0651\u064e\u0627 \u0639\u0627\u0644\u0648\u0646 \u0639\u0644\u064a\u0647\u0645 \u0628\u0642\u0647\u0631 \u0627\u0644\u0645\u064f\u0644\u0652\u0643\u0650 \u0648\u0627\u0644\u0633\u0644\u0637\u0627\u0646.","7:128":"\u0642\u0627\u0644 \u0645\u0648\u0633\u0649 \u0644\u0642\u0648\u0645\u0647 -\u0645\u0646 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644-: \u0627\u0633\u062a\u0639\u064a\u0646\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0641\u0631\u0639\u0648\u0646 \u0648\u0642\u0648\u0645\u0647\u060c \u0648\u0627\u0635\u0628\u0631\u0648\u0627 \u0639\u0644\u0649 \u0645\u0627 \u0646\u0627\u0644\u0643\u0645 \u0645\u0646 \u0641\u0631\u0639\u0648\u0646 \u0645\u0646 \u0627\u0644\u0645\u0643\u0627\u0631\u0647 \u0641\u064a \u0623\u0646\u0641\u0633\u0643\u0645 \u0648\u0623\u0628\u0646\u0627\u0626\u0643\u0645. \u0625\u0646 \u0627\u0644\u0623\u0631\u0636 \u0643\u0644\u0647\u0627 \u0644\u0644\u0647 \u064a\u0648\u0631\u062b\u0647\u0627 \u0645\u0646 \u064a\u0634\u0627\u0621 \u0645\u0646 \u0639\u0628\u0627\u062f\u0647\u060c \u0648\u0627\u0644\u0639\u0627\u0642\u0628\u0629 \u0627\u0644\u0645\u062d\u0645\u0648\u062f\u0629 \u0644\u0645\u0646 \u0627\u062a\u0642\u0649 \u0627\u0644\u0644\u0647 \u0641\u0641\u0639\u0644 \u0623\u0648\u0627\u0645\u0631\u0647 \u0648\u0627\u062c\u062a\u0646\u0628 \u0646\u0648\u0627\u0647\u064a\u0647.","7:129":"\u0642\u0627\u0644 \u0642\u0648\u0645 \u0645\u0648\u0633\u0649 -\u0645\u0646 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644- \u0644\u0646\u0628\u064a\u0647\u0645 \u0645\u0648\u0633\u0649: \u0627\u0628\u062a\u064f\u0644\u064a\u0646\u0627 \u0648\u0623\u064f\u0648\u0630\u064a\u0646\u0627 \u0628\u0630\u0628\u062d \u0623\u0628\u0646\u0627\u0626\u0646\u0627 \u0648\u0627\u0633\u062a\u062d\u064a\u0627\u0621 \u0646\u0633\u0627\u0626\u0646\u0627 \u0639\u0644\u0649 \u064a\u062f \u0641\u0631\u0639\u0648\u0646 \u0648\u0642\u0648\u0645\u0647\u060c \u0645\u0646 \u0642\u0628\u0644 \u0623\u0646 \u062a\u0623\u062a\u064a\u0646\u0627\u060c \u0648\u0645\u0646 \u0628\u0639\u062f \u0645\u0627 \u062c\u0626\u062a\u0646\u0627\u060c \u0642\u0627\u0644 \u0645\u0648\u0633\u0649 \u0644\u0647\u0645: \u0644\u0639\u0644 \u0631\u0628\u0643\u0645 \u0623\u0646 \u064a\u0647\u0644\u0643 \u0639\u062f\u0648\u0643\u0645 \u0641\u0631\u0639\u0648\u0646 \u0648\u0642\u0648\u0645\u0647\u060c \u0648\u064a\u0633\u062a\u062e\u0644\u0641\u0643\u0645 \u0641\u064a \u0623\u0631\u0636\u0647\u0645 \u0628\u0639\u062f \u0647\u0644\u0627\u0643\u0647\u0645\u060c \u0641\u064a\u0646\u0638\u0631 \u0643\u064a\u0641 \u062a\u0639\u0645\u0644\u0648\u0646\u060c \u0647\u0644 \u062a\u0634\u0643\u0631\u0648\u0646 \u0623\u0648 \u062a\u0643\u0641\u0631\u0648\u0646\u061f","7:130":"\u0648\u0644\u0642\u062f \u0627\u0628\u062a\u0644\u064a\u0646\u0627 \u0641\u0631\u0639\u0648\u0646 \u0648\u0642\u0648\u0645\u0647 \u0628\u0627\u0644\u0642\u062d\u0637 \u0648\u0627\u0644\u062c\u062f\u0628\u060c \u0648\u0646\u064e\u0642\u0652\u0635 \u062b\u0645\u0627\u0631\u0647\u0645 \u0648\u063a\u064e\u0644\u0627\u062a\u0647\u0645; \u0644\u064a\u062a\u0630\u0643\u0631\u0648\u0627\u060c \u0648\u064a\u0646\u0632\u062c\u0631\u0648\u0627 \u0639\u0646 \u0636\u0644\u0627\u0644\u0627\u062a\u0647\u0645\u060c \u0648\u064a\u0641\u0632\u0639\u0648\u0627 \u0625\u0644\u0649 \u0631\u0628\u0647\u0645 \u0628\u0627\u0644\u062a\u0648\u0628\u0629.","7:131":"\u0641\u0625\u0630\u0627 \u062c\u0627\u0621 \u0641\u0631\u0639\u0648\u0646\u064e \u0648\u0642\u0648\u0645\u064e\u0647 \u0627\u0644\u062e\u0650\u0635\u0652\u0628\u064f \u0648\u0627\u0644\u0631\u0632\u0642\u064f \u0642\u0627\u0644\u0648\u0627: \u0647\u0630\u0627 \u0644\u0646\u0627 \u0628\u0645\u0627 \u0646\u0633\u062a\u062d\u0642\u0647\u060c \u0648\u0625\u0646 \u064a\u064f\u0635\u0650\u0628\u0652\u0647\u0645 \u062c\u062f\u0628 \u0648\u0642\u062d\u0637 \u064a\u062a\u0634\u0627\u0621\u0645\u0648\u0627\u060c \u0648\u064a\u0642\u0648\u0644\u0648\u0627: \u0647\u0630\u0627 \u0628\u0633\u0628\u0628 \u0645\u0648\u0633\u0649 \u0648\u0645\u064e\u0646 \u0645\u0639\u0647. \u0623\u0644\u0627 \u0625\u0646\u0651\u064e \u0645\u0627 \u064a\u0635\u064a\u0628\u0647\u0645 \u0645\u0646 \u0627\u0644\u062c\u062f\u0628 \u0648\u0627\u0644\u0642\u062d\u0637 \u0625\u0646\u0645\u0627 \u0647\u0648 \u0628\u0642\u0636\u0627\u0621 \u0627\u0644\u0644\u0647 \u0648\u0642\u062f\u0631\u0647\u060c \u0648\u0628\u0633\u0628\u0628 \u0630\u0646\u0648\u0628\u0647\u0645 \u0648\u0643\u0641\u0631\u0647\u0645\u060c \u0648\u0644\u0643\u0646 \u0623\u0643\u062b\u0631 \u0642\u0648\u0645 \u0641\u0631\u0639\u0648\u0646 \u0644\u0627 \u064a\u0639\u0644\u0645\u0648\u0646 \u0630\u0644\u0643; \u0644\u0627\u0646\u063a\u0645\u0627\u0631\u0647\u0645 \u0641\u064a \u0627\u0644\u062c\u0647\u0644 \u0648\u0627\u0644\u0636\u0644\u0627\u0644.","7:132":"\u0648\u0642\u0627\u0644 \u0642\u0648\u0645 \u0641\u0631\u0639\u0648\u0646 \u0644\u0645\u0648\u0633\u0649: \u0623\u064a \u0622\u064a\u0629 \u062a\u0623\u062a\u0650\u0646\u0627 \u0628\u0647\u0627\u060c \u0648\u062f\u0644\u0627\u0644\u0629 \u0648\u062d\u062c\u0629 \u0623\u0642\u0645\u062a\u0647\u0627 \u0644\u062a\u0635\u0631\u0641\u0646\u0627 \u0639\u0645\u0627 \u0646\u062d\u0646 \u0639\u0644\u064a\u0647 \u0645\u0646 \u062f\u064a\u0646 \u0641\u0631\u0639\u0648\u0646\u060c \u0641\u0645\u0627 \u0646\u062d\u0646 \u0644\u0643 \u0628\u0645\u0635\u062f\u0651\u0650\u0642\u064a\u0646.","7:133":"\u0641\u0623\u0631\u0633\u0644\u0646\u0627 \u0639\u0644\u064a\u0647\u0645 \u0633\u064a\u0644\u0627 \u062c\u0627\u0631\u0641\u064b\u0627 \u0623\u063a\u0631\u0642 \u0627\u0644\u0632\u0631\u0648\u0639 \u0648\u0627\u0644\u062b\u0645\u0627\u0631\u060c \u0648\u0623\u0631\u0633\u0644\u0646\u0627 \u0627\u0644\u062c\u0631\u0627\u062f\u060c \u0641\u0623\u0643\u0644 \u0632\u0631\u0648\u0639\u0647\u0645 \u0648\u062b\u0645\u0627\u0631\u0647\u0645 \u0648\u0623\u0628\u0648\u0627\u0628\u0647\u0645 \u0648\u0633\u0642\u0648\u0641\u0647\u0645 \u0648\u062b\u064a\u0627\u0628\u0647\u0645\u060c \u0648\u0623\u0631\u0633\u0644\u0646\u0627 \u0627\u0644\u0642\u064f\u0645\u0651\u064e\u0644 \u0627\u0644\u0630\u064a \u064a\u0641\u0633\u062f \u0627\u0644\u062b\u0645\u0627\u0631 \u0648\u064a\u0642\u0636\u064a \u0639\u0644\u0649 \u0627\u0644\u062d\u064a\u0648\u0627\u0646 \u0648\u0627\u0644\u0646\u0628\u0627\u062a\u060c \u0648\u0623\u0631\u0633\u0644\u0646\u0627 \u0627\u0644\u0636\u0641\u0627\u062f\u0639 \u0641\u0645\u0644\u0623\u062a \u0622\u0646\u064a\u062a\u0647\u0645 \u0648\u0623\u0637\u0639\u0645\u062a\u0647\u0645 \u0648\u0645\u0636\u0627\u062c\u0639\u0647\u0645\u060c \u0648\u0623\u0631\u0633\u0644\u0646\u0627 \u0623\u064a\u0636\u064b\u0627 \u0627\u0644\u062f\u0645 \u0641\u0635\u0627\u0631\u062a \u0623\u0646\u0647\u0627\u0631\u0647\u0645 \u0648\u0622\u0628\u0627\u0631\u0647\u0645 \u062f\u0645\u064b\u0627\u060c \u0648\u0644\u0645 \u064a\u062c\u062f\u0648\u0627 \u0645\u0627\u0621 \u0635\u0627\u0644\u062d\u064b\u0627 \u0644\u0644\u0634\u0631\u0628\u060c \u0647\u0630\u0647 \u0622\u064a\u0627\u062a \u0645\u0646 \u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0642\u062f\u0631 \u0639\u0644\u064a\u0647\u0627 \u063a\u064a\u0631\u0647\u060c \u0645\u0641\u0631\u0642\u0627\u062a \u0628\u0639\u0636\u0647\u0627 \u0639\u0646 \u0628\u0639\u0636\u060c \u0648\u0645\u0639 \u0643\u0644 \u0647\u0630\u0627 \u062a\u0631\u0641\u0651\u064e\u0639 \u0642\u0648\u0645 \u0641\u0631\u0639\u0648\u0646\u060c \u0641\u0627\u0633\u062a\u0643\u0628\u0631\u0648\u0627 \u0639\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647\u060c \u0648\u0643\u0627\u0646\u0648\u0627 \u0642\u0648\u0645\u064b\u0627 \u064a\u0639\u0645\u0644\u0648\u0646 \u0628\u0645\u0627 \u064a\u0646\u0647\u0649 \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0645\u0646 \u0627\u0644\u0645\u0639\u0627\u0635\u064a \u0648\u0627\u0644\u0641\u0633\u0642 \u0639\u062a\u0648\u0651\u064b\u0627 \u0648\u062a\u0645\u0631\u062f\u064b\u0627.","7:134":"\u0648\u0644\u0645\u0627 \u0646\u0632\u0644 \u0627\u0644\u0639\u0630\u0627\u0628 \u0639\u0644\u0649 \u0641\u0631\u0639\u0648\u0646 \u0648\u0642\u0648\u0645\u0647 \u0641\u0632\u0639\u0648\u0627 \u0625\u0644\u0649 \u0645\u0648\u0633\u0649 \u0648\u0642\u0627\u0644\u0648\u0627: \u064a\u0627 \u0645\u0648\u0633\u0649 \u0627\u062f\u0639 \u0644\u0646\u0627 \u0631\u0628\u0643 \u0628\u0645\u0627 \u0623\u0648\u062d\u0649 \u0628\u0647 \u0625\u0644\u064a\u0643 \u0645\u0650\u0646 \u0631\u064e\u0641\u0652\u0639 \u0627\u0644\u0639\u0630\u0627\u0628 \u0628\u0627\u0644\u062a\u0648\u0628\u0629\u060c \u0644\u0626\u0646 \u0631\u0641\u0639\u062a \u0639\u0646\u0627 \u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0630\u064a \u0646\u062d\u0646 \u0641\u064a\u0647 \u0644\u0646\u0635\u062f\u0651\u0650\u0642\u0646\u0651\u064e \u0628\u0645\u0627 \u062c\u0626\u062a \u0628\u0647\u060c \u0648\u0646\u062a\u0628\u0639 \u0645\u0627 \u062f\u0639\u0648\u062a \u0625\u0644\u064a\u0647\u060c \u0648\u0644\u0646\u0637\u0644\u0642\u0646\u0651\u064e \u0645\u0639\u0643 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644\u060c \u0641\u0644\u0627 \u0646\u0645\u0646\u0639\u0647\u0645 \u0645\u0646 \u0623\u0646 \u064a\u0630\u0647\u0628\u0648\u0627 \u062d\u064a\u062b \u0634\u0627\u0624\u0648\u0627.","7:135":"\u0641\u0644\u0645\u0627 \u0631\u0641\u0639 \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645 \u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0630\u0649 \u0623\u0646\u0632\u0644\u0647 \u0628\u0647\u0645 \u0625\u0644\u0649 \u0623\u062c\u0644\u064d \u0647\u0645 \u0628\u0627\u0644\u063a\u0648\u0647 \u0644\u0627 \u0645\u062d\u0627\u0644\u0629 \u0641\u064a\u0639\u0630\u0628\u0648\u0646 \u0641\u064a\u0647\u060c \u0644\u0627 \u064a\u0646\u0641\u0639\u0647\u0645 \u0645\u0627 \u062a\u0642\u062f\u0651\u064e\u0645 \u0644\u0647\u0645 \u0645\u0646 \u0627\u0644\u0625\u0645\u0647\u0627\u0644 \u0648\u0643\u064e\u0634\u0652\u0641\u0650 \u0627\u0644\u0639\u0630\u0627\u0628 \u0625\u0644\u0649 \u062d\u0644\u0648\u0644\u0647\u060c \u0625\u0630\u0627 \u0647\u0645 \u064a\u0646\u0642\u0636\u0648\u0646 \u0639\u0647\u0648\u062f\u0647\u0645 \u0627\u0644\u062a\u064a \u0639\u0627\u0647\u062f\u0648\u0627 \u0639\u0644\u064a\u0647\u0627 \u0631\u0628\u0647\u0645 \u0648\u0645\u0648\u0633\u0649\u060c \u0648\u064a\u0642\u064a\u0645\u0648\u0646 \u0639\u0644\u0649 \u0643\u0641\u0631\u0647\u0645 \u0648\u0636\u0644\u0627\u0644\u0647\u0645.","7:136":"\u0641\u0627\u0646\u062a\u0642\u0645\u0646\u0627 \u0645\u0646\u0647\u0645 \u062d\u064a\u0646 \u062c\u0627\u0621 \u0627\u0644\u0623\u062c\u0644 \u0627\u0644\u0645\u062d\u062f\u062f \u0644\u0625\u0647\u0644\u0627\u0643\u0647\u0645\u060c \u0648\u0630\u0644\u0643 \u0628\u0625\u062d\u0644\u0627\u0644 \u0646\u0642\u0645\u062a\u0646\u0627 \u0639\u0644\u064a\u0647\u0645\u060c \u0648\u0647\u064a \u0625\u063a\u0631\u0627\u0642\u0647\u0645 \u0641\u064a \u0627\u0644\u0628\u062d\u0631; \u0628\u0633\u0628\u0628 \u062a\u0643\u0630\u064a\u0628\u0647\u0645 \u0628\u0627\u0644\u0645\u0639\u062c\u0632\u0627\u062a \u0627\u0644\u062a\u064a \u0638\u0647\u0631\u062a \u0639\u0644\u0649 \u064a\u062f \u0645\u0648\u0633\u0649\u060c \u0648\u0643\u0627\u0646\u0648\u0627 \u0639\u0646 \u0647\u0630\u0647 \u0627\u0644\u0645\u0639\u062c\u0632\u0627\u062a \u063a\u0627\u0641\u0644\u064a\u0646\u060c \u0648\u062a\u0644\u0643 \u0627\u0644\u063a\u0641\u0644\u0629 \u0647\u064a \u0633\u0628\u0628 \u0627\u0644\u062a\u0643\u0630\u064a\u0628.","7:137":"\u0648\u0623\u0648\u0631\u062b\u0646\u0627 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0627\u0644\u0630\u064a\u0646 \u0643\u0627\u0646\u0648\u0627 \u064a\u064f\u0633\u062a\u064e\u0630\u064e\u0644\u0651\u064f\u0648\u0646 \u0644\u0644\u062e\u062f\u0645\u0629\u060c \u0645\u0634\u0627\u0631\u0642 \u0627\u0644\u0623\u0631\u0636 \u0648\u0645\u063a\u0627\u0631\u0628\u0647\u0627 (\u0648\u0647\u064a \u0628\u0644\u0627\u062f \xab\u0627\u0644\u0634\u0627\u0645\xbb ) \u0627\u0644\u062a\u064a \u0628\u0627\u0631\u0643\u0646\u0627 \u0641\u064a\u0647\u0627\u060c \u0628\u0625\u062e\u0631\u0627\u062c \u0627\u0644\u0632\u0631\u0648\u0639 \u0648\u0627\u0644\u062b\u0645\u0627\u0631 \u0648\u0627\u0644\u0623\u0646\u0647\u0627\u0631\u060c \u0648\u062a\u0645\u062a \u0643\u0644\u0645\u0629 \u0631\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0627\u0644\u062d\u0633\u0646\u0649 \u0639\u0644\u0649 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0628\u0627\u0644\u062a\u0645\u0643\u064a\u0646 \u0644\u0647\u0645 \u0641\u064a \u0627\u0644\u0623\u0631\u0636; \u0628\u0633\u0628\u0628 \u0635\u0628\u0631\u0647\u0645 \u0639\u0644\u0649 \u0623\u0630\u0649 \u0641\u0631\u0639\u0648\u0646 \u0648\u0642\u0648\u0645\u0647\u060c \u0648\u062f\u0645\u0651\u064e\u0631\u0646\u0627 \u0645\u0627 \u0643\u0627\u0646 \u064a\u0635\u0646\u0639 \u0641\u0631\u0639\u0648\u0646 \u0648\u0642\u0648\u0645\u0647 \u0645\u0646 \u0627\u0644\u0639\u0645\u0627\u0631\u0627\u062a \u0648\u0627\u0644\u0645\u0632\u0627\u0631\u0639\u060c \u0648\u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u064a\u0628\u0646\u0648\u0646 \u0645\u0646 \u0627\u0644\u0623\u0628\u0646\u064a\u0629 \u0648\u0627\u0644\u0642\u0635\u0648\u0631 \u0648\u063a\u064a\u0631 \u0630\u0644\u0643.","7:138":"\u0648\u0642\u0637\u0639\u0646\u0627 \u0628\u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0627\u0644\u0628\u062d\u0631\u060c \u0641\u0645\u0631\u0651\u064f\u0648\u0627 \u0639\u0644\u0649 \u0642\u0648\u0645 \u064a\u0642\u064a\u0645\u0648\u0646 \u0648\u064a\u0648\u0627\u0638\u0628\u0648\u0646 \u0639\u0644\u0649 \u0639\u0628\u0627\u062f\u0629 \u0623\u0635\u0646\u0627\u0645 \u0644\u0647\u0645\u060c \u0642\u0627\u0644 \u0628\u0646\u0648 \u0625\u0633\u0631\u0627\u0626\u064a\u0644: \u0627\u062c\u0639\u0644 \u0644\u0646\u0627 \u064a\u0627 \u0645\u0648\u0633\u0649 \u0635\u0646\u0645\u064b\u0627 \u0646\u0639\u0628\u062f\u0647 \u0648\u0646\u062a\u062e\u0630\u0647 \u0625\u0644\u0647\u064b\u0627\u060c \u0643\u0645\u0627 \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0642\u0648\u0645 \u0623\u0635\u0646\u0627\u0645 \u064a\u0639\u0628\u062f\u0648\u0646\u0647\u0627\u060c \u0642\u0627\u0644 \u0645\u0648\u0633\u0649 \u0644\u0647\u0645: \u0625\u0646\u0643\u0645 \u0623\u064a\u0647\u0627 \u0627\u0644\u0642\u0648\u0645 \u062a\u062c\u0647\u0644\u0648\u0646 \u0639\u0638\u0645\u0629 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u062a\u0639\u0644\u0645\u0648\u0646 \u0623\u0646 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0644\u0627 \u062a\u0646\u0628\u063a\u064a \u0625\u0644\u0627 \u0644\u0644\u0647 \u0627\u0644\u0648\u0627\u062d\u062f \u0627\u0644\u0642\u0647\u0627\u0631.","7:139":"\u0625\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0642\u064a\u0645\u064a\u0646 \u0639\u0644\u0649 \u0647\u0630\u0647 \u0627\u0644\u0623\u0635\u0646\u0627\u0645 \u0645\u064f\u0647\u0652\u0644\u064e\u0643 \u0645\u0627 \u0647\u0645 \u0641\u064a\u0647 \u0645\u0646 \u0627\u0644\u0634\u0631\u0643\u060c \u0648\u0645\u062f\u0645\u0651\u064e\u0631 \u0648\u0628\u0627\u0637\u0644 \u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u064a\u0639\u0645\u0644\u0648\u0646 \u0645\u0646 \u0639\u0628\u0627\u062f\u062a\u0647\u0645 \u0644\u062a\u0644\u0643 \u0627\u0644\u0623\u0635\u0646\u0627\u0645\u060c \u0627\u0644\u062a\u064a \u0644\u0627 \u062a\u062f\u0641\u0639 \u0639\u0646\u0647\u0645 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647 \u0625\u0630\u0627 \u0646\u0632\u0644 \u0628\u0647\u0645.","7:140":"\u0642\u0627\u0644 \u0645\u0648\u0633\u0649 \u0644\u0642\u0648\u0645\u0647: \u0623\u063a\u064a\u0631 \u0627\u0644\u0644\u0647 \u0623\u0637\u0644\u0628 \u0644\u0643\u0645 \u0645\u0639\u0628\u0648\u062f\u064b\u0627 \u062a\u0639\u0628\u062f\u0648\u0646\u0647 \u0645\u0646 \u062f\u0648\u0646\u0647\u060c \u0648\u0627\u0644\u0644\u0647 \u0647\u0648 \u0627\u0644\u0630\u064a \u062e\u0644\u0642\u0643\u0645\u060c \u0648\u0641\u0636\u0651\u064e\u0644\u0643\u0645 \u0639\u0644\u0649 \u0639\u0627\u0644\u0645\u064a \u0632\u0645\u0627\u0646\u0643\u0645 \u0628\u0643\u062b\u0631\u0629 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0641\u064a\u0643\u0645\u060c \u0648\u0625\u0647\u0644\u0627\u0643 \u0639\u062f\u0648\u0643\u0645 \u0648\u0645\u0627 \u062e\u0635\u0651\u064e\u0643\u0645 \u0628\u0647 \u0645\u0646 \u0627\u0644\u0622\u064a\u0627\u062a\u061f","7:141":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 - \u064a\u0627 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 - \u0646\u0650\u0639\u064e\u0645\u0646\u0627 \u0639\u0644\u064a\u0643\u0645 \u0625\u0630 \u0623\u0646\u0642\u0630\u0646\u0627\u0643\u0645 \u0645\u0646 \u0623\u064e\u0633\u0652\u0631 \u0641\u0631\u0639\u0648\u0646 \u0648\u0622\u0644\u0647\u060c \u0648\u0645\u0627 \u0643\u0646\u062a\u0645 \u0641\u064a\u0647 \u0645\u0646 \u0627\u0644\u0647\u0648\u0627\u0646 \u0648\u0627\u0644\u0630\u0644\u0629 \u0645\u0646 \u062a\u0630\u0628\u064a\u062d \u0623\u0628\u0646\u0627\u0626\u0643\u0645 \u0648\u0627\u0633\u062a\u0628\u0642\u0627\u0621 \u0646\u0633\u0627\u0626\u0643\u0645 \u0644\u0644\u062e\u062f\u0645\u0629 \u0648\u0627\u0644\u0627\u0645\u062a\u0647\u0627\u0646\u060c \u0648\u0641\u064a \u062d\u064e\u0645\u0652\u0644\u0650\u0643\u0645 \u0639\u0644\u0649 \u0623\u0642\u0628\u062d \u0627\u0644\u0639\u0630\u0627\u0628 \u0648\u0623\u0633\u0648\u0626\u0647\u060c \u062b\u0645 \u0625\u0646\u062c\u0627\u0626\u0643\u0645\u060c \u0627\u062e\u062a\u0628\u0627\u0631 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0648\u0646\u0639\u0645\u0629 \u0639\u0638\u064a\u0645\u0629.","7:142":"\u0648\u0648\u0627\u0639\u062f \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0645\u0648\u0633\u0649 \u0644\u0645\u0646\u0627\u062c\u0627\u0629 \u0631\u0628\u0647 \u062b\u0644\u0627\u062b\u064a\u0646 \u0644\u064a\u0644\u0629\u060c \u062b\u0645 \u0632\u0627\u062f\u0647 \u0641\u064a \u0627\u0644\u0623\u062c\u0644 \u0628\u0639\u062f \u0630\u0644\u0643 \u0639\u0634\u0631 \u0644\u064a\u0627\u0644\u060c \u0641\u062a\u0645\u0651\u064e \u0645\u0627 \u0648\u064e\u0642\u0651\u064e\u062a\u064e\u0647 \u0627\u0644\u0644\u0647 \u0644\u0645\u0648\u0633\u0649 \u0644\u062a\u0643\u0644\u064a\u0645\u0647 \u0623\u0631\u0628\u0639\u064a\u0646 \u0644\u064a\u0644\u0629. \u0648\u0642\u0627\u0644 \u0645\u0648\u0633\u0649 \u0644\u0623\u062e\u064a\u0647 \u0647\u0627\u0631\u0648\u0646 -\u062d\u064a\u0646 \u0623\u0631\u0627\u062f \u0627\u0644\u0645\u0636\u064a\u0651\u064e \u0644\u0645\u0646\u0627\u062c\u0627\u0629 \u0631\u0628\u0647-: \u0643\u0646 \u062e\u0644\u064a\u0641\u062a\u064a \u0641\u064a \u0642\u0648\u0645\u064a \u062d\u062a\u0649 \u0623\u0631\u062c\u0639\u060c \u0648\u0623\u062d\u0645\u0650\u0644\u064e\u0647\u0645 \u0639\u0644\u0649 \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u0648\u0639\u0628\u0627\u062f\u062a\u0647\u060c \u0648\u0644\u0627 \u062a\u0633\u0644\u0643\u0652 \u0637\u0631\u064a\u0642 \u0627\u0644\u0630\u064a\u0646 \u064a\u0641\u0633\u062f\u0648\u0646 \u0641\u064a \u0627\u0644\u0623\u0631\u0636.","7:143":"\u0648\u0644\u0645\u0627 \u062c\u0627\u0621 \u0645\u0648\u0633\u0649 \u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0627\u0644\u0645\u062d\u062f\u062f \u0648\u0647\u0648 \u062a\u0645\u0627\u0645 \u0623\u0631\u0628\u0639\u064a\u0646 \u0644\u064a\u0644\u0629\u060c \u0648\u0643\u0644\u0651\u064e\u0645\u0647 \u0631\u0628\u0647 \u0628\u0645\u0627 \u0643\u0644\u0651\u064e\u0645\u0647 \u0645\u0646 \u0648\u062d\u064a\u0647 \u0648\u0623\u0645\u0631\u0647 \u0648\u0646\u0647\u064a\u0647\u060c \u0637\u0645\u0639 \u0641\u064a \u0631\u0624\u064a\u0629 \u0627\u0644\u0644\u0647 \u0641\u0637\u0644\u0628 \u0627\u0644\u0646\u0638\u0631 \u0625\u0644\u064a\u0647\u060c \u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u0644\u0647: \u0644\u0646 \u062a\u0631\u0627\u0646\u064a\u060c \u0623\u064a \u0644\u0646 \u062a\u0642\u062f\u0631 \u0639\u0644\u0649 \u0631\u0624\u064a\u062a\u064a \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0644\u0643\u0646 \u0627\u0646\u0638\u0631 \u0625\u0644\u0649 \u0627\u0644\u062c\u0628\u0644\u060c \u0641\u0625\u0646 \u0627\u0633\u062a\u0642\u0631 \u0645\u0643\u0627\u0646\u0647 \u0625\u0630\u0627 \u062a\u062c\u0644\u0651\u064e\u064a\u062a\u064f \u0644\u0647 \u0641\u0633\u0648\u0641 \u062a\u0631\u0627\u0646\u064a\u060c \u0641\u0644\u0645\u0627 \u062a\u062c\u0644\u0651\u064e\u0649 \u0631\u0628\u0647 \u0644\u0644\u062c\u0628\u0644 \u062c\u0639\u0644\u0647 \u062f\u0643\u0651\u064b\u0627 \u0645\u0633\u062a\u0648\u064a\u064b\u0627 \u0628\u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0633\u0642\u0637 \u0645\u0648\u0633\u0649 \u0645\u063a\u0634\u064a\u0651\u064b\u0627 \u0639\u0644\u064a\u0647\u060c \u0641\u0644\u0645\u0627 \u0623\u0641\u0627\u0642 \u0645\u0646 \u063a\u0634\u064a\u062a\u0647 \u0642\u0627\u0644: \u062a\u0646\u0632\u064a\u0647\u064b\u0627 \u0644\u0643 \u064a\u0627 \u0631\u0628 \u0639\u0645\u0627 \u0644\u0627 \u064a\u0644\u064a\u0642 \u0628\u062c\u0644\u0627\u0644\u0643\u060c \u0625\u0646\u064a \u062a\u0628\u062a \u0625\u0644\u064a\u0643 \u0645\u0646 \u0645\u0633\u0623\u0644\u062a\u064a \u0625\u064a\u0627\u0643 \u0627\u0644\u0631\u0624\u064a\u0629 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0623\u0646\u0627 \u0623\u0648\u0644 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u0643 \u0645\u0646 \u0642\u0648\u0645\u064a.","7:144":"\u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u064a\u0627 \u0645\u0648\u0633\u0649: \u0625\u0646\u064a \u0627\u062e\u062a\u0631\u062a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0646\u0627\u0633 \u0628\u0631\u0633\u0627\u0644\u0627\u062a\u064a \u0625\u0644\u0649 \u062e\u0644\u0642\u064a \u0627\u0644\u0630\u064a\u0646 \u0623\u0631\u0633\u0644\u062a\u0643 \u0625\u0644\u064a\u0647\u0645 \u0648\u0628\u0643\u0644\u0627\u0645\u064a \u0625\u064a\u0627\u0643 \u0645\u0650\u0646 \u063a\u064a\u0631 \u0648\u0633\u0627\u0637\u0629\u060c \u0641\u062e\u0630 \u0645\u0627 \u0623\u0639\u0637\u064a\u062a\u0643 \u0645\u0650\u0646 \u0623\u0645\u0631\u064a \u0648\u0646\u0647\u064a\u064a\u060c \u0648\u062a\u0645\u0633\u0651\u064e\u0643 \u0628\u0647\u060c \u0648\u0627\u0639\u0645\u0644 \u0628\u0647\u060c \u0648\u0643\u0646 \u0645\u0646 \u0627\u0644\u0634\u0627\u0643\u0631\u064a\u0646 \u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0644\u0649 \u0645\u0627 \u0622\u062a\u0627\u0643 \u0645\u0646 \u0631\u0633\u0627\u0644\u062a\u0647\u060c \u0648\u062e\u0635\u0651\u064e\u0643 \u0628\u0643\u0644\u0627\u0645\u0647.","7:145":"\u0648\u0643\u062a\u0628\u0646\u0627 \u0644\u0645\u0648\u0633\u0649 \u0641\u064a \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0645\u0646 \u0643\u0644 \u0645\u0627 \u064a\u062d\u062a\u0627\u062c \u0625\u0644\u064a\u0647 \u0641\u064a \u062f\u064a\u0646\u0647 \u0645\u0646 \u0627\u0644\u0623\u062d\u0643\u0627\u0645\u060c \u0645\u0648\u0639\u0638\u0629 \u0644\u0644\u0627\u0632\u062f\u062c\u0627\u0631 \u0648\u0627\u0644\u0627\u0639\u062a\u0628\u0627\u0631 \u0648\u062a\u0641\u0635\u064a\u0644\u0627 \u0644\u062a\u0643\u0627\u0644\u064a\u0641 \u0627\u0644\u062d\u0644\u0627\u0644 \u0648\u0627\u0644\u062d\u0631\u0627\u0645 \u0648\u0627\u0644\u0623\u0645\u0631 \u0648\u0627\u0644\u0646\u0647\u064a \u0648\u0627\u0644\u0642\u0635\u0635 \u0648\u0627\u0644\u0639\u0642\u0627\u0626\u062f \u0648\u0627\u0644\u0623\u062e\u0628\u0627\u0631 \u0648\u0627\u0644\u0645\u063a\u064a\u0628\u0627\u062a\u060c \u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u0644\u0647: \u0641\u062e\u0630\u0647\u0627 \u0628\u0642\u0648\u0629\u060c \u0623\u064a: \u062e\u0630 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0628\u062c\u062f \u0648\u0627\u062c\u062a\u0647\u0627\u062f\u060c \u0648\u0623\u0645\u0631 \u0642\u0648\u0645\u0643 \u064a\u0639\u0645\u0644\u0648\u0627 \u0628\u0645\u0627 \u0634\u0631\u0639 \u0627\u0644\u0644\u0647 \u0641\u064a\u0647\u0627; \u0641\u0625\u0646 \u0645\u064e\u0646 \u0623\u0634\u0631\u0643 \u0645\u0646\u0647\u0645 \u0648\u0645\u0650\u0646 \u063a\u064a\u0631\u0647\u0645 \u0641\u0625\u0646\u064a \u0633\u0623\u0631\u064a\u0647 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u062f\u0627\u0631 \u0627\u0644\u0641\u0627\u0633\u0642\u064a\u0646\u060c \u0648\u0647\u064a \u0646\u0627\u0631 \u0627\u0644\u0644\u0647 \u0627\u0644\u062a\u064a \u0623\u0639\u062f\u0651\u064e\u0647\u0627 \u0644\u0623\u0639\u062f\u0627\u0626\u0647 \u0627\u0644\u062e\u0627\u0631\u062c\u064a\u0646 \u0639\u0646 \u0637\u0627\u0639\u062a\u0647.","7:146":"\u0633\u0623\u0635\u0631\u0641 \u0639\u0646 \u0641\u064e\u0647\u0652\u0645 \u0627\u0644\u062d\u062c\u062c \u0648\u0627\u0644\u0623\u062f\u0644\u0629 \u0627\u0644\u062f\u0627\u0644\u0629 \u0639\u0644\u0649 \u0639\u0638\u0645\u062a\u064a \u0648\u0634\u0631\u064a\u0639\u062a\u064a \u0648\u0623\u062d\u0643\u0627\u0645\u064a \u0642\u0644\u0648\u0628 \u0627\u0644\u0645\u062a\u0643\u0628\u0631\u064a\u0646 \u0639\u0646 \u0637\u0627\u0639\u062a\u064a\u060c \u0648\u0627\u0644\u0645\u062a\u0643\u0628\u0631\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0646\u0627\u0633 \u0628\u063a\u064a\u0631 \u0627\u0644\u062d\u0642\u060c \u0641\u0644\u0627 \u064a\u062a\u0628\u0639\u0648\u0646 \u0646\u0628\u064a\u064b\u0627 \u0648\u0644\u0627 \u064a\u0635\u063a\u0648\u0646 \u0625\u0644\u064a\u0647 \u0644\u062a\u0643\u0628\u0631\u0647\u0645\u060c \u0648\u0625\u0646\u0652 \u064a\u064e\u0631\u064e \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u062a\u0643\u0628\u0631\u0648\u0646 \u0639\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0643\u0644 \u0622\u064a\u0629 \u0644\u0627 \u064a\u0624\u0645\u0646\u0648\u0627 \u0628\u0647\u0627 \u0644\u0625\u0639\u0631\u0627\u0636\u0647\u0645 \u0648\u0645\u062d\u0627\u062f\u0651\u064e\u062a\u0647\u0645 \u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0625\u0646 \u064a\u0631\u0648\u0627 \u0637\u0631\u064a\u0642 \u0627\u0644\u0635\u0644\u0627\u062d \u0644\u0627 \u064a\u062a\u062e\u0630\u0648\u0647 \u0637\u0631\u064a\u0642\u064b\u0627\u060c \u0648\u0625\u0646 \u064a\u0631\u0648\u0627 \u0637\u0631\u064a\u0642 \u0627\u0644\u0636\u0644\u0627\u0644\u060c \u0623\u064a \u0627\u0644\u0643\u0641\u0631 \u064a\u062a\u062e\u0630\u0648\u0647 \u0637\u0631\u064a\u0642\u064b\u0627 \u0648\u062f\u064a\u0646\u064b\u0627; \u0648\u0630\u0644\u0643 \u0628\u0633\u0628\u0628 \u062a\u0643\u0630\u064a\u0628\u0647\u0645 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0648\u063a\u0641\u0644\u062a\u0647\u0645 \u0639\u0646 \u0627\u0644\u0646\u0638\u0631 \u0641\u064a\u0647\u0627 \u0648\u0627\u0644\u062a\u0641\u0643\u0631 \u0641\u064a \u062f\u0644\u0627\u0644\u0627\u062a\u0647\u0627.","7:147":"\u0648\u0627\u0644\u0630\u064a\u0646 \u0643\u0630\u0651\u064e\u0628\u0648\u0627 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0648\u062d\u062c\u062c\u0647 \u0648\u0628\u0644\u0642\u0627\u0621 \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u062d\u0628\u0637\u062a \u0623\u0639\u0645\u0627\u0644\u0647\u0645; \u0628\u0633\u0628\u0628 \u0641\u064e\u0642\u0652\u062f\u0650 \u0634\u0631\u0637\u0647\u0627\u060c \u0648\u0647\u0648 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u062a\u0635\u062f\u064a\u0642 \u0628\u062c\u0632\u0627\u0626\u0647\u060c \u0645\u0627 \u064a\u062c\u0632\u0648\u0646 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0625\u0644\u0627 \u062c\u0632\u0627\u0621 \u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u064a\u0639\u0645\u0644\u0648\u0646\u0647 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0645\u0646 \u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u0645\u0639\u0627\u0635\u064a\u060c \u0648\u0647\u0648 \u0627\u0644\u062e\u0644\u0648\u062f \u0641\u064a \u0627\u0644\u0646\u0627\u0631.","7:148":"\u0648\u0627\u062a\u062e\u0630 \u0642\u0648\u0645 \u0645\u0648\u0633\u0649 \u0645\u0646 \u0628\u0639\u062f \u0645\u0627 \u0641\u0627\u0631\u0642\u0647\u0645 \u0645\u0627\u0636\u064a\u064b\u0627 \u0644\u0645\u0646\u0627\u062c\u0627\u0629 \u0631\u0628\u0647 \u0645\u0639\u0628\u0648\u062f\u064b\u0627 \u0645\u0650\u0646 \u0630\u0647\u0628\u0647\u0645 \u0639\u0650\u062c\u0644\u0627 \u062c\u0633\u062f\u064b\u0627 \u0628\u0644\u0627 \u0631\u0648\u062d\u060c \u0644\u0647 \u0635\u0648\u062a\u060c \u0623\u0644\u0645 \u064a\u0639\u0644\u0645\u0648\u0627 \u0623\u0646\u0647 \u0644\u0627 \u064a\u0643\u0644\u0645\u0647\u0645\u060c \u0648\u0644\u0627 \u064a\u0631\u0634\u062f\u0647\u0645 \u0625\u0644\u0649 \u062e\u064a\u0631\u061f \u0623\u064e\u0642\u0652\u062f\u064e\u0645\u064f\u0648\u0627 \u0639\u0644\u0649 \u0645\u0627 \u0623\u0642\u062f\u0645\u0648\u0627 \u0639\u0644\u064a\u0647 \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631 \u0627\u0644\u0634\u0646\u064a\u0639\u060c \u0648\u0643\u0627\u0646\u0648\u0627 \u0638\u0627\u0644\u0645\u064a\u0646 \u0644\u0623\u0646\u0641\u0633\u0647\u0645 \u0648\u0627\u0636\u0639\u064a\u0646 \u0627\u0644\u0634\u064a\u0621 \u0641\u064a \u063a\u064a\u0631 \u0645\u0648\u0636\u0639\u0647.","7:149":"\u0648\u0644\u0645\u0627 \u0646\u062f\u0645 \u0627\u0644\u0630\u064a\u0646 \u0639\u0628\u062f\u0648\u0627 \u0627\u0644\u0639\u062c\u0644 \u0645\u0650\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u0639\u0646\u062f \u0631\u062c\u0648\u0639 \u0645\u0648\u0633\u0649 \u0625\u0644\u064a\u0647\u0645\u060c \u0648\u0631\u0623\u0648\u0627 \u0623\u0646\u0647\u0645 \u0642\u062f \u0636\u0644\u0651\u064f\u0648\u0627 \u0639\u0646 \u0642\u0635\u062f \u0627\u0644\u0633\u0628\u064a\u0644\u060c \u0648\u0630\u0647\u0628\u0648\u0627 \u0639\u0646 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647\u060c \u0623\u062e\u0630\u0648\u0627 \u0641\u064a \u0627\u0644\u0625\u0642\u0631\u0627\u0631 \u0628\u0627\u0644\u0639\u0628\u0648\u062f\u064a\u0629 \u0648\u0627\u0644\u0627\u0633\u062a\u063a\u0641\u0627\u0631\u060c \u0641\u0642\u0627\u0644\u0648\u0627: \u0644\u0626\u0646 \u0644\u0645 \u064a\u0631\u062d\u0645\u0646\u0627 \u0631\u0628\u0646\u0627 \u0628\u0642\u064e\u0628\u0648\u0644 \u062a\u0648\u0628\u062a\u0646\u0627\u060c \u0648\u064a\u0633\u062a\u0631 \u0628\u0647\u0627 \u0630\u0646\u0648\u0628\u0646\u0627\u060c \u0644\u0646\u0643\u0648\u0646\u0646 \u0645\u0646 \u0627\u0644\u0647\u0627\u0644\u0643\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0630\u0647\u0628\u062a \u0623\u0639\u0645\u0627\u0644\u0647\u0645.","7:150":"\u0648\u0644\u0645\u0627 \u0631\u062c\u0639 \u0645\u0648\u0633\u0649 \u0625\u0644\u0649 \u0642\u0648\u0645\u0647 \u0645\u0650\u0646 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u063a\u0636\u0628\u0627\u0646 \u062d\u0632\u064a\u0646\u064b\u0627; \u0644\u0623\u0646 \u0627\u0644\u0644\u0647 \u0642\u062f \u0623\u062e\u0628\u0631\u0647 \u0623\u0646\u0647 \u0642\u062f \u0641\u064f\u062a\u0650\u0646 \u0642\u0648\u0645\u0647\u060c \u0648\u0623\u0646 \u0627\u0644\u0633\u0627\u0645\u0631\u064a\u0651\u064e \u0642\u062f \u0623\u0636\u0644\u0651\u064e\u0647\u0645\u060c \u0642\u0627\u0644 \u0645\u0648\u0633\u0649: \u0628\u0626\u0633 \u0627\u0644\u062e\u0644\u0627\u0641\u0629 \u0627\u0644\u062a\u064a \u062e\u0644\u0641\u062a\u0645\u0648\u0646\u064a \u0645\u0650\u0646 \u0628\u0639\u062f\u064a\u060c \u0623\u0639\u062c\u0644\u062a\u0645 \u0623\u064e\u0645\u0652\u0631 \u0631\u0628\u0643\u0645\u061f \u0623\u064a: \u0623\u0633\u062a\u0639\u062c\u0644\u062a\u0645 \u0645\u062c\u064a\u0626\u064a \u0625\u0644\u064a\u0643\u0645 \u0648\u0647\u0648 \u0645\u0642\u062f\u0651\u064e\u0631 \u0645\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u061f \u0648\u0623\u0644\u0642\u0649 \u0645\u0648\u0633\u0649 \u0623\u0644\u0648\u0627\u062d \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u063a\u0636\u0628\u0627 \u0639\u0644\u0649 \u0642\u0648\u0645\u0647 \u0627\u0644\u0630\u064a\u0646 \u0639\u0628\u062f\u0648\u0627 \u0627\u0644\u0639\u062c\u0644\u060c \u0648\u063a\u0636\u0628\u064b\u0627 \u0639\u0644\u0649 \u0623\u062e\u064a\u0647 \u0647\u0627\u0631\u0648\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0628\u0631\u0623\u0633 \u0623\u062e\u064a\u0647 \u064a\u062c\u0631\u0647 \u0625\u0644\u064a\u0647\u060c \u0642\u0627\u0644 \u0647\u0627\u0631\u0648\u0646 \u0645\u0633\u062a\u0639\u0637\u0641\u064b\u0627: \u064a\u0627 \u0627\u0628\u0646 \u0623\u0645\u064a: \u0625\u0646 \u0627\u0644\u0642\u0648\u0645 \u0627\u0633\u062a\u0630\u0644\u0648\u0646\u064a \u0648\u0639\u062f\u0651\u064f\u0648\u0646\u064a \u0636\u0639\u064a\u0641\u064b\u0627 \u0648\u0642\u0627\u0631\u0628\u0648\u0627 \u0623\u0646 \u064a\u0642\u062a\u0644\u0648\u0646\u064a\u060c \u0641\u0644\u0627 \u062a\u064e\u0633\u0631\u0651\u064e \u0627\u0644\u0623\u0639\u062f\u0627\u0621 \u0628\u0645\u0627 \u062a\u0641\u0639\u0644 \u0628\u064a\u060c \u0648\u0644\u0627 \u062a\u062c\u0639\u0644\u0646\u064a \u0641\u064a \u063a\u0636\u0628\u0643 \u0645\u0639 \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u0630\u064a\u0646 \u062e\u0627\u0644\u0641\u0648\u0627 \u0623\u0645\u0631\u0643 \u0648\u0639\u0628\u062f\u0648\u0627 \u0627\u0644\u0639\u062c\u0644.","7:151":"\u0642\u0627\u0644 \u0645\u0648\u0633\u0649 \u0644\u0645\u0627 \u062a\u0628\u064a\u0646 \u0644\u0647 \u0639\u0630\u0631 \u0623\u062e\u064a\u0647\u060c \u0648\u0639\u0644\u0645 \u0623\u0646\u0647 \u0644\u0645 \u064a\u064f\u0641\u064e\u0631\u0651\u0650\u0637 \u0641\u064a\u0645\u0627 \u0643\u0627\u0646 \u0639\u0644\u064a\u0647 \u0645\u0646 \u0623\u0645\u0631 \u0627\u0644\u0644\u0647: \u0631\u0628\u0651\u0650 \u0627\u063a\u0641\u0631 \u0644\u064a \u063a\u0636\u0628\u064a\u060c \u0648\u0627\u063a\u0641\u0631 \u0644\u0623\u062e\u064a \u0645\u0627 \u0633\u0628\u0642 \u0628\u064a\u0646\u0647 \u0648\u0628\u064a\u0646 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644\u060c \u0648\u0623\u062f\u062e\u0644\u0646\u0627 \u0641\u064a \u0631\u062d\u0645\u062a\u0643 \u0627\u0644\u0648\u0627\u0633\u0639\u0629\u060c \u0641\u0625\u0646\u0643 \u0623\u0631\u062d\u0645 \u0628\u0646\u0627 \u0645\u0646 \u0643\u0644 \u0631\u0627\u062d\u0645.","7:152":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u0627\u062a\u062e\u0630\u0648\u0627 \u0627\u0644\u0639\u062c\u0644 \u0625\u0644\u0647\u064b\u0627 \u0633\u064a\u0646\u0627\u0644\u0647\u0645 \u063a\u0636\u0628 \u0634\u062f\u064a\u062f \u0645\u0650\u0646 \u0631\u0628\u0647\u0645 \u0648\u0647\u0648\u0627\u0646 \u0641\u064a \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627; \u0628\u0633\u0628\u0628 \u0643\u0641\u0631\u0647\u0645 \u0628\u0631\u0628\u0647\u0645\u060c \u0648\u0643\u0645\u0627 \u0641\u0639\u0644\u0646\u0627 \u0628\u0647\u0624\u0644\u0627\u0621 \u0646\u0641\u0639\u0644 \u0628\u0627\u0644\u0645\u0641\u062a\u0631\u064a\u0646 \u0627\u0644\u0645\u0628\u062a\u062f\u0639\u064a\u0646 \u0641\u064a \u062f\u064a\u0646 \u0627\u0644\u0644\u0647\u060c \u0641\u0643\u0644 \u0635\u0627\u062d\u0628 \u0628\u062f\u0639\u0629 \u0630\u0644\u064a\u0644.","7:153":"\u0648\u0627\u0644\u0630\u064a\u0646 \u0639\u0645\u0644\u0648\u0627 \u0627\u0644\u0633\u064a\u0626\u0627\u062a \u0645\u0646 \u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u0645\u0639\u0627\u0635\u064a\u060c \u062b\u0645 \u0631\u062c\u0639\u0648\u0627 \u0645\u0650\u0646 \u0628\u0639\u062f \u0641\u0639\u0644\u0647\u0627 \u0625\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u060c \u0625\u0646 \u0631\u0628\u0643 \u0645\u0646 \u0628\u0639\u062f \u0627\u0644\u062a\u0648\u0628\u0629 \u0627\u0644\u0646\u0635\u0648\u062d \u0644\u063a\u0641\u0648\u0631 \u0644\u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u063a\u064a\u0631 \u0641\u0627\u0636\u062d\u0647\u0645 \u0628\u0647\u0627\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645 \u0648\u0628\u0643\u0644 \u0645\u064e\u0646 \u0643\u0627\u0646 \u0645\u062b\u0644\u0647\u0645 \u0645\u0646 \u0627\u0644\u062a\u0627\u0626\u0628\u064a\u0646.","7:154":"\u0648\u0644\u0645\u0627 \u0633\u0643\u0646 \u0639\u0646 \u0645\u0648\u0633\u0649 \u063a\u0636\u0628\u0647 \u0623\u062e\u0630 \u0627\u0644\u0623\u0644\u0648\u0627\u062d \u0628\u0639\u062f \u0623\u0646 \u0623\u0644\u0642\u0627\u0647\u0627 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0641\u064a\u0647\u0627 \u0628\u064a\u0627\u0646 \u0644\u0644\u062d\u0642 \u0648\u0631\u062d\u0645\u0629 \u0644\u0644\u0630\u064a\u0646 \u064a\u062e\u0627\u0641\u0648\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u064a\u062e\u0634\u0648\u0646 \u0639\u0642\u0627\u0628\u0647.","7:155":"\u0648\u0627\u062e\u062a\u0627\u0631 \u0645\u0648\u0633\u0649 \u0645\u0646 \u0642\u0648\u0645\u0647 \u0633\u0628\u0639\u064a\u0646 \u0631\u062c\u0644\u0627 \u0645\u0650\u0646 \u062e\u064a\u0627\u0631\u0647\u0645\u060c \u0648\u062e\u0631\u062c \u0628\u0647\u0645 \u0625\u0644\u0649 \u0637\u0648\u0631 \xab\u0633\u064a\u0646\u0627\u0621\xbb \u0644\u0644\u0648\u0642\u062a \u0648\u0627\u0644\u0623\u062c\u0644 \u0627\u0644\u0630\u064a \u0648\u0627\u0639\u062f\u0647 \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u0644\u0642\u0627\u0647 \u0641\u064a\u0647 \u0628\u0647\u0645 \u0644\u0644\u062a\u0648\u0628\u0629 \u0645\u0645\u0627 \u0643\u0627\u0646 \u0645\u0646 \u0633\u0641\u0647\u0627\u0621 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0645\u0646 \u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0639\u062c\u0644\u060c \u0641\u0644\u0645\u0627 \u0623\u062a\u0648\u0627 \u0630\u0644\u0643 \u0627\u0644\u0645\u0643\u0627\u0646 \u0642\u0627\u0644\u0648\u0627: \u0644\u0646 \u0646\u0624\u0645\u0646 \u0644\u0643 -\u064a\u0627 \u0645\u0648\u0633\u0649- \u062d\u062a\u0649 \u0646\u0631\u0649 \u0627\u0644\u0644\u0647 \u062c\u0647\u0631\u0629 \u0641\u0625\u0646\u0643 \u0642\u062f \u0643\u0644\u0651\u064e\u0645\u062a\u0647 \u0641\u0623\u0631\u0650\u0646\u064e\u0627\u0647\u064f\u060c \u0641\u0623\u062e\u0630\u062a\u0647\u0645 \u0627\u0644\u0632\u0644\u0632\u0644\u0629 \u0627\u0644\u0634\u062f\u064a\u062f\u0629 \u0641\u0645\u0627\u062a\u0648\u0627\u060c \u0641\u0642\u0627\u0645 \u0645\u0648\u0633\u0649 \u064a\u062a\u0636\u0631\u0639 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u064a\u0642\u0648\u0644: \u0631\u0628 \u0645\u0627\u0630\u0627 \u0623\u0642\u0648\u0644 \u0644\u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0625\u0630\u0627 \u0623\u062a\u064a\u062a\u064f\u0647\u0645\u060c \u0648\u0642\u062f \u0623\u0647\u0644\u0643\u062a\u064e \u062e\u064a\u0627\u0631\u0647\u0645\u061f \u0644\u0648 \u0634\u0626\u062a \u0623\u0647\u0644\u0643\u062a\u0647\u0645 \u062c\u0645\u064a\u0639\u064b\u0627 \u0645\u0646 \u0642\u0628\u0644 \u0647\u0630\u0627 \u0627\u0644\u062d\u0627\u0644 \u0648\u0623\u0646\u0627 \u0645\u0639\u0647\u0645\u060c \u0641\u0625\u0646 \u0630\u0644\u0643 \u0623\u062e\u0641 \u0639\u0644\u064a\u0651\u064e\u060c \u0623\u062a\u0647\u0644\u0643\u0646\u0627 \u0628\u0645\u0627 \u0641\u0639\u0644\u0647 \u0633\u0641\u0647\u0627\u0621 \u0627\u0644\u0623\u062d\u0644\u0627\u0645 \u0645\u0646\u0627\u061f \u0645\u0627 \u0647\u0630\u0647 \u0627\u0644\u0641\u0639\u0644\u0629 \u0627\u0644\u062a\u064a \u0641\u0639\u0644\u0647\u0627 \u0642\u0648\u0645\u064a \u0645\u0646 \u0639\u0628\u0627\u062f\u062a\u0647\u0645 \u0627\u0644\u0639\u062c\u0644 \u0625\u0644\u0627 \u0627\u0628\u062a\u0644\u0627\u0621\u064c \u0648\u0627\u062e\u062a\u0628\u0627\u0631\u064c\u060c \u062a\u0636\u0644\u0651\u064f \u0628\u0647\u0627 \u0645\u064e\u0646 \u062a\u0634\u0627\u0621 \u0645\u0650\u0646 \u062e\u0644\u0642\u0643\u060c \u0648\u062a\u0647\u062f\u064a \u0628\u0647\u0627 \u0645\u0646 \u062a\u0634\u0627\u0621 \u0647\u062f\u0627\u064a\u062a\u0647\u060c \u0623\u0646\u062a \u0648\u0644\u064a\u0651\u064f\u0646\u0627 \u0648\u0646\u0627\u0635\u0631\u0646\u0627\u060c \u0641\u0627\u063a\u0641\u0631 \u0630\u0646\u0648\u0628\u0646\u0627\u060c \u0648\u0627\u0631\u062d\u0645\u0646\u0627 \u0628\u0631\u062d\u0645\u062a\u0643\u060c \u0648\u0623\u0646\u062a \u062e\u064a\u0631 \u0645\u064e\u0646 \u0635\u0641\u062d \u0639\u0646 \u062c\u064f\u0631\u0652\u0645\u060c \u0648\u0633\u062a\u0631 \u0639\u0646 \u0630\u0646\u0628.","7:156":"\u0648\u0627\u062c\u0639\u0644\u0646\u0627 \u0645\u0645\u0646 \u0643\u062a\u0628\u062a\u064e \u0644\u0647 \u0627\u0644\u0635\u0627\u0644\u062d\u0627\u062a \u0645\u0646 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0625\u0646\u0627 \u0631\u062c\u0639\u0646\u0627 \u062a\u0627\u0626\u0628\u064a\u0646 \u0625\u0644\u064a\u0643\u060c \u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0644\u0645\u0648\u0633\u0649: \u0639\u0630\u0627\u0628\u064a \u0623\u0635\u064a\u0628 \u0628\u0647 \u0645\u064e\u0646 \u0623\u0634\u0627\u0621 \u0645\u0650\u0646 \u062e\u0644\u0642\u064a\u060c \u0643\u0645\u0627 \u0623\u0635\u0628\u062a\u064f \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u0623\u0635\u0628\u062a\u0647\u0645 \u0645\u0646 \u0642\u0648\u0645\u0643\u060c \u0648\u0631\u062d\u0645\u062a\u064a \u0648\u0633\u0639\u062a \u062e\u0644\u0642\u064a \u0643\u0644\u0651\u064e\u0647\u0645\u060c \u0641\u0633\u0623\u0643\u062a\u0628\u0647\u0627 \u0644\u0644\u0630\u064a\u0646 \u064a\u062e\u0627\u0641\u0648\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u064a\u062e\u0634\u0648\u0646 \u0639\u0642\u0627\u0628\u0647\u060c \u0641\u064a\u0624\u062f\u0648\u0646 \u0641\u0631\u0627\u0626\u0636\u0647\u060c \u0648\u064a\u062c\u062a\u0646\u0628\u0648\u0646 \u0645\u0639\u0627\u0635\u064a\u0647\u060c \u0648\u0627\u0644\u0630\u064a\u0646 \u0647\u0645 \u0628\u062f\u0644\u0627\u0626\u0644 \u0627\u0644\u062a\u0648\u062d\u064a\u062f \u0648\u0628\u0631\u0627\u0647\u064a\u0646\u0647 \u064a\u0635\u062f\u0642\u0648\u0646.","7:157":"\u0647\u0630\u0647 \u0627\u0644\u0631\u062d\u0645\u0629 \u0633\u0623\u0643\u062a\u0628\u0647\u0627 \u0644\u0644\u0630\u064a\u0646 \u064a\u062e\u0627\u0641\u0648\u0646 \u0627\u0644\u0644\u0647 \u0648\u064a\u062c\u062a\u0646\u0628\u0648\u0646 \u0645\u0639\u0627\u0635\u064a\u0647\u060c \u0648\u064a\u062a\u0628\u0639\u0648\u0646 \u0627\u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0646\u0628\u064a \u0627\u0644\u0623\u0645\u064a \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u0642\u0631\u0623 \u0648\u0644\u0627 \u064a\u0643\u062a\u0628\u060c \u0648\u0647\u0648 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0627\u0644\u0630\u064a \u064a\u062c\u062f\u0648\u0646 \u0635\u0641\u062a\u0647 \u0648\u0623\u0645\u0631\u0647 \u0645\u0643\u062a\u0648\u0628\u064e\u064a\u0652\u0646 \u0639\u0646\u062f\u0647\u0645 \u0641\u064a \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644\u060c \u064a\u0623\u0645\u0631\u0647\u0645 \u0628\u0627\u0644\u062a\u0648\u062d\u064a\u062f \u0648\u0627\u0644\u0637\u0627\u0639\u0629 \u0648\u0643\u0644 \u0645\u0627 \u0639\u0631\u0641 \u062d\u064f\u0633\u0652\u0646\u0647\u060c \u0648\u064a\u0646\u0647\u0627\u0647\u0645 \u0639\u0646 \u0627\u0644\u0634\u0631\u0643 \u0648\u0627\u0644\u0645\u0639\u0635\u064a\u0629 \u0648\u0643\u0644 \u0645\u0627 \u0639\u0631\u0641 \u0642\u064f\u0628\u0652\u062d\u0647\u060c \u0648\u064a\u064f\u062d\u0650\u0644\u0651\u064f \u0644\u0647\u0645 \u0627\u0644\u0637\u064a\u0628\u0627\u062a \u0645\u0646 \u0627\u0644\u0645\u0637\u0627\u0639\u0645 \u0648\u0627\u0644\u0645\u0634\u0627\u0631\u0628 \u0648\u0627\u0644\u0645\u0646\u0627\u0643\u062d\u060c \u0648\u064a\u064f\u062d\u0631\u0651\u0650\u0645 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u062e\u0628\u0627\u0626\u062b \u0645\u0646\u0647\u0627 \u0643\u0644\u062d\u0645 \u0627\u0644\u062e\u0646\u0632\u064a\u0631\u060c \u0648\u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u064a\u0633\u062a\u062d\u0644\u0651\u064f\u0648\u0646\u0647 \u0645\u0646 \u0627\u0644\u0645\u0637\u0627\u0639\u0645 \u0648\u0627\u0644\u0645\u0634\u0627\u0631\u0628 \u0627\u0644\u062a\u064a \u062d\u0631\u0651\u064e\u0645\u0647\u0627 \u0627\u0644\u0644\u0647\u060c \u0648\u064a\u0630\u0647\u0628 \u0639\u0646\u0647\u0645 \u0645\u0627 \u0643\u064f\u0644\u0651\u0650\u0641\u0648\u0647 \u0645\u0646 \u0627\u0644\u0623\u0645\u0648\u0631 \u0627\u0644\u0634\u0627\u0642\u0629 \u0643\u0642\u0637\u0639 \u0645\u0648\u0636\u0639 \u0627\u0644\u0646\u062c\u0627\u0633\u0629 \u0645\u0646 \u0627\u0644\u062b\u0648\u0628\u060c \u0648\u0625\u062d\u0631\u0627\u0642 \u0627\u0644\u063a\u0646\u0627\u0626\u0645\u060c \u0648\u0627\u0644\u0642\u0635\u0627\u0635 \u062d\u062a\u0645\u064b\u0627 \u0645\u0646 \u0627\u0644\u0642\u0627\u062a\u0644 \u0639\u0645\u062f\u064b\u0627 \u0643\u0627\u0646 \u0627\u0644\u0642\u062a\u0644 \u0623\u0645 \u062e\u0637\u0623\u060c \u0641\u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0628\u0627\u0644\u0646\u0628\u064a \u0627\u0644\u0623\u0645\u064a \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0623\u0642\u0631\u0648\u0627 \u0628\u0646\u0628\u0648\u062a\u0647\u060c \u0648\u0648\u0642\u0631\u0648\u0647 \u0648\u0639\u0638\u0651\u064e\u0645\u0648\u0647 \u0648\u0646\u0635\u0631\u0648\u0647\u060c \u0648\u0627\u062a\u0628\u0639\u0648\u0627 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0645\u0646\u0632\u0644 \u0639\u0644\u064a\u0647\u060c \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0633\u0646\u062a\u0647\u060c \u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u0641\u0627\u0626\u0632\u0648\u0646 \u0628\u0645\u0627 \u0648\u0639\u062f \u0627\u0644\u0644\u0647 \u0628\u0647 \u0639\u0628\u0627\u062f\u0647 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646.","7:158":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0644\u0646\u0627\u0633 \u0643\u0644\u0647\u0645: \u0625\u0646\u064a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0625\u0644\u064a\u0643\u0645 \u062c\u0645\u064a\u0639\u064b\u0627 \u0644\u0627 \u0625\u0644\u0649 \u0628\u0639\u0636\u0643\u0645 \u062f\u0648\u0646 \u0628\u0639\u0636\u060c \u0627\u0644\u0630\u064a \u0644\u0647 \u0645\u0644\u0643 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0648\u0645\u0627 \u0641\u064a\u0647\u0645\u0627\u060c \u0644\u0627 \u064a\u0646\u0628\u063a\u064a \u0623\u0646 \u062a\u0643\u0648\u0646 \u0627\u0644\u0623\u0644\u0648\u0647\u064a\u0629 \u0648\u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0625\u0644\u0627 \u0644\u0647 \u062c\u0644 \u062b\u0646\u0627\u0624\u0647\u060c \u0627\u0644\u0642\u0627\u062f\u0631 \u0639\u0644\u0649 \u0625\u064a\u062c\u0627\u062f \u0627\u0644\u062e\u0644\u0642 \u0648\u0625\u0641\u0646\u0627\u0626\u0647 \u0648\u0628\u0639\u062b\u0647\u060c \u0641\u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0623\u0642\u0631\u0651\u064f\u0648\u0627 \u0628\u0648\u062d\u062f\u0627\u0646\u064a\u062a\u0647\u060c \u0648\u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0628\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0627\u0644\u0646\u0628\u064a \u0627\u0644\u0623\u0645\u064a\u0651\u0650 \u0627\u0644\u0630\u064a \u064a\u0624\u0645\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0645\u0627 \u0623\u0646\u0632\u0644 \u0625\u0644\u064a\u0647 \u0645\u0646 \u0631\u0628\u0647 \u0648\u0645\u0627 \u0623\u0646\u0632\u0644 \u0639\u0644\u0649 \u0627\u0644\u0646\u0628\u064a\u064a\u0646 \u0645\u0646 \u0642\u0628\u0644\u0647\u060c \u0648\u0627\u062a\u0628\u0639\u0648\u0627 \u0647\u0630\u0627 \u0627\u0644\u0631\u0633\u0648\u0644\u060c \u0648\u0627\u0644\u062a\u0632\u0645\u0648\u0627 \u0627\u0644\u0639\u0645\u0644 \u0628\u0645\u0627 \u0623\u0645\u0631\u0643\u0645 \u0628\u0647 \u0645\u0646 \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647\u060c \u0631\u062c\u0627\u0621 \u0623\u0646 \u062a\u0648\u0641\u0642\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645.","7:159":"\u0648\u0645\u0650\u0646 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0645\u0646 \u0642\u0648\u0645 \u0645\u0648\u0633\u0649 \u062c\u0645\u0627\u0639\u0629 \u064a\u0633\u062a\u0642\u064a\u0645\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u062d\u0642\u060c \u064a\u0647\u062f\u0648\u0646 \u0627\u0644\u0646\u0627\u0633 \u0628\u0647\u060c \u0648\u064a\u0639\u062f\u0644\u0648\u0646 \u0628\u0647 \u0641\u064a \u0627\u0644\u062d\u0643\u0645 \u0641\u064a \u0642\u0636\u0627\u064a\u0627\u0647\u0645.","7:160":"\u0648\u0641\u0631\u0651\u064e\u0642\u0646\u0627 \u0642\u0648\u0645 \u0645\u0648\u0633\u0649 \u0645\u0650\u0646 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0627\u062b\u0646\u062a\u064a \u0639\u0634\u0631\u0629 \u0642\u0628\u064a\u0644\u0629 \u0628\u0639\u062f\u062f \u0627\u0644\u0623\u0633\u0628\u0627\u0637 -\u0648\u0647\u0645 \u0623\u0628\u0646\u0627\u0621 \u064a\u0639\u0642\u0648\u0628- \u0643\u0644 \u0642\u0628\u064a\u0644\u0629 \u0645\u0639\u0631\u0648\u0641\u0629 \u0645\u0646 \u062c\u0647\u0629 \u0646\u0642\u064a\u0628\u0647\u0627. \u0648\u0623\u0648\u062d\u064a\u0646\u0627 \u0625\u0644\u0649 \u0645\u0648\u0633\u0649 \u0625\u0630 \u0637\u0644\u0628 \u0645\u0646\u0647 \u0642\u0648\u0645\u0647 \u0627\u0644\u0633\u0642\u064a\u0627 \u062d\u064a\u0646 \u0639\u0637\u0634\u0648\u0627 \u0641\u064a \u0627\u0644\u062a\u0651\u0650\u064a\u0652\u0647: \u0623\u0646 \u0627\u0636\u0631\u0628 \u0628\u0639\u0635\u0627\u0643 \u0627\u0644\u062d\u062c\u0631\u060c \u0641\u0636\u0631\u0628\u0647\u060c \u0641\u0627\u0646\u0641\u062c\u0631\u062a \u0645\u0646\u0647 \u0627\u062b\u0646\u062a\u0627 \u0639\u0634\u0631\u0629 \u0639\u064a\u0646\u064b\u0627 \u0645\u0646 \u0627\u0644\u0645\u0627\u0621\u060c \u0642\u062f \u0639\u0644\u0645\u062a \u0643\u0644 \u0642\u0628\u064a\u0644\u0629 \u0645\u0646 \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0627\u0644\u0627\u062b\u0646\u062a\u064a \u0639\u0634\u0631\u0629 \u0645\u0634\u0631\u0628\u0647\u0645\u060c \u0644\u0627 \u062a\u062f\u062e\u0644 \u0642\u0628\u064a\u0644\u0629 \u0639\u0644\u0649 \u063a\u064a\u0631\u0647\u0627 \u0641\u064a \u0634\u0631\u0628\u0647\u0627\u060c \u0648\u0638\u0644\u0651\u064e\u0644\u0646\u0627 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0633\u062d\u0627\u0628\u060c \u0648\u0623\u0646\u0632\u0644\u0646\u0627 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0645\u0646\u0651\u064e -\u0648\u0647\u0648 \u0634\u064a\u0621 \u064a\u0634\u0628\u0647 \u0627\u0644\u0635\u0651\u064e\u0645\u063a\u060c \u0637\u0639\u0645\u0647 \u0643\u0627\u0644\u0639\u0633\u0644- \u0648\u0627\u0644\u0633\u0644\u0648\u0649\u060c \u0648\u0647\u0648 \u0637\u0627\u0626\u0631 \u064a\u0634\u0628\u0647 \u0627\u0644\u0633\u0651\u064f\u0645\u064e\u0627\u0646\u064e\u0649\u060c \u0648\u0642\u0644\u0646\u0627 \u0644\u0647\u0645: \u0643\u0644\u0648\u0627 \u0645\u0646 \u0637\u064a\u0628\u0627\u062a \u0645\u0627 \u0631\u0632\u0642\u0646\u0627\u0643\u0645\u060c \u0641\u0643\u0631\u0647\u0648\u0627 \u0630\u0644\u0643 \u0648\u0645\u0644\u0651\u064f\u0648\u0647 \u0645\u0646 \u0637\u0648\u0644 \u0627\u0644\u0645\u062f\u0627\u0648\u0645\u0629 \u0639\u0644\u064a\u0647\u060c \u0648\u0642\u0627\u0644\u0648\u0627: \u0644\u0646 \u0646\u0635\u0628\u0631 \u0639\u0644\u0649 \u0637\u0639\u0627\u0645 \u0648\u0627\u062d\u062f\u060c \u0648\u0637\u0644\u0628\u0648\u0627 \u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u0627\u0644\u0630\u064a \u0647\u0648 \u0623\u062f\u0646\u0649 \u0628\u0627\u0644\u0630\u064a \u0647\u0648 \u062e\u064a\u0631. \u0648\u0645\u0627 \u0638\u0644\u0645\u0648\u0646\u0627 \u062d\u064a\u0646 \u0644\u0645 \u064a\u0634\u0643\u0631\u0648\u0627 \u0644\u0644\u0647\u060c \u0648\u0644\u0645 \u064a\u0642\u0648\u0645\u0648\u0627 \u0628\u0645\u0627 \u0623\u0648\u062c\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645\u060c \u0648\u0644\u0643\u0646 \u0643\u0627\u0646\u0648\u0627 \u0623\u0646\u0641\u0633\u0647\u0645 \u064a\u0638\u0644\u0645\u0648\u0646; \u0625\u0630 \u0641\u0648\u0651\u064e\u062a\u0648\u0627 \u0639\u0644\u064a\u0647\u0627 \u0643\u0644 \u062e\u064a\u0631\u060c \u0648\u0639\u0631\u0651\u064e\u0636\u0648\u0647\u0627 \u0644\u0644\u0634\u0631 \u0648\u0627\u0644\u0646\u0642\u0645\u0629.","7:161":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0639\u0635\u064a\u0627\u0646 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0644\u0631\u0628\u0647\u0645 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0648\u0644\u0646\u0628\u064a\u0647\u0645 \u0645\u0648\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u062a\u0628\u062f\u064a\u0644\u0647\u0645 \u0627\u0644\u0642\u0648\u0644 \u0627\u0644\u0630\u064a \u0623\u0645\u0631\u0648\u0627 \u0623\u0646 \u064a\u0642\u0648\u0644\u0648\u0647 \u062d\u064a\u0646 \u0642\u0627\u0644 \u0627\u0644\u0644\u0647 \u0644\u0647\u0645: \u0627\u0633\u0643\u0646\u0648\u0627 \u0642\u0631\u064a\u0629 \xab\u0628\u064a\u062a \u0627\u0644\u0645\u0642\u062f\u0633\xbb \u060c \u0648\u0643\u0644\u0648\u0627 \u0645\u0646 \u062b\u0645\u0627\u0631\u0647\u0627 \u0648\u062d\u0628\u0648\u0628\u0647\u0627 \u0648\u0646\u0628\u0627\u062a\u0647\u0627 \u0623\u064a\u0646 \u0634\u0626\u062a\u0645 \u0648\u0645\u062a\u0649 \u0634\u0626\u062a\u0645\u060c \u0648\u0642\u0648\u0644\u0648\u0627: \u062d\u064f\u0637\u0651\u064e \u0639\u0646\u0627 \u0630\u0646\u0648\u0628\u0646\u0627\u060c \u0648\u0627\u062f\u062e\u0644\u0648\u0627 \u0627\u0644\u0628\u0627\u0628 \u062e\u0627\u0636\u0639\u064a\u0646 \u0644\u0644\u0647\u060c \u0646\u063a\u0641\u0631 \u0644\u0643\u0645 \u062e\u0637\u0627\u064a\u0627\u0643\u0645\u060c \u0641\u0644\u0627 \u0646\u0624\u0627\u062e\u0630\u0643\u0645 \u0639\u0644\u064a\u0647\u0627\u060c \u0648\u0633\u0646\u0632\u064a\u062f \u0627\u0644\u0645\u062d\u0633\u0646\u064a\u0646 \u0645\u0650\u0646 \u062e\u064e\u064a\u0652\u0631\u064e\u064a\u0650 \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629.","7:162":"\u0641\u063a\u064a\u0651\u064e\u0631 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0645\u0646\u0647\u0645 \u0645\u0627 \u0623\u0645\u0631\u0647\u0645 \u0627\u0644\u0644\u0647 \u0628\u0647 \u0645\u0646 \u0627\u0644\u0642\u0648\u0644\u060c \u0648\u062f\u062e\u0644\u0648\u0627 \u0627\u0644\u0628\u0627\u0628 \u064a\u0632\u062d\u0641\u0648\u0646 \u0639\u0644\u0649 \u0623\u0633\u062a\u0627\u0647\u0647\u0645\u060c \u0648\u0642\u0627\u0644\u0648\u0627: \u062d\u0628\u0629 \u0641\u064a \u0634\u0639\u0631\u0629\u060c \u0641\u0623\u0631\u0633\u0644\u0646\u0627 \u0639\u0644\u064a\u0647\u0645 \u0639\u0630\u0627\u0628\u064b\u0627 \u0645\u0646 \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u0623\u0647\u0644\u0643\u0646\u0627\u0647\u0645 \u0628\u0647; \u0628\u0633\u0628\u0628 \u0638\u0644\u0645\u0647\u0645 \u0648\u0639\u0635\u064a\u0627\u0646\u0647\u0645.","7:163":"\u0648\u0627\u0633\u0623\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u064a\u0647\u0648\u062f \u0639\u0646 \u062e\u0628\u0631 \u0623\u0647\u0644 \u0627\u0644\u0642\u0631\u064a\u0629 \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u062a \u0628\u0642\u0631\u0628 \u0627\u0644\u0628\u062d\u0631\u060c \u0625\u0630 \u064a\u0639\u062a\u062f\u064a \u0623\u0647\u0644\u0647\u0627 \u0641\u064a \u064a\u0648\u0645 \u0627\u0644\u0633\u0628\u062a \u0639\u0644\u0649 \u062d\u0631\u0645\u0627\u062a \u0627\u0644\u0644\u0647\u060c \u062d\u064a\u062b \u0623\u0645\u0631\u0647\u0645 \u0623\u0646 \u064a\u0639\u0638\u0645\u0648\u0627 \u064a\u0648\u0645 \u0627\u0644\u0633\u0628\u062a \u0648\u0644\u0627 \u064a\u0635\u064a\u062f\u0648\u0627 \u0641\u064a\u0647 \u0633\u0645\u0643\u064b\u0627\u060c \u0641\u0627\u0628\u062a\u0644\u0627\u0647\u0645 \u0627\u0644\u0644\u0647 \u0648\u0627\u0645\u062a\u062d\u0646\u0647\u0645; \u0641\u0643\u0627\u0646\u062a \u062d\u064a\u062a\u0627\u0646\u0647\u0645 \u062a\u0623\u062a\u064a\u0647\u0645 \u064a\u0648\u0645 \u0627\u0644\u0633\u0628\u062a \u0643\u062b\u064a\u0631\u0629 \u0637\u0627\u0641\u064a\u0629 \u0639\u0644\u0649 \u0648\u062c\u0647 \u0627\u0644\u0628\u062d\u0631\u060c \u0648\u0625\u0630\u0627 \u0630\u0647\u0628 \u064a\u0648\u0645 \u0627\u0644\u0633\u0628\u062a \u062a\u0630\u0647\u0628 \u0627\u0644\u062d\u064a\u062a\u0627\u0646 \u0641\u064a \u0627\u0644\u0628\u062d\u0631\u060c \u0648\u0644\u0627 \u064a\u0631\u0648\u0646 \u0645\u0646\u0647\u0627 \u0634\u064a\u0626\u064b\u0627\u060c \u0641\u0643\u0627\u0646\u0648\u0627 \u064a\u062d\u062a\u0627\u0644\u0648\u0646 \u0639\u0644\u0649 \u062d\u0628\u0633\u0647\u0627 \u0641\u064a \u064a\u0648\u0645 \u0627\u0644\u0633\u0628\u062a \u0641\u064a \u062d\u0641\u0627\u0626\u0631\u060c \u0648\u064a\u0635\u0637\u0627\u062f\u0648\u0646\u0647\u0627 \u0628\u0639\u062f\u0647. \u0648\u0643\u0645\u0627 \u0648\u0635\u0641\u0646\u0627 \u0644\u0643\u0645 \u0645\u0646 \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631 \u0648\u0627\u0644\u0627\u0628\u062a\u0644\u0627\u0621\u060c \u0644\u0625\u0638\u0647\u0627\u0631 \u0627\u0644\u0633\u0645\u0643 \u0639\u0644\u0649 \u0638\u0647\u0631 \u0627\u0644\u0645\u0627\u0621 \u0641\u064a \u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0645\u062d\u0631\u0645 \u0639\u0644\u064a\u0647\u0645 \u0635\u064a\u062f\u0647 \u0641\u064a\u0647\u060c \u0648\u0625\u062e\u0641\u0627\u0626\u0647 \u0639\u0644\u064a\u0647\u0645 \u0641\u064a \u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0645\u062d\u0644\u0644 \u0644\u0647\u0645 \u0641\u064a\u0647 \u0635\u064a\u062f\u0647\u060c \u0643\u0630\u0644\u0643 \u0646\u062e\u062a\u0628\u0631\u0647\u0645 \u0628\u0633\u0628\u0628 \u0641\u0633\u0642\u0647\u0645 \u0639\u0646 \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u0648\u062e\u0631\u0648\u062c\u0647\u0645 \u0639\u0646\u0647\u0627.","7:164":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0625\u0630 \u0642\u0627\u0644\u062a \u062c\u0645\u0627\u0639\u0629 \u0645\u0646\u0647\u0645 \u0644\u062c\u0645\u0627\u0639\u0629 \u0623\u062e\u0631\u0649 \u0643\u0627\u0646\u062a \u062a\u0639\u0638 \u0627\u0644\u0645\u0639\u062a\u062f\u064a\u0646 \u0641\u064a \u064a\u0648\u0645 \u0627\u0644\u0633\u0628\u062a\u060c \u0648\u062a\u0646\u0647\u0627\u0647\u0645 \u0639\u0646 \u0645\u0639\u0635\u064a\u0629 \u0627\u0644\u0644\u0647 \u0641\u064a\u0647: \u0644\u0650\u0645\u064e \u062a\u0639\u0638\u0648\u0646 \u0642\u0648\u0645\u064b\u0627 \u0627\u0644\u0644\u0647 \u0645\u0647\u0644\u0643\u0647\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0628\u0645\u0639\u0635\u064a\u062a\u0647\u0645 \u0625\u064a\u0627\u0647 \u0623\u0648 \u0645\u0639\u0630\u0628\u0647\u0645 \u0639\u0630\u0627\u0628\u0627 \u0634\u062f\u064a\u062f\u064b\u0627 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629\u061f \u0642\u0627\u0644 \u0627\u0644\u0630\u064a\u0646 \u0643\u0627\u0646\u0648\u0627 \u064a\u0646\u0647\u064e\u0648\u0652\u0646\u0647\u0645 \u0639\u0646 \u0645\u0639\u0635\u064a\u0629 \u0627\u0644\u0644\u0647: \u0646\u064e\u0639\u0650\u0638\u0647\u0645 \u0648\u0646\u0646\u0647\u0627\u0647\u0645 \u0644\u0650\u0646\u064f\u0639\u0652\u0630\u064e\u0631 \u0641\u064a\u0647\u0645\u060c \u0648\u0646\u0624\u062f\u064a \u0641\u0631\u0636 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0646\u0627 \u0641\u064a \u0627\u0644\u0623\u0645\u0631 \u0628\u0627\u0644\u0645\u0639\u0631\u0648\u0641 \u0648\u0627\u0644\u0646\u0647\u064a \u0639\u0646 \u0627\u0644\u0645\u0646\u0643\u0631\u060c \u0648\u0631\u062c\u0627\u0621 \u0623\u0646 \u064a\u062a\u0642\u0648\u0627 \u0627\u0644\u0644\u0647\u060c \u0641\u064a\u062e\u0627\u0641\u0648\u0647\u060c \u0648\u064a\u062a\u0648\u0628\u0648\u0627 \u0645\u0646 \u0645\u0639\u0635\u064a\u062a\u0647\u0645 \u0631\u0628\u0647\u0645 \u0648\u062a\u0639\u0630\u0651\u0650\u064a\u0647\u0645 \u0639\u0644\u0649 \u0645\u0627 \u062d\u0631\u0651\u064e\u0645 \u0639\u0644\u064a\u0647\u0645.","7:165":"\u0641\u0644\u0645\u0627 \u062a\u0631\u0643\u062a \u0627\u0644\u0637\u0627\u0626\u0641\u0629 \u0627\u0644\u062a\u064a \u0627\u0639\u062a\u062f\u062a \u0641\u064a \u064a\u0648\u0645 \u0627\u0644\u0633\u0628\u062a \u0645\u0627 \u0630\u064f\u0643\u0651\u0650\u0631\u062a \u0628\u0647\u060c \u0648\u0627\u0633\u062a\u0645\u0631\u062a \u0639\u0644\u0649 \u063a\u064a\u0651\u0650\u0647\u0627 \u0648\u0627\u0639\u062a\u062f\u0627\u0626\u0647\u0627 \u0641\u064a\u0647\u060c \u0648\u0644\u0645 \u062a\u0633\u062a\u062c\u0628 \u0644\u0645\u0627 \u0648\u064e\u0639\u064e\u0638\u064e\u062a\u0652\u0647\u0627 \u0628\u0647 \u0627\u0644\u0637\u0627\u0626\u0641\u0629 \u0627\u0644\u0648\u0627\u0639\u0638\u0629\u060c \u0623\u0646\u062c\u0649 \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a\u0646 \u064a\u0646\u0647\u0648\u0646 \u0639\u0646 \u0645\u0639\u0635\u064a\u062a\u0647\u060c \u0648\u0623\u062e\u0630 \u0627\u0644\u0630\u064a\u0646 \u0627\u0639\u062a\u062f\u064e\u0648\u0652\u0627 \u0641\u064a \u064a\u0648\u0645 \u0627\u0644\u0633\u0628\u062a \u0628\u0639\u0630\u0627\u0628 \u0623\u0644\u064a\u0645 \u0634\u062f\u064a\u062f; \u0628\u0633\u0628\u0628 \u0645\u062e\u0627\u0644\u0641\u062a\u0647\u0645 \u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u0648\u062e\u0631\u0648\u062c\u0647\u0645 \u0639\u0646 \u0637\u0627\u0639\u062a\u0647.","7:166":"\u0641\u0644\u0645\u0627 \u062a\u0645\u0631\u062f\u062a \u062a\u0644\u0643 \u0627\u0644\u0637\u0627\u0626\u0641\u0629\u060c \u0648\u062a\u062c\u0627\u0648\u0632\u062a \u0645\u0627 \u0646\u0647\u0627\u0647\u0627 \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0645\u0646 \u0639\u062f\u0645 \u0627\u0644\u0635\u064a\u062f \u0641\u064a \u064a\u0648\u0645 \u0627\u0644\u0633\u0628\u062a\u060c \u0642\u0627\u0644 \u0644\u0647\u0645 \u0627\u0644\u0644\u0647: \u0643\u0648\u0646\u0648\u0627 \u0642\u0631\u062f\u0629 \u062e\u0627\u0633\u0626\u064a\u0646 \u0645\u0628\u0639\u062f\u064a\u0646 \u0645\u0646 \u0643\u0644 \u062e\u064a\u0631\u060c \u0641\u0643\u0627\u0646\u0648\u0627 \u0643\u0630\u0644\u0643.","7:167":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0625\u0630 \u0639\u0644\u0645 \u0630\u0644\u0643 \u0625\u0639\u0644\u0627\u0645\u064b\u0627 \u0635\u0631\u064a\u062d\u064b\u0627 \u0644\u064a\u0628\u0639\u062b\u0646 \u0639\u0644\u0649 \u0627\u0644\u064a\u0647\u0648\u062f \u0645\u064e\u0646 \u064a\u0630\u064a\u0642\u0647\u0645 \u0633\u0648\u0621 \u0627\u0644\u0639\u0630\u0627\u0628 \u0648\u0627\u0644\u0625\u0630\u0644\u0627\u0644 \u0625\u0644\u0649 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629. \u0625\u0646 \u0631\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0633\u0631\u064a\u0639 \u0627\u0644\u0639\u0642\u0627\u0628 \u0644\u0650\u0645\u064e\u0646 \u0627\u0633\u062a\u062d\u0642\u0647 \u0628\u0633\u0628\u0628 \u0643\u0641\u0631\u0647 \u0648\u0645\u0639\u0635\u064a\u062a\u0647\u060c \u0648\u0625\u0646\u0647 \u0644\u063a\u0641\u0648\u0631 \u0639\u0646 \u0630\u0646\u0648\u0628 \u0627\u0644\u062a\u0627\u0626\u0628\u064a\u0646\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","7:168":"\u0648\u0641\u0631\u0651\u064e\u0642\u0646\u0627 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u062c\u0645\u0627\u0639\u0627\u062a\u060c \u0645\u0646\u0647\u0645 \u0627\u0644\u0642\u0627\u0626\u0645\u0648\u0646 \u0628\u062d\u0642\u0648\u0642 \u0627\u0644\u0644\u0647 \u0648\u062d\u0642\u0648\u0642 \u0639\u0628\u0627\u062f\u0647\u060c \u0648\u0645\u0646\u0647\u0645 \u0627\u0644\u0645\u0642\u0635\u0651\u0650\u0631\u0648\u0646 \u0627\u0644\u0638\u0627\u0644\u0645\u0648\u0646 \u0644\u0623\u0646\u0641\u0633\u0647\u0645\u060c \u0648\u0627\u062e\u062a\u0628\u0631\u0646\u0627 \u0647\u0624\u0644\u0627\u0621 \u0628\u0627\u0644\u0631\u062e\u0627\u0621 \u0641\u064a \u0627\u0644\u0639\u064a\u0634 \u0648\u0627\u0644\u0633\u0651\u064e\u0639\u064e\u0629 \u0641\u064a \u0627\u0644\u0631\u0632\u0642\u060c \u0648\u0627\u062e\u062a\u0628\u0631\u0646\u0627\u0647\u0645 \u0623\u064a\u0636\u064b\u0627 \u0628\u0627\u0644\u0634\u062f\u0629 \u0641\u064a \u0627\u0644\u0639\u064a\u0634 \u0648\u0627\u0644\u0645\u0635\u0627\u0626\u0628 \u0648\u0627\u0644\u0631\u0632\u0627\u064a\u0627; \u0631\u062c\u0627\u0621 \u0623\u0646 \u064a\u0631\u062c\u0639\u0648\u0627 \u0625\u0644\u0649 \u0637\u0627\u0639\u0629 \u0631\u0628\u0647\u0645 \u0648\u064a\u062a\u0648\u0628\u0648\u0627 \u0645\u0646 \u0645\u0639\u0627\u0635\u064a\u0647.","7:169":"\u0641\u062c\u0627\u0621 \u0645\u0646 \u0628\u0639\u062f \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u0648\u0635\u0641\u0646\u0627\u0647\u0645 \u0628\u064e\u062f\u064e\u0644\u064f \u0633\u0648\u0621 \u0623\u062e\u0630\u0648\u0627 \u0627\u0644\u0643\u062a\u0627\u0628 \u0645\u0646 \u0623\u0633\u0644\u0627\u0641\u0647\u0645\u060c \u0641\u0642\u0631\u0624\u0648\u0647 \u0648\u0639\u0644\u0645\u0648\u0647\u060c \u0648\u062e\u0627\u0644\u0641\u0648\u0627 \u062d\u0643\u0645\u0647\u060c \u064a\u0623\u062e\u0630\u0648\u0646 \u0645\u0627 \u064a\u0639\u0631\u0636 \u0644\u0647\u0645 \u0645\u0646 \u0645\u062a\u0627\u0639 \u0627\u0644\u062f\u0646\u064a\u0627 \u0645\u0646 \u062f\u0646\u064a\u0621 \u0627\u0644\u0645\u0643\u0627\u0633\u0628 \u0643\u0627\u0644\u0631\u0634\u0648\u0629 \u0648\u063a\u064a\u0631\u0647\u0627; \u0648\u0630\u0644\u0643 \u0644\u0634\u062f\u0629 \u062d\u0631\u0635\u0647\u0645 \u0648\u0646\u064e\u0647\u064e\u0645\u0647\u0645\u060c \u0648\u064a\u0642\u0648\u0644\u0648\u0646 \u0645\u0639 \u0630\u0644\u0643: \u0625\u0646 \u0627\u0644\u0644\u0647 \u0633\u064a\u063a\u0641\u0631 \u0644\u0646\u0627 \u0630\u0646\u0648\u0628\u0646\u0627 \u062a\u0645\u0646\u064a\u064b\u0627 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0627\u0644\u0623\u0628\u0627\u0637\u064a\u0644\u060c \u0648\u0625\u0646 \u064a\u0623\u062a \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u064a\u0647\u0648\u062f\u064e \u0645\u062a\u0627\u0639\u064c \u0632\u0627\u0626\u0644\u064c \u0645\u0646 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062d\u0631\u0627\u0645 \u064a\u0623\u062e\u0630\u0648\u0647 \u0648\u064a\u0633\u062a\u062d\u0644\u0648\u0647\u060c \u0645\u0635\u0631\u0651\u0650\u064a\u0646 \u0639\u0644\u0649 \u0630\u0646\u0648\u0628\u0647\u0645 \u0648\u062a\u0646\u0627\u0648\u0644\u0647\u0645 \u0627\u0644\u062d\u0631\u0627\u0645\u060c \u0623\u0644\u064e\u0645\u0652 \u064a\u0624\u062e\u0630 \u0639\u0644\u0649 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0639\u0647\u0648\u062f \u0628\u0625\u0642\u0627\u0645\u0629 \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0639\u0645\u0644 \u0628\u0645\u0627 \u0641\u064a\u0647\u0627\u060c \u0648\u0623\u0644\u0627 \u064a\u0642\u0648\u0644\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u062d\u0642 \u0648\u0623\u0644\u0627 \u064a\u0643\u0630\u0628\u0648\u0627 \u0639\u0644\u064a\u0647\u060c \u0648\u0639\u0644\u0645\u0648\u0627 \u0645\u0627 \u0641\u064a \u0627\u0644\u0643\u062a\u0627\u0628 \u0641\u0636\u064a\u0639\u0648\u0647\u060c \u0648\u062a\u0631\u0643\u0648\u0627 \u0627\u0644\u0639\u0645\u0644 \u0628\u0647\u060c \u0648\u062e\u0627\u0644\u0641\u0648\u0627 \u0639\u0647\u062f \u0627\u0644\u0644\u0647 \u0625\u0644\u064a\u0647\u0645 \u0641\u064a \u0630\u0644\u0643\u061f \u0648\u0627\u0644\u062f\u0627\u0631 \u0627\u0644\u0622\u062e\u0631\u0629 \u062e\u064a\u0631 \u0644\u0644\u0630\u064a\u0646 \u064a\u062a\u0642\u0648\u0646 \u0627\u0644\u0644\u0647\u060c \u0641\u064a\u0645\u062a\u062b\u0644\u0648\u0646 \u0623\u0648\u0627\u0645\u0631\u0647\u060c \u0648\u064a\u062c\u062a\u0646\u0628\u0648\u0646 \u0646\u0648\u0627\u0647\u064a\u0647\u060c \u0623\u0641\u0644\u0627 \u064a\u0639\u0642\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u064a\u0623\u062e\u0630\u0648\u0646 \u062f\u0646\u064a\u0621 \u0627\u0644\u0645\u0643\u0627\u0633\u0628 \u0623\u0646 \u0645\u0627 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u062e\u064a\u0631 \u0648\u0623\u0628\u0642\u0649 \u0644\u0644\u0645\u062a\u0642\u064a\u0646\u061f","7:170":"\u0648\u0627\u0644\u0630\u064a\u0646 \u064a\u062a\u0645\u0633\u0651\u064e\u0643\u0648\u0646 \u0628\u0627\u0644\u0643\u062a\u0627\u0628\u060c \u0648\u064a\u0639\u0645\u0644\u0648\u0646 \u0628\u0645\u0627 \u0641\u064a\u0647 \u0645\u0646 \u0627\u0644\u0639\u0642\u0627\u0626\u062f \u0648\u0627\u0644\u0623\u062d\u0643\u0627\u0645\u060c \u0648\u064a\u062d\u0627\u0641\u0638\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0635\u0644\u0627\u0629 \u0628\u062d\u062f\u0648\u062f\u0647\u0627\u060c \u0648\u0644\u0627 \u064a\u0636\u064a\u0639\u0648\u0646 \u0623\u0648\u0642\u0627\u062a\u0647\u0627\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u062b\u064a\u0628\u0647\u0645 \u0639\u0644\u0649 \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0627\u0644\u0635\u0627\u0644\u062d\u0629\u060c \u0648\u0644\u0627 \u064a\u0636\u064a\u0639\u0647\u0627.","7:171":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0625\u0630 \u0631\u0641\u0639\u0646\u0627 \u0627\u0644\u062c\u0628\u0644 \u0641\u0648\u0642 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0643\u0623\u0646\u0647 \u0633\u062d\u0627\u0628\u0629 \u062a\u0638\u0644\u0647\u0645\u060c \u0648\u0623\u064a\u0642\u0646\u0648\u0627 \u0623\u0646\u0647 \u0648\u0627\u0642\u0639 \u0628\u0647\u0645 \u0625\u0646 \u0644\u0645 \u064a\u0642\u0628\u0644\u0648\u0627 \u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u062a\u0648\u0631\u0627\u0629\u060c \u0648\u0642\u0644\u0646\u0627 \u0644\u0647\u0645: \u062e\u0630\u0648\u0627 \u0645\u0627 \u0622\u062a\u064a\u0646\u0627\u0643\u0645 \u0628\u0642\u0648\u0629\u060c \u0623\u064a \u0627\u0639\u0645\u0644\u0648\u0627 \u0628\u0645\u0627 \u0623\u0639\u0637\u064a\u0646\u0627\u0643\u0645 \u0628\u0627\u062c\u062a\u0647\u0627\u062f \u0645\u0646\u0643\u0645\u060c \u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0645\u0627 \u0641\u064a \u0643\u062a\u0627\u0628\u0646\u0627 \u0645\u0646 \u0627\u0644\u0639\u0647\u0648\u062f \u0648\u0627\u0644\u0645\u0648\u0627\u062b\u064a\u0642 \u0627\u0644\u062a\u064a \u0623\u062e\u0630\u0646\u0627\u0647\u0627 \u0639\u0644\u064a\u0643\u0645 \u0628\u0627\u0644\u0639\u0645\u0644 \u0628\u0645\u0627 \u0641\u064a\u0647; \u0643\u064a \u062a\u062a\u0642\u0648\u0627 \u0631\u0628\u0643\u0645 \u0641\u062a\u0646\u062c\u0648\u0627 \u0645\u0646 \u0639\u0642\u0627\u0628\u0647.","7:172":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0625\u0630 \u0627\u0633\u062a\u062e\u0631\u062c \u0631\u0628\u0643 \u0623\u0648\u0644\u0627\u062f \u0622\u062f\u0645 \u0645\u0650\u0646 \u0623\u0635\u0644\u0627\u0628 \u0622\u0628\u0627\u0626\u0647\u0645\u060c \u0648\u0642\u0631\u0631\u0647\u0645 \u0628\u062a\u0648\u062d\u064a\u062f\u0647 \u0628\u0645\u0627 \u0623\u0648\u062f\u0639\u0647 \u0641\u064a \u0641\u0637\u0631\u0647\u0645 \u0645\u0646 \u0623\u0646\u0647 \u0631\u0628\u0647\u0645 \u0648\u062e\u0627\u0644\u0642\u0647\u0645 \u0648\u0645\u0644\u064a\u0643\u0647\u0645\u060c \u0641\u0623\u0642\u0631\u0648\u0627 \u0644\u0647 \u0628\u0630\u0644\u0643\u060c \u062e\u0634\u064a\u0629 \u0623\u0646 \u064a\u0646\u0643\u0631\u0648\u0627 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0641\u0644\u0627 \u064a\u0642\u0631\u0648\u0627 \u0628\u0634\u064a\u0621 \u0645\u0646\u0647\u060c \u0648\u064a\u0632\u0639\u0645\u0648\u0627 \u0623\u0646 \u062d\u062c\u0629 \u0627\u0644\u0644\u0647 \u0645\u0627 \u0642\u0627\u0645\u062a \u0639\u0644\u064a\u0647\u0645\u060c \u0648\u0644\u0627 \u0639\u0646\u062f\u0647\u0645 \u0639\u0644\u0645 \u0628\u0647\u0627\u060c \u0628\u0644 \u0643\u0627\u0646\u0648\u0627 \u0639\u0646\u0647\u0627 \u063a\u0627\u0641\u0644\u064a\u0646.","7:173":"\u0623\u0648 \u0644\u0626\u0644\u0627 \u062a\u0642\u0648\u0644\u0648\u0627: \u0625\u0646\u0645\u0627 \u0623\u0634\u0631\u0643 \u0622\u0628\u0627\u0624\u0646\u0627 \u0645\u0646 \u0642\u0628\u0644\u0646\u0627 \u0648\u0646\u0642\u0636\u0648\u0627 \u0627\u0644\u0639\u0647\u062f\u060c \u0641\u0627\u0642\u062a\u062f\u064a\u0646\u0627 \u0628\u0647\u0645 \u0645\u0646 \u0628\u0639\u062f\u0647\u0645\u060c \u0623\u0641\u062a\u0639\u0630\u0628\u0646\u0627 \u0628\u0645\u0627 \u0641\u0639\u0644 \u0627\u0644\u0630\u064a\u0646 \u0623\u0628\u0637\u0644\u0648\u0627 \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0628\u062c\u0639\u0644\u0647\u0645 \u0645\u0639 \u0627\u0644\u0644\u0647 \u0634\u0631\u064a\u0643\u0627 \u0641\u064a \u0627\u0644\u0639\u0628\u0627\u062f\u0629\u061f","7:174":"\u0648\u0643\u0645\u0627 \u0641\u064e\u0635\u0651\u064e\u0644\u0652\u0646\u0627 \u0627\u0644\u0622\u064a\u0627\u062a\u060c \u0648\u0628\u064a\u0651\u064e\u0646\u0651\u064e\u0627 \u0641\u064a\u0647\u0627 \u0645\u0627 \u0641\u0639\u0644\u0646\u0627\u0647 \u0628\u0627\u0644\u0623\u0645\u0645 \u0627\u0644\u0633\u0627\u0628\u0642\u0629\u060c \u0643\u0630\u0644\u0643 \u0646\u0641\u0635\u0651\u0650\u0644 \u0627\u0644\u0622\u064a\u0627\u062a \u0648\u0646\u0628\u064a\u0651\u0650\u0646\u0647\u0627 \u0644\u0642\u0648\u0645\u0643 \u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644; \u0631\u062c\u0627\u0621 \u0623\u0646 \u064a\u0631\u062c\u0639\u0648\u0627 \u0639\u0646 \u0634\u0631\u0643\u0647\u0645\u060c \u0648\u064a\u0646\u064a\u0628\u0648\u0627 \u0625\u0644\u0649 \u0631\u0628\u0647\u0645.","7:175":"\u0648\u0627\u0642\u0635\u0635 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0639\u0644\u0649 \u0623\u0645\u062a\u0643 \u062e\u0628\u0631 \u0631\u062c\u0644 \u0645\u0646 \u0628\u0646\u064a \u0625\u0633\u0631\u0627\u0626\u064a\u0644 \u0623\u0639\u0637\u064a\u0646\u0627\u0647 \u062d\u062c\u062c\u0646\u0627 \u0648\u0623\u062f\u0644\u062a\u0646\u0627\u060c \u0641\u062a\u0639\u0644\u0651\u064e\u0645\u0647\u0627\u060c \u062b\u0645 \u0643\u0641\u0631 \u0628\u0647\u0627\u060c \u0648\u0646\u0628\u0630\u0647\u0627 \u0648\u0631\u0627\u0621 \u0638\u0647\u0631\u0647\u060c \u0641\u0627\u0633\u062a\u062d\u0648\u0630 \u0639\u0644\u064a\u0647 \u0627\u0644\u0634\u064a\u0637\u0627\u0646\u060c \u0641\u0635\u0627\u0631 \u0645\u0646 \u0627\u0644\u0636\u0627\u0644\u064a\u0646 \u0627\u0644\u0647\u0627\u0644\u0643\u064a\u0646; \u0628\u0633\u0628\u0628 \u0645\u062e\u0627\u0644\u0641\u062a\u0647 \u0623\u0645\u0631 \u0631\u0628\u0647 \u0648\u0637\u0627\u0639\u062a\u0647 \u0627\u0644\u0634\u064a\u0637\u0627\u0646.","7:176":"\u0648\u0644\u0648 \u0634\u0626\u0646\u0627 \u0623\u0646 \u0646\u0631\u0641\u0639 \u0642\u062f\u0631\u0647 \u0628\u0645\u0627 \u0622\u062a\u064a\u0646\u0627\u0647 \u0645\u0646 \u0627\u0644\u0622\u064a\u0627\u062a \u0644\u0641\u0639\u0644\u0646\u0627\u060c \u0648\u0644\u0643\u0646\u0647 \u0631\u064e\u0643\u064e\u0646\u064e \u0625\u0644\u0649 \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u062a\u0628\u0639 \u0647\u0648\u0627\u0647\u060c \u0648\u0622\u062b\u0631 \u0644\u064e\u0630\u0651\u064e\u0627\u062a\u0647 \u0648\u0634\u0647\u0648\u0627\u062a\u0647 \u0639\u0644\u0649 \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0627\u0645\u062a\u0646\u0639 \u0639\u0646 \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u0648\u062e\u0627\u0644\u0641 \u0623\u0645\u0631\u0647. \u0641\u064e\u0645\u064e\u062b\u064e\u0644\u064f \u0647\u0630\u0627 \u0627\u0644\u0631\u062c\u0644 \u0645\u062b\u0644 \u0627\u0644\u0643\u0644\u0628\u060c \u0625\u0646 \u062a\u0637\u0631\u062f\u0647 \u0623\u0648 \u062a\u062a\u0631\u0643\u0647 \u064a\u064f\u062e\u0652\u0631\u062c \u0644\u0633\u0627\u0646\u0647 \u0641\u064a \u0627\u0644\u062d\u0627\u0644\u064a\u0646 \u0644\u0627\u0647\u062b\u064b\u0627\u060c \u0641\u0643\u0630\u0644\u0643 \u0627\u0644\u0630\u064a \u0627\u0646\u0633\u0644\u062e \u0645\u0646 \u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u064a\u0638\u0644 \u0639\u0644\u0649 \u0643\u0641\u0631\u0647 \u0625\u0646 \u0627\u062c\u062a\u0647\u062f\u0652\u062a\u064e \u0641\u064a \u062f\u0639\u0648\u062a\u0643 \u0644\u0647 \u0623\u0648 \u0623\u0647\u0645\u0644\u062a\u0647\u060c \u0647\u0630\u0627 \u0627\u0644\u0648\u0635\u0641 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0648\u0635\u0641 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u0630\u064a\u0646 \u0643\u0627\u0646\u0648\u0627 \u0636\u0627\u0644\u064a\u0646 \u0642\u0628\u0644 \u0623\u0646 \u062a\u0623\u062a\u064a\u0647\u0645 \u0628\u0627\u0644\u0647\u062f\u0649 \u0648\u0627\u0644\u0631\u0633\u0627\u0644\u0629\u060c \u0641\u0627\u0642\u0635\u0635 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0623\u062e\u0628\u0627\u0631 \u0627\u0644\u0623\u0645\u0645 \u0627\u0644\u0645\u0627\u0636\u064a\u0629\u060c \u0641\u0641\u064a \u0625\u062e\u0628\u0627\u0631\u0643 \u0628\u0630\u0644\u0643 \u0623\u0639\u0638\u0645 \u0645\u0639\u062c\u0632\u0629\u060c \u0644\u0639\u0644 \u0642\u0648\u0645\u0643 \u064a\u062a\u062f\u0628\u0631\u0648\u0646 \u0641\u064a\u0645\u0627 \u062c\u0626\u062a\u0647\u0645 \u0628\u0647 \u0641\u064a\u0624\u0645\u0646\u0648\u0627 \u0644\u0643.","7:177":"\u0642\u064e\u0628\u064f\u062d\u064e \u0645\u062b\u0644\u0627 \u0645\u062b\u0644\u064f \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u0630\u064a\u0646 \u0643\u0630\u0651\u064e\u0628\u0648\u0627 \u0628\u062d\u062c\u062c \u0627\u0644\u0644\u0647 \u0648\u0623\u062f\u0644\u062a\u0647\u060c \u0641\u062c\u062d\u062f\u0648\u0647\u0627\u060c \u0648\u0623\u0646\u0641\u0633\u0647\u0645 \u0643\u0627\u0646\u0648\u0627 \u064a\u0638\u0644\u0645\u0648\u0646\u0647\u0627; \u0628\u0633\u0628\u0628 \u062a\u0643\u0630\u064a\u0628\u0647\u0645 \u0628\u0647\u0630\u0647 \u0627\u0644\u062d\u062c\u062c \u0648\u0627\u0644\u0623\u062f\u0644\u0629.","7:178":"\u0645\u0646 \u064a\u0648\u0641\u0642\u0647 \u0627\u0644\u0644\u0647 \u0644\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0647 \u0648\u0637\u0627\u0639\u062a\u0647 \u0641\u0647\u0648 \u0627\u0644\u0645\u0648\u0641\u0651\u064e\u0642\u060c \u0648\u0645\u0646 \u064a\u062e\u0630\u0644\u0647 \u0641\u0644\u0645 \u064a\u0648\u0641\u0642\u0647 \u0641\u0647\u0648 \u0627\u0644\u062e\u0627\u0633\u0631 \u0627\u0644\u0647\u0627\u0644\u0643\u060c \u0641\u0627\u0644\u0647\u062f\u0627\u064a\u0629 \u0648\u0627\u0644\u0625\u0636\u0644\u0627\u0644 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647.","7:179":"\u0648\u0644\u0642\u062f \u062e\u0644\u0642\u0646\u0627 \u0644\u0644\u0646\u0627\u0631 -\u0627\u0644\u062a\u064a \u064a\u0639\u0630\u0651\u0650\u0628 \u0627\u0644\u0644\u0647 \u0641\u064a\u0647\u0627 \u0645\u064e\u0646 \u064a\u0633\u062a\u062d\u0642 \u0627\u0644\u0639\u0630\u0627\u0628 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629- \u0643\u062b\u064a\u0631\u064b\u0627 \u0645\u0646 \u0627\u0644\u062c\u0646 \u0648\u0627\u0644\u0625\u0646\u0633\u060c \u0644\u0647\u0645 \u0642\u0644\u0648\u0628 \u0644\u0627 \u064a\u0639\u0642\u0644\u0648\u0646 \u0628\u0647\u0627\u060c \u0641\u0644\u0627 \u064a\u0631\u062c\u0648\u0646 \u062b\u0648\u0627\u0628\u064b\u0627 \u0648\u0644\u0627 \u064a\u062e\u0627\u0641\u0648\u0646 \u0639\u0642\u0627\u0628\u064b\u0627\u060c \u0648\u0644\u0647\u0645 \u0623\u0639\u064a\u0646 \u0644\u0627 \u064a\u0646\u0638\u0631\u0648\u0646 \u0628\u0647\u0627 \u0625\u0644\u0649 \u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0648\u0623\u062f\u0644\u062a\u0647\u060c \u0648\u0644\u0647\u0645 \u0622\u0630\u0627\u0646 \u0644\u0627 \u064a\u0633\u0645\u0639\u0648\u0646 \u0628\u0647\u0627 \u0622\u064a\u0627\u062a \u0643\u062a\u0627\u0628 \u0627\u0644\u0644\u0647 \u0641\u064a\u062a\u0641\u0643\u0631\u0648\u0627 \u0641\u064a\u0647\u0627\u060c \u0647\u0624\u0644\u0627\u0621 \u0643\u0627\u0644\u0628\u0647\u0627\u0626\u0645 \u0627\u0644\u062a\u064a \u0644\u0627 \u062a\u064e\u0641\u0652\u0642\u064e\u0647\u064f \u0645\u0627 \u064a\u0642\u0627\u0644 \u0644\u0647\u0627\u060c \u0648\u0644\u0627 \u062a\u0641\u0647\u0645 \u0645\u0627 \u062a\u0628\u0635\u0631\u0647\u060c \u0648\u0644\u0627 \u062a\u0639\u0642\u0644 \u0628\u0642\u0644\u0648\u0628\u0647\u0627 \u0627\u0644\u062e\u064a\u0631 \u0648\u0627\u0644\u0634\u0631 \u0641\u062a\u0645\u064a\u0632 \u0628\u064a\u0646\u0647\u0645\u0627\u060c \u0628\u0644 \u0647\u0645 \u0623\u0636\u0644 \u0645\u0646\u0647\u0627; \u0644\u0623\u0646 \u0627\u0644\u0628\u0647\u0627\u0626\u0645 \u062a\u0628\u0635\u0631 \u0645\u0646\u0627\u0641\u0639\u0647\u0627 \u0648\u0645\u0636\u0627\u0631\u0647\u0627 \u0648\u062a\u062a\u0628\u0639 \u0631\u0627\u0639\u064a\u0647\u0627\u060c \u0648\u0647\u0645 \u0628\u062e\u0644\u0627\u0641 \u0630\u0644\u0643\u060c \u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u063a\u0627\u0641\u0644\u0648\u0646 \u0639\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0637\u0627\u0639\u062a\u0647.","7:180":"\u0648\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0623\u0633\u0645\u0627\u0621 \u0627\u0644\u062d\u0633\u0646\u0649\u060c \u0627\u0644\u062f\u0627\u0644\u0629 \u0639\u0644\u0649 \u0643\u0645\u0627\u0644 \u0639\u0638\u0645\u062a\u0647\u060c \u0648\u0643\u0644 \u0623\u0633\u0645\u0627\u0626\u0647 \u062d\u0633\u0646\u060c \u0641\u0627\u0637\u0644\u0628\u0648\u0627 \u0645\u0646\u0647 \u0628\u0623\u0633\u0645\u0627\u0626\u0647 \u0645\u0627 \u062a\u0631\u064a\u062f\u0648\u0646\u060c \u0648\u0627\u062a\u0631\u0643\u0648\u0627 \u0627\u0644\u0630\u064a\u0646 \u064a\u064f\u063a\u064a\u0651\u0650\u0631\u0648\u0646 \u0641\u064a \u0623\u0633\u0645\u0627\u0626\u0647 \u0628\u0627\u0644\u0632\u064a\u0627\u062f\u0629 \u0623\u0648 \u0627\u0644\u0646\u0642\u0635\u0627\u0646 \u0623\u0648 \u0627\u0644\u062a\u062d\u0631\u064a\u0641\u060c \u0643\u0623\u0646 \u064a\u064f\u0633\u0645\u0651\u064e\u0649 \u0628\u0647\u0627 \u0645\u0646 \u0644\u0627 \u064a\u0633\u062a\u062d\u0642\u0647\u0627\u060c \u0643\u062a\u0633\u0645\u064a\u0629 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0628\u0647\u0627 \u0622\u0644\u0647\u062a\u0647\u0645\u060c \u0623\u0648 \u0623\u0646 \u064a\u062c\u0639\u0644 \u0644\u0647\u0627 \u0645\u0639\u0646\u0649 \u0644\u0645 \u064a\u064f\u0631\u062f\u0652\u0647 \u0627\u0644\u0644\u0647 \u0648\u0644\u0627 \u0631\u0633\u0648\u0644\u0647\u060c \u0641\u0633\u0648\u0641 \u064a\u062c\u0632\u0648\u0646 \u062c\u0632\u0627\u0621 \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0627\u0644\u0633\u064a\u0626\u0629 \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u0648\u0627 \u064a\u0639\u0645\u0644\u0648\u0646\u0647\u0627 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0645\u0646 \u0627\u0644\u0643\u0641\u0631 \u0628\u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0644\u0625\u0644\u062d\u0627\u062f \u0641\u064a \u0623\u0633\u0645\u0627\u0626\u0647 \u0648\u062a\u0643\u0630\u064a\u0628 \u0631\u0633\u0648\u0644\u0647.","7:181":"\u0648\u0645\u0646 \u0627\u0644\u0630\u064a\u0646 \u062e\u064e\u0644\u064e\u0642\u0652\u0646\u0627 \u062c\u0645\u0627\u0639\u0629 \u0641\u0627\u0636\u0644\u0629 \u064a\u0647\u062a\u062f\u0648\u0646 \u0628\u0627\u0644\u062d\u0642 \u0648\u064a\u064e\u062f\u0652\u0639\u0648\u0646 \u0625\u0644\u064a\u0647\u060c \u0648\u0628\u0647 \u064a\u0642\u0636\u0648\u0646 \u0648\u064a\u0646\u0635\u0641\u0648\u0646 \u0627\u0644\u0646\u0627\u0633\u060c \u0648\u0647\u0645 \u0623\u0626\u0645\u0629 \u0627\u0644\u0647\u062f\u0649 \u0645\u0645\u0646 \u0623\u0646\u0639\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d.","7:182":"\u0648\u0627\u0644\u0630\u064a\u0646 \u0643\u0630\u0651\u064e\u0628\u0648\u0627 \u0628\u0622\u064a\u0627\u062a\u0646\u0627\u060c \u0641\u062c\u062d\u062f\u0648\u0647\u0627\u060c \u0648\u0644\u0645 \u064a\u062a\u0630\u0643\u0631\u0648\u0627 \u0628\u0647\u0627\u060c \u0633\u0646\u0641\u062a\u062d \u0644\u0647\u0645 \u0623\u0628\u0648\u0627\u0628 \u0627\u0644\u0631\u0632\u0642 \u0648\u0648\u062c\u0648\u0647 \u0627\u0644\u0645\u0639\u0627\u0634 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0627\u0633\u062a\u062f\u0631\u0627\u062c\u064b\u0627 \u0644\u0647\u0645 \u062d\u062a\u0649 \u064a\u063a\u062a\u0631\u0648\u0627 \u0628\u0645\u0627 \u0647\u0645 \u0641\u064a\u0647 \u0648\u064a\u0639\u062a\u0642\u062f\u0648\u0627 \u0623\u0646\u0647\u0645 \u0639\u0644\u0649 \u0634\u064a\u0621\u060c \u062b\u0645 \u0646\u0639\u0627\u0642\u0628\u0647\u0645 \u0639\u0644\u0649 \u063a\u0650\u0631\u0651\u064e\u0629 \u0645\u0646 \u062d\u064a\u062b \u0644\u0627 \u064a\u0639\u0644\u0645\u0648\u0646. \u0648\u0647\u0630\u0647 \u0639\u0642\u0648\u0628\u0629 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0627\u0644\u062a\u0643\u0630\u064a\u0628 \u0628\u062d\u062c\u062c \u0627\u0644\u0644\u0647 \u0648\u0622\u064a\u0627\u062a\u0647.","7:183":"\u0648\u0623\u0645\u0647\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u0643\u0630\u0628\u0648\u0627 \u0628\u0622\u064a\u0627\u062a\u0646\u0627 \u062d\u062a\u0649 \u064a\u0638\u0646\u0648\u0627 \u0623\u0646\u0647\u0645 \u0644\u0627 \u064a\u0639\u0627\u0642\u0628\u0648\u0646\u060c \u0641\u064a\u0632\u062f\u0627\u062f\u0648\u0627 \u0643\u0641\u0631\u064b\u0627 \u0648\u0637\u063a\u064a\u0627\u0646\u064b\u0627\u060c \u0648\u0628\u0630\u0644\u0643 \u064a\u062a\u0636\u0627\u0639\u0641 \u0644\u0647\u0645 \u0627\u0644\u0639\u0630\u0627\u0628. \u0625\u0646 \u0643\u064a\u062f\u064a \u0645\u062a\u064a\u0646\u060c \u0623\u064a: \u0642\u0648\u064a \u0634\u062f\u064a\u062f \u0644\u0627 \u064a\u064f\u062f\u0652\u0641\u0639 \u0628\u0642\u0648\u0629 \u0648\u0644\u0627 \u0628\u062d\u064a\u0644\u0629.","7:184":"\u0623\u0648 \u0644\u0645 \u064a\u062a\u0641\u0643\u0631 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u0643\u0630\u0628\u0648\u0627 \u0628\u0622\u064a\u0627\u062a\u0646\u0627 \u0641\u064a\u062a\u062f\u0628\u0631\u0648\u0627 \u0628\u0639\u0642\u0648\u0644\u0647\u0645\u060c \u0648\u064a\u0639\u0644\u0645\u0648\u0627 \u0623\u0646\u0647 \u0644\u064a\u0633 \u0628\u0645\u062d\u0645\u062f \u062c\u0646\u0648\u0646\u061f \u0645\u0627 \u0647\u0648 \u0625\u0644\u0627 \u0646\u0630\u064a\u0631 \u0644\u0647\u0645 \u0645\u0646 \u0639\u0642\u0627\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0643\u0641\u0631\u0647\u0645 \u0628\u0647 \u0625\u0646 \u0644\u0645 \u064a\u0624\u0645\u0646\u0648\u0627\u060c \u0646\u0627\u0635\u062d \u0645\u0628\u064a\u0646.","7:185":"\u0623\u0648 \u0644\u0645 \u064a\u0646\u0638\u0631 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0643\u0630\u0628\u0648\u0646 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0641\u064a \u0645\u0644\u0643 \u0627\u0644\u0644\u0647 \u0627\u0644\u0639\u0638\u064a\u0645 \u0648\u0633\u0644\u0637\u0627\u0646\u0647 \u0627\u0644\u0642\u0627\u0647\u0631 \u0641\u064a \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0645\u0627 \u062e\u0644\u0642 \u0627\u0644\u0644\u0647 -\u062c\u0644\u0651\u064e \u062b\u0646\u0627\u0624\u0647- \u0645\u0646 \u0634\u064a\u0621 \u0641\u064a\u0647\u0645\u0627\u060c \u0641\u064a\u062a\u062f\u0628\u0631\u0648\u0627 \u0630\u0644\u0643 \u0648\u064a\u0639\u062a\u0628\u0631\u0648\u0627 \u0628\u0647\u060c \u0648\u064a\u0646\u0638\u0631\u0648\u0627 \u0641\u064a \u0622\u062c\u0627\u0644\u0647\u0645 \u0627\u0644\u062a\u064a \u0639\u0633\u0649 \u0623\u0646 \u062a\u0643\u0648\u0646 \u0642\u064e\u0631\u064f\u0628\u064e\u062a\u0652 \u0641\u064a\u0647\u0644\u0643\u0648\u0627 \u0639\u0644\u0649 \u0643\u0641\u0631\u0647\u0645\u060c \u0648\u064a\u0635\u064a\u0631\u0648\u0627 \u0625\u0644\u0649 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647 \u0648\u0623\u0644\u064a\u0645 \u0639\u0642\u0627\u0628\u0647\u061f \u0641\u0628\u0623\u064a \u062a\u062e\u0648\u064a\u0641 \u0648\u062a\u062d\u0630\u064a\u0631 \u0628\u0639\u062f \u062a\u062d\u0630\u064a\u0631 \u0627\u0644\u0642\u0631\u0622\u0646 \u064a\u0635\u062f\u0642\u0648\u0646 \u0648\u064a\u0639\u0645\u0644\u0648\u0646\u061f","7:186":"\u0645\u064e\u0646 \u064a\u0636\u0644\u0644\u0647 \u0627\u0644\u0644\u0647 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0631\u0634\u0627\u062f \u0641\u0644\u0627 \u0647\u0627\u062f\u064a \u0644\u0647\u060c \u0648\u064a\u062a\u0631\u0643\u064f\u0647\u0645 \u0641\u064a \u0643\u0641\u0631\u0647\u0645 \u064a\u062a\u062d\u064a\u0631\u0648\u0646 \u0648\u064a\u062a\u0631\u062f\u062f\u0648\u0646.","7:187":"\u064a\u0633\u0623\u0644\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0643\u0641\u0627\u0631 \xab\u0645\u0643\u0629\xbb \u0639\u0646 \u0627\u0644\u0633\u0627\u0639\u0629 \u0645\u062a\u0649 \u0642\u064a\u0627\u0645\u0647\u0627\u061f \u0642\u0644 \u0644\u0647\u0645: \u0639\u0650\u0644\u0652\u0645\u064f \u0642\u064a\u0627\u0645\u0647\u0627 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0638\u0647\u0631\u0647\u0627 \u0625\u0644\u0627 \u0647\u0648\u060c \u062b\u064e\u0642\u064f\u0644\u064e \u0639\u0644\u0645\u0647\u0627\u060c \u0648\u062e\u0641\u064a \u0639\u0644\u0649 \u0623\u0647\u0644 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636\u060c \u0641\u0644\u0627 \u064a\u0639\u0644\u0645 \u0648\u0642\u062a \u0642\u064a\u0627\u0645\u0647\u0627 \u0645\u0644\u064e\u0643 \u0645\u0642\u0631\u0651\u064e\u0628 \u0648\u0644\u0627 \u0646\u0628\u064a \u0645\u0631\u0633\u0644\u060c \u0644\u0627 \u062a\u062c\u064a\u0621 \u0627\u0644\u0633\u0627\u0639\u0629 \u0625\u0644\u0627 \u0641\u062c\u0623\u0629\u060c \u064a\u0633\u0623\u0644\u0643 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0642\u0648\u0645 \u0639\u0646\u0647\u0627 \u0643\u0623\u0646\u0643 \u062d\u0631\u064a\u0635 \u0639\u0644\u0649 \u0627\u0644\u0639\u0644\u0645 \u0628\u0647\u0627\u060c \u0645\u0633\u062a\u0642\u0635 \u0628\u0627\u0644\u0633\u0624\u0627\u0644 \u0639\u0646\u0647\u0627\u060c \u0642\u0644 \u0644\u0647\u0645: \u0625\u0646\u0645\u0627 \u0639\u0644\u0645\u0647\u0627 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0627\u0644\u0630\u064a \u064a\u0639\u0644\u0645 \u063a\u064a\u0628 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0644\u0643\u0646\u0651\u064e \u0623\u0643\u062b\u0631 \u0627\u0644\u0646\u0627\u0633 \u0644\u0627 \u064a\u0639\u0644\u0645\u0648\u0646 \u0623\u0646 \u0630\u0644\u0643 \u0644\u0627 \u064a\u0639\u0644\u0645\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647.","7:188":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0644\u0627 \u0623\u0642\u062f\u0631\u064f \u0639\u0644\u0649 \u062c\u064e\u0644\u0652\u0628\u0650 \u062e\u064a\u0631 \u0644\u0646\u0641\u0633\u064a \u0648\u0644\u0627 \u062f\u0641\u0639 \u0634\u0631 \u064a\u062d\u0644 \u0628\u0647\u0627 \u0625\u0644\u0627 \u0645\u0627 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0648 \u0643\u0646\u062a \u0623\u0639\u0644\u0645 \u0627\u0644\u063a\u064a\u0628 \u0644\u0641\u0639\u0644\u062a \u0627\u0644\u0623\u0633\u0628\u0627\u0628 \u0627\u0644\u062a\u064a \u0623\u0639\u0644\u0645 \u0623\u0646\u0647\u0627 \u062a\u0643\u062b\u0651\u0650\u0631 \u0644\u064a \u0627\u0644\u0645\u0635\u0627\u0644\u062d \u0648\u0627\u0644\u0645\u0646\u0627\u0641\u0639\u060c \u0648\u0644\u0627\u062a\u0651\u064e\u0642\u064a\u062a\u064f \u0645\u0627 \u064a\u0643\u0648\u0646 \u0645\u0646 \u0627\u0644\u0634\u0631 \u0642\u0628\u0644 \u0623\u0646 \u064a\u0642\u0639\u060c \u0645\u0627 \u0623\u0646\u0627 \u0625\u0644\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0623\u0631\u0633\u0644\u0646\u064a \u0625\u0644\u064a\u0643\u0645\u060c \u0623\u062e\u0648\u0651\u0650\u0641 \u0645\u0646 \u0639\u0642\u0627\u0628\u0647\u060c \u0648\u0623\u0628\u0634\u0631 \u0628\u062b\u0648\u0627\u0628\u0647 \u0642\u0648\u0645\u064b\u0627 \u064a\u0635\u062f\u0642\u0648\u0646 \u0628\u0623\u0646\u064a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u064a\u0639\u0645\u0644\u0648\u0646 \u0628\u0634\u0631\u0639\u0647.","7:189":"\u0647\u0648 \u0627\u0644\u0630\u064a \u062e\u0644\u0642\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633- \u0645\u0646 \u0646\u0641\u0633 \u0648\u0627\u062d\u062f\u0629\u060c \u0648\u0647\u064a \u0622\u062f\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0648\u062e\u064e\u0644\u064e\u0642 \u0645\u0646\u0647\u0627 \u0632\u0648\u062c\u0647\u0627\u060c \u0648\u0647\u064a \u062d\u0648\u0627\u0621; \u0644\u064a\u0623\u0646\u0633 \u0628\u0647\u0627 \u0648\u064a\u0637\u0645\u0626\u0646\u060c \u0641\u0644\u0645\u0627 \u062c\u0627\u0645\u0639\u0647\u0627 -\u0648\u0627\u0644\u0645\u0631\u0627\u062f \u062c\u0646\u0633 \u0627\u0644\u0632\u0648\u062c\u064a\u0646 \u0645\u0646 \u0630\u0631\u064a\u0629 \u0622\u062f\u0645- \u062d\u0645\u0644\u062a \u0645\u0627\u0621\u064b \u062e\u0641\u064a\u0641\u064b\u0627\u060c \u0641\u0642\u0627\u0645\u062a \u0628\u0647 \u0648\u0642\u0639\u062f\u062a \u0648\u0623\u062a\u0645\u062a \u0627\u0644\u062d\u0645\u0644\u060c \u0641\u0644\u0645\u0627 \u0642\u064e\u0631\u064f\u0628\u062a \u0648\u0644\u0627\u062f\u062a\u0647\u0627 \u0648\u0623\u062b\u0642\u0644\u062a \u062f\u0639\u0627 \u0627\u0644\u0632\u0648\u062c\u0627\u0646 \u0631\u0628\u0647\u0645\u0627: \u0644\u0626\u0646 \u0623\u0639\u0637\u064a\u062a\u0646\u0627 \u0628\u0634\u0631\u064b\u0627 \u0633\u0648\u064a\u064b\u0627 \u0635\u0627\u0644\u062d\u064b\u0627 \u0644\u0646\u0643\u0648\u0646\u0646 \u0645\u0645\u0646 \u064a\u0634\u0643\u0631\u0643 \u0639\u0644\u0649 \u0645\u0627 \u0648\u0647\u0628\u062a \u0644\u0646\u0627 \u0645\u0646 \u0627\u0644\u0648\u0644\u062f \u0627\u0644\u0635\u0627\u0644\u062d.","7:190":"\u0641\u0644\u0645\u0627 \u0631\u0632\u0642 \u0627\u0644\u0644\u0647 \u0627\u0644\u0632\u0648\u062c\u064a\u0646 \u0648\u0644\u062f\u064b\u0627 \u0635\u0627\u0644\u062d\u064b\u0627\u060c \u062c\u0639\u0644\u0627 \u0644\u0644\u0647 \u0634\u0631\u0643\u0627\u0621 \u0641\u064a \u0630\u0644\u0643 \u0627\u0644\u0648\u0644\u062f \u0627\u0644\u0630\u064a \u0627\u0646\u0641\u0631\u062f \u0627\u0644\u0644\u0647 \u0628\u062e\u0644\u0642\u0647 \u0641\u0639\u0628\u0651\u064e\u062f\u0627\u0647 \u0644\u063a\u064a\u0631 \u0627\u0644\u0644\u0647\u060c \u0641\u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u062a\u0646\u0632\u0647 \u0639\u0646 \u0643\u0644 \u0634\u0631\u0643.","7:191":"\u0623\u064a\u0634\u0631\u0643 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0641\u064a \u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0644\u0647 \u0645\u062e\u0644\u0648\u0642\u0627\u062a\u0647\u060c \u0648\u0647\u064a \u0644\u0627 \u062a\u0642\u062f\u0631 \u0639\u0644\u0649 \u062e\u064e\u0644\u0652\u0642 \u0634\u064a\u0621\u060c \u0628\u0644 \u0647\u064a \u0645\u062e\u0644\u0648\u0642\u0629\u061f","7:192":"\u0648\u0644\u0627 \u062a\u0633\u062a\u0637\u064a\u0639 \u0623\u0646 \u062a\u0646\u0635\u0631 \u0639\u0627\u0628\u062f\u064a\u0647\u0627 \u0623\u0648 \u062a\u062f\u0641\u0639 \u0639\u0646 \u0646\u0641\u0633\u0647\u0627 \u0633\u0648\u0621\u064b\u0627\u060c \u0641\u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u0644\u0627 \u062a\u062e\u0644\u0642 \u0634\u064a\u0626\u064b\u0627\u060c \u0628\u0644 \u0647\u064a \u0645\u062e\u0644\u0648\u0642\u0629\u060c \u0648\u0644\u0627 \u062a\u0633\u062a\u0637\u064a\u0639 \u0623\u0646 \u062a\u062f\u0641\u0639 \u0627\u0644\u0645\u0643\u0631\u0648\u0647 \u0639\u0645\u0646 \u064a\u0639\u0628\u062f\u0647\u0627\u060c \u0648\u0644\u0627 \u0639\u0646 \u0646\u0641\u0633\u0647\u0627\u060c \u0641\u0643\u064a\u0641 \u062a\u064f\u062a\u0651\u064e\u062e\u0630 \u0645\u0639 \u0627\u0644\u0644\u0647 \u0622\u0644\u0647\u0629\u061f \u0625\u0646\u0652 \u0647\u0630\u0627 \u0625\u0644\u0627 \u0623\u0638\u0644\u0645 \u0627\u0644\u0638\u0644\u0645 \u0648\u0623\u0633\u0641\u0647 \u0627\u0644\u0633\u0651\u064e\u0641\u064e\u0647.","7:193":"\u0648\u0625\u0646 \u0646\u062f\u0639\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646- \u0647\u0630\u0647 \u0627\u0644\u0623\u0635\u0646\u0627\u0645 \u0627\u0644\u062a\u064a \u0639\u0628\u062f\u062a\u0645\u0648\u0647\u0627 \u0645\u0646 \u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u0625\u0644\u0649 \u0627\u0644\u0647\u062f\u0649\u060c \u0644\u0627 \u062a\u0633\u0645\u0639 \u062f\u0639\u0627\u0621\u0643\u0645 \u0648\u0644\u0627 \u062a\u062a\u0628\u0639\u0643\u0645; \u064a\u0633\u062a\u0648\u064a \u062f\u0639\u0627\u0624\u0643\u0645 \u0644\u0647\u0627 \u0648\u0633\u0643\u0648\u062a\u0643\u0645 \u0639\u0646\u0647\u0627; \u0644\u0623\u0646\u0647\u0627 \u0644\u0627 \u062a\u0633\u0645\u0639 \u0648\u0644\u0627 \u062a\u0628\u0635\u0631 \u0648\u0644\u0627 \u062a\u064e\u0647\u062f\u0650\u064a \u0648\u0644\u0627 \u062a\u064f\u0647\u062f\u0649.","7:194":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u062a\u0639\u0628\u062f\u0648\u0646 \u0645\u0646 \u063a\u064a\u0631 \u0627\u0644\u0644\u0647 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646- \u0647\u0645 \u0645\u0645\u0644\u0648\u0643\u0648\u0646 \u0644\u0631\u0628\u0647\u0645 \u0643\u0645\u0627 \u0623\u0646\u0643\u0645 \u0645\u0645\u0644\u0648\u0643\u0648\u0646 \u0644\u0631\u0628\u0643\u0645\u060c \u0641\u0625\u0646 \u0643\u0646\u062a\u0645 \u0643\u0645\u0627 \u062a\u0632\u0639\u0645\u0648\u0646 \u0635\u0627\u062f\u0642\u064a\u0646 \u0641\u064a \u0623\u0646\u0647\u0627 \u062a\u0633\u062a\u062d\u0642 \u0645\u0646 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0634\u064a\u0626\u064b\u0627 \u0641\u0627\u062f\u0639\u0648\u0647\u0645 \u0641\u0644\u064a\u0633\u062a\u062c\u064a\u0628\u0648\u0627 \u0644\u0643\u0645\u060c \u0641\u0625\u0646 \u0627\u0633\u062a\u062c\u0627\u0628\u0648\u0627 \u0644\u0643\u0645 \u0648\u062d\u0635\u0651\u064e\u0644\u0648\u0627 \u0645\u0637\u0644\u0648\u0628\u0643\u0645\u060c \u0648\u0625\u0644\u0627 \u062a\u0628\u064a\u0646 \u0623\u0646\u0643\u0645 \u0643\u0627\u0630\u0628\u0648\u0646 \u0645\u0641\u062a\u0631\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0623\u0639\u0638\u0645 \u0627\u0644\u0641\u0631\u064a\u0629.","7:195":"\u0623\u0644\u0647\u0630\u0647 \u0627\u0644\u0622\u0644\u0647\u0629 \u0648\u0627\u0644\u0623\u0635\u0646\u0627\u0645 \u0623\u0631\u062c\u0644 \u064a\u0633\u0639\u064e\u0648\u0652\u0646 \u0628\u0647\u0627 \u0645\u0639\u0643\u0645 \u0641\u064a \u062d\u0648\u0627\u0626\u062c\u0643\u0645\u061f \u0623\u0645 \u0644\u0647\u0645 \u0623\u064a\u062f\u064d \u064a\u062f\u0641\u0639\u0648\u0646 \u0628\u0647\u0627 \u0639\u0646\u0643\u0645 \u0648\u064a\u0646\u0635\u0631\u0648\u0646\u0643\u0645 \u0639\u0644\u0649 \u0645\u0646 \u064a\u0631\u064a\u062f \u0628\u0643\u0645 \u0634\u0631\u064b\u0627 \u0648\u0645\u0643\u0631\u0648\u0647\u064b\u0627\u061f \u0623\u0645 \u0644\u0647\u0645 \u0623\u0639\u064a\u0646 \u064a\u0646\u0638\u0631\u0648\u0646 \u0628\u0647\u0627 \u0641\u064a\u0639\u0631\u0651\u0650\u0641\u0648\u0646\u0643\u0645 \u0645\u0627 \u0639\u0627\u064a\u0646\u0648\u0627 \u0648\u0623\u0628\u0635\u0631\u0648\u0627 \u0645\u0645\u0627 \u064a\u063a\u064a\u0628 \u0639\u0646\u0643\u0645 \u0641\u0644\u0627 \u062a\u0631\u0648\u0646\u0647\u061f \u0623\u0645 \u0644\u0647\u0645 \u0622\u0630\u0627\u0646 \u064a\u0633\u0645\u0639\u0648\u0646 \u0628\u0647\u0627 \u0641\u064a\u062e\u0628\u0631\u0648\u0646\u0643\u0645 \u0628\u0645\u0627 \u0644\u0645 \u062a\u0633\u0645\u0639\u0648\u0647\u061f \u0641\u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u0622\u0644\u0647\u062a\u0643\u0645 \u0627\u0644\u062a\u064a \u062a\u0639\u0628\u062f\u0648\u0646\u0647\u0627 \u0644\u064a\u0633 \u0641\u064a\u0647\u0627 \u0634\u064a\u0621 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0622\u0644\u0627\u062a\u060c \u0641\u0645\u0627 \u0648\u062c\u0647 \u0639\u0628\u0627\u062f\u062a\u0643\u0645 \u0625\u064a\u0627\u0647\u0627\u060c \u0648\u0647\u064a \u062e\u0627\u0644\u064a\u0629 \u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0627\u0644\u062a\u064a \u0628\u0647\u0627 \u064a\u062a\u0648\u0635\u0644 \u0625\u0644\u0649 \u062c\u0644\u0628 \u0627\u0644\u0646\u0641\u0639 \u0623\u0648 \u062f\u0641\u0639 \u0627\u0644\u0636\u0631\u061f \u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0645\u0646 \u0639\u0628\u062f\u0629 \u0627\u0644\u0623\u0648\u062b\u0627\u0646: \u0627\u062f\u0639\u0648\u0627 \u0622\u0644\u0647\u062a\u0643\u0645 \u0627\u0644\u0630\u064a\u0646 \u062c\u0639\u0644\u062a\u0645\u0648\u0647\u0645 \u0644\u0644\u0647 \u0634\u0631\u0643\u0627\u0621 \u0641\u064a \u0627\u0644\u0639\u0628\u0627\u062f\u0629\u060c \u062b\u0645 \u0627\u062c\u062a\u0645\u0639\u0648\u0627 \u0639\u0644\u0649 \u0625\u064a\u0642\u0627\u0639 \u0627\u0644\u0633\u0648\u0621 \u0648\u0627\u0644\u0645\u0643\u0631\u0648\u0647 \u0628\u064a\u060c \u0641\u0644\u0627 \u062a\u0624\u062e\u0631\u0648\u0646\u064a \u0648\u0639\u062c\u0651\u0650\u0644\u0648\u0627 \u0628\u0630\u0644\u0643\u060c \u0641\u0625\u0646\u064a \u0644\u0627 \u0623\u0628\u0627\u0644\u064a \u0628\u0622\u0644\u0647\u062a\u0643\u0645; \u0644\u0627\u0639\u062a\u0645\u0627\u062f\u064a \u0639\u0644\u0649 \u062d\u0641\u0638 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647.","7:196":"\u0625\u0646 \u0648\u0644\u064a\u0651\u0650\u064a\u064e \u0627\u0644\u0644\u0647\u060c \u0627\u0644\u0630\u064a \u064a\u062a\u0648\u0644\u0649 \u062d\u0641\u0638\u064a \u0648\u0646\u0635\u0631\u064a\u060c \u0647\u0648 \u0627\u0644\u0630\u064a \u0646\u0632\u0651\u064e\u0644 \u0639\u0644\u064a\u0651\u064e \u0627\u0644\u0642\u0631\u0622\u0646 \u0628\u0627\u0644\u062d\u0642\u060c \u0648\u0647\u0648 \u064a\u062a\u0648\u0644\u0649 \u0627\u0644\u0635\u0627\u0644\u062d\u064a\u0646 \u0645\u0650\u0646 \u0639\u0628\u0627\u062f\u0647\u060c \u0648\u064a\u0646\u0635\u0631\u0647\u0645 \u0639\u0644\u0649 \u0623\u0639\u062f\u0627\u0626\u0647\u0645 \u0648\u0644\u0627 \u064a\u062e\u0630\u0644\u0647\u0645.","7:197":"\u0648\u0627\u0644\u0630\u064a\u0646 \u062a\u062f\u0639\u0648\u0646 -\u0623\u0646\u062a\u0645 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646- \u0645\u0650\u0646 \u063a\u064a\u0631 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0622\u0644\u0647\u0629 \u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639\u0648\u0646 \u0646\u0635\u0631\u0643\u0645\u060c \u0648\u0644\u0627 \u064a\u0642\u062f\u0631\u0648\u0646 \u0639\u0644\u0649 \u0646\u0635\u0631\u0629 \u0623\u0646\u0641\u0633\u0647\u0645.","7:198":"\u0648\u0625\u0646 \u062a\u062f\u0639\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646- \u0622\u0644\u0647\u062a\u0643\u0645 \u0625\u0644\u0649 \u0627\u0644\u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0648\u0627\u0644\u0633\u062f\u0627\u062f \u0644\u0627 \u064a\u0633\u0645\u0639\u0648\u0627 \u062f\u0639\u0627\u0621\u0643\u0645\u060c \u0648\u062a\u0631\u0649 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0622\u0644\u0647\u0629 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0645\u0650\u0646 \u0639\u0628\u062f\u0629 \u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u064a\u0642\u0627\u0628\u0644\u0648\u0646\u0643 \u0643\u0627\u0644\u0646\u0627\u0638\u0631 \u0625\u0644\u064a\u0643 \u0648\u0647\u0645 \u0644\u0627 \u064a\u0628\u0635\u0631\u0648\u0646; \u0644\u0623\u0646\u0647\u0645 \u0644\u0627 \u0623\u0628\u0635\u0627\u0631 \u0644\u0647\u0645 \u0648\u0644\u0627 \u0628\u0635\u0627\u0626\u0631.","7:199":"\u0627\u0642\u0652\u0628\u064e\u0644\u0652 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a \u0623\u0646\u062a \u0648\u0623\u0645\u062a\u0643- \u0627\u0644\u0641\u0636\u0644 \u0645\u0646 \u0623\u062e\u0644\u0627\u0642 \u0627\u0644\u0646\u0627\u0633 \u0648\u0623\u0639\u0645\u0627\u0644\u0647\u0645\u060c \u0648\u0644\u0627 \u062a\u0637\u0644\u0628 \u0645\u0646\u0647\u0645 \u0645\u0627 \u064a\u0634\u0642 \u0639\u0644\u064a\u0647\u0645 \u062d\u062a\u0649 \u0644\u0627 \u064a\u0646\u0641\u0631\u0648\u0627\u060c \u0648\u0623\u0652\u0645\u0631 \u0628\u0643\u0644 \u0642\u0648\u0644 \u062d\u0633\u0646 \u0648\u0641\u0650\u0639\u0652\u0644\u064d \u062c\u0645\u064a\u0644\u060c \u0648\u0623\u0639\u0631\u0636 \u0639\u0646 \u0645\u0646\u0627\u0632\u0639\u0629 \u0627\u0644\u0633\u0641\u0647\u0627\u0621 \u0648\u0645\u0633\u0627\u0648\u0627\u0629 \u0627\u0644\u062c\u0647\u0644\u0629 \u0627\u0644\u0623\u063a\u0628\u064a\u0627\u0621.","7:200":"\u0648\u0625\u0645\u0627 \u064a\u0635\u064a\u0628\u0646\u0651\u064e\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0645\u0646 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u063a\u0636\u0628 \u0623\u0648 \u062a\u064f\u062d\u0650\u0633 \u0645\u0646\u0647 \u0628\u0648\u0633\u0648\u0633\u0629 \u0648\u062a\u062b\u0628\u064a\u0637 \u0639\u0646 \u0627\u0644\u062e\u064a\u0631 \u0623\u0648 \u062d\u062b \u0639\u0644\u0649 \u0627\u0644\u0634\u0631\u0651\u0650\u060c \u0641\u0627\u0644\u062c\u0623 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0645\u0633\u062a\u0639\u064a\u0630\u064b\u0627 \u0628\u0647\u060c \u0625\u0646\u0647 \u0633\u0645\u064a\u0639 \u0644\u0643\u0644 \u0642\u0648\u0644\u060c \u0639\u0644\u064a\u0645 \u0628\u0643\u0644 \u0641\u0639\u0644.","7:201":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u0627\u062a\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0645\u0650\u0646 \u062e\u0644\u0642\u0647\u060c \u0641\u062e\u0627\u0641\u0648\u0627 \u0639\u0642\u0627\u0628\u0647 \u0628\u0623\u062f\u0627\u0621 \u0641\u0631\u0627\u0626\u0636\u0647 \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0646\u0648\u0627\u0647\u064a\u0647\u060c \u0625\u0630\u0627 \u0623\u0635\u0627\u0628\u0647\u0645 \u0639\u0627\u0631\u0636 \u0645\u0646 \u0648\u0633\u0648\u0633\u0629 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u062a\u0630\u0643\u0651\u064e\u0631\u0648\u0627 \u0645\u0627 \u0623\u0648\u062c\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0645\u0646 \u0637\u0627\u0639\u062a\u0647\u060c \u0648\u0627\u0644\u062a\u0648\u0628\u0629 \u0625\u0644\u064a\u0647\u060c \u0641\u0625\u0630\u0627 \u0647\u0645 \u0645\u0646\u062a\u0647\u0648\u0646 \u0639\u0646 \u0645\u0639\u0635\u064a\u0629 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0628\u0635\u064a\u0631\u0629\u060c \u0622\u062e\u0630\u0648\u0646 \u0628\u0623\u0645\u0631 \u0627\u0644\u0644\u0647\u060c \u0639\u0627\u0635\u0648\u0646 \u0644\u0644\u0634\u064a\u0637\u0627\u0646.","7:202":"\u0648\u0625\u062e\u0648\u0627\u0646 \u0627\u0644\u0634\u064a\u0627\u0637\u064a\u0646\u060c \u0648\u0647\u0645 \u0627\u0644\u0641\u062c\u0651\u064e\u0627\u0631 \u0645\u0646 \u0636\u0644\u0627\u0644 \u0627\u0644\u0625\u0646\u0633 \u062a\u0645\u062f\u0647\u0645 \u0627\u0644\u0634\u064a\u0627\u0637\u064a\u0646 \u0645\u0646 \u0627\u0644\u062c\u0646 \u0641\u064a \u0627\u0644\u0636\u0644\u0627\u0644\u0629 \u0648\u0627\u0644\u063a\u064e\u0648\u0627\u064a\u0629\u060c \u0648\u0644\u0627 \u062a\u062f\u0651\u064e\u062e\u0631 \u0634\u064a\u0627\u0637\u064a\u0646 \u0627\u0644\u062c\u0646 \u0648\u064f\u0633\u0652\u0639\u064b\u0627 \u0641\u064a \u0645\u062f\u0651\u0650\u0647\u0645 \u0634\u064a\u0627\u0637\u064a\u0646 \u0627\u0644\u0625\u0646\u0633 \u0641\u064a \u0627\u0644\u063a\u064a\u0651\u0650\u060c \u0648\u0644\u0627 \u062a\u062f\u0651\u064e\u062e\u0631 \u0634\u064a\u0627\u0637\u064a\u0646 \u0627\u0644\u0625\u0646\u0633 \u0648\u064f\u0633\u0652\u0639\u064b\u0627 \u0641\u064a \u0639\u0645\u0644 \u0645\u0627 \u062a\u0648\u062d\u064a \u0628\u0647 \u0634\u064a\u0627\u0637\u064a\u0646 \u0627\u0644\u062c\u0646.","7:203":"\u0648\u0625\u0630\u0627 \u0644\u0645 \u062a\u062c\u0626 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0628\u0622\u064a\u0629 \u0642\u0627\u0644\u0648\u0627: \u0647\u0644\u0627 \u0623\u062d\u062f\u064e\u062b\u0652\u062a\u0647\u0627 \u0648\u0627\u062e\u062a\u0644\u0642\u062a\u0647\u0627 \u0645\u0646 \u0639\u0646\u062f \u0646\u0641\u0633\u0643\u060c \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0625\u0646 \u0647\u0630\u0627 \u0644\u064a\u0633 \u0644\u064a\u060c \u0648\u0644\u0627 \u064a\u062c\u0648\u0632 \u0644\u064a \u0641\u0650\u0639\u0652\u0644\u0647; \u0644\u0623\u0646 \u0627\u0644\u0644\u0647 \u0625\u0646\u0645\u0627 \u0623\u0645\u0631\u0646\u064a \u0628\u0627\u062a\u0628\u0627\u0639 \u0645\u0627 \u064a\u0648\u062d\u0649 \u0625\u0644\u064a\u0651\u064e \u0645\u0646 \u0639\u0646\u062f\u0647\u060c \u0648\u0647\u0648 \u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0630\u064a \u0623\u062a\u0644\u0648\u0647 \u0639\u0644\u064a\u0643\u0645 \u062d\u062c\u062c\u064b\u0627 \u0648\u0628\u0631\u0627\u0647\u064a\u0646 \u0645\u0646 \u0631\u0628\u0643\u0645\u060c \u0648\u0628\u064a\u0627\u0646\u064b\u0627 \u064a\u0647\u062f\u064a \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645\u060c \u0648\u0631\u062d\u0645\u0629 \u064a\u0631\u062d\u0645 \u0627\u0644\u0644\u0647 \u0628\u0647\u0627 \u0639\u0628\u0627\u062f\u0647 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646.","7:204":"\u0648\u0625\u0630\u0627 \u0642\u0631\u0626 \u0627\u0644\u0642\u0631\u0622\u0646 \u0641\u0627\u0633\u062a\u0645\u0639\u0648\u0627 \u0644\u0647 \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633 \u0648\u0623\u0646\u0635\u062a\u0648\u0627\u060c \u0644\u062a\u0639\u0642\u0644\u0648\u0647 \u0631\u062c\u0627\u0621 \u0623\u0646 \u064a\u0631\u062d\u0645\u0643\u0645 \u0627\u0644\u0644\u0647 \u0628\u0647.","7:205":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0631\u0628\u0643 \u0641\u064a \u0646\u0641\u0633\u0643 \u062a\u062e\u0634\u0639\u064b\u0627 \u0648\u062a\u0648\u0627\u0636\u0639\u064b\u0627 \u0644\u0644\u0647 \u062e\u0627\u0626\u0641\u064b\u0627 \u0648\u062c\u0644 \u0627\u0644\u0642\u0644\u0628 \u0645\u0646\u0647\u060c \u0648\u0627\u062f\u0639\u0647 \u0645\u062a\u0648\u0633\u0637\u064b\u0627 \u0628\u064a\u0646 \u0627\u0644\u062c\u0647\u0631 \u0648\u0627\u0644\u0645\u062e\u0627\u0641\u062a\u0629 \u0641\u064a \u0623\u0648\u0644 \u0627\u0644\u0646\u0647\u0627\u0631 \u0648\u0622\u062e\u0631\u0647\u060c \u0648\u0644\u0627 \u062a\u0643\u0646 \u0645\u0646 \u0627\u0644\u0630\u064a\u0646 \u064a\u064e\u063a\u0652\u0641\u064f\u0644\u0648\u0646 \u0639\u0646 \u0630\u0643\u0631 \u0627\u0644\u0644\u0647\u060c \u0648\u064a\u0644\u0647\u0648\u0646 \u0639\u0646\u0647 \u0641\u064a \u0633\u0627\u0626\u0631 \u0623\u0648\u0642\u0627\u062a\u0647\u0645.","7:206":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u0639\u0646\u062f \u0631\u0628\u0643 \u0645\u0646 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0644\u0627 \u064a\u0633\u062a\u0643\u0628\u0631\u0648\u0646 \u0639\u0646 \u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0644\u0647\u060c \u0628\u0644 \u064a\u0646\u0642\u0627\u062f\u0648\u0646 \u0644\u0623\u0648\u0627\u0645\u0631\u0647\u060c \u0648\u064a\u0633\u0628\u062d\u0648\u0646\u0647 \u0628\u0627\u0644\u0644\u064a\u0644 \u0648\u0627\u0644\u0646\u0647\u0627\u0631\u060c \u0648\u064a\u0646\u0632\u0647\u0648\u0646\u0647 \u0639\u0645\u0627 \u0644\u0627 \u064a\u0644\u064a\u0642 \u0628\u0647\u060c \u0648\u0644\u0647 \u0648\u062d\u062f\u0647 -\u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647- \u064a\u0633\u062c\u062f\u0648\u0646.","8:1":"\u064a\u0633\u0623\u0644\u0643 \u0623\u0635\u062d\u0627\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0639\u0646 \u0627\u0644\u063a\u0646\u0627\u0626\u0645 \u064a\u0648\u0645 \xab\u0628\u062f\u0631\xbb \u0643\u064a\u0641 \u062a\u0642\u0633\u0645\u0647\u0627 \u0628\u064a\u0646\u0647\u0645\u061f \u0642\u0644 \u0644\u0647\u0645: \u0625\u0646\u0651\u064e \u0623\u0645\u0631\u0647\u0627 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0641\u0627\u0644\u0631\u0633\u0648\u0644 \u064a\u062a\u0648\u0644\u0649 \u0642\u0633\u0645\u062a\u0647\u0627 \u0628\u0623\u0645\u0631 \u0631\u0628\u0647\u060c \u0641\u0627\u062a\u0642\u0648\u0627 \u0639\u0642\u0627\u0628 \u0627\u0644\u0644\u0647 \u0648\u0644\u0627 \u062a\u064f\u0642\u064e\u062f\u0645\u0648\u0627 \u0639\u0644\u0649 \u0645\u0639\u0635\u064a\u062a\u0647\u060c \u0648\u0627\u062a\u0631\u0643\u0648\u0627 \u0627\u0644\u0645\u0646\u0627\u0632\u0639\u0629 \u0648\u0627\u0644\u0645\u062e\u0627\u0635\u0645\u0629 \u0628\u0633\u0628\u0628 \u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0648\u0627\u0644\u060c \u0648\u0623\u0635\u0644\u062d\u0648\u0627 \u0627\u0644\u062d\u0627\u0644 \u0628\u064a\u0646\u0643\u0645\u060c \u0648\u0627\u0644\u062a\u0632\u0645\u0648\u0627 \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0625\u0646 \u0643\u0646\u062a\u0645 \u0645\u0624\u0645\u0646\u064a\u0646; \u0641\u0625\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u064a\u062f\u0639\u0648 \u0625\u0644\u0649 \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647.","8:2":"\u0625\u0646\u0645\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0628\u0627\u0644\u0644\u0647 \u062d\u0642\u064b\u0627 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0625\u0630\u0627 \u0630\u064f\u0643\u0650\u0631 \u0627\u0644\u0644\u0647 \u0641\u0632\u0639\u062a \u0642\u0644\u0648\u0628\u0647\u0645\u060c \u0648\u0625\u0630\u0627 \u062a\u0644\u064a\u062a \u0639\u0644\u064a\u0647\u0645 \u0622\u064a\u0627\u062a \u0627\u0644\u0642\u0631\u0622\u0646 \u0632\u0627\u062f\u062a\u0647\u0645 \u0625\u064a\u0645\u0627\u0646\u064b\u0627 \u0645\u0639 \u0625\u064a\u0645\u0627\u0646\u0647\u0645\u060c \u0644\u062a\u062f\u0628\u0631\u0647\u0645 \u0644\u0645\u0639\u0627\u0646\u064a\u0647 \u0648\u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u064a\u062a\u0648\u0643\u0644\u0648\u0646\u060c \u0641\u0644\u0627 \u064a\u0631\u062c\u0648\u0646 \u063a\u064a\u0631\u0647\u060c \u0648\u0644\u0627 \u064a\u0631\u0647\u0628\u0648\u0646 \u0633\u0648\u0627\u0647.","8:3":"\u0627\u0644\u0630\u064a\u0646 \u064a\u062f\u0627\u0648\u0645\u0648\u0646 \u0639\u0644\u0649 \u0623\u062f\u0627\u0621 \u0627\u0644\u0635\u0644\u0648\u0627\u062a \u0627\u0644\u0645\u0641\u0631\u0648\u0636\u0629 \u0641\u064a \u0623\u0648\u0642\u0627\u062a\u0647\u0627\u060c \u0648\u0645\u0645\u0627 \u0631\u0632\u0642\u0646\u0627\u0647\u0645 \u0645\u0646 \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u064a\u0646\u0641\u0642\u0648\u0646 \u0641\u064a\u0645\u0627 \u0623\u0645\u0631\u0646\u0627\u0647\u0645 \u0628\u0647.","8:4":"\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u064a\u0641\u0639\u0644\u0648\u0646 \u0647\u0630\u0647 \u0627\u0644\u0623\u0641\u0639\u0627\u0644 \u0647\u0645 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u062d\u0642\u064b\u0627 \u0638\u0627\u0647\u0631\u064b\u0627 \u0648\u0628\u0627\u0637\u0646\u064b\u0627 \u0628\u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645\u060c \u0644\u0647\u0645 \u0645\u0646\u0627\u0632\u0644 \u0639\u0627\u0644\u064a\u0629 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0648\u0639\u0641\u0648 \u0639\u0646 \u0630\u0646\u0648\u0628\u0647\u0645\u060c \u0648\u0631\u0632\u0642 \u0643\u0631\u064a\u0645\u060c \u0648\u0647\u0648 \u0627\u0644\u062c\u0646\u0629.","8:5":"\u0643\u0645\u0627 \u0623\u0646\u0643\u0645 \u0644\u0645\u0627 \u0627\u062e\u062a\u0644\u0641\u062a\u0645 \u0641\u064a \u0627\u0644\u0645\u063a\u0627\u0646\u0645 \u0641\u0627\u0646\u062a\u0632\u0639\u0647\u0627 \u0627\u0644\u0644\u0647 \u0645\u0646\u0643\u0645\u060c \u0648\u062c\u0639\u0644\u0647\u0627 \u0625\u0644\u0649 \u0642\u064e\u0633\u0652\u0645\u0647 \u0648\u0642\u064e\u0633\u0652\u0645 \u0631\u0633\u0648\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0643\u0630\u0644\u0643 \u0623\u0645\u0631\u0643 \u0631\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0628\u0627\u0644\u062e\u0631\u0648\u062c \u0645\u0646 \xab\u0627\u0644\u0645\u062f\u064a\u0646\u0629\xbb \u0644\u0644\u0642\u0627\u0621 \u0639\u0650\u064a\u0652\u0631 \u0642\u0631\u064a\u0634\u060c \u0648\u0630\u0644\u0643 \u0628\u0627\u0644\u0648\u062d\u064a \u0627\u0644\u0630\u064a \u0623\u062a\u0627\u0643 \u0628\u0647 \u062c\u0628\u0631\u064a\u0644 \u0645\u0639 \u0643\u0631\u0627\u0647\u0629 \u0641\u0631\u064a\u0642 \u0645\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0644\u0644\u062e\u0631\u0648\u062c.","8:6":"\u064a\u062c\u0627\u062f\u0644\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0641\u0631\u064a\u0642 \u0645\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0641\u064a \u0627\u0644\u0642\u062a\u0627\u0644 \u0645\u0650\u0646 \u0628\u0639\u062f \u0645\u0627 \u062a\u0628\u064a\u0651\u064e\u0646 \u0644\u0647\u0645 \u0623\u0646 \u0630\u0644\u0643 \u0648\u0627\u0642\u0639\u060c \u0643\u0623\u0646\u0647\u0645 \u064a\u0633\u0627\u0642\u0648\u0646 \u0625\u0644\u0649 \u0627\u0644\u0645\u0648\u062a\u060c \u0648\u0647\u0645 \u064a\u0646\u0638\u0631\u0648\u0646 \u0625\u0644\u064a\u0647 \u0639\u0650\u064a\u0627\u0646\u064b\u0627.","8:7":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u062c\u0627\u062f\u0644\u0648\u0646- \u0648\u064e\u0639\u0652\u062f\u064e \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0628\u0627\u0644\u0638\u0651\u064e\u0641\u0652\u0631 \u0628\u0625\u062d\u062f\u0649 \u0627\u0644\u0637\u0627\u0626\u0641\u062a\u064a\u0646: \u0627\u0644\u0639\u064a\u0631 \u0648\u0645\u0627 \u062a\u062d\u0645\u0644\u0647 \u0645\u0650\u0646 \u0623\u0631\u0632\u0627\u0642\u060c \u0623\u0648 \u0627\u0644\u0646\u0641\u064a\u0631\u060c \u0648\u0647\u0648 \u0642\u062a\u0627\u0644 \u0627\u0644\u0623\u0639\u062f\u0627\u0621 \u0648\u0627\u0644\u0627\u0646\u062a\u0635\u0627\u0631 \u0639\u0644\u064a\u0647\u0645\u060c \u0648\u0623\u0646\u062a\u0645 \u062a\u062d\u0628\u0648\u0646 \u0627\u0644\u0638\u0651\u064e\u0641\u0652\u0631 \u0628\u0627\u0644\u0639\u064a\u0631 \u062f\u0648\u0646 \u0627\u0644\u0642\u062a\u0627\u0644\u060c \u0648\u064a\u0631\u064a\u062f \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u062d\u0642 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u064a\u064f\u0639\u0652\u0644\u064a\u0647 \u0628\u0623\u0645\u0631\u0647 \u0625\u064a\u0627\u0643\u0645 \u0628\u0642\u062a\u0627\u0644 \u0627\u0644\u0643\u0641\u0627\u0631\u060c \u0648\u064a\u0633\u062a\u0623\u0635\u0644 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0628\u0627\u0644\u0647\u0644\u0627\u0643.","8:8":"\u0644\u064a\u0639\u0632\u0651\u064e \u0627\u0644\u0644\u0647 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0623\u0647\u0644\u0647\u060c \u0648\u064a\u0630\u0647\u0628 \u0627\u0644\u0634\u0631\u0643 \u0648\u0623\u0647\u0644\u0647\u060c \u0648\u0644\u0648 \u0643\u0631\u0647 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0630\u0644\u0643.","8:9":"\u0627\u0630\u0643\u0631\u0648\u0627 \u0646\u0639\u0645\u0629 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u064a\u0648\u0645 \xab\u0628\u062f\u0631\xbb \u0625\u0630 \u062a\u0637\u0644\u0628\u0648\u0646 \u0627\u0644\u0646\u0635\u0631 \u0639\u0644\u0649 \u0639\u062f\u0648\u0643\u0645\u060c \u0641\u0627\u0633\u062a\u062c\u0627\u0628 \u0627\u0644\u0644\u0647 \u0644\u062f\u0639\u0627\u0626\u0643\u0645 \u0642\u0627\u0626\u0644\u0627 \u0625\u0646\u064a \u0645\u0645\u062f\u0651\u064f\u0643\u0645 \u0628\u0623\u0644\u0641 \u0645\u0646 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0645\u0646 \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u064a\u062a\u0628\u0639 \u0628\u0639\u0636\u0647\u0645 \u0628\u0639\u0636\u064b\u0627.","8:10":"\u0648\u0645\u0627 \u062c\u0639\u0644 \u0627\u0644\u0644\u0647 \u0630\u0644\u0643 \u0627\u0644\u0625\u0645\u062f\u0627\u062f \u0625\u0644\u0627 \u0628\u0634\u0627\u0631\u0629 \u0644\u0643\u0645 \u0628\u0627\u0644\u0646\u0635\u0631\u060c \u0648\u0644\u062a\u0633\u0643\u0646 \u0628\u0647 \u0642\u0644\u0648\u0628\u0643\u0645\u060c \u0648\u062a\u0648\u0642\u0646\u0648\u0627 \u0628\u0646\u0635\u0631 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645\u060c \u0648\u0645\u0627 \u0627\u0644\u0646\u0635\u0631 \u0625\u0644\u0627 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0644\u0627 \u0628\u0634\u062f\u0629 \u0628\u0623\u0633\u0643\u0645 \u0648\u0642\u0648\u0627\u0643\u0645. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0639\u0632\u064a\u0632 \u0641\u064a \u0645\u0644\u0643\u0647\u060c \u062d\u0643\u064a\u0645 \u0641\u064a \u062a\u062f\u0628\u064a\u0631\u0647 \u0648\u0634\u0631\u0639\u0647.","8:11":"\u0625\u0630 \u064a\u064f\u0644\u0652\u0642\u064a \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0627\u0644\u0646\u0639\u0627\u0633 \u0623\u0645\u0627\u0646\u064b\u0627 \u0645\u0646\u0647 \u0644\u0643\u0645 \u0645\u0646 \u062e\u0648\u0641 \u0639\u062f\u0648\u0643\u0645 \u0623\u0646 \u064a\u063a\u0644\u0628\u0643\u0645\u060c \u0648\u064a\u0646\u0632\u0644 \u0639\u0644\u064a\u0643\u0645 \u0645\u0646 \u0627\u0644\u0633\u062d\u0627\u0628 \u0645\u0627\u0621 \u0637\u0647\u0648\u0631\u064b\u0627\u060c \u0644\u064a\u0637\u0647\u0631\u0643\u0645 \u0628\u0647 \u0645\u0646 \u0627\u0644\u0623\u062d\u062f\u0627\u062b \u0627\u0644\u0638\u0627\u0647\u0631\u0629\u060c \u0648\u064a\u0632\u064a\u0644 \u0639\u0646\u0643\u0645 \u0641\u064a \u0627\u0644\u0628\u0627\u0637\u0646 \u0648\u0633\u0627\u0648\u0633 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0648\u062e\u0648\u0627\u0637\u0631\u0647\u060c \u0648\u0644\u064a\u0634\u062f\u0651\u064e \u0639\u0644\u0649 \u0642\u0644\u0648\u0628\u0643\u0645 \u0628\u0627\u0644\u0635\u0628\u0631 \u0639\u0646\u062f \u0627\u0644\u0642\u062a\u0627\u0644\u060c \u0648\u064a\u062b\u0628\u062a \u0628\u0647 \u0623\u0642\u062f\u0627\u0645 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u062a\u0644\u0628\u064a\u062f \u0627\u0644\u0623\u0631\u0636 \u0627\u0644\u0631\u0645\u0644\u064a\u0629 \u0628\u0627\u0644\u0645\u0637\u0631 \u062d\u062a\u0649 \u0644\u0627 \u062a\u0646\u0632\u0644\u0642 \u0641\u064a\u0647\u0627 \u0627\u0644\u0623\u0642\u062f\u0627\u0645.","8:12":"\u0625\u0630 \u064a\u0648\u062d\u064a \u0631\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0625\u0644\u0649 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0627\u0644\u0630\u064a\u0646 \u0623\u0645\u062f\u0651\u064e \u0627\u0644\u0644\u0647 \u0628\u0647\u0645 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0641\u064a \u063a\u0632\u0648\u0629 \xab\u0628\u062f\u0631\xbb \u0623\u0646\u064a \u0645\u0639\u0643\u0645 \u0623\u064f\u0639\u064a\u0646\u0643\u0645 \u0648\u0623\u0646\u0635\u0631\u0643\u0645\u060c \u0641\u0642\u0648\u0651\u064f\u0648\u0627 \u0639\u0632\u0627\u0626\u0645 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627\u060c \u0633\u0623\u0644\u0642\u064a \u0641\u064a \u0642\u0644\u0648\u0628 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0627\u0644\u062e\u0648\u0641 \u0627\u0644\u0634\u062f\u064a\u062f \u0648\u0627\u0644\u0630\u0644\u0629 \u0648\u0627\u0644\u0635\u0651\u064e\u063a\u064e\u0627\u0631\u060c \u0641\u0627\u0636\u0631\u0628\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0631\u0624\u0648\u0633 \u0627\u0644\u0643\u0641\u0627\u0631\u060c \u0648\u0627\u0636\u0631\u0628\u0648\u0627 \u0645\u0646\u0647\u0645 \u0643\u0644 \u0637\u0631\u0641 \u0648\u0645\u0650\u0641\u0652\u0635\u0644.","8:13":"\u0630\u0644\u0643 \u0627\u0644\u0630\u064a \u062d\u062f\u062b \u0644\u0644\u0643\u0641\u0627\u0631 \u0645\u0646 \u0636\u064e\u0631\u0652\u0628 \u0631\u0624\u0648\u0633\u0647\u0645 \u0648\u0623\u0639\u0646\u0627\u0642\u0647\u0645 \u0648\u0623\u0637\u0631\u0627\u0641\u0647\u0645; \u0628\u0633\u0628\u0628 \u0645\u062e\u0627\u0644\u0641\u062a\u0647\u0645 \u0644\u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0645\u064e\u0646 \u064a\u062e\u0627\u0644\u0641 \u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0634\u062f\u064a\u062f \u0627\u0644\u0639\u0642\u0627\u0628 \u0644\u0647 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629.","8:14":"\u0630\u0644\u0643\u0645 \u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0630\u064a \u0639\u062c\u0651\u064e\u0644\u062a\u0647 \u0644\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0643\u0627\u0641\u0631\u0648\u0646 \u0627\u0644\u0645\u062e\u0627\u0644\u0641\u0648\u0646 \u0644\u0623\u0648\u0627\u0645\u0631 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627- \u0641\u0630\u0648\u0642\u0648\u0647 \u0641\u064a \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0644\u0643\u0645 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0639\u0630\u0627\u0628 \u0627\u0644\u0646\u0627\u0631.","8:15":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u064e\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0625\u0630\u0627 \u0642\u0627\u0628\u0644\u062a\u0645 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0641\u064a \u0627\u0644\u0642\u062a\u0627\u0644 \u0645\u062a\u0642\u0627\u0631\u0628\u064a\u0646 \u0645\u0646\u0643\u0645 \u0641\u0644\u0627 \u062a\u064f\u0648\u064e\u0644\u0651\u064f\u0648\u0647\u0645 \u0638\u0647\u0648\u0631\u0643\u0645\u060c \u0641\u062a\u0646\u0647\u0632\u0645\u0648\u0627 \u0639\u0646\u0647\u0645\u060c \u0648\u0644\u0643\u0646 \u0627\u062b\u0628\u062a\u0648\u0627 \u0644\u0647\u0645\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0645\u0639\u0643\u0645 \u0648\u0646\u0627\u0635\u0631\u0643\u0645 \u0639\u0644\u064a\u0647\u0645.","8:16":"\u0648\u0645\u0646 \u064a\u064f\u0648\u064e\u0644\u0651\u0650\u0647\u0645 \u0645\u0646\u0643\u0645 \u0638\u0647\u0631\u0647 \u0648\u0642\u062a \u0627\u0644\u0632\u062d\u0641 \u0625\u0644\u0627 \u0645\u0646\u0639\u0637\u0641\u064b\u0627 \u0644\u0645\u0643\u064a\u062f\u0629 \u0627\u0644\u0643\u0641\u0627\u0631 \u0623\u0648 \u0645\u0646\u062d\u0627\u0632\u064b\u0627 \u0625\u0644\u0649 \u062c\u0645\u0627\u0639\u0629 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u062d\u0627\u0636\u0631\u064a \u0627\u0644\u062d\u0631\u0628 \u062d\u064a\u062b \u0643\u0627\u0646\u0648\u0627\u060c \u0641\u0642\u062f \u0627\u0633\u062a\u062d\u0642 \u0627\u0644\u063a\u0636\u0628 \u0645\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0645\u0642\u0627\u0645\u0647 \u062c\u0647\u0646\u0645\u060c \u0648\u0628\u0626\u0633 \u0627\u0644\u0645\u0635\u064a\u0631 \u0648\u0627\u0644\u0645\u0646\u0642\u0644\u0628.","8:17":"\u0641\u0644\u0645 \u062a\u0642\u062a\u0644\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u064a\u0648\u0645 \xab\u0628\u062f\u0631\xbb \u060c \u0648\u0644\u0643\u0646 \u0627\u0644\u0644\u0647 \u0642\u062a\u0644\u0647\u0645\u060c \u062d\u064a\u062b \u0623\u0639\u0627\u0646\u0643\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643\u060c \u0648\u0645\u0627 \u0631\u0645\u064a\u062a \u062d\u064a\u0646 \u0631\u0645\u064a\u062a -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0648\u0644\u0643\u0646 \u0627\u0644\u0644\u0647 \u0631\u0645\u0649\u060c \u062d\u064a\u062b \u0623\u0648\u0635\u0644 \u0627\u0644\u0631\u0645\u064a\u0629 \u0627\u0644\u062a\u064a \u0631\u0645\u064a\u062a\u0647\u0627 \u0625\u0644\u0649 \u0648\u062c\u0648\u0647 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646; \u0648\u0644\u064a\u062e\u062a\u0628\u0631 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u064a\u0648\u0635\u0644\u0647\u0645 \u0628\u0627\u0644\u062c\u0647\u0627\u062f \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0627\u0644\u062f\u0631\u062c\u0627\u062a\u060c \u0648\u064a\u0639\u0631\u0651\u0650\u0641\u0647\u0645 \u0646\u0639\u0645\u062a\u0647 \u0639\u0644\u064a\u0647\u0645\u060c \u0641\u064a\u0634\u0643\u0631\u0648\u0627 \u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0639\u0644\u0649 \u0630\u0644\u0643. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0633\u0645\u064a\u0639 \u0644\u062f\u0639\u0627\u0626\u0643\u0645 \u0648\u0623\u0642\u0648\u0627\u0644\u0643\u0645 \u0645\u0627 \u0623\u0633\u0631\u0631\u062a\u0645 \u0628\u0647 \u0648\u0645\u0627 \u0623\u0639\u0644\u0646\u062a\u0645\u060c \u0639\u0644\u064a\u0645 \u0628\u0645\u0627 \u0641\u064a\u0647 \u0635\u0644\u0627\u062d \u0639\u0628\u0627\u062f\u0647.","8:18":"\u0647\u0630\u0627 \u0627\u0644\u0641\u0639\u0644 \u0645\u0650\u0646 \u0642\u062a\u0644 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0648\u0631\u0645\u064a\u0647\u0645 \u062d\u064a\u0646 \u0627\u0646\u0647\u0632\u0645\u0648\u0627\u060c \u0648\u0627\u0644\u0628\u0644\u0627\u0621 \u0627\u0644\u062d\u0633\u0646 \u0628\u0646\u0635\u0631 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0639\u0644\u0649 \u0623\u0639\u062f\u0627\u0626\u0647\u0645\u060c \u0647\u0648 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0644\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0648\u0623\u0646 \u0627\u0644\u0644\u0647 -\u0641\u064a\u0645\u0627 \u064a\u064f\u0633\u0652\u062a\u0642\u0628\u0644- \u0645\u064f\u0636\u0639\u0650\u0641 \u0648\u0645\u064f\u0628\u0637\u0650\u0644 \u0645\u0643\u0631 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u062d\u062a\u0649 \u064a\u064e\u0630\u0650\u0644\u0651\u064f\u0648\u0627 \u0648\u064a\u0646\u0642\u0627\u062f\u0648\u0627 \u0644\u0644\u062d\u0642 \u0623\u0648 \u064a\u0647\u0644\u0643\u0648\u0627.","8:19":"\u0625\u0646 \u062a\u0637\u0644\u0628\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0643\u0641\u0627\u0631- \u0645\u0646 \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u0648\u0642\u0639 \u0628\u0623\u0633\u0647 \u0648\u0639\u0630\u0627\u0628\u0647 \u0639\u0644\u0649 \u0627\u0644\u0645\u0639\u062a\u062f\u064a\u0646 \u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0641\u0642\u062f \u0623\u062c\u0627\u0628 \u0627\u0644\u0644\u0647 \u0637\u0644\u0628\u0643\u0645\u060c \u062d\u064a\u0646 \u0623\u0648\u0642\u0639 \u0628\u0643\u0645 \u0645\u0650\u0646 \u0639\u0642\u0627\u0628\u0647 \u0645\u0627 \u0643\u0627\u0646 \u0646\u0643\u0627\u0644\u0627 \u0644\u0643\u0645 \u0648\u0639\u0628\u0631\u0629 \u0644\u0644\u0645\u062a\u0642\u064a\u0646\u060c \u0641\u0625\u0646 \u062a\u0646\u062a\u0647\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0643\u0641\u0627\u0631- \u0639\u0646 \u0627\u0644\u0643\u0641\u0631 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0642\u062a\u0627\u0644 \u0646\u0628\u064a\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0641\u0647\u0648 \u062e\u064a\u0631 \u0644\u0643\u0645 \u0641\u064a \u062f\u0646\u064a\u0627\u0643\u0645 \u0648\u0623\u062e\u0631\u0627\u0643\u0645\u060c \u0648\u0625\u0646 \u062a\u0639\u0648\u062f\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u062d\u0631\u0628 \u0648\u0642\u062a\u0627\u0644 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0642\u062a\u0627\u0644 \u0623\u062a\u0628\u0627\u0639\u0647 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0646\u064e\u0639\u064f\u062f\u0652 \u0628\u0647\u0632\u064a\u0645\u062a\u0643\u0645 \u0643\u0645\u0627 \u0647\u064f\u0632\u0645\u062a\u0645 \u064a\u0648\u0645 \xab\u0628\u062f\u0631\xbb \u060c \u0648\u0644\u0646 \u062a\u063a\u0646\u064a \u0639\u0646\u0643\u0645 \u062c\u0645\u0627\u0639\u062a\u0643\u0645 \u0634\u064a\u0626\u064b\u0627\u060c \u0643\u0645\u0627 \u0644\u0645 \u062a\u063a\u0646 \u0639\u0646\u0643\u0645 \u064a\u0648\u0645 \xab\u0628\u062f\u0631\xbb \u0645\u0639 \u0643\u062b\u0631\u0629 \u0639\u062f\u062f\u0643\u0645 \u0648\u0639\u062a\u0627\u062f\u0643\u0645 \u0648\u0642\u0644\u0629 \u0639\u062f\u062f \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0648\u0639\u062f\u062a\u0647\u0645\u060c \u0648\u0623\u0646 \u0627\u0644\u0644\u0647 \u0645\u0639 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u062a\u0623\u064a\u064a\u062f\u0647 \u0648\u0646\u0635\u0631\u0647.","8:20":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0623\u0637\u064a\u0639\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0641\u064a\u0645\u0627 \u0623\u0645\u0631\u0643\u0645 \u0628\u0647 \u0648\u0646\u0647\u0627\u0643\u0645 \u0639\u0646\u0647\u060c \u0648\u0644\u0627 \u062a\u062a\u0631\u0643\u0648\u0627 \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u0648\u0637\u0627\u0639\u0629 \u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0623\u0646\u062a\u0645 \u062a\u0633\u0645\u0639\u0648\u0646 \u0645\u0627 \u064a\u062a\u0644\u0649 \u0639\u0644\u064a\u0643\u0645 \u0641\u064a \u0627\u0644\u0642\u0631\u0622\u0646 \u0645\u0646 \u0627\u0644\u062d\u062c\u062c \u0648\u0627\u0644\u0628\u0631\u0627\u0647\u064a\u0646.","8:21":"\u0648\u0644\u0627 \u062a\u0643\u0648\u0646\u0648\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0641\u064a \u0645\u062e\u0627\u0644\u0641\u0629 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0643\u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0625\u0630\u0627 \u0633\u0645\u0639\u0648\u0627 \u0643\u062a\u0627\u0628 \u0627\u0644\u0644\u0647 \u064a\u062a\u0644\u0649 \u0639\u0644\u064a\u0647\u0645 \u0642\u0627\u0644\u0648\u0627: \u0633\u0645\u0639\u0646\u0627 \u0628\u0622\u0630\u0627\u0646\u0646\u0627\u060c \u0648\u0647\u0645 \u0641\u064a \u0627\u0644\u062d\u0642\u064a\u0642\u0629 \u0644\u0627 \u064a\u062a\u062f\u0628\u0631\u0648\u0646 \u0645\u0627 \u0633\u0645\u0639\u0648\u0627\u060c \u0648\u0644\u0627 \u064a\u0641\u0643\u0631\u0648\u0646 \u0641\u064a\u0647.","8:22":"\u0625\u0646\u0651\u064e \u0634\u0631 \u0645\u0627 \u062f\u0628\u0651\u064e \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 -\u0645\u0650\u0646\u0652 \u062e\u064e\u0644\u0652\u0642 \u0627\u0644\u0644\u0647- \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0627\u0644\u0635\u0645\u0651\u064f \u0627\u0644\u0630\u064a\u0646 \u0627\u0646\u0633\u062f\u0651\u064e\u062a \u0622\u0630\u0627\u0646\u0647\u0645 \u0639\u0646 \u0633\u0645\u0627\u0639 \u0627\u0644\u062d\u0642 \u0641\u0644\u0627 \u064a\u0633\u0645\u0639\u0648\u0646\u060c \u0627\u0644\u0628\u0643\u0645 \u0627\u0644\u0630\u064a\u0646 \u062e\u0631\u0633\u062a \u0623\u0644\u0633\u0646\u062a\u0647\u0645 \u0639\u0646 \u0627\u0644\u0646\u0637\u0642 \u0628\u0647 \u0641\u0644\u0627 \u064a\u0646\u0637\u0642\u0648\u0646\u060c \u0647\u0624\u0644\u0627\u0621 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0644\u0627 \u064a\u0639\u0642\u0644\u0648\u0646 \u0639\u0646 \u0627\u0644\u0644\u0647 \u0623\u0645\u0631\u0647 \u0648\u0646\u0647\u064a\u0647.","8:23":"\u0648\u0644\u0648 \u0639\u0644\u0645 \u0627\u0644\u0644\u0647 \u0641\u064a \u0647\u0624\u0644\u0627\u0621 \u062e\u064a\u0631\u064b\u0627 \u0644\u0623\u0633\u0645\u0639\u0647\u0645 \u0645\u0648\u0627\u0639\u0638 \u0627\u0644\u0642\u0631\u0622\u0646 \u0648\u0639\u0628\u0631\u0647 \u062d\u062a\u0649 \u064a\u0639\u0642\u0644\u0648\u0627 \u0639\u0646 \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644 \u062d\u062c\u062c\u0647 \u0648\u0628\u0631\u0627\u0647\u064a\u0646\u0647\u060c \u0648\u0644\u0643\u0646\u0647 \u0639\u0644\u0645 \u0623\u0646\u0647 \u0644\u0627 \u062e\u064a\u0631 \u0641\u064a\u0647\u0645 \u0648\u0623\u0646\u0647\u0645 \u0644\u0627 \u064a\u0624\u0645\u0646\u0648\u0646\u060c \u0648\u0644\u0648 \u0623\u0633\u0645\u0639\u0647\u0645 -\u0639\u0644\u0649 \u0627\u0644\u0641\u0631\u0636 \u0648\u0627\u0644\u062a\u0642\u062f\u064a\u0631- \u0644\u062a\u0648\u0644\u0651\u064e\u0648\u0627 \u0639\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0642\u0635\u062f\u064b\u0627 \u0648\u0639\u0646\u0627\u062f\u064b\u0627 \u0628\u0639\u062f \u0641\u0647\u0645\u0647\u0645 \u0644\u0647\u060c \u0648\u0647\u0645 \u0645\u0639\u0631\u0636\u0648\u0646 \u0639\u0646\u0647\u060c \u0644\u0627 \u0627\u0644\u062a\u0641\u0627\u062a \u0644\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u062d\u0642 \u0628\u0648\u062c\u0647 \u0645\u0646 \u0627\u0644\u0648\u062c\u0648\u0647.","8:24":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u0650\u0642\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0631\u0628\u064b\u0627 \u0648\u0628\u0645\u062d\u0645\u062f \u0646\u0628\u064a\u064b\u0627 \u0648\u0631\u0633\u0648\u0644\u0627 \u0627\u0633\u062a\u062c\u064a\u0628\u0648\u0627 \u0644\u0644\u0647 \u0648\u0644\u0644\u0631\u0633\u0648\u0644 \u0628\u0627\u0644\u0637\u0627\u0639\u0629 \u0625\u0630\u0627 \u062f\u0639\u0627\u0643\u0645 \u0644\u0645\u0627 \u064a\u062d\u064a\u064a\u0643\u0645 \u0645\u0646 \u0627\u0644\u062d\u0642\u060c \u0641\u0641\u064a \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0625\u0635\u0644\u0627\u062d \u062d\u064a\u0627\u062a\u0643\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0627\u0639\u0644\u0645\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0623\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0647\u0648 \u0627\u0644\u0645\u062a\u0635\u0631\u0641 \u0641\u064a \u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0634\u064a\u0627\u0621\u060c \u0648\u0627\u0644\u0642\u0627\u062f\u0631 \u0639\u0644\u0649 \u0623\u0646 \u064a\u062d\u0648\u0644 \u0628\u064a\u0646 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0648\u0645\u0627 \u064a\u0634\u062a\u0647\u064a\u0647 \u0642\u0644\u0628\u0647\u060c \u0641\u0647\u0648 \u0633\u0628\u062d\u0627\u0646\u0647 \u0627\u0644\u0630\u064a \u064a\u0646\u0628\u063a\u064a \u0623\u0646 \u064a\u0633\u062a\u062c\u0627\u0628 \u0644\u0647 \u0625\u0630\u0627 \u062f\u0639\u0627\u0643\u0645; \u0625\u0630 \u0628\u064a\u062f\u0647 \u0645\u0644\u0643\u0648\u062a \u0643\u0644 \u0634\u064a\u0621\u060c \u0648\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646\u0643\u0645 \u062a\u064f\u062c\u0645\u0639\u0648\u0646 \u0644\u064a\u0648\u0645 \u0644\u0627 \u0631\u064a\u0628 \u0641\u064a\u0647\u060c \u0641\u064a\u062c\u0627\u0632\u064a \u0643\u0644\u0627 \u0628\u0645\u0627 \u064a\u0633\u062a\u062d\u0642.","8:25":"\u0648\u0627\u062d\u0630\u0631\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0627\u062e\u062a\u0628\u0627\u0631\u064b\u0627 \u0648\u0645\u062d\u0646\u0629 \u064a\u064f\u0639\u064e\u0645\u0651\u064f \u0628\u0647\u0627 \u0627\u0644\u0645\u0633\u064a\u0621 \u0648\u063a\u064a\u0631\u0647 \u0644\u0627 \u064a\u064f\u062e\u064e\u0635 \u0628\u0647\u0627 \u0623\u0647\u0644 \u0627\u0644\u0645\u0639\u0627\u0635\u064a \u0648\u0644\u0627 \u0645\u064e\u0646 \u0628\u0627\u0634\u0631 \u0627\u0644\u0630\u0646\u0628\u060c \u0628\u0644 \u062a\u0635\u064a\u0628 \u0627\u0644\u0635\u0627\u0644\u062d\u064a\u0646 \u0645\u0639\u0647\u0645 \u0625\u0630\u0627 \u0642\u062f\u0631\u0648\u0627 \u0639\u0644\u0649 \u0625\u0646\u0643\u0627\u0631 \u0627\u0644\u0638\u0644\u0645 \u0648\u0644\u0645 \u064a\u0646\u0643\u0631\u0648\u0647\u060c \u0648\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0634\u062f\u064a\u062f \u0627\u0644\u0639\u0642\u0627\u0628 \u0644\u0645\u0646 \u062e\u0627\u0644\u0641 \u0623\u0645\u0631\u0647 \u0648\u0646\u0647\u064a\u0647.","8:26":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0646\u0650\u0639\u064e\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0625\u0630 \u0623\u0646\u062a\u0645 \u0628\u0640 \xab\u0645\u0643\u0629\xbb \u0642\u0644\u064a\u0644\u0648 \u0627\u0644\u0639\u062f\u062f \u0645\u0642\u0647\u0648\u0631\u0648\u0646\u060c \u062a\u062e\u0627\u0641\u0648\u0646 \u0623\u0646 \u064a\u0623\u062e\u0630\u0643\u0645 \u0627\u0644\u0643\u0641\u0627\u0631 \u0628\u0633\u0631\u0639\u0629\u060c \u0641\u062c\u0639\u0644 \u0644\u0643\u0645 \u0645\u0623\u0648\u0649 \u062a\u0623\u0648\u0648\u0646 \u0625\u0644\u064a\u0647 \u0648\u0647\u0648 \xab\u0627\u0644\u0645\u062f\u064a\u0646\u0629\xbb \u060c \u0648\u0642\u0648\u0651\u064e\u0627\u0643\u0645 \u0628\u0646\u0635\u0631\u0647 \u0639\u0644\u064a\u0647\u0645 \u064a\u0648\u0645 \xab\u0628\u062f\u0631\xbb \u060c \u0648\u0623\u0637\u0639\u0645\u0643\u0645 \u0645\u0646 \u0627\u0644\u0637\u064a\u0628\u0627\u062a -\u0627\u0644\u062a\u064a \u0645\u0646 \u062c\u0645\u0644\u062a\u0647\u0627 \u0627\u0644\u063a\u0646\u0627\u0626\u0645-; \u0644\u0643\u064a \u062a\u0634\u0643\u0631\u0648\u0627 \u0644\u0647 \u0639\u0644\u0649 \u0645\u0627 \u0631\u0632\u0642\u0643\u0645 \u0648\u0623\u0646\u0639\u0645 \u0628\u0647 \u0639\u0644\u064a\u0643\u0645.","8:27":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647 \u0644\u0627 \u062a\u062e\u0648\u0646\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0628\u062a\u0631\u0643 \u0645\u0627 \u0623\u0648\u062c\u0628\u0647 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0648\u0641\u0650\u0639\u0652\u0644 \u0645\u0627 \u0646\u0647\u0627\u0643\u0645 \u0639\u0646\u0647\u060c \u0648\u0644\u0627 \u062a\u0641\u0631\u0637\u0648\u0627 \u0641\u064a\u0645\u0627 \u0627\u0626\u062a\u0645\u0646\u0643\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u060c \u0648\u0623\u0646\u062a\u0645 \u062a\u0639\u0644\u0645\u0648\u0646 \u0623\u0646\u0647 \u0623\u0645\u0627\u0646\u0629 \u064a\u062c\u0628 \u0627\u0644\u0648\u0641\u0627\u0621 \u0628\u0647\u0627.","8:28":"\u0648\u0627\u0639\u0644\u0645\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0623\u0646 \u0623\u0645\u0648\u0627\u0644\u0643\u0645 \u0627\u0644\u062a\u064a \u0627\u0633\u062a\u062e\u0644\u0641\u0643\u0645 \u0627\u0644\u0644\u0647 \u0641\u064a\u0647\u0627\u060c \u0648\u0623\u0648\u0644\u0627\u062f\u0643\u0645 \u0627\u0644\u0630\u064a\u0646 \u0648\u0647\u0628\u0647\u0645 \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0627\u062e\u062a\u0628\u0627\u0631 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0648\u0627\u0628\u062a\u0644\u0627\u0621 \u0644\u0639\u0628\u0627\u062f\u0647; \u0644\u064a\u0639\u0644\u0645 \u0623\u064a\u0634\u0643\u0631\u0648\u0646\u0647 \u0639\u0644\u064a\u0647\u0627 \u0648\u064a\u0637\u064a\u0639\u0648\u0646\u0647 \u0641\u064a\u0647\u0627\u060c \u0623\u0648 \u064a\u0646\u0634\u063a\u0644\u0648\u0646 \u0628\u0647\u0627 \u0639\u0646\u0647\u061f \u0648\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0639\u0646\u062f\u0647 \u062e\u064a\u0631 \u0648\u062b\u0648\u0627\u0628 \u0639\u0638\u064a\u0645 \u0644\u0645\u0646 \u0627\u062a\u0642\u0627\u0647 \u0648\u0623\u0637\u0627\u0639\u0647.","8:29":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647 \u0625\u0646 \u062a\u062a\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0628\u0641\u0639\u0644 \u0623\u0648\u0627\u0645\u0631\u0647 \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0646\u0648\u0627\u0647\u064a\u0647 \u064a\u062c\u0639\u0644 \u0644\u0643\u0645 \u0641\u0635\u0644\u0627 \u0628\u064a\u0646 \u0627\u0644\u062d\u0642 \u0648\u0627\u0644\u0628\u0627\u0637\u0644\u060c \u0648\u064a\u064e\u0645\u062d\u064f \u0639\u0646\u0643\u0645 \u0645\u0627 \u0633\u0644\u0641 \u0645\u0646 \u0630\u0646\u0648\u0628\u0643\u0645 \u0648\u064a\u0633\u062a\u0631\u0647\u0627 \u0639\u0644\u064a\u0643\u0645\u060c \u0641\u0644\u0627 \u064a\u0624\u0627\u062e\u0630\u0643\u0645 \u0628\u0647\u0627. \u0648\u0627\u0644\u0644\u0647 \u0630\u0648 \u0627\u0644\u0625\u062d\u0633\u0627\u0646 \u0648\u0627\u0644\u0639\u0637\u0627\u0621 \u0627\u0644\u0643\u062b\u064a\u0631 \u0627\u0644\u0648\u0627\u0633\u0639.","8:30":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u062d\u064a\u0646 \u064a\u0643\u064a\u062f \u0644\u0643 \u0645\u0634\u0631\u0643\u0648 \u0642\u0648\u0645\u0643 \u0628\u0640 \xab\u0645\u0643\u0651\u064e\u0629\xbb ; \u0644\u064a\u062d\u0628\u0633\u0648\u0643 \u0623\u0648 \u064a\u0642\u062a\u0644\u0648\u0643 \u0623\u0648 \u064a\u0646\u0641\u0648\u0643 \u0645\u0646 \u0628\u0644\u062f\u0643. \u0648\u064a\u0643\u064a\u062f\u0648\u0646 \u0644\u0643\u060c \u0648\u0631\u062f\u0651\u064e \u0627\u0644\u0644\u0647 \u0645\u0643\u0631\u0647\u0645 \u0639\u0644\u064a\u0647\u0645 \u062c\u0632\u0627\u0621 \u0644\u0647\u0645\u060c \u0648\u064a\u0645\u0643\u0631 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0644\u0644\u0647 \u062e\u064a\u0631 \u0627\u0644\u0645\u0627\u0643\u0631\u064a\u0646.","8:31":"\u0648\u0625\u0630\u0627 \u062a\u062a\u0644\u0649 \u0639\u0644\u0649 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0622\u064a\u0627\u062a \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0639\u0632\u064a\u0632 \u0642\u0627\u0644\u0648\u0627 \u062c\u0647\u0644\u0627 \u0645\u0646\u0647\u0645 \u0648\u0639\u0646\u0627\u062f\u064b\u0627 \u0644\u0644\u062d\u0642: \u0642\u062f \u0633\u0645\u0639\u0646\u0627 \u0647\u0630\u0627 \u0645\u0646 \u0642\u0628\u0644\u060c \u0644\u0648 \u0646\u0634\u0627\u0621 \u0644\u0642\u0644\u0646\u0627 \u0645\u062b\u0644 \u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0622\u0646\u060c \u0645\u0627 \u0647\u0630\u0627 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0630\u064a \u062a\u062a\u0644\u0648\u0647 \u0639\u0644\u064a\u0646\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0625\u0644\u0627 \u0623\u0643\u0627\u0630\u064a\u0628 \u0627\u0644\u0623\u0648\u0644\u064a\u0646.","8:32":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0642\u0648\u0644 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0645\u0646 \u0642\u0648\u0645\u0643 \u062f\u0627\u0639\u064a\u0646 \u0627\u0644\u0644\u0647: \u0625\u0646 \u0643\u0627\u0646 \u0645\u0627 \u062c\u0627\u0621 \u0628\u0647 \u0645\u062d\u0645\u062f \u0647\u0648 \u0627\u0644\u062d\u0642 \u0645\u0650\u0646 \u0639\u0646\u062f\u0643 \u0641\u0623\u0645\u0637\u0631 \u0639\u0644\u064a\u0646\u0627 \u062d\u062c\u0627\u0631\u0629 \u0645\u0646 \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u0623\u0648 \u0627\u0626\u062a\u0646\u0627 \u0628\u0639\u0630\u0627\u0628 \u0634\u062f\u064a\u062f \u0645\u0648\u062c\u0639.","8:33":"\u0648\u0645\u0627 \u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0644\u064a\u0639\u0630\u0651\u0650\u0628 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646\u060c \u0648\u0623\u0646\u062a -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0628\u064a\u0646 \u0638\u0647\u0631\u0627\u0646\u064e\u064a\u0652\u0647\u0645\u060c \u0648\u0645\u0627 \u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u0645\u0639\u0630\u0651\u0650\u0628\u0647\u0645\u060c \u0648\u0647\u0645 \u064a\u0633\u062a\u063a\u0641\u0631\u0648\u0646 \u0645\u0646 \u0630\u0646\u0648\u0628\u0647\u0645.","8:34":"\u0648\u0643\u064a\u0641 \u0644\u0627 \u064a\u0633\u062a\u062d\u0642\u0651\u064f\u0648\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647\u060c \u0648\u0647\u0645 \u064a\u0635\u062f\u0648\u0646 \u0623\u0648\u0644\u064a\u0627\u0621\u0647 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0639\u0646 \u0627\u0644\u0637\u0648\u0627\u0641 \u0628\u0627\u0644\u0643\u0639\u0628\u0629 \u0648\u0627\u0644\u0635\u0644\u0627\u0629 \u0641\u064a \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u062d\u0631\u0627\u0645\u061f \u0648\u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u0623\u0648\u0644\u064a\u0627\u0621 \u0627\u0644\u0644\u0647\u060c \u0625\u0646\u0652 \u0623\u0648\u0644\u064a\u0627\u0621 \u0627\u0644\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0630\u064a\u0646 \u064a\u062a\u0642\u0648\u0646\u0647 \u0628\u0623\u062f\u0627\u0621 \u0641\u0631\u0627\u0626\u0636\u0647 \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0645\u0639\u0627\u0635\u064a\u0647\u060c \u0648\u0644\u0643\u0646 \u0623\u0643\u062b\u0631 \u0627\u0644\u0643\u0641\u0627\u0631 \u0644\u0627 \u064a\u0639\u0644\u0645\u0648\u0646; \u0641\u0644\u0630\u0644\u0643 \u0627\u062f\u0651\u064e\u0639\u0648\u0627 \u0644\u0623\u0646\u0641\u0633\u0647\u0645 \u0623\u0645\u0631\u064b\u0627\u060c \u063a\u064a\u0631\u0647\u0645 \u0623\u0648\u0644\u0649 \u0628\u0647.","8:35":"\u0648\u0645\u0627 \u0643\u0627\u0646 \u0635\u0644\u0627\u062a\u0647\u0645 \u0639\u0646\u062f \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u062d\u0631\u0627\u0645 \u0625\u0644\u0627 \u0635\u0641\u064a\u0631\u064b\u0627 \u0648\u062a\u0635\u0641\u064a\u0642\u064b\u0627. \u0641\u0630\u0648\u0642\u0648\u0627 \u0639\u0630\u0627\u0628 \u0627\u0644\u0642\u062a\u0644 \u0648\u0627\u0644\u0623\u0633\u0631 \u064a\u0648\u0645 \xab\u0628\u062f\u0631\xbb ; \u0628\u0633\u0628\u0628 \u062c\u062d\u0648\u062f\u0643\u0645 \u0648\u0623\u0641\u0639\u0627\u0644\u0643\u0645 \u0627\u0644\u062a\u064a \u0644\u0627 \u064a\u064f\u0642\u0652\u062f\u0645 \u0639\u0644\u064a\u0647\u0627 \u0625\u0644\u0627 \u0627\u0644\u0643\u0641\u0631\u0629\u060c \u0627\u0644\u062c\u0627\u062d\u062f\u0648\u0646 \u062a\u0648\u062d\u064a\u062f \u0631\u0628\u0647\u0645 \u0648\u0631\u0633\u0627\u0644\u0629 \u0646\u0628\u064a\u0647\u0645.","8:36":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u062c\u062d\u062f\u0648\u0627 \u0648\u062d\u062f\u0627\u0646\u064a\u0629 \u0627\u0644\u0644\u0647 \u0648\u0639\u0635\u0648\u0627 \u0631\u0633\u0648\u0644\u0647 \u064a\u0646\u0641\u0642\u0648\u0646 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0641\u064a\u0639\u0637\u0648\u0646\u0647\u0627 \u0623\u0645\u062b\u0627\u0644\u0647\u0645 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0648\u0623\u0647\u0644 \u0627\u0644\u0636\u0644\u0627\u0644\u060c \u0644\u064a\u0635\u062f\u0648\u0627 \u0639\u0646 \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0648\u064a\u0645\u0646\u0639\u0648\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0639\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0641\u064a\u0646\u0641\u0642\u0648\u0646 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0641\u064a \u0630\u0644\u0643\u060c \u062b\u0645 \u062a\u0643\u0648\u0646 \u0639\u0627\u0642\u0628\u0629 \u0646\u0641\u0642\u062a\u0647\u0645 \u062a\u0644\u0643 \u0646\u062f\u0627\u0645\u0629 \u0648\u062d\u0633\u0631\u0629 \u0639\u0644\u064a\u0647\u0645; \u0644\u0623\u0646 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u062a\u0630\u0647\u0628\u060c \u0648\u0644\u0627 \u064a\u0638\u0641\u0631\u0648\u0646 \u0628\u0645\u0627 \u064a\u0623\u0645\u064f\u0644\u0648\u0646 \u0645\u0650\u0646 \u0625\u0637\u0641\u0627\u0621 \u0646\u0648\u0631 \u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u0635\u062f \u0639\u0646 \u0633\u0628\u064a\u0644\u0647\u060c \u062b\u0645 \u064a\u0647\u0632\u0645\u0647\u0645 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0622\u062e\u0631 \u0627\u0644\u0623\u0645\u0631. \u0648\u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0625\u0644\u0649 \u062c\u0647\u0646\u0645 \u064a\u062d\u0634\u0631\u0648\u0646 \u0641\u064a\u0639\u0630\u0628\u0648\u0646 \u0641\u064a\u0647\u0627.","8:37":"\u064a\u062d\u0634\u0631 \u0627\u0644\u0644\u0647 \u0648\u064a\u062e\u0632\u064a \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0628\u0631\u0628\u0647\u0645\u060c \u0648\u0623\u0646\u0641\u0642\u0648\u0627 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0644\u0645\u0646\u0639 \u0627\u0644\u0646\u0627\u0633 \u0639\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u0635\u062f \u0639\u0646 \u0633\u0628\u064a\u0644\u0647; \u0644\u064a\u0645\u064a\u0632 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0627\u0644\u062e\u0628\u064a\u062b \u0645\u0646 \u0627\u0644\u0637\u064a\u0628\u060c \u0648\u064a\u062c\u0639\u0644 \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0627\u0644 \u0627\u0644\u062d\u0631\u0627\u0645 \u0627\u0644\u0630\u064a \u0623\u064f\u0646\u0641\u0642 \u0644\u0644\u0635\u062f\u0651\u0650 \u0639\u0646 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u0628\u0639\u0636\u0647 \u0641\u0648\u0642 \u0628\u0639\u0636 \u0645\u062a\u0631\u0627\u0643\u0645\u064b\u0627 \u0645\u062a\u0631\u0627\u0643\u0628\u064b\u0627\u060c \u0641\u064a\u062c\u0639\u0644\u0647 \u0641\u064a \u0646\u0627\u0631 \u062c\u0647\u0646\u0645\u060c \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0641\u0627\u0631 \u0647\u0645 \u0627\u0644\u062e\u0627\u0633\u0631\u0648\u0646 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629.","8:38":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0644\u0630\u064a\u0646 \u062c\u062d\u062f\u0648\u0627 \u0648\u062d\u062f\u0627\u0646\u064a\u0629 \u0627\u0644\u0644\u0647 \u0645\u0650\u0646 \u0645\u0634\u0631\u0643\u064a \u0642\u0648\u0645\u0643: \u0625\u0646 \u064a\u0646\u0632\u062c\u0631\u0648\u0627 \u0639\u0646 \u0627\u0644\u0643\u0641\u0631 \u0648\u0639\u062f\u0627\u0648\u0629 \u0627\u0644\u0646\u0628\u064a \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u064a\u0631\u062c\u0639\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0648\u0639\u062f\u0645 \u0642\u062a\u0627\u0644 \u0627\u0644\u0631\u0633\u0648\u0644 \u0648\u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u064a\u063a\u0641\u0631 \u0627\u0644\u0644\u0647 \u0644\u0647\u0645 \u0645\u0627 \u0633\u0628\u0642 \u0645\u0646 \u0627\u0644\u0630\u0646\u0648\u0628\u060c \u0641\u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u064a\u062c\u064f\u0628\u0651\u064f \u0645\u0627 \u0642\u0628\u0644\u0647. \u0648\u0625\u0646 \u064a\u064e\u0639\u064f\u062f\u0652 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0644\u0642\u062a\u0627\u0644\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0628\u0639\u062f \u0627\u0644\u0648\u0642\u0639\u0629 \u0627\u0644\u062a\u064a \u0623\u0648\u0642\u0639\u062a\u0647\u0627 \u0628\u0647\u0645 \u064a\u0648\u0645 \xab\u0628\u062f\u0631\xbb \u0641\u0642\u062f \u0633\u0628\u0642\u062a \u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u0623\u0648\u0644\u064a\u0646\u060c \u0648\u0647\u064a \u0623\u0646\u0647\u0645 \u0625\u0630\u0627 \u0643\u0630\u0628\u0648\u0627 \u0648\u0627\u0633\u062a\u0645\u0631\u0648\u0627 \u0639\u0644\u0649 \u0639\u0646\u0627\u062f\u0647\u0645 \u0623\u0646\u0646\u0627 \u0646\u0639\u0627\u062c\u0644\u0647\u0645 \u0628\u0627\u0644\u0639\u0630\u0627\u0628 \u0648\u0627\u0644\u0639\u0642\u0648\u0628\u0629.","8:39":"\u0648\u0642\u0627\u062a\u0644\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u062d\u062a\u0649 \u0644\u0627 \u064a\u0643\u0648\u0646 \u0634\u0650\u0631\u0652\u0643\u064c \u0648\u0635\u062f\u0651\u064c \u0639\u0646 \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647; \u0648\u0644\u0627 \u064a\u064f\u0639\u0652\u0628\u064e\u062f\u064e \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647\u060c \u0641\u064a\u0631\u062a\u0641\u0639 \u0627\u0644\u0628\u0644\u0627\u0621 \u0639\u0646 \u0639\u0628\u0627\u062f \u0627\u0644\u0644\u0647 \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u062d\u062a\u0649 \u064a\u0643\u0648\u0646 \u0627\u0644\u062f\u064a\u0646 \u0648\u0627\u0644\u0637\u0627\u0639\u0629 \u0648\u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0643\u0644\u0647\u0627 \u0644\u0644\u0647 \u062e\u0627\u0644\u0635\u0629 \u062f\u0648\u0646 \u063a\u064a\u0631\u0647\u060c \u0641\u0625\u0646 \u0627\u0646\u0632\u062c\u0631\u0648\u0627 \u0639\u0646 \u0642\u062a\u0646\u0629 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0648\u0639\u0646 \u0627\u0644\u0634\u0631\u0643 \u0628\u0627\u0644\u0644\u0647 \u0648\u0635\u0627\u0631\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u062f\u064a\u0646 \u0627\u0644\u062d\u0642 \u0645\u0639\u0643\u0645\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0645\u0627 \u064a\u0639\u0645\u0644\u0648\u0646 \u0645\u0650\u0646 \u062a\u0631\u0643 \u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u062f\u062e\u0648\u0644 \u0641\u064a \u0627\u0644\u0625\u0633\u0644\u0627\u0645.","8:40":"\u0648\u0625\u0646 \u0623\u0639\u0631\u0636 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0639\u0645\u0651\u064e\u0627 \u062f\u0639\u0648\u062a\u0645\u0648\u0647\u0645 \u0625\u0644\u064a\u0647 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0645\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u062a\u0631\u0643 \u0642\u062a\u0627\u0644\u0643\u0645\u060c \u0648\u0623\u0628\u064e\u0648\u0652\u0627 \u0625\u0644\u0627 \u0627\u0644\u0625\u0635\u0631\u0627\u0631 \u0639\u0644\u0649 \u0627\u0644\u0643\u0641\u0631 \u0648\u0642\u062a\u0627\u0644\u0643\u0645\u060c \u0641\u0623\u064a\u0642\u0650\u0646\u0648\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0645\u0639\u064a\u0646\u0643\u0645 \u0648\u0646\u0627\u0635\u0631\u0643\u0645 \u0639\u0644\u064a\u0647\u0645. \u0646\u0650\u0639\u0652\u0645\u064e \u0627\u0644\u0645\u0639\u064a\u0646 \u0648\u0627\u0644\u0646\u0627\u0635\u0631 \u0644\u0643\u0645 \u0648\u0644\u0623\u0648\u0644\u064a\u0627\u0626\u0647 \u0639\u0644\u0649 \u0623\u0639\u062f\u0627\u0626\u0643\u0645.","8:41":"\u0648\u0627\u0639\u0644\u0645\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0623\u0646 \u0645\u0627 \u0638\u064e\u0641\u0650\u0631\u062a\u0645 \u0628\u0647 \u0645\u0650\u0646 \u0639\u062f\u0648\u0643\u0645 \u0628\u0627\u0644\u062c\u0647\u0627\u062f \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0641\u0623\u0631\u0628\u0639\u0629 \u0623\u062e\u0645\u0627\u0633\u0647 \u0644\u0644\u0645\u0642\u0627\u062a\u0644\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u062d\u0636\u0631\u0648\u0627 \u0627\u0644\u0645\u0639\u0631\u0643\u0629\u060c \u0648\u0627\u0644\u062e\u0645\u0633 \u0627\u0644\u0628\u0627\u0642\u064a \u064a\u062c\u0632\u0651\u064e\u0623\u064f \u062e\u0645\u0633\u0629 \u0623\u0642\u0633\u0627\u0645: \u0627\u0644\u0623\u0648\u0644 \u0644\u0644\u0647 \u0648\u0644\u0644\u0631\u0633\u0648\u0644\u060c \u0641\u064a\u062c\u0639\u0644 \u0641\u064a \u0645\u0635\u0627\u0644\u062d \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0627\u0644\u0639\u0627\u0645\u0629\u060c \u0648\u0627\u0644\u062b\u0627\u0646\u064a \u0644\u0630\u0648\u064a \u0642\u0631\u0627\u0628\u0629 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0647\u0645 \u0628\u0646\u0648 \u0647\u0627\u0634\u0645 \u0648\u0628\u0646\u0648 \u0627\u0644\u0645\u0637\u0644\u0628\u060c \u062c\u064f\u0639\u0650\u0644 \u0644\u0647\u0645 \u0627\u0644\u062e\u0645\u0633 \u0645\u0643\u0627\u0646 \u0627\u0644\u0635\u062f\u0642\u0629 \u0641\u0625\u0646\u0647\u0627 \u0644\u0627 \u062a\u062d\u0644\u0651\u064f \u0644\u0647\u0645\u060c \u0648\u0627\u0644\u062b\u0627\u0644\u062b \u0644\u0644\u064a\u062a\u0627\u0645\u0649\u060c \u0648\u0627\u0644\u0631\u0627\u0628\u0639 \u0644\u0644\u0645\u0633\u0627\u0643\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0644\u0627 \u064a\u0645\u0644\u0643\u0648\u0646 \u0645\u0627 \u064a\u0643\u0641\u064a\u0647\u0645 \u0648\u064a\u0633\u062f \u062d\u0627\u062c\u062a\u0647\u0645\u060c \u0648\u0627\u0644\u062e\u0627\u0645\u0633 \u0644\u0644\u0645\u0633\u0627\u0641\u0631 \u0627\u0644\u0630\u064a \u0627\u0646\u0642\u0637\u0639\u062a \u0628\u0647 \u0627\u0644\u0646\u0641\u0642\u0629\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u0645\u0642\u0631\u0651\u0650\u064a\u0646 \u0628\u062a\u0648\u062d\u064a\u062f \u0627\u0644\u0644\u0647 \u0645\u0637\u064a\u0639\u064a\u0646 \u0644\u0647\u060c \u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u0645\u0627 \u0623\u0646\u0632\u0644 \u0639\u0644\u0649 \u0639\u0628\u062f\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0645\u0646 \u0627\u0644\u0622\u064a\u0627\u062a \u0648\u0627\u0644\u0645\u062f\u062f \u0648\u0627\u0644\u0646\u0635\u0631 \u064a\u0648\u0645 \u0641\u064e\u0631\u064e\u0642 \u0628\u064a\u0646 \u0627\u0644\u062d\u0642 \u0648\u0627\u0644\u0628\u0627\u0637\u0644 \u0628\u0640 \xab\u0628\u062f\u0631\xbb \u060c \u064a\u0648\u0645 \u0627\u0644\u062a\u0642\u0649 \u062c\u064e\u0645\u0652\u0639\u064f \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0648\u062c\u064e\u0645\u0652\u0639\u064f \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646. \u0648\u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621 \u0642\u062f\u064a\u0631 \u0644\u0627 \u064a\u0639\u062c\u0632\u0647 \u0634\u064a\u0621.","8:42":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u062d\u064a\u0646\u0645\u0627 \u0643\u0646\u062a\u0645 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628 \u0627\u0644\u0648\u0627\u062f\u064a \u0627\u0644\u0623\u0642\u0631\u0628 \u0625\u0644\u0649 \xab\u0627\u0644\u0645\u062f\u064a\u0646\u0629\xbb \u060c \u0648\u0639\u062f\u0648\u0643\u0645 \u0646\u0627\u0632\u0644 \u0628\u062c\u0627\u0646\u0628 \u0627\u0644\u0648\u0627\u062f\u064a \u0627\u0644\u0623\u0642\u0635\u0649\u060c \u0648\u0639\u0650\u064a\u0631 \u0627\u0644\u062a\u062c\u0627\u0631\u0629 \u0641\u064a \u0645\u0643\u0627\u0646 \u0623\u0633\u0641\u0644 \u0645\u0646\u0643\u0645 \u0625\u0644\u0649 \u0633\u0627\u062d\u0644 \xab\u0627\u0644\u0628\u062d\u0631 \u0627\u0644\u0623\u062d\u0645\u0631\xbb \u060c \u0648\u0644\u0648 \u062d\u0627\u0648\u0644\u062a\u0645 \u0623\u0646 \u062a\u0636\u0639\u0648\u0627 \u0645\u0648\u0639\u062f\u064b\u0627 \u0644\u0647\u0630\u0627 \u0627\u0644\u0644\u0642\u0627\u0621 \u0644\u0627\u062e\u062a\u0644\u0641\u062a\u0645\u060c \u0648\u0644\u0643\u0646\u0651\u064e \u0627\u0644\u0644\u0647 \u062c\u0645\u0639\u0643\u0645 \u0639\u0644\u0649 \u063a\u064a\u0631 \u0645\u064a\u0639\u0627\u062f; \u0644\u064a\u0642\u0636\u064a \u0623\u0645\u0631\u064b\u0627 \u0643\u0627\u0646 \u0645\u0641\u0639\u0648\u0644\u0627 \u0628\u0646\u0635\u0631 \u0623\u0648\u0644\u064a\u0627\u0626\u0647\u060c \u0648\u062e\u0650\u0630\u0652\u0644\u0627\u0646 \u0623\u0639\u062f\u0627\u0626\u0647 \u0628\u0627\u0644\u0642\u062a\u0644 \u0648\u0627\u0644\u0623\u0633\u0631; \u0648\u0630\u0644\u0643 \u0644\u064a\u0647\u0644\u0643 \u0645\u0646 \u0647\u0644\u0643 \u0645\u0646\u0647\u0645 \u0639\u0646 \u062d\u062c\u0629 \u0644\u0644\u0647 \u062b\u0628\u062a\u062a \u0644\u0647 \u0641\u0639\u0627\u064a\u0646\u0647\u0627 \u0648\u0642\u0637\u0639\u062a \u0639\u0630\u0631\u0647\u060c \u0648\u0644\u064a\u062d\u064a\u0627 \u0645\u064e\u0646 \u062d\u064a\u0651\u064e \u0639\u0646 \u062d\u062c\u0629 \u0644\u0644\u0647 \u0642\u062f \u062b\u0628\u062a\u062a \u0648\u0638\u0647\u0631\u062a \u0644\u0647. \u0648\u0625\u0646 \u0627\u0644\u0644\u0647 \u0644\u0633\u0645\u064a\u0639 \u0644\u0623\u0642\u0648\u0627\u0644 \u0627\u0644\u0641\u0631\u064a\u0642\u064a\u0646\u060c \u0644\u0627 \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0634\u064a\u0621\u060c \u0639\u0644\u064a\u0645 \u0628\u0646\u064a\u0651\u064e\u0627\u062a\u0647\u0645 \u0648\u0623\u0639\u0645\u0627\u0644\u0647\u0645","8:43":"\u0648\u0627\u0630\u0643\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u062d\u064a\u0646\u0645\u0627 \u0623\u0631\u0627\u0643 \u0627\u0644\u0644\u0647 \u0642\u0644\u0629 \u0639\u062f\u062f \u0639\u062f\u0648\u0643 \u0641\u064a \u0645\u0646\u0627\u0645\u0643\u060c \u0641\u0623\u062e\u0628\u0631\u062a \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u0630\u0644\u0643\u060c \u0641\u0642\u0648\u0650\u064a\u062a \u0642\u0644\u0648\u0628\u0647\u0645\u060c \u0648\u0627\u062c\u062a\u0631\u0624\u0648\u0627 \u0639\u0644\u0649 \u062d\u0631\u0628\u0647\u0645\u060c \u0648\u0644\u0648 \u0623\u0631\u0627\u0643 \u0631\u0628\u0643 \u0643\u062b\u0631\u0629 \u0639\u062f\u062f\u0647\u0645 \u0644\u062a\u0631\u062f\u062f \u0623\u0635\u062d\u0627\u0628\u0643 \u0641\u064a \u0645\u0644\u0627\u0642\u0627\u062a\u0647\u0645\u060c \u0648\u062c\u064e\u0628\u064f\u0646\u062a\u0645 \u0648\u0627\u062e\u062a\u0644\u0641\u062a\u0645 \u0641\u064a \u0623\u0645\u0631 \u0627\u0644\u0642\u062a\u0627\u0644\u060c \u0648\u0644\u0643\u0646 \u0627\u0644\u0644\u0647 \u0633\u0644\u0651\u064e\u0645 \u0645\u0646 \u0627\u0644\u0641\u0634\u0644\u060c \u0648\u0646\u062c\u0651\u064e\u0649 \u0645\u0646 \u0639\u0627\u0642\u0628\u0629 \u0630\u0644\u0643. \u0625\u0646\u0647 \u0639\u0644\u064a\u0645 \u0628\u062e\u0641\u0627\u064a\u0627 \u0627\u0644\u0642\u0644\u0648\u0628 \u0648\u0637\u0628\u0627\u0626\u0639 \u0627\u0644\u0646\u0641\u0648\u0633.","8:44":"\u0648\u0627\u0630\u0643\u0631 \u0623\u064a\u0636\u064b\u0627 \u062d\u064a\u0646\u0645\u0627 \u0628\u0631\u0632 \u0627\u0644\u0623\u0639\u062f\u0627\u0621 \u0625\u0644\u0649 \u0623\u0631\u0636 \u0627\u0644\u0645\u0639\u0631\u0643\u0629 \u0641\u0631\u0623\u064a\u062a\u0645\u0648\u0647\u0645 \u0642\u0644\u064a\u0644\u0627 \u0641\u0627\u062c\u062a\u0631\u0623\u062a\u0645 \u0639\u0644\u064a\u0647\u0645\u060c \u0648\u0642\u0644\u0651\u064e\u0644\u0643\u0645 \u0641\u064a \u0623\u0639\u064a\u0646\u0647\u0645\u060c \u0644\u064a\u062a\u0631\u0643\u0648\u0627 \u0627\u0644\u0627\u0633\u062a\u0639\u062f\u0627\u062f \u0644\u062d\u0631\u0628\u0643\u0645; \u0644\u064a\u0642\u0636\u064a \u0627\u0644\u0644\u0647 \u0623\u0645\u0631\u064b\u0627 \u0643\u0627\u0646 \u0645\u0641\u0639\u0648\u0644\u0627 \u0641\u064a\u062a\u062d\u0642\u0642 \u0648\u064e\u0639\u0652\u062f\u064f \u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0628\u0627\u0644\u0646\u0635\u0631 \u0648\u0627\u0644\u063a\u0644\u0628\u0629\u060c \u0641\u0643\u0627\u0646\u062a \u0643\u0644\u0645\u0629 \u0627\u0644\u0644\u0647 \u0647\u064a \u0627\u0644\u0639\u0644\u064a\u0627 \u0648\u0643\u0644\u0645\u0629 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0627\u0644\u0633\u0641\u0644\u0649. \u0648\u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0645\u0635\u064a\u0631 \u0627\u0644\u0623\u0645\u0648\u0631 \u0643\u0644\u0647\u0627\u060c \u0641\u064a\u062c\u0627\u0632\u064a \u0643\u0644\u0627 \u0628\u0645\u0627 \u064a\u0633\u062a\u062d\u0642.","8:45":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0625\u0630\u0627 \u0644\u0642\u064a\u062a\u0645 \u062c\u0645\u0627\u0639\u0629 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u0641\u0631 \u0642\u062f \u0627\u0633\u062a\u0639\u062f\u0648\u0627 \u0644\u0642\u062a\u0627\u0644\u0643\u0645\u060c \u0641\u0627\u062b\u0628\u062a\u0648\u0627 \u0648\u0644\u0627 \u062a\u0646\u0647\u0632\u0645\u0648\u0627 \u0639\u0646\u0647\u0645\u060c \u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u0627\u0644\u0644\u0647 \u0643\u062b\u064a\u0631\u064b\u0627 \u062f\u0627\u0639\u064a\u0646 \u0645\u0628\u062a\u0647\u0644\u064a\u0646 \u0644\u0625\u0646\u0632\u0627\u0644 \u0627\u0644\u0646\u0635\u0631 \u0639\u0644\u064a\u0643\u0645 \u0648\u0627\u0644\u0638\u0651\u064e\u0641\u064e\u0631 \u0628\u0639\u062f\u0648\u0643\u0645; \u0644\u0643\u064a \u062a\u0641\u0648\u0632\u0648\u0627.","8:46":"\u0648\u0627\u0644\u062a\u0632\u0645\u0648\u0627 \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u0648\u0637\u0627\u0639\u0629 \u0631\u0633\u0648\u0644\u0647 \u0641\u064a \u0643\u0644 \u0623\u062d\u0648\u0627\u0644\u0643\u0645\u060c \u0648\u0644\u0627 \u062a\u062e\u062a\u0644\u0641\u0648\u0627 \u0641\u062a\u062a\u0641\u0631\u0642 \u0643\u0644\u0645\u062a\u0643\u0645 \u0648\u062a\u062e\u062a\u0644\u0641 \u0642\u0644\u0648\u0628\u0643\u0645\u060c \u0641\u062a\u0636\u0639\u0641\u0648\u0627 \u0648\u062a\u0630\u0647\u0628 \u0642\u0648\u062a\u0643\u0645 \u0648\u0646\u0635\u0631\u0643\u0645\u060c \u0648\u0627\u0635\u0628\u0631\u0648\u0627 \u0639\u0646\u062f \u0644\u0642\u0627\u0621 \u0627\u0644\u0639\u062f\u0648. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0645\u0639 \u0627\u0644\u0635\u0627\u0628\u0631\u064a\u0646 \u0628\u0627\u0644\u0639\u0648\u0646 \u0648\u0627\u0644\u0646\u0635\u0631 \u0648\u0627\u0644\u062a\u0623\u064a\u064a\u062f\u060c \u0648\u0644\u0646 \u064a\u062e\u0630\u0644\u0647\u0645.","8:47":"\u0648\u0644\u0627 \u062a\u0643\u0648\u0646\u0648\u0627 \u0645\u062b\u0644 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u062e\u0631\u062c\u0648\u0627 \u0645\u0646 \u0628\u0644\u062f\u0647\u0645 \u0643\u0628\u0631\u064b\u0627 \u0648\u0631\u064a\u0627\u0621\u064b; \u0644\u064a\u0645\u0646\u0639\u0648\u0627 \u0627\u0644\u0646\u0627\u0633 \u0639\u0646 \u0627\u0644\u062f\u062e\u0648\u0644 \u0641\u064a \u062f\u064a\u0646 \u0627\u0644\u0644\u0647. \u0648\u0627\u0644\u0644\u0647 \u0628\u0645\u0627 \u064a\u0639\u0645\u0644\u0648\u0646 \u0645\u062d\u064a\u0637 \u0644\u0627 \u064a\u063a\u064a\u0628 \u0639\u0646\u0647 \u0634\u064a\u0621.","8:48":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u062d\u064a\u0646 \u062d\u0633\u0651\u064e\u0646 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0644\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0645\u0627 \u062c\u0627\u0624\u0648\u0627 \u0644\u0647 \u0648\u0645\u0627 \u0647\u0645\u0651\u064f\u0648\u0627 \u0628\u0647\u060c \u0648\u0642\u0627\u0644 \u0644\u0647\u0645: \u0644\u0646 \u064a\u063a\u0644\u0628\u0643\u0645 \u0623\u062d\u062f \u0627\u0644\u064a\u0648\u0645\u060c \u0641\u0625\u0646\u064a \u0646\u0627\u0635\u0631\u0643\u0645\u060c \u0641\u0644\u0645\u0627 \u062a\u0642\u0627\u0628\u0644 \u0627\u0644\u0641\u0631\u064a\u0642\u0627\u0646: \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0648\u0645\u0639\u0647\u0645 \u0627\u0644\u0634\u064a\u0637\u0627\u0646\u060c \u0648\u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0648\u0645\u0639\u0647\u0645 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629\u060c \u0631\u062c\u0639 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0645\u064f\u062f\u0652\u0628\u0631\u064b\u0627\u060c \u0648\u0642\u0627\u0644 \u0644\u0644\u0645\u0634\u0631\u0643\u064a\u0646: \u0625\u0646\u064a \u0628\u0631\u064a\u0621 \u0645\u0646\u0643\u0645\u060c \u0625\u0646\u064a \u0623\u0631\u0649 \u0645\u0627 \u0644\u0627 \u062a\u0631\u0648\u0646 \u0645\u0646 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0627\u0644\u0630\u064a\u0646 \u062c\u0627\u0624\u0648\u0627 \u0645\u062f\u062f\u064b\u0627 \u0644\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0625\u0646\u064a \u0623\u062e\u0627\u0641 \u0627\u0644\u0644\u0647\u060c \u0641\u062e\u0630\u0644\u0647\u0645 \u0648\u062a\u0628\u0631\u0623 \u0645\u0646\u0647\u0645. \u0648\u0627\u0644\u0644\u0647 \u0634\u062f\u064a\u062f \u0627\u0644\u0639\u0642\u0627\u0628 \u0644\u0645\u0646 \u0639\u0635\u0627\u0647 \u0648\u0644\u0645 \u064a\u062a\u0628 \u062a\u0648\u0628\u0629 \u0646\u0635\u0648\u062d\u064b\u0627.","8:49":"\u0648\u0627\u0630\u0643\u0631\u0648\u0627 \u062d\u064a\u0646 \u064a\u0642\u0648\u0644 \u0623\u0647\u0644 \u0627\u0644\u0634\u0631\u0643 \u0648\u0627\u0644\u0646\u0641\u0627\u0642 \u0648\u0645\u0631\u0636\u0649 \u0627\u0644\u0642\u0644\u0648\u0628\u060c \u0648\u0647\u0645 \u064a\u0631\u0648\u0646 \u0642\u0644\u0629 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u0643\u062b\u0631\u0629 \u0639\u062f\u0648\u0647\u0645: \u063a\u0631\u0651\u064e \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u062f\u064a\u0646\u064f\u0647\u0645\u060c \u0641\u0623\u0648\u0631\u062f\u0647\u0645 \u0647\u0630\u0647 \u0627\u0644\u0645\u0648\u0627\u0631\u062f\u060c \u0648\u0644\u0645 \u064a\u062f\u0631\u0643 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0623\u0646\u0647 \u0645\u0646 \u064a\u062a\u0648\u0643\u0644 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u064a\u062b\u0642 \u0628\u0648\u0639\u062f\u0647 \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0644\u0646 \u064a\u062e\u0630\u0644\u0647\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0639\u0632\u064a\u0632 \u0644\u0627 \u064a\u0639\u062c\u0632\u0647 \u0634\u064a\u0621\u060c \u062d\u0643\u064a\u0645 \u0641\u064a \u062a\u062f\u0628\u064a\u0631\u0647 \u0648\u0635\u0646\u0639\u0647.","8:50":"\u0648\u0644\u0648 \u062a\u0639\u0627\u064a\u0646 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u062d\u0627\u0644 \u0642\u0628\u0636 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0623\u0631\u0648\u0627\u062d \u0627\u0644\u0643\u0641\u0627\u0631 \u0648\u0627\u0646\u062a\u0632\u0627\u0639\u0647\u0627\u060c \u0648\u0647\u0645 \u064a\u0636\u0631\u0628\u0648\u0646 \u0648\u062c\u0648\u0647\u0647\u0645 \u0641\u064a \u062d\u0627\u0644 \u0625\u0642\u0628\u0627\u0644\u0647\u0645\u060c \u0648\u064a\u0636\u0631\u0628\u0648\u0646 \u0638\u0647\u0648\u0631\u0647\u0645 \u0641\u064a \u062d\u0627\u0644 \u0641\u0631\u0627\u0631\u0647\u0645\u060c \u0648\u064a\u0642\u0648\u0644\u0648\u0646 \u0644\u0647\u0645: \u0630\u0648\u0642\u0648\u0627 \u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0645\u062d\u0631\u0642\u060c \u0644\u0631\u0623\u064a\u062a \u0623\u0645\u0631\u064b\u0627 \u0639\u0638\u064a\u0645\u064b\u0627\u060c \u0648\u0647\u0630\u0627 \u0627\u0644\u0633\u064a\u0627\u0642 \u0648\u0625\u0646 \u0643\u0627\u0646 \u0633\u0628\u0628\u0647 \u0648\u0642\u0639\u0629 \xab\u0628\u062f\u0631\xbb \u060c \u0648\u0644\u0643\u0646\u0647 \u0639\u0627\u0645 \u0641\u064a \u062d\u0642 \u0643\u0644\u0651\u0650 \u0643\u0627\u0641\u0631.","8:51":"\u0630\u0644\u0643 \u0627\u0644\u062c\u0632\u0627\u0621 \u0627\u0644\u0630\u064a \u0623\u0635\u0627\u0628 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0641\u0628\u0633\u0628\u0628 \u0623\u0639\u0645\u0627\u0644\u0643\u0645 \u0627\u0644\u0633\u064a\u0626\u0629 \u0641\u064a \u062d\u064a\u0627\u062a\u0643\u0645 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0644\u0627 \u064a\u0638\u0644\u0645 \u0627\u0644\u0644\u0647 \u0623\u062d\u062f\u064b\u0627 \u0645\u0646 \u062e\u064e\u0644\u0652\u0642\u0647 \u0645\u062b\u0642\u0627\u0644 \u0630\u0631\u0629\u060c \u0628\u0644 \u0647\u0648 \u0627\u0644\u062d\u064e\u0643\u064e\u0645\u064f \u0627\u0644\u0639\u062f\u0644 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u062c\u0648\u0631.","8:52":"\u0625\u0646\u0651\u064e \u0645\u0627 \u0646\u0632\u0644 \u0628\u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u064a\u0648\u0645\u0626\u0630 \u0633\u064f\u0646\u0651\u064e\u0629 \u0627\u0644\u0644\u0647 \u0641\u064a \u0639\u0642\u0627\u0628 \u0627\u0644\u0637\u063a\u0627\u0629 \u0645\u0646 \u0627\u0644\u0623\u0645\u0645 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0645\u0646 \u0623\u0645\u062b\u0627\u0644 \u0641\u0631\u0639\u0648\u0646 \u0648\u0627\u0644\u0633\u0627\u0628\u0642\u064a\u0646 \u0644\u0647\u060c \u0639\u0646\u062f\u0645\u0627 \u0643\u0630\u0651\u064e\u0628\u0648\u0627 \u0631\u0633\u0644 \u0627\u0644\u0644\u0647 \u0648\u062c\u062d\u062f\u0648\u0627 \u0622\u064a\u0627\u062a\u0647\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0623\u0646\u0632\u0644 \u0628\u0647\u0645 \u0639\u0642\u0627\u0628\u0647 \u0628\u0633\u0628\u0628 \u0630\u0646\u0648\u0628\u0647\u0645. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0642\u0648\u064a \u0644\u0627 \u064a\u064f\u0642\u0652\u0647\u0631\u060c \u0634\u062f\u064a\u062f \u0627\u0644\u0639\u0642\u0627\u0628 \u0644\u0645\u0646 \u0639\u0635\u0627\u0647 \u0648\u0644\u0645 \u064a\u062a\u0628 \u0645\u0646 \u0630\u0646\u0628\u0647.","8:53":"\u0630\u0644\u0643 \u0627\u0644\u062c\u0632\u0627\u0621 \u0627\u0644\u0633\u064a\u0651\u0650\u0626 \u0628\u0623\u0646 \u0627\u0644\u0644\u0647 \u0625\u0630\u0627 \u0623\u0646\u0639\u0645 \u0639\u0644\u0649 \u0642\u0648\u0645 \u0646\u0639\u0645\u0629 \u0644\u0645 \u064a\u0633\u0644\u0628\u0647\u0627 \u0645\u0646\u0647\u0645 \u062d\u062a\u0649 \u064a\u063a\u064a\u0651\u0650\u0631\u0648\u0627 \u062d\u0627\u0644\u0647\u0645 \u0627\u0644\u0637\u064a\u0628\u0629 \u0625\u0644\u0649 \u062d\u0627\u0644 \u0633\u064a\u0626\u0629\u060c \u0648\u0623\u0646 \u0627\u0644\u0644\u0647 \u0633\u0645\u064a\u0639 \u0644\u0623\u0642\u0648\u0627\u0644 \u062e\u0644\u0642\u0647\u060c \u0639\u0644\u064a\u0645 \u0628\u0623\u062d\u0648\u0627\u0644\u0647\u0645\u060c \u0641\u064a\u062c\u0631\u064a \u0639\u0644\u064a\u0647\u0645 \u0645\u0627 \u0627\u0642\u062a\u0636\u0627\u0647 \u0639\u0644\u0645\u0647 \u0648\u0645\u0634\u064a\u0626\u062a\u0647.","8:54":"\u0634\u0623\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0641\u064a \u0630\u0644\u0643 \u0643\u0634\u0623\u0646 \u0622\u0644 \u0641\u0631\u0639\u0648\u0646 \u0627\u0644\u0630\u064a\u0646 \u0643\u0630\u0628\u0648\u0627 \u0645\u0648\u0633\u0649\u060c \u0648\u0634\u0623\u0646 \u0627\u0644\u0630\u064a\u0646 \u0643\u0630\u0628\u0648\u0627 \u0631\u0633\u0644\u0647\u0645 \u0645\u0646 \u0627\u0644\u0623\u0645\u0645 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0641\u0623\u0647\u0644\u0643\u0647\u0645 \u0627\u0644\u0644\u0647 \u0628\u0633\u0628\u0628 \u0630\u0646\u0648\u0628\u0647\u0645\u060c \u0648\u0623\u063a\u0631\u0642 \u0622\u0644 \u0641\u0631\u0639\u0648\u0646 \u0641\u064a \u0627\u0644\u0628\u062d\u0631\u060c \u0648\u0643\u0644 \u0645\u0646\u0647\u0645 \u0643\u0627\u0646 \u0641\u0627\u0639\u0644\u0627 \u0645\u0627 \u0644\u0645 \u064a\u0643\u0646 \u0644\u0647 \u0641\u0650\u0639\u0652\u0644\u064f\u0647 \u0645\u0646 \u062a\u0643\u0630\u064a\u0628\u0647\u0645 \u0631\u0633\u0644 \u0627\u0644\u0644\u0647 \u0648\u062c\u062d\u0648\u062f\u0647\u0645 \u0622\u064a\u0627\u062a\u0647\u060c \u0648\u0625\u0634\u0631\u0627\u0643\u0647\u0645 \u0641\u064a \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u063a\u064a\u0631\u0647.","8:55":"\u0625\u0646 \u0634\u0631 \u0645\u0627 \u062f\u0628\u0651\u064e \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0627\u0644\u0643\u0641\u0627\u0631 \u0627\u0644\u0645\u0635\u0631\u0651\u064f\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0643\u0641\u0631\u060c \u0641\u0647\u0645 \u0644\u0627 \u064a\u0635\u062f\u0642\u0648\u0646 \u0631\u0633\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u064a\u064f\u0642\u0631\u0648\u0646 \u0628\u0648\u062d\u062f\u0627\u0646\u064a\u062a\u0647\u060c \u0648\u0644\u0627 \u064a\u062a\u0628\u0639\u0648\u0646 \u0634\u0631\u0639\u0647.","8:56":"\u0645\u0650\u0646 \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0623\u0634\u0631\u0627\u0631 \u0627\u0644\u064a\u0647\u0648\u062f \u0627\u0644\u0630\u064a\u0646 \u062f\u062e\u0644\u0648\u0627 \u0645\u0639\u0643 \u0641\u064a \u0627\u0644\u0645\u0639\u0627\u0647\u062f\u0627\u062a \u0628\u0623\u0646 \u0644\u0627 \u064a\u062d\u0627\u0631\u0628\u0648\u0643 \u0648\u0644\u0627 \u064a\u0638\u0627\u0647\u0631\u0648\u0627 \u0639\u0644\u064a\u0643 \u0623\u062d\u062f\u064b\u0627\u060c \u062b\u0645 \u064a\u0646\u0642\u0636\u0648\u0646 \u0639\u0647\u062f\u0647\u0645 \u0627\u0644\u0645\u0631\u0629 \u062a\u0644\u0648 \u0627\u0644\u0645\u0631\u0629\u060c \u0648\u0647\u0645 \u0644\u0627 \u064a\u062e\u0627\u0641\u0648\u0646 \u0627\u0644\u0644\u0647.","8:57":"\u0641\u0625\u0646 \u0648\u0627\u062c\u0647\u062a \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0646\u0627\u0642\u0636\u064a\u0646 \u0644\u0644\u0639\u0647\u0648\u062f \u0648\u0627\u0644\u0645\u0648\u0627\u062b\u064a\u0642 \u0641\u064a \u0627\u0644\u0645\u0639\u0631\u0643\u0629\u060c \u0641\u0623\u0646\u0632\u0650\u0644\u0652 \u0628\u0647\u0645 \u0645\u0646 \u0627\u0644\u0639\u0630\u0627\u0628 \u0645\u0627 \u064a\u064f\u062f\u0652\u062e\u0644 \u0627\u0644\u0631\u0639\u0628 \u0641\u064a \u0642\u0644\u0648\u0628 \u0627\u0644\u0622\u062e\u0631\u064a\u0646\u060c \u0648\u064a\u0634\u062a\u062a \u062c\u0645\u0648\u0639\u0647\u0645; \u0644\u0639\u0644\u0647\u0645 \u064a\u0630\u0651\u0643\u0631\u0648\u0646\u060c \u0641\u0644\u0627 \u064a\u062c\u062a\u0631\u0626\u0648\u0646 \u0639\u0644\u0649 \u0645\u062b\u0644 \u0627\u0644\u0630\u064a \u0623\u0642\u062f\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0627\u0628\u0642\u0648\u0646.","8:58":"\u0648\u0625\u0646 \u062e\u0641\u062a -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u0646 \u0642\u0648\u0645\u064d \u062e\u064a\u0627\u0646\u0629 \u0638\u0647\u0631\u062a \u0628\u0648\u0627\u062f\u0631\u0647\u0627 \u0641\u0623\u0644\u0642 \u0625\u0644\u064a\u0647\u0645 \u0639\u0647\u062f\u0647\u0645\u060c \u0643\u064a \u064a\u0643\u0648\u0646 \u0627\u0644\u0637\u0631\u0641\u0627\u0646 \u0645\u0633\u062a\u0648\u064a\u064a\u0646 \u0641\u064a \u0627\u0644\u0639\u0644\u0645 \u0628\u0623\u0646\u0647 \u0644\u0627 \u0639\u0647\u062f \u0628\u0639\u062f \u0627\u0644\u064a\u0648\u0645. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u062d\u0628 \u0627\u0644\u062e\u0627\u0626\u0646\u064a\u0646 \u0641\u064a \u0639\u0647\u0648\u062f\u0647\u0645 \u0627\u0644\u0646\u0627\u0642\u0636\u064a\u0646 \u0644\u0644\u0639\u0647\u062f \u0648\u0627\u0644\u0645\u064a\u062b\u0627\u0642.","8:59":"\u0648\u0644\u0627 \u064a\u0638\u0646\u0646 \u0627\u0644\u0630\u064a\u0646 \u062c\u062d\u062f\u0648\u0627 \u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0623\u0646\u0647\u0645 \u0641\u0627\u062a\u0648\u0627 \u0648\u0646\u062c\u064e\u0648\u0652\u0627\u060c \u0648\u0623\u0646 \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0642\u062f\u0631 \u0639\u0644\u064a\u0647\u0645\u060c \u0625\u0646\u0647\u0645 \u0644\u0646 \u064a\u064f\u0641\u0652\u0644\u0650\u062a\u0648\u0627 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647.","8:60":"\u0648\u0623\u0639\u062f\u0651\u064f\u0648\u0627 - \u064a\u0627 \u0645\u0639\u0634\u0631 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 - \u0644\u0645\u0648\u0627\u062c\u0647\u0629 \u0623\u0639\u062f\u0627\u0626\u0643\u0645 \u0643\u0644 \u0645\u0627 \u062a\u0642\u062f\u0631\u0648\u0646 \u0639\u0644\u064a\u0647 \u0645\u0650\u0646 \u0639\u062f\u062f \u0648\u0639\u062f\u0629\u060c \u0644\u062a\u064f\u062f\u0652\u062e\u0644\u0648\u0627 \u0628\u0630\u0644\u0643 \u0627\u0644\u0631\u0647\u0628\u0629 \u0641\u064a \u0642\u0644\u0648\u0628 \u0623\u0639\u062f\u0627\u0621 \u0627\u0644\u0644\u0647 \u0648\u0623\u0639\u062f\u0627\u0626\u0643\u0645 \u0627\u0644\u0645\u062a\u0631\u0628\u0635\u064a\u0646 \u0628\u0643\u0645\u060c \u0648\u062a\u062e\u064a\u0641\u0648\u0627 \u0622\u062e\u0631\u064a\u0646 \u0644\u0627 \u062a\u0638\u0647\u0631 \u0644\u0643\u0645 \u0639\u062f\u0627\u0648\u062a\u0647\u0645 \u0627\u0644\u0622\u0646\u060c \u0644\u0643\u0646 \u0627\u0644\u0644\u0647 \u064a\u0639\u0644\u0645\u0647\u0645 \u0648\u064a\u0639\u0644\u0645 \u0645\u0627 \u064a\u0636\u0645\u0631\u0648\u0646\u0647. \u0648\u0645\u0627 \u062a\u0628\u0630\u0644\u0648\u0627 \u0645\u0646 \u0645\u0627\u0644 \u0648\u063a\u064a\u0631\u0647 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0642\u0644\u064a\u0644\u0627 \u0623\u0648 \u0643\u062b\u064a\u0631\u064b\u0627 \u064a\u062e\u0644\u0641\u0647 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0643\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u064a\u062f\u062e\u0631 \u0644\u0643\u0645 \u062b\u0648\u0627\u0628\u0647 \u0625\u0644\u0649 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0648\u0623\u0646\u062a\u0645 \u0644\u0627 \u062a\u064f\u0646\u0652\u0642\u0635\u0648\u0646 \u0645\u0646 \u0623\u062c\u0631 \u0630\u0644\u0643 \u0634\u064a\u0626\u064b\u0627.","8:61":"\u0648\u0625\u0646 \u0645\u0627\u0644\u0648\u0627 \u0625\u0644\u0649 \u062a\u0631\u0643 \u0627\u0644\u062d\u0631\u0628 \u0648\u0631\u063a\u0628\u0648\u0627 \u0641\u064a \u0645\u0633\u0627\u0644\u0645\u062a\u0643\u0645 \u0641\u0645\u0650\u0644\u0652 \u0625\u0644\u0649 \u0630\u0644\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0648\u0641\u064e\u0648\u0651\u0650\u0636\u0652 \u0623\u0645\u0631\u0643 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u062b\u0642 \u0628\u0647. \u0625\u0646\u0647 \u0647\u0648 \u0627\u0644\u0633\u0645\u064a\u0639 \u0644\u0623\u0642\u0648\u0627\u0644\u0647\u0645\u060c \u0627\u0644\u0639\u0644\u064a\u0645 \u0628\u0646\u064a\u0651\u064e\u0627\u062a\u0647\u0645.","8:62":"\u0648\u0625\u0646 \u0623\u0631\u0627\u062f \u0627\u0644\u0630\u064a\u0646 \u0639\u0627\u0647\u062f\u0648\u0643 \u0627\u0644\u0645\u0643\u0631 \u0628\u0643 \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0633\u064a\u0643\u0641\u064a\u0643 \u062e\u062f\u0627\u0639\u0647\u0645; \u0625\u0646\u0647 \u0647\u0648 \u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644 \u0639\u0644\u064a\u0643 \u0646\u0635\u0631\u0647 \u0648\u0642\u0648\u0651\u064e\u0627\u0643 \u0628\u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0645\u0646 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0648\u0627\u0644\u0623\u0646\u0635\u0627\u0631\u060c \u0648\u062c\u064e\u0645\u064e\u0639 \u0628\u064a\u0646 \u0642\u0644\u0648\u0628\u0647\u0645 \u0628\u0639\u062f \u0627\u0644\u062a\u0641\u0631\u0642\u060c \u0644\u0648 \u0623\u0646\u0641\u0642\u062a \u0645\u0627\u0644 \u0627\u0644\u062f\u0646\u064a\u0627 \u0639\u0644\u0649 \u062c\u0645\u0639 \u0642\u0644\u0648\u0628\u0647\u0645 \u0645\u0627 \u0627\u0633\u062a\u0637\u0639\u062a \u0625\u0644\u0649 \u0630\u0644\u0643 \u0633\u0628\u064a\u0644\u0627 \u0648\u0644\u0643\u0646 \u0627\u0644\u0644\u0647 \u062c\u0645\u0639 \u0628\u064a\u0646\u0647\u0627 \u0639\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0641\u0623\u0635\u0628\u062d\u0648\u0627 \u0625\u062e\u0648\u0627\u0646\u064b\u0627 \u0645\u062a\u062d\u0627\u0628\u064a\u0646\u060c \u0625\u0646\u0647 \u0639\u0632\u064a\u0632 \u0641\u064a \u0645\u064f\u0644\u0652\u0643\u0647\u060c \u062d\u0643\u064a\u0645 \u0641\u064a \u0623\u0645\u0631\u0647 \u0648\u062a\u062f\u0628\u064a\u0631\u0647.","8:63":"\u0648\u0625\u0646 \u0623\u0631\u0627\u062f \u0627\u0644\u0630\u064a\u0646 \u0639\u0627\u0647\u062f\u0648\u0643 \u0627\u0644\u0645\u0643\u0631 \u0628\u0643 \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0633\u064a\u0643\u0641\u064a\u0643 \u062e\u062f\u0627\u0639\u0647\u0645\u061b \u0625\u0646\u0647 \u0647\u0648 \u0627\u0644\u0630\u064a \u0623\u0646\u0632\u0644 \u0639\u0644\u064a\u0643 \u0646\u0635\u0631\u0647 \u0648\u0642\u0648\u0651\u064e\u0627\u0643 \u0628\u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0645\u0646 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0648\u0627\u0644\u0623\u0646\u0635\u0627\u0631\u060c \u0648\u062c\u064e\u0645\u064e\u0639 \u0628\u064a\u0646 \u0642\u0644\u0648\u0628\u0647\u0645 \u0628\u0639\u062f \u0627\u0644\u062a\u0641\u0631\u0642\u060c \u0644\u0648 \u0623\u0646\u0641\u0642\u062a \u0645\u0627\u0644 \u0627\u0644\u062f\u0646\u064a\u0627 \u0639\u0644\u0649 \u062c\u0645\u0639 \u0642\u0644\u0648\u0628\u0647\u0645 \u0645\u0627 \u0627\u0633\u062a\u0637\u0639\u062a \u0625\u0644\u0649 \u0630\u0644\u0643 \u0633\u0628\u064a\u0644\u0627 \u0648\u0644\u0643\u0646 \u0627\u0644\u0644\u0647 \u062c\u0645\u0639 \u0628\u064a\u0646\u0647\u0627 \u0639\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0641\u0623\u0635\u0628\u062d\u0648\u0627 \u0625\u062e\u0648\u0627\u0646\u064b\u0627 \u0645\u062a\u062d\u0627\u0628\u064a\u0646\u060c \u0625\u0646\u0647 \u0639\u0632\u064a\u0632 \u0641\u064a \u0645\u064f\u0644\u0652\u0643\u0647\u060c \u062d\u0643\u064a\u0645 \u0641\u064a \u0623\u0645\u0631\u0647 \u0648\u062a\u062f\u0628\u064a\u0631\u0647.","8:64":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a \u0625\u0646 \u0627\u0644\u0644\u0647 \u0643\u0627\u0641\u064a\u0643\u060c \u0648\u0643\u0627\u0641\u064a \u0627\u0644\u0630\u064a\u0646 \u0645\u0639\u0643 \u0645\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0634\u0631\u0651\u064e \u0623\u0639\u062f\u0627\u0626\u0643\u0645.","8:65":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a \u062d\u064f\u062b\u0651\u064e \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u0643 \u0639\u0644\u0649 \u0627\u0644\u0642\u062a\u0627\u0644\u060c \u0625\u0646 \u064a\u0643\u0646 \u0645\u0646\u0643\u0645 \u0639\u0634\u0631\u0648\u0646 \u0635\u0627\u0628\u0631\u0648\u0646 \u0639\u0646\u062f \u0644\u0642\u0627\u0621 \u0627\u0644\u0639\u062f\u0648 \u064a\u063a\u0644\u0628\u0648\u0627 \u0645\u0627\u0626\u062a\u064a\u0646 \u0645\u0646\u0647\u0645\u060c \u0648\u0625\u0646 \u064a\u0643\u0646 \u0645\u0646\u0643\u0645 \u0645\u0627\u0626\u0629 \u0645\u062c\u0627\u0647\u062f\u0629 \u0635\u0627\u0628\u0631\u0629 \u064a\u063a\u0644\u0628\u0648\u0627 \u0623\u0644\u0641\u064b\u0627 \u0645\u0646 \u0627\u0644\u0643\u0641\u0627\u0631; \u0644\u0623\u0646\u0647\u0645 \u0642\u0648\u0645 \u0644\u0627 \u0639\u0650\u0644\u0652\u0645 \u0648\u0644\u0627 \u0641\u0647\u0645 \u0639\u0646\u062f\u0647\u0645 \u0644\u0645\u0627 \u0623\u0639\u062f\u0651\u064e \u0627\u0644\u0644\u0647 \u0644\u0644\u0645\u062c\u0627\u0647\u062f\u064a\u0646 \u0641\u064a \u0633\u0628\u064a\u0644\u0647\u060c \u0641\u0647\u0645 \u064a\u0642\u0627\u062a\u0644\u0648\u0646 \u0645\u0646 \u0623\u062c\u0644 \u0627\u0644\u0639\u0644\u0648 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0648\u0627\u0644\u0641\u0633\u0627\u062f \u0641\u064a\u0647\u0627.","8:66":"\u0627\u0644\u0622\u0646 \u062e\u0641\u0641 \u0627\u0644\u0644\u0647 \u0639\u0646\u0643\u0645 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0644\u0645\u0627 \u0641\u064a\u0643\u0645 \u0645\u0646 \u0627\u0644\u0636\u0639\u0641\u060c \u0641\u0625\u0646 \u064a\u0643\u0646 \u0645\u0646\u0643\u0645 \u0645\u0627\u0626\u0629 \u0635\u0627\u0628\u0631\u0629 \u064a\u063a\u0644\u0628\u0648\u0627 \u0645\u0627\u0626\u062a\u064a\u0646 \u0645\u0646 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646\u060c \u0648\u0625\u0646 \u064a\u0643\u0646 \u0645\u0646\u0643\u0645 \u0623\u0644\u0641 \u064a\u063a\u0644\u0628\u0648\u0627 \u0623\u0644\u0641\u064a\u0646 \u0645\u0646\u0647\u0645 \u0628\u0625\u0630\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649. \u0648\u0627\u0644\u0644\u0647 \u0645\u0639 \u0627\u0644\u0635\u0627\u0628\u0631\u064a\u0646 \u0628\u062a\u0623\u064a\u064a\u062f\u0647 \u0648\u0646\u0635\u0631\u0647.","8:67":"\u0644\u0627 \u064a\u0646\u0628\u063a\u064a \u0644\u0646\u0628\u064a \u0623\u0646 \u064a\u0643\u0648\u0646 \u0644\u0647 \u0623\u0633\u0631\u0649 \u0645\u0650\u0646 \u0623\u0639\u062f\u0627\u0626\u0647 \u062d\u062a\u0649 \u064a\u0628\u0627\u0644\u063a \u0641\u064a \u0627\u0644\u0642\u062a\u0644; \u0644\u0625\u062f\u062e\u0627\u0644 \u0627\u0644\u0631\u0639\u0628 \u0641\u064a \u0642\u0644\u0648\u0628\u0647\u0645 \u0648\u064a\u0648\u0637\u062f \u062f\u0639\u0627\u0626\u0645 \u0627\u0644\u062f\u064a\u0646\u060c \u062a\u0631\u064a\u062f\u0648\u0646 -\u064a\u0627 \u0645\u0639\u0634\u0631 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646- \u0628\u0623\u062e\u0630\u0643\u0645 \u0627\u0644\u0641\u062f\u0627\u0621 \u0645\u0646 \u0623\u0633\u0631\u0649 \xab\u0628\u062f\u0631\xbb \u0645\u062a\u0627\u0639 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0627\u0644\u0644\u0647 \u064a\u0631\u064a\u062f \u0625\u0638\u0647\u0627\u0631 \u062f\u064a\u0646\u0647 \u0627\u0644\u0630\u064a \u0628\u0647 \u062a\u062f\u0631\u0643 \u0627\u0644\u0622\u062e\u0631\u0629. \u0648\u0627\u0644\u0644\u0647 \u0639\u0632\u064a\u0632 \u0644\u0627 \u064a\u064f\u0642\u0652\u0647\u0631\u060c \u062d\u0643\u064a\u0645 \u0641\u064a \u0634\u0631\u0639\u0647.","8:68":"\u0644\u0648\u0644\u0627 \u0643\u062a\u0627\u0628 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0633\u0628\u0642 \u0628\u0647 \u0627\u0644\u0642\u0636\u0627\u0621 \u0648\u0627\u0644\u0642\u062f\u0631 \u0628\u0625\u0628\u0627\u062d\u0629 \u0627\u0644\u063a\u0646\u064a\u0645\u0629 \u0648\u0641\u062f\u0627\u0621 \u0627\u0644\u0623\u0633\u0631\u0649 \u0644\u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0629\u060c \u0644\u0646\u0627\u0644\u0643\u0645 \u0639\u0630\u0627\u0628 \u0639\u0638\u064a\u0645 \u0628\u0633\u0628\u0628 \u0623\u062e\u0652\u0630\u0643\u0645 \u0627\u0644\u063a\u0646\u064a\u0645\u0629 \u0648\u0627\u0644\u0641\u062f\u0627\u0621 \u0642\u0628\u0644 \u0623\u0646 \u064a\u0646\u0632\u0644 \u0628\u0634\u0623\u0646\u0647\u0645\u0627 \u062a\u0634\u0631\u064a\u0639.","8:69":"\u0641\u0643\u0644\u0648\u0627 \u0645\u0646 \u0627\u0644\u063a\u0646\u0627\u0626\u0645 \u0648\u0641\u062f\u0627\u0621 \u0627\u0644\u0623\u0633\u0631\u0649 \u0641\u0647\u0648 \u062d\u0644\u0627\u0644 \u0637\u064a\u0628\u060c \u0648\u062d\u0627\u0641\u0638\u0648\u0627 \u0639\u0644\u0649 \u0623\u062d\u0643\u0627\u0645 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u0648\u062a\u0634\u0631\u064a\u0639\u0627\u062a\u0647. \u0625\u0646 \u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0644\u0639\u0628\u0627\u062f\u0647\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","8:70":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a \u0642\u0644 \u0644\u0645\u0646 \u0623\u0633\u0631\u062a\u0645\u0648\u0647\u0645 \u0641\u064a \xab\u0628\u062f\u0631\xbb : \u0644\u0627 \u062a\u0623\u0633\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0641\u062f\u0627\u0621 \u0627\u0644\u0630\u064a \u0623\u062e\u0630 \u0645\u0646\u0643\u0645\u060c \u0625\u0646 \u064a\u0639\u0644\u0645 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0641\u064a \u0642\u0644\u0648\u0628\u0643\u0645 \u062e\u064a\u0631\u064b\u0627 \u064a\u0624\u062a\u0643\u0645 \u062e\u064a\u0631\u064b\u0627 \u0645\u0645\u0627 \u0623\u064f\u062e\u0630 \u0645\u0646\u0643\u0645 \u0645\u0646 \u0627\u0644\u0645\u0627\u0644 \u0628\u0623\u0646 \u064a\u064f\u064a\u064e\u0633\u0651\u0650\u0631 \u0644\u0643\u0645 \u0645\u0646 \u0641\u0636\u0644\u0647 \u062e\u064a\u0631\u064b\u0627 \u0643\u062b\u064a\u0631\u064b\u0627 -\u0648\u0642\u062f \u0623\u0646\u062c\u0632 \u0627\u0644\u0644\u0647 \u0648\u0639\u062f\u0647 \u0644\u0644\u0639\u0628\u0627\u0633 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0648\u063a\u064a\u0631\u0647-\u060c \u0648\u064a\u063a\u0641\u0631 \u0644\u0643\u0645 \u0630\u0646\u0648\u0628\u0643\u0645. \u0648\u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u063a\u0641\u0648\u0631 \u0644\u0630\u0646\u0648\u0628 \u0639\u0628\u0627\u062f\u0647 \u0625\u0630\u0627 \u062a\u0627\u0628\u0648\u0627\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","8:71":"\u0648\u0625\u0646 \u064a\u0631\u062f \u0627\u0644\u0630\u064a\u0646 \u0623\u064e\u0637\u0652\u0644\u064e\u0642\u0652\u062a\u064e \u0635\u0631\u0627\u062d\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0645\u0646 \u0627\u0644\u0623\u0633\u0631\u0649 \u0627\u0644\u063a\u062f\u0631 \u0628\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0641\u0644\u0627 \u062a\u064e\u064a\u0652\u0626\u0633\u0652\u060c \u0641\u0642\u062f \u062e\u0627\u0646\u0648\u0627 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0642\u0628\u0644 \u0648\u062d\u0627\u0631\u0628\u0648\u0643\u060c \u0641\u0646\u0635\u0631\u0643 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645. \u0648\u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645 \u0628\u0645\u0627 \u062a\u0646\u0637\u0648\u064a \u0639\u0644\u064a\u0647 \u0627\u0644\u0635\u062f\u0648\u0631\u060c \u062d\u0643\u064a\u0645 \u0641\u064a \u062a\u062f\u0628\u064a\u0631 \u0634\u0624\u0648\u0646 \u0639\u0628\u0627\u062f\u0647.","8:72":"\u0625\u0646 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647\u060c \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0648\u0647\u0627\u062c\u0631\u0648\u0627 \u0625\u0644\u0649 \u062f\u0627\u0631 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0623\u0648 \u0628\u0644\u062f \u064a\u062a\u0645\u0643\u0646\u0648\u0646 \u0641\u064a\u0647 \u0645\u0646 \u0639\u0628\u0627\u062f\u0629 \u0631\u0628\u0647\u0645\u060c \u0648\u062c\u0627\u0647\u062f\u0648\u0627 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u0645\u0627\u0644 \u0648\u0627\u0644\u0646\u0641\u0633\u060c \u0648\u0627\u0644\u0630\u064a\u0646 \u0623\u0646\u0632\u0644\u0648\u0627 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0641\u064a \u062f\u0648\u0631\u0647\u0645\u060c \u0648\u0648\u0627\u0633\u0648\u0647\u0645 \u0628\u0623\u0645\u0648\u0627\u0644\u0647\u0645\u060c \u0648\u0646\u0635\u0631\u0648\u0627 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647\u060c \u0623\u0648\u0644\u0626\u0643 \u0628\u0639\u0636\u0647\u0645 \u0646\u0635\u0631\u0627\u0621 \u0628\u0639\u0636. \u0623\u0645\u0627 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0648\u0644\u0645 \u064a\u0647\u0627\u062c\u0631\u0648\u0627 \u0645\u0646 \u062f\u0627\u0631 \u0627\u0644\u0643\u0641\u0631 \u0641\u0644\u0633\u062a\u0645 \u0645\u0643\u0644\u0641\u064a\u0646 \u0628\u062d\u0645\u0627\u064a\u062a\u0647\u0645 \u0648\u0646\u0635\u0631\u062a\u0647\u0645 \u062d\u062a\u0649 \u064a\u0647\u0627\u062c\u0631\u0648\u0627\u060c \u0648\u0625\u0646 \u0648\u0642\u0639 \u0639\u0644\u064a\u0647\u0645 \u0638\u0644\u0645 \u0645\u0646 \u0627\u0644\u0643\u0641\u0627\u0631 \u0641\u0637\u0644\u0628\u0648\u0627 \u0646\u0635\u0631\u062a\u0643\u0645 \u0641\u0627\u0633\u062a\u062c\u064a\u0628\u0648\u0627 \u0644\u0647\u0645\u060c \u0625\u0644\u0627 \u0639\u0644\u0649 \u0642\u0648\u0645 \u0628\u064a\u0646\u0643\u0645 \u0648\u0628\u064a\u0646\u0647\u0645 \u0639\u0647\u062f \u0645\u0624\u0643\u062f \u0644\u0645 \u064a\u0646\u0642\u0636\u0648\u0647. \u0648\u0627\u0644\u0644\u0647 \u0628\u0635\u064a\u0631 \u0628\u0623\u0639\u0645\u0627\u0644\u0643\u0645\u060c \u064a\u062c\u0632\u064a \u0643\u0644\u0627 \u0639\u0644\u0649 \u0642\u062f\u0631 \u0646\u064a\u062a\u0647 \u0648\u0639\u0645\u0644\u0647.","8:73":"\u0648\u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0628\u0639\u0636\u0647\u0645 \u0646\u0635\u0631\u0627\u0621 \u0628\u0639\u0636\u060c \u0648\u0625\u0646 \u0644\u0645 \u062a\u0643\u0648\u0646\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0646\u0635\u0631\u0627\u0621 \u0628\u0639\u0636 \u062a\u0643\u0646 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0641\u062a\u0646\u0629 \u0644\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0639\u0646 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647\u060c \u0648\u0641\u0633\u0627\u062f \u0639\u0631\u064a\u0636 \u0628\u0627\u0644\u0635\u062f \u0639\u0646 \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0648\u062a\u0642\u0648\u064a\u0629 \u062f\u0639\u0627\u0626\u0645 \u0627\u0644\u0643\u0641\u0631.","8:74":"\u0648\u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u062a\u0631\u0643\u0648\u0627 \u062f\u064a\u0627\u0631\u0647\u0645 \u0642\u0627\u0635\u062f\u064a\u0646 \u062f\u0627\u0631 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0623\u0648 \u0628\u0644\u062f\u064b\u0627 \u064a\u062a\u0645\u0643\u0646\u0648\u0646 \u0641\u064a\u0647 \u0645\u0646 \u0639\u0628\u0627\u062f\u0629 \u0631\u0628\u0647\u0645\u060c \u0648\u062c\u0627\u0647\u062f\u0648\u0627 \u0644\u0625\u0639\u0644\u0627\u0621 \u0643\u0644\u0645\u0629 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0644\u0630\u064a\u0646 \u0646\u0635\u0631\u0648\u0627 \u0625\u062e\u0648\u0627\u0646\u0647\u0645 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0648\u0622\u0648\u0648\u0647\u0645 \u0648\u0648\u0627\u0633\u0648\u0647\u0645 \u0628\u0627\u0644\u0645\u0627\u0644 \u0648\u0627\u0644\u062a\u0623\u064a\u064a\u062f\u060c \u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0627\u0644\u0635\u0627\u062f\u0642\u0648\u0646 \u062d\u0642\u064b\u0627\u060c \u0644\u0647\u0645 \u0645\u063a\u0641\u0631\u0629 \u0644\u0630\u0646\u0648\u0628\u0647\u0645\u060c \u0648\u0631\u0632\u0642 \u0643\u0631\u064a\u0645 \u0648\u0627\u0633\u0639 \u0641\u064a \u062c\u0646\u0627\u062a \u0627\u0644\u0646\u0639\u064a\u0645.","8:75":"\u0648\u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0645\u0650\u0646 \u0628\u0639\u062f \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0648\u0627\u0644\u0623\u0646\u0635\u0627\u0631\u060c \u0648\u0647\u0627\u062c\u0631\u0648\u0627 \u0648\u062c\u0627\u0647\u062f\u0648\u0627 \u0645\u0639\u0643\u0645 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647\u060c \u0641\u0623\u0648\u0644\u0626\u0643 \u0645\u0646\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0644\u0647\u0645 \u0645\u0627 \u0644\u0643\u0645 \u0648\u0639\u0644\u064a\u0647\u0645 \u0645\u0627 \u0639\u0644\u064a\u0643\u0645\u060c \u0648\u0623\u0648\u0644\u0648 \u0627\u0644\u0642\u0631\u0627\u0628\u0629 \u0628\u0639\u0636\u0647\u0645 \u0623\u0648\u0644\u0649 \u0628\u0628\u0639\u0636 \u0641\u064a \u0627\u0644\u062a\u0648\u0627\u0631\u062b \u0641\u064a \u062d\u0643\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0639\u0627\u0645\u0629 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0628\u0643\u0644 \u0634\u064a\u0621 \u0639\u0644\u064a\u0645 \u064a\u0639\u0644\u0645 \u0645\u0627 \u064a\u0635\u0644\u062d \u0639\u0628\u0627\u062f\u0647 \u0645\u0650\u0646 \u062a\u0648\u0631\u064a\u062b \u0628\u0639\u0636\u0647\u0645 \u0645\u0646 \u0628\u0639\u0636 \u0641\u064a \u0627\u0644\u0642\u0631\u0627\u0628\u0629 \u0648\u0627\u0644\u0646\u0633\u0628 \u062f\u0648\u0646 \u0627\u0644\u062a\u0648\u0627\u0631\u062b \u0628\u0627\u0644\u062d\u0650\u0644\u0652\u0641\u060c \u0648\u063a\u064a\u0631 \u0630\u0644\u0643 \u0645\u0645\u0627 \u0643\u0627\u0646 \u0641\u064a \u0623\u0648\u0644 \u0627\u0644\u0625\u0633\u0644\u0627\u0645.","9:1":"\u0647\u0630\u0647 \u0628\u0631\u0627\u0621\u0629 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0625\u0639\u0644\u0627\u0646 \u0628\u0627\u0644\u062a\u062e\u0644\u064a \u0639\u0646 \u0627\u0644\u0639\u0647\u0648\u062f \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u062a \u0628\u064a\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646.","9:2":"\u0641\u0633\u064a\u0631\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646- \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0645\u062f\u0651\u064e\u0629 \u0623\u0631\u0628\u0639\u0629 \u0623\u0634\u0647\u0631\u060c \u062a\u0630\u0647\u0628\u0648\u0646 \u062d\u064a\u062b \u0634\u0626\u062a\u0645 \u0622\u0645\u0646\u064a\u0646 \u0645\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0648\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646\u0643\u0645 \u0644\u0646 \u062a\u064f\u0641\u0652\u0644\u0650\u062a\u0648\u0627 \u0645\u0646 \u0627\u0644\u0639\u0642\u0648\u0628\u0629\u060c \u0648\u0623\u0646 \u0627\u0644\u0644\u0647 \u0645\u0630\u0644 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0648\u0645\u0648\u0631\u062b\u0647\u0645 \u0627\u0644\u0639\u0627\u0631 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0627\u0644\u0646\u0627\u0631 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629. \u0648\u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629 \u0644\u0630\u0648\u064a \u0627\u0644\u0639\u0647\u0648\u062f \u0627\u0644\u0645\u0637\u0644\u0642\u0629 \u063a\u064a\u0631 \u0627\u0644\u0645\u0624\u0642\u062a\u0629\u060c \u0623\u0648 \u0645\u0646 \u0644\u0647 \u0639\u0647\u062f \u062f\u0648\u0646 \u0623\u0631\u0628\u0639\u0629 \u0623\u0634\u0647\u0631\u060c \u0641\u064a\u0643\u0645\u0651\u064e\u0644 \u0644\u0647 \u0623\u0631\u0628\u0639\u0629 \u0623\u0634\u0647\u0631\u060c \u0623\u0648 \u0645\u064e\u0646 \u0643\u0627\u0646 \u0644\u0647 \u0639\u0647\u062f \u0641\u0646\u0642\u0636\u0647.","9:3":"\u0648\u0625\u0639\u0644\u0627\u0645 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0625\u0646\u0630\u0627\u0631 \u0625\u0644\u0649 \u0627\u0644\u0646\u0627\u0633 \u064a\u0648\u0645 \u0627\u0644\u0646\u062d\u0631 \u0623\u0646\u0651\u064e \u0627\u0644\u0644\u0647 \u0628\u0631\u064a\u0621 \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646\u060c \u0648\u0631\u0633\u0648\u0644\u0647 \u0628\u0631\u064a\u0621 \u0645\u0646\u0647\u0645 \u0643\u0630\u0644\u0643. \u0641\u0625\u0646 \u0631\u062c\u0639\u062a\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646- \u0625\u0644\u0649 \u0627\u0644\u062d\u0642 \u0648\u062a\u0631\u0643\u062a\u0645 \u0634\u0631\u0643\u0643\u0645 \u0641\u0647\u0648 \u062e\u064a\u0631 \u0644\u0643\u0645\u060c \u0648\u0625\u0646 \u0623\u0639\u0631\u0636\u062a\u0645 \u0639\u0646 \u0642\u064e\u0628\u0648\u0644 \u0627\u0644\u062d\u0642 \u0648\u0623\u0628\u064a\u062a\u0645 \u0627\u0644\u062f\u062e\u0648\u0644 \u0641\u064a \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u0641\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646\u0643\u0645 \u0644\u0646 \u062a\u064f\u0641\u0652\u0644\u0650\u062a\u0648\u0627 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647. \u0648\u0623\u0646\u0630\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0639\u0631\u0636\u064a\u0646 \u0639\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0648\u062c\u0639.","9:4":"\u0648\u064a\u064f\u0633\u062a\u062b\u0646\u0649 \u0645\u0646 \u0627\u0644\u062d\u0643\u0645 \u0627\u0644\u0633\u0627\u0628\u0642 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0627\u0644\u0630\u064a\u0646 \u062f\u062e\u0644\u0648\u0627 \u0645\u0639\u0643\u0645 \u0641\u064a \u0639\u0647\u062f \u0645\u062d\u062f\u062f \u0628\u0645\u062f\u0629\u060c \u0648\u0644\u0645 \u064a\u062e\u0648\u0646\u0648\u0627 \u0627\u0644\u0639\u0647\u062f\u060c \u0648\u0644\u0645 \u064a\u0639\u0627\u0648\u0646\u0648\u0627 \u0639\u0644\u064a\u0643\u0645 \u0623\u062d\u062f\u0627 \u0645\u0646 \u0627\u0644\u0623\u0639\u062f\u0627\u0621\u060c \u0641\u0623\u0643\u0645\u0644\u0648\u0627 \u0644\u0647\u0645 \u0639\u0647\u062f\u0647\u0645 \u0625\u0644\u0649 \u0646\u0647\u0627\u064a\u062a\u0647 \u0627\u0644\u0645\u062d\u062f\u0648\u062f\u0629. \u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u062d\u0628 \u0627\u0644\u0645\u062a\u0642\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0623\u062f\u0651\u064e\u0648\u0627 \u0645\u0627 \u0623\u0645\u0631\u0648\u0627 \u0628\u0647\u060c \u0648\u0627\u062a\u0642\u0648\u0627 \u0627\u0644\u0634\u0631\u0643 \u0648\u0627\u0644\u062e\u064a\u0627\u0646\u0629\u060c \u0648\u063a\u064a\u0631 \u0630\u0644\u0643 \u0645\u0646 \u0627\u0644\u0645\u0639\u0627\u0635\u064a.","9:5":"\u0641\u0625\u0630\u0627 \u0627\u0646\u0642\u0636\u062a \u0627\u0644\u0623\u0634\u0647\u0631 \u0627\u0644\u0623\u0631\u0628\u0639\u0629 \u0627\u0644\u062a\u064a \u0623\u0645\u0651\u064e\u0646\u062a\u0645 \u0641\u064a\u0647\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646\u060c \u0641\u0623\u0639\u0644\u0646\u0648\u0627 \u0627\u0644\u062d\u0631\u0628 \u0639\u0644\u0649 \u0623\u0639\u062f\u0627\u0621 \u0627\u0644\u0644\u0647 \u062d\u064a\u062b \u0643\u0627\u0646\u0648\u0627\u060c \u0648\u0627\u0642\u0635\u062f\u0648\u0647\u0645 \u0628\u0627\u0644\u062d\u0635\u0627\u0631 \u0641\u064a \u0645\u0639\u0627\u0642\u0644\u0647\u0645\u060c \u0648\u062a\u0631\u0635\u062f\u0648\u0627 \u0644\u0647\u0645 \u0641\u064a \u0637\u0631\u0642\u0647\u0645\u060c \u0641\u0625\u0646 \u0631\u062c\u0639\u0648\u0627 \u0639\u0646 \u0643\u0641\u0631\u0647\u0645 \u0648\u062f\u062e\u0644\u0648\u0627 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0627\u0644\u062a\u0632\u0645\u0648\u0627 \u0634\u0631\u0627\u0626\u0639\u0647 \u0645\u0646 \u0625\u0642\u0627\u0645 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0625\u062e\u0631\u0627\u062c \u0627\u0644\u0632\u0643\u0627\u0629\u060c \u0641\u0627\u062a\u0631\u0643\u0648\u0647\u0645\u060c \u0641\u0642\u062f \u0623\u0635\u0628\u062d\u0648\u0627 \u0625\u062e\u0648\u0627\u0646\u0643\u0645 \u0641\u064a \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0625\u0646 \u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0644\u0645\u0646 \u062a\u0627\u0628 \u0648\u0623\u0646\u0627\u0628\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","9:6":"\u0648\u0625\u0630\u0627 \u0637\u0644\u0628 \u0623\u062d\u062f \u0645\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0627\u0633\u062a\u0628\u064a\u062d\u062a \u062f\u0645\u0627\u0624\u0647\u0645 \u0648\u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0627\u0644\u062f\u062e\u0648\u0644 \u0641\u064a \u062c\u0648\u0627\u0631\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0648\u0631\u063a\u0628 \u0641\u064a \u0627\u0644\u0623\u0645\u0627\u0646\u060c \u0641\u0623\u062c\u0628\u0647 \u0625\u0644\u0649 \u0637\u0644\u0628\u0647 \u062d\u062a\u0649 \u064a\u0633\u0645\u0639 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645 \u0648\u064a\u0637\u0651\u064e\u0644\u0639 \u0639\u0644\u0649 \u0647\u062f\u0627\u064a\u062a\u0647\u060c \u062b\u0645 \u0623\u064e\u0639\u0650\u062f\u0652\u0647 \u0645\u0646 \u062d\u064a\u062b \u0623\u062a\u0649 \u0622\u0645\u0646\u064b\u0627; \u0648\u0630\u0644\u0643 \u0644\u0625\u0642\u0627\u0645\u0629 \u0627\u0644\u062d\u062c\u0629 \u0639\u0644\u064a\u0647; \u0630\u0644\u0643 \u0628\u0633\u0628\u0628 \u0623\u0646 \u0627\u0644\u0643\u0641\u0627\u0631 \u0642\u0648\u0645 \u062c\u0627\u0647\u0644\u0648\u0646 \u0628\u062d\u0642\u0627\u0626\u0642 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0641\u0631\u0628\u0645\u0627 \u0627\u062e\u062a\u0627\u0631\u0648\u0647 \u0625\u0630\u0627 \u0632\u0627\u0644 \u0627\u0644\u062c\u0647\u0644 \u0639\u0646\u0647\u0645.","9:7":"\u0644\u0627 \u064a\u0646\u0628\u063a\u064a \u0623\u0646 \u064a\u0643\u0648\u0646 \u0644\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0639\u0647\u062f \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0648\u0639\u0646\u062f \u0631\u0633\u0648\u0644\u0647\u060c \u0625\u0644\u0627 \u0627\u0644\u0630\u064a\u0646 \u0639\u0627\u0647\u062f\u062a\u0645 \u0639\u0646\u062f \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u062d\u0631\u0627\u0645 \u0641\u064a \u0635\u0644\u062d (\u0627\u0644\u062d\u062f\u064a\u0628\u064a\u0629) \u0641\u0645\u0627 \u0623\u0642\u0627\u0645\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0648\u0641\u0627\u0621 \u0628\u0639\u0647\u062f\u0643\u0645 \u0641\u0623\u0642\u064a\u0645\u0648\u0627 \u0644\u0647\u0645 \u0639\u0644\u0649 \u0645\u062b\u0644 \u0630\u0644\u0643. \u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u062d\u0628 \u0627\u0644\u0645\u062a\u0642\u064a\u0646 \u0627\u0644\u0645\u0648\u0641\u0651\u0650\u064a\u0646 \u0628\u0639\u0647\u0648\u062f\u0647\u0645.","9:8":"\u0625\u0646 \u0634\u0623\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0623\u0646 \u064a\u0644\u062a\u0632\u0645\u0648\u0627 \u0628\u0627\u0644\u0639\u0647\u0648\u062f \u0645\u0627 \u062f\u0627\u0645\u062a \u0627\u0644\u063a\u0644\u0628\u0629 \u0644\u063a\u064a\u0631\u0647\u0645\u060c \u0623\u0645\u0627 \u0625\u0630\u0627 \u0634\u0639\u0631\u0648\u0627 \u0628\u0627\u0644\u0642\u0648\u0629 \u0639\u0644\u0649 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0641\u0625\u0646\u0647\u0645 \u0644\u0627 \u064a\u0631\u0627\u0639\u0648\u0646 \u0627\u0644\u0642\u0631\u0627\u0628\u0629 \u0648\u0644\u0627 \u0627\u0644\u0639\u0647\u062f\u060c \u0641\u0644\u0627 \u064a\u063a\u0631\u0646\u0643\u0645 \u0645\u0646\u0647\u0645 \u0645\u0627 \u064a\u0639\u0627\u0645\u0644\u0648\u0646\u0643\u0645 \u0628\u0647 \u0648\u0642\u062a \u0627\u0644\u062e\u0648\u0641 \u0645\u0646\u0643\u0645\u060c \u0641\u0625\u0646\u0647\u0645 \u064a\u0642\u0648\u0644\u0648\u0646 \u0644\u0643\u0645 \u0643\u0644\u0627\u0645\u064b\u0627 \u0628\u0623\u0644\u0633\u0646\u062a\u0647\u0645; \u0644\u062a\u0631\u0636\u0648\u0627 \u0639\u0646\u0647\u0645\u060c \u0648\u0644\u0643\u0646 \u0642\u0644\u0648\u0628\u0647\u0645 \u062a\u0623\u0628\u0649 \u0630\u0644\u0643\u060c \u0648\u0623\u0643\u062b\u0631\u0647\u0645 \u0645\u062a\u0645\u0631\u062f\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0646\u0627\u0642\u0636\u0648\u0646 \u0644\u0644\u0639\u0647\u062f.","9:9":"\u0627\u0633\u062a\u0628\u062f\u0644\u0648\u0627 \u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0639\u0631\u0636 \u0627\u0644\u062f\u0646\u064a\u0627 \u0627\u0644\u062a\u0627\u0641\u0647\u060c \u0641\u0623\u0639\u0631\u0636\u0648\u0627 \u0639\u0646 \u0627\u0644\u062d\u0642 \u0648\u0645\u0646\u0639\u0648\u0627 \u0627\u0644\u0631\u0627\u063a\u0628\u064a\u0646 \u0641\u064a \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0639\u0646 \u0627\u0644\u062f\u062e\u0648\u0644 \u0641\u064a\u0647\u060c \u0644\u0642\u062f \u0642\u064e\u0628\u064f\u062d \u0641\u0639\u0644\u0647\u0645\u060c \u0648\u0633\u0627\u0621 \u0635\u0646\u064a\u0639\u0647\u0645.","9:10":"\u0625\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u062d\u0631\u0628 \u0639\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0623\u0647\u0644\u0647\u060c \u0641\u0644\u0627 \u064a\u0642\u064a\u0645\u0648\u0646 \u0648\u0632\u0646\u064b\u0627 \u0644\u0642\u0631\u0627\u0628\u0629 \u0627\u0644\u0645\u0624\u0645\u0646 \u0648\u0644\u0627 \u0644\u0639\u0647\u062f\u0647\u060c \u0648\u0634\u0623\u0646\u0647\u0645 \u0627\u0644\u0639\u062f\u0648\u0627\u0646 \u0648\u0627\u0644\u0638\u0644\u0645.","9:11":"\u0641\u0625\u0646 \u0623\u0642\u0644\u0639\u0648\u0627 \u0639\u0646 \u0639\u0628\u0627\u062f\u0629 \u063a\u064a\u0631 \u0627\u0644\u0644\u0647\u060c \u0648\u0646\u0637\u0642\u0648\u0627 \u0628\u0643\u0644\u0645\u0629 \u0627\u0644\u062a\u0648\u062d\u064a\u062f\u060c \u0648\u0627\u0644\u062a\u0632\u0645\u0648\u0627 \u0634\u0631\u0627\u0626\u0639 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0645\u0646 \u0625\u0642\u0627\u0645 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0625\u064a\u062a\u0627\u0621 \u0627\u0644\u0632\u0643\u0627\u0629\u060c \u0641\u0625\u0646\u0647\u0645 \u0625\u062e\u0648\u0627\u0646\u0643\u0645 \u0641\u064a \u0627\u0644\u0625\u0633\u0644\u0627\u0645. \u0648\u0646\u0628\u064a\u0646 \u0627\u0644\u0622\u064a\u0627\u062a\u060c \u0648\u0646\u0648\u0636\u062d\u0647\u0627 \u0644\u0642\u0648\u0645 \u064a\u0646\u062a\u0641\u0639\u0648\u0646 \u0628\u0647\u0627.","9:12":"\u0648\u0625\u0646\u0652 \u0646\u064e\u0642\u064e\u0636\u064e \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0627\u0644\u0639\u0647\u0648\u062f \u0627\u0644\u062a\u064a \u0623\u0628\u0631\u0645\u062a\u0645\u0648\u0647\u0627 \u0645\u0639\u0647\u0645\u060c \u0648\u0623\u0638\u0647\u0631\u0648\u0627 \u0627\u0644\u0637\u0639\u0646 \u0641\u064a \u062f\u064a\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0641\u0642\u0627\u062a\u0644\u0648\u0647\u0645 \u0641\u0625\u0646\u0647\u0645 \u0631\u0624\u0633\u0627\u0621 \u0627\u0644\u0636\u0644\u0627\u0644\u060c \u0644\u0627 \u0639\u0647\u062f \u0644\u0647\u0645 \u0648\u0644\u0627 \u0630\u0645\u0629\u060c \u062d\u062a\u0649 \u064a\u0646\u062a\u0647\u0648\u0627 \u0639\u0646 \u0643\u0641\u0631\u0647\u0645 \u0648\u0639\u062f\u0627\u0648\u062a\u0647\u0645 \u0644\u0644\u0625\u0633\u0644\u0627\u0645.","9:13":"\u0644\u0627 \u062a\u062a\u0631\u062f\u062f\u0648\u0627 \u0641\u064a \u0642\u062a\u0627\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u0630\u064a\u0646 \u0646\u0642\u0636\u0648\u0627 \u0639\u0647\u0648\u062f\u0647\u0645\u060c \u0648\u0639\u0645\u0644\u0648\u0627 \u0639\u0644\u0649 \u0625\u062e\u0631\u0627\u062c \u0627\u0644\u0631\u0633\u0648\u0644 \u0645\u0646 (\u0645\u0643\u0629) \u060c \u0648\u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0628\u062f\u0624\u0648\u0627 \u0628\u0625\u064a\u0630\u0627\u0626\u0643\u0645 \u0623\u0648\u0644 \u0627\u0644\u0623\u0645\u0631\u060c \u0623\u062a\u062e\u0627\u0641\u0648\u0646\u0647\u0645 \u0623\u0648 \u062a\u062e\u0627\u0641\u0648\u0646 \u0645\u0644\u0627\u0642\u0627\u062a\u0647\u0645 \u0641\u064a \u0627\u0644\u062d\u0631\u0628\u061f \u0641\u0627\u0644\u0644\u0647 \u0623\u062d\u0642 \u0623\u0646 \u062a\u062e\u0627\u0641\u0648\u0647 \u0625\u0646 \u0643\u0646\u062a\u0645 \u0645\u0624\u0645\u0646\u064a\u0646 \u062d\u0642\u064b\u0627.","9:14":"\u064a\u0627 \u0645\u0639\u0634\u0631 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0642\u0627\u062a\u0644\u0648\u0627 \u0623\u0639\u062f\u0627\u0621 \u0627\u0644\u0644\u0647 \u064a\u0639\u0630\u0628\u0647\u0645 \u0639\u0632 \u0648\u062c\u0644 \u0628\u0623\u064a\u062f\u064a\u0643\u0645\u060c \u0648\u064a\u0630\u0644\u0647\u0645 \u0628\u0627\u0644\u0647\u0632\u064a\u0645\u0629 \u0648\u0627\u0644\u062e\u0632\u064a\u060c \u0648\u064a\u0646\u0635\u0631\u0643\u0645 \u0639\u0644\u064a\u0647\u0645\u060c \u0648\u064a\u064f\u0639\u0652\u0644\u0650 \u0643\u0644\u0645\u062a\u0647\u060c \u0648\u064a\u0634\u0641 \u0628\u0647\u0632\u064a\u0645\u062a\u0647\u0645 \u0635\u062f\u0648\u0631\u0643\u0645 \u0627\u0644\u062a\u064a \u0637\u0627\u0644\u0645\u0627 \u0644\u062d\u0642 \u0628\u0647\u0627 \u0627\u0644\u062d\u0632\u0646 \u0648\u0627\u0644\u063a\u0645 \u0645\u0646 \u0643\u064a\u062f \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646\u060c \u0648\u064a\u064f\u0630\u0652\u0647\u0650\u0628 \u0639\u0646 \u0642\u0644\u0648\u0628 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0627\u0644\u063a\u064a\u0638. \u0648\u0645\u0646 \u062a\u0627\u0628 \u0645\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0639\u0627\u0646\u062f\u064a\u0646 \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u062a\u0648\u0628 \u0639\u0644\u0649 \u0645\u0646 \u064a\u0634\u0627\u0621. \u0648\u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645 \u0628\u0635\u062f\u0642 \u062a\u0648\u0628\u0629 \u0627\u0644\u062a\u0627\u0626\u0628\u060c \u062d\u0643\u064a\u0645 \u0641\u064a \u062a\u062f\u0628\u064a\u0631\u0647 \u0648\u0635\u0646\u0639\u0647 \u0648\u0648\u064e\u0636\u0652\u0639 \u062a\u0634\u0631\u064a\u0639\u0627\u062a\u0647 \u0644\u0639\u0628\u0627\u062f\u0647.","9:15":"@9:14","9:16":"\u0645\u0650\u0646 \u0633\u0646\u0629 \u0627\u0644\u0644\u0647 \u0627\u0644\u0627\u0628\u062a\u0644\u0627\u0621\u060c \u0641\u0644\u0627 \u062a\u0638\u0646\u0648\u0627 \u064a\u0627 \u0645\u0639\u0634\u0631 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0623\u0646 \u064a\u062a\u0631\u0643\u0643\u0645 \u0627\u0644\u0644\u0647 \u062f\u0648\u0646 \u0627\u062e\u062a\u0628\u0627\u0631; \u0644\u064a\u0639\u0644\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u0645\u064b\u0627 \u0638\u0627\u0647\u0631\u064b\u0627 \u0644\u0644\u062e\u0644\u0642 \u0627\u0644\u0630\u064a\u0646 \u0623\u062e\u0644\u0635\u0648\u0627 \u0641\u064a \u062c\u0647\u0627\u062f\u0647\u0645\u060c \u0648\u0644\u0645 \u064a\u062a\u062e\u0630\u0648\u0627 \u063a\u064a\u0631 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u0637\u0627\u0646\u0629 \u0648\u0623\u0648\u0644\u064a\u0627\u0621. \u0648\u0627\u0644\u0644\u0647 \u062e\u0628\u064a\u0631 \u0628\u062c\u0645\u064a\u0639 \u0623\u0639\u0645\u0627\u0644\u0643\u0645 \u0648\u0645\u062c\u0627\u0632\u064a\u0643\u0645 \u0628\u0647\u0627.","9:17":"\u0644\u064a\u0633 \u0645\u0646 \u0634\u0623\u0646 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0625\u0639\u0645\u0627\u0631 \u0628\u064a\u0648\u062a \u0627\u0644\u0644\u0647\u060c \u0648\u0647\u0645 \u064a\u0639\u0644\u0646\u0648\u0646 \u0643\u0641\u0631\u0647\u0645 \u0628\u0627\u0644\u0644\u0647 \u0648\u064a\u062c\u0639\u0644\u0648\u0646 \u0644\u0647 \u0634\u0631\u0643\u0627\u0621. \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0628\u0637\u0644\u062a \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629\u060c \u0648\u0645\u0635\u064a\u0631\u0647\u0645 \u0627\u0644\u062e\u0644\u0648\u062f \u0641\u064a \u0627\u0644\u0646\u0627\u0631.","9:18":"\u0644\u0627 \u064a\u0639\u062a\u0646\u064a \u0628\u0628\u064a\u0648\u062a \u0627\u0644\u0644\u0647 \u0648\u064a\u0639\u0645\u0631\u0647\u0627 \u0625\u0644\u0627 \u0627\u0644\u0630\u064a\u0646 \u064a\u0624\u0645\u0646\u0648\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631\u060c \u0648\u064a\u0642\u064a\u0645\u0648\u0646 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u064a\u0624\u062a\u0648\u0646 \u0627\u0644\u0632\u0643\u0627\u0629\u060c \u0648\u0644\u0627 \u064a\u062e\u0627\u0641\u0648\u0646 \u0641\u064a \u0627\u0644\u0644\u0647 \u0644\u0648\u0645\u0629 \u0644\u0627\u0626\u0645\u060c \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0639\u064f\u0645\u0651\u064e\u0627\u0631 \u0647\u0645 \u0627\u0644\u0645\u0647\u062a\u062f\u0648\u0646 \u0625\u0644\u0649 \u0627\u0644\u062d\u0642.","9:19":"\u0623\u062c\u0639\u0644\u062a\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0642\u0648\u0645- \u0645\u0627 \u062a\u0642\u0648\u0645\u0648\u0646 \u0628\u0647 \u0645\u0646 \u0633\u0642\u064a \u0627\u0644\u062d\u062c\u064a\u062c \u0648\u0639\u0650\u0645\u0627\u0631\u0629 \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u062d\u0631\u0627\u0645 \u0643\u0625\u064a\u0645\u0627\u0646 \u0645\u0646 \u0622\u0645\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631 \u0648\u062c\u0627\u0647\u062f \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647\u061f \u0644\u0627 \u062a\u062a\u0633\u0627\u0648\u0649 \u062d\u0627\u0644 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0648\u062d\u0627\u0644 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0644\u0623\u0646 \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0642\u0628\u0644 \u0639\u0645\u0644\u0627 \u0628\u063a\u064a\u0631 \u0627\u0644\u0625\u064a\u0645\u0627\u0646. \u0648\u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0644\u0627 \u064a\u0648\u0641\u0642 \u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u062e\u064a\u0631 \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0644\u0623\u0646\u0641\u0633\u0647\u0645 \u0628\u0627\u0644\u0643\u0641\u0631.","9:20":"\u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u062a\u0631\u0643\u0648\u0627 \u062f\u0627\u0631 \u0627\u0644\u0643\u0641\u0631 \u0642\u0627\u0635\u062f\u064a\u0646 \u062f\u0627\u0631 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u0628\u0630\u0644\u0648\u0627 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0648\u0623\u0646\u0641\u0633\u0647\u0645 \u0641\u064a \u0627\u0644\u062c\u0647\u0627\u062f \u0644\u0625\u0639\u0644\u0627\u0621 \u0643\u0644\u0645\u0629 \u0627\u0644\u0644\u0647\u060c \u0647\u0624\u0644\u0627\u0621 \u0623\u0639\u0638\u0645 \u062f\u0631\u062c\u0647 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0648\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u0641\u0627\u0626\u0632\u0648\u0646 \u0628\u0631\u0636\u0648\u0627\u0646\u0647.","9:21":"\u0625\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0644\u0647\u0645 \u0627\u0644\u0628\u0634\u0631\u0649 \u0645\u0646 \u0631\u0628\u0647\u0645 \u0628\u0627\u0644\u0631\u062d\u0645\u0629 \u0627\u0644\u0648\u0627\u0633\u0639\u0629 \u0648\u0627\u0644\u0631\u0636\u0648\u0627\u0646 \u0627\u0644\u0630\u064a \u0644\u0627 \u0633\u062e\u0637 \u0628\u0639\u062f\u0647\u060c \u0648\u0645\u0635\u064a\u0631\u0647\u0645 \u0625\u0644\u0649 \u062c\u0646\u0627\u062a \u0627\u0644\u062e\u0644\u062f \u0648\u0627\u0644\u0646\u0639\u064a\u0645 \u0627\u0644\u062f\u0627\u0626\u0645.","9:22":"\u0645\u0627\u0643\u062b\u064a\u0646 \u0641\u064a \u062a\u0644\u0643 \u0627\u0644\u062c\u0646\u0627\u0646 \u0644\u0627 \u0646\u0647\u0627\u064a\u0629 \u0644\u0625\u0642\u0627\u0645\u062a\u0647\u0645 \u0648\u062a\u0646\u0639\u0645\u0647\u0645\u060c \u0648\u0630\u0644\u0643 \u062b\u0648\u0627\u0628 \u0645\u0627 \u0642\u062f\u0651\u064e\u0645\u0648\u0647 \u0645\u0646 \u0627\u0644\u0637\u0627\u0639\u0627\u062a \u0648\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d \u0641\u064a \u062d\u064a\u0627\u062a\u0647\u0645 \u0627\u0644\u062f\u0646\u064a\u0627. \u0625\u0646 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0639\u0646\u062f\u0647 \u0623\u062c\u0631 \u0639\u0638\u064a\u0645 \u0644\u0645\u0646 \u0622\u0645\u0646 \u0648\u0639\u0645\u0644 \u0635\u0627\u0644\u062d\u0627 \u0628\u0627\u0645\u062a\u062b\u0627\u0644 \u0623\u0648\u0627\u0645\u0631\u0647 \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0646\u0648\u0627\u0647\u064a\u0647.","9:23":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647 \u0644\u0627 \u062a\u062a\u062e\u0630\u0648\u0627 \u0623\u0642\u0631\u0628\u0627\u0621\u0643\u0645 -\u0645\u0646 \u0627\u0644\u0622\u0628\u0627\u0621 \u0648\u0627\u0644\u0625\u062e\u0648\u0627\u0646 \u0648\u063a\u064a\u0631\u0647\u0645- \u0623\u0648\u0644\u064a\u0627\u0621\u060c \u062a\u0641\u0634\u0648\u0646 \u0625\u0644\u064a\u0647\u0645 \u0623\u0633\u0631\u0627\u0631 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0648\u062a\u0633\u062a\u0634\u064a\u0631\u0648\u0646\u0647\u0645 \u0641\u064a \u0623\u0645\u0648\u0631\u0643\u0645\u060c \u0645\u0627 \u062f\u0627\u0645\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0643\u0641\u0631 \u0645\u0639\u0627\u062f\u064a\u0646 \u0644\u0644\u0625\u0633\u0644\u0627\u0645. \u0648\u0645\u0646 \u064a\u062a\u062e\u0630\u0647\u0645 \u0623\u0648\u0644\u064a\u0627\u0621 \u0648\u064a\u064f\u0644\u0652\u0642\u0650 \u0625\u0644\u064a\u0647\u0645 \u0627\u0644\u0645\u0648\u062f\u0629 \u0641\u0642\u062f \u0639\u0635\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0648\u0638\u0644\u0645 \u0646\u0641\u0633\u0647 \u0638\u0644\u0645\u064b\u0627 \u0639\u0638\u064a\u0645\u064b\u0627.","9:24":"\u0642\u0644 -\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0644\u0645\u0624\u0645\u0646\u064a\u0646: \u0625\u0646 \u0641\u064e\u0636\u0651\u064e\u0644\u062a\u0645 \u0627\u0644\u0622\u0628\u0627\u0621 \u0648\u0627\u0644\u0623\u0628\u0646\u0627\u0621 \u0648\u0627\u0644\u0625\u062e\u0648\u0627\u0646 \u0648\u0627\u0644\u0632\u0648\u062c\u0627\u062a \u0648\u0627\u0644\u0642\u0631\u0627\u0628\u0627\u062a \u0648\u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u062a\u064a \u062c\u0645\u0639\u062a\u0645\u0648\u0647\u0627 \u0648\u0627\u0644\u062a\u062c\u0627\u0631\u0629 \u0627\u0644\u062a\u064a \u062a\u062e\u0627\u0641\u0648\u0646 \u0639\u062f\u0645 \u0631\u0648\u0627\u062c\u0647\u0627 \u0648\u0627\u0644\u0628\u064a\u0648\u062a \u0627\u0644\u0641\u0627\u0631\u0647\u0629 \u0627\u0644\u062a\u064a \u0623\u0642\u0645\u062a\u0645 \u0641\u064a\u0647\u0627\u060c \u0625\u0646 \u0641\u064e\u0636\u0651\u064e\u0644\u062a\u0645 \u0630\u0644\u0643 \u0639\u0644\u0649 \u062d\u0628 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0627\u0644\u062c\u0647\u0627\u062f \u0641\u064a \u0633\u0628\u064a\u0644\u0647 \u0641\u0627\u0646\u062a\u0638\u0631\u0648\u0627 \u0639\u0642\u0627\u0628 \u0627\u0644\u0644\u0647 \u0648\u0646\u0643\u0627\u0644\u0647 \u0628\u0643\u0645. \u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0648\u0641\u0642 \u0627\u0644\u062e\u0627\u0631\u062c\u064a\u0646 \u0639\u0646 \u0637\u0627\u0639\u062a\u0647.","9:25":"\u0644\u0642\u062f \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0646\u064e\u0635\u0652\u0631\u064e\u0647 \u0639\u0644\u064a\u0643\u0645 \u0641\u064a \u0645\u0648\u0627\u0642\u0639 \u0643\u062b\u064a\u0631\u0629 \u0639\u0646\u062f\u0645\u0627 \u0623\u062e\u0630\u062a\u0645 \u0628\u0627\u0644\u0623\u0633\u0628\u0627\u0628 \u0648\u062a\u0648\u0643\u0644\u062a\u0645 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647. \u0648\u064a\u0648\u0645 \u063a\u0632\u0648\u0629 (\u062d\u0646\u064a\u0646) \u0642\u0644\u062a\u0645: \u0644\u0646 \u0646\u064f\u063a\u0652\u0644\u064e\u0628\u064e \u0627\u0644\u064a\u0648\u0645 \u0645\u0646 \u0642\u0644\u0629\u060c \u0641\u063a\u0631\u0651\u064e\u062a\u0643\u0645 \u0627\u0644\u0643\u062b\u0631\u0629 \u0641\u0644\u0645 \u062a\u0646\u0641\u0639\u0643\u0645\u060c \u0648\u0638\u0647\u0631 \u0639\u0644\u064a\u0643\u0645 \u0627\u0644\u0639\u062f\u0648 \u0641\u0644\u0645 \u062a\u062c\u062f\u0648\u0627 \u0645\u0644\u062c\u0623\u064b \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0627\u0644\u0648\u0627\u0633\u0639\u0629 \u0641\u0641\u0631\u0631\u062a\u0645 \u0645\u0646\u0647\u0632\u0645\u064a\u0646.","9:26":"\u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0627\u0644\u0637\u0645\u0623\u0646\u064a\u0646\u0629 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0644\u0649 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0641\u062b\u0628\u062a\u0648\u0627\u060c \u0648\u0623\u0645\u062f\u0651\u064e\u0647\u0645 \u0628\u062c\u0646\u0648\u062f \u0645\u0646 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629 \u0644\u0645 \u064a\u0631\u0648\u0647\u0627\u060c \u0641\u0646\u0635\u0631\u0647\u0645 \u0639\u0644\u0649 \u0639\u062f\u0648\u0647\u0645\u060c \u0648\u0639\u0630\u0651\u064e\u0628 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627. \u0648\u062a\u0644\u0643 \u0639\u0642\u0648\u0628\u0629 \u0627\u0644\u0644\u0647 \u0644\u0644\u0635\u0627\u062f\u0651\u0650\u064a\u0646 \u0639\u0646 \u062f\u064a\u0646\u0647\u060c \u0627\u0644\u0645\u0643\u0630\u0651\u0650\u0628\u064a\u0646 \u0644\u0631\u0633\u0648\u0644\u0647.","9:27":"\u0648\u0645\u0646 \u0631\u062c\u0639 \u0639\u0646 \u0643\u0641\u0631\u0647 \u0628\u0639\u062f \u0630\u0644\u0643 \u0648\u062f\u062e\u0644 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u064a\u0642\u0628\u0644 \u062a\u0648\u0628\u0629 \u0645\u064e\u0646 \u064a\u0634\u0627\u0621 \u0645\u0646\u0647\u0645\u060c \u0641\u064a\u063a\u0641\u0631 \u0630\u0646\u0628\u0647. \u0648\u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0631\u062d\u064a\u0645.","9:28":"\u064a\u0627 \u0645\u0639\u0634\u0631 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0625\u0646\u0645\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0631\u0650\u062c\u0652\u0633 \u0648\u062e\u064e\u0628\u064e\u062b \u0641\u0644\u0627 \u062a\u0645\u0643\u0646\u0648\u0647\u0645 \u0645\u0646 \u0627\u0644\u0627\u0642\u062a\u0631\u0627\u0628 \u0645\u0646 \u0627\u0644\u062d\u0631\u0645 \u0628\u0639\u062f \u0647\u0630\u0627 \u0627\u0644\u0639\u0627\u0645 \u0627\u0644\u062a\u0627\u0633\u0639 \u0645\u0646 \u0627\u0644\u0647\u062c\u0631\u0629\u060c \u0648\u0625\u0646 \u062e\u0641\u062a\u0645 \u0641\u0642\u0631\u064b\u0627 \u0644\u0627\u0646\u0642\u0637\u0627\u0639 \u063a\u0627\u0631\u062a\u0647\u0645 \u0639\u0646\u0643\u0645\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0633\u064a\u0639\u0648\u0636\u0643\u0645 \u0639\u0646\u0647\u0627\u060c \u0648\u064a\u0643\u0641\u064a\u0643\u0645 \u0645\u0646 \u0641\u0636\u0644\u0647 \u0625\u0646 \u0634\u0627\u0621\u060c \u0625\u0646 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645 \u0628\u062d\u0627\u0644\u0643\u0645\u060c \u062d\u0643\u064a\u0645 \u0641\u064a \u062a\u062f\u0628\u064a\u0631 \u0634\u0624\u0648\u0646\u0643\u0645.","9:29":"\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0642\u0627\u062a\u0644\u0648\u0627 \u0627\u0644\u0643\u0641\u0627\u0631 \u0627\u0644\u0630\u064a\u0646 \u0644\u0627 \u064a\u0624\u0645\u0646\u0648\u0646 \u0628\u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u064a\u0624\u0645\u0646\u0648\u0646 \u0628\u0627\u0644\u0628\u0639\u062b \u0648\u0627\u0644\u062c\u0632\u0627\u0621\u060c \u0648\u0644\u0627 \u064a\u062c\u062a\u0646\u0628\u0648\u0646 \u0645\u0627 \u0646\u0647\u0649 \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0644\u0627 \u064a\u0644\u062a\u0632\u0645\u0648\u0646 \u0623\u062d\u0643\u0627\u0645 \u0634\u0631\u064a\u0639\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649\u060c \u062d\u062a\u0649 \u064a\u062f\u0641\u0639\u0648\u0627 \u0627\u0644\u062c\u0632\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u0641\u0631\u0636\u0648\u0646\u0647\u0627 \u0639\u0644\u064a\u0647\u0645 \u0628\u0623\u064a\u062f\u064a\u0647\u0645 \u062e\u0627\u0636\u0639\u064a\u0646 \u0623\u0630\u0644\u0627\u0621.","9:30":"\u0644\u0642\u062f \u0623\u0634\u0631\u0643 \u0627\u0644\u064a\u0647\u0648\u062f \u0628\u0627\u0644\u0644\u0647 \u0639\u0646\u062f\u0645\u0627 \u0632\u0639\u0645\u0648\u0627 \u0623\u0646 \u0639\u0632\u064a\u0631\u064b\u0627 \u0627\u0628\u0646 \u0627\u0644\u0644\u0647. \u0648\u0623\u0634\u0631\u0643 \u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0628\u0627\u0644\u0644\u0647 \u0639\u0646\u062f\u0645\u0627 \u0627\u062f\u0651\u064e\u0639\u0648\u0627 \u0623\u0646 \u0627\u0644\u0645\u0633\u064a\u062d \u0627\u0628\u0646 \u0627\u0644\u0644\u0647. \u0648\u0647\u0630\u0627 \u0627\u0644\u0642\u0648\u0644 \u0627\u062e\u062a\u0644\u0642\u0648\u0647 \u0645\u0646 \u0639\u0646\u062f \u0623\u0646\u0641\u0633\u0647\u0645\u060c \u0648\u0647\u0645 \u0628\u0630\u0644\u0643 \u064a\u0634\u0627\u0628\u0647\u0648\u0646 \u0642\u0648\u0644 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0645\u0646 \u0642\u0628\u0644\u0647\u0645. \u0642\u064e\u0627\u062a\u064e\u0644\u064e \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u062c\u0645\u064a\u0639\u064b\u0627 \u0643\u064a\u0641 \u064a\u0639\u062f\u0644\u0648\u0646 \u0639\u0646 \u0627\u0644\u062d\u0642 \u0625\u0644\u0649 \u0627\u0644\u0628\u0627\u0637\u0644\u061f","9:31":"\u0627\u062a\u062e\u0630 \u0627\u0644\u064a\u0647\u0648\u062f\u064f \u0648\u0627\u0644\u0646\u0635\u0627\u0631\u0649 \u0627\u0644\u0639\u0644\u0645\u0627\u0621\u064e \u0648\u0627\u0644\u0639\u064f\u0628\u0651\u064e\u0627\u062f\u064e \u0623\u0631\u0628\u0627\u0628\u064b\u0627 \u064a\u064f\u0634\u064e\u0631\u0651\u0650\u0639\u0648\u0646 \u0644\u0647\u0645 \u0627\u0644\u0623\u062d\u0643\u0627\u0645\u060c \u0641\u064a\u0644\u062a\u0632\u0645\u0648\u0646 \u0628\u0647\u0627 \u0648\u064a\u062a\u0631\u0643\u0648\u0646 \u0634\u0631\u0627\u0626\u0639 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u062a\u062e\u0630\u0648\u0627 \u0627\u0644\u0645\u0633\u064a\u062d \u0639\u064a\u0633\u0649 \u0627\u0628\u0646 \u0645\u0631\u064a\u0645 \u0625\u0644\u0647\u064b\u0627 \u0641\u0639\u0628\u062f\u0648\u0647\u060c \u0648\u0642\u062f \u0623\u0645\u0631\u0647\u0645 \u0627\u0644\u0644\u0647 \u0628\u0639\u0628\u0627\u062f\u062a\u0647 \u0648\u062d\u062f\u0647 \u062f\u0648\u0646 \u063a\u064a\u0631\u0647\u060c \u0641\u0647\u0648 \u0627\u0644\u0625\u0644\u0647 \u0627\u0644\u062d\u0642 \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0647\u0648. \u062a\u0646\u0632\u0651\u064e\u0647 \u0648\u062a\u0642\u062f\u0651\u064e\u0633 \u0639\u0645\u0627 \u064a\u0641\u062a\u0631\u064a\u0647 \u0623\u0647\u0644 \u0627\u0644\u0634\u0631\u0643 \u0648\u0627\u0644\u0636\u0644\u0627\u0644.","9:32":"\u064a\u0631\u064a\u062f \u0627\u0644\u0643\u0641\u0627\u0631 \u0628\u062a\u0643\u0630\u064a\u0628\u0647\u0645 \u0623\u0646 \u064a\u0628\u0637\u0644\u0648\u0627 \u062f\u064a\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u064a\u0628\u0637\u0644\u0648\u0627 \u062d\u062c\u062c \u0627\u0644\u0644\u0647 \u0648\u0628\u0631\u0627\u0647\u064a\u0646\u0647 \u0639\u0644\u0649 \u062a\u0648\u062d\u064a\u062f\u0647 \u0627\u0644\u0630\u064a \u062c\u0627\u0621 \u0628\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u064a\u0623\u0628\u0649 \u0627\u0644\u0644\u0647 \u0625\u0644\u0627 \u0623\u0646 \u064a\u062a\u0645 \u062f\u064a\u0646\u0647 \u0648\u064a\u0638\u0647\u0631\u0647\u060c \u0648\u064a\u0639\u0644\u064a \u0643\u0644\u0645\u062a\u0647\u060c \u0648\u0644\u0648 \u0643\u0631\u0647 \u0630\u0644\u0643 \u0627\u0644\u062c\u0627\u062d\u062f\u0648\u0646.","9:33":"\u0647\u0648 \u0627\u0644\u0630\u064a \u0623\u0631\u0633\u0644 \u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f\u064b\u0627 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0628\u0627\u0644\u0642\u0631\u0622\u0646 \u0648\u062f\u064a\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645; \u0644\u064a\u0639\u0644\u064a\u0647 \u0639\u0644\u0649 \u0627\u0644\u0623\u062f\u064a\u0627\u0646 \u0643\u0644\u0647\u0627\u060c \u0648\u0644\u0648 \u0643\u0631\u0647 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u062f\u064a\u0646 \u0627\u0644\u062d\u0642 -\u0627\u0644\u0625\u0633\u0644\u0627\u0645- \u0648\u0638\u0647\u0648\u0631\u0647 \u0639\u0644\u0649 \u0627\u0644\u0623\u062f\u064a\u0627\u0646.","9:34":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u064e\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0625\u0646 \u0643\u062b\u064a\u0631\u064b\u0627 \u0645\u0646 \u0639\u0644\u0645\u0627\u0621 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0648\u0639\u064f\u0628\u0651\u064e\u0627\u062f\u0647\u0645 \u0644\u064a\u0623\u062e\u0630\u0648\u0646 \u0623\u0645\u0648\u0627\u0644 \u0627\u0644\u0646\u0627\u0633 \u0628\u063a\u064a\u0631 \u062d\u0642 \u0643\u0627\u0644\u0631\u0634\u0648\u0629 \u0648\u063a\u064a\u0631\u0647\u0627\u060c \u0648\u064a\u0645\u0646\u0639\u0648\u0646 \u0627\u0644\u0646\u0627\u0633 \u0645\u0646 \u0627\u0644\u062f\u062e\u0648\u0644 \u0641\u064a \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u064a\u0635\u062f\u0648\u0646 \u0639\u0646 \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647. \u0648\u0627\u0644\u0630\u064a\u0646 \u064a\u0645\u0633\u0643\u0648\u0646 \u0627\u0644\u0623\u0645\u0648\u0627\u0644\u060c \u0648\u0644\u0627 \u064a\u0624\u062f\u0648\u0646 \u0632\u0643\u0627\u062a\u0647\u0627\u060c \u0648\u0644\u0627 \u064a\u064f\u062e\u0652\u0631\u062c\u0648\u0646 \u0645\u0646\u0647\u0627 \u0627\u0644\u062d\u0642\u0648\u0642 \u0627\u0644\u0648\u0627\u062c\u0628\u0629\u060c \u0641\u0628\u0634\u0651\u0650\u0631\u0647\u0645 \u0628\u0639\u0630\u0627\u0628 \u0645\u0648\u062c\u0639.","9:35":"\u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u062a\u0648\u0636\u0639 \u0642\u0637\u0639 \u0627\u0644\u0630\u0647\u0628 \u0648\u0627\u0644\u0641\u0636\u0629 \u0641\u064a \u0627\u0644\u0646\u0627\u0631\u060c \u0641\u0625\u0630\u0627 \u0627\u0634\u062a\u062f\u062a \u062d\u0631\u0627\u0631\u062a\u0647\u0627 \u0623\u064f\u062d\u0631\u0642\u062a \u0628\u0647\u0627 \u062c\u0628\u0627\u0647 \u0623\u0635\u062d\u0627\u0628\u0647\u0627 \u0648\u062c\u0646\u0648\u0628\u0647\u0645 \u0648\u0638\u0647\u0648\u0631\u0647\u0645. \u0648\u0642\u064a\u0644 \u0644\u0647\u0645 \u062a\u0648\u0628\u064a\u062e\u064b\u0627: \u0647\u0630\u0627 \u0645\u0627\u0644\u0643\u0645 \u0627\u0644\u0630\u064a \u0623\u0645\u0633\u0643\u062a\u0645\u0648\u0647 \u0648\u0645\u0646\u0639\u062a\u0645 \u0645\u0646\u0647 \u062d\u0642\u0648\u0642 \u0627\u0644\u0644\u0647\u060c \u0641\u0630\u0648\u0642\u0648\u0627 \u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0645\u0648\u062c\u0639; \u0628\u0633\u0628\u0628 \u0643\u0646\u0632\u0643\u0645 \u0648\u0625\u0645\u0633\u0627\u0643\u0643\u0645.","9:36":"\u0625\u0646\u0651 \u0639\u062f\u0629 \u0627\u0644\u0634\u0647\u0648\u0631 \u0641\u064a \u062d\u0643\u0645 \u0627\u0644\u0644\u0647 \u0648\u0641\u064a\u0645\u0627 \u0643\u064f\u062a\u0628 \u0641\u064a \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u0645\u062d\u0641\u0648\u0638 \u0627\u062b\u0646\u0627 \u0639\u0634\u0631 \u0634\u0647\u0631\u064b\u0627\u060c \u064a\u0648\u0645 \u062e\u0644\u0642 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0646\u0647\u0627 \u0623\u0631\u0628\u0639\u0629 \u062d\u064f\u0631\u064f\u0645; \u062d\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647 \u0641\u064a\u0647\u0646\u0651\u064e \u0627\u0644\u0642\u062a\u0627\u0644 (\u0647\u064a: \u0630\u0648 \u0627\u0644\u0642\u0639\u062f\u0629 \u0648\u0630\u0648 \u0627\u0644\u062d\u062c\u0629 \u0648\u0627\u0644\u0645\u062d\u0631\u0645 \u0648\u0631\u062c\u0628) \u0630\u0644\u0643 \u0647\u0648 \u0627\u0644\u062f\u064a\u0646 \u0627\u0644\u0645\u0633\u062a\u0642\u064a\u0645\u060c \u0641\u0644\u0627 \u062a\u0638\u0644\u0645\u0648\u0627 \u0641\u064a\u0647\u0646 \u0623\u0646\u0641\u0633\u0643\u0645; \u0644\u0632\u064a\u0627\u062f\u0629 \u062a\u062d\u0631\u064a\u0645\u0647\u0627\u060c \u0648\u0643\u0648\u0646 \u0627\u0644\u0638\u0644\u0645 \u0641\u064a\u0647\u0627 \u0623\u0634\u062f \u0645\u0646\u0647 \u0641\u064a \u063a\u064a\u0631\u0647\u0627\u060c \u0644\u0627 \u0623\u0646\u0651\u064e \u0627\u0644\u0638\u0644\u0645 \u0641\u064a \u063a\u064a\u0631\u0647\u0627 \u062c\u0627\u0626\u0632. \u0648\u0642\u0627\u062a\u0644\u0648\u0627 \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u062c\u0645\u064a\u0639\u064b\u0627 \u0643\u0645\u0627 \u064a\u0642\u0627\u062a\u0644\u0648\u0646\u0643\u0645 \u062c\u0645\u064a\u0639\u064b\u0627\u060c \u0648\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0645\u0639 \u0623\u0647\u0644 \u0627\u0644\u062a\u0642\u0648\u0649 \u0628\u062a\u0623\u064a\u064a\u062f\u0647 \u0648\u0646\u0635\u0631\u0647.","9:37":"\u0625\u0646 \u0627\u0644\u0630\u064a \u0643\u0627\u0646\u062a \u062a\u0641\u0639\u0644\u0647 \u0627\u0644\u0639\u0631\u0628 \u0641\u064a \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629 \u0645\u0646 \u062a\u062d\u0631\u064a\u0645 \u0623\u0631\u0628\u0639\u0629 \u0623\u0634\u0647\u0631 \u0645\u0646 \u0627\u0644\u0633\u0646\u0629 \u0639\u062f\u062f\u064b\u0627 \u0644\u0627 \u062a\u062d\u062f\u064a\u062f\u064b\u0627 \u0628\u0623\u0633\u0645\u0627\u0621 \u0627\u0644\u0623\u0634\u0647\u0631 \u0627\u0644\u062a\u064a \u062d\u0631\u0651\u064e\u0645\u0647\u0627 \u0627\u0644\u0644\u0647\u060c \u0641\u064a\u0624\u062e\u0631\u0648\u0646 \u0628\u0639\u0636\u0647\u0627 \u0623\u0648 \u064a\u0642\u062f\u0651\u0650\u0645\u0648\u0646\u0647 \u0648\u064a\u062c\u0639\u0644\u0648\u0646 \u0645\u0643\u0627\u0646\u0647 \u0645\u0646 \u0623\u0634\u0647\u0631 \u0627\u0644\u062d\u0644 \u0645\u0627 \u0623\u0631\u0627\u062f\u0648\u0627 \u062d\u0633\u0628 \u062d\u0627\u062c\u062a\u0647\u0645 \u0644\u0644\u0642\u062a\u0627\u0644\u060c \u0625\u0646 \u0630\u0644\u0643 \u0632\u064a\u0627\u062f\u0629 \u0641\u064a \u0627\u0644\u0643\u0641\u0631\u060c \u064a\u0636\u0644 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0628\u0647 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627\u060c \u064a\u062d\u0644\u0648\u0646 \u0627\u0644\u0630\u064a \u0623\u062e\u0631\u0648\u0627 \u062a\u062d\u0631\u064a\u0645\u0647 \u0645\u0646 \u0627\u0644\u0623\u0634\u0647\u0631 \u0627\u0644\u0623\u0631\u0628\u0639\u0629 \u0639\u0627\u0645\u064b\u0627\u060c \u0648\u064a\u062d\u0631\u0645\u0648\u0646\u0647 \u0639\u0627\u0645\u0627; \u0644\u064a\u0648\u0627\u0641\u0642\u0648\u0627 \u0639\u062f\u062f \u0627\u0644\u0634\u0647\u0648\u0631 \u0627\u0644\u0623\u0631\u0628\u0639\u0629\u060c \u0641\u064a\u062d\u0644\u0648\u0627 \u0645\u0627 \u062d\u0631\u0651\u064e\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646\u0647\u0627. \u0632\u064e\u064a\u0651\u064e\u0646 \u0644\u0647\u0645 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0633\u064a\u0626\u0629. \u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0648\u0641\u0642 \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062d\u0642 \u0648\u0627\u0644\u0635\u0648\u0627\u0628.","9:38":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0645\u0627 \u0628\u0627\u0644\u0643\u0645 \u0625\u0630\u0627 \u0642\u064a\u0644 \u0644\u0643\u0645: \u0627\u062e\u0631\u062c\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u062f \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0644\u0642\u062a\u0627\u0644 \u0623\u0639\u062f\u0627\u0626\u0643\u0645 \u062a\u0643\u0627\u0633\u0644\u062a\u0645 \u0648\u0644\u0632\u0645\u062a\u0645 \u0645\u0633\u0627\u0643\u0646\u0643\u0645\u061f \u0647\u0644 \u0622\u062b\u0631\u062a\u0645 \u062d\u0638\u0648\u0638\u0643\u0645 \u0627\u0644\u062f\u0646\u064a\u0648\u064a\u0629 \u0639\u0644\u0649 \u0646\u0639\u064a\u0645 \u0627\u0644\u0622\u062e\u0631\u0629\u061f \u0641\u0645\u0627 \u062a\u0633\u062a\u0645\u062a\u0639\u0648\u0646 \u0628\u0647 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0642\u0644\u064a\u0644 \u0632\u0627\u0626\u0644\u060c \u0623\u0645\u0627 \u0646\u0639\u064a\u0645 \u0627\u0644\u0622\u062e\u0631\u0629 \u0627\u0644\u0630\u064a \u0623\u0639\u062f\u0647 \u0627\u0644\u0644\u0647 \u0644\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0627\u0644\u0645\u062c\u0627\u0647\u062f\u064a\u0646 \u0641\u0643\u062b\u064a\u0631 \u062f\u0627\u0626\u0645.","9:39":"\u0625\u0646 \u0644\u0627 \u062a\u0646\u0641\u0631\u0648\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0625\u0644\u0649 \u0642\u062a\u0627\u0644 \u0639\u062f\u0648\u0643\u0645 \u064a\u0646\u0632\u0644\u0650 \u0627\u0644\u0644\u0647 \u0639\u0642\u0648\u0628\u062a\u0647 \u0628\u0643\u0645\u060c \u0648\u064a\u0623\u062a \u0628\u0642\u0648\u0645 \u0622\u062e\u0631\u064a\u0646 \u064a\u0646\u0641\u0631\u0648\u0646 \u0625\u0630\u0627 \u0627\u0633\u062a\u064f\u0646\u0652\u0641\u0631\u0648\u0627\u060c \u0648\u064a\u0637\u064a\u0639\u0648\u0646 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0644\u0646 \u062a\u0636\u0631\u0648\u0627 \u0627\u0644\u0644\u0647 \u0634\u064a\u0626\u064b\u0627 \u0628\u062a\u0648\u0644\u0651\u0650\u064a\u0643\u0645 \u0639\u0646 \u0627\u0644\u062c\u0647\u0627\u062f\u060c \u0641\u0647\u0648 \u0627\u0644\u063a\u0646\u064a \u0639\u0646\u0643\u0645 \u0648\u0623\u0646\u062a\u0645 \u0627\u0644\u0641\u0642\u0631\u0627\u0621 \u0625\u0644\u064a\u0647. \u0648\u0645\u0627 \u064a\u0631\u064a\u062f\u0647 \u0627\u0644\u0644\u0647 \u064a\u0643\u0648\u0646 \u0644\u0627 \u0645\u062d\u0627\u0644\u0629. \u0648\u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0643\u0644 \u0634\u064a\u0621 \u0642\u062f\u064a\u0631 \u0645\u0646 \u0646\u0635\u0631 \u062f\u064a\u0646\u0647 \u0648\u0646\u0628\u064a\u0647 \u062f\u0648\u0646\u0643\u0645.","9:40":"\u064a\u0627 \u0645\u0639\u0634\u0631 \u0623\u0635\u062d\u0627\u0628 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0625\u0646 \u0644\u0627 \u062a\u0646\u0641\u0631\u0648\u0627 \u0645\u0639\u0647 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0625\u0630\u0627 \u0627\u0633\u062a\u064e\u0646\u0652\u0641\u064e\u0631\u0643\u0645\u060c \u0648\u0625\u0646 \u0644\u0627 \u062a\u0646\u0635\u0631\u0648\u0647; \u0641\u0642\u062f \u0623\u064a\u062f\u0647 \u0627\u0644\u0644\u0647 \u0648\u0646\u0635\u0631\u0647 \u064a\u0648\u0645 \u0623\u062e\u0631\u062c\u0647 \u0627\u0644\u0643\u0641\u0627\u0631 \u0645\u0646 \u0642\u0631\u064a\u0634 \u0645\u0646 \u0628\u0644\u062f\u0647 (\u0645\u0643\u0629) \u060c \u0648\u0647\u0648 \u062b\u0627\u0646\u064a \u0627\u062b\u0646\u064a\u0646 (\u0647\u0648 \u0648\u0623\u0628\u0648 \u0628\u0643\u0631 \u0627\u0644\u0635\u062f\u064a\u0642 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647) \u0648\u0623\u0644\u062c\u0624\u0648\u0647\u0645\u0627 \u0625\u0644\u0649 \u0646\u0642\u0628 \u0641\u064a \u062c\u0628\u0644 \u062b\u0648\u0631 \u0628\u0640 \xab\u0645\u0643\u0629\xbb \u060c \u0641\u0645\u0643\u062b\u0627 \u0641\u064a\u0647 \u062b\u0644\u0627\u062b \u0644\u064a\u0627\u0644\u060c \u0625\u0630 \u064a\u0642\u0648\u0644 \u0644\u0635\u0627\u062d\u0628\u0647 (\u0623\u0628\u064a \u0628\u0643\u0631) \u0644\u0645\u0627 \u0631\u0623\u0649 \u0645\u0646\u0647 \u0627\u0644\u062e\u0648\u0641 \u0639\u0644\u064a\u0647: \u0644\u0627 \u062a\u062d\u0632\u0646 \u0625\u0646 \u0627\u0644\u0644\u0647 \u0645\u0639\u0646\u0627 \u0628\u0646\u0635\u0631\u0647 \u0648\u062a\u0623\u064a\u064a\u062f\u0647\u060c \u0641\u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0627\u0644\u0637\u0645\u0623\u0646\u064a\u0646\u0629 \u0641\u064a \u0642\u0644\u0628 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0623\u0639\u0627\u0646\u0647 \u0628\u062c\u0646\u0648\u062f \u0644\u0645 \u064a\u0631\u0647\u0627 \u0623\u062d\u062f \u0645\u0646 \u0627\u0644\u0628\u0634\u0631 \u0648\u0647\u0645 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u0629\u060c \u0641\u0623\u0646\u062c\u0627\u0647 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0639\u062f\u0648\u0647 \u0648\u0623\u0630\u0644 \u0627\u0644\u0644\u0647 \u0623\u0639\u062f\u0627\u0621\u0647\u060c \u0648\u062c\u0639\u0644 \u0643\u0644\u0645\u0629 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0627\u0644\u0633\u0641\u0644\u0649. \u0648\u0643\u0644\u0645\u0629\u064f \u0627\u0644\u0644\u0647 \u0647\u064a \u0627\u0644\u0639\u0644\u064a\u0627\u060c \u0648\u0630\u0644\u0643 \u0628\u0625\u0639\u0644\u0627\u0621 \u0634\u0623\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645. \u0648\u0627\u0644\u0644\u0647 \u0639\u0632\u064a\u0632 \u0641\u064a \u0645\u0644\u0643\u0647\u060c \u062d\u0643\u064a\u0645 \u0641\u064a \u062a\u062f\u0628\u064a\u0631 \u0634\u0624\u0648\u0646 \u0639\u0628\u0627\u062f\u0647. \u0648\u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629 \u0645\u0646\u0642\u0628\u0629 \u0639\u0638\u064a\u0645\u0629 \u0644\u0623\u0628\u064a \u0628\u0643\u0631 \u0627\u0644\u0635\u062f\u064a\u0642 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647.","9:41":"\u0627\u062e\u0631\u062c\u0648\u0627 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0644\u0644\u062c\u0647\u0627\u062f \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0634\u0628\u0627\u0628\u064b\u0627 \u0648\u0634\u064a\u0648\u062e\u064b\u0627 \u0641\u064a \u0627\u0644\u0639\u0633\u0631 \u0648\u0627\u0644\u064a\u0633\u0631\u060c \u0639\u0644\u0649 \u0623\u064a \u062d\u0627\u0644 \u0643\u0646\u062a\u0645\u060c \u0648\u0623\u0646\u0641\u0642\u0648\u0627 \u0623\u0645\u0648\u0627\u0644\u0643\u0645 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u0642\u0627\u062a\u0644\u0648\u0627 \u0628\u0623\u064a\u062f\u064a\u0643\u0645 \u0644\u0625\u0639\u0644\u0627\u0621 \u0643\u0644\u0645\u0629 \u0627\u0644\u0644\u0647\u060c \u0630\u0644\u0643 \u0627\u0644\u062e\u0631\u0648\u062c \u0648\u0627\u0644\u0628\u0630\u0644 \u062e\u064a\u0631 \u0644\u0643\u0645 \u0641\u064a \u062d\u0627\u0644\u0643\u0645 \u0648\u0645\u0622\u0644\u0643\u0645 \u0645\u0646 \u0627\u0644\u062a\u062b\u0627\u0642\u0644 \u0648\u0627\u0644\u0625\u0645\u0633\u0627\u0643 \u0648\u0627\u0644\u062a\u062e\u0644\u0641\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0639\u0644\u0645 \u0628\u0641\u0636\u0644 \u0627\u0644\u062c\u0647\u0627\u062f \u0648\u0627\u0644\u062b\u0648\u0627\u0628 \u0639\u0646\u062f \u0627\u0644\u0644\u0647 \u0641\u0627\u0641\u0639\u0644\u0648\u0627 \u0645\u0627 \u0623\u064f\u0645\u0631\u062a\u0645 \u0628\u0647\u060c \u0648\u0627\u0633\u062a\u062c\u064a\u0628\u0648\u0627 \u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647.","9:42":"\u0648\u0628\u0651\u064e\u062e \u0627\u0644\u0644\u0647 \u062c\u0644\u0651\u064e \u062c\u0644\u0627\u0644\u0647 \u062c\u0645\u0627\u0639\u0629 \u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0627\u0633\u062a\u0623\u0630\u0646\u0648\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0641\u064a \u0627\u0644\u062a\u062e\u0644\u0641 \u0639\u0646 \u063a\u0632\u0648\u0629 (\u062a\u0628\u0648\u0643) \u0645\u0628\u064a\u0646\u064b\u0627 \u0623\u0646\u0647 \u0644\u0648 \u0643\u0627\u0646 \u062e\u0631\u0648\u062c\u0647\u0645 \u0625\u0644\u0649 \u063a\u0646\u064a\u0645\u0629 \u0642\u0631\u064a\u0628\u0629 \u0633\u0647\u0644\u0629 \u0627\u0644\u0645\u0646\u0627\u0644 \u0644\u0627\u062a\u0628\u0639\u0648\u0643\u060c \u0648\u0644\u0643\u0646 \u0644\u0645\u0627 \u062f\u0639\u0648\u0627 \u0625\u0644\u0649 \u0642\u062a\u0627\u0644 \u0627\u0644\u0631\u0648\u0645 \u0641\u064a \u0623\u0637\u0631\u0627\u0641 \u0628\u0644\u0627\u062f (\u0627\u0644\u0634\u0627\u0645) \u0641\u064a \u0648\u0642\u062a \u0627\u0644\u062d\u0631 \u062a\u062e\u0627\u0630\u0644\u0648\u0627\u060c \u0648\u062a\u062e\u0644\u0641\u0648\u0627\u060c \u0648\u0633\u064a\u0639\u062a\u0630\u0631\u0648\u0646 \u0644\u062a\u062e\u0644\u0641\u0647\u0645 \u0639\u0646 \u0627\u0644\u062e\u0631\u0648\u062c \u062d\u0627\u0644\u0641\u064a\u0646 \u0628\u0623\u0646\u0647\u0645 \u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639\u0648\u0646 \u0630\u0644\u0643\u060c \u064a\u0647\u0644\u0643\u0648\u0646 \u0623\u0646\u0641\u0633\u0647\u0645 \u0628\u0627\u0644\u0643\u0630\u0628 \u0648\u0627\u0644\u0646\u0641\u0627\u0642\u060c \u0648\u0627\u0644\u0644\u0647 \u064a\u0639\u0644\u0645 \u0625\u0646\u0647\u0645 \u0644\u0643\u0627\u0630\u0628\u0648\u0646 \u0641\u064a\u0645\u0627 \u064a\u0628\u062f\u0648\u0646 \u0644\u0643 \u0645\u0646 \u0627\u0644\u0623\u0639\u0630\u0627\u0631.","9:43":"\u0639\u0641\u0627 \u0627\u0644\u0644\u0647 \u0639\u0646\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0639\u0645\u0651\u064e\u0627 \u0648\u0642\u0639 \u0645\u0646\u0643 \u0645\u0650\u0646 \u062a\u064e\u0631\u0652\u0643 \u0627\u0644\u0623\u0648\u0644\u0649 \u0648\u0627\u0644\u0623\u0643\u0645\u0644\u060c \u0648\u0647\u0648 \u0625\u0630\u0646\u0643 \u0644\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0641\u064a \u0627\u0644\u0642\u0639\u0648\u062f \u0639\u0646 \u0627\u0644\u062c\u0647\u0627\u062f\u060c \u0644\u0623\u064a \u0633\u0628\u0628 \u0623\u064e\u0630\u0650\u0646\u0652\u062a\u064e \u0644\u0647\u0624\u0644\u0627\u0621 \u0628\u0627\u0644\u062a\u062e\u0644\u0641 \u0639\u0646 \u0627\u0644\u063a\u0632\u0648\u0629\u060c \u062d\u062a\u0649 \u064a\u0638\u0647\u0631 \u0644\u0643 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0642\u0648\u0627 \u0641\u064a \u0627\u0639\u062a\u0630\u0627\u0631\u0647\u0645 \u0648\u062a\u0639\u0644\u0645 \u0627\u0644\u0643\u0627\u0630\u0628\u064a\u0646 \u0645\u0646\u0647\u0645 \u0641\u064a \u0630\u0644\u0643\u061f","9:44":"\u0644\u064a\u0633 \u0645\u0646 \u0634\u0623\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631 \u0623\u0646 \u064a\u0633\u062a\u0623\u0630\u0646\u0648\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0641\u064a \u0627\u0644\u062a\u062e\u0644\u0641 \u0639\u0646 \u0627\u0644\u062c\u0647\u0627\u062f \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u0646\u0641\u0633 \u0648\u0627\u0644\u0645\u0627\u0644\u060c \u0648\u0625\u0646\u0645\u0627 \u0647\u0630\u0627 \u0645\u0646 \u0634\u0623\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646. \u0648\u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645 \u0628\u0645\u0646 \u062e\u0627\u0641\u0647 \u0641\u0627\u062a\u0642\u0627\u0647 \u0628\u0623\u062f\u0627\u0621 \u0641\u0631\u0627\u0626\u0636\u0647 \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0646\u0648\u0627\u0647\u064a\u0647.","9:45":"\u0625\u0646\u0645\u0627 \u064a\u0637\u0644\u0628 \u0627\u0644\u0625\u0630\u0646 \u0644\u0644\u062a\u062e\u0644\u0641 \u0639\u0646 \u0627\u0644\u062c\u0647\u0627\u062f \u0627\u0644\u0630\u064a\u0646 \u0644\u0627 \u064a\u0635\u062f\u0651\u0650\u0642\u0648\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0644\u0627 \u0628\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631\u060c \u0648\u0644\u0627 \u064a\u0639\u0645\u0644\u0648\u0646 \u0635\u0627\u0644\u062d\u064b\u0627\u060c \u0648\u0634\u0643\u0651\u064e\u062a\u0652 \u0642\u0644\u0648\u0628\u0647\u0645 \u0641\u064a \u0635\u062d\u0629 \u0645\u0627 \u062c\u0626\u062a \u0628\u0647 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0645\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u0634\u0631\u0627\u0626\u0639\u0647\u060c \u0641\u0647\u0645 \u0641\u064a \u0634\u0643\u0647\u0645 \u064a\u062a\u062d\u064a\u0651\u064e\u0631\u0648\u0646.","9:46":"\u0648\u0644\u0648 \u0623\u0631\u0627\u062f \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0627\u0644\u062e\u0631\u0648\u062c \u0645\u0639\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0625\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u062f \u0644\u062a\u0623\u0647\u0651\u064e\u0628\u0648\u0627 \u0644\u0647 \u0628\u0627\u0644\u0632\u0627\u062f \u0648\u0627\u0644\u0631\u0627\u062d\u0644\u0629\u060c \u0648\u0644\u0643\u0646 \u0627\u0644\u0644\u0647 \u0643\u0631\u0647 \u062e\u0631\u0648\u062c\u0647\u0645 \u0641\u062b\u064e\u0642\u064f\u0644\u064e \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u062e\u0631\u0648\u062c \u0642\u0636\u0627\u0621 \u0648\u0642\u062f\u0631\u064b\u0627\u060c \u0648\u0625\u0646 \u0643\u0627\u0646 \u0623\u0645\u0631\u0647\u0645 \u0628\u0647 \u0634\u0631\u0639\u0627\u060c \u0648\u0642\u064a\u0644 \u0644\u0647\u0645: \u062a\u062e\u0644\u0641\u0648\u0627 \u0645\u0639 \u0627\u0644\u0642\u0627\u0639\u062f\u064a\u0646 \u0645\u0646 \u0627\u0644\u0645\u0631\u0636\u0649 \u0648\u0627\u0644\u0636\u0639\u0641\u0627\u0621 \u0648\u0627\u0644\u0646\u0633\u0627\u0621 \u0648\u0627\u0644\u0635\u0628\u064a\u0627\u0646.","9:47":"\u0644\u0648 \u062e\u0631\u062c \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0645\u0639\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0644\u0644\u062c\u0647\u0627\u062f \u0644\u0646\u0634\u0631\u0648\u0627 \u0627\u0644\u0627\u0636\u0637\u0631\u0627\u0628 \u0641\u064a \u0627\u0644\u0635\u0641\u0648\u0641 \u0648\u0627\u0644\u0634\u0631 \u0648\u0627\u0644\u0641\u0633\u0627\u062f\u060c \u0648\u0644\u0623\u0633\u0631\u0639\u0648\u0627 \u0627\u0644\u0633\u064a\u0631 \u0628\u064a\u0646\u0643\u0645 \u0628\u0627\u0644\u0646\u0645\u064a\u0645\u0629 \u0648\u0627\u0644\u0628\u063a\u0636\u0627\u0621\u060c \u064a\u0628\u063a\u0648\u0646 \u0641\u062a\u0646\u062a\u0643\u0645 \u0628\u062a\u062b\u0628\u064a\u0637\u0643\u0645 \u0639\u0646 \u0627\u0644\u062c\u0647\u0627\u062f \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u0641\u064a\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0639\u064a\u0648\u0646 \u0644\u0647\u0645 \u064a\u0633\u0645\u0639\u0648\u0646 \u0623\u062e\u0628\u0627\u0631\u0643\u0645\u060c \u0648\u064a\u0646\u0642\u0644\u0648\u0646\u0647\u0627 \u0625\u0644\u064a\u0647\u0645. \u0648\u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645 \u0628\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a\u0647\u0645 \u0639\u0644\u0649 \u0630\u0644\u0643.","9:48":"\u0644\u0642\u062f \u0627\u0628\u062a\u063a\u0649 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0641\u062a\u0646\u0629 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0639\u0646 \u062f\u064a\u0646\u0647\u0645 \u0648\u0635\u062f\u0647\u0645 \u0639\u0646 \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0642\u0628\u0644 \u063a\u0632\u0648\u0629 (\u062a\u0628\u0648\u0643) \u060c \u0648\u0643\u0634\u0641 \u0623\u0645\u0631\u0647\u0645\u060c \u0648\u0635\u0631\u0651\u064e\u0641\u0648\u0627 \u0644\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0627\u0644\u0623\u0645\u0648\u0631 \u0641\u064a \u0625\u0628\u0637\u0627\u0644 \u0645\u0627 \u062c\u0626\u062a \u0628\u0647\u060c \u0643\u0645\u0627 \u0641\u0639\u0644\u0648\u0627 \u064a\u0648\u0645 (\u0623\u062d\u062f) \u0648\u064a\u0648\u0645 (\u0627\u0644\u062e\u0646\u062f\u0642) \u060c \u0648\u062f\u0628\u0651\u064e\u0631\u0648\u0627 \u0644\u0643 \u0627\u0644\u0643\u064a\u062f \u062d\u062a\u0649 \u062c\u0627\u0621 \u0627\u0644\u0646\u0635\u0631 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0648\u0623\u0639\u0632 \u062c\u0646\u062f\u0647 \u0648\u0646\u0635\u0631 \u062f\u064a\u0646\u0647\u060c \u0648\u0647\u0645 \u0643\u0627\u0631\u0647\u0648\u0646 \u0644\u0647.","9:49":"\u0648\u0645\u0650\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0645\u0646 \u064a\u0637\u0644\u0628 \u0627\u0644\u0625\u0630\u0646 \u0644\u0644\u0642\u0639\u0648\u062f \u0639\u0646 \u0627\u0644\u062c\u0647\u0627\u062f \u0648\u064a\u0642\u0648\u0644: \u0644\u0627 \u062a\u0648\u0642\u0639\u0652\u0646\u064a \u0641\u064a \u0627\u0644\u0627\u0628\u062a\u0644\u0627\u0621 \u0628\u0645\u0627 \u064a\u0639\u0631\u0636 \u0644\u064a \u0641\u064a \u062d\u0627\u0644\u0629 \u0627\u0644\u062e\u0631\u0648\u062c \u0645\u0646 \u0641\u062a\u0646\u0629 \u0627\u0644\u0646\u0633\u0627\u0621. \u0644\u0642\u062f \u0633\u0642\u0637 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0641\u064a \u0641\u062a\u0646\u0629 \u0627\u0644\u0646\u0641\u0627\u0642 \u0627\u0644\u0643\u0628\u0631\u0649. \u0641\u0625\u0646 \u062c\u0647\u0646\u0645 \u0644\u0645\u062d\u064a\u0637\u0629 \u0628\u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u0622\u062e\u0631\u060c \u0641\u0644\u0627 \u064a\u064f\u0641\u0652\u0644\u0650\u062a \u0645\u0646\u0647\u0645 \u0623\u062d\u062f.","9:50":"\u0625\u0646 \u064a\u0635\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0633\u0631\u0648\u0631 \u0648\u063a\u0646\u064a\u0645\u0629 \u064a\u062d\u0632\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646\u060c \u0648\u0625\u0646 \u064a\u0644\u062d\u0642 \u0628\u0643 \u0645\u0643\u0631\u0648\u0647 \u0645\u0646 \u0647\u0632\u064a\u0645\u0629 \u0623\u0648 \u0634\u062f\u0629 \u064a\u0642\u0648\u0644\u0648\u0627: \u0646\u062d\u0646 \u0623\u0635\u062d\u0627\u0628 \u0631\u0623\u064a \u0648\u062a\u062f\u0628\u064a\u0631 \u0642\u062f \u0627\u062d\u062a\u0637\u0646\u0627 \u0644\u0623\u0646\u0641\u0633\u0646\u0627 \u0628\u062a\u062e\u0644\u0641\u0646\u0627 \u0639\u0646 \u0645\u062d\u0645\u062f\u060c \u0648\u064a\u0646\u0635\u0631\u0641\u0648\u0627 \u0648\u0647\u0645 \u0645\u0633\u0631\u0648\u0631\u0648\u0646 \u0628\u0645\u0627 \u0635\u0646\u0639\u0648\u0627 \u0648\u0628\u0645\u0627 \u0623\u0635\u0627\u0628\u0643 \u0645\u0646 \u0627\u0644\u0633\u0648\u0621.","9:51":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u062a\u062e\u0627\u0630\u0644\u064a\u0646 \u0632\u062c\u0631\u064b\u0627 \u0644\u0647\u0645 \u0648\u062a\u0648\u0628\u064a\u062e\u064b\u0627: \u0644\u0646 \u064a\u0635\u064a\u0628\u0646\u0627 \u0625\u0644\u0627 \u0645\u0627 \u0642\u062f\u0651\u064e\u0631\u0647 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0646\u0627 \u0648\u0643\u062a\u0628\u0647 \u0641\u064a \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u0645\u062d\u0641\u0648\u0638\u060c \u0647\u0648 \u0646\u0627\u0635\u0631\u0646\u0627 \u0639\u0644\u0649 \u0623\u0639\u062f\u0627\u0626\u0646\u0627\u060c \u0648\u0639\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u0648\u062d\u062f\u0647 \u0641\u0644\u064a\u0639\u062a\u0645\u062f \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0628\u0647.","9:52":"\u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a-: \u0647\u0644 \u062a\u0646\u062a\u0638\u0631\u0648\u0646 \u0628\u0646\u0627 \u0625\u0644\u0627 \u0634\u0647\u0627\u062f\u0629 \u0623\u0648 \u0638\u0641\u0631\u064b\u0627 \u0628\u0643\u0645\u061f \u0648\u0646\u062d\u0646 \u0646\u0646\u062a\u0638\u0631 \u0628\u0643\u0645 \u0623\u0646 \u064a\u0635\u064a\u0628\u0643\u0645 \u0627\u0644\u0644\u0647 \u0628\u0639\u0642\u0648\u0628\u0629 \u0645\u0650\u0646 \u0639\u0646\u062f\u0647 \u0639\u0627\u062c\u0644\u0629 \u062a\u0647\u0644\u0643\u0643\u0645 \u0623\u0648 \u0628\u0623\u064a\u062f\u064a\u0646\u0627 \u0641\u0646\u0642\u062a\u0644\u0643\u0645\u060c \u0641\u0627\u0646\u062a\u0638\u0631\u0648\u0627 \u0625\u0646\u0627 \u0645\u0639\u0643\u0645 \u0645\u0646\u062a\u0638\u0631\u0648\u0646 \u0645\u0627 \u0627\u0644\u0644\u0647 \u0641\u0627\u0639\u0644 \u0628\u0643\u0644 \u0641\u0631\u064a\u0642 \u0645\u0646\u0627 \u0648\u0645\u0646\u0643\u0645.","9:53":"\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0644\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646: \u0623\u0646\u0641\u0642\u0648\u0627 \u0623\u0645\u0648\u0627\u0644\u0643\u0645 \u0643\u064a\u0641 \u0634\u0626\u062a\u0645\u060c \u0648\u0639\u0644\u0649 \u0623\u064a \u062d\u0627\u0644 \u0634\u0626\u062a\u0645 \u0637\u0627\u0626\u0639\u064a\u0646 \u0623\u0648 \u0643\u0627\u0631\u0647\u064a\u0646\u060c \u0644\u0646 \u064a\u0642\u0628\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646\u0643\u0645 \u0646\u0641\u0642\u0627\u062a\u0643\u0645; \u0644\u0623\u0646\u0643\u0645 \u0642\u0648\u0645 \u062e\u0627\u0631\u062c\u0648\u0646 \u0639\u0646 \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u0648\u0637\u0627\u0639\u062a\u0647.","9:54":"\u0648\u0633\u0628\u0628 \u0639\u062f\u0645 \u0642\u064e\u0628\u0648\u0644 \u0646\u0641\u0642\u0627\u062a\u0647\u0645 \u0623\u0646\u0647\u0645 \u0623\u0636\u0645\u0631\u0648\u0627 \u0627\u0644\u0643\u0641\u0631 \u0628\u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644 \u0648\u062a\u0643\u0630\u064a\u0628 \u0631\u0633\u0648\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0644\u0627 \u064a\u0623\u062a\u0648\u0646 \u0627\u0644\u0635\u0644\u0627\u0629 \u0625\u0644\u0627 \u0648\u0647\u0645 \u0645\u062a\u062b\u0627\u0642\u0644\u0648\u0646\u060c \u0648\u0644\u0627 \u064a\u0646\u0641\u0642\u0648\u0646 \u0627\u0644\u0623\u0645\u0648\u0627\u0644 \u0625\u0644\u0627 \u0648\u0647\u0645 \u0643\u0627\u0631\u0647\u0648\u0646\u060c \u0641\u0647\u0645 \u0644\u0627 \u064a\u0631\u062c\u0648\u0646 \u062b\u0648\u0627\u0628 \u0647\u0630\u0647 \u0627\u0644\u0641\u0631\u0627\u0626\u0636\u060c \u0648\u0644\u0627 \u064a\u062e\u0634\u0648\u0646 \u0639\u0644\u0649 \u062a\u0631\u0643\u0647\u0627 \u0639\u0642\u0627\u0628\u064b\u0627 \u0628\u0633\u0628\u0628 \u0643\u0641\u0631\u0647\u0645.","9:55":"\u0641\u0644\u0627 \u062a\u0639\u062c\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0623\u0645\u0648\u0627\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0648\u0644\u0627 \u0623\u0648\u0644\u0627\u062f\u0647\u0645\u060c \u0625\u0646\u0645\u0627 \u064a\u0631\u064a\u062f \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u0639\u0630\u0628\u0647\u0645 \u0628\u0647\u0627 \u0641\u064a \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627 \u0628\u0627\u0644\u062a\u0639\u0628 \u0641\u064a \u062a\u062d\u0635\u064a\u0644\u0647\u0627 \u0648\u0628\u0627\u0644\u0645\u0635\u0627\u0626\u0628 \u0627\u0644\u062a\u064a \u062a\u0642\u0639 \u0641\u064a\u0647\u0627\u060c \u062d\u064a\u062b \u0644\u0627 \u064a\u062d\u062a\u0633\u0628\u0648\u0646 \u0630\u0644\u0643 \u0639\u0646\u062f \u0627\u0644\u0644\u0647\u060c \u0648\u062a\u062e\u0631\u062c \u0623\u0646\u0641\u0633\u0647\u0645\u060c \u0641\u064a\u0645\u0648\u062a\u0648\u0627 \u0639\u0644\u0649 \u0643\u0641\u0631\u0647\u0645 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647.","9:56":"\u0648\u064a\u062d\u0644\u0641 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0628\u0627\u0644\u0644\u0647 \u0644\u0643\u0645 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0643\u0630\u0628\u064b\u0627 \u0648\u0628\u0627\u0637\u0644\u0627 \u0625\u0646\u0647\u0645 \u0644\u0645\u0646\u0643\u0645\u060c \u0648\u0644\u064a\u0633\u0648\u0627 \u0645\u0646\u0643\u0645\u060c \u0648\u0644\u0643\u0646\u0647\u0645 \u0642\u0648\u0645 \u064a\u062e\u0627\u0641\u0648\u0646 \u0641\u064a\u062d\u0644\u0641\u0648\u0646 \u062a\u064e\u0642\u0650\u064a\u0651\u064e\u0629 \u0644\u0643\u0645.","9:57":"\u0644\u0648 \u064a\u062c\u062f \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0645\u0623\u0645\u0646\u064b\u0627 \u0648\u062d\u0635\u0646\u064b\u0627 \u064a\u062d\u0641\u0638\u0647\u0645\u060c \u0623\u0648 \u0643\u0647\u0641\u064b\u0627 \u0641\u064a \u062c\u0628\u0644 \u064a\u0624\u0648\u064a\u0647\u0645\u060c \u0623\u0648 \u0646\u0641\u0642\u064b\u0627 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u064a\u0646\u062c\u064a\u0647\u0645 \u0645\u0646\u0643\u0645\u060c \u0644\u0627\u0646\u0635\u0631\u0641\u0648\u0627 \u0625\u0644\u064a\u0647 \u0648\u0647\u0645 \u064a\u0633\u0631\u0639\u0648\u0646.","9:58":"\u0648\u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0645\u064e\u0646 \u064a\u0639\u064a\u0628\u0643 \u0641\u064a \u0642\u0633\u0645\u0629 \u0627\u0644\u0635\u062f\u0642\u0627\u062a\u060c \u0641\u0625\u0646 \u0646\u0627\u0644\u0647\u0645 \u0646\u0635\u064a\u0628 \u0645\u0646\u0647\u0627 \u0631\u0636\u0648\u0627 \u0648\u0633\u0643\u062a\u0648\u0627\u060c \u0648\u0625\u0646 \u0644\u0645 \u064a\u0635\u0628\u0647\u0645 \u062d\u0638 \u0645\u0646\u0647\u0627 \u0633\u062e\u0637\u0648\u0627 \u0639\u0644\u064a\u0643 \u0648\u0639\u0627\u0628\u0648\u0643.","9:59":"\u0648\u0644\u0648 \u0623\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u064a\u0639\u064a\u0628\u0648\u0646\u0643 \u0641\u064a \u0642\u0633\u0645\u0629 \u0627\u0644\u0635\u062f\u0642\u0627\u062a \u0631\u0636\u0648\u0627 \u0628\u0645\u0627 \u0642\u0633\u0645 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0644\u0647\u0645\u060c \u0648\u0642\u0627\u0644\u0648\u0627: \u062d\u0633\u0628\u0646\u0627 \u0627\u0644\u0644\u0647\u060c \u0633\u064a\u0624\u062a\u064a\u0646\u0627 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0641\u0636\u0644\u0647\u060c \u0648\u064a\u0639\u0637\u064a\u0646\u0627 \u0631\u0633\u0648\u0644\u0647 \u0645\u0645\u0627 \u0622\u062a\u0627\u0647 \u0627\u0644\u0644\u0647\u060c \u0625\u0646\u0627 \u0646\u0631\u063a\u0628 \u0623\u0646 \u064a\u0648\u0633\u0639 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0646\u0627\u060c \u0641\u064a\u063a\u0646\u064a\u0646\u0627 \u0639\u0646 \u0627\u0644\u0635\u062f\u0642\u0629 \u0648\u0639\u0646 \u0635\u062f\u0642\u0627\u062a \u0627\u0644\u0646\u0627\u0633. \u0644\u0648 \u0641\u0639\u0644\u0648\u0627 \u0630\u0644\u0643 \u0644\u0643\u0627\u0646 \u062e\u064a\u0631\u064b\u0627 \u0644\u0647\u0645 \u0648\u0623\u062c\u062f\u0649.","9:60":"\u0625\u0646\u0645\u0627 \u062a\u0639\u0637\u0649 \u0627\u0644\u0632\u0643\u0648\u0627\u062a \u0627\u0644\u0648\u0627\u062c\u0628\u0629 \u0644\u0644\u0645\u062d\u062a\u0627\u062c\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0644\u0627 \u064a\u0645\u0644\u0643\u0648\u0646 \u0634\u064a\u0626\u064b\u0627\u060c \u0648\u0644\u0644\u0645\u0633\u0627\u0643\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0644\u0627 \u064a\u0645\u0644\u0643\u0648\u0646 \u0645\u0627 \u064a\u0643\u0641\u064a\u0647\u0645 \u0648\u064a\u0633\u062f \u062d\u0627\u062c\u062a\u0647\u0645\u060c \u0648\u0644\u0644\u0633\u0639\u0627\u0629 \u0627\u0644\u0630\u064a\u0646 \u064a\u062c\u0645\u0639\u0648\u0646\u0647\u0627\u060c \u0648\u0644\u0644\u0630\u064a\u0646 \u062a\u0624\u0644\u0651\u0650\u0641\u0648\u0646 \u0642\u0644\u0648\u0628\u0647\u0645 \u0628\u0647\u0627 \u0645\u0645\u0646 \u064a\u064f\u0631\u0652\u062c\u064e\u0649 \u0625\u0633\u0644\u0627\u0645\u0647 \u0623\u0648 \u0642\u0648\u0629 \u0625\u064a\u0645\u0627\u0646\u0647 \u0623\u0648 \u0646\u0641\u0639\u0647 \u0644\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0623\u0648 \u062a\u062f\u0641\u0639\u0648\u0646 \u0628\u0647\u0627 \u0634\u0631\u0651\u064e \u0623\u062d\u062f \u0639\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0648\u062a\u0639\u0637\u0649 \u0641\u064a \u0639\u062a\u0642 \u0631\u0642\u0627\u0628 \u0627\u0644\u0623\u0631\u0642\u0627\u0621 \u0648\u0627\u0644\u0645\u0643\u0627\u062a\u0628\u064a\u0646\u060c \u0648\u062a\u0639\u0637\u0649 \u0644\u0644\u063a\u0627\u0631\u0645\u064a\u0646 \u0644\u0625\u0635\u0644\u0627\u062d \u0630\u0627\u062a \u0627\u0644\u0628\u064a\u0646\u060c \u0648\u0644\u0645\u0646 \u0623\u062b\u0642\u0644\u064e\u062a\u0652\u0647\u0645 \u0627\u0644\u062f\u064a\u0648\u0646 \u0641\u064a \u063a\u064a\u0631 \u0641\u0633\u0627\u062f \u0648\u0644\u0627 \u062a\u0628\u0630\u064a\u0631 \u0641\u0623\u0639\u0633\u0631\u0648\u0627\u060c \u0648\u0644\u0644\u063a\u0632\u0627\u0629 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0644\u0645\u0633\u0627\u0641\u0631 \u0627\u0644\u0630\u064a \u0627\u0646\u0642\u0637\u0639\u062a \u0628\u0647 \u0627\u0644\u0646\u0641\u0642\u0629\u060c \u0647\u0630\u0647 \u0627\u0644\u0642\u0633\u0645\u0629 \u0641\u0631\u064a\u0636\u0629 \u0641\u0631\u0636\u0647\u0627 \u0627\u0644\u0644\u0647 \u0648\u0642\u062f\u0651\u064e\u0631\u0647\u0627. \u0648\u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645 \u0628\u0645\u0635\u0627\u0644\u062d \u0639\u0628\u0627\u062f\u0647\u060c \u062d\u0643\u064a\u0645 \u0641\u064a \u062a\u062f\u0628\u064a\u0631\u0647 \u0648\u0634\u0631\u0639\u0647.","9:61":"\u0648\u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0642\u0648\u0645 \u064a\u0624\u0630\u0648\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0628\u0627\u0644\u0643\u0644\u0627\u0645\u060c \u0648\u064a\u0642\u0648\u0644\u0648\u0646: \u0625\u0646\u0647 \u064a\u0633\u062a\u0645\u0639 \u0644\u0643\u0644 \u0645\u0627 \u064a\u0642\u0627\u0644 \u0644\u0647 \u0641\u064a\u0635\u062f\u0642\u0647\u060c \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a-: \u0625\u0646 \u0645\u062d\u0645\u062f\u064b\u0627 \u0647\u0648 \u0623\u0630\u0646 \u062a\u0633\u062a\u0645\u0639 \u0644\u0643\u0644 \u062e\u064a\u0631\u060c \u064a\u0624\u0645\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u064a\u0635\u062f\u0642 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0641\u064a\u0645\u0627 \u064a\u062e\u0628\u0631\u0648\u0646\u0647\u060c \u0648\u0647\u0648 \u0631\u062d\u0645\u0629 \u0644\u0645\u0646 \u0627\u062a\u0628\u0639\u0647 \u0648\u0627\u0647\u062a\u062f\u0649 \u0628\u0647\u062f\u0627\u0647. \u0648\u0627\u0644\u0630\u064a\u0646 \u064a\u0624\u0630\u0648\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0645\u062d\u0645\u062f\u064b\u0627 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0628\u0623\u064a \u0646\u0648\u0639 \u0645\u0646 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u0625\u064a\u0630\u0627\u0621\u060c \u0644\u0647\u0645 \u0639\u0630\u0627\u0628 \u0645\u0624\u0644\u0645 \u0645\u0648\u062c\u0639.","9:62":"\u064a\u062d\u0644\u0641 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0627\u0644\u0623\u064a\u0645\u0627\u0646 \u0627\u0644\u0643\u0627\u0630\u0628\u0629\u060c \u0648\u064a\u0642\u062f\u0645\u0648\u0646 \u0627\u0644\u0623\u0639\u0630\u0627\u0631 \u0627\u0644\u0645\u0644\u0641\u0642\u0629; \u0644\u064a\u064f\u0631\u0636\u064f\u0648\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0648\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0623\u062d\u0642 \u0648\u0623\u0648\u0644\u0649 \u0623\u0646 \u064a\u064f\u0631\u0636\u064f\u0648\u0647\u0645\u0627 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0647\u0645\u0627 \u0648\u0637\u0627\u0639\u062a\u0647\u0645\u0627\u060c \u0625\u0646 \u0643\u0627\u0646\u0648\u0627 \u0645\u0624\u0645\u0646\u064a\u0646 \u062d\u0642\u064b\u0627.","9:63":"\u0623\u0644\u0645 \u064a\u0639\u0644\u0645 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0623\u0646 \u0645\u0635\u064a\u0631 \u0627\u0644\u0630\u064a\u0646 \u064a\u062d\u0627\u0631\u0628\u0648\u0646 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0646\u0627\u0631\u064f \u062c\u0647\u0646\u0645 \u0644\u0647\u0645 \u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u062f\u0627\u0626\u0645 \u0641\u064a\u0647\u0627\u061f \u0630\u0644\u0643 \u0627\u0644\u0645\u0635\u064a\u0631 \u0647\u0648 \u0627\u0644\u0647\u0648\u0627\u0646 \u0648\u0627\u0644\u0630\u0644 \u0627\u0644\u0639\u0638\u064a\u0645\u060c \u0648\u0645\u0646 \u0627\u0644\u0645\u062d\u0627\u0631\u0628\u0629 \u0623\u0630\u0650\u064a\u0651\u064e\u0629 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0628\u0633\u0628\u0647 \u0648\u0627\u0644\u0642\u062f\u062d \u0641\u064a\u0647\u060c \u0639\u064a\u0627\u0630\u064b\u0627 \u0628\u0627\u0644\u0644\u0647 \u0645\u0646 \u0630\u0644\u0643.","9:64":"\u064a\u062e\u0627\u0641 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0623\u0646 \u062a\u0646\u0632\u0644 \u0641\u064a \u0634\u0623\u0646\u0647\u0645 \u0633\u0648\u0631\u0629 \u062a\u062e\u0628\u0631\u0647\u0645 \u0628\u0645\u0627 \u064a\u0636\u0645\u0631\u0648\u0646\u0647 \u0641\u064a \u0642\u0644\u0648\u0628\u0647\u0645 \u0645\u0646 \u0627\u0644\u0643\u0641\u0631\u060c \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a-: \u0627\u0633\u062a\u0645\u0631\u0648\u0627 \u0639\u0644\u0649 \u0645\u0627 \u0623\u0646\u062a\u0645 \u0639\u0644\u064a\u0647 \u0645\u0646 \u0627\u0644\u0627\u0633\u062a\u0647\u0632\u0627\u0621 \u0648\u0627\u0644\u0633\u062e\u0631\u064a\u0629\u060c \u0625\u0646 \u0627\u0644\u0644\u0647 \u0645\u062e\u0631\u062c \u062d\u0642\u064a\u0642\u0629 \u0645\u0627 \u062a\u062d\u0630\u0631\u0648\u0646.","9:65":"\u0648\u0644\u0626\u0646 \u0633\u0623\u0644\u062a\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0639\u0645\u0627 \u0642\u0627\u0644\u0648\u0627 \u0645\u0646 \u0627\u0644\u0642\u064e\u062f\u0652\u062d \u0641\u064a \u062d\u0642\u0643 \u0648\u062d\u0642 \u0623\u0635\u062d\u0627\u0628\u0643 \u0644\u064e\u064a\u064e\u0642\u0648\u0644\u064f\u0646\u0651\u064e: \u0625\u0646\u0645\u0627 \u0643\u0646\u0627 \u0646\u062a\u062d\u062f\u062b \u0628\u0643\u0644\u0627\u0645 \u0644\u0627 \u0642\u0635\u062f \u0644\u0646\u0627 \u0628\u0647\u060c \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a-: \u0623\u0628\u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644 \u0648\u0622\u064a\u0627\u062a\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0643\u0646\u062a\u0645 \u062a\u0633\u062a\u0647\u0632\u0626\u0648\u0646\u061f","9:66":"\u0644\u0627 \u062a\u0639\u062a\u0630\u0631\u0648\u0627 -\u0645\u0639\u0634\u0631 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646- \u0641\u0644\u0627 \u062c\u062f\u0648\u0649 \u0645\u0650\u0646 \u0627\u0639\u062a\u0630\u0627\u0631\u0643\u0645\u060c \u0642\u062f \u0643\u0641\u0631\u062a\u0645 \u0628\u0647\u0630\u0627 \u0627\u0644\u0645\u0642\u0627\u0644 \u0627\u0644\u0630\u064a \u0627\u0633\u062a\u0647\u0632\u0623\u062a\u0645 \u0628\u0647\u060c \u0625\u0646 \u0646\u0639\u0641 \u0639\u0646 \u062c\u0645\u0627\u0639\u0629 \u0645\u0646\u0643\u0645 \u0637\u0644\u0628\u062a \u0627\u0644\u0639\u0641\u0648 \u0648\u0623\u062e\u0644\u0635\u062a \u0641\u064a \u062a\u0648\u0628\u062a\u0647\u0627\u060c \u0646\u0639\u0630\u0628 \u062c\u0645\u0627\u0639\u0629 \u0623\u062e\u0631\u0649 \u0628\u0633\u0628\u0628 \u0625\u062c\u0631\u0627\u0645\u0647\u0645 \u0628\u0647\u0630\u0647 \u0627\u0644\u0645\u0642\u0627\u0644\u0629 \u0627\u0644\u0641\u0627\u062c\u0631\u0629 \u0627\u0644\u062e\u0627\u0637\u0626\u0629.","9:67":"\u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0648\u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0627\u062a \u0635\u0646\u0641 \u0648\u0627\u062d\u062f \u0641\u064a \u0625\u0639\u0644\u0627\u0646\u0647\u0645 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0633\u062a\u0628\u0637\u0627\u0646\u0647\u0645 \u0627\u0644\u0643\u0641\u0631\u060c \u064a\u0623\u0645\u0631\u0648\u0646 \u0628\u0627\u0644\u0643\u0641\u0631 \u0628\u0627\u0644\u0644\u0647 \u0648\u0645\u0639\u0635\u064a\u0629 \u0631\u0633\u0648\u0644\u0647 \u0648\u064a\u0646\u0647\u0648\u0646 \u0639\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u0637\u0627\u0639\u0629\u060c \u0648\u064a\u0645\u0633\u0643\u0648\u0646 \u0623\u064a\u062f\u064a\u0647\u0645 \u0639\u0646 \u0627\u0644\u0646\u0641\u0642\u0629 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647\u060c \u0646\u0633\u0648\u0627 \u0627\u0644\u0644\u0647 \u0641\u0644\u0627 \u064a\u0630\u0643\u0631\u0648\u0646\u0647\u060c \u0641\u0646\u0633\u064a\u0647\u0645 \u0645\u0646 \u0631\u062d\u0645\u062a\u0647\u060c \u0641\u0644\u0645 \u064a\u0648\u0641\u0642\u0647\u0645 \u0625\u0644\u0649 \u062e\u064a\u0631. \u0625\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0647\u0645 \u0627\u0644\u062e\u0627\u0631\u062c\u0648\u0646 \u0639\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647.","9:68":"\u0648\u0639\u062f \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0648\u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0627\u062a \u0648\u0627\u0644\u0643\u0641\u0627\u0631 \u0628\u0623\u0646 \u0645\u0635\u064a\u0631\u0647\u0645 \u0625\u0644\u0649 \u0646\u0627\u0631 \u062c\u0647\u0646\u0645 \u062e\u0627\u0644\u062f\u064a\u0646 \u0641\u064a\u0647\u0627 \u0623\u0628\u062f\u064b\u0627\u060c \u0647\u064a \u0643\u0627\u0641\u064a\u062a\u0647\u0645; \u0639\u0642\u0627\u0628\u064b\u0627 \u0639\u0644\u0649 \u0643\u0641\u0631\u0647\u0645 \u0628\u0627\u0644\u0644\u0647\u060c \u0648\u0637\u0631\u062f\u0647\u0645 \u0627\u0644\u0644\u0647 \u0645\u0650\u0646 \u0631\u062d\u0645\u062a\u0647\u060c \u0648\u0644\u0647\u0645 \u0639\u0630\u0627\u0628 \u062f\u0627\u0626\u0645.","9:69":"\u0625\u0646 \u0623\u0641\u0639\u0627\u0644\u0643\u0645 -\u0645\u0639\u0634\u0631 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646- \u0645\u0646 \u0627\u0644\u0627\u0633\u062a\u0647\u0632\u0627\u0621 \u0648\u0627\u0644\u0643\u0641\u0631 \u0643\u0623\u0641\u0639\u0627\u0644 \u0627\u0644\u0623\u0645\u0645 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u062a \u0639\u0644\u0649 \u062c\u0627\u0646\u0628 \u0645\u0646 \u0627\u0644\u0642\u0648\u0629 \u0648\u0627\u0644\u0645\u0627\u0644 \u0648\u0627\u0644\u0623\u0648\u0644\u0627\u062f \u0623\u0634\u062f \u0645\u0646\u0643\u0645\u060c \u0641\u0627\u0637\u0652\u0645\u064e\u0623\u0646\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u062a\u064e\u0645\u062a\u0651\u064e\u0639\u0648\u0627 \u0628\u0645\u0627 \u0641\u064a\u0647\u0627 \u0645\u0646 \u0627\u0644\u062d\u0638\u0648\u0638 \u0648\u0627\u0644\u0645\u0644\u0630\u0627\u062a\u060c \u0641\u0627\u0633\u062a\u0645\u0639\u062a\u0645 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0628\u0646\u0635\u064a\u0628\u0643\u0645 \u0645\u0646 \u0627\u0644\u0634\u0647\u0648\u0627\u062a \u0627\u0644\u0641\u0627\u0646\u064a\u0629 \u0643\u0627\u0633\u062a\u0645\u062a\u0627\u0639 \u0627\u0644\u0630\u064a\u0646 \u0645\u0646 \u0642\u0628\u0644\u0643\u0645 \u0628\u062d\u0638\u0648\u0638\u0647\u0645 \u0627\u0644\u0641\u0627\u0646\u064a\u0629\u060c \u0648\u062e\u0636\u062a\u0645 \u0628\u0627\u0644\u0643\u0630\u0628 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647 \u0643\u062e\u0648\u0636 \u062a\u0644\u0643 \u0627\u0644\u0623\u0645\u0645 \u0642\u0628\u0644\u0643\u0645\u060c \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0645\u0648\u0635\u0648\u0641\u0648\u0646 \u0628\u0647\u0630\u0647 \u0627\u0644\u0623\u062e\u0644\u0627\u0642 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0630\u0647\u0628\u062a \u062d\u0633\u0646\u0627\u062a\u0647\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u062e\u0627\u0633\u0631\u0648\u0646 \u0628\u0628\u064a\u0639\u0647\u0645 \u0646\u0639\u064a\u0645 \u0627\u0644\u0622\u062e\u0631\u0629 \u0628\u062d\u0638\u0648\u0638\u0647\u0645 \u0645\u0646 \u0627\u0644\u062f\u0646\u064a\u0627.","9:70":"\u0623\u0644\u0645 \u064a\u0623\u062a \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u062e\u0628\u0631\u064f \u0627\u0644\u0630\u064a\u0646 \u0645\u0636\u0648\u0627 \u0645\u0650\u0646 \u0642\u0648\u0645 \u0646\u0648\u062d \u0648\u0642\u0628\u064a\u0644\u0629 \u0639\u0627\u062f \u0648\u0642\u0628\u064a\u0644\u0629 \u062b\u0645\u0648\u062f \u0648\u0642\u0648\u0645 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0648\u0623\u0635\u062d\u0627\u0628 (\u0645\u062f\u064a\u0646) \u0648\u0642\u0648\u0645 \u0644\u0648\u0637 \u0639\u0646\u062f\u0645\u0627 \u062c\u0627\u0621\u0647\u0645 \u0627\u0644\u0645\u0631\u0633\u0644\u0648\u0646 \u0628\u0627\u0644\u0648\u062d\u064a \u0648\u0628\u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647 \u0641\u0643\u0630\u0651\u064e\u0628\u0648\u0647\u0645\u061f \u0641\u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0628\u0647\u0624\u0644\u0627\u0621 \u062c\u0645\u064a\u0639\u064b\u0627 \u0639\u0630\u0627\u0628\u0647; \u0627\u0646\u062a\u0642\u0627\u0645\u064b\u0627 \u0645\u0646\u0647\u0645 \u0644\u0633\u0648\u0621 \u0639\u0645\u0644\u0647\u0645\u060c \u0641\u0645\u0627 \u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u0644\u064a\u0638\u0644\u0645\u0647\u0645\u060c \u0648\u0644\u0643\u0646 \u0643\u0627\u0646\u0648\u0627 \u0647\u0645 \u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0644\u0623\u0646\u0641\u0633\u0647\u0645 \u0628\u0627\u0644\u062a\u0643\u0630\u064a\u0628 \u0648\u0627\u0644\u0645\u062e\u0627\u0644\u0641\u0629.","9:71":"\u0648\u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0648\u0627\u0644\u0645\u0624\u0645\u0646\u0627\u062a \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0628\u0639\u0636\u0647\u0645 \u0623\u0646\u0635\u0627\u0631 \u0628\u0639\u0636\u060c \u064a\u0623\u0645\u0631\u0648\u0646 \u0627\u0644\u0646\u0627\u0633 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u060c \u0648\u064a\u0646\u0647\u0648\u0646\u0647\u0645 \u0639\u0646 \u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u0645\u0639\u0627\u0635\u064a\u060c \u0648\u064a\u0624\u062f\u0648\u0646 \u0627\u0644\u0635\u0644\u0627\u0629\u060c \u0648\u064a\u0639\u0637\u0648\u0646 \u0627\u0644\u0632\u0643\u0627\u0629\u060c \u0648\u064a\u0637\u064a\u0639\u0648\u0646 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u064a\u0646\u062a\u0647\u0648\u0646 \u0639\u0645\u0627 \u0646\u064f\u0647\u0648\u0627 \u0639\u0646\u0647\u060c \u0623\u0648\u0644\u0626\u0643 \u0633\u064a\u0631\u062d\u0645\u0647\u0645 \u0627\u0644\u0644\u0647 \u0641\u064a\u0646\u0642\u0630\u0647\u0645 \u0645\u0646 \u0639\u0630\u0627\u0628\u0647 \u0648\u064a\u062f\u062e\u0644\u0647\u0645 \u062c\u0646\u062a\u0647. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0639\u0632\u064a\u0632 \u0641\u064a \u0645\u0644\u0643\u0647\u060c \u062d\u0643\u064a\u0645 \u0641\u064a \u062a\u0634\u0631\u064a\u0639\u0627\u062a\u0647 \u0648\u0623\u062d\u0643\u0627\u0645\u0647.","9:72":"\u0648\u0639\u062f \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0648\u0627\u0644\u0645\u0624\u0645\u0646\u0627\u062a \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u062c\u0646\u0627\u062a \u062a\u062c\u0631\u064a \u0645\u0646 \u062a\u062d\u062a \u0642\u0635\u0648\u0631\u0647\u0627 \u0648\u0623\u0634\u062c\u0627\u0631\u0647\u0627 \u0627\u0644\u0623\u0646\u0647\u0627\u0631 \u0645\u0627\u0643\u062b\u064a\u0646 \u0641\u064a\u0647\u0627 \u0623\u0628\u062f\u064b\u0627\u060c \u0644\u0627 \u064a\u0632\u0648\u0644 \u0639\u0646\u0647\u0645 \u0646\u0639\u064a\u0645\u0647\u0627\u060c \u0648\u0645\u0633\u0627\u0643\u0646 \u062d\u0633\u0646\u0629 \u0627\u0644\u0628\u0646\u0627\u0621 \u0637\u064a\u0628\u0629 \u0627\u0644\u0642\u0631\u0627\u0631 \u0641\u064a \u062c\u0646\u0627\u062a \u0625\u0642\u0627\u0645\u0629\u060c \u0648\u0631\u0636\u0648\u0627\u0646 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0623\u0643\u0628\u0631 \u0648\u0623\u0639\u0638\u0645 \u0645\u0645\u0627 \u0647\u0645 \u0641\u064a\u0647 \u0645\u0646 \u0627\u0644\u0646\u0639\u064a\u0645. \u0630\u0644\u0643 \u0627\u0644\u0648\u0639\u062f \u0628\u062b\u0648\u0627\u0628 \u0627\u0644\u0622\u062e\u0631\u0629 \u0647\u0648 \u0627\u0644\u0641\u0644\u0627\u062d \u0627\u0644\u0639\u0638\u064a\u0645.","9:73":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a \u062c\u0627\u0647\u062f \u0627\u0644\u0643\u0641\u0627\u0631 \u0628\u0627\u0644\u0633\u064a\u0641 \u0648\u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0628\u0627\u0644\u0644\u0633\u0627\u0646 \u0648\u0627\u0644\u062d\u062c\u0629\u060c \u0648\u0627\u0634\u062f\u062f \u0639\u0644\u0649 \u0643\u0644\u0627 \u0627\u0644\u0641\u0631\u064a\u0642\u064a\u0646\u060c \u0648\u0645\u0642\u0631\u0651\u064f\u0647\u0645 \u062c\u0647\u0646\u0645\u060c \u0648\u0628\u0626\u0633 \u0627\u0644\u0645\u0635\u064a\u0631 \u0645\u0635\u064a\u0631\u0647\u0645.","9:74":"\u064a\u062d\u0644\u0641 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0628\u0627\u0644\u0644\u0647 \u0623\u0646\u0647\u0645 \u0645\u0627 \u0642\u0627\u0644\u0648\u0627 \u0634\u064a\u0626\u064b\u0627 \u064a\u0633\u064a\u0621 \u0625\u0644\u0649 \u0627\u0644\u0631\u0633\u0648\u0644 \u0648\u0625\u0644\u0649 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0625\u0646\u0647\u0645 \u0644\u0643\u0627\u0630\u0628\u0648\u0646; \u0641\u0644\u0642\u062f \u0642\u0627\u0644\u0648\u0627 \u0643\u0644\u0645\u0629 \u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0631\u062a\u062f\u0648\u0627 \u0628\u0647\u0627 \u0639\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0648\u062d\u0627\u0648\u0644\u0648\u0627 \u0627\u0644\u0625\u0636\u0631\u0627\u0631 \u0628\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0641\u0644\u0645 \u064a\u0645\u0643\u0646\u0647\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0630\u0644\u0643\u060c \u0648\u0645\u0627 \u0648\u062c\u062f \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0634\u064a\u0626\u064b\u0627 \u064a\u0639\u064a\u0628\u0648\u0646\u0647\u060c \u0648\u064a\u0646\u062a\u0642\u062f\u0648\u0646\u0647\u060c \u0625\u0644\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 -\u062a\u0639\u0627\u0644\u0649- \u062a\u0641\u0636\u0644 \u0639\u0644\u064a\u0647\u0645\u060c \u0641\u0623\u063a\u0646\u0627\u0647\u0645 \u0628\u0645\u0627 \u0641\u062a\u062d \u0639\u0644\u0649 \u0646\u0628\u064a\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0645\u0646 \u0627\u0644\u062e\u064a\u0631 \u0648\u0627\u0644\u0628\u0631\u0643\u0629\u060c \u0641\u0625\u0646 \u064a\u0631\u062c\u0639 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0643\u0641\u0627\u0631 \u0625\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u062a\u0648\u0628\u0629 \u0641\u0647\u0648 \u062e\u064a\u0631 \u0644\u0647\u0645\u060c \u0648\u0625\u0646 \u064a\u0639\u0631\u0636\u0648\u0627\u060c \u0623\u0648 \u064a\u0633\u062a\u0645\u0631\u0648\u0627 \u0639\u0644\u0649 \u062d\u0627\u0644\u0647\u0645\u060c \u064a\u0639\u0630\u0628\u0647\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u0639\u0630\u0627\u0628 \u0627\u0644\u0645\u0648\u062c\u0639 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0639\u0644\u0649 \u0623\u064a\u062f\u064a \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0648\u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0628\u0646\u0627\u0631 \u062c\u0647\u0646\u0645\u060c \u0648\u0644\u064a\u0633 \u0644\u0647\u0645 \u0645\u0646\u0642\u0630 \u064a\u0646\u0642\u0630\u0647\u0645 \u0648\u0644\u0627 \u0646\u0627\u0635\u0631 \u064a\u062f\u0641\u0639 \u0639\u0646\u0647\u0645 \u0633\u0648\u0621 \u0627\u0644\u0639\u0630\u0627\u0628.","9:75":"\u0648\u0645\u0646 \u0641\u0642\u0631\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0645\u064e\u0646 \u064a\u0642\u0637\u0639 \u0627\u0644\u0639\u0647\u062f \u0639\u0644\u0649 \u0646\u0641\u0633\u0647: \u0644\u0626\u0646 \u0623\u0639\u0637\u0627\u0647 \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0627\u0644 \u0644\u064a\u0635\u062f\u0651\u064e\u0642\u0646\u0651\u064e \u0645\u0646\u0647\u060c \u0648\u0644\u064a\u0639\u0645\u064e\u0644\u0646\u0651\u064e \u0645\u0627 \u064a\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u0648\u0646 \u0641\u064a \u0623\u0645\u0648\u0627\u0644\u0647\u0645\u060c \u0648\u0644\u064a\u0633\u064a\u0631\u064e\u0646\u0651\u064e \u0641\u064a \u0637\u0631\u064a\u0642 \u0627\u0644\u0635\u0644\u0627\u062d.","9:76":"\u0641\u0644\u0645\u0627 \u0623\u0639\u0637\u0627\u0647\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0641\u0636\u0644\u0647 \u0628\u062e\u0644\u0648\u0627 \u0628\u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u0635\u062f\u0642\u0629 \u0648\u0628\u0625\u0646\u0641\u0627\u0642 \u0627\u0644\u0645\u0627\u0644 \u0641\u064a \u0627\u0644\u062e\u064a\u0631\u060c \u0648\u062a\u0648\u0644\u0651\u064e\u0648\u0627 \u0648\u0647\u0645 \u0645\u0639\u0631\u0636\u0648\u0646 \u0639\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645.","9:77":"\u0641\u0643\u0627\u0646 \u062c\u0632\u0627\u0621 \u0635\u0646\u064a\u0639\u0647\u0645 \u0648\u0639\u0627\u0642\u0628\u062a\u0647\u0645 \u0623\u064e\u0646\u0652 \u0632\u0627\u062f\u0647\u0645 \u0646\u0641\u0627\u0642\u064b\u0627 \u0639\u0644\u0649 \u0646\u0641\u0627\u0642\u0647\u0645\u060c \u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639\u0648\u0646 \u0627\u0644\u062a\u062e\u0644\u0635 \u0645\u0646\u0647 \u0625\u0644\u0649 \u064a\u0648\u0645 \u0627\u0644\u062d\u0633\u0627\u0628; \u0648\u0630\u0644\u0643 \u0628\u0633\u0628\u0628 \u0625\u062e\u0644\u0627\u0641\u0647\u0645 \u0627\u0644\u0648\u0639\u062f \u0627\u0644\u0630\u064a \u0642\u0637\u0639\u0648\u0647 \u0639\u0644\u0649 \u0623\u0646\u0641\u0633\u0647\u0645\u060c \u0648\u0628\u0633\u0628\u0628 \u0646\u0641\u0627\u0642\u0647\u0645 \u0648\u0643\u0630\u0628\u0647\u0645.","9:78":"\u0623\u0644\u0645 \u064a\u0639\u0644\u0645 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0623\u0646 \u0627\u0644\u0644\u0647 \u064a\u0639\u0644\u0645 \u0645\u0627 \u064a\u062e\u0641\u0648\u0646\u0647 \u0641\u064a \u0623\u0646\u0641\u0633\u0647\u0645 \u0648\u0645\u0627 \u064a\u062a\u062d\u062f\u062b\u0648\u0646 \u0628\u0647 \u0641\u064a \u0645\u062c\u0627\u0644\u0633\u0647\u0645 \u0645\u0646 \u0627\u0644\u0643\u064a\u062f \u0648\u0627\u0644\u0645\u0643\u0631\u060c \u0648\u0623\u0646 \u0627\u0644\u0644\u0647 \u0639\u0644\u0627\u0645 \u0627\u0644\u063a\u064a\u0648\u0628\u061f \u0641\u0633\u064a\u062c\u0627\u0632\u064a\u0647\u0645 \u0639\u0644\u0649 \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0627\u0644\u062a\u064a \u0623\u062d\u0635\u0627\u0647\u0627 \u0639\u0644\u064a\u0647\u0645.","9:79":"\u0648\u0645\u0639 \u0628\u062e\u0644 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0644\u0627 \u064a\u064e\u0633\u0652\u0644\u064e\u0645 \u0627\u0644\u0645\u062a\u0635\u062f\u0642\u0648\u0646 \u0645\u0646 \u0623\u0630\u0627\u0647\u0645; \u0641\u0625\u0630\u0627 \u062a\u0635\u062f\u0642 \u0627\u0644\u0623\u063a\u0646\u064a\u0627\u0621 \u0628\u0627\u0644\u0645\u0627\u0644 \u0627\u0644\u0643\u062b\u064a\u0631 \u0639\u0627\u0628\u0648\u0647\u0645 \u0648\u0627\u062a\u0647\u0645\u0648\u0647\u0645 \u0628\u0627\u0644\u0631\u064a\u0627\u0621\u060c \u0648\u0625\u0630\u0627 \u062a\u0635\u062f\u0642 \u0627\u0644\u0641\u0642\u0631\u0627\u0621 \u0628\u0645\u0627 \u0641\u064a \u0637\u0627\u0642\u062a\u0647\u0645 \u0627\u0633\u062a\u0647\u0632\u0624\u0648\u0627 \u0628\u0647\u0645\u060c \u0648\u0642\u0627\u0644\u0648\u0627 \u0633\u062e\u0631\u064a\u0629 \u0645\u0646\u0647\u0645: \u0645\u0627\u0630\u0627 \u062a\u062c\u062f\u064a \u0635\u062f\u0642\u062a\u0647\u0645 \u0647\u0630\u0647\u061f \u0633\u062e\u0631 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646\u060c \u0648\u0644\u0647\u0645 \u0639\u0630\u0627\u0628 \u0645\u0624\u0644\u0645 \u0645\u0648\u062c\u0639.","9:80":"\u0627\u0633\u062a\u063a\u0641\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0644\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0623\u0648 \u0644\u0627 \u062a\u0633\u062a\u063a\u0641\u0631 \u0644\u0647\u0645\u060c \u0641\u0644\u0646 \u064a\u063a\u0641\u0631 \u0627\u0644\u0644\u0647 \u0644\u0647\u0645\u060c \u0645\u0647\u0645\u0627 \u0643\u062b\u0631 \u0627\u0633\u062a\u063a\u0641\u0627\u0631\u0643 \u0644\u0647\u0645 \u0648\u062a\u0643\u0631\u0631; \u0644\u0623\u0646\u0647\u0645 \u0643\u0641\u0631\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647. \u0648\u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0644\u0627 \u064a\u0648\u0641\u0642 \u0644\u0644\u0647\u062f\u0649 \u0627\u0644\u062e\u0627\u0631\u062c\u064a\u0646 \u0639\u0646 \u0637\u0627\u0639\u062a\u0647.","9:81":"\u0641\u0631\u062d \u0627\u0644\u0645\u062e\u0644\u0641\u0648\u0646 \u0627\u0644\u0630\u064a\u0646 \u062a\u062e\u0644\u0641\u0648\u0627 \u0639\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0628\u0642\u0639\u0648\u062f\u0647\u0645 \u0641\u064a (\u0627\u0644\u0645\u062f\u064a\u0646\u0629) \u0645\u062e\u0627\u0644\u0641\u064a\u0646 \u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0643\u0631\u0647\u0648\u0627 \u0623\u0646 \u064a\u062c\u0627\u0647\u062f\u0648\u0627 \u0645\u0639\u0647 \u0628\u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0648\u0623\u0646\u0641\u0633\u0647\u0645 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u0642\u0627\u0644 \u0628\u0639\u0636\u0647\u0645 \u0644\u0628\u0639\u0636: \u0644\u0627 \u062a\u0646\u0641\u0631\u0648\u0627 \u0641\u064a \u0627\u0644\u062d\u0631\u0651\u0650\u060c \u0648\u0643\u0627\u0646\u062a \u063a\u0632\u0648\u0629 (\u062a\u0628\u0648\u0643) \u0641\u064a \u0648\u0642\u062a \u0634\u062f\u0629 \u0627\u0644\u062d\u0631\u0651\u0650. \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0646\u0627\u0631 \u062c\u0647\u0646\u0645 \u0623\u0634\u062f \u062d\u0631\u064b\u0627\u060c \u0644\u0648 \u0643\u0627\u0646\u0648\u0627 \u064a\u0639\u0644\u0645\u0648\u0646 \u0630\u0644\u0643.","9:82":"\u0641\u0644\u064a\u0636\u062d\u0643 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0627\u0644\u0630\u064a\u0646 \u062a\u062e\u0644\u0641\u0648\u0627 \u0639\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0641\u064a \u063a\u0632\u0648\u0629 (\u062a\u0628\u0648\u0643) \u0642\u0644\u064a\u0644\u0627 \u0641\u064a \u062d\u064a\u0627\u062a\u0647\u0645 \u0627\u0644\u062f\u0646\u064a\u0627 \u0627\u0644\u0641\u0627\u0646\u064a\u0629\u060c \u0648\u0644\u064a\u0628\u0643\u0648\u0627 \u0643\u062b\u064a\u0631\u064b\u0627 \u0641\u064a \u0646\u0627\u0631 \u062c\u0647\u0646\u0645; \u062c\u0632\u0627\u0621\u064b \u0628\u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u064a\u0643\u0633\u0628\u0648\u0646 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0645\u0646 \u0627\u0644\u0646\u0641\u0627\u0642 \u0648\u0627\u0644\u0643\u0641\u0631.","9:83":"\u0641\u0625\u0646\u0652 \u0631\u064e\u062f\u0651\u064e\u0643 \u0627\u0644\u0644\u0647 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0645\u0650\u0646 \u063a\u0632\u0648\u062a\u0643 \u0625\u0644\u0649 \u062c\u0645\u0627\u0639\u0629 \u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0627\u0644\u062b\u0627\u0628\u062a\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0646\u0641\u0627\u0642\u060c \u0641\u0627\u0633\u062a\u0623\u0630\u0646\u0648\u0643 \u0644\u0644\u062e\u0631\u0648\u062c \u0645\u0639\u0643 \u0625\u0644\u0649 \u063a\u0632\u0648\u0629 \u0623\u062e\u0631\u0649 \u0628\u0639\u062f \u063a\u0632\u0648\u0629 (\u062a\u0628\u0648\u0643) \u0641\u0642\u0644 \u0644\u0647\u0645: \u0644\u0646 \u062a\u062e\u0631\u062c\u0648\u0627 \u0645\u0639\u064a \u0623\u0628\u062f\u064b\u0627 \u0641\u064a \u063a\u0632\u0648\u0629 \u0645\u0646 \u0627\u0644\u063a\u0632\u0648\u0627\u062a\u060c \u0648\u0644\u0646 \u062a\u0642\u0627\u062a\u0644\u0648\u0627 \u0645\u0639\u064a \u0639\u062f\u0648\u064b\u0627 \u0645\u0646 \u0627\u0644\u0623\u0639\u062f\u0627\u0621; \u0625\u0646\u0643\u0645 \u0631\u0636\u064a\u062a\u0645 \u0628\u0627\u0644\u0642\u0639\u0648\u062f \u0623\u0648\u0644 \u0645\u0631\u0629\u060c \u0641\u0627\u0642\u0639\u062f\u0648\u0627 \u0645\u0639 \u0627\u0644\u0630\u064a\u0646 \u062a\u062e\u0644\u0641\u0648\u0627 \u0639\u0646 \u0627\u0644\u062c\u0647\u0627\u062f \u0645\u0639 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645.","9:84":"\u0648\u0644\u0627 \u062a\u0635\u0644\u0651\u0650 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0623\u0628\u062f\u064b\u0627 \u0639\u0644\u0649 \u0623\u062d\u062f \u0645\u0627\u062a \u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646\u060c \u0648\u0644\u0627 \u062a\u0642\u0645 \u0639\u0644\u0649 \u0642\u0628\u0631\u0647 \u0644\u062a\u062f\u0639\u0648 \u0644\u0647; \u0644\u0623\u0646\u0647\u0645 \u0643\u0641\u0631\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0628\u0631\u0633\u0648\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0645\u0627\u062a\u0648\u0627 \u0648\u0647\u0645 \u0641\u0627\u0633\u0642\u0648\u0646. \u0648\u0647\u0630\u0627 \u062d\u0643\u0645 \u0639\u0627\u0645 \u0641\u064a \u0643\u0644 \u0645\u0646 \u0639\u064f\u0644\u0650\u0645\u064e \u0646\u0641\u0627\u0642\u0647.","9:85":"\u0648\u0644\u0627 \u062a\u0639\u062c\u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0623\u0645\u0648\u0627\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0648\u0623\u0648\u0644\u0627\u062f\u0647\u0645\u060c \u0625\u0646\u0645\u0627 \u064a\u0631\u064a\u062f \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u0639\u0630\u0628\u0647\u0645 \u0628\u0647\u0627 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0628\u0645\u0643\u0627\u0628\u062f\u062a\u0647\u0645 \u0627\u0644\u0634\u062f\u0627\u0626\u062f \u0641\u064a \u0634\u0623\u0646\u0647\u0627\u060c \u0648\u0628\u0645\u0648\u062a\u0647\u0645 \u0639\u0644\u0649 \u0643\u0641\u0631\u0647\u0645 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647.","9:86":"\u0648\u0625\u0630\u0627 \u0623\u0646\u0632\u0644\u062a \u0633\u0648\u0631\u0629 \u0639\u0644\u0649 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u062a\u0623\u0645\u0631 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u0625\u062e\u0644\u0627\u0635 \u0644\u0647 \u0648\u0627\u0644\u062c\u0647\u0627\u062f \u0645\u0639 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0637\u0644\u0628 \u0627\u0644\u0625\u0630\u0646 \u0645\u0646\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0623\u0648\u0644\u0648 \u0627\u0644\u064a\u0633\u0627\u0631 \u0645\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646\u060c \u0648\u0642\u0627\u0644\u0648\u0627: \u0627\u062a\u0631\u0643\u0646\u0627 \u0645\u0639 \u0627\u0644\u0642\u0627\u0639\u062f\u064a\u0646 \u0627\u0644\u0639\u0627\u062c\u0632\u064a\u0646 \u0639\u0646 \u0627\u0644\u062e\u0631\u0648\u062c.","9:87":"\u0631\u0636\u064a \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0644\u0623\u0646\u0641\u0633\u0647\u0645 \u0628\u0627\u0644\u0639\u0627\u0631\u060c \u0648\u0647\u0648 \u0623\u0646 \u064a\u0642\u0639\u062f\u0648\u0627 \u0641\u064a \u0627\u0644\u0628\u064a\u0648\u062a \u0645\u0639 \u0627\u0644\u0646\u0633\u0627\u0621 \u0648\u0627\u0644\u0635\u0628\u064a\u0627\u0646 \u0648\u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0623\u0639\u0630\u0627\u0631\u060c \u0648\u062e\u062a\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0642\u0644\u0648\u0628\u0647\u0645; \u0628\u0633\u0628\u0628 \u0646\u0641\u0627\u0642\u0647\u0645 \u0648\u062a\u062e\u0644\u0641\u0647\u0645 \u0639\u0646 \u0627\u0644\u062c\u0647\u0627\u062f \u0648\u0627\u0644\u062e\u0631\u0648\u062c \u0645\u0639 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647\u060c \u0641\u0647\u0645 \u0644\u0627 \u064a\u0641\u0642\u0647\u0648\u0646 \u0645\u0627 \u0641\u064a\u0647 \u0635\u0644\u0627\u062d\u0647\u0645 \u0648\u0631\u0634\u0627\u062f\u0647\u0645.","9:88":"\u0625\u0646\u0652 \u062a\u062e\u0644\u0651\u064e\u0641 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0639\u0646 \u0627\u0644\u063a\u0632\u0648\u060c \u0641\u0642\u062f \u062c\u0627\u0647\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0645\u0639\u0647 \u0628\u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0648\u0623\u0646\u0641\u0633\u0647\u0645\u060c \u0648\u0623\u0648\u0644\u0626\u0643 \u0644\u0647\u0645 \u0627\u0644\u0646\u0635\u0631 \u0648\u0627\u0644\u063a\u0646\u064a\u0645\u0629 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0627\u0644\u062c\u0646\u0629 \u0648\u0627\u0644\u0643\u0631\u0627\u0645\u0629 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0648\u0623\u0648\u0644\u0626\u0643 \u0647\u0645 \u0627\u0644\u0641\u0627\u0626\u0632\u0648\u0646.","9:89":"\u0623\u0639\u062f\u0651\u064e \u0627\u0644\u0644\u0647 \u0644\u0647\u0645 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u062c\u0646\u0627\u062a \u062a\u062c\u0631\u064a \u0645\u0650\u0646 \u062a\u062d\u062a \u0642\u0635\u0648\u0631\u0647\u0627 \u0648\u0623\u0634\u062c\u0627\u0631\u0647\u0627 \u0627\u0644\u0623\u0646\u0647\u0627\u0631 \u0645\u0627\u0643\u062b\u064a\u0646 \u0641\u064a\u0647\u0627 \u0623\u0628\u062f\u064b\u0627. \u0648\u0630\u0644\u0643 \u0647\u0648 \u0627\u0644\u0641\u0644\u0627\u062d \u0627\u0644\u0639\u0638\u064a\u0645.","9:90":"\u0648\u062c\u0627\u0621 \u062c\u0645\u0627\u0639\u0629 \u0645\u0646 \u0623\u062d\u064a\u0627\u0621 \u0627\u0644\u0639\u0631\u0628 \u062d\u0648\u0644 (\u0627\u0644\u0645\u062f\u064a\u0646\u0629) \u064a\u0639\u062a\u0630\u0631\u0648\u0646 \u0625\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u064a\u0628\u064a\u0646\u0648\u0646 \u0644\u0647 \u0645\u0627 \u0647\u0645 \u0641\u064a\u0647 \u0645\u0646 \u0627\u0644\u0636\u0639\u0641 \u0648\u0639\u062f\u0645 \u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u0627\u0644\u062e\u0631\u0648\u062c \u0644\u0644\u063a\u0632\u0648\u060c \u0648\u0642\u0639\u062f \u0642\u0648\u0645 \u0628\u063a\u064a\u0631 \u0639\u0630\u0631 \u0623\u0638\u0647\u0631\u0648\u0647 \u062c\u0631\u0623\u0629 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645. \u0633\u064a\u0635\u064a\u0628 \u0627\u0644\u0630\u064a\u0646 \u0643\u0641\u0631\u0648\u0627 \u0645\u0646 \u0647\u0624\u0644\u0627\u0621 \u0639\u0630\u0627\u0628 \u0623\u0644\u064a\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u0628\u0627\u0644\u0642\u062a\u0644 \u0648\u063a\u064a\u0631\u0647\u060c \u0648\u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0628\u0627\u0644\u0646\u0627\u0631.","9:91":"\u0644\u064a\u0633 \u0639\u0644\u0649 \u0623\u0647\u0644 \u0627\u0644\u0623\u0639\u0630\u0627\u0631 \u0645\u0650\u0646 \u0627\u0644\u0636\u0639\u0641\u0627\u0621 \u0648\u0627\u0644\u0645\u0631\u0636\u0649 \u0648\u0627\u0644\u0641\u0642\u0631\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u0644\u0627 \u064a\u0645\u0644\u0643\u0648\u0646 \u0645\u0646 \u0627\u0644\u0645\u0627\u0644 \u0645\u0627 \u064a\u062a\u062c\u0647\u0632\u0648\u0646 \u0628\u0647 \u0644\u0644\u062e\u0631\u0648\u062c \u0625\u062b\u0645 \u0641\u064a \u0627\u0644\u0642\u0639\u0648\u062f \u0625\u0630\u0627 \u0623\u062e\u0644\u0635\u0648\u0627 \u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0645\u0627 \u0639\u0644\u0649 \u0645\u064e\u0646 \u0623\u062d\u0633\u0646 \u0645\u0645\u0646 \u0645\u0646\u0639\u0647 \u0627\u0644\u0639\u0630\u0631 \u0639\u0646 \u0627\u0644\u062c\u0647\u0627\u062f \u0645\u0639 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0647\u0648 \u0646\u0627\u0635\u062d \u0644\u0644\u0647 \u0648\u0644\u0631\u0633\u0648\u0644\u0647 \u0645\u0646 \u0637\u0631\u064a\u0642 \u064a\u0639\u0627\u0642\u0628 \u0645\u0650\u0646 \u0642\u0650\u0628\u064e\u0644\u0650\u0647 \u0648\u064a\u0624\u0627\u062e\u0630 \u0639\u0644\u064a\u0647. \u0648\u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0644\u0644\u0645\u062d\u0633\u0646\u064a\u0646\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","9:92":"\u0648\u0643\u0630\u0644\u0643 \u0644\u0627 \u0625\u062b\u0645 \u0639\u0644\u0649 \u0627\u0644\u0630\u064a\u0646 \u0625\u0630\u0627 \u0645\u0627 \u062c\u0627\u0624\u0648\u0643 \u064a\u0637\u0644\u0628\u0648\u0646 \u0623\u0646 \u062a\u0639\u064a\u0646\u0647\u0645 \u0628\u062d\u0645\u0644\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u062f \u0642\u0644\u062a \u0644\u0647\u0645: \u0644\u0627 \u0623\u062c\u062f \u0645\u0627 \u0623\u062d\u0645\u0644\u0643\u0645 \u0639\u0644\u064a\u0647 \u0645\u0646 \u0627\u0644\u062f\u0648\u0627\u0628\u0651\u0650\u060c \u0641\u0627\u0646\u0635\u0631\u0641\u0648\u0627 \u0639\u0646\u0643\u060c \u0648\u0642\u062f \u0641\u0627\u0636\u062a \u0623\u0639\u064a\u0646\u0647\u0645 \u062f\u064e\u0645\u0639\u064b\u0627 \u0623\u0633\u0641\u064b\u0627 \u0639\u0644\u0649 \u0645\u0627 \u0641\u0627\u062a\u0647\u0645 \u0645\u0646 \u0634\u0631\u0641 \u0627\u0644\u062c\u0647\u0627\u062f \u0648\u062b\u0648\u0627\u0628\u0647; \u0644\u0623\u0646\u0647\u0645 \u0644\u0645 \u064a\u062c\u062f\u0648\u0627 \u0645\u0627 \u064a\u0646\u0641\u0642\u0648\u0646\u060c \u0648\u0645\u0627 \u064a\u062d\u0645\u0644\u0647\u0645 \u0644\u0648 \u062e\u0631\u062c\u0648\u0627 \u0644\u0644\u062c\u0647\u0627\u062f \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647.","9:93":"\u0625\u0646\u0645\u0627 \u0627\u0644\u0625\u062b\u0645 \u0648\u0627\u0644\u0644\u0648\u0645 \u0639\u0644\u0649 \u0627\u0644\u0623\u063a\u0646\u064a\u0627\u0621 \u0627\u0644\u0630\u064a\u0646 \u062c\u0627\u0621\u0648\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u064a\u0637\u0644\u0628\u0648\u0646 \u0627\u0644\u0625\u0630\u0646 \u0628\u0627\u0644\u062a\u062e\u0644\u0641\u060c \u0648\u0647\u0645 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0627\u0644\u0623\u063a\u0646\u064a\u0627\u0621 \u0627\u062e\u062a\u0627\u0631\u0648\u0627 \u0644\u0623\u0646\u0641\u0633\u0647\u0645 \u0627\u0644\u0642\u0639\u0648\u062f \u0645\u0639 \u0627\u0644\u0646\u0633\u0627\u0621 \u0648\u0623\u0647\u0644 \u0627\u0644\u0623\u0639\u0630\u0627\u0631\u060c \u0648\u062e\u062a\u0645 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0642\u0644\u0648\u0628\u0647\u0645 \u0628\u0627\u0644\u0646\u0641\u0627\u0642\u060c \u0641\u0644\u0627 \u064a\u062f\u062e\u0644\u0647\u0627 \u0625\u064a\u0645\u0627\u0646\u060c \u0641\u0647\u0645 \u0644\u0627 \u064a\u0639\u0644\u0645\u0648\u0646 \u0633\u0648\u0621 \u0639\u0627\u0642\u0628\u062a\u0647\u0645 \u0628\u062a\u062e\u0644\u0641\u0647\u0645 \u0639\u0646\u0643 \u0648\u062a\u0631\u0643\u0647\u0645 \u0627\u0644\u062c\u0647\u0627\u062f \u0645\u0639\u0643.","9:94":"\u064a\u0639\u062a\u0630\u0631 \u0625\u0644\u064a\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u062a\u062e\u0644\u0641\u0648\u0646 \u0639\u0646 \u062c\u0647\u0627\u062f \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0628\u0627\u0644\u0623\u0643\u0627\u0630\u064a\u0628 \u0639\u0646\u062f\u0645\u0627 \u062a\u0639\u0648\u062f\u0648\u0646 \u0645\u0650\u0646 \u062c\u0647\u0627\u062f\u0643\u0645 \u0645\u0646 \u063a\u0632\u0648\u0629 (\u062a\u0628\u0648\u0643) \u060c \u0642\u0644 \u0644\u0647\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644-: \u0644\u0627 \u062a\u0639\u062a\u0630\u0631\u0648\u0627 \u0644\u0646 \u0646\u0635\u062f\u0642\u0643\u0645 \u0641\u064a\u0645\u0627 \u062a\u0642\u0648\u0644\u0648\u0646\u060c \u0642\u062f \u0646\u0628\u0623\u0646\u0627 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0623\u0645\u0631\u0643\u0645 \u0645\u0627 \u062d\u0642\u0642 \u0644\u062f\u064a\u0646\u0627 \u0643\u0630\u0628\u0643\u0645\u060c \u0648\u0633\u064a\u0631\u0649 \u0627\u0644\u0644\u0647 \u0639\u0645\u0644\u0643\u0645 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0625\u0646 \u0643\u0646\u062a\u0645 \u062a\u062a\u0648\u0628\u0648\u0646 \u0645\u0646 \u0646\u0641\u0627\u0642\u0643\u0645\u060c \u0623\u0648 \u062a\u0642\u064a\u0645\u0648\u0646 \u0639\u0644\u064a\u0647\u060c \u0648\u0633\u064a\u064f\u0638\u0647\u0631 \u0644\u0644\u0646\u0627\u0633 \u0623\u0639\u0645\u0627\u0644\u0643\u0645 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u062b\u0645 \u062a\u0631\u062c\u0639\u0648\u0646 \u0628\u0639\u062f \u0645\u0645\u0627\u062a\u0643\u0645 \u0625\u0644\u0649 \u0627\u0644\u0630\u064a \u0644\u0627 \u062a\u062e\u0641\u0649 \u0639\u0644\u064a\u0647 \u0628\u0648\u0627\u0637\u0646 \u0623\u0645\u0648\u0631\u0643\u0645 \u0648\u0638\u0648\u0627\u0647\u0631\u0647\u0627\u060c \u0641\u064a\u062e\u0628\u0631\u0643\u0645 \u0628\u0623\u0639\u0645\u0627\u0644\u0643\u0645 \u0643\u0644\u0647\u0627\u060c \u0648\u064a\u062c\u0627\u0632\u064a\u0643\u0645 \u0639\u0644\u064a\u0647\u0627.","9:95":"\u0633\u064a\u062d\u0644\u0641 \u0644\u0643\u0645 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0628\u0627\u0644\u0644\u0647 -\u0643\u0627\u0630\u0628\u064a\u0646 \u0645\u0639\u062a\u0630\u0631\u064a\u0646- \u0625\u0630\u0627 \u0631\u062c\u0639\u062a\u0645 \u0625\u0644\u064a\u0647\u0645 \u0645\u0646 \u0627\u0644\u063a\u0632\u0648; \u0644\u062a\u062a\u0631\u0643\u0648\u0647\u0645 \u062f\u0648\u0646 \u0645\u0633\u0627\u0621\u0644\u0629\u060c \u0641\u0627\u062c\u062a\u0646\u0628\u0648\u0647\u0645 \u0648\u0623\u0639\u0631\u0636\u0648\u0627 \u0639\u0646\u0647\u0645 \u0627\u062d\u062a\u0642\u0627\u0631\u064b\u0627 \u0644\u0647\u0645\u060c \u0625\u0646\u0647\u0645 \u062e\u0628\u062b\u0627\u0621 \u0627\u0644\u0628\u0648\u0627\u0637\u0646\u060c \u0648\u0645\u0643\u0627\u0646\u0647\u0645 \u0627\u0644\u0630\u064a \u064a\u0623\u0648\u0648\u0646 \u0625\u0644\u064a\u0647 \u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u0646\u0627\u0631 \u062c\u0647\u0646\u0645; \u062c\u0632\u0627\u0621 \u0628\u0645\u0627 \u0643\u0627\u0646\u0648\u0627 \u064a\u0643\u0633\u0628\u0648\u0646 \u0645\u0646 \u0627\u0644\u0622\u062b\u0627\u0645 \u0648\u0627\u0644\u062e\u0637\u0627\u064a\u0627.","9:96":"\u064a\u062d\u0644\u0641 \u0644\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0643\u0630\u0628\u064b\u0627; \u0644\u062a\u064e\u0631\u0636\u064e\u0648\u0627 \u0639\u0646\u0647\u0645\u060c \u0641\u0625\u0646 \u0631\u0636\u064a\u062a\u0645 \u0639\u0646\u0647\u0645 -\u0644\u0623\u0646\u0643\u0645 \u0644\u0627 \u062a\u0639\u0644\u0645\u0648\u0646 \u0643\u0630\u0628\u0647\u0645- \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0631\u0636\u0649 \u0639\u0646 \u0647\u0624\u0644\u0627\u0621 \u0648\u0644\u0627 \u063a\u064a\u0631\u0647\u0645 \u0645\u0645\u0646 \u0627\u0633\u062a\u0645\u0631\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0641\u0633\u0648\u0642 \u0648\u0627\u0644\u062e\u0631\u0648\u062c \u0639\u0646 \u0637\u0627\u0639\u0629 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647.","9:97":"\u0627\u0644\u0623\u0639\u0631\u0627\u0628 \u0633\u0643\u0627\u0646 \u0627\u0644\u0628\u0627\u062f\u064a\u0629 \u0623\u0634\u062f \u0643\u0641\u0631\u064b\u0627 \u0648\u0646\u0641\u0627\u0642\u064b\u0627 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u062d\u0627\u0636\u0631\u0629\u060c \u0648\u0630\u0644\u0643 \u0644\u062c\u0641\u0627\u0626\u0647\u0645 \u0648\u0642\u0633\u0648\u0629 \u0642\u0644\u0648\u0628\u0647\u0645 \u0648\u0628\u064f\u0639\u062f\u0647\u0645 \u0639\u0646 \u0627\u0644\u0639\u0644\u0645 \u0648\u0627\u0644\u0639\u0644\u0645\u0627\u0621\u060c \u0648\u0645\u062c\u0627\u0644\u0633 \u0627\u0644\u0648\u0639\u0638 \u0648\u0627\u0644\u0630\u0643\u0631\u060c \u0641\u0647\u0645 \u0644\u0630\u0644\u0643 \u0623\u062d\u0642 \u0628\u0623\u0646 \u0644\u0627 \u064a\u0639\u0644\u0645\u0648\u0627 \u062d\u062f\u0648\u062f \u0627\u0644\u062f\u064a\u0646\u060c \u0648\u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0634\u0631\u0627\u0626\u0639 \u0648\u0627\u0644\u0623\u062d\u0643\u0627\u0645. \u0648\u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645 \u0628\u062d\u0627\u0644 \u0647\u0624\u0644\u0627\u0621 \u062c\u0645\u064a\u0639\u064b\u0627\u060c \u062d\u0643\u064a\u0645 \u0641\u064a \u062a\u062f\u0628\u064a\u0631\u0647 \u0644\u0623\u0645\u0648\u0631 \u0639\u0628\u0627\u062f\u0647.","9:98":"\u0648\u0645\u0646 \u0627\u0644\u0623\u0639\u0631\u0627\u0628 \u0645\u064e\u0646 \u064a\u062d\u062a\u0633\u0628 \u0645\u0627 \u064a\u0646\u0641\u0642 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u063a\u0631\u0627\u0645\u0629 \u0648\u062e\u0633\u0627\u0631\u0629 \u0644\u0627 \u064a\u0631\u062c\u0648 \u0644\u0647 \u062b\u0648\u0627\u0628\u064b\u0627\u060c \u0648\u0644\u0627 \u064a\u062f\u0641\u0639 \u0639\u0646 \u0646\u0641\u0633\u0647 \u0639\u0642\u0627\u0628\u064b\u0627\u060c \u0648\u064a\u0646\u062a\u0638\u0631 \u0628\u0643\u0645 \u0627\u0644\u062d\u0648\u0627\u062f\u062b \u0648\u0627\u0644\u0622\u0641\u0627\u062a\u060c \u0648\u0644\u0643\u0646 \u0627\u0644\u0633\u0648\u0621 \u062f\u0627\u0626\u0631 \u0639\u0644\u064a\u0647\u0645 \u0644\u0627 \u0628\u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646. \u0648\u0627\u0644\u0644\u0647 \u0633\u0645\u064a\u0639 \u0644\u0645\u0627 \u064a\u0642\u0648\u0644\u0648\u0646 \u0639\u0644\u064a\u0645 \u0628\u0646\u064a\u0627\u062a\u0647\u0645 \u0627\u0644\u0641\u0627\u0633\u062f\u0629.","9:99":"\u0648\u0645\u0646 \u0627\u0644\u0623\u0639\u0631\u0627\u0628 \u0645\u064e\u0646 \u064a\u0624\u0645\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u064a\u0642\u0631\u0651\u064f \u0628\u0648\u062d\u062f\u0627\u0646\u064a\u062a\u0647 \u0648\u0628\u0627\u0644\u0628\u0639\u062b \u0628\u0639\u062f \u0627\u0644\u0645\u0648\u062a\u060c \u0648\u0627\u0644\u062b\u0648\u0627\u0628 \u0648\u0627\u0644\u0639\u0642\u0627\u0628\u060c \u0648\u064a\u062d\u062a\u0633\u0628 \u0645\u0627 \u064a\u0646\u0641\u0642 \u0645\u0646 \u0646\u0641\u0642\u0629 \u0641\u064a \u062c\u0647\u0627\u062f \u0627\u0644\u0645\u0634\u0631\u0643\u064a\u0646 \u0642\u0627\u0635\u062f\u064b\u0627 \u0628\u0647\u0627 \u0631\u0636\u0627 \u0627\u0644\u0644\u0647 \u0648\u0645\u062d\u0628\u062a\u0647\u060c \u0648\u064a\u062c\u0639\u0644\u0647\u0627 \u0648\u0633\u064a\u0644\u0629 \u0625\u0644\u0649 \u062f\u0639\u0627\u0621 \u0627\u0644\u0631\u0633\u0648\u0644 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0644\u0647\u060c \u0623\u0644\u0627 \u0625\u0646 \u0647\u0630\u0647 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u062a\u0642\u0631\u0628\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649\u060c \u0633\u064a\u062f\u062e\u0644\u0647\u0645 \u0627\u0644\u0644\u0647 \u0641\u064a \u062c\u0646\u062a\u0647. \u0625\u0646 \u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0644\u0645\u0627 \u0641\u0639\u0644\u0648\u0627 \u0645\u0646 \u0627\u0644\u0633\u064a\u0626\u0627\u062a\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","9:100":"\u0648\u0627\u0644\u0630\u064a\u0646 \u0633\u0628\u0642\u0648\u0627 \u0627\u0644\u0646\u0627\u0633 \u0623\u0648\u0644\u0627 \u0625\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u0646 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0647\u062c\u0631\u0648\u0627 \u0642\u0648\u0645\u0647\u0645 \u0648\u0639\u0634\u064a\u0631\u062a\u0647\u0645 \u0648\u0627\u0646\u062a\u0642\u0644\u0648\u0627 \u0625\u0644\u0649 \u062f\u0627\u0631 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0627\u0644\u0630\u064a\u0646 \u0646\u0635\u0631\u0648\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0639\u0644\u0649 \u0623\u0639\u062f\u0627\u0626\u0647 \u0627\u0644\u0643\u0641\u0627\u0631\u060c \u0648\u0627\u0644\u0630\u064a\u0646 \u0627\u062a\u0628\u0639\u0648\u0647\u0645 \u0628\u0625\u062d\u0633\u0627\u0646 \u0641\u064a \u0627\u0644\u0627\u0639\u062a\u0642\u0627\u062f \u0648\u0627\u0644\u0623\u0642\u0648\u0627\u0644 \u0648\u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0637\u0644\u0628\u064b\u0627 \u0644\u0645\u0631\u0636\u0627\u0629 \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649\u060c \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0630\u064a\u0646 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645 \u0644\u0637\u0627\u0639\u062a\u0647\u0645 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0648\u0631\u0636\u0648\u0627 \u0639\u0646\u0647 \u0644\u0645\u0627 \u0623\u062c\u0632\u0644 \u0644\u0647\u0645 \u0645\u0646 \u0627\u0644\u062b\u0648\u0627\u0628 \u0639\u0644\u0649 \u0637\u0627\u0639\u062a\u0647\u0645 \u0648\u0625\u064a\u0645\u0627\u0646\u0647\u0645\u060c \u0648\u0623\u0639\u062f\u0651\u064e \u0644\u0647\u0645 \u062c\u0646\u0627\u062a \u062a\u062c\u0631\u064a \u062a\u062d\u062a \u0642\u0635\u0648\u0631\u0647\u0627 \u0648\u0623\u0634\u062c\u0627\u0631\u0647\u0627 \u0627\u0644\u0623\u0646\u0647\u0627\u0631 \u062e\u0627\u0644\u062f\u064a\u0646 \u0641\u064a\u0647\u0627 \u0623\u0628\u062f\u064b\u0627\u060c \u0630\u0644\u0643 \u0647\u0648 \u0627\u0644\u0641\u0644\u0627\u062d \u0627\u0644\u0639\u0638\u064a\u0645. \u0648\u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0622\u064a\u0629 \u062a\u0632\u0643\u064a\u0629 \u0644\u0644\u0635\u062d\u0627\u0628\u0629 -\u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645- \u0648\u062a\u0639\u062f\u064a\u0644 \u0644\u0647\u0645\u060c \u0648\u062b\u0646\u0627\u0621 \u0639\u0644\u064a\u0647\u0645; \u0648\u0644\u0647\u0630\u0627 \u0641\u0625\u0646 \u062a\u0648\u0642\u064a\u0631\u0647\u0645 \u0645\u0646 \u0623\u0635\u0648\u0644 \u0627\u0644\u0625\u064a\u0645\u0627\u0646.","9:101":"\u0648\u0645\u0646 \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u0630\u064a\u0646 \u062d\u0648\u0644 (\u0627\u0644\u0645\u062f\u064a\u0646\u0629) \u0623\u0639\u0631\u0627\u0628 \u0645\u0646\u0627\u0641\u0642\u0648\u0646\u060c \u0648\u0645\u0646 \u0623\u0647\u0644 (\u0627\u0644\u0645\u062f\u064a\u0646\u0629) \u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0623\u0642\u0627\u0645\u0648\u0627 \u0639\u0644\u0649 \u0627\u0644\u0646\u0641\u0627\u0642\u060c \u0648\u0627\u0632\u062f\u0627\u062f\u0648\u0627 \u0641\u064a\u0647 \u0637\u063a\u064a\u0627\u0646\u064b\u0627\u060c \u0628\u062d\u064a\u062b \u064a\u062e\u0641\u0649 \u0639\u0644\u064a\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0623\u0645\u0631\u0647\u0645\u060c \u0646\u062d\u0646 \u0646\u0639\u0644\u0645\u0647\u0645\u060c \u0633\u0646\u0639\u0630\u0628\u0647\u0645 \u0645\u0631\u062a\u064a\u0646: \u0628\u0627\u0644\u0642\u062a\u0644 \u0648\u0627\u0644\u0633\u0628\u064a \u0648\u0627\u0644\u0641\u0636\u064a\u062d\u0629 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0628\u0639\u0630\u0627\u0628 \u0627\u0644\u0642\u0628\u0631 \u0628\u0639\u062f \u0627\u0644\u0645\u0648\u062a\u060c \u062b\u0645 \u064a\u064f\u0631\u064e\u062f\u0651\u064f\u0648\u0646 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0625\u0644\u0649 \u0639\u0630\u0627\u0628 \u0639\u0638\u064a\u0645 \u0641\u064a \u0646\u0627\u0631 \u062c\u0647\u0646\u0645.","9:102":"\u0648\u0622\u062e\u0631\u0648\u0646 \u0645\u0646 \u0623\u0647\u0644 (\u0627\u0644\u0645\u062f\u064a\u0646\u0629) \u0648\u0645\u0645\u0646 \u062d\u0648\u0644\u0647\u0627\u060c \u0627\u0639\u062a\u0631\u0641\u0648\u0627 \u0628\u0630\u0646\u0648\u0628\u0647\u0645 \u0648\u0646\u062f\u0645\u0648\u0627 \u0639\u0644\u064a\u0647\u0627 \u0648\u062a\u0627\u0628\u0648\u0627 \u0645\u0646\u0647\u0627\u060c \u062e\u0644\u0637\u0648\u0627 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0635\u0627\u0644\u062d -\u0648\u0647\u0648 \u0627\u0644\u062a\u0648\u0628\u0629 \u0648\u0627\u0644\u0646\u062f\u0645 \u0648\u0627\u0644\u0627\u0639\u062a\u0631\u0627\u0641 \u0628\u0627\u0644\u0630\u0646\u0628 \u0648\u063a\u064a\u0631 \u0630\u0644\u0643 \u0645\u0646 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0635\u0627\u0644\u062d\u0629- \u0628\u0622\u062e\u0631 \u0633\u064a\u0651\u0650\u0626 -\u0648\u0647\u0648 \u0627\u0644\u062a\u062e\u0644\u0641 \u0639\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u063a\u064a\u0631\u0647 \u0645\u0646 \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0633\u064a\u0626\u0629- \u0639\u0633\u0649 \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u0648\u0641\u0642\u0647\u0645 \u0644\u0644\u062a\u0648\u0628\u0629 \u0648\u064a\u0642\u0628\u0644\u0647\u0627 \u0645\u0646\u0647\u0645. \u0625\u0646 \u0627\u0644\u0644\u0647 \u063a\u0641\u0648\u0631 \u0644\u0639\u0628\u0627\u062f\u0647\u060c \u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","9:103":"\u062e\u0630 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0645\u0646 \u0623\u0645\u0648\u0627\u0644 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u062a\u0627\u0626\u0628\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u062e\u0644\u0637\u0648\u0627 \u0639\u0645\u0644\u0627 \u0635\u0627\u0644\u062d\u0627 \u0648\u0622\u062e\u0631 \u0633\u064a\u0626\u0627 \u0635\u062f\u0642\u0629 \u062a\u0637\u0647\u0631\u0647\u0645 \u0645\u0650\u0646 \u062f\u0646\u0633 \u0630\u0646\u0648\u0628\u0647\u0645\u060c \u0648\u062a\u0631\u0641\u0639\u0647\u0645 \u0639\u0646 \u0645\u0646\u0627\u0632\u0644 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0625\u0644\u0649 \u0645\u0646\u0627\u0632\u0644 \u0627\u0644\u0645\u062e\u0644\u0635\u064a\u0646\u060c \u0648\u0627\u062f\u0639 \u0644\u0647\u0645 \u0628\u0627\u0644\u0645\u063a\u0641\u0631\u0629 \u0644\u0630\u0646\u0648\u0628\u0647\u0645 \u0648\u0627\u0633\u062a\u063a\u0641\u0631 \u0644\u0647\u0645 \u0645\u0646\u0647\u0627\u060c \u0625\u0646 \u062f\u0639\u0627\u0621\u0643 \u0648\u0627\u0633\u062a\u063a\u0641\u0627\u0631\u0643 \u0631\u062d\u0645\u0629 \u0648\u0637\u0645\u0623\u0646\u064a\u0646\u0629 \u0644\u0647\u0645. \u0648\u0627\u0644\u0644\u0647 \u0633\u0645\u064a\u0639 \u0644\u0643\u0644 \u062f\u0639\u0627\u0621 \u0648\u0642\u0648\u0644\u060c \u0639\u0644\u064a\u0645 \u0628\u0623\u062d\u0648\u0627\u0644 \u0627\u0644\u0639\u0628\u0627\u062f \u0648\u0646\u064a\u0627\u062a\u0647\u0645\u060c \u0648\u0633\u064a\u062c\u0627\u0632\u064a \u0643\u0644\u0651\u064e \u0639\u0627\u0645\u0644 \u0628\u0639\u0645\u0644\u0647.","9:104":"\u0623\u0644\u0645 \u064a\u0639\u0644\u0645 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u062a\u062e\u0644\u0641\u0648\u0646 \u0639\u0646 \u0627\u0644\u062c\u0647\u0627\u062f \u0648\u063a\u064a\u0631\u0647\u0645 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0647\u0648 \u0627\u0644\u0630\u064a \u064a\u0642\u0628\u0644 \u062a\u0648\u0628\u0629 \u0639\u0628\u0627\u062f\u0647\u060c \u0648\u064a\u0623\u062e\u0630 \u0627\u0644\u0635\u062f\u0642\u0627\u062a \u0648\u064a\u062b\u064a\u0628 \u0639\u0644\u064a\u0647\u0627\u060c \u0648\u0623\u0646 \u0627\u0644\u0644\u0647 \u0647\u0648 \u0627\u0644\u062a\u0648\u0627\u0628 \u0644\u0639\u0628\u0627\u062f\u0647 \u0625\u0630\u0627 \u0631\u062c\u0639\u0648\u0627 \u0625\u0644\u0649 \u0637\u0627\u0639\u062a\u0647\u060c \u0627\u0644\u0631\u062d\u064a\u0645 \u0628\u0647\u0645 \u0625\u0630\u0627 \u0623\u0646\u0627\u0628\u0648\u0627 \u0625\u0644\u0649 \u0631\u0636\u0627\u0647\u061f","9:105":"\u0648\u0642\u0644 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0644\u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u062a\u062e\u0644\u0651\u0650\u0641\u064a\u0646 \u0639\u0646 \u0627\u0644\u062c\u0647\u0627\u062f: \u0627\u0639\u0645\u0644\u0648\u0627 \u0644\u0644\u0647 \u0628\u0645\u0627 \u064a\u0631\u0636\u064a\u0647 \u0645\u0646 \u0637\u0627\u0639\u062a\u0647\u060c \u0648\u0623\u062f\u0627\u0621 \u0641\u0631\u0627\u0626\u0636\u0647\u060c \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0627\u0644\u0645\u0639\u0627\u0635\u064a\u060c \u0641\u0633\u064a\u0631\u0649 \u0627\u0644\u0644\u0647 \u0639\u0645\u0644\u0643\u0645 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646\u060c \u0648\u0633\u064a\u062a\u0628\u064a\u0646 \u0623\u0645\u0631\u0643\u0645\u060c \u0648\u0633\u062a\u0631\u062c\u0639\u0648\u0646 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u0629 \u0625\u0644\u0649 \u0645\u064e\u0646 \u064a\u0639\u0644\u0645 \u0633\u0631\u0643\u0645 \u0648\u062c\u0647\u0631\u0643\u0645\u060c \u0641\u064a\u062e\u0628\u0631\u0643\u0645 \u0628\u0645\u0627 \u0643\u0646\u062a\u0645 \u062a\u0639\u0645\u0644\u0648\u0646. \u0648\u0641\u064a \u0647\u0630\u0627 \u062a\u0647\u062f\u064a\u062f \u0648\u0648\u0639\u064a\u062f \u0644\u0645\u0646 \u0627\u0633\u062a\u0645\u0631 \u0639\u0644\u0649 \u0628\u0627\u0637\u0644\u0647 \u0648\u0637\u063a\u064a\u0627\u0646\u0647.","9:106":"\u0648\u0645\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u062a\u062e\u0644\u0641\u064a\u0646 \u0639\u0646\u0643\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0641\u064a \u063a\u0632\u0648\u0629 (\u062a\u0628\u0648\u0643) \u0622\u062e\u0631\u0648\u0646 \u0645\u0624\u062e\u0631\u0648\u0646; \u0644\u064a\u0642\u0636\u064a \u0627\u0644\u0644\u0647 \u0641\u064a\u0647\u0645 \u0645\u0627 \u0647\u0648 \u0642\u0627\u0636. \u0648\u0647\u0624\u0644\u0627\u0621 \u0647\u0645 \u0627\u0644\u0630\u064a\u0646 \u0646\u062f\u0645\u0648\u0627 \u0639\u0644\u0649 \u0645\u0627 \u0641\u0639\u0644\u0648\u0627\u060c \u0648\u0647\u0645: \u0645\u064f\u0631\u0627\u0631\u0629 \u0628\u0646 \u0627\u0644\u0631\u0628\u064a\u0639\u060c \u0648\u0643\u0639\u0628 \u0628\u0646 \u0645\u0627\u0644\u0643\u060c \u0648\u0647\u0644\u0627\u0644 \u0628\u0646 \u0623\u064f\u0645\u064a\u0651\u064e\u0629\u060c \u0625\u0645\u0627 \u064a\u0639\u0630\u0628\u0647\u0645 \u0627\u0644\u0644\u0647\u060c \u0648\u0625\u0645\u0627 \u064a\u0639\u0641\u0648 \u0639\u0646\u0647\u0645. \u0648\u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645 \u0628\u0645\u0646 \u064a\u0633\u062a\u062d\u0642 \u0627\u0644\u0639\u0642\u0648\u0628\u0629 \u0623\u0648 \u0627\u0644\u0639\u0641\u0648\u060c \u062d\u0643\u064a\u0645 \u0641\u064a \u0643\u0644 \u0623\u0642\u0648\u0627\u0644\u0647 \u0648\u0623\u0641\u0639\u0627\u0644\u0647.","9:107":"\u0648\u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0627\u0644\u0630\u064a\u0646 \u0628\u0646\u0648\u0627 \u0645\u0633\u062c\u062f\u064b\u0627; \u0645\u0636\u0627\u0631\u0629 \u0644\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0648\u0643\u0641\u0631\u064b\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u062a\u0641\u0631\u064a\u0642\u064b\u0627 \u0628\u064a\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646\u060c \u0644\u064a\u0635\u0644\u064a \u0641\u064a\u0647 \u0628\u0639\u0636\u0647\u0645 \u0648\u064a\u062a\u0631\u0643 \u0645\u0633\u062c\u062f (\u0642\u0628\u0627\u0621) \u0627\u0644\u0630\u064a \u064a\u0635\u0644\u064a \u0641\u064a\u0647 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646\u060c \u0641\u064a\u062e\u062a\u0644\u0641 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0648\u064a\u062a\u0641\u0631\u0642\u0648\u0627 \u0628\u0633\u0628\u0628 \u0630\u0644\u0643\u060c \u0648\u0627\u0646\u062a\u0638\u0627\u0631\u0627 \u0644\u0645\u0646 \u062d\u0627\u0631\u0628 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0645\u0646 \u0642\u0628\u0644 -\u0648\u0647\u0648 \u0623\u0628\u0648 \u0639\u0627\u0645\u0631 \u0627\u0644\u0631\u0627\u0647\u0628 \u0627\u0644\u0641\u0627\u0633\u0642- \u0644\u064a\u0643\u0648\u0646 \u0645\u0643\u0627\u0646\u064b\u0627 \u0644\u0644\u0643\u064a\u062f \u0644\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0648\u0644\u064a\u062d\u0644\u0641\u0646\u0651\u064e \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0623\u0646\u0647\u0645 \u0645\u0627 \u0623\u0631\u0627\u062f\u0648\u0627 \u0628\u0628\u0646\u0627\u0626\u0647 \u0625\u0644\u0627 \u0627\u0644\u062e\u064a\u0631 \u0648\u0627\u0644\u0631\u0641\u0642 \u0628\u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u0627\u0644\u062a\u0648\u0633\u0639\u0629 \u0639\u0644\u0649 \u0627\u0644\u0636\u0639\u0641\u0627\u0621 \u0627\u0644\u0639\u0627\u062c\u0632\u064a\u0646 \u0639\u0646 \u0627\u0644\u0633\u064a\u0631 \u0625\u0644\u0649 \u0645\u0633\u062c\u062f (\u0642\u0628\u0627\u0621) \u060c \u0648\u0627\u0644\u0644\u0647 \u064a\u0634\u0647\u062f \u0625\u0646\u0647\u0645 \u0644\u0643\u0627\u0630\u0628\u0648\u0646 \u0641\u064a\u0645\u0627 \u064a\u062d\u0644\u0641\u0648\u0646 \u0639\u0644\u064a\u0647. \u0648\u0642\u062f \u0647\u064f\u062f\u0650\u0645 \u0627\u0644\u0645\u0633\u062c\u062f \u0648\u0623\u064f\u062d\u0631\u0650\u0642.","9:108":"\u0644\u0627 \u062a\u0642\u0645 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0644\u0644\u0635\u0644\u0627\u0629 \u0641\u064a \u0630\u0644\u0643 \u0627\u0644\u0645\u0633\u062c\u062f \u0623\u0628\u062f\u064b\u0627; \u0641\u0625\u0646 \u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u0630\u064a \u0623\u064f\u0633\u0651\u0650\u0633\u064e \u0639\u0644\u0649 \u0627\u0644\u062a\u0642\u0648\u0649 \u0645\u0646 \u0623\u0648\u0644 \u064a\u0648\u0645 -\u0648\u0647\u0648 \u0645\u0633\u062c\u062f (\u0642\u0628\u0627\u0621) - \u0623\u0648\u0644\u0649 \u0623\u0646 \u062a\u0642\u0648\u0645 \u0641\u064a\u0647 \u0644\u0644\u0635\u0644\u0627\u0629\u060c \u0641\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0645\u0633\u062c\u062f \u0631\u062c\u0627\u0644 \u064a\u062d\u0628\u0648\u0646 \u0623\u0646 \u064a\u062a\u0637\u0647\u0631\u0648\u0627 \u0628\u0627\u0644\u0645\u0627\u0621 \u0645\u0646 \u0627\u0644\u0646\u062c\u0627\u0633\u0627\u062a \u0648\u0627\u0644\u0623\u0642\u0630\u0627\u0631\u060c \u0643\u0645\u0627 \u064a\u062a\u0637\u0647\u0631\u0648\u0646 \u0628\u0627\u0644\u062a\u0648\u0631\u0639 \u0648\u0627\u0644\u0627\u0633\u062a\u063a\u0641\u0627\u0631 \u0645\u0646 \u0627\u0644\u0630\u0646\u0648\u0628 \u0648\u0627\u0644\u0645\u0639\u0627\u0635\u064a. \u0648\u0627\u0644\u0644\u0647 \u064a\u062d\u0628 \u0627\u0644\u0645\u062a\u0637\u0647\u0631\u064a\u0646. \u0648\u0625\u0630\u0627 \u0643\u0627\u0646 \u0645\u0633\u062c\u062f (\u0642\u0628\u0627\u0621) \u0642\u062f \u0623\u064f\u0633\u0651\u0650\u0633\u064e \u0639\u0644\u0649 \u0627\u0644\u062a\u0642\u0648\u0649 \u0645\u0646 \u0623\u0648\u0644 \u064a\u0648\u0645\u060c \u0641\u0645\u0633\u062c\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0643\u0630\u0644\u0643 \u0628\u0637\u0631\u064a\u0642 \u0627\u0644\u0623\u0648\u0644\u0649 \u0648\u0627\u0644\u0623\u062d\u0631\u0649.","9:109":"\u0644\u0627 \u064a\u0633\u062a\u0648\u064a \u0645\u064e\u0646 \u0623\u0633\u0651\u064e\u0633 \u0628\u0646\u064a\u0627\u0646\u0647 \u0639\u0644\u0649 \u062a\u0642\u0648\u0649 \u0627\u0644\u0644\u0647 \u0648\u0637\u0627\u0639\u062a\u0647 \u0648\u0645\u0631\u0636\u0627\u062a\u0647\u060c \u0648\u0645\u0646 \u0623\u0633\u0651\u064e\u0633 \u0628\u0646\u064a\u0627\u0646\u0647 \u0639\u0644\u0649 \u0637\u0631\u0641 \u062d\u0641\u0631\u0629 \u0645\u062a\u062f\u0627\u0639\u064a\u0629 \u0644\u0644\u0633\u0642\u0648\u0637\u060c \u0641\u0628\u0646\u0649 \u0645\u0633\u062c\u062f\u064b\u0627 \u0636\u0631\u0627\u0631\u064b\u0627 \u0648\u0643\u0641\u0631\u064b\u0627 \u0648\u062a\u0641\u0631\u064a\u0642\u064b\u0627 \u0628\u064a\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0641\u0623\u062f\u0651\u064e\u0649 \u0628\u0647 \u0630\u0644\u0643 \u0625\u0644\u0649 \u0627\u0644\u0633\u0642\u0648\u0637 \u0641\u064a \u0646\u0627\u0631 \u062c\u0647\u0646\u0645. \u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0647\u062f\u064a \u0627\u0644\u0642\u0648\u0645 \u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0627\u0644\u0645\u062a\u062c\u0627\u0648\u0632\u064a\u0646 \u062d\u062f\u0648\u062f\u0647.","9:110":"\u0644\u0627 \u064a\u0632\u0627\u0644 \u0628\u0646\u064a\u0627\u0646 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0627\u0644\u0630\u064a \u0628\u0646\u0648\u0647 \u0645\u0636\u0627\u0631\u0651\u064e\u0629 \u0644\u0645\u0633\u062c\u062f (\u0642\u0628\u0627\u0621) \u0634\u0643\u064b\u0627 \u0648\u0646\u0641\u0627\u0642\u064b\u0627 \u0645\u0627\u0643\u062b\u064b\u0627 \u0641\u064a \u0642\u0644\u0648\u0628\u0647\u0645\u060c \u0625\u0644\u0649 \u0623\u0646 \u062a\u062a\u0642\u0637\u0639 \u0642\u0644\u0648\u0628\u0647\u0645 \u0628\u0642\u062a\u0644\u0647\u0645 \u0623\u0648 \u0645\u0648\u062a\u0647\u0645\u060c \u0623\u0648 \u0628\u0646\u062f\u0645\u0647\u0645 \u063a\u0627\u064a\u0629 \u0627\u0644\u0646\u062f\u0645\u060c \u0648\u062a\u0648\u0628\u062a\u0647\u0645 \u0625\u0644\u0649 \u0631\u0628\u0647\u0645\u060c \u0648\u062e\u0648\u0641\u0647\u0645 \u0645\u0646\u0647 \u063a\u0627\u064a\u0629 \u0627\u0644\u062e\u0648\u0641. \u0648\u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0645 \u0628\u0645\u0627 \u0639\u0644\u064a\u0647 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0645\u0646 \u0627\u0644\u0634\u0643 \u0648\u0645\u0627 \u0642\u0635\u062f\u0648\u0627 \u0641\u064a \u0628\u0646\u0627\u0626\u0647\u0645\u060c \u062d\u0643\u064a\u0645 \u0641\u064a \u062a\u062f\u0628\u064a\u0631 \u0623\u0645\u0648\u0631 \u062e\u0644\u0642\u0647.","9:111":"\u0625\u0646 \u0627\u0644\u0644\u0647 \u0627\u0634\u062a\u0631\u0649 \u0645\u0646 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0623\u0646\u0641\u0633\u0647\u0645 \u0628\u0623\u0646 \u0644\u0647\u0645 \u0641\u064a \u0645\u0642\u0627\u0628\u0644 \u0630\u0644\u0643 \u0627\u0644\u062c\u0646\u0629\u060c \u0648\u0645\u0627 \u0623\u0639\u062f \u0627\u0644\u0644\u0647 \u0641\u064a\u0647\u0627 \u0645\u0646 \u0627\u0644\u0646\u0639\u064a\u0645 \u0644\u0628\u0630\u0644\u0647\u0645 \u0646\u0641\u0648\u0633\u0647\u0645 \u0648\u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0641\u064a \u062c\u0647\u0627\u062f \u0623\u0639\u062f\u0627\u0626\u0647 \u0644\u0625\u0639\u0644\u0627\u0621 \u0643\u0644\u0645\u062a\u0647 \u0648\u0625\u0638\u0647\u0627\u0631 \u062f\u064a\u0646\u0647\u060c \u0641\u064a\u064e\u0642\u0652\u062a\u0644\u0648\u0646 \u0648\u064a\u064f\u0642\u062a\u064e\u0644\u0648\u0646\u060c \u0648\u0639\u062f\u064b\u0627 \u0639\u0644\u064a\u0647 \u062d\u0642\u064b\u0627 \u0641\u064a \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0627\u0644\u0645\u0646\u0632\u0644\u0629 \u0639\u0644\u0649 \u0645\u0648\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644 \u0627\u0644\u0645\u0646\u0632\u0644 \u0639\u0644\u0649 \u0639\u064a\u0633\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645\u060c \u0648\u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0645\u0646\u0632\u0644 \u0639\u0644\u0649 \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645. \u0648\u0644\u0627 \u0623\u062d\u062f \u0623\u0648\u0641\u0649 \u0628\u0639\u0647\u062f\u0647 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0644\u0645\u0646 \u0648\u0641\u0651\u064e\u0649 \u0628\u0645\u0627 \u0639\u0627\u0647\u062f \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u060c \u0641\u0623\u0638\u0647\u0650\u0631\u0648\u0627 \u0627\u0644\u0633\u0631\u0648\u0631-\u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646- \u0628\u0628\u064a\u0639\u0643\u0645 \u0627\u0644\u0630\u064a \u0628\u0627\u064a\u0639\u062a\u0645 \u0627\u0644\u0644\u0647 \u0628\u0647\u060c \u0648\u0628\u0645\u0627 \u0648\u0639\u062f\u0643\u0645 \u0628\u0647 \u0645\u0646 \u0627\u0644\u062c\u0646\u0629 \u0648\u0627\u0644\u0631\u0636\u0648\u0627\u0646\u060c \u0648\u0630\u0644\u0643 \u0627\u0644\u0628\u064a\u0639 \u0647\u0648 \u0627\u0644\u0641\u0644\u0627\u062d \u0627\u0644\u0639\u0638\u064a\u0645.","9:112":"\u0648\u0645\u0646 \u0635\u0641\u0627\u062a \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0644\u0647\u0645 \u0627\u0644\u0628\u0634\u0627\u0631\u0629 \u0628\u062f\u062e\u0648\u0644 \u0627\u0644\u062c\u0646\u0629 \u0623\u0646\u0647\u0645 \u0627\u0644\u062a\u0627\u0626\u0628\u0648\u0646 \u0627\u0644\u0631\u0627\u062c\u0639\u0648\u0646 \u0639\u0645\u0627 \u0643\u0631\u0647\u0647 \u0627\u0644\u0644\u0647 \u0625\u0644\u0649 \u0645\u0627 \u064a\u062d\u0628\u0647 \u0648\u064a\u0631\u0636\u0627\u0647\u060c \u0627\u0644\u0630\u064a\u0646 \u0623\u062e\u0644\u0635\u0648\u0627 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0648\u062c\u062f\u0648\u0627 \u0641\u064a \u0637\u0627\u0639\u062a\u0647\u060c \u0627\u0644\u0630\u064a\u0646 \u064a\u062d\u0645\u062f\u0648\u0646 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0643\u0644 \u0645\u0627 \u0627\u0645\u062a\u062d\u0646\u0647\u0645 \u0628\u0647 \u0645\u0646 \u062e\u064a\u0631 \u0623\u0648 \u0634\u0631\u060c \u0627\u0644\u0635\u0627\u0626\u0645\u0648\u0646\u060c \u0627\u0644\u0631\u0627\u0643\u0639\u0648\u0646 \u0641\u064a \u0635\u0644\u0627\u062a\u0647\u0645\u060c \u0627\u0644\u0633\u0627\u062c\u062f\u0648\u0646 \u0641\u064a\u0647\u0627\u060c \u0627\u0644\u0630\u064a\u0646 \u064a\u0623\u0645\u0631\u0648\u0646 \u0627\u0644\u0646\u0627\u0633 \u0628\u0643\u0644 \u0645\u0627 \u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0628\u0647\u060c \u0648\u064a\u0646\u0647\u0648\u0646\u0647\u0645 \u0639\u0646 \u0643\u0644 \u0645\u0627 \u0646\u0647\u0649 \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0627\u0644\u0645\u0624\u062f\u0648\u0646 \u0641\u0631\u0627\u0626\u0636 \u0627\u0644\u0644\u0647 \u0627\u0644\u0645\u0646\u062a\u0647\u0648\u0646 \u0625\u0644\u0649 \u0623\u0645\u0631\u0647 \u0648\u0646\u0647\u064a\u0647\u060c \u0627\u0644\u0642\u0627\u0626\u0645\u0648\u0646 \u0639\u0644\u0649 \u0637\u0627\u0639\u062a\u0647\u060c \u0627\u0644\u0648\u0627\u0642\u0641\u0648\u0646 \u0639\u0646\u062f \u062d\u062f\u0648\u062f\u0647. \u0648\u0628\u0634\u0651\u0650\u0631 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0628\u064a- \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0627\u0644\u0645\u062a\u0635\u0641\u064a\u0646 \u0628\u0647\u0630\u0647 \u0627\u0644\u0635\u0641\u0627\u062a \u0628\u0631\u0636\u0648\u0627\u0646 \u0627\u0644\u0644\u0647 \u0648\u062c\u0646\u062a\u0647.","9:113":"\u0645\u0627 \u0643\u0627\u0646 \u064a\u0646\u0628\u063a\u064a \u0644\u0644\u0646\u0628\u064a \u0645\u062d\u0645\u062f \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0623\u0646 \u064a\u062f\u0639\u0648\u0627 \u0628\u0627\u0644\u0645\u063a\u0641\u0631\u0629 \u0644\u0644\u0645\u0634\u0631\u0643\u064a\u0646\u060c \u0648\u0644\u0648 \u0643\u0627\u0646\u0648\u0627 \u0630\u0648\u064a \u0642\u0631\u0627\u0628\u0629 \u0644\u0647\u0645 \u0645\u0650\u0646 \u0628\u0639\u062f \u0645\u0627 \u0645\u0627\u062a\u0648\u0627 \u0639\u0644\u0649 \u0634\u0631\u0643\u0647\u0645 \u0628\u0627\u0644\u0644\u0647 \u0648\u0639\u0628\u0627\u062f\u0629 \u0627\u0644\u0623\u0648\u062b\u0627\u0646\u060c \u0648\u062a\u0628\u064a\u0646 \u0644\u0647\u0645 \u0623\u0646\u0647\u0645 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u062c\u062d\u064a\u0645 \u0644\u0645\u0648\u062a\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u0634\u0631\u0643\u060c \u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u063a\u0641\u0631 \u0644\u0644\u0645\u0634\u0631\u0643\u064a\u0646\u060c \u0643\u0645\u0627 \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: {\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0644\u0627 \u064a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0623\u064e\u0646\u0652 \u064a\u064f\u0634\u0652\u0631\u064e\u0643\u064e \u0628\u0650\u0647\u0650} \u0648\u0643\u0645\u0627 \u0642\u0627\u0644 \u0633\u0628\u062d\u0627\u0646\u0647: {\u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0645\u064e\u0646\u0652 \u064a\u064f\u0634\u0652\u0631\u0650\u0643\u0652 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0641\u064e\u0642\u064e\u062f\u0652 \u062d\u064e\u0631\u0651\u064e\u0645\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650 \u0627\u0644\u0652\u062c\u064e\u0646\u0651\u064e\u0629\u064e} .","9:114":"\u0648\u0645\u0627 \u0643\u0627\u0646 \u0627\u0633\u062a\u063a\u0641\u0627\u0631 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0644\u0623\u0628\u064a\u0647 \u0627\u0644\u0645\u0634\u0631\u0643\u060c \u0625\u0644\u0627 \u0639\u0646 \u0645\u0648\u0639\u062f\u0629 \u0648\u0639\u062f\u0647\u0627 \u0625\u064a\u0627\u0647\u060c \u0648\u0647\u064a \u0642\u0648\u0644\u0647: {\u0633\u064e\u0623\u064e\u0633\u0652\u062a\u064e\u063a\u0652\u0641\u0650\u0631\u064f \u0644\u064e\u0643\u064e \u0631\u064e\u0628\u0651\u0650\u064a \u0625\u0650\u0646\u0651\u064e\u0647\u064f \u0643\u064e\u0627\u0646\u064e \u0628\u0650\u064a \u062d\u064e\u0641\u0650\u064a\u0651\u064b\u0627} . \u0641\u0644\u0645\u0627 \u062a\u0628\u064a\u0651\u064e\u0646 \u0644\u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0623\u0646 \u0623\u0628\u0627\u0647 \u0639\u062f\u0648 \u0644\u0644\u0647 \u0648\u0644\u0645 \u064a\u0646\u0641\u0639 \u0641\u064a\u0647 \u0627\u0644\u0648\u0639\u0638 \u0648\u0627\u0644\u062a\u0630\u0643\u064a\u0631\u060c \u0648\u0623\u0646\u0647 \u0633\u064a\u0645\u0648\u062a \u0643\u0627\u0641\u0631\u064b\u0627\u060c \u062a\u0631\u0643\u0647 \u0648\u062a\u0631\u0643 \u0627\u0644\u0627\u0633\u062a\u063a\u0641\u0627\u0631 \u0644\u0647\u060c \u0648\u062a\u0628\u0631\u0623 \u0645\u0646\u0647. \u0625\u0646 \u0625\u0628\u0631\u0627\u0647\u064a\u0645 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645 \u0639\u0638\u064a\u0645 \u0627\u0644\u062a\u0636\u0631\u0639 \u0644\u0644\u0647\u060c \u0643\u062b\u064a\u0631 \u0627\u0644\u0635\u0641\u062d \u0639\u0645\u0627 \u064a\u0635\u062f\u0631 \u0645\u0650\u0646 \u0642\u0648\u0645\u0647 \u0645\u0646 \u0627\u0644\u0632\u0644\u0627\u062a.","9:115":"\u0648\u0645\u0627 \u0643\u0627\u0646 \u0627\u0644\u0644\u0647 \u0644\u064a\u0636\u0644\u0651\u064e \u0642\u0648\u0645\u064b\u0627 \u0628\u0639\u062f \u0623\u0646 \u0645\u064e\u0646\u0651\u064e \u0639\u0644\u064a\u0647\u0645 \u0628\u0627\u0644\u0647\u062f\u0627\u064a\u0629 \u0648\u0627\u0644\u062a\u0648\u0641\u064a\u0642 \u062d\u062a\u0649 \u064a\u0628\u064a\u0651\u0650\u0646 \u0644\u0647\u0645 \u0645\u0627 \u064a\u062a\u0642\u0648\u0646\u0647 \u0628\u0647\u060c \u0648\u0645\u0627 \u064a\u062d\u062a\u0627\u062c\u0648\u0646 \u0625\u0644\u064a\u0647 \u0641\u064a \u0623\u0635\u0648\u0644 \u0627\u0644\u062f\u064a\u0646 \u0648\u0641\u0631\u0648\u0639\u0647. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0628\u0643\u0644 \u0634\u064a\u0621 \u0639\u0644\u064a\u0645\u060c \u0641\u0642\u062f \u0639\u0644\u0651\u064e\u0645\u0643\u0645 \u0645\u0627 \u0644\u0645 \u062a\u0643\u0648\u0646\u0648\u0627 \u062a\u0639\u0644\u0645\u0648\u0646\u060c \u0648\u0628\u064a\u0651\u064e\u0646 \u0644\u0643\u0645 \u0645\u0627 \u0628\u0647 \u062a\u0646\u062a\u0641\u0639\u0648\u0646\u060c \u0648\u0623\u0642\u0627\u0645 \u0627\u0644\u062d\u062c\u0629 \u0639\u0644\u064a\u0643\u0645 \u0628\u0625\u0628\u0644\u0627\u063a\u0643\u0645 \u0631\u0633\u0627\u0644\u062a\u0647.","9:116":"\u0625\u0646 \u0627\u0644\u0644\u0647 \u0645\u0627\u0644\u0643 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0648\u0645\u0627 \u0641\u064a\u0647\u0646 \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647 \u0641\u064a \u0627\u0644\u062e\u0644\u0642 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0648\u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0648\u0627\u0644\u062a\u0634\u0631\u064a\u0639\u060c \u064a\u062d\u064a\u064a \u0645\u064e\u0646 \u064a\u0634\u0627\u0621 \u0648\u064a\u0645\u064a\u062a \u0645\u064e\u0646 \u064a\u0634\u0627\u0621\u060c \u0648\u0645\u0627 \u0644\u0643\u0645 \u0645\u0650\u0646 \u0623\u062d\u062f \u063a\u064a\u0631 \u0627\u0644\u0644\u0647 \u064a\u062a\u0648\u0644\u0649 \u0623\u0645\u0648\u0631\u0643\u0645\u060c \u0648\u0644\u0627 \u0646\u0635\u064a\u0631 \u064a\u0646\u0635\u0631\u0643\u0645 \u0639\u0644\u0649 \u0639\u062f\u0648\u0643\u0645.","9:117":"\u0644\u0642\u062f \u0648\u0641\u0651\u064e\u0642 \u0627\u0644\u0644\u0647 \u0646\u0628\u064a\u0647 \u0645\u062d\u0645\u062f\u0627 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0625\u0644\u0649 \u0627\u0644\u0625\u0646\u0627\u0628\u0629 \u0625\u0644\u064a\u0647 \u0648\u0637\u0627\u0639\u062a\u0647\u060c \u0648\u062a\u0627\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0647\u062c\u0631\u0648\u0627 \u062f\u064a\u0627\u0631\u0647\u0645 \u0648\u0639\u0634\u064a\u0631\u062a\u0647\u0645 \u0625\u0644\u0649 \u062f\u0627\u0631 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u062a\u0627\u0628 \u0639\u0644\u0649 \u0623\u0646\u0635\u0627\u0631 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0627\u0644\u0630\u064a\u0646 \u062e\u0631\u062c\u0648\u0627 \u0645\u0639\u0647 \u0644\u0642\u062a\u0627\u0644 \u0627\u0644\u0623\u0639\u062f\u0627\u0621 \u0641\u064a \u063a\u0632\u0648\u0629 (\u062a\u0628\u0648\u0643) \u0641\u064a \u062d\u0631\u0651\u064d \u0634\u062f\u064a\u062f\u060c \u0648\u0636\u064a\u0642 \u0645\u0646 \u0627\u0644\u0632\u0627\u062f \u0648\u0627\u0644\u0638\u0651\u064e\u0647\u0652\u0631\u060c \u0644\u0642\u062f \u062a\u0627\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645 \u0645\u0646 \u0628\u0639\u062f \u0645\u0627 \u0643\u0627\u062f \u064a\u064e\u0645\u064a\u0644 \u0642\u0644\u0648\u0628 \u0628\u0639\u0636\u0647\u0645 \u0639\u0646 \u0627\u0644\u062d\u0642\u060c \u0641\u064a\u0645\u064a\u0644\u0648\u0646 \u0625\u0644\u0649 \u0627\u0644\u062f\u0651\u064e\u0639\u0629 \u0648\u0627\u0644\u0633\u0643\u0648\u0646\u060c \u0644\u0643\u0646 \u0627\u0644\u0644\u0647 \u062b\u0628\u062a\u0647\u0645 \u0648\u0642\u0648\u0651\u064e\u0627\u0647\u0645 \u0648\u062a\u0627\u0628 \u0639\u0644\u064a\u0647\u0645\u060c \u0625\u0646\u0647 \u0628\u0647\u0645 \u0631\u0624\u0648\u0641 \u0631\u062d\u064a\u0645. \u0648\u0645\u0646 \u0631\u062d\u0645\u062a\u0647 \u0628\u0647\u0645 \u0623\u0646\u0652 \u0645\u064e\u0646\u0651\u064e \u0639\u0644\u064a\u0647\u0645 \u0628\u0627\u0644\u062a\u0648\u0628\u0629\u060c \u0648\u0642\u064e\u0628\u0650\u0644\u064e\u0647\u0627 \u0645\u0646\u0647\u0645\u060c \u0648\u062b\u0628\u0651\u064e\u062a\u0647\u0645 \u0639\u0644\u064a\u0647\u0627.","9:118":"\u0648\u0643\u0630\u0644\u0643 \u062a\u0627\u0628 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0627\u0644\u062b\u0644\u0627\u062b\u0629 \u0627\u0644\u0630\u064a\u0646 \u062e\u064f\u0644\u0651\u0650\u0641\u0648\u0627 \u0645\u0646 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 -\u0648\u0647\u0645 \u0643\u0639\u0628 \u0628\u0646 \u0645\u0627\u0644\u0643 \u0648\u0647\u0644\u0627\u0644 \u0628\u0646 \u0623\u064f\u0645\u064a\u0651\u064e\u0629 \u0648\u0645\u064f\u0631\u064e\u0627\u0631\u0629 \u0628\u0646 \u0627\u0644\u0631\u0628\u064a\u0639- \u062a\u062e\u0644\u0651\u064e\u0641\u0648\u0627 \u0639\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u062d\u0632\u0646\u0648\u0627 \u062d\u0632\u0646\u064b\u0627 \u0634\u062f\u064a\u062f\u064b\u0627\u060c \u062d\u062a\u0649 \u0625\u0630\u0627 \u0636\u0627\u0642\u062a \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0623\u0631\u0636 \u0628\u0633\u064e\u0639\u064e\u062a\u0647\u0627 \u063a\u0645\u0651\u064b\u0627 \u0648\u0646\u062f\u0645\u064b\u0627 \u0628\u0633\u0628\u0628 \u062a\u062e\u0644\u0641\u0647\u0645\u060c \u0648\u0636\u0627\u0642\u062a \u0639\u0644\u064a\u0647\u0645 \u0623\u0646\u0641\u0633\u0647\u0645 \u0644\u0650\u0645\u064e\u0627 \u0623\u0635\u0627\u0628\u0647\u0645 \u0645\u0646 \u0627\u0644\u0647\u0645\u060c \u0648\u0623\u064a\u0642\u0646\u0648\u0627 \u0623\u0646 \u0644\u0627 \u0645\u0644\u062c\u0623 \u0645\u0646 \u0627\u0644\u0644\u0647 \u0625\u0644\u0627 \u0625\u0644\u064a\u0647\u060c \u0648\u0641\u0651\u064e\u0642\u0647\u0645 \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649 \u0625\u0644\u0649 \u0627\u0644\u0637\u0627\u0639\u0629 \u0648\u0627\u0644\u0631\u062c\u0648\u0639 \u0625\u0644\u0649 \u0645\u0627 \u064a\u0631\u0636\u064a\u0647 \u0633\u0628\u062d\u0627\u0646\u0647. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0647\u0648 \u0627\u0644\u062a\u0648\u0627\u0628 \u0639\u0644\u0649 \u0639\u0628\u0627\u062f\u0647\u060c \u0627\u0644\u0631\u062d\u064a\u0645 \u0628\u0647\u0645.","9:119":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0627\u0645\u062a\u062b\u0644\u0648\u0627 \u0623\u0648\u0627\u0645\u0631 \u0627\u0644\u0644\u0647 \u0648\u0627\u062c\u062a\u0646\u0628\u0648\u0627 \u0646\u0648\u0627\u0647\u064a\u0647 \u0641\u064a \u0643\u0644 \u0645\u0627 \u062a\u0641\u0639\u0644\u0648\u0646 \u0648\u062a\u062a\u0631\u0643\u0648\u0646\u060c \u0648\u0643\u0648\u0646\u0648\u0627 \u0645\u0639 \u0627\u0644\u0635\u0627\u062f\u0642\u064a\u0646 \u0641\u064a \u0623\u064e\u064a\u0645\u0627\u0646\u0647\u0645 \u0648\u0639\u0647\u0648\u062f\u0647\u0645\u060c \u0648\u0641\u064a \u0643\u0644 \u0634\u0623\u0646 \u0645\u0646 \u0634\u0624\u0648\u0646\u0647\u0645.","9:120":"\u0645\u0627 \u0643\u0627\u0646 \u064a\u0646\u0628\u063a\u064a \u0644\u0623\u0647\u0644 \u0645\u062f\u064a\u0646\u0629 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0648\u0645\u064e\u0646 \u062d\u0648\u0644\u0647\u0645 \u0645\u0646 \u0633\u0643\u0627\u0646 \u0627\u0644\u0628\u0627\u062f\u064a\u0629 \u0623\u0646 \u064a\u062a\u062e\u0644\u0651\u064e\u0641\u0648\u0627 \u0641\u064a \u0623\u0647\u0644\u0647\u0645 \u0648\u062f\u0648\u0631\u0647\u0645 \u0639\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645\u060c \u0648\u0644\u0627 \u064a\u0631\u0636\u0648\u0627 \u0644\u0623\u0646\u0641\u0633\u0647\u0645 \u0628\u0627\u0644\u0631\u0627\u062d\u0629 \u0648\u0627\u0644\u0631\u0633\u0648\u0644 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0641\u064a \u062a\u0639\u0628 \u0648\u0645\u0634\u0642\u0629; \u0630\u0644\u0643 \u0628\u0623\u0646\u0647\u0645 \u0644\u0627 \u064a\u0635\u064a\u0628\u0647\u0645 \u0641\u064a \u0633\u0641\u0631\u0647\u0645 \u0648\u062c\u0647\u0627\u062f\u0647\u0645 \u0639\u0637\u0634 \u0648\u0644\u0627 \u062a\u0639\u0628 \u0648\u0644\u0627 \u0645\u062c\u0627\u0639\u0629 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u064a\u0637\u0624\u0648\u0646 \u0623\u0631\u0636\u064b\u0627 \u064a\u064f\u063a\u0636\u0650\u0628\u064f \u0627\u0644\u0643\u0641\u0627\u0631\u064e \u0648\u0637\u0624\u0647\u0645 \u0625\u064a\u0627\u0647\u0627\u060c \u0648\u0644\u0627 \u064a\u0635\u064a\u0628\u0648\u0646 \u0645\u0650\u0646 \u0639\u062f\u0648 \u0627\u0644\u0644\u0647 \u0648\u0639\u062f\u0648\u0647\u0645 \u0642\u062a\u0644\u0627 \u0623\u0648 \u0647\u0632\u064a\u0645\u0629\u064b \u0625\u0644\u0627 \u0643\u064f\u062a\u0650\u0628 \u0644\u0647\u0645 \u0628\u0630\u0644\u0643 \u0643\u0644\u0647 \u062b\u0648\u0627\u0628 \u0639\u0645\u0644 \u0635\u0627\u0644\u062d. \u0625\u0646 \u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u0636\u064a\u0639 \u0623\u062c\u0631 \u0627\u0644\u0645\u062d\u0633\u0646\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0623\u062d\u0633\u0646\u0648\u0627 \u0641\u064a \u0645\u0628\u0627\u062f\u0631\u062a\u0647\u0645 \u0625\u0644\u0649 \u0623\u0645\u0631 \u0627\u0644\u0644\u0647\u060c \u0648\u0642\u064a\u0627\u0645\u0647\u0645 \u0628\u0645\u0627 \u0639\u0644\u064a\u0647\u0645 \u0645\u0646 \u062d\u0642\u0647\u060c \u0648\u062d\u0642 \u062e\u0644\u0642\u0647.","9:121":"\u0648\u0644\u0627 \u064a\u0646\u0641\u0642\u0648\u0646 \u0646\u0641\u0642\u0629 \u0635\u063a\u064a\u0631\u0629 \u0648\u0644\u0627 \u0643\u0628\u064a\u0631\u0629 \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u064a\u0642\u0637\u0639\u0648\u0646 \u0648\u0627\u062f\u064a\u064b\u0627 \u0641\u064a \u0633\u064a\u0631\u0647\u0645 \u0645\u0639 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645 \u0641\u064a \u062c\u0647\u0627\u062f\u0647\u060c \u0625\u0644\u0627 \u0643\u064f\u062a\u0650\u0628 \u0644\u0647\u0645 \u0623\u062c\u0631 \u0639\u0645\u0644\u0647\u0645; \u0644\u064a\u062c\u0632\u064a\u0647\u0645 \u0627\u0644\u0644\u0647 \u0623\u062d\u0633\u0646 \u0645\u0627 \u064a\u064f\u062c\u0652\u0632\u064e\u0648\u0646 \u0628\u0647 \u0639\u0644\u0649 \u0623\u0639\u0645\u0627\u0644\u0647\u0645 \u0627\u0644\u0635\u0627\u0644\u062d\u0629.","9:122":"\u0648\u0645\u0627 \u0643\u0627\u0646 \u064a\u0646\u0628\u063a\u064a \u0644\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0623\u0646 \u064a\u062e\u0631\u062c\u0648\u0627 \u062c\u0645\u064a\u0639\u064b\u0627 \u0644\u0642\u062a\u0627\u0644 \u0639\u062f\u0648\u0651\u0650\u0647\u0645\u060c \u0643\u0645\u0627 \u0644\u0627 \u064a\u0633\u062a\u0642\u064a\u0645 \u0644\u0647\u0645 \u0623\u0646 \u064a\u0642\u0639\u062f\u0648\u0627 \u062c\u0645\u064a\u0639\u064b\u0627\u060c \u0641\u0647\u0644\u0627 \u062e\u0631\u062c \u0645\u0646 \u0643\u0644 \u0641\u0631\u0642\u0629 \u062c\u0645\u0627\u0639\u0629 \u062a\u062d\u0635\u0644 \u0628\u0647\u0645 \u0627\u0644\u0643\u0641\u0627\u064a\u0629 \u0648\u0627\u0644\u0645\u0642\u0635\u0648\u062f; \u0648\u0630\u0644\u0643 \u0644\u064a\u062a\u0641\u0642\u0647 \u0627\u0644\u0642\u0627\u0639\u062f\u0648\u0646 \u0639\u0646 \u0627\u0644\u0642\u062a\u0627\u0644 \u0641\u064a\u0639\u0644\u0645\u0648\u0627 \u0645\u0627 \u062a\u062c\u062f\u062f \u0645\u0646 \u0627\u0644\u0623\u062d\u0643\u0627\u0645 \u0641\u064a \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u0648\u0645\u0627 \u0623\u0646\u0632\u0644 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644\u0647\u060c \u0648\u064a\u0646\u0630\u0631\u0648\u0627 \u0642\u0648\u0645\u0647\u0645 \u0628\u0645\u0627 \u062a\u0639\u0644\u0645\u0648\u0647 \u0639\u0646\u062f \u0631\u062c\u0648\u0639\u0647\u0645 \u0625\u0644\u064a\u0647\u0645\u060c \u0644\u0639\u0644\u0647\u0645 \u064a\u062d\u0630\u0631\u0648\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0644\u0647 \u0628\u0627\u0645\u062a\u062b\u0627\u0644 \u0623\u0648\u0627\u0645\u0631\u0647 \u0648\u0627\u062c\u062a\u0646\u0627\u0628 \u0646\u0648\u0627\u0647\u064a\u0647.","9:123":"\u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0630\u064a\u0646 \u0635\u062f\u0651\u064e\u0642\u0648\u0627 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0648\u0639\u0645\u0644\u0648\u0627 \u0628\u0634\u0631\u0639\u0647\u060c \u0627\u0628\u062f\u0624\u0648\u0627 \u0628\u0642\u062a\u0627\u0644 \u0627\u0644\u0623\u0642\u0631\u0628 \u0641\u0627\u0644\u0623\u0642\u0631\u0628 \u0625\u0644\u0649 \u062f\u0627\u0631 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0645\u0646 \u0627\u0644\u0643\u0641\u0627\u0631\u060c \u0648\u0644\u064a\u062c\u062f \u0627\u0644\u0643\u0641\u0627\u0631 \u0641\u064a\u0643\u0645 \u063a\u0650\u0644\u0652\u0638\u0629 \u0648\u0634\u062f\u0629\u060c \u0648\u0627\u0639\u0644\u0645\u0648\u0627 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0645\u0639 \u0627\u0644\u0645\u062a\u0642\u064a\u0646 \u0628\u062a\u0623\u064a\u064a\u062f\u0647 \u0648\u0646\u0635\u0631\u0647.","9:124":"\u0648\u0625\u0630\u0627 \u0645\u0627 \u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u0633\u0648\u0631\u0629 \u0645\u0646 \u0633\u0648\u0631 \u0627\u0644\u0642\u0631\u0622\u0646 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644\u0647\u060c \u0641\u0645\u0650\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0645\u0646 \u064a\u0642\u0648\u0644: -\u0625\u0646\u0643\u0627\u0631\u064b\u0627 \u0648\u0627\u0633\u062a\u0647\u0632\u0627\u0621\u064b- \u0623\u064a\u0651\u064f\u0643\u0645 \u0632\u0627\u062f\u062a\u0647 \u0647\u0630\u0647 \u0627\u0644\u0633\u0648\u0631\u0629 \u062a\u0635\u062f\u064a\u0642\u064b\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0622\u064a\u0627\u062a\u0647\u061f \u0641\u0623\u0645\u0627 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647 \u0641\u0632\u0627\u062f\u0647\u0645 \u0646\u0632\u0648\u0644 \u0627\u0644\u0633\u0648\u0631\u0629 \u0625\u064a\u0645\u0627\u0646\u064b\u0627 \u0628\u0627\u0644\u0639\u0644\u0645 \u0628\u0647\u0627 \u0648\u062a\u062f\u0628\u0631\u0647\u0627 \u0648\u0627\u0639\u062a\u0642\u0627\u062f\u0647\u0627 \u0648\u0627\u0644\u0639\u0645\u0644 \u0628\u0647\u0627\u060c \u0648\u0647\u0645 \u064a\u0641\u0631\u062d\u0648\u0646 \u0628\u0645\u0627 \u0623\u0639\u0637\u0627\u0647\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u064a\u0642\u064a\u0646.","9:125":"\u0648\u0623\u0645\u0627 \u0627\u0644\u0630\u064a\u0646 \u0641\u064a \u0642\u0644\u0648\u0628\u0647\u0645 \u0646\u0641\u0627\u0642 \u0648\u0634\u0643 \u0641\u064a \u062f\u064a\u0646 \u0627\u0644\u0644\u0647\u060c \u0641\u0625\u0646 \u0646\u0632\u0648\u0644 \u0627\u0644\u0633\u0648\u0631\u0629 \u064a\u0632\u064a\u062f\u0647\u0645 \u0646\u0641\u0627\u0642\u064b\u0627 \u0648\u0634\u0643\u064b\u0627 \u0625\u0644\u0649 \u0645\u0627 \u0647\u0645 \u0639\u0644\u064a\u0647 \u0645\u0646 \u0642\u0628\u0644\u064f \u0645\u0646 \u0627\u0644\u0646\u0641\u0627\u0642 \u0648\u0627\u0644\u0634\u0643\u060c \u0648\u0647\u0644\u0643 \u0647\u0624\u0644\u0627\u0621 \u0648\u0647\u0645 \u062c\u0627\u062d\u062f\u0648\u0646 \u0628\u0627\u0644\u0644\u0647 \u0648\u0622\u064a\u0627\u062a\u0647.","9:126":"\u0623\u0648 \u0644\u0627 \u064a\u0631\u0649 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0623\u0646 \u0627\u0644\u0644\u0647 \u064a\u0628\u062a\u0644\u064a\u0647\u0645 \u0628\u0627\u0644\u0642\u062d\u0637 \u0648\u0627\u0644\u0634\u062f\u0629\u060c \u0648\u0628\u0625\u0638\u0647\u0627\u0631 \u0645\u0627 \u064a\u0628\u0637\u0646\u0648\u0646 \u0645\u0646 \u0627\u0644\u0646\u0641\u0627\u0642 \u0645\u0631\u0629 \u0623\u0648 \u0645\u0631\u062a\u064a\u0646 \u0641\u064a \u0643\u0644 \u0639\u0627\u0645\u061f \u062b\u0645 \u0647\u0645 \u0645\u0639 \u0630\u0644\u0643 \u0644\u0627 \u064a\u062a\u0648\u0628\u0648\u0646 \u0645\u0650\u0646 \u0643\u0641\u0631\u0647\u0645 \u0648\u0646\u0641\u0627\u0642\u0647\u0645\u060c \u0648\u0644\u0627 \u0647\u0645 \u064a\u062a\u0639\u0638\u0648\u0646 \u0648\u0644\u0627 \u064a\u062a\u0630\u0643\u0631\u0648\u0646 \u0628\u0645\u0627 \u064a\u0639\u0627\u064a\u0646\u0648\u0646 \u0645\u0646 \u0622\u064a\u0627\u062a \u0627\u0644\u0644\u0647.","9:127":"\u0648\u0625\u0630\u0627 \u0645\u0627 \u0623\u064f\u0646\u0632\u0644\u062a \u0633\u0648\u0631\u0629 \u062a\u063a\u064e\u0627\u0645\u064e\u0632\u064e \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0628\u0627\u0644\u0639\u064a\u0648\u0646 \u0625\u0646\u0643\u0627\u0631\u064b\u0627 \u0644\u0646\u0632\u0648\u0644\u0647\u0627 \u0648\u0633\u062e\u0631\u064a\u0629 \u0648\u063a\u064a\u0638\u064b\u0627; \u0644\u0650\u0645\u064e\u0627 \u0646\u0632\u0644 \u0641\u064a\u0647\u0627 \u0645\u0650\u0646 \u0630\u0650\u0643\u0652\u0631 \u0639\u064a\u0648\u0628\u0647\u0645 \u0648\u0623\u0641\u0639\u0627\u0644\u0647\u0645\u060c \u062b\u0645 \u064a\u0642\u0648\u0644\u0648\u0646: \u0647\u0644 \u064a\u0631\u0627\u0643\u0645 \u0645\u0646 \u0623\u062d\u062f \u0625\u0646 \u0642\u0645\u062a\u0645 \u0645\u0646 \u0639\u0646\u062f \u0627\u0644\u0631\u0633\u0648\u0644\u061f \u0641\u0625\u0646 \u0644\u0645 \u064a\u0631\u0647\u0645 \u0623\u062d\u062f \u0642\u0627\u0645\u0648\u0627 \u0648\u0627\u0646\u0635\u0631\u0641\u0648\u0627 \u0645\u0646 \u0639\u0646\u062f\u0647 \u0639\u0644\u064a\u0647 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0627\u0644\u0633\u0644\u0627\u0645 \u0645\u062e\u0627\u0641\u0629 \u0627\u0644\u0641\u0636\u064a\u062d\u0629. \u0635\u0631\u0641 \u0627\u0644\u0644\u0647 \u0642\u0644\u0648\u0628\u0647\u0645 \u0639\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646; \u0628\u0633\u0628\u0628 \u0623\u0646\u0647\u0645 \u0644\u0627 \u064a\u0641\u0647\u0645\u0648\u0646 \u0648\u0644\u0627 \u064a\u062a\u062f\u0628\u0631\u0648\u0646.","9:128":"\u0644\u0642\u062f \u062c\u0627\u0621\u0643\u0645 \u0623\u064a\u0647\u0627 \u0627\u0644\u0645\u0624\u0645\u0646\u0648\u0646 \u0631\u0633\u0648\u0644 \u0645\u0646 \u0642\u0648\u0645\u0643\u0645\u060c \u064a\u0634\u0642 \u0639\u0644\u064a\u0647 \u0645\u0627 \u062a\u0644\u0642\u0648\u0646 \u0645\u0646 \u0627\u0644\u0645\u0643\u0631\u0648\u0647 \u0648\u0627\u0644\u0639\u0646\u062a\u060c \u062d\u0631\u064a\u0635 \u0639\u0644\u0649 \u0625\u064a\u0645\u0627\u0646\u0643\u0645 \u0648\u0635\u0644\u0627\u062d \u0634\u0623\u0646\u0643\u0645\u060c \u0648\u0647\u0648 \u0628\u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0643\u062b\u064a\u0631 \u0627\u0644\u0631\u0623\u0641\u0629 \u0648\u0627\u0644\u0631\u062d\u0645\u0629.","9:129":"\u0641\u0625\u0646 \u0623\u0639\u0631\u0636 \u0627\u0644\u0645\u0634\u0631\u0643\u0648\u0646 \u0648\u0627\u0644\u0645\u0646\u0627\u0641\u0642\u0648\u0646 \u0639\u0646 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0643 -\u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u0633\u0648\u0644- \u0641\u0642\u0644 \u0644\u0647\u0645: \u062d\u0633\u0628\u064a \u0627\u0644\u0644\u0647\u060c \u064a\u0643\u0641\u064a\u0646\u064a \u062c\u0645\u064a\u0639 \u0645\u0627 \u0623\u0647\u0645\u0651\u064e\u0646\u064a\u060c \u0644\u0627 \u0645\u0639\u0628\u0648\u062f \u0628\u062d\u0642 \u0625\u0644\u0627 \u0647\u0648\u060c \u0639\u0644\u064a\u0647 \u0627\u0639\u062a\u0645\u062f\u062a\u060c \u0648\u0625\u0644\u064a\u0647 \u0641\u064e\u0648\u0651\u064e\u0636\u0652\u062a\u064f \u062c\u0645\u064a\u0639 \u0623\u0645\u0648\u0631\u064a; \u0641\u0625\u0646\u0647 \u0646\u0627\u0635\u0631\u064a \u0648\u0645\u0639\u064a\u0646\u064a\u060c \u0648\u0647\u0648 \u0631\u0628 \u0627\u0644\u0639\u0631\u0634 \u0627\u0644\u0639\u0638\u064a\u0645\u060c \u0627\u0644\u0630\u064a \u0647\u0648 \u0623\u0639\u0638\u0645 \u0627\u0644\u0645\u062e\u0644\u0648\u0642\u0627\u062a."}},1151,[]);